INSERT INTO `ai_model_config` VALUES (2090378093471383554, 'DeepSeek_siliconflow', 'CUSTOM', 'https://api.siliconflow.cn/v1', 'zZylG5oyEK0gWdoB0FdK6iQJf5sBWaRkHUK0XPj6uUhfK/wxLPhKvBZJJlegFdXSqdauzUlTyzXR6xZdTPo5OHV3InyPjsFrSlhpGs1kSQ==', 'deepseek-ai/DeepSeek-V4-Pro', 30, '{\"max_tokens\": 2048, \"temperature\": 0.7}', 1, 1, '2026-08-20 17:59:09', '2026-08-21 15:36:59');
INSERT INTO `ai_prompt_template` VALUES (4001, '食材解析模板', 'INGREDIENT_RECOMMEND', '你是食谱系统的食材解析助手。用户会描述家里现有的食材，你需要把它们解析成结构化列表。\n可选食材库标准名称如下(只能从中选择，不要编造)：\n{ingredientList}\n\n用户输入：{userInput}\n\n请只输出 JSON，格式为：{\"ingredients\":[\"标准名称1\",\"标准名称2\"]}\n如果用户提到的食材在库中不存在，请忽略该食材。', 2090378093471383554, '2026-08-20 15:16:35', '2026-08-21 15:43:58');
INSERT INTO `ai_prompt_template` VALUES (4002, '筛选条件解析模板', 'CONDITION_FILTER', '你是食谱系统的查询条件解析助手。用户会用自然语言描述想吃什么，你需要解析成结构化筛选条件。\n可用标签：{tagList}\n\n用户输入：{userInput}\n\n请只输出 JSON，格式为：{\"minCalorie\":null,\"maxCalorie\":null,\"tagName\":null,\"maxCookTime\":null,\"maxDifficulty\":null}\n未提及的条件填 null，卡路里单位为大卡(整道菜)。', 2090378093471383554, '2026-08-20 15:16:35', '2026-08-21 15:43:54');
INSERT INTO `ai_prompt_template` VALUES (4003, '兜底生成模板', 'FALLBACK_GENERATE', '你是专业厨师。请根据用户需求设计一道菜谱。\n严格约束：食材只能从下面的食材库中选择，禁止使用库中不存在的食材。\n食材库：{ingredientList}\n\n用户需求：{userInput}\n\n请只输出 JSON，格式为：\n{\"name\":\"菜名\",\"summary\":\"简介\",\"difficulty\":3,\"cookTime\":30,\"baseServings\":2,\"ingredients\":[{\"name\":\"标准食材名\",\"amount\":100,\"unit\":\"克\",\"isOptional\":false,\"remark\":\"\"}],\"steps\":[\"步骤1\",\"步骤2\"],\"tips\":[\"提示1\"]}\n单位只能使用\"克\"\"毫升\"或该食材已配置的单位。', 2090378093471383554, '2026-08-20 15:16:35', '2026-08-21 15:43:48');
