INSERT INTO `recipe` VALUES (300001, 'B52轰炸机', '/upload/recipe-cover/import/placeholder.png', '这款鸡尾酒口感层次分明，入口先是伏特加的烈，紧接着是咖啡奶油的回甘，点燃后饮用有独特的冰火体验，属于经典创意鸡尾酒。咖啡酒与百利甜酒提供了少量咖啡因和奶脂，但整体营养以酒精为主。制作需要练习分层倒酒和点火技巧，对新手稍有难度，整个过程大约只需 5 分钟。', 3, 80.00, 5, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300002, 'Mojito莫吉托', '/upload/recipe-cover/import/placeholder.png', '这款鸡尾酒口感清爽酸甜，带有薄荷的清凉和朗姆酒的微醺，是经典的夏季饮品。酒精含量较低，佐以富含维生素 C 的青柠，能生津解渴、提神醒脑。制作十分简单，对新手友好，从备料到完成只需大约十 分钟。', 3, 187.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300003, 'Q 弹虾滑馄饨', '/upload/recipe-cover/import/placeholder.png', 'Q 弹虾滑馄饨，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300004, '三色虾仁', '/upload/recipe-cover/import/r300004.jpg', '三色虾仁，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300005, '上汤娃娃菜', '/upload/recipe-cover/import/r300005.png', '这道上汤娃娃菜清甜鲜美，口感软嫩，属于家常素菜，尤其适合减肥期间食用。娃娃菜富含维生素和膳食纤维，低脂低热量，搭配皮蛋和午餐肉增添风味又不会过多增加负担。制作难度适中，新手也能尝试，从备菜到出锅大约只需 20 分钟。', 3, 158.00, 20, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300006, '中式馅饼', '/upload/recipe-cover/import/placeholder.png', '这道饼外皮微脆内里松软，馅料咸香，属于家常面食。富含碳水化合物和蛋白质，搭配胡萝卜和鸡蛋更添营养。制作难度中等，新手需掌握火候，但步骤明确易上手。从备料到完成大约需要 1 小时。', 4, 1265.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300007, '乡村啤酒鸭', '/upload/recipe-cover/import/placeholder.png', '鸭肉与啤酒同炖，汤汁浓郁，肉质鲜香软烂，还带有一股淡淡的啤酒清香，是一道风味独特的家常菜。鸭肉本身滋补，富含蛋白质、B 族维生素和多种矿物质，搭配啤酒炖煮后更易入味。这道菜步骤虽稍多，但操作并不复杂，一般初学者只需 大约 1 小时即可完成。', 4, 1324.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300008, '乾隆白菜', '/upload/recipe-cover/import/r300008.jpg', '乾隆白菜是一道经典的北京风味凉菜，以手撕白菜心拌上浓稠芝麻酱汁，口感酸甜爽脆、醇厚开胃。白菜富含维生素和膳食纤维，芝麻酱则带来优质脂肪与钙质，清爽解腻又营养。全程不炒不煮，调酱拌匀即可，对新手十分友好，一般仅需 10 分钟便能端上餐桌。', 2, 150.00, 10, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300009, '五彩鸡丝拌面', '/upload/recipe-cover/import/placeholder.png', '五彩鸡丝拌面，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300010, '什锦蛋炒饭', '/upload/recipe-cover/import/r300010.png', '什锦蛋炒饭，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300011, '傲椒风味翅尖', '/upload/recipe-cover/import/r300011.png', '傲椒风味翅尖，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1105, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300012, '冒烤鸭', '/upload/recipe-cover/import/r300012.png', '冒烤鸭，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1106, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300013, '农家一碗香', '/upload/recipe-cover/import/r300013.jpg', '这是一道咸香下饭的湖南家常小炒，五花肉的油润、鸡蛋的嫩滑与青椒的清香彼此融合，口感层次丰富。猪肉与鸡蛋提供优质蛋白质，搭配青椒补充维生素 C，营养均衡。中等难度，需要注意煸炒火候和调味顺序，新手稍加练习也能做好。预计备菜 7 分钟，烹饪 10 分钟，总共约 17 分钟就能出锅。', 3, 1638.00, 7, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300014, '农家小炒肉（玉耳版本）', '/upload/recipe-cover/import/r300014.png', '农家小炒肉（玉耳版本），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300015, '农家小炒肉（鸡蛋干版本）', '/upload/recipe-cover/import/placeholder.png', '农家小炒肉（鸡蛋干版本），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300016, '农家蒸蛋', '/upload/recipe-cover/import/r300016.jpg', '农家蒸蛋，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300017, '冬瓜茶', '/upload/recipe-cover/import/placeholder.png', '冬瓜茶是一款清爽解暑的传统饮品，口感甘甜柔和，带有冬瓜特有的清香，冰镇后风味更佳。冬瓜本身低热量、富含水分，搭配冰糖熬制，能补充能量、生津止渴。制作不复杂，但对新手而言需要一些耐心，全程大约需要 4 到 5 小时。', 2, 296.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300018, '冬瓜酿肉', '/upload/recipe-cover/import/r300018.jpg', '冬瓜酿肉是一道荤素搭配的家常蒸菜，口感鲜嫩爽滑，肉馅的咸香与冬瓜的清甜相互融合，清爽不腻。猪肉末提供优质蛋白质和必需氨基酸，冬瓜则有助于清热利尿、补充水分。做法简单，即使是新手也能轻松上手，只需稍加练习卷肉技巧即可。从备料到出锅，大约需要 30 分钟。', 4, 578.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300019, '冰粉', '/upload/recipe-cover/import/placeholder.png', '石凉粉是河南信阳的传统小吃，口感爽滑如果冻，配以薄荷汁或柠檬汁清凉解暑，属于豫菜系。由冰粉籽手工揉搓而成，天然无添加，含有丰富的植物胶质。制作非常简单，对新手友好，全程约需 3 小时，其中 2.5 小时为静置凝固时间，几乎不占用人工。', 2, 110.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300020, '冷吃兔', '/upload/recipe-cover/import/placeholder.png', '这是一道经典的四川自贡盐帮菜，麻辣干香，兔肉紧实有嚼劲，入口先辣后鲜，回味悠长。兔肉高蛋白低脂肪，富含卵磷脂和多种氨基酸，营养丰富且易于消化。制作过程需处理多种香料并严格控制火候，对新手有一定挑战。从备料到炒制完成约需 1.5 小时，但放置一夜后风味更佳，值得提前准备。', 4, 590.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300021, '凉拌木耳', '/upload/recipe-cover/import/r300021.jpg', '凉拌木耳，由于发放物资中有很多干货，木耳是较为健康的食物。且凉拌木耳的烹饪方式也相对简单。', 2, 129.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300022, '凉拌油麦菜', '/upload/recipe-cover/import/placeholder.png', '一道清爽解腻的家常凉菜，芝麻酱的醇厚包裹着油麦菜的脆嫩，酸甜咸香交织，非常开胃。油麦菜富含维生素和膳食纤维，芝麻酱则补充钙与健康脂肪，营养均衡。做法毫无难度，切一切、拌一拌就行，从准备到上桌只需十几分钟，特别适合新手和忙碌时快速成菜。', 1, 191.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300023, '凉拌莴笋', '/upload/recipe-cover/import/r300023.jpeg', '一道清脆爽口的家常凉拌小菜，莴笋经过腌制后格外脆嫩，带着微微辣意，十分开胃。富含维生素与膳食纤维，热量不高。做法简单，对新手很友好，从备料到上桌大约二十分钟，冰镇后风味更佳。', 2, 295.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300024, '凉拌莴笋丝', '/upload/recipe-cover/import/r300024.jpg', '凉拌莴笋丝，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1006, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300025, '凉拌豆腐', '/upload/recipe-cover/import/placeholder.png', '这道凉菜清爽可口，富含植物蛋白和钙质，低脂健康，制作简单快捷，一般初学者只需要 10 分钟即可完成。', 2, 343.00, 10, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300026, '凉拌金针菇', '/upload/recipe-cover/import/placeholder.png', '凉拌金针菇是一道简单快捷的家常开胃凉菜，口感脆嫩爽滑，咸鲜微酸。金针菇富含膳食纤维和多种维生素，热量较低。制作全程只需焯烫和调味，对新手非常友好，忙碌时也能快速准备。从备菜到完成大约只需 10 分钟。', 2, 163.00, 10, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300027, '凉拌鸡丝', '/upload/recipe-cover/import/r300027.jpg', '一道少油低卡的家常凉菜，鸡丝嫩滑入味，麻油与香醋调和出微麻微酸的清爽口感，适合夏日解腻。鸡胸肉富含优质蛋白且脂肪含量低。做法简单，新手也能轻松上手，从备料到完成大约只需 30 分钟。', 3, 293.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300028, '凉拌黄瓜', '/upload/recipe-cover/import/placeholder.png', '这是一道清爽开胃的家常凉菜，口感脆嫩，酸香适口。黄瓜富含水分和维生素，有助于清热解暑、美容养颜。做法非常简单，对新手友好，只需拍碎、调味、腌制 15 分钟，全程约 20 分钟即可完成。', 1, 107.00, 15, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300029, '凉皮', '/upload/recipe-cover/import/placeholder.png', '凉皮是一道源自陕西的家常小吃，口感筋道爽滑，酸辣开胃，带有浓郁的芝麻酱香。芝麻酱和面筋提供了丰富的植物蛋白与钙质，搭配清脆的黄瓜和绿豆芽，富含维生素和膳食纤维。整体操作难度中等，只需简单煮烫、切丝和调汁，一般初学者也能从容完成。从备料到上桌大约需要 40 分钟，非常适合夏日餐桌。', 3, 761.00, 40, 1, 1107, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300030, '凉粉', '/upload/recipe-cover/import/r300030.jpg', '凉粉是一道源自四川的传统小吃，口感冰凉爽滑，酸辣开胃，很适合夏天消暑。主要原料是豌豆淀粉，富含碳水化合物，能为身体快速补充能量。制作过程不算复杂，但需要耐心搅煮和长时间冷藏定型，对新手来说难度适中。从煮制到完成大约需要 3-4 小时，其中大部分是等待冷藏的时间，动手操作只需大约半 小时。', 3, 539.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300031, '凤爪蒸豆米', '/upload/recipe-cover/import/r300031.png', '凤爪蒸豆米，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300032, '利提巧卡', '/upload/recipe-cover/import/placeholder.png', '利提巧卡是印度比哈尔邦的传统主食，由烤得金黄的麦球和烟熏风味的蔬菜泥组成，口感外脆内软，香气浓郁。烤鹰嘴豆粉馅料富含植物蛋白和膳食纤维，搭配茄子、番茄、土豆等蔬菜，营养丰富。制作需要和面、包馅、烤制以及处理蔬菜，步骤较多，对新手有一定挑战，全程大约需要 60 分钟完成。', 5, 1019.00, 60, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300033, '剁椒木耳炒鸡蛋', '/upload/recipe-cover/import/r300033.jpg', '剁椒木耳炒鸡蛋，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300034, '剁椒鱼头', '/upload/recipe-cover/import/r300034.png', '剁椒鱼头，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300035, '剁椒鱼头（白鲢鱼头版）', '/upload/recipe-cover/import/r300035.png', '剁椒鱼头（白鲢鱼头版），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300036, '剁椒鱼头（草鱼头版）', '/upload/recipe-cover/import/r300036.png', '剁椒鱼头（草鱼头版），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300037, '勾芡香菇汤', '/upload/recipe-cover/import/r300037.jpeg', '香菇勾芡汤汤浓味鲜，滑润适口，是一道快手的家常汤品。香菇含有丰富的氨基酸和多糖，有助于增强免疫力。制作过程需要一些基本的控火和勾芡技巧，但对新手依然友好。从备料到出锅，大约只需 25 分钟。', 3, 146.00, 25, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300038, '包子', '/upload/recipe-cover/import/r300038.png', '包子，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300039, '包菜炒鸡蛋', '/upload/recipe-cover/import/placeholder.png', '包菜炒鸡蛋，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300040, '包菜炒鸡蛋粉丝', '/upload/recipe-cover/import/r300040.jpg', '包菜炒鸡蛋粉丝是一道咸鲜可口的家常快手菜，脆甜的包菜丝与软韧的粉丝、嫩滑的鸡蛋相互融合，口感层次丰富。包菜富含维生素和膳食纤维，鸡蛋提供优质蛋白质，胡萝卜增添营养，荤素搭配均衡。制作时需要提前浸泡粉丝，整体流程稍多但操作并不复杂，对新手有一定挑战性。从备料到出锅，大约需要 1 小时 20 分钟。', 3, 570.00, 20, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300041, '半成品意面', '/upload/recipe-cover/import/placeholder.png', '这是一道利用市售半成品快速完成的西式简餐，面条弹韧有嚼劲，搭配现成酱料风味浓郁。以碳水化合物为主，能迅速补充能量，并含有蛋白质。制作难度极低，新手也能零失误，从开火到装盘仅需约 2 分钟。', 1, 578.00, 2, 1, 1107, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300042, '南派红烧肉', '/upload/recipe-cover/import/placeholder.png', '这道红烧肉成菜色泽红亮，肥肉入口即化、瘦肉酥烂不柴，咸中带甜，是典型的南方甜口风味。五花肉提供优质蛋白和丰富的胶原蛋白，香辛料还能去腥暖胃。制作虽需熬糖色与慢炖，但每一步都拆解得清晰易懂，新手跟着操作也能成功，全程约 1.5 小时即可端上桌。', 4, 3248.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300043, '卤大排', '/upload/recipe-cover/import/r300043.png', '卤大排，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1108, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300044, '卤方干', '/upload/recipe-cover/import/r300044.png', '卤方干，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1108, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300045, '卤翅根', '/upload/recipe-cover/import/r300045.png', '卤翅根，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1108, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300046, '卤肉肠', '/upload/recipe-cover/import/placeholder.png', '卤肉肠，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1108, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300047, '卤菜', '/upload/recipe-cover/import/r300047.jpeg', '这是一道经典中式卤味，肉质鲜嫩入味，香气浓郁，卤汁可反复使用、越陈越香，适合做凉菜、下酒或搭配主食。菜品富含优质蛋白和多种维生素，营养均衡。制作需要一点耐心，但步骤清晰，对新手比较友好。提前浸泡去血水、熬糖色和高压卤制约需 1 小时，再浸泡过夜让风味充分渗入，第二天取出切片即可享用。', 3, 467.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300048, '卤鸡爪', '/upload/recipe-cover/import/r300048.png', '卤鸡爪，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1108, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300049, '卤鸡腿', '/upload/recipe-cover/import/r300049.png', '卤鸡腿，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1108, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300050, '印度土豆花菜', '/upload/recipe-cover/import/placeholder.png', '这道印度家常素菜以干香金黄、香料浓郁为特点，土豆绵软、花菜略带焦边，属于北印度风味。土豆和花菜富含膳食纤维与维生素 C，营养均衡。做法简单，对新手友好，从准备到出锅约需 25 分钟。', 3, 668.00, 25, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300051, '印度奶茶', '/upload/recipe-cover/import/placeholder.png', '印度奶茶是一道充满异域风情的家常饮品，以红茶、牛奶和多种香料现煮而成，口感浓郁顺滑，带有生姜、豆蔻、肉桂交织的辛香暖意。牛奶提供优质蛋白和钙质，香料则有助于暖身驱寒、促进消化。制作过程简单直观，对新手友好，从备料到入口只需大约 10 分钟。', 2, 135.00, 10, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300052, '印度烤饼', '/upload/recipe-cover/import/placeholder.png', '这是一道印度风味的发酵烤饼，外表微焦酥脆，内部松软有嚼劲，是咖喱的绝佳搭档。富含碳水化合物和蛋白质，酸奶的加入也让面饼更易消化。制作稍有难度，需注意面团软硬和火候，但平底锅即可操作，提前 1 小时发酵，总耗时约 1.5 小时。', 3, 559.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300053, '印度焖饭', '/upload/recipe-cover/import/placeholder.png', '印度焖饭是源自莫卧儿帝国时期的皇家料理，米粒细长、香料气息浓郁，鸡肉嫩滑、米饭粒粒分明，层次丰富。富含蛋白质和多种香料精华，能提振食欲。制作步骤较繁琐，对新手不太友好，全程约需 90 分钟（鸡肉需提前腌制 1 小时）。', 5, 730.00, 90, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300054, '印度葫芦丸子', '/upload/recipe-cover/import/placeholder.png', '这道北印度素菜将葫芦擦丝与鹰嘴豆粉团成丸子，油炸后浸入番茄洋葱咖喱，外酥内软、酱汁浓郁香辛。瓠瓜清润、鹰嘴豆粉提供植物蛋白与膳食纤维，是一道饱腹又均衡的素食。制作涉及油炸和熬酱，步骤稍多但按序操作不难掌握，全程大约需要 40 分钟。', 4, 571.00, 40, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300055, '原味豆浆', '/upload/recipe-cover/import/r300055.png', '原味豆浆，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300056, '原味豆浆（冲调版本）', '/upload/recipe-cover/import/placeholder.png', '原味豆浆（冲调版本），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300057, '原味豆浆（现磨版本）', '/upload/recipe-cover/import/placeholder.png', '原味豆浆（现磨版本），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300058, '反沙芋头', '/upload/recipe-cover/import/r300058.jpg', '反沙芋头是一道外酥里糯、甜香可口的潮汕传统小吃，常作下午茶点。荔浦芋头富含膳食纤维、钾和多种维生素，能提供持久饱腹感。制作不难但需要掌握熬糖火候，适合稍有基础的初学者尝试，全程大约 20 分钟即可完成。', 3, 397.00, 20, 1, 1109, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300059, '口水鸡', '/upload/recipe-cover/import/r300059.jpg', '口水鸡是一道经典的四川凉菜，红油包裹的鸡肉冰爽 Q 弹、麻辣鲜香，夏季食用开胃解腻。鸡肉富含优质蛋白，搭配花生碎和香料，提供能量与风味。制作难度中等，需注意煮鸡火候和红油调味，适合有一定下厨经验的烹饪者。从备料、煮鸡、冷却到淋汁完成，预计耗时约 1.5 小时。', 3, 1392.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300060, '可乐桶', '/upload/recipe-cover/import/placeholder.png', '可乐桶是一款简单易调的休闲鸡尾酒，口感清爽甜润，可乐的气泡和柠檬汁很好地中和了威士忌的烈感，适合聚会场合。主要提供能量，柠檬补充维生素 C。整个调配过程只需 5 分钟即可完成，新手也能轻松上手。', 2, 450.00, 5, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300061, '可乐炒饭', '/upload/recipe-cover/import/placeholder.png', '这道菜以可乐替代糖调味，带来独特的焦香微甜风味，酱汁浓郁包裹粒粒米饭，属于创意家常炒饭。鸡蛋和火腿肠提供优质蛋白质与能量，搭配主食米饭，营养均衡管饱。操作步骤直观，适合新手尝试，一般 大约 20 分钟便可端上桌。', 3, 913.00, 20, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300062, '可乐鸡翅', '/upload/recipe-cover/import/placeholder.png', '可乐鸡翅色泽红亮、口感嫩滑，味道咸甜适口，是一道流行于家庭餐桌的创意菜肴。鸡翅富含优质蛋白质与脂肪，搭配可乐烹煮后肉质更为软烂。制作过程需要掌握煎制与收汁的火候，对新手有一定挑战，但跟随步骤仍可成功。从备料到完成大约耗时 40 分钟。', 3, 960.00, 40, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300063, '台式卤肉饭', '/upload/recipe-cover/import/r300063.jpg', '台式卤肉饭是一道浓香四溢的台湾家常料理，肉条软糯入味，酱汁琥珀般油亮，浇在热米饭上满口脂香。富含优质蛋白、胶原蛋白和碳水，能快速补充能量。做法对新手非常友好，只需备好食材、掌握火候，全程约 1.5 小时即可完成，其中动手操作仅需半小时，剩下的交给小火慢炖。', 3, 1495.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300064, '吐司果酱', '/upload/recipe-cover/import/placeholder.png', '这是一道极简快手早餐，烤至微脆的吐司夹入甜香果酱，外脆内软，方便随身携带，属于典型的便捷西式简餐。主要提供碳水化合物和糖分，能快速补充晨间能量。操作几乎零门槛，非常适合不擅烹饪的忙碌新手。从准备到完成只需大约 2 分钟，无需开火，也几乎不用清洗厨具。', 1, 223.00, 2, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300065, '咕噜肉', '/upload/recipe-cover/import/placeholder.png', '咕噜肉是一道经典粤式家常菜，酸甜开胃、外酥里嫩，菠萝的果香让肉块吃起来格外清爽解腻。猪肉提供优质蛋白质，青椒和菠萝则补充维生素与膳食纤维。这道菜的难点在于掌握炸肉的火候，对新手略有挑战，但只要按步骤操作便能成功。从腌制到出锅，全程大约需要 40 分钟，很适合为家人做一道下饭快菜。', 4, 673.00, 40, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300066, '咖啡椰奶冻', '/upload/recipe-cover/import/r300066.png', '这款甜品融合了咖啡的醇厚与椰奶的清甜，口感像布丁般细腻滑嫩，层次丰富。淡奶油和椰汁提供了优质脂肪与植物营养，食用能带来满足感。做法非常友好，只需混合加热，无需复杂技巧，新手也能一次成功。不算冷藏的话，实际操作约需 1 小时，加上冷藏定型共 大约 4 小时即可享用。', 4, 162.00, 30, 1, 1109, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300067, '咖喱炒蟹', '/upload/recipe-cover/import/placeholder.png', '这是一道融合泰式风味的家常海鲜菜，浓郁咖喱包裹着爆满的蟹肉，带有蟹黄香气和椰浆的顺滑口感。螃蟹富含优质蛋白和多种微量元素，有助于补充体力。制作工序清晰，只需注意封煎蟹黄和最后关火翻炒酱汁，对有一定下厨经验的人比较友好，一般从备料到出锅约需 30 分钟。', 4, 815.00, 30, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300068, '咖喱肥牛', '/upload/recipe-cover/import/r300068.jpg', '咖喱肥牛是一道浓郁下饭的家常菜，咖喱的辛香与肥牛的脂香融合，搭配土豆、胡萝卜等蔬菜，口感绵软醇厚。富含蛋白质、维生素和钙质，荤素搭配均衡。做法简单，对新手友好，一般只需 40 分钟就能端上餐桌，很适合作为便当菜。', 4, 1821.00, 40, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300069, '咸肉菜饭', '/upload/recipe-cover/import/placeholder.png', '这是一道充满上海弄堂风情的家常主食，咸肉的醇香与青菜的清甜在猪油的点化下融进每一粒米饭，既有锅巴焦脆，又保留菜梗爽嫩，层次分明。青菜富含维生素和膳食纤维，咸肉提供蛋白质与能量，荤素搭配均衡。做法并不复杂，但需要掌握分次下菜叶的小技巧，对新手而言稍有挑战。从头备料到出锅，大约需要 1 小时。', 4, 847.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300070, '咸蛋黄狮子头（卤制版）', '/upload/recipe-cover/import/placeholder.png', '咸蛋黄狮子头（卤制版），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1108, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300071, '咸蛋黄狮子头（蒸制版）', '/upload/recipe-cover/import/placeholder.png', '咸蛋黄狮子头（蒸制版），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300072, '响油鳝丝', '/upload/recipe-cover/import/placeholder.png', '响油鳝丝是一道经典的江浙沪家常菜，鳝丝鲜嫩滑爽，蒜香浓郁，酱汁微甜，淋上热猪油后香气四溢，非常下饭。鳝鱼富含优质蛋白和 DHA，营养丰富。这道菜对刀工和火候有一定要求，难度适中，新手需要稍加练习。从备料到出锅，一般 大约 40 分钟就能端上餐桌。', 3, 556.00, 40, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300073, '商芝肉', '/upload/recipe-cover/import/placeholder.png', '商芝肉是陕西商县的传统风味菜，色泽红润，质地软嫩，肥而不腻，带有商芝独特的清香。猪肉提供优质蛋白和脂肪，蕨类蔬菜商芝则增添了膳食纤维和多种微量元素。这道菜工序繁琐，对刀工和火候均有要求，适合有一定烹饪基础的人挑战。从备料到成菜，全程大约需要 2.5 小时。', 5, 1621.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300074, '啤酒鸭', '/upload/recipe-cover/import/r300074.jpg', '这是一道风味独特的家常菜肴，鸭肉鲜香软烂，透着淡淡啤酒清香，热而不浮、香而不腻。鸭肉富含蛋白质，啤酒去腥增香，搭配食用更有滋味。做法对新手友好，从备料到出锅大约需要 1 小时。', 4, 170.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300075, '嗨嗨桶（炸物桶）', '/upload/recipe-cover/import/r300075.png', '嗨嗨桶（炸物桶），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1105, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
