INSERT INTO `recipe` VALUES (300077, '嗨嗨锅（泡椒鸡米花米线）', '/upload/recipe-cover/import/r300077.png', '嗨嗨锅（泡椒鸡米花米线），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1106, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300078, '嗨嗨锅（番茄肥牛锅）', '/upload/recipe-cover/import/r300078.png', '嗨嗨锅（番茄肥牛锅），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1106, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300079, '嗨嗨锅（酸菜鱼米线）', '/upload/recipe-cover/import/r300079.png', '嗨嗨锅（酸菜鱼米线），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1106, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300080, '嗨嗨锅（鲜蔬锅）', '/upload/recipe-cover/import/r300080.png', '嗨嗨锅（鲜蔬锅），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1106, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300081, '回锅肉', '/upload/recipe-cover/import/r300081.jpeg', '回锅肉是四川传统名菜，以二刀肉或五花肉为主料，成菜色泽红亮，肥肉透明微卷、瘦肉干香不柴，口感肥而不腻，咸鲜微辣，带有蒜苗与豆瓣酱的复合香气。猪肉富含优质蛋白和必需脂肪酸，搭配青红椒、蒜苗可补充维生素。这道菜步骤稍多，包含煮、切、煸炒，对火候和刀工有一定要求，但按流程操作新手也能成功，预计全程耗时约 40 分钟。', 4, 997.00, 40, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300082, '土豆炖排骨', '/upload/recipe-cover/import/placeholder.png', '排骨软烂脱骨，土豆绵软入味，酱香浓郁微甜微辣，是一道典型的北方家常炖菜。富含蛋白质、钙质和碳水化合物，营养均衡。制作略有难度，需掌握炒糖色与火候，但步骤清晰，新手也能尝试，全程大约 1.5 小时。', 3, 991.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300083, '土豆牛腩', '/upload/recipe-cover/import/r300083.png', '土豆牛腩，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1111, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300084, '地三鲜', '/upload/recipe-cover/import/r300084.jpg', '地三鲜是东北经典家常菜，茄子软糯、土豆绵香、尖椒清脆，酱香咸鲜十分下饭。食材搭配可提供丰富的维生素与膳食纤维，土豆还带来满足的碳水能量。这道菜需要油炸和快速翻炒，有一定技巧要求，新手需稍加练习，制作全程约需 40 分钟。', 3, 264.00, 40, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300085, '基础牛奶面包', '/upload/recipe-cover/import/r300085.jpg', '这款基础牛奶面包通过酵头预发酵简化了传统面包的制作，成品奶香浓郁，质地松软。富含碳水化合物和蛋白质，能为身体提供能量。难度适中，适合烘焙新手尝试，全程大约需要 200 分钟。', 5, 2048.00, 200, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300086, '外婆菜炒鸡蛋', '/upload/recipe-cover/import/r300086.png', '外婆菜炒鸡蛋，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300087, '大大大块牛腩面', '/upload/recipe-cover/import/r300087.png', '大大大块牛腩面，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300088, '大排面', '/upload/recipe-cover/import/r300088.png', '大排面，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300089, '大盘肥肠鸡手工面', '/upload/recipe-cover/import/r300089.png', '大盘肥肠鸡手工面，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300090, '太阳蛋', '/upload/recipe-cover/import/placeholder.png', '太阳蛋是一道用微波炉快速制成的家常早餐。口感嫩滑，蛋清凝固、蛋黄微溏，属于典型的快手菜。鸡蛋富含优质蛋白和多种维生素，易于消化吸收。做法非常简单，对新手友好。使用可控火候微波炉只需 3 分钟就能完成，不可控火候的也仅需几分钟反复加热。', 2, 113.00, 3, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300091, '奇异果菠菜特调', '/upload/recipe-cover/import/r300091.jpg', '这是一道清爽健康的果蔬特饮，口感酸甜细腻，带有奇异果与苹果的天然果香，菠菜味清淡不抢。富含维生素 C 和膳食纤维，有助于促进消化。制作非常简单，新手也能一次成功，全程预计只需 10 分钟。', 1, 184.00, 10, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300092, '奥利奥冰淇淋', '/upload/recipe-cover/import/placeholder.png', '奥利奥冰淇淋口感细腻，奶香与奥利奥的酥脆甜蜜相融，纯动物奶油令整体轻盈不腻。它主要提供能量，含有脂肪和碳水化合物，适合作为消暑小甜点。制作过程较为简单，只需处理饼干夹心和搅打奶油，新手稍加耐心也可完成，全程准备约需半小时，再冷冻 4 小时以上即可享用。', 3, 1160.00, 30, 1, 1109, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300093, '奥尔良风味烤鸡腿', '/upload/recipe-cover/import/placeholder.png', '奥尔良风味烤鸡腿是一道简单易做的菜，富含蛋白质和铁。总共花费约 3 小时，其中手动操作时间约 20 分钟。', 5, 955.00, 20, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300094, '奥尔良鸡翅', '/upload/recipe-cover/import/r300094.jpg', '奥尔良鸡翅，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300095, '奶油蘑菇汤', '/upload/recipe-cover/import/placeholder.png', '这是一道经典法式浓汤，口感丝滑绵密，菌香与奶香交融。蘑菇富含膳食纤维和微量元素，牛奶则提供优质蛋白与钙质。做法非常简单，新手也能轻松驾驭，从备料到完成大约需要 30 分钟。 ---', 1, 426.00, 30, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300096, '奶皮子酸奶', '/upload/recipe-cover/import/placeholder.png', '奶皮子酸奶，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300097, '奶茶', '/upload/recipe-cover/import/placeholder.png', '这是一道用红茶和奶粉轻松调制的家常饮品，茶香与奶香交融，口感顺滑温暖。红茶中的茶多酚搭配牛奶的蛋白质和钙质，既能提神又补充日常营养。做法非常简单，新手也能一次成功，仅需大约半 小时就能喝上自制奶茶。', 2, 81.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300098, '奶酪培根通心粉', '/upload/recipe-cover/import/r300098.jpg', '奶酪培根通心粉是经典美式家常菜，口感浓郁绵密，奶酪包裹弹牙通心粉，搭配香脆培根，咸香满足。富含蛋白质与钙质，但热量和脂肪较高，建议偶尔享用。制作需要一定耐心，掌握基础白酱和火候对新手略有挑战，整体难度中等。不烘烤时约 30 分钟即可上桌，若选择烘烤需额外预热和烤制，总时长约 1 小时。', 3, 728.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300099, '奶黄鸡包', '/upload/recipe-cover/import/r300099.png', '奶黄鸡包，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300100, '姜炒鸡', '/upload/recipe-cover/import/r300100.jpg', '姜炒鸡是湖南风味的下饭菜肴，鸡肉干香入味，姜香浓郁，辣而不燥。鸡肉富含优质蛋白，生姜有助于驱寒暖胃、促进食欲。做法简单，新手也能轻松掌握。从腌制到出锅大约需要 1 小时。', 3, 1539.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300101, '姜葱捞鸡', '/upload/recipe-cover/import/placeholder.png', '姜葱捞鸡是一道粤式经典家常菜，鸡肉嫩滑多汁，葱姜香气浓郁，咸鲜适口，十分下饭。鸡腿肉提供优质蛋白质，搭配姜葱能温中散寒、促进食欲。整体操作以蒸制和手撕为主，步骤清晰，对新手来说比较容易上手。从备料到完成大约需要 40 分钟。', 3, 549.00, 40, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300102, '姬松茸菌子鸡汤面', '/upload/recipe-cover/import/placeholder.png', '姬松茸菌子鸡汤面，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300103, '孜然牛肉', '/upload/recipe-cover/import/placeholder.png', '孜然牛肉是一道香辣鲜嫩的家常小炒，浓郁的孜然风味与牛肉的软滑、青椒的清脆融合得恰到好处。牛肉富含优质蛋白和铁，搭配青椒还能补充维生素，营养均衡。制作需要一些刀工和火候把控，适合有一定下厨基础的爱好者尝试。算上腌肉和备菜，全程大约 45 分钟就能端上餐桌。', 3, 612.00, 45, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300104, '完美水煮蛋', '/upload/recipe-cover/import/placeholder.png', '这是一道通过科学家研发的循环水煮法制成的鸡蛋，蛋黄绵密细腻，蛋白均匀凝固，口感层次分明。它保留了更多营养素，多酚含量比传统煮法高 23%，蛋白质丰富。制作难度较高，需精准控温并反复转移，预计制作时长约 35 分钟。', 2, 86.00, 35, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300105, '宫保鸡丁', '/upload/recipe-cover/import/r300105.jpg', '这道川味名菜以糊辣荔枝味见长，小酸甜中透着干辣椒与花椒的香气，鸡丁嫩滑、花生酥脆，口感层次丰富。富含优质蛋白和不饱和脂肪酸，开胃下饭。做法分成简易和进阶两版，对新手比较友好，提前规划好腌制时间即可。从备料到出锅大约需要 1.5 小时。', 4, 1790.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300106, '家常土豆片', '/upload/recipe-cover/import/r300106.jpg', '家常土豆片，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300107, '家常小炒', '/upload/recipe-cover/import/r300107.jpg', '家常小炒，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300108, '家常日本豆腐', '/upload/recipe-cover/import/placeholder.png', '家常日本豆腐是一道外酥里嫩的家常快手菜，金黄脆壳包裹着柔滑的玉子豆腐，搭配青椒、胡萝卜等时蔬，可调成咸鲜或酸甜风味，脆嫩咸香。日本豆腐以鸡蛋为主要原料，富含优质蛋白，加上木耳和蔬菜，营养均衡。需要一点煎豆腐的技巧，难度适中，新手也能尝试，全程大约 30 分钟即可上桌。', 3, 946.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300109, '小炒河虾', '/upload/recipe-cover/import/r300109.png', '小炒河虾，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300110, '小炒肉', '/upload/recipe-cover/import/placeholder.png', '小炒肉是一道香辣下饭的经典湘式家常菜，五花肉片焦香不腻，搭配鲜辣椒与豆豉、豆瓣酱炒出浓郁酱香。富含优质蛋白质和脂肪，辣椒能提供丰富的维生素 C，有助开胃暖身。制作难度中等，适合有一定基础的新手尝试，需注意肉片腌制和火候把控。从备料到出锅大约需要 1 小时，其中腌制 30 分钟，炒制过程约 15 分钟。', 3, 2873.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300111, '小炒脆笋', '/upload/recipe-cover/import/placeholder.png', '小炒脆笋，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300112, '小炒花菜', '/upload/recipe-cover/import/r300112.jpg', '小炒花菜，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300113, '小炒藕丁', '/upload/recipe-cover/import/r300113.jpg', '小炒藕丁是一道快手家常素菜，藕丁脆嫩爽口，咸鲜中带着微微辣意，非常下饭。莲藕富含膳食纤维和维生素，有助于清热润燥。制作简单，只要注意藕丁焯水和调味，厨房新手也能轻松完成。全程大约 20 分钟就能端上餐桌。', 3, 214.00, 20, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300114, '小炒面筋', '/upload/recipe-cover/import/r300114.png', '小炒面筋，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300115, '小炒香干', '/upload/recipe-cover/import/r300115.jpg', '小炒香干，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300116, '小炒鸡丁', '/upload/recipe-cover/import/r300116.jpg', '小炒鸡丁，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300117, '小炒鸡肝', '/upload/recipe-cover/import/r300117.jpg', '这道鸡肝小炒蒜香浓郁，口感嫩滑带点孜然的焦香，是一道家常风味小炒。鸡肝富含铁、维生素 A 和优质蛋白，有助补血明目。制作时需掌握焯水去腥的技巧，对新手略有挑战，从备料到出锅大约需要四十分钟。', 3, 760.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300118, '小炒黄牛肉', '/upload/recipe-cover/import/r300118.jpg', '这道湘味小炒以大火爆炒逼出牛肉的嫩滑与椒香，口感鲜辣劲爽、芹菜脆嫩，极具湖南风味。牛里脊提供优质蛋白和易吸收的铁质，搭配芹菜增添膳食纤维，营养均衡。备料与烹饪步骤简单明了，全程旺火快炒，对新手十分友好，从切配到出锅大约一小时即可完成。', 4, 619.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300119, '小米南瓜粥', '/upload/recipe-cover/import/r300119.png', '小米南瓜粥，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300120, '小米粥', '/upload/recipe-cover/import/placeholder.png', '小米粥是一道北方常见的家常粥品，口感绵滑，米香浓郁，熬出的米油尤其养胃。它富含蛋白质、脂肪、碳水化合物和胡萝卜素，维生素 B1 含量在粮食中名列前茅，容易消化吸收。做法非常简单，新手也能轻松掌握，从烧水到出锅大约需要 30-35 分钟。', 2, 362.00, 35, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300121, '小米辣炒肉', '/upload/recipe-cover/import/placeholder.png', '小米辣炒肉香辣过瘾，是一道典型的西南风味下饭菜，猪肉的鲜嫩搭配小米辣的爽辣，令人食欲大开。猪肉富含蛋白质和脂肪，辣椒提供丰富的维生素 C，能够促进食欲。虽然需要掌握爆香和翻炒的火候，但步骤清晰，新手也能轻松上手，预计制作时长约 25 分钟。注意，这道菜辣味突出，不建议清淡饮食者尝试。', 3, 620.00, 25, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300122, '小酥肉', '/upload/recipe-cover/import/placeholder.png', '小酥肉外酥里嫩，咸香中带着花椒的微麻，是川渝地区家家户户都会做的家常炸物。猪肉富含蛋白质和脂肪，油炸后热量较高，适合偶尔解馋。这道菜步骤稍多，需掌握初炸定型与复炸上色的火候，对新手略有挑战，预计从头到尾约 1 小时 30 分钟完成。', 3, 1939.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300123, '小鸡炖蘑菇', '/upload/recipe-cover/import/placeholder.png', '小鸡炖蘑菇，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1111, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300124, '小龙虾', '/upload/recipe-cover/import/r300124.jpg', '这道菜麻辣鲜香，虾肉细嫩多汁，是经典的川湘风味下酒菜，在家自制干净又实惠。小龙虾富含优质蛋白和多种微量元素，但汤汁含油盐较多，适合偶尔享用。处理活虾和多种香料对新手有一定挑战，不过不去虾线可明显降低难度。从备料到出锅大约需要 45 分钟。', 4, 571.00, 45, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300125, '尖叫牛蛙', '/upload/recipe-cover/import/r300125.jpg', '这道菜鲜辣开胃，蛙肉滑嫩弹牙，是一道典型的川味家常菜。牛蛙本身高蛋白、低脂肪，搭配泡姜泡椒等发酵食材，有助于促进食欲。做法相对直接，但油温控制和调味比例需要稍加留意，一般初学者也能在 1 到 2 小时内完成。', 4, 1643.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300126, '尖椒炒牛肉', '/upload/recipe-cover/import/placeholder.png', '一道家常小炒，咸香微辣，牛肉滑嫩入味，尖椒清脆爽口。牛肉提供优质蛋白和铁，尖椒富含维生素 C，搭配起来营养均衡。虽然腌制需要一些耐心，但操作步骤明确，新手也能上手，难度适中。从备料到出锅大约需要 1 小时。', 3, 449.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300127, '山西过油肉', '/upload/recipe-cover/import/placeholder.png', '过油肉是山西传统名菜，肉片滑嫩、蒜苔爽脆，咸鲜微酸，带着陈醋的醇香，属于典型的地方家常风味。猪里脊提供优质蛋白，搭配木耳、蒜苔和葱头，营养均衡。这道菜对火候和上浆技巧有一定要求，更适合有一定下厨基础的爱好者尝试。从备料到出锅，大约需要 40 分钟。', 4, 679.00, 40, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300128, '巴基斯坦牛肉咖喱', '/upload/recipe-cover/import/r300128.png', '这道巴基斯坦风味咖喱牛肉香浓软糯，酸辣开胃，带着浓郁的香料气息。牛肉提供优质蛋白，搭配番茄和酸奶，营养均衡。做法不算繁琐，但慢炖需要一点耐心，很适合在闲暇的周末从容准备。从头到尾大约两个半小时，就能端出一锅温暖的异国美味。', 5, 602.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300129, '带把肘子', '/upload/recipe-cover/import/placeholder.png', '带把肘子是陕西大荔的传统名菜，因脚爪形似把柄而得名。成菜肘皮胶粘软糯，肉质酥烂不腻，蘸甜面酱佐葱段食用，咸香醇厚。富含胶原蛋白和优质蛋白质，滋补养颜。制作需去骨、定形、长时间蒸制，对新手有一定挑战，预计整个制作过程约需 3.5 小时。', 5, 1037.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300130, '干煎阿根廷红虾', '/upload/recipe-cover/import/r300130.jpg', '一道鲜美诱人的海鲜快手菜，煎制后的阿根廷红虾肉质白嫩，口感鲜甜浓郁，虾壳酥香。富含碘、磷和虾青素等微量元素，有助于增强免疫力、保护心脏并降低胆固醇。难度适中，需要掌握火候和翻面技巧，但步骤清晰，新手按操作来也能成功。预计 大约 20 分钟即可完成。', 3, 309.00, 20, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300131, '干煸仔鸡', '/upload/recipe-cover/import/r300131.jpg', '这是一道源自北大食堂、甜辣风味的创新川菜，鸡肉先腌后炸，外酥里嫩，土豆香糯，青椒脆爽，裹满红亮的甜辣酱汁，咸甜微辣十分开胃。富含蛋白质、碳水化合物及维生素。制作涉及油炸和酱汁熬制，对新手稍有挑战，但按步骤操作即可成功，全程约需 1 小时。', 4, 1300.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300132, '干锅花菜', '/upload/recipe-cover/import/r300132.jpg', '干锅花菜是一道湘味家常菜，口感脆嫩干香，五花肉焦香四溢，带着微微辣意。花菜富含维生素 C 和膳食纤维，搭配五花肉补充蛋白质与能量。制作难度适中，只需注意焯水后充分沥干并把五花肉煸出油脂，适合有一定基础的烹饪新手。从准备到出锅大约需要 40 分钟。', 3, 759.00, 40, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300133, '广式萝卜牛腩', '/upload/recipe-cover/import/r300133.webp', '这是一道广式家常炖菜，牛腩软烂入味，萝卜吸饱汤汁后清甜浓郁，整体酱香回甘。富含优质蛋白和膳食纤维，开胃助消化。制作步骤稍多但难度适中，新手按部就班也能成功。预计从头到尾大约需要 2.5 小时完成。', 4, 483.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300134, '微波炉腊肠煲仔饭', '/upload/recipe-cover/import/r300134.png', '这是一道简单快手的粤式风味主食，米饭吸足腊肠油脂后油润咸香，搭配脆嫩青菜和胡萝卜，口感层次丰富。富含碳水化合物、蛋白质和多种维生素，营养均衡。烹饪用微波炉操作，对新手十分友好，预计全程仅需 15 分钟即可享用。', 2, 1039.00, 15, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300135, '微波炉荷包蛋', '/upload/recipe-cover/import/placeholder.png', '微波炉荷包蛋是一道便捷的家常快手菜，蛋白嫩滑、蛋黄软糯，带有芝麻油的清香。鸡蛋富含优质蛋白质和卵磷脂。做法极其简单，新手也能轻松掌握，从准备到出锅仅需约 2 分钟。', 1, 169.00, 2, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300136, '微波炉蒸蛋', '/upload/recipe-cover/import/placeholder.png', '一道用微波炉快速制作的嫩滑蒸蛋，口感细腻如布丁，属于家常快手菜。富含优质蛋白，易于消化吸收，很适合作为早餐或轻食。制作非常简单，新手也能轻松上手，全程约 10 分钟即可完成。', 1, 151.00, 10, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300137, '微波炉蛋糕', '/upload/recipe-cover/import/placeholder.png', '微波炉版的快手蛋糕，口感松软香甜，是一道零基础也能轻松上手的家庭甜点。以鸡蛋、面粉为基础，搭配黄油提供能量和浓郁香气，糖分快速补充体力，加入坚果或水果还能增加膳食纤维和维生素。仅需准备少数材料，借助微波炉高火一分钟即可完成，从备料到品尝最快仅需 2 分钟，新手约 20 分钟即可搞定。', 1, 308.00, 2, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300138, '微波炉鸡蛋羹', '/upload/recipe-cover/import/r300138.jpg', '微波炉鸡蛋羹是一道简单快手的家常蒸蛋，口感嫩滑细腻，尤其适合作为夜宵或快速加餐。鸡蛋富含优质蛋白质和多种维生素，能为身体提供必要营养，虾皮还补充了钙质。这道菜对新手非常友好，无需掌握火候技巧，从打蛋调味到出炉，全程仅需约 10 分钟即可完成。', 2, 160.00, 10, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300139, '微波葱姜黑鳕鱼', '/upload/recipe-cover/import/placeholder.png', '微波做鱼，葱姜提鲜，热油一淋，香气四溢，是一道肉质细嫩、滋味咸鲜的家常蒸鱼菜，属于改良粤式做法。黑鳕鱼富含优质蛋白和欧米伽-3 脂肪酸，对心脑健康有益。操作不算复杂，但需掌握火候和油温，更适合有一定下厨经验的朋友。从备料到上桌大约只需二十分钟。', 3, 749.00, 30, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300140, '徽派红烧肉', '/upload/recipe-cover/import/r300140.jpeg', '徽派红烧肉是一道色泽红亮、肥而不腻的经典徽式家常菜，口感软糯 Q 弹，咸甜交融。以五花肉为主料，富含优质蛋白质和脂肪，能提供充沛能量。烹制需掌握炒糖色与火候，稍有挑战，预估制作时长约 45 分钟。', 4, 3847.00, 45, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300141, '心形鸡排', '/upload/recipe-cover/import/r300141.png', '心形鸡排，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1105, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300142, '意式烤鸡', '/upload/recipe-cover/import/placeholder.png', '意式烤鸡是一道带有地中海风味的家常烤箱菜。鸡腿肉经过蒜香橄榄油腌制，烤后外皮微焦、内里鲜嫩多汁，搭配柠檬汁和欧芹，口感清爽不腻。鸡肉富含优质蛋白质，橄榄油提供不饱和脂肪酸，营养均衡。制作难度适中，需要提前预热烤箱，新手跟着步骤也能顺利完成，从腌制到出炉总计约五十分钟。', 3, 315.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300143, '意式肉酱面', '/upload/recipe-cover/import/r300143.jpg', '意式肉酱面是一道简单快手的家常西餐，酱汁浓郁、面条筋道，适合忙碌的日常。肉末和洋葱搭配成品意面酱，能快速补充蛋白质与碳水化合物，洋葱还含有膳食纤维。做法对初学者十分友好，全程只需简单切炒，熟练后 15 分钟就能端上桌，比方便面更满足。', 1, 1199.00, 15, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300144, '意式香肠北非蛋', '/upload/recipe-cover/import/placeholder.png', '意式香肠北非蛋是一道浓郁鲜香的地中海风味料理，溏心蛋卧在酸甜的番茄肉酱里，搭配脆面包蘸食，口感丰富。主要食材提供优质蛋白质，番茄、甜椒和洋葱带来维生素与膳食纤维。制作不难，只需注意焖蛋火候，全程约 30 分钟即可上桌。', 3, 668.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300145, '懒人蛋挞', '/upload/recipe-cover/import/r300145.png', '这道甜品利用现成的蛋挞皮和蛋挞液，外皮酥香、内馅嫩滑，带有焦糖斑点，是经典粤式点心中最易上手的版本。主要成分鸡蛋和牛奶提供了优质蛋白质与钙质，适合作为家庭小点心。整个操作只需组装和烘烤，对完全零基础的新手也很友好，从预热烤箱到出炉约需 40 分钟。', 3, 137.00, 40, 1, 1107, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300146, '戚风蛋糕', '/upload/recipe-cover/import/r300146.jpg', '这道烘焙入门甜品口感细腻绵软，拥有云朵般的轻盈质地，属于西点中的经典基础款。主要原料鸡蛋和牛奶提供了优质蛋白与钙质，营养丰富。制作过程对打发、翻拌及烘烤火候要求较高，具有一定挑战，但只要耐心按步骤操作，新手也能成功。从准备到出炉一般需要 1.5 至 2 小时。', 5, 274.00, 30, 1, 1109, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300147, '手工春卷', '/upload/recipe-cover/import/r300147.png', '手工春卷，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300148, '手工水饺', '/upload/recipe-cover/import/placeholder.png', '手工水饺是一道中式经典主食，皮薄馅大、鲜美多汁，饱腹又可以根据个人口味随意调味。猪肉馅提供优质蛋白质和脂肪，搭配韭菜还能补充维生素与膳食纤维。这道菜品对新手来说难度较高，需要掌握和面、擀皮、调馅和煮饺的火候，预计制作时间约 3 小时。', 5, 1313.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300149, '手工烧麦', '/upload/recipe-cover/import/r300149.png', '手工烧麦，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300150, '手抓饼', '/upload/recipe-cover/import/placeholder.png', '手抓饼外酥里软，层次分明，是深受喜爱的家常面点。饼皮用半烫面制作，柔韧有嚼劲，搭配鸡蛋和蔬菜，营养均衡。做法对新手很友好，从和面到出锅大约只需 40 分钟，非常适合忙碌的早晨。 ---', 2, 1050.00, 40, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300151, '手撕包菜', '/upload/recipe-cover/import/r300151.jpeg', '手撕包菜是一道酸辣脆爽的经典湘菜，成菜包菜脆嫩入味，五花肉干香不腻，开胃下饭。包菜富含维生素 C 和膳食纤维，搭配五花肉能提供蛋白质和能量。制作时需要掌握大火快炒的火候，对新手稍有挑战，但按步骤操作也能成功。从备料到出锅大约 20 分钟。', 3, 1663.00, 20, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300152, '手枪大鸡腿', '/upload/recipe-cover/import/r300152.jpg', '手枪大鸡腿，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1105, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300153, '扬州炒饭', '/upload/recipe-cover/import/r300153.png', '这是一道配料丰富的升级版炒饭，米饭粒粒分明，鸡蛋嫩滑，搭配虾仁、午餐肉和蔬菜丁，口感层次鲜明，属于淮扬菜系中的经典主食。富含优质蛋白、碳水化合物和多种维生素，营养均衡。步骤虽多但操作直观，对初级烹饪者也较为友好，只需耐心备料。预计制作时长约 1 小时。', 4, 1769.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300154, '把子肉', '/upload/recipe-cover/import/placeholder.png', '把子肉，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1108, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300155, '披萨饼皮', '/upload/recipe-cover/import/r300155.jpeg', '披萨饼皮采用低温隔夜发酵，成品饼底柔软又略带嚼劲，属于家常西式面点。主要提供碳水化合物和少量优质脂肪。制作流程简单，但需要耐心等待面团发酵，对新手也算友好。从准备到烘烤完成，算上隔夜冷藏时间大约需要 10-14 小时，适合提前一天备好。', 4, 537.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300156, '拔丝土豆', '/upload/recipe-cover/import/r300156.jpeg', '拔丝土豆是一道经典的鲁菜，成菜色泽金黄、糖丝细长，外脆里糯、香甜可口。土豆富含碳水化合物和维生素 C，能快速补充能量。这道菜有一定难度，新手需注意熬糖火候，避免翻沙或焦苦。从备料到出锅，预计制作时长约 30 分钟。', 3, 1158.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300157, '排骨山药玉米汤', '/upload/recipe-cover/import/placeholder.png', '排骨山药玉米汤清甜醇厚，山药软糯、玉米回甘，融合了排骨的鲜香，属于老少皆宜的家常汤品。它富含蛋白质、膳食纤维和多种维生素，有健脾益胃、增强抵抗力的作用。做法简单，预处理和炖煮步骤清晰，新手也能轻松上手，全程大约需要 1 小时即可完成。', 2, 1054.00, 30, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300158, '排骨苦瓜汤', '/upload/recipe-cover/import/placeholder.png', '排骨苦瓜汤是一道汤色清亮、鲜美回甘的粤式家常汤品，排骨软烂、苦瓜清热解腻。富含蛋白质与维生素，虾皮还能补充钙质。处理过程需要焯水去腥、仔细去除苦瓜瓤，对新手有一定挑战，但借助电压力锅可大幅简化；传统慢炖需 2 至 4 小时，建议提前 4 小时准备，压力锅则只需约 1 小时。', 4, 905.00, 30, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300159, '提拉米苏', '/upload/recipe-cover/import/r300159.jpg', '这道意大利传统甜品无需烤箱，奶酪糊绵密轻盈，浸润咖啡液的手指饼干香醇柔软，属于入门级甜点。富含蛋白质和钙质，但糖分与热量较高，宜偶尔享用。操作简便，对烘焙新手十分友好，只需大约半 小时动手，再冷藏四小时即可成型品尝。', 4, 809.00, 30, 1, 1109, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300160, '新疆大盘鸡', '/upload/recipe-cover/import/r300160.jpeg', '新疆大盘鸡是一道风味浓郁、色彩鲜艳的新疆家常菜，鸡肉鲜嫩不柴，土豆软糯吸汁，麻辣中带着微甜回甘。富含优质蛋白质和碳水化合物，搭配彩椒还能补充维生素 C。制作过程需要炒糖色和掌握收汁火候，对新手有一定挑战，但跟随步骤细心操作并不难，整体大约 1 小时可以完成。', 4, 1108.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300161, '无厨师机蜂蜜面包', '/upload/recipe-cover/import/r300161.jpg', '这是一款无需厨师机的家常蜂蜜小面包，松软香甜，底部略带脆感，表面刷满蜂蜜水再撒上芝麻，透着朴实的甜香。主要用料为高筋面粉、牛奶、鸡蛋和黄油，提供充足的碳水化合物、蛋白质和钙质，作为早餐或加餐都很安心。做法简单，全程手揉，发酵时间灵活，甚至可以提前一晚放入冰箱冷藏，第二天再烘烤，对新手相当友好。制作耗时大约 3 小时，其中大部分是发面等待时间，实际动手并不费力。', 5, 176.00, 30, 1, 1109, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300162, '无骨鸡爪', '/upload/recipe-cover/import/r300162.jpg', '酸辣开胃、口感 Q 弹，是一道家常凉拌小吃。鸡爪富含胶原蛋白，对皮肤有益。去骨步骤繁琐费力，制作难度较高，不太适合新手尝试。全程耗时约 8 小时 15 分钟。', 5, 815.00, 15, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300163, '日式咖喱饭', '/upload/recipe-cover/import/r300163.jpg', '日式咖喱饭是一道浓郁醇厚的家常和风料理，以咖喱块调味，搭配土豆、胡萝卜、洋葱和肉类，口感顺滑绵密、辛香微甜。它富含蛋白质、碳水与多种维生素，能为身体提供充足能量。做法整体不算复杂，但需要掌握火候与搅拌技巧，适合稍有下厨经验的朋友尝试。从备料到出锅约需 1 小时，冷藏后风味更佳。', 4, 730.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300164, '日式肥牛丼饭', '/upload/recipe-cover/import/r300164.png', '一道经典的日式家常盖饭，肥牛片与白洋葱在咸甜酱汁中炖煮入味，肉质软嫩，洋葱甜润，汁香浓郁。牛肉提供优质蛋白和血红素铁，洋葱富含膳食纤维与多种抗氧化物。制作不算复杂，新手只要跟着步骤操作也能轻松完成，炒煮过程约需 30 分钟。', 4, 774.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300165, '昂刺鱼豆腐汤', '/upload/recipe-cover/import/r300165.jpg', '昂刺鱼豆腐汤是一道口感鲜嫩、汤白味浓的家常汤品，鱼肉刺少肉嫩，豆腐滑润，带有胡椒的微辛暖意，适合各个年龄层。鱼富含优质蛋白质，搭配豆腐能补充钙质，营养均衡好吸收。制作过程不算复杂，只要注意去腥和煎鱼防粘，一般初学者也可以上手，预计制作时长约 40 分钟。', 3, 321.00, 40, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300166, '朱雀汤', '/upload/recipe-cover/import/r300166.jpg', '朱雀汤是一道豫东地区的家常快手汤品，口感顺滑香甜，带着芝麻油的醇香。鸡蛋提供优质蛋白质，制作非常简单，只需烧水冲蛋几步就能完成，前后不到十分钟即可上桌，还有清热去火的效果。', 1, 168.00, 30, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300167, '杀猪菜', '/upload/recipe-cover/import/placeholder.png', '这是一道源自东北的经典炖菜，酸爽鲜香、暖心暖胃。酸菜富含乳酸菌和膳食纤维，排骨提供优质蛋白与钙质，血肠则能补充铁元素。制作时需要耐心处理血肠以防煮爆，对厨房新手有一定挑战。从备料到出锅，预计耗时约一小时。', 4, 1657.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300168, '杂粮饭', '/upload/recipe-cover/import/r300168.png', '杂粮饭，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300169, '杨枝甘露', '/upload/recipe-cover/import/placeholder.png', '这是一道改良版的经典港式甜品，用奇亚籽代替西谷米，口感滑嫩又带有籽粒的细微嚼劲，芒果的香甜与葡萄柚的微酸交织，椰奶增添浓郁。富含膳食纤维、维生素 C 和优质脂肪，清爽解暑。制作非常简单，新手也能轻松完成，从备料到享用只需约 20 分钟。', 2, 661.00, 20, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300170, '松仁玉米', '/upload/recipe-cover/import/placeholder.png', '松仁玉米是一道口感清甜脆嫩的家常快手菜，松仁香酥、玉米甜润，属于广受欢迎的北方家常风味。玉米和松仁搭配，能提供丰富的膳食纤维、不饱和脂肪酸和多种维生素，营养均衡。做法简单，新手也能轻松驾驭，从备料到出锅一般只需大约十五 分钟。', 2, 580.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300171, '松糕', '/upload/recipe-cover/import/r300171.png', '松糕，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300172, '枝竹羊腩煲', '/upload/recipe-cover/import/placeholder.png', '这是一道源自广东的传统煲仔菜，羊肉与腐竹在柱侯酱和腐乳的调和下，酱香浓郁，口感肥美而不腻口，暖身暖心，尤其适合寒冬食用。羊肉富含蛋白质和铁质，能温补气血，腐竹则提供优质植物蛋白，搭配起来营养均衡。虽然备料和炖煮步骤较多，但全程火候控制并不复杂，新手只需按部就班也能成功。预计从准备到出锅约需两个半小时。', 5, 2391.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300173, '柠檬凤爪', '/upload/recipe-cover/import/r300173.jpg', '柠檬凤爪，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1006, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300174, '柠檬水', '/upload/recipe-cover/import/r300174.jpg', '这道饮品以新鲜柠檬为主角，搭配果蜜调和，酸甜平衡，冰镇后更感清凉解暑。柠檬富含维生素 C，经常饮用有助于补充营养、提神美白。制作步骤极简，只需捶打、加料、摇晃，新手也能在三五分钟内完成。', 1, 141.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300175, '柱候牛腩', '/upload/recipe-cover/import/r300175.jpeg', '这是一道经典广式风味菜肴，肉香浓郁，色泽红亮，带筋牛腩软烂入味，口感丰富。富含优质蛋白质和胶原蛋白，滋补暖身。虽需一定耐心，但使用高压锅能大幅缩短时间，对新手也较友好。普通炖煮约需 3 小时，用高压锅则约 1 小时即可完成。', 4, 980.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300176, '桂圆红枣粥', '/upload/recipe-cover/import/placeholder.png', '一道甜香软糯的中式传统粥品。以糯米、红枣和桂圆同煮，自带甘甜，暖身暖胃。有补血安神、健脑益智、补养心脾的食养效果。做法非常友好，新手也能轻松掌握，从准备到粥香满屋大约需要 70 分钟。', 2, 617.00, 70, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300177, '桂林十八酿', '/upload/recipe-cover/import/r300177.png', '桂林传统酿菜系列，将调好味的猪肉、虾滑等馅料酿入青椒、苦瓜、田螺、茄子等十多种中空食材中，煎焖成菜，一菜一味，鲜香多汁，口感软嫩或弹牙，属于浓郁的地方家常风味。馅料提供优质蛋白质，搭配多种蔬菜，富含维生素与膳食纤维，营养较为均衡。制作步骤需要逐一填馅和掌控火候，稍需耐心，但操作逻辑简单，厨艺新手也能尝试，预计全部完成约需 1.5 小时。', 3, 468.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300178, '梅干菜凤爪翅', '/upload/recipe-cover/import/r300178.jpg', '梅干菜凤爪翅，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1111, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300179, '梅菜扣肉', '/upload/recipe-cover/import/r300179.jpeg', '这是一道客家传统名菜，成菜酱红油亮、汤汁黏稠，扣肉肥而不腻、软烂醇香。五花肉富含优质蛋白和脂肪酸，搭配梅干菜能提供膳食纤维。整体工序稍多，需要掌握煮、炸、蒸的火候，对新手有一定挑战。从备料到出锅，连同浸泡梅菜的时间在内，大约需要 2.5 小时。', 4, 3756.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300180, '棒棒虾', '/upload/recipe-cover/import/r300180.png', '棒棒虾，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1105, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300181, '椒盐排条', '/upload/recipe-cover/import/placeholder.png', '椒盐排条是上海本帮菜里的经典家常菜，外酥里嫩，咸香适口。猪大排提供优质蛋白质和必需氨基酸，能补充体力。这道菜虽然步骤稍多，但跟着流程走并不难，新手也可以大胆尝试。从备料到出锅，大约需要 40 分钟。', 4, 1290.00, 40, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300182, '椒盐玉米', '/upload/recipe-cover/import/r300182.jpeg', '一道外酥里嫩、咸香扑鼻的风味小食，有着川菜馆里常见的干香口感，咬开是玉米自带的清甜。玉米提供丰富的碳水化合物与膳食纤维，搭配芝麻还能补充优质脂肪和维生素 E。这道菜步骤略多但操作简单，需要一点耐心抖水裹粉，对新手比较友好。从解冻到出锅大约需要 30 分钟。', 3, 693.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300183, '榄菜肉末四季豆', '/upload/recipe-cover/import/r300183.jpg', '榄菜肉末四季豆是潮汕风味浓厚的家常小炒，口感咸香脆嫩，十分下饭。四季豆富含膳食纤维与维生素，搭配肉末能提供优质蛋白，橄榄菜则带来独特的鲜咸风味。这道菜步骤清晰，新手也能较快上手，只需注意将四季豆彻底炒熟。从备料到出锅，大约三十分钟即可完成。', 3, 720.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300184, '毛豆烧土鸡', '/upload/recipe-cover/import/r300184.png', '毛豆烧土鸡，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300185, '水油焖蔬菜', '/upload/recipe-cover/import/placeholder.png', '水油焖蔬菜是一道简单快手的家常佐餐，通过沸水加几滴油和调料，让叶菜口感软嫩、色泽油亮，既清爽又带有淡淡油香。这种做法有助于提高脂溶性维生素的吸收率，比生吃蔬菜更有营养价值。烹饪难度低，对新手非常友好，从洗菜到出锅一般只需 10 分钟。', 2, 92.00, 10, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300186, '水煮牛肉', '/upload/recipe-cover/import/r300186.jpg', '水煮牛肉是川菜中的经典麻辣味型，口感滑嫩、汤汁红亮、香辣烫鲜。牛肉富含优质蛋白质和铁，搭配豆芽可补充膳食纤维。这道菜对新手来说不算太难，但需注意火候和泼油安全，整体制作约需四十分钟。', 3, 431.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300187, '水煮玉米', '/upload/recipe-cover/import/placeholder.png', '水煮玉米是一道家常快手菜，口感清甜软糯。新鲜玉米带皮煮制，保留原香，加入盐和糖更能提味。它富含膳食纤维、维生素与碳水化合物，能为身体提供饱足感。做法极其简单，新手也能轻松上手，从准备到上桌只需大约 15 分钟。', 2, 108.00, 15, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300188, '水煮肉片', '/upload/recipe-cover/import/placeholder.png', '水煮肉片是一道麻辣鲜香、肉片滑嫩、配菜爽脆的经典川菜，极其适合下饭。猪里脊提供优质蛋白质，搭配豆芽等蔬菜，营养均衡。做法稍显繁琐，尤其需要耐心腌制肉片和制作刀口辣椒，新手大约需要 1 至 2 小时完成。', 5, 361.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300189, '水煮蛋', '/upload/recipe-cover/import/r300189.png', '水煮蛋，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300190, '水煮鱼', '/upload/recipe-cover/import/placeholder.png', '水煮鱼是一道麻辣鲜香、鱼肉嫩滑的经典川菜。巴沙鱼富含优质蛋白且脂肪含量低，搭配时令蔬菜营养均衡。做法中等难度，对新手有一定挑战，但按步骤操作也能成功。预计制作时长约 2 小时。', 4, 248.00, 30, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300191, '汤面', '/upload/recipe-cover/import/placeholder.png', '汤面是一道自由搭配的家常主食，汤汁清爽，面条软滑，兼容各种荤素食材，味道可鲜可淡。它富含碳水化合物和优质蛋白质，搭配蔬菜还能补充维生素与膳食纤维，营养均衡又饱腹。做法非常简单，无需厨艺基础，新手也能轻松驾驭。从准备食材到出锅，一般约需 30 分钟。', 2, 565.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300192, '河南蒸面条', '/upload/recipe-cover/import/r300192.png', '河南蒸面条是源自河南的家常小吃，面条先蒸后炒再蒸，油润入味，口感劲道爽滑。五花肉和蒜薹提供丰富的蛋白质和膳食纤维，搭配主食带来均衡营养。制作步骤稍多一些，但对新手而言只要按顺序操作就能成功。从备料到出锅，总共约需 40 分钟。', 4, 3066.00, 40, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300193, '油泼辣子', '/upload/recipe-cover/import/r300193.jpg', '一道香辣扑鼻的陕西风味调味料，红油润泽，芝麻蒜香交织，入口辣而不燥、回味绵长。辣椒富含维生素 C 与辣椒素，能增进食欲、暖身驱寒。制作过程需掌握油温，对新手稍有挑战，但按部就班即可成功。全程约 10 分钟完成，是家常拌菜拌面的点睛之笔。', 3, 1854.00, 10, 1, 1112, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300194, '油渣大白菜', '/upload/recipe-cover/import/r300194.jpg', '油渣大白菜，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300195, '油焖大虾', '/upload/recipe-cover/import/r300195.jpg', '这道鲁菜经典以咸甜交融的酱汁包裹整虾，成菜红亮油润，虾肉紧实弹嫩。虾本身富含优质蛋白与虾青素，脂肪含量低，是补充营养又不易增加负担的食材。制作时需要炼葱油、剪虾、焖烧、收汁，对火候和调味把握有一定要求，更适合有基础的厨友尝试，全程大约需要 40 分钟。', 4, 584.00, 40, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300196, '油酥', '/upload/recipe-cover/import/placeholder.png', '这是一道中式面点配料，常用于烙饼，能让成品层次分明、外酥里软。主要提供碳水化合物和脂肪，为身体补充能量。做法十分简单，新手友好，预计只需 3 分钟就能调好。', 2, 111.00, 3, 1, 1112, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300197, '油醋爆蛋', '/upload/recipe-cover/import/placeholder.png', '这是一道湘味十足的家常快手下饭菜，酸辣鲜香，鸡蛋焦香蓬松裹满浓郁汤汁，十分开胃。鸡蛋提供优质蛋白质和卵磷脂，搭配香醋更有助于促进食欲。做法极其简单，新手友好，从准备到出锅仅需大约十分钟。', 2, 471.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300198, '泡椒鸡杂面', '/upload/recipe-cover/import/placeholder.png', '泡椒鸡杂面，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300199, '泰国手标红茶', '/upload/recipe-cover/import/r300199.jpg', '这是一道源自泰国街头的经典奶茶，茶香浓郁，口感绵密顺滑，炼乳与牛奶带来香甜奶味。茶奶结合可提供少量蛋白质和钙，但含糖量较高，适宜作为消暑解渴的饮品。制作步骤简单，但需反复过滤茶汤并等待长时间冷藏，整体耗时约 4 小时 20 分钟，对新手稍有耐心即可完成。', 3, 185.00, 20, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300200, '洋葱炒猪肉', '/upload/recipe-cover/import/placeholder.png', '这是一道家常风味小炒，咸中带甜，酱香浓郁，洋葱炒软后滋味温和，搭配嫩滑猪肉片非常下饭。猪肉提供优质蛋白质和 B 族维生素，洋葱含膳食纤维和多种抗氧化物，开胃助消化。操作简单，新手也能轻松上手，预计制作时长仅需 15 分钟。', 3, 979.00, 15, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300201, '洋葱炒鸡蛋', '/upload/recipe-cover/import/r300201.jpeg', '洋葱炒鸡蛋是一道咸香适口、葱香浓郁的家常菜肴，鸡蛋嫩滑，洋葱清甜，属于国民下饭菜。鸡蛋富含优质蛋白质和多种维生素，洋葱含有膳食纤维和抗氧化物质，是一道营养均衡的快手菜。这道菜操作极其简单，对新手非常友好，从备料到出锅只需约 5 分钟。', 2, 562.00, 5, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300202, '活珠子/凤凰蛋', '/upload/recipe-cover/import/placeholder.png', '活珠子/凤凰蛋，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300203, '浇汁西兰花', '/upload/recipe-cover/import/r300203.jpg', '浇汁西兰花，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1113, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300204, '浓香整块鸡汤面', '/upload/recipe-cover/import/r300204.png', '浓香整块鸡汤面，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300205, '海带结', '/upload/recipe-cover/import/placeholder.png', '海带结，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1108, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300206, '海边落日', '/upload/recipe-cover/import/r300206.jpg', '这款鸡尾酒色彩层次分明，底部红石榴糖浆似晚霞，中间橙汁透亮，上层蓝橙酒液如海水，整体呈现海边落日的意境，喝起来酸甜清爽，带朗姆酒香。橙汁和柠檬汁含少量维生素 C，酒精能帮助放松。调酒步骤不复杂，但倒液沿搅拌棒做出分层需要一点耐心，新手跟着做也能成功，准备加调制大约一刻钟搞定。', 3, 173.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300207, '淄博烧烤', '/upload/recipe-cover/import/r300207.jpg', '这是一道山东淄博特色烧烤，小饼卷肉配大葱的吃法风味独特，肉香、酱香与葱香交融，口感层次丰富。五花肉富含优质蛋白质和脂肪，大葱提供膳食纤维，搭配小饼能快速补充能量。制作需要控制炭火火候和翻烤技巧，对新手稍具挑战，全程约 40 分钟即可完成。', 4, 650.00, 40, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300208, '清炒春菜', '/upload/recipe-cover/import/r300208.jpg', '清炒春菜，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300209, '清炒毛白菜', '/upload/recipe-cover/import/r300209.jpg', '清炒毛白菜，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300210, '清炒油麦菜', '/upload/recipe-cover/import/r300210.jpg', '清炒油麦菜，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300211, '清炒花菜', '/upload/recipe-cover/import/placeholder.png', '一道常见的家常素菜，口感脆嫩爽口。富含维生素 C 和膳食纤维。做法简单快捷，一般初学者仅需 15 分钟即可完成。', 2, 211.00, 15, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300212, '清炒莴笋片', '/upload/recipe-cover/import/r300212.jpg', '清炒莴笋片，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300213, '清炒菜心', '/upload/recipe-cover/import/r300213.jpg', '清炒菜心，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300214, '清炒西兰花', '/upload/recipe-cover/import/r300214.jpg', '清炒西兰花，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300215, '清炒青菜', '/upload/recipe-cover/import/r300215.jpg', '清炒青菜，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300216, '清蒸南瓜', '/upload/recipe-cover/import/placeholder.png', '一道原汁原味的家常蒸菜，最大程度保留南瓜的天然甜味与营养，口感软糯香甜，既可当甜点也可作主食。南瓜富含β-胡萝卜素和膳食纤维，有益视力与肠胃健康。制作极其简单，新手也能轻松搞定，从切配到出锅仅需 15-20 分钟。', 1, 80.00, 20, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300217, '清蒸生蚝', '/upload/recipe-cover/import/placeholder.png', '清蒸生蚝是一道原汁原味的沿海家常菜，蚝肉鲜嫩多汁，带着淡淡的海水咸香，蒜蓉与姜丝激发出清甜口感。生蚝富含优质蛋白和锌元素，能帮助提升免疫力。操作不算复杂，但掀开滚烫锅盖和处理蚝壳需要稍加小心，新手也能顺利完成。从刷洗到出锅，大约只需二十分钟。', 3, 184.00, 30, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300218, '清蒸鲈鱼', '/upload/recipe-cover/import/r300218.jpg', '清蒸鲈鱼是一道粤式经典蒸菜，鱼肉细嫩爽滑，味道清淡鲜美，能最大程度保留鲈鱼的原汁原味。鲈鱼富含优质蛋白和 DHA，营养丰富且易于消化。这道菜操作简单，对新手非常友好，从备料到出锅大约只需三十分钟。', 3, 385.00, 30, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300219, '清蒸鳜鱼', '/upload/recipe-cover/import/r300219.jpg', '清蒸鳜鱼肉质细嫩，鲜甜本味突出，是讲究原汁原味的家常河鲜做法。鳜鱼富含优质蛋白和多种微量元素，易于消化吸收。处理时需小心鱼鳍，但整体步骤不复杂，新手稍加注意也能胜任。从备料到出锅，大约只需半小时。', 3, 359.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300220, '温泉蛋', '/upload/recipe-cover/import/placeholder.png', '温泉蛋源自日本，蛋白呈半流动凝乳状，蛋黄却温润凝固，口感滑嫩细腻，与溏心蛋恰好相反。鸡蛋富含优质蛋白、卵磷脂和多种维生素，营养十分全面。制作时需要借助温度计将水温控制在 70℃，虽然对温度稍有要求，但步骤简单，耐心等待约半小时便能完成。佐以昆布酱油和葱花，鲜香清爽，是一道轻松上手的小食。', 3, 72.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300221, '湖南家常红烧肉', '/upload/recipe-cover/import/r300221.jpeg', '湖南家常红烧肉是一道湘味浓郁的家常菜，五花肉经慢炖后肥而不腻、入口软糯，咸香中带着微辣回甘。富含优质蛋白和脂肪，能为身体提供充足能量。制作需要一些耐心，对新手有一定挑战，但按步骤操作不难掌握，预计全程约 1 小时。', 3, 1348.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300222, '湘祁米夫鸭', '/upload/recipe-cover/import/r300222.jpg', '湖南两祁地区传统特色菜，鸭肉煸炒后裹上混合米粉蒸制，口感软糯，咸香入味，回味悠长。鸭肉富含优质蛋白质和 B 族维生素，搭配米粉提供能量，营养均衡。制作需先煸炒再高压蒸制，稍有难度，适合有一定烹饪基础的朋友。从备料到出锅大约需要 1 小时，若选用老鸭需延长蒸制时间。', 4, 1332.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300223, '溏心蛋', '/upload/recipe-cover/import/placeholder.png', '这是一道用普通电锅就能轻松做出的家常蛋料理，蛋黄呈现流动的溏心状态，口感嫩滑香醇。每颗鸡蛋提供约 6 克优质蛋白质，尤其适合健身人群补充营养。制作过程简单明了，只要掌握好加热和静置的时间，新手也能快速上手，全程仅需 大约 15 分钟。', 3, 72.00, 15, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300224, '澳门湿版免治牛肉饭', '/upload/recipe-cover/import/r300224.jpg', '这是一道经典的澳门葡式风味快餐，牛肉碎嫩滑咸香，裹着浓郁酱汁和半熟蛋液，拌入米饭后口感油润诱人。牛肉末提供优质蛋白质，搭配鸡蛋和洋葱，营养均衡管饱。操作步骤简单易上手，特别适合新手尝试，从备料到出锅大约只需 30 分钟。', 2, 1011.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300225, '火腿饭团', '/upload/recipe-cover/import/r300225.png', '一道简单快手的日式风味饭团，咸香火腿搭配沙拉酱与海苔，口感丰富饱腹。富含碳水化合物、蛋白质和维生素，能快速补充能量。制作难度极低，新手也能轻松上手，从煮饭到完成大约只需 1 小时。', 4, 665.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300226, '炒凉粉', '/upload/recipe-cover/import/r300226.jpg', '炒凉粉是一道山西、陕西地区的特色小吃，入口滑嫩，咸香微辣，带着蒜香和酱香。凉粉主要由淀粉制成，能提供丰富的碳水化合物，快速补充能量。烹饪难度适中，适合有一定基础的新手尝试，全程制作大约需要 15 分钟。', 3, 567.00, 15, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300227, '炒年糕', '/upload/recipe-cover/import/placeholder.png', '这是一道闽南风味的主食，年糕软糯弹牙，带着葱油的焦香，家常又饱腹。以米粉制成的年糕提供充足碳水化合物，搭配鸡蛋和青菜能补充蛋白质与维生素，营养均衡。做法简单，对新手友好，从准备到出锅大约需要 30 分钟。', 3, 960.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300228, '炒意大利面', '/upload/recipe-cover/import/r300228.jpg', '这道炒意大利面软糯爽口，搭配肥牛和酱料，酱香浓郁，是带有西式风味的家常主食。富含碳水化合物与蛋白质，能快速补充能量。做法简单，新手也能轻松掌握，全程大约需要 30 分钟。', 3, 406.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300229, '炒方便面', '/upload/recipe-cover/import/r300229.png', '这道炒方便面口感 Q 弹筋道，咸香入味，是一道改良自传统煮面的家常快手主食。搭配鸡蛋和火腿肠，丰富了蛋白质和能量来源。做法简单，只需注意冷水冲面保持口感，新手也能轻松完成，全程大约 15 分钟即可出锅。', 2, 789.00, 15, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300230, '炒河粉', '/upload/recipe-cover/import/placeholder.png', '炒河粉是一道流行于广东地区的经典小吃，讲究镬气十足、干香爽滑，河粉软韧透亮，搭配肉丝、豆芽和黄瓜丝，口感层次丰富。主要提供碳水化合物和蛋白质，蔬菜的加入也补充了维生素与膳食纤维。按本菜谱操作难度适中，即便新手只要备齐材料也能尝试，整个制作过程约需 30 分钟即可端上餐桌。', 4, 822.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300231, '炒滑蛋', '/upload/recipe-cover/import/r300231.jpg', '炒滑蛋是一道口感嫩滑、蛋香浓郁的经典家常菜，带有淡淡的奶香。鸡蛋富含优质蛋白质和多种维生素，营养丰富，易于吸收。做法非常友好，新手也能轻松掌握，从备料到出锅只需约 5 分钟，是忙碌时快速补充能量的理想选择。', 1, 391.00, 5, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300232, '炒茄子', '/upload/recipe-cover/import/placeholder.png', '这道家常炒茄子软嫩入味，酱香浓郁，加八角后风味更足。茄子富含膳食纤维、维生素 P 和钾元素，有助于保护心血管。做法简单，对新手友好，全程大火快炒，从备料到出锅大约二十分钟即可完成。', 3, 610.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300233, '炒青菜', '/upload/recipe-cover/import/placeholder.png', '这是一道清爽可口的家常素菜，口感脆嫩、咸鲜回甘。青菜富含维生素与膳食纤维，有助于促进消化。做法非常简单，零基础也能轻松驾驭，从备菜到出锅大约只需 10 分钟。', 2, 152.00, 10, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300234, '炒馍', '/upload/recipe-cover/import/placeholder.png', '炒馍是一道咸香酥脆的家常面食，属于北方风味。馒头丁炒至金黄，外脆里软，孜然与五香粉的加入让风味更加浓郁。可搭配鸡蛋提供蛋白质，搭配小葱增添清香，营养均衡。制作难度适中，新手也能很快上手，预计 大约 15 分钟即可出锅享用。', 3, 767.00, 15, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300235, '炸串酱料', '/upload/recipe-cover/import/placeholder.png', '这款万能炸串酱料香辣浓郁、鲜咸适口，属于街头风味风格。主要提供脂肪和香辛料带来的芳香物质，能增进食欲。制作非常简单，对新手毫无压力，全程只需大约 10 分钟即可完成。', 2, 1826.00, 10, 1, 1112, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300236, '炸肉肠', '/upload/recipe-cover/import/placeholder.png', '炸肉肠，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1105, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300237, '炸薯条', '/upload/recipe-cover/import/r300237.jpg', '炸薯条外酥里软，金黄咸香，属于广受欢迎的快餐小食。土豆提供碳水化合物和膳食纤维，但油炸或空气炸制后热量较高。使用半成品薯条和空气炸锅，操作简单，新手也能轻松上手。从预热到出锅，大约需要 25 分钟。', 2, 1132.00, 25, 1, 1107, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300238, '炸酱面', '/upload/recipe-cover/import/placeholder.png', '炸酱面是一道酱香浓郁、面条劲道的传统北京家常面食，搭配清爽菜码，咸甜适口。主要营养来自瘦肉蛋白质和蔬菜维生素，能为人体提供充足能量。做法对新手友好，预计制作时长约 30 分钟，熟练掌握后可通过备菜与炒酱并行进一步缩短时间。', 3, 1272.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300239, '炸鲜奶', '/upload/recipe-cover/import/r300239.jpg', '炸鲜奶是一道外壳酥脆、内馅柔软的甜点。制作本身不难，但奶糊必须充分加热并冷藏定型，否则切块和油炸时容易散开。实际操作约需 30 分钟，另需至少 2 小时冷藏定型。', 3, 1100.00, 30, 1, 1109, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300240, '炸鸡排', '/upload/recipe-cover/import/r300240.png', '炸鸡排，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1105, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300241, '炸鸡排（普通鸡排）', '/upload/recipe-cover/import/placeholder.png', '炸鸡排（普通鸡排），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1105, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300242, '炸鸡排（调理鸡排）', '/upload/recipe-cover/import/placeholder.png', '炸鸡排（调理鸡排），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1105, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300243, '炸鸡腿', '/upload/recipe-cover/import/r300243.png', '炸鸡腿，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1105, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300244, '炸鸡腿时蔬面', '/upload/recipe-cover/import/r300244.png', '炸鸡腿时蔬面，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300245, '烙饼', '/upload/recipe-cover/import/r300245.jpg', '这道家常烙饼层次分明，外皮酥脆内里柔软，带着油酥的焦香，是北方餐桌上常见的主食。主要提供碳水化合物和能量，适合搭配菜肴一起食用。制作需要一点手法，尤其卷酥和擀饼环节，但跟着步骤操作并不难，新手也能掌握。从和面到烙好，大约需要 1 个小时。', 4, 1185.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300246, '烤箱版巴斯克芝士蛋糕', '/upload/recipe-cover/import/r300246.jpg', '巴斯克芝士蛋糕是一道口感浓郁绵密、表面焦香内部湿润的甜品，属于西班牙巴斯克地区的经典风味。主要原料为奶油奶酪和鸡蛋，富含优质蛋白质和钙质。制作过程非常简单，新手也能轻松驾驭。从准备到出炉仅需约 30 分钟，但建议冷藏过夜后食用，总耗时约 8 小时以上。', 2, 266.00, 30, 1, 1109, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300247, '烤肠', '/upload/recipe-cover/import/r300247.png', '烤肠，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1114, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300248, '烤茄子', '/upload/recipe-cover/import/r300248.jpg', '烤茄子香气浓郁、外焦里嫩，孜然和蒜蓉的辛香完美融入软糯的茄肉，是街头烧烤风味在家轻松复刻的菜品。茄子富含维生素 P 和花青素，有助于保护心血管、抗氧化。做法需要用到烤箱，但步骤清晰，新手也能在大约半 小时完成，很适合作为家庭聚餐的快手下饭菜。', 3, 145.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300249, '烤蛋挞', '/upload/recipe-cover/import/r300249.png', '烤蛋挞是一款经典的中式甜品，外皮酥脆、内馅嫩滑，奶香浓郁。富含蛋白质、钙质和多种维生素，能提供丰富能量。制作过程十分简单，新手也能轻松上手，而且半成品可冷冻保存，随吃随取。从准备到出炉，大约需要 1 小时。', 4, 169.00, 30, 1, 1109, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300250, '烤鱼', '/upload/recipe-cover/import/r300250.jpg', '这道川味烤鱼麻辣鲜香，鱼肉外焦里嫩，配菜吸饱汤汁后格外下饭。草鱼富含优质蛋白，搭配多种蔬菜，营养均衡。做法看似复杂，但跟着步骤走其实不难，适合想挑战硬菜的新手。从备料到上桌大约需要一小时。', 4, 2152.00, 30, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300251, '烤鸡翅', '/upload/recipe-cover/import/placeholder.png', '腌制入味的鸡中翅经高温烘烤，外皮微焦、内里鲜嫩多汁，带有黑胡椒和酱油的咸香。富含优质蛋白质和胶原蛋白。难度适中，新手也能轻松上手，从准备到出炉大约需要 1 小时。还可按喜好添加蜂蜜或五香粉增添风味。', 3, 187.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300252, '热奶茶', '/upload/recipe-cover/import/r300252.png', '热奶茶，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300253, '热干面', '/upload/recipe-cover/import/placeholder.png', '热干面是武汉最具代表性的小吃之一，属于鄂菜系。碱水面条筋道爽滑，裹满浓稠的芝麻酱，搭配酸豆角、萝卜干和肉末，咸香微辣，滋味醇厚。主要提供碳水化合物和蛋白质，芝麻酱也富含钙质。制作简单快捷，新手也能轻松上手，从煮面到拌好大约只需十几分钟。', 3, 1341.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300254, '煎烤羊排', '/upload/recipe-cover/import/placeholder.png', '一道外酥里嫩、香气浓郁的料理，先以香料炖煮再煎出金黄脆壳，风味浓郁不腻，是家常宴客两相宜的硬菜。羊肉富含优质蛋白和铁、锌等矿物质，有助于温补气血。做法步骤稍多，但只要按流程走，新手也能拿下；使用高压锅全程约 1 小时，普通锅约 1.5 小时。', 4, 1850.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300255, '煎饺', '/upload/recipe-cover/import/placeholder.png', '煎饺是一道底部金黄酥脆、内馅鲜嫩多汁的家常面点，常见于北方餐桌。搭配速冻水饺制作，富含碳水化合物和蛋白质，简单快手。预估难度二星，对新手非常友好，总共约需 15 分钟就能端上桌。', 2, 769.00, 15, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300256, '照烧鸡腿饭', '/upload/recipe-cover/import/placeholder.png', '照烧鸡腿饭是一道甜咸适口的下饭菜，鸡腿煎得焦香后融入浓郁酱汁，口感嫩滑入味。鸡腿肉富含优质蛋白，搭配西兰花和胡萝卜能补充膳食纤维与维生素。制作稍需一点去骨技巧，但整体不复杂，新手跟着步骤也能成功。从备料到出锅，大约 30 分钟就能端上餐桌。', 4, 1670.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300257, '煮泡面加蛋', '/upload/recipe-cover/import/placeholder.png', '煮泡面加蛋是一道便捷的快手主食，口感顺滑，汤味浓郁，适合随时填饱肚子。主要提供碳水化合物和蛋白质，能快速补充能量。做法极其简单，只需烧水、煮面、打入鸡蛋煮熟，新手也能轻松掌握，全程大约 10 分钟即可完成。', 1, 550.00, 10, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300258, '煮锅蒸米饭', '/upload/recipe-cover/import/r300258.jpeg', '这是一道朴实无华的家常主食，用普通煮锅就能做出软糯适口的米饭。白米饭主要提供碳水化合物，为身体快速补充能量。做法极为简单，新手只需全程关注火候即可轻松掌握，从下米到出锅大约需要 25 分钟。', 2, 418.00, 25, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300259, '燕麦鸡蛋饼', '/upload/recipe-cover/import/placeholder.png', '燕麦鸡蛋饼是一道快手营养早餐，口感软嫩，带有燕麦的谷物香气与蛋奶的醇厚，属于家常简约风格。富含蛋白质、碳水化合物和膳食纤维，能为身体提供充足能量，尤其适合健身人士和工作日早晨。做法简单，对新手友好，从备料到出锅通常只需十几分钟。', 2, 535.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300260, '爆炒牛肉', '/upload/recipe-cover/import/placeholder.png', '爆炒牛肉，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300261, '牛奶燕麦', '/upload/recipe-cover/import/placeholder.png', '一份高蛋白、高纤维的便捷营养早餐，将牛奶的滑润、燕麦的谷香与煎蛋的嫩脆巧妙结合，入口温热柔和、易于消化，饱腹感强。制作过程简单直接，对新手极为友好，全程约三分钟即可完成，搭配蔬果更添清爽。', 1, 421.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300262, '牛排', '/upload/recipe-cover/import/r300262.jpg', '这是一道经典的西式煎牛排，焦香外壳包裹着鲜嫩多汁的肉心，搭配黄油、大蒜和香草，风味浓郁。富含优质蛋白质、油脂及铁、锌等矿物质。烹饪流程对新手较为友好，但掌握火候仍需一些练习，全程 15-30 分钟即可完成。', 4, 1605.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300263, '牛油果拉西', '/upload/recipe-cover/import/placeholder.png', '这是一款融合了印度传统酸奶饮品“拉西”的创新饮品，口感绵密顺滑、清甜不腻，特别适合作为早餐或午后提神饮品。牛油果富含单不饱和脂肪酸与膳食纤维，搭配酸奶的优质蛋白和益生菌，一杯便能提供持久饱腹感。制作极为简单，新手也能零失败，从备料到享用只需 大约 5 分钟。', 1, 392.00, 5, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300264, '牛油火锅底料', '/upload/recipe-cover/import/placeholder.png', '这道重庆火锅底料以大量牛油为基底，糅合糍粑辣椒和多种香辛料，熬出的底料麻辣醇厚、香气浓烈，是涮烫毛肚、鸭肠等食材的灵魂。牛油和猪油提供了丰富能量，辣椒与花椒能温中散寒、促进食欲，但油脂含量较高，宜节制食用。制作过程需精准控制油温和翻炒火候，对新手有一定挑战，从备料到完成约需 1 小时。', 5, 585.00, 30, 1, 1107, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300265, '牛肉盒', '/upload/recipe-cover/import/r300265.png', '牛肉盒，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300266, '特色热干面', '/upload/recipe-cover/import/r300266.png', '特色热干面，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1113, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300267, '特色鸡汤馄饨', '/upload/recipe-cover/import/r300267.png', '特色鸡汤馄饨，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300268, '猪油拌饭', '/upload/recipe-cover/import/placeholder.png', '这是一道充满南方家常气息的简单拌饭，米粒被融化的猪油包裹，透着酱油的咸鲜和葱花的清香，是许多孩子食欲不振时的安心之选。主要提供快速碳水与脂肪能量，但胆固醇较高，不宜常吃。制作毫无门槛，哪怕完全不会做饭也能轻松完成，煮好的米饭只要几分钟就能拌出一碗香喷喷的主食。', 1, 420.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300269, '猪皮冻', '/upload/recipe-cover/import/r300269.jpg', '猪皮冻是北方年夜饭常见的传统凉菜，晶莹剔透，口感滑嫩 Q 弹，特别适合下酒。猪皮富含胶原蛋白，有美容养颜的作用。这道菜难度稍高，需要耐心处理猪皮去腥和长时间熬煮，预计制作时长约 24 小时。', 3, 1630.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300270, '猪肉烩酸菜', '/upload/recipe-cover/import/placeholder.png', '猪肉烩酸菜是一道北方家常炖菜，酸香浓郁，五花肉软烂，排骨入味。主要提供蛋白质，酸菜也带来乳酸菌等有益成分。做法步骤清晰，新手也能按部就班完成，但需耐心慢炖，从头到尾大约需要 3 小时。', 5, 1817.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300271, '猴头菇山药玉米糊', '/upload/recipe-cover/import/placeholder.png', '猴头菇山药玉米糊，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300272, '玉米排骨汤', '/upload/recipe-cover/import/r300272.jpeg', '玉米排骨汤是一道鲜美清甜的家常汤品，排骨软烂，玉米和胡萝卜带来自然甜味。富含蛋白质、维生素和膳食纤维，营养均衡。做法简单，对新手友好，只需将排骨焯水煸香后慢炖约一小时即可完成。从备菜到出锅大约需要一个半小时。', 3, 1724.00, 30, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300273, '玛格丽特饼干', '/upload/recipe-cover/import/r300273.jpg', '玛格丽特饼干口感酥松，黄油香气浓郁，是一款经典的西式小甜点。它主要由蛋黄、黄油和面粉制成，含有丰富的碳水化合物与脂肪，能快速补充能量。制作难度适中，从准备到出炉大约需要 45 分钟，新手也能轻松上手。', 3, 863.00, 45, 1, 1109, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300274, '现炸大油条', '/upload/recipe-cover/import/r300274.png', '现炸大油条，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300275, '现熬豆粥', '/upload/recipe-cover/import/r300275.png', '现熬豆粥，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300276, '珍珠糯米肉丸', '/upload/recipe-cover/import/placeholder.png', '珍珠糯米肉丸，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300277, '甜辣烤全翅', '/upload/recipe-cover/import/placeholder.png', '这道甜辣烤全翅利用空气炸锅烹制，外皮微焦、内里多汁，甜中带辣的风味很受欢迎。鸡肉富含优质蛋白质，用空气炸代替油炸大幅减少了油脂，吃起来负担更轻。制作流程清晰明了，只需提前腌制并中途翻面一次，对新手也比较友好。从处理食材到出锅大约需要 3 个小时，大部分是静置腌制的时间，实际操作并不繁琐。', 3, 775.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300278, '甜辣辣年糕烧鸡', '/upload/recipe-cover/import/placeholder.png', '甜辣辣年糕烧鸡，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1111, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300279, '生汆丸子汤', '/upload/recipe-cover/import/placeholder.png', '生汆丸子汤口感鲜嫩弹滑，是一道原汁原味的家常汤品。猪肉提供优质蛋白质，搭配木耳、黄花等食材，营养较为均衡。制作中需要自己剁肉并掌握挤丸子的火候，稍有些门槛，更适合有一定基础的厨艺爱好者。从备料到上桌大约需要 1 小时。', 4, 857.00, 30, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300280, '生炒上海青', '/upload/recipe-cover/import/r300280.jpg', '生炒上海青，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300281, '生炸大鸡腿', '/upload/recipe-cover/import/r300281.png', '生炸大鸡腿，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1105, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300282, '田螺酿', '/upload/recipe-cover/import/r300282.jpeg', '田螺酿是阳朔“十八酿”之首，螺肉韧而紧致、猪肉嫩滑，紫苏薄荷清香扑鼻，曾登上《舌尖上的中国 2》。富含蛋白质和多种微量元素，螺肉与猪肉搭配营养互补。这道菜步骤稍多，对新手有一定挑战，需提前半天让田螺吐沙，正式制作约 40 分钟，适合节假日全家一起动手。', 4, 533.00, 40, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300283, '电饭煲三文鱼炊饭', '/upload/recipe-cover/import/r300283.webp', '这是一道融合日式炊饭做法的家常料理，米饭吸饱牛油和三文鱼的香气，口感浓郁鲜香。三文鱼提供优质蛋白和不饱和脂肪酸，搭配菌菇更添膳食纤维。操作极其简单，只需用电饭煲一键完成，从备料到出锅大约 45 分钟，非常适合新手尝试。', 2, 889.00, 45, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300284, '电饭煲蒸米饭', '/upload/recipe-cover/import/placeholder.png', '一道家喻户晓的基础主食，米香纯粹、口感软糯，因水量调节可偏硬或偏润。富含碳水化合物，能快速补充能量，适合搭配各类菜肴。操作极其简单，新手也能轻松上手，从洗米到焖好大约需要四十分钟。', 1, 442.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300285, '番茄牛肉蛋花汤', '/upload/recipe-cover/import/placeholder.png', '番茄牛肉蛋花汤是一道酸甜开胃的家常汤品，口感鲜嫩顺滑。牛肉富含优质蛋白和铁，番茄提供番茄红素和维生素 C，鸡蛋则补充卵磷脂。做法简单，新手也能轻松掌握，通常大约半 小时就能端上餐桌。', 3, 262.00, 30, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300286, '番茄红酱', '/upload/recipe-cover/import/placeholder.png', '这款意式风味酱料香浓可口，蔬菜与牛肉的搭配带来丰富口感。它富含蛋白质和多种维生素，营养均衡。制作过程稍有繁琐，需要一些烹饪基础，例如炒出颗粒感的牛肉和控火慢煮。从备料到完成约需一小时，一次可多做一些冷冻保存，随取随用十分方便。', 4, 1955.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300287, '番茄菌菇肉丸', '/upload/recipe-cover/import/placeholder.png', '番茄菌菇肉丸，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300288, '番茄鸡蛋面', '/upload/recipe-cover/import/r300288.jpg', '番茄鸡蛋面，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300289, '瘦肉土豆片', '/upload/recipe-cover/import/r300289.jpg', '一道快手家常小炒，肉片滑嫩，土豆片软韧入味，带有蒜苗清香，属于典型的家常菜风格。瘦肉富含优质蛋白质和铁质，土豆提供碳水化合物和膳食纤维，搭配均衡。制作流程简单明了，需注意刀工和火候，适合有一定基础的新手尝试。从备料到出锅，预计 大约 1 小时即可完成。', 3, 585.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300290, '白切鸡', '/upload/recipe-cover/import/r300290.png', '白切鸡，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300291, '白灼菜心', '/upload/recipe-cover/import/r300291.jpg', '这道经典粤菜采用白灼技法，沸水快焯保留菜心的清甜与脆嫩，根茎尤为爽口，味道清淡鲜美。富含维生素 C 和膳食纤维，低脂低热量，适合追求健康饮食的人群。做法非常简单，预估难度仅两星，一般初学者只需 15 分钟即可完成，是快速补充绿叶蔬菜的理想选择。', 2, 86.00, 15, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300292, '白灼虾', '/upload/recipe-cover/import/r300292.webp', '白灼虾是一道粤式经典快手菜，虾肉鲜甜弹嫩，原汁原味。虾本身富含优质蛋白和多种矿物质，搭配蘸料开胃不油腻。做法简单容错率高，对新手非常友好，从备料到出锅大约只需 15 分钟。', 2, 519.00, 15, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300293, '白灼虾（8只）', '/upload/recipe-cover/import/placeholder.png', '白灼虾（8只），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1113, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300294, '白米粥', '/upload/recipe-cover/import/r300294.png', '白米粥，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300295, '白菜炖豆腐', '/upload/recipe-cover/import/r300295.jpg', '白菜炖豆腐，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1111, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300296, '白菜猪肉炖粉条', '/upload/recipe-cover/import/placeholder.png', '猪肉白菜炖粉条是东北地区经典的家常炖菜，汤汁浓郁咸鲜，五花肉软烂、粉条吸饱肉香后滑韧入味，白菜清甜解腻。整道菜荤素搭配均衡，能提供蛋白质、维生素和碳水化合物，营养饱腹。制作过程需要一些耐心，特别是粉条处理和炖煮火候，对新手有一定挑战，但按步骤操作不易失败，从头到尾大约需要 45 分钟即可上桌。', 3, 1880.00, 45, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300297, '百叶包肉', '/upload/recipe-cover/import/placeholder.png', '百叶包肉，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300298, '百香果橙子特调', '/upload/recipe-cover/import/r300298.jpg', '这是一道酸甜清爽的夏日饮品，融合了百香果的热带果香与橙子的鲜甜，搭配茉莉绿茶或苏打气泡水，口感层次分明，冰爽解腻。富含维生素 C，有助增强免疫力和滋润肌肤。包含腌制、泡茶、榨汁等步骤，操作略多但难度适中，新手也能尝试。需提前一天腌制百香果，总耗时约 24 小时，实际动手时间仅 大约 30 分钟。', 3, 173.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300299, '皮蛋瘦肉粥', '/upload/recipe-cover/import/placeholder.png', '皮蛋瘦肉粥是广东经典的家常粥品，粥底绵密顺滑，皮蛋的醇香与瘦肉的鲜嫩融合，口感温润鲜美。它富含碳水化合物和优质蛋白质，搭配蔬菜，营养较为均衡，易于消化吸收。这道粥步骤虽多，但操作直观，新手跟着流程也能顺利完成，预计制作时长约 1.5 小时，借助电饭锅的预约或保温功能，作为早餐尤为方便。', 3, 776.00, 30, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300300, '皮蛋豆腐', '/upload/recipe-cover/import/placeholder.png', '皮蛋豆腐是一道清爽开胃的凉拌家常菜，松花蛋 Q 弹滑嫩，嫩豆腐入口即化，咸香微酸的口味特别下饭。豆腐富含优质植物蛋白和钙，皮蛋则提供铁、维生素 A 等营养素，搭配食用易于消化吸收。制作过程几乎零门槛，新手也能轻松完成，从备料到上桌仅需 大约 5 分钟。', 1, 566.00, 5, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300301, '砂糖椰子冰沙', '/upload/recipe-cover/import/r300301.jpg', '砂糖椰子冰沙是一道极具热带风情的快手冷饮，清甜的椰香融合粗粒黄糖的焦香，口感绵密冰爽。椰子水富含天然电解质与矿物质，能快速补充水分，咖啡调糖增添碳水能量。制作门槛极低，只要提前将椰汁冻硬，敲打成沙即可，对新手毫无压力。从冷冻到出品需提前准备 10 小时以上，但动手操作仅需几分钟，很适合作为悠闲的午后冰品。', 1, 231.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300302, '砂锅三鲜豆腐', '/upload/recipe-cover/import/r300302.png', '砂锅三鲜豆腐，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1115, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300303, '砂锅原味鸡汤米线', '/upload/recipe-cover/import/r300303.png', '砂锅原味鸡汤米线，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1115, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300304, '砂锅木瓜', '/upload/recipe-cover/import/r300304.png', '砂锅木瓜，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1115, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
