INSERT INTO `recipe` VALUES (300327, '笋子鸡丁盖饭（包菜版）', '/upload/recipe-cover/import/placeholder.png', '笋子鸡丁盖饭（包菜版），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300328, '笋子鸡丁盖饭（菜苔版）', '/upload/recipe-cover/import/placeholder.png', '笋子鸡丁盖饭（菜苔版），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300329, '简易版炒糖色', '/upload/recipe-cover/import/placeholder.png', '糖色是中餐红烧类菜肴上色的关键技法，火候到位时能带来红亮光泽与独特的焦香风味。主要成分为糖，提供能量，但更多是调和菜肴色泽与口味。这道简易版炒糖色对火候控制有一定要求，新手需多加练习才能避免发苦或发甜，整体制作约需十分钟。', 4, 1028.00, 30, 1, 1112, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300330, '简易红烧肉', '/upload/recipe-cover/import/r300330.jpg', '这道家常美味色泽红润油亮，口感软糯，肥而不腻，酱香浓郁，搭配米饭特别过瘾。五花肉提供优质蛋白质和必需脂肪酸，加上鹌鹑蛋或豆皮，营养更全面。做法对新手相当友好，从备料到出锅大约需要 1.5 小时。', 3, 2775.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300331, '米粥', '/upload/recipe-cover/import/placeholder.png', '白粥清淡绵软，是家常必备的暖胃主食，米香纯粹，老少皆宜。富含碳水化合物和少量蛋白质，易于消化吸收，有补脾、和胃、清肺的食养之效。操作简单，只需掌握好火候和水量，初学者也能轻松完成，全程约需 25 分钟。', 2, 308.00, 25, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300332, '米饭', '/upload/recipe-cover/import/r300332.png', '米饭，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300333, '粉蒸肉', '/upload/recipe-cover/import/placeholder.png', '粉蒸肉是一道经典中式蒸菜，香味浓郁，口感软糯，属于广泛流传的家常风味。五花肉提供优质蛋白质和脂肪，搭配土豆等根茎蔬菜，营养均衡。此菜适合有一定烹饪经验的人士制作，从准备到完成大约需要 90 分钟。', 4, 1606.00, 90, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300334, '粗粮盒', '/upload/recipe-cover/import/r300334.png', '粗粮盒，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300335, '粢饭糕', '/upload/recipe-cover/import/r300335.png', '粢饭糕，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300336, '糍糕', '/upload/recipe-cover/import/placeholder.png', '糍糕，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300337, '糖拌西红柿', '/upload/recipe-cover/import/r300337.jpg', '这是一道适合夏季的家常凉菜，酸甜爽口，制作简便。西红柿富含维生素 C，开胃解腻。新手也能轻松完成，整个过程（包含冷藏）约 15 分钟即可上桌。', 2, 104.00, 15, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300338, '糖糕（红糖馅）', '/upload/recipe-cover/import/placeholder.png', '糖糕（红糖馅），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1105, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300339, '糖醋排骨', '/upload/recipe-cover/import/r300339.jpeg', '糖醋排骨是一道酸甜可口、外酥里嫩的传统名菜，广受欢迎。排骨富含优质蛋白和钙质，有较好的滋补效果。这道菜涉及焯水、油炸、炒糖色和收汁等多个步骤，对火候和调味有一定要求，不算特别适合新手，但按照优化后的流程操作成功率较高。预计制作时长为 大约 45 分钟。', 4, 1022.00, 45, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300340, '糖醋汁', '/upload/recipe-cover/import/placeholder.png', '这款调味汁酸甜可口，是中餐里糖醋菜肴的经典风味来源。调制简单、比例易记，新手也能轻松上手，从备料到完成约需 10 分钟。糖分能提供能量，醋香有助于开胃解腻，让家常菜瞬间变得有滋有味。', 2, 146.00, 10, 1, 1112, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300341, '糖醋里脊', '/upload/recipe-cover/import/placeholder.png', '糖醋里脊酸甜浓郁、外酥里嫩，是广受欢迎的家常风味，在多地域菜系中都很常见。猪里脊提供优质蛋白，但裹粉油炸和糖醋汁使整体热量偏高。制作时需要掌握腌制、复炸和调汁火候，对新手稍有挑战，建议提前备好料并一气呵成。从备料到出锅大约需要 45 分钟到 1 小时。', 4, 1573.00, 45, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300342, '糖醋鲤鱼', '/upload/recipe-cover/import/r300342.jpg', '糖醋鲤鱼是经典鲁菜，外酥里嫩、酸甜适口，鱼身炸至金黄浇上红亮糖醋汁，十分诱人。鱼肉富含优质蛋白和多种矿物质，易于消化吸收。这道菜对新手不太友好，难度中等偏上，需掌握改刀、挂糊和油炸火候。从备料到成菜大约需要 1 小时。', 4, 1011.00, 30, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300343, '糯米杂谷饭团（奥尔良鸡肉馅）', '/upload/recipe-cover/import/placeholder.png', '糯米杂谷饭团（奥尔良鸡肉馅），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300344, '素炒豆角', '/upload/recipe-cover/import/placeholder.png', '这是一道酱香浓郁的家常小炒，豆角软嫩入味，鲜辣下饭。富含膳食纤维和多种维生素，有助于促进消化。做法简单，新手也能轻松上手，从备菜到出锅大约 20 分钟。', 2, 107.00, 20, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300345, '素面', '/upload/recipe-cover/import/r300345.png', '素面，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300346, '紫菜蛋花汤', '/upload/recipe-cover/import/placeholder.png', '紫菜蛋花汤是一道清淡鲜美的家常汤品，属于中式简易汤菜。紫菜富含碘、钙和膳食纤维，鸡蛋提供优质蛋白质，二者搭配营养均衡。做法非常简单，对新手友好，从准备到出锅仅需约 20 分钟。', 2, 217.00, 20, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300347, '紫薯杂粮饭', '/upload/recipe-cover/import/placeholder.png', '紫薯杂粮饭，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300348, '红柚蛋糕', '/upload/recipe-cover/import/placeholder.png', '红柚蛋糕是一道用空气炸锅就能轻松完成的清新甜点，融合了红柚果粒的微酸果香与蛋糕的松软口感，适合作为单人份下午茶。鸡蛋和面粉提供蛋白质与碳水，红柚富含维生素 C，带来简单的基础营养。制作难度中等，关键在于分次搅拌成无颗粒的淡黄色面糊，新手只要耐心按步骤操作就能成功。从备料到出锅大约需要 35 分钟，想吃现烤甜点时不会占用太多时间。', 3, 622.00, 35, 1, 1109, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300349, '红烧冬瓜', '/upload/recipe-cover/import/r300349.jpeg', '红烧冬瓜是一道色泽红亮、香鲜味美的家常素菜，口感软糯入味，属于大众喜爱的中式烧菜。冬瓜本身富含水分、膳食纤维和维生素 C，具有清热解暑、利尿消肿的作用，搭配简单的调味料，营养又好消化。这道菜对初学者比较友好，操作步骤清晰，只需掌握好火候和调味，预计制作时长约 25 分钟。', 3, 519.00, 25, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300350, '红烧猪蹄', '/upload/recipe-cover/import/r300350.jpg', '红烧猪蹄是一道汤汁浓郁、肉质软糯的经典家常菜，咸香甜美，极为下饭。猪蹄富含胶原蛋白和蛋白质，营养丰富。这道菜对新手有一定挑战，但借助高压锅可以简化流程，有一定烹饪基础更易上手。从备料到完成大约需要 1 小时。', 4, 639.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300351, '红烧茄子', '/upload/recipe-cover/import/placeholder.png', '红烧茄子是一道咸香浓郁的家常下饭菜，软糯的茄块吸饱汤汁，搭配柿子椒和番茄，酸辣适口。茄子富含膳食纤维和维生素 P，炸过的茄块香而不腻。制作需要挂糊油炸并慢烧入味，步骤略多但对新手仍可尝试，专注细节就能成功。从备料到出锅大约需要 45 分钟。', 4, 547.00, 45, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300352, '红烧鱼', '/upload/recipe-cover/import/placeholder.png', '红烧鱼是一道家常风味浓郁的经典菜，咸鲜微甜，鱼肉嫩滑入味，属于大众喜爱的中式烧菜。鱼肉富含优质蛋白和不饱和脂肪酸，营养易吸收。制作时需要处理生鱼和油煎，步骤稍多，对新手有一定挑战，但跟着菜谱操作也能成功。从备料到出锅，大约需要 40 分钟。', 4, 570.00, 40, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300353, '红烧鱼块', '/upload/recipe-cover/import/r300353.png', '红烧鱼块，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1111, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300354, '红烧鱼头', '/upload/recipe-cover/import/placeholder.png', '红烧鱼头是一道经典的家常烧菜，鱼头胶质丰富，肉质滑嫩，汤汁咸鲜微辣，十分下饭。鱼头富含优质蛋白、卵磷脂和不饱和脂肪酸，对滋养皮肤和大脑有益。由于需要处理生鱼和剁骨，难度稍高，不建议完全零基础的新手独自操作，全程制作（含腌制）约需 2–2.5 小时。', 4, 333.00, 30, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300355, '红烧鲤鱼', '/upload/recipe-cover/import/placeholder.png', '红烧鲤鱼是一道家常鲁菜，鱼肉先炸后炖，外皮微韧，肉质鲜嫩，咸甜酱香中透着五花肉的醇厚，汤汁浓稠下饭。富含优质蛋白和钙、磷等矿物质，有助滋补。处理炸鱼和调味配比稍需耐心，但步骤清晰，新手跟着做也能完成。从备料到出锅预计 大约 1 小时。', 4, 1051.00, 30, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300356, '红烧鸡翅', '/upload/recipe-cover/import/placeholder.png', '红烧鸡翅是一道家常下饭菜，咸鲜带甜、色泽红亮，肉质嫩滑易脱骨。鸡翅富含优质蛋白质与胶原蛋白，营养好吸收。制作难度适中，新手按步骤操作也能顺利掌握，从备料到出锅大约需要 40 分钟。', 3, 1016.00, 40, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300357, '红芸豆拌饭', '/upload/recipe-cover/import/placeholder.png', '这道北印度家常菜是旁遮普邦和德里地区的传统美食，番茄洋葱汤汁浓郁辛香，炖煮后红芸豆软糯入味，与热米饭拌食温暖饱腹。豆子富含蛋白质、膳食纤维和多种微量元素，营养均衡。做法简单，初学者也能轻松上手，全程制作约 40 分钟，但干豆需提前浸泡 8 小时。浓郁的家常滋味，有妈妈的味道。', 3, 1842.00, 40, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300358, '红豆酒酿', '/upload/recipe-cover/import/placeholder.png', '红豆酒酿，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300359, '经典毛豆烧鸡', '/upload/recipe-cover/import/placeholder.png', '经典毛豆烧鸡，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300360, '罗宋汤', '/upload/recipe-cover/import/placeholder.png', '一道源自俄罗斯甜菜汤、在上海改良的海派家常汤品，以番茄和牛肉为主调，口感酸甜浓郁、醇厚鲜美。富含优质蛋白、番茄红素及多种维生素，营养均衡。制作简单，对初学者友好，全程预计 2–3 小时即可完成。', 4, 2006.00, 30, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300361, '羊排焖面', '/upload/recipe-cover/import/r300361.jpg', '羊排焖面是一道肉香浓郁、面条筋道的北方家常硬菜，羊排软烂，宽面吸足汤汁，每一口都满足。这道菜有肉有面有菜，一顿饭就能补齐人体所需的蛋白质、碳水和脂肪，营养全面。制作时需要先炖羊排再和面焖面，步骤稍多，更适合有一定下厨经验的朋友尝试，预计全程大约花费一个半小时。', 4, 1616.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300362, '羊肉汤', '/upload/recipe-cover/import/r300362.jpg', '羊肉汤是一道家常暖身汤品，汤色乳白，肉质鲜嫩，带有大葱和白胡椒的清香与微辛。富含蛋白质、钙、铁等营养成分，有温补脾胃、抵御寒冷的功效。制作步骤简单，新手也能轻松掌握，整个烹饪过程大约需要 30 分钟。', 3, 599.00, 30, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300363, '美式炒蛋', '/upload/recipe-cover/import/placeholder.png', '这是一道松软鲜嫩的美式家常蛋料理，加入牛奶后蛋花细密、口感绵润，富含优质蛋白和钙质。做法简单，对新手友好，从准备到出锅大约只需 20 分钟。', 2, 258.00, 20, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300364, '老友猪肉粉', '/upload/recipe-cover/import/r300364.jpg', '老友猪肉粉酸辣鲜香，米粉爽滑，带着豆豉与酸笋特有的浓郁风味，是典型的南宁家常味。猪肉提供优质蛋白质，米粉则快速补充碳水能量。整体制作中等难度，需注意提前泡发米粉，熟练后大约四十分钟就能端上桌。', 3, 927.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300365, '老妈蹄花', '/upload/recipe-cover/import/r300365.jpg', '老妈蹄花汤色奶白，猪蹄软烂脱骨，口感细腻，配上酸辣蘸汁十分开胃，是经典的川式家常菜。猪蹄富含胶原蛋白，白芸豆增添绵密口感，营养丰富。操作需要高压锅和提前浸泡，对新手有一定挑战，但按步骤来做不难掌握。含浸泡和压煮，全程大约需要 2 小时（不含提前一晚浸泡白芸豆的时间）。', 4, 1425.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300366, '老干妈拌面', '/upload/recipe-cover/import/placeholder.png', '一道香辣开胃的家常快手面食，面条筋道裹满老干妈的豆豉辣香，酱油提鲜，简单却滋味十足。作为主食能快速补充碳水化合物和能量，辣椒素还有助促进食欲。制作毫无门槛，新手也能轻松驾驭，从烧水到出锅只需大约十 分钟。', 1, 502.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300367, '老式锅包肉', '/upload/recipe-cover/import/r300367.jpg', '锅包肉是东北经典名菜，起源于哈尔滨道台府，以白醋调出鲜明酸香，外壳酥脆、肉片滑嫩，酸甜爽口。猪肉提供优质蛋白质，搭配葱姜等蔬菜开胃解腻。这道菜需要掌握挂浆、油温和复炸技巧，烹饪难度中等偏上，新手需要耐心练习。从腌肉、调糊到炸制出锅，预计制作时长约 90 分钟。', 4, 882.00, 90, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300368, '老母鸡汤面', '/upload/recipe-cover/import/placeholder.png', '老母鸡汤面，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300369, '老面小笼包', '/upload/recipe-cover/import/r300369.png', '老面小笼包，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300370, '老面馒头', '/upload/recipe-cover/import/placeholder.png', '老面馒头，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
