INSERT INTO `recipe` VALUES (300382, '肥西老母鸡汤', '/upload/recipe-cover/import/r300382.png', '肥西老母鸡汤，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
