INSERT INTO `recipe` VALUES (300442, '蒜苔炒肉末', '/upload/recipe-cover/import/placeholder.png', '蒜苔炒肉末是北方家常菜，咸鲜脆嫩，蒜香浓郁。蒜苔富含膳食纤维和维生素，五花肉提供蛋白质，荤素搭配均衡。做法简单，备料轻松，新手也能快速上手。从切配到出锅大约只需 10 分钟。', 2, 258.00, 10, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300443, '蒜苔炒香干', '/upload/recipe-cover/import/placeholder.png', '蒜苔炒香干，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300444, '蒜苔炒鸡胗', '/upload/recipe-cover/import/placeholder.png', '蒜苔炒鸡胗，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300445, '蒜蓉娃娃菜', '/upload/recipe-cover/import/r300445.jpg', '蒜蓉娃娃菜，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300446, '蒜蓉炒芹菜', '/upload/recipe-cover/import/r300446.jpg', '蒜蓉炒芹菜是一道清脆爽口、蒜香浓郁的家常快手素菜。芹菜富含膳食纤维、维生素 K 和钾元素。这道菜的灵魂在于「脆」——大火快炒半分钟即出锅，口感脆生生的，一口咬下去还有汁水。从备料到出锅大约只需 10 分钟。', 2, 150.00, 10, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300447, '蒜蓉空心菜', '/upload/recipe-cover/import/r300447.jpg', '蒜蓉空心菜是一道清脆爽口、蒜香浓郁的家常快手菜，属于典型的川式小炒风味。空心菜富含膳食纤维、维生素和钙质，有助于促进肠道蠕动。做法非常简单，对新手十分友好，从备料到出锅大约只需 15 分钟。', 2, 440.00, 15, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300448, '蒜蓉粉丝虾', '/upload/recipe-cover/import/r300448.png', '蒜蓉粉丝虾，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300449, '蒜蓉虾', '/upload/recipe-cover/import/r300449.jpeg', '这道广东传统名菜以鲜香嫩滑著称，虾肉清甜弹牙，蒜香浓郁扑鼻。海虾富含优质蛋白和钙、硒等微量元素，搭配蒜蓉有助杀菌开胃。做法十分简单，处理虾、铺酱、蒸制、淋油几步即成，新手也能轻松驾驭，全程约需 15 分钟。', 2, 456.00, 15, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300450, '蒜蓉西兰花', '/upload/recipe-cover/import/placeholder.png', '这道家常蔬菜以蒜香浓郁、调味简单见长，西兰花焯水后软嫩或微脆，清淡鲜美。富含维生素 C、膳食纤维和多种抗氧化物质，是营养均衡的快手素菜。制作过程不难，新手也能轻松掌握，从备料到出锅一般约 15 分钟即可完成。', 2, 187.00, 15, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300451, '蒜香酱油', '/upload/recipe-cover/import/placeholder.png', '蒜香酱油是一道蒜香浓郁、咸鲜油润的家常蘸料，常用于白切鸡、饺子等菜肴的提味。大蒜和芝麻分别具有抗菌和补充不饱和脂肪酸的作用。做法极其简单，对新手非常友好，全程只需大约 5 分钟即可完成。', 2, 177.00, 5, 1, 1112, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300452, '蒜香黄油虾', '/upload/recipe-cover/import/r300452.jpg', '蒜香黄油虾是一道经典的西式海鲜菜，虾肉鲜嫩弹牙，被浓郁的蒜香和黄油包裹，带有淡淡柠檬清香。虾肉富含优质蛋白，搭配黄油提供能量，适合快速补充营养。做法简单，只需几种常见食材，新手也能轻松上手，从备料到出锅大约二十分钟。', 2, 526.00, 30, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300453, '蒜黄炒鸡蛋', '/upload/recipe-cover/import/placeholder.png', '蒜黄炒鸡蛋，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300454, '蒲烧茄子', '/upload/recipe-cover/import/placeholder.png', '蒲烧茄子是一道咸甜交织、口感软糯的家常菜，借鉴日式蒲烧风味却用中式煎烧手法烹制。茄子富含膳食纤维和多种维生素，有助于清热活血。难度适中，对新手稍需耐心，预计制作时长约 30 分钟。', 3, 326.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300455, '蒸南瓜', '/upload/recipe-cover/import/placeholder.png', '蒸南瓜，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300456, '蒸卤面', '/upload/recipe-cover/import/placeholder.png', '这是一道豫南地区经典的家常面食，荤素搭配，面条吸足汤汁，口感软韧，咸香入味。五花肉提供优质蛋白质和脂肪，芹菜富含膳食纤维。做法简单易学，新手也能从容上手，整体制作约需一小时。', 4, 1563.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300457, '蒸嫩豆腐', '/upload/recipe-cover/import/placeholder.png', '蒸嫩豆腐，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300458, '蒸水蛋', '/upload/recipe-cover/import/placeholder.png', '这是一道以滑嫩如布丁的口感和清雅鲜美的风味见长的家常菜，南北通吃，北方常亲切地称其为“鸡蛋糕儿”。鸡蛋富含优质蛋白和卵磷脂，是日常补充营养的便捷之选。做法只需掌握蛋水比例和小火慢蒸的诀窍，对新手非常友好，从准备到出锅通常 大约 15 分钟就能完成。', 2, 143.00, 15, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300459, '蒸箱鸡蛋羹', '/upload/recipe-cover/import/placeholder.png', '这是一道利用蒸箱快速制作的嫩滑家常蛋羹，口感可调，水少则弹、水多则嫩。富含优质蛋白质和多种营养素，易于消化吸收。难度适中，新手稍加注意即可掌握，从准备到出锅大约只需 15 分钟。', 3, 118.00, 15, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300460, '蒸花卷', '/upload/recipe-cover/import/placeholder.png', '这是一道北方传统面食，松软可口，带着淡淡麦香。使用冷冻花卷蒸制，能快速补充碳水化合物和膳食纤维。做法极其简单，烹饪新手也能轻松掌握，全程仅需半小时，是理想的快手早餐。', 2, 400.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300461, '蔗糖糖浆', '/upload/recipe-cover/import/r300461.jpg', '自制饮料糖浆，按 1：1 比例将白砂糖与水混合溶解，方便控制冷饮甜度，是调饮的基础配方。富含碳水化合物，能快速补充能量。做法极其简单，对新手非常友好，仅需几分钟即可完成，冷藏可保存一周。', 1, 400.00, 30, 1, 1112, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300462, '蔬菜鸡蛋卷饼', '/upload/recipe-cover/import/placeholder.png', '蔬菜鸡蛋卷饼，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300463, '薄皮青椒', '/upload/recipe-cover/import/placeholder.png', '薄皮青椒，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1108, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300464, '薯条', '/upload/recipe-cover/import/placeholder.png', '薯条，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1105, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300465, '虎皮肘子', '/upload/recipe-cover/import/placeholder.png', '这道菜成品色泽红亮，肘皮呈现诱人的虎皮纹路，口感软烂入味，肥而不腻，瘦肉松软，属于传统中式宴客大菜。猪肘富含胶原蛋白和优质蛋白，经过长时间炖煮后更易吸收，对皮肤和关节有一定滋养效果。制作过程包含烧皮、油炸、炒糖色和高压炖煮等多个步骤，对新手来说挑战较大，建议有一定烹饪基础再尝试。从预处理到上桌，预计总耗时约 2.5 小时。', 5, 1018.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300466, '虎皮青椒', '/upload/recipe-cover/import/r300466.jpg', '虎皮青椒是一道家常小菜，外皮微焦起皱，口感软嫩带脆，咸鲜中透着酸甜，十分开胃下饭。青椒富含维生素 C 和膳食纤维，有助于增强免疫力、促进消化。制作过程简单明了，只需掌握按压和火候，对新手也比较友好，一般约 15 分钟就能完成。', 3, 341.00, 15, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300467, '虾仁蒸鸡蛋', '/upload/recipe-cover/import/r300467.jpg', '虾仁蒸鸡蛋，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300468, '蚂蚁上树', '/upload/recipe-cover/import/placeholder.png', '蚂蚁上树是一道经典的川味家常菜，咸香微辣，粉丝软滑吸汁，肉末细嫩鲜香。以红薯粉丝和肉末为主料，富含碳水化合物与蛋白质，能快速补充能量。制作难度中等，步骤清晰，对新手比较友好，全程约需 20 分钟即可完成。', 3, 791.00, 20, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300469, '蚕豆炒虾仁', '/upload/recipe-cover/import/placeholder.png', '蚕豆炒虾仁，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300470, '蚕豆炒鸡蛋', '/upload/recipe-cover/import/r300470.jpg', '蚕豆炒鸡蛋，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300471, '蚝油三鲜菇', '/upload/recipe-cover/import/r300471.jpeg', '蚝油三鲜菇是一道鲜美滑嫩的家常快手菜，菌菇吸饱蚝油酱汁，口感软滑有嚼劲，带着微微辣意，清爽不腻。富含植物蛋白、膳食纤维和多种维生素，搭配西蓝花营养均衡。制作简单，新手也能轻松掌握，从备料到出锅仅需 大约 15 分钟。', 3, 222.00, 15, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300472, '蚝油生菜', '/upload/recipe-cover/import/placeholder.png', '蚝油生菜是一道爽口鲜香的家常菜，脆嫩的生菜淋上蒜香蚝油汁，咸中带甜，属于粤菜和川菜馆都很常见的快手素菜。富含维生素和膳食纤维，有助于促进消化。做法对新手非常友好，从洗菜到出锅大约只需 15 分钟即可完成。', 2, 125.00, 15, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300473, '蛋包饭', '/upload/recipe-cover/import/placeholder.png', '以嫩滑蛋皮包裹茄汁炒饭，口感丰富，酸甜开胃，是一道经典的日式家庭料理。富含蛋白质、碳水和多种维生素，营养均衡。包裹蛋皮需要一点技巧，但整体难度适中，新手也可尝试，从准备到完成约需 25 分钟。', 3, 695.00, 25, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300474, '蛋炒饭', '/upload/recipe-cover/import/placeholder.png', '一道家常蛋炒饭，金黄的蛋丝裹着粒粒分明的米饭，搭配火腿、胡萝卜和黄瓜，口感丰富，咸香适口。鸡蛋提供优质蛋白，胡萝卜增添维生素，碳水化合物带来充足能量。制作步骤稍多，但新手按流程操作也能成功，全程大约需要 25 分钟。', 3, 853.00, 25, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300475, '蛋煎糍粑', '/upload/recipe-cover/import/placeholder.png', '一道简单快手的小吃，外皮微酥，内里软糯，裹着蛋香与甜味，是南方家常风味。糍粑提供丰富碳水，鸡蛋补充蛋白质，热量较高但很顶饱。制作过程极其简单，新手也能轻松驾驭，全程仅需大约十 分钟。', 2, 379.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300476, '蛋饼', '/upload/recipe-cover/import/r300476.png', '蛋饼，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300477, '蛏抱蛋', '/upload/recipe-cover/import/r300477.jpeg', '蛏抱蛋是福建福州一带的传统家常菜，蛏肉裹着蛋液煎得外酥里嫩，带着洋葱和生抽的咸鲜香气。蛏子富含优质蛋白和锌、铁等微量元素，与鸡蛋搭配营养均衡。制作难度适中，需掌握煎炸火候但步骤不繁琐，预计 大约 30 分钟就能端上餐桌。', 3, 1229.00, 30, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300478, '蜜汁南瓜', '/upload/recipe-cover/import/r300478.jpg', '蜜汁南瓜，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300479, '螺蛳粉', '/upload/recipe-cover/import/placeholder.png', '螺蛳粉是广西柳州的特色小吃，汤鲜味浓，酸辣爽口，米粉软滑筋道。口味上融合了螺蛳汤的鲜美、酸笋的独特发酵风味和辣椒油的刺激，层次分明。作为主食，米粉提供充足碳水化合物，螺蛳肉包和配料带来一定蛋白质，酸笋则有助于开胃促消化。这道菜所需操作简单，只需按顺序煮熟米粉和调味即可，对新手非常友好。从烧水到出锅，最快约十分钟就能端上餐桌，适合快手解决一餐。', 1, 1109.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300480, '血浆鸭', '/upload/recipe-cover/import/placeholder.png', '血浆鸭是一道湖南武冈传统名菜，鸭肉香酥脆嫩，浸透醋血后连姜和辣椒都变得甜净不辣。鸭肉与鸭血提供优质蛋白和铁质，适合补血养身。制作步骤较多，需要留意火候和翻炒，但跟着步骤操作，初学者也能在 大约 2 小时完成。', 5, 2482.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300481, '西兰花炒鸡胸肉', '/upload/recipe-cover/import/placeholder.png', '西兰花炒鸡胸肉，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300482, '西红柿土豆炖牛肉', '/upload/recipe-cover/import/r300482.png', '一道家常炖菜，酸甜开胃，汤汁浓郁，牛肉软烂，土豆绵密。牛肉提供优质蛋白，西红柿富含番茄红素，搭配土豆和洋葱，营养均衡。操作简单，无需复杂技巧，新手也能轻松上手。从备菜到出锅大约需要 1 至 1.5 小时。', 4, 827.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300483, '西红柿炒鸡蛋', '/upload/recipe-cover/import/placeholder.png', '一道酸甜开胃的家常菜肴，嫩滑的鸡蛋裹着软烂多汁的西红柿，是中国家庭餐桌上的经典味道。鸡蛋提供优质蛋白质，西红柿富含维生素 C 和番茄红素，营养均衡好吸收。步骤简单，原材料易得，特别适合厨房新手入门，从头备菜到盛盘出锅大约只需 15 分钟。', 2, 252.00, 15, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300484, '西红柿炒鸡蛋盖饭', '/upload/recipe-cover/import/placeholder.png', '西红柿炒鸡蛋盖饭，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300485, '西红柿牛腩', '/upload/recipe-cover/import/placeholder.png', '西红柿牛腩汤汁浓厚酸甜可口，牛肉软绵醇香，是道开胃下饭的家常菜。富含蛋白质、维生素和番茄红素，营养均衡。对新手有一定挑战，需要掌握炖肉火候和番茄炒汁的技巧。一般初学者大约需要 90 分钟完成。', 5, 1569.00, 90, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300486, '西红柿豆腐汤羹', '/upload/recipe-cover/import/r300486.jpeg', '一道清淡鲜美的家常汤羹，酸甜开胃，口感嫩滑。西红柿富含维生素 C 和番茄红素，搭配鸡蛋与豆腐，能补充优质蛋白，营养均衡易吸收。做法简单，只需切配翻炒和煮制，新手也能轻松掌握，从准备到出锅大约 15 分钟即可完成。', 2, 242.00, 15, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300487, '西红柿鸡蛋挂面', '/upload/recipe-cover/import/r300487.jpg', '西红柿鸡蛋挂面是一道家常快手面食，酸甜咸鲜，汤汁浓郁，面条劲道，属于融入北方风味的日常主食。鸡蛋提供优质蛋白，西红柿富含番茄红素和维生素，搭配碳水主食，营养均衡。操作简单，步骤清晰，对新手友好，从备料到完成大约只需 20 分钟。', 2, 654.00, 20, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300488, '西红柿鸡蛋汤', '/upload/recipe-cover/import/placeholder.png', '西红柿鸡蛋汤是一道酸甜开胃、口感滑嫩的家常汤品，做法极简，属于老少皆宜的大众菜肴。富含番茄红素、维生素 C 和优质蛋白质，营养均衡易吸收。对新手非常友好，快手省时，预计制作时长 大约 15 分钟。', 2, 258.00, 15, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300489, '西芹炒虾仁', '/upload/recipe-cover/import/placeholder.png', '西芹炒虾仁，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300490, '西芹花生米', '/upload/recipe-cover/import/r300490.jpg', '西芹花生米，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1006, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300491, '西葫芦炒鸡蛋', '/upload/recipe-cover/import/r300491.jpeg', '西葫芦炒鸡蛋是一道清爽可口的家常快手菜，西葫芦软嫩多汁、鸡蛋鲜香松软，加入西红柿后更添酸甜风味，十分下饭。鸡蛋提供优质蛋白质和卵磷脂，西葫芦含有丰富的维生素 C 和膳食纤维，搭配食用营养均衡。制作过程简单，对新手非常友好，从备料到出锅一般初学者只需 15 分钟即可完成。', 2, 224.00, 15, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300492, '话梅煮毛豆', '/upload/recipe-cover/import/r300492.jpeg', '话梅煮毛豆是一道酸甜开胃的家常小菜，口感清爽软糯，带有梅子的自然果香。毛豆富含植物蛋白和膳食纤维，有助于补充能量、促进消化。做法非常简单，新手也能轻松上手，全程只需 35 到 45 分钟即可完成。', 2, 454.00, 45, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300493, '豆皮毛白菜', '/upload/recipe-cover/import/placeholder.png', '豆皮毛白菜，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300494, '豆角焖面', '/upload/recipe-cover/import/placeholder.png', '豆角焖面是一道北方家常面食，面条吸饱汤汁，口感软韧咸香，带着豆角的清爽和肉片的油润。五花肉提供蛋白质和脂肪，豆角富含膳食纤维和维生素，荤素搭配均衡。整体操作不难，但需要留意火候和加汤时机，适合有一定下厨经验的朋友尝试，一般约 30 分钟就能端上桌。', 3, 1386.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300495, '豆豉鲮鱼油麦菜', '/upload/recipe-cover/import/r300495.jpg', '豆豉鲮鱼油麦菜是一道咸香下饭的快手家常小炒，源于粤式罐头菜肴，油麦菜清脆、鲮鱼酥香。荤素搭配，富含蛋白质和膳食纤维。做法简单，对新手十分友好，一般十五分钟即可完成。', 2, 416.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300496, '豉汁排骨', '/upload/recipe-cover/import/placeholder.png', '这是一道粤式茶楼里的人气蒸点，豉香醇厚，排骨滑嫩脱骨。排骨提供优质蛋白和钙质，发酵豆豉增添风味也更利吸收。做法需经过泡洗、腌制和控火蒸制，对新手稍有考验，但步骤清晰易上手，从备料到出锅大约只需 1 小时。剩余的汤汁用来拌饭或拌面格外鲜美。', 4, 1513.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300497, '豉汁蒸白鱔', '/upload/recipe-cover/import/r300497.jpeg', '豉汁蒸白鱔是一道粤式经典蒸菜，豆豉蒜蓉的酱香渗透进鱼肉，口感嫩滑鲜美。白鱔富含优质蛋白和多种不饱和脂肪酸，对身体有滋补作用。操作步骤清晰，但处理生鱼和掌握火候稍有挑战，适合有一定基础的厨友。从备料到上桌大约需要 30 分钟。', 3, 472.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300498, '豉汁鱼块', '/upload/recipe-cover/import/placeholder.png', '豉汁鱼块，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300499, '豌豆肉末', '/upload/recipe-cover/import/placeholder.png', '豌豆肉末，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300500, '贵州辣子鸡', '/upload/recipe-cover/import/r300500.jpg', '贵州辣子鸡是贵州地区的经典家常菜，以糍粑辣椒和多种香料烹制而成，鸡肉香糯软烂，土豆绵密入味，整体风味香辣浓郁。鸡肉富含优质蛋白质，搭配土豆等配菜，营养均衡。这道菜步骤较多，对新手有一定挑战，但按部就班也能成功。从备料到出锅，预计需要 1.大约 5 小时。', 4, 1441.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300501, '贵州风味辣子鸡', '/upload/recipe-cover/import/r300501.png', '贵州风味辣子鸡，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300502, '赤豆糊元宵', '/upload/recipe-cover/import/r300502.png', '赤豆糊元宵，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300503, '辣椒炒肉', '/upload/recipe-cover/import/placeholder.png', '辣椒炒肉是一道湘味浓郁的家常菜，辣椒干香微焦，肉片滑嫩入味，咸鲜微辣十分下饭。猪肉富含优质蛋白质和 B 族维生素，青椒则提供丰富的维生素 C。这道菜需要掌握干煸和快炒的火候，适合有一定烹饪基础的朋友尝试。从备料到出锅，大约需要 30 分钟。', 3, 425.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300504, '速冻水饺', '/upload/recipe-cover/import/placeholder.png', '这是一道源自中国的家常面食，采用市售冻饺速成，皮薄馅丰，口感鲜香。佐以醋、姜、蒜等蘸料，滋味更添层次。作为一餐，它能提供充足的蛋白质与碳水，营养饱腹。制作毫无难点，新手也能轻松上手，前后仅需大约一 刻钟。', 1, 502.00, 30, 1, 1107, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300505, '速冻汤圆', '/upload/recipe-cover/import/r300505.jpg', '速冻汤圆是一道快速方便的微波炉甜点，外皮软糯、内馅香甜，属于中式传统小吃。主要提供碳水化合物，能迅速补充能量。做法极易上手，新手也能轻松完成，从准备到出锅仅需大约 6 分钟。', 1, 568.00, 6, 1, 1107, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300506, '速冻馄饨', '/upload/recipe-cover/import/placeholder.png', '速冻馄饨皮薄馅嫩，汤清味鲜，是一道便捷的家常面食。主要提供碳水化合物和蛋白质，便于快速补充能量。做法简单，对新手非常友好，使用电饭煲即可完成，从烧水到出锅大约需要 55 分钟。', 2, 540.00, 55, 1, 1107, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300507, '酒酿蛋花甜羹', '/upload/recipe-cover/import/placeholder.png', '酒酿蛋花甜羹，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300508, '酒酿醪糟', '/upload/recipe-cover/import/r300508.jpeg', '这是一道传统中式发酵甜品，口感清甜微醺，带着淡淡的酒香。具有健脾开胃、促进消化的作用。制作过程简单有趣，虽然需要等待发酵，但动手操作并不复杂，非常适合作为发酵入门。预计制作总时长约 2 天，其中实际动手时间仅需 大约 1 小时。', 4, 420.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300509, '酥皮萝卜丝馅饼', '/upload/recipe-cover/import/r300509.png', '酥皮萝卜丝馅饼，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300510, '酱拌荞麦面', '/upload/recipe-cover/import/r300510.jpeg', '酱拌荞麦面酸甜可口、清凉爽滑，是一道简单快手的家常凉拌面。荞麦面富含膳食纤维和蛋白质，搭配黄瓜、胡萝卜增添清爽口感与维生素，营养均衡。只需煮面、切菜、拌入老干妈，几步搞定，对新手非常友好，一般约 20 分钟便可完成。冷藏后食用风味更佳。', 2, 475.00, 20, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300511, '酱排骨', '/upload/recipe-cover/import/r300511.jpeg', '酱排骨色泽酱红，肉质酥烂，骨香浓郁，汁浓味鲜，咸中带甜，是一道经典的家常菜。排骨富含优质蛋白质和钙质，营养均衡。制作涉及炒糖色和较长时间炖煮，对新手有一定挑战，但只要按步骤操作，也能顺利掌握。预计从备料到出锅约需 1 小时。', 4, 1351.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300512, '酱椒蒜香片片鱼', '/upload/recipe-cover/import/r300512.png', '酱椒蒜香片片鱼，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300513, '酱炖蟹', '/upload/recipe-cover/import/placeholder.png', '这道菜是浙江平湖地区的秋日限定咸鲜风味，蟹黄绵润裹着酱香，蟹肉清甜，汤汁拌饭一绝。富含优质蛋白和微量元素。难度适中，适合有基础的新手，从准备到出锅大约 30 分钟。', 3, 468.00, 30, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300514, '酱牛肉', '/upload/recipe-cover/import/r300514.jpg', '酱牛肉是一道北派家常冷荤，酱香浓郁，口感紧实不散，嚼劲十足。牛腱子肉富含优质蛋白和多种氨基酸，慢炖后更易消化吸收。制作过程不算复杂，但包含腌制、慢炖和长时间冷藏，对新手来说需要些耐心，从头到尾大约需要 10 小时。', 5, 2265.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300515, '酱蒸白干', '/upload/recipe-cover/import/r300515.png', '酱蒸白干，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300516, '酱蒸豆腐', '/upload/recipe-cover/import/r300516.jpg', '酱蒸豆腐，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300517, '酱香小河虾', '/upload/recipe-cover/import/r300517.jpg', '酱香小河虾，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300518, '酸奶意式奶冻', '/upload/recipe-cover/import/r300518.png', '一道改良自意大利经典的甜品，融入原味酸奶后口感更为清爽顺滑，甜而不腻，适合作为餐后小点搭配水果或果酱。奶制品带来丰富的钙质和蛋白质，营养温和。制作步骤简单，只需加热搅拌和冷藏定型，新手也能顺利上手，从准备到冷藏完成大约需要 5 小时。', 4, 1034.00, 30, 1, 1109, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300519, '酸梅汤', '/upload/recipe-cover/import/r300519.jpg', '酸梅汤是一道酸甜可口、清凉解暑的传统饮品，冰镇后饮用尤为沁人心脾。配方中的乌梅、山楂、甘草等原料有助于生津止渴、消食开胃。做法简单，新手友好，只需浸泡、熬煮和冷藏即可。制作全程包括浸泡、两次煎煮和冷藏，大约需要 6 小时以上，建议提前准备。', 2, 359.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300520, '酸梅汤（半成品加工）', '/upload/recipe-cover/import/placeholder.png', '酸梅汤（半成品加工）是一道酸甜爽口的夏日消暑饮品，传统京味风格。酸梅汤本身有生津止渴、帮助消化的好处。做法极其简单，只需按顺序搅拌即可，对新手毫无难度，全程大约五分钟就能完成。', 1, 603.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300521, '酸菜肥肠煲', '/upload/recipe-cover/import/r300521.png', '酸菜肥肠煲，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1115, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300522, '酸菜血旺豆腐', '/upload/recipe-cover/import/placeholder.png', '酸菜血旺豆腐，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1111, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300523, '酸辣包菜', '/upload/recipe-cover/import/placeholder.png', '酸辣包菜，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300524, '酸辣土豆丝', '/upload/recipe-cover/import/placeholder.png', '酸辣开胃的经典家常菜，口感脆爽，色泽鲜亮，属于大众喜爱的快手小炒。土豆提供碳水化合物和钾元素，辣椒富含维生素 C，有助于增进食欲。操作步骤简单明了，对新手十分友好，从备料到出锅大约只需 20 分钟。', 2, 374.00, 20, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300525, '酸辣大白菜', '/upload/recipe-cover/import/placeholder.png', '酸辣大白菜，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300526, '酸辣海带丝', '/upload/recipe-cover/import/r300526.jpg', '酸辣海带丝，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300527, '酸辣蕨根粉', '/upload/recipe-cover/import/placeholder.png', '酸辣蕨根粉口感爽滑筋道，酸辣开胃，是一道家常凉菜，也可当作主食享用。蕨根粉富含淀粉和膳食纤维，能为身体提供能量。这道菜做法格外简单，对新手非常友好，从准备到完成只需 10 分钟。', 2, 318.00, 10, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300528, '醉排骨', '/upload/recipe-cover/import/r300528.jpeg', '醉排骨是福州传统名菜，口感外酥里嫩，酸甜开胃，带着独特的鱼露鲜香。排骨富含蛋白质和钙质，营养解馋。这道菜需要掌握挂糊和复炸的技巧，更适合有一定下厨经验的朋友尝试，全程大约需要 40 分钟完成。', 4, 934.00, 40, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300529, '醪糟小汤圆', '/upload/recipe-cover/import/placeholder.png', '醪糟小汤圆是一道香甜软糯的传统中式甜品，酒酿的微酸与糯米的绵滑交融，暖胃又舒心。它富含碳水化合物和少量 B 族维生素，能快速补充能量，也有助促进血液循环。做法毫无门槛，对新手特别友好，从烧水到出锅只需约 15 分钟，是一碗随时都能轻松完成的家常甜汤。', 2, 957.00, 15, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300530, '金枪鱼酱三明治', '/upload/recipe-cover/import/placeholder.png', '这道西式早餐三明治以水浸金枪鱼拌入蛋黄酱和俄式酸黄瓜汁，咸鲜微酸，口感绵密，配上烤脆的吐司格外饱腹。富含优质蛋白和 Omega-3 等营养，能快速补充能量。制作非常简单，只需混合酱料、用轻食机加热，新手也能在 5 分钟里轻松搞定。', 1, 569.00, 5, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300531, '金汤力', '/upload/recipe-cover/import/r300531.jpg', '这是一款经典的金酒鸡尾酒，口感清爽微苦，带有柠檬的明亮酸香与汤力水的细腻气泡，入口轻盈畅快。虽然主要提供水分和少量酒精带来的热量，新鲜柠檬汁能补充维生素 C，帮助提神。做法非常简单，新手也能轻松掌握，预计只需 5 分钟即可完成。', 2, 205.00, 5, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300532, '金汤酸菜鱼', '/upload/recipe-cover/import/r300532.png', '金汤酸菜鱼，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1106, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300533, '金汤酸菜鱼（大份）', '/upload/recipe-cover/import/r300533.png', '金汤酸菜鱼（大份），家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1106, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300534, '金牌老母鸡汤', '/upload/recipe-cover/import/placeholder.png', '金牌老母鸡汤，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300535, '金菲士', '/upload/recipe-cover/import/r300535.jpg', '经典金酒鸡尾酒，酸甜适口，气泡激爽。柠檬提供丰富维 C，搭配蔗糖糖浆平衡酸度。制作非常简单，新手只需 5 分钟即可调制完成，适合在家轻松享用。注意饮酒有害健康，请勿过量。', 2, 150.00, 5, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300536, '金针菇日本豆腐煲', '/upload/recipe-cover/import/placeholder.png', '金针菇日本豆腐煲是一道酱香浓郁的家常下饭菜，豆腐外焦里嫩，金针菇爽滑入味。金针菇富含氨基酸和膳食纤维，日本豆腐提供优质蛋白，营养开胃。这道菜步骤简单，新手也能轻松掌握，从备菜到出锅大约需要 30 分钟。', 2, 606.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300537, '金针菇汤', '/upload/recipe-cover/import/placeholder.png', '这是一道清淡爽口的家常汤品，口味鲜美，属简易快手菜。金针菇含有丰富的氨基酸和膳食纤维，加鸡蛋还能补充优质蛋白。制作门槛极低，新手也能轻松驾驭，从备菜到出锅大约只需 10 分钟。', 2, 149.00, 10, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300538, '金钱蛋', '/upload/recipe-cover/import/placeholder.png', '金钱蛋是一道外焦里嫩、咸香微辣的湘味家常菜，煎至金黄的蛋片形似铜钱，寓意吉祥。鸡蛋与青红椒搭配，富含优质蛋白质和多种维生素，营养均衡。制作难度中等，新手稍加练习也能掌握，全程约需 30 分钟即可完成下饭菜。', 3, 427.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300539, '铜锅安格斯肥牛', '/upload/recipe-cover/import/placeholder.png', '铜锅安格斯肥牛，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1106, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300540, '铜锅川味水煮肉片', '/upload/recipe-cover/import/placeholder.png', '铜锅川味水煮肉片，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1106, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
