INSERT INTO `recipe` VALUES (300542, '铜锅豆花鸡', '/upload/recipe-cover/import/placeholder.png', '铜锅豆花鸡，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1106, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300543, '银耳莲子炖梨', '/upload/recipe-cover/import/placeholder.png', '银耳莲子炖梨，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300544, '银耳莲子粥', '/upload/recipe-cover/import/r300544.png', '银耳莲子粥清甜润滑，银耳软糯、莲子绵密，是常见的滋补粥品。富含天然胶质、膳食纤维及多种微量元素，有助养心安神。制作需经历浸泡和慢熬，对新手的耐心是个考验，全程大约需要 3.5 小时。', 4, 282.00, 30, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300545, '银鱼浦鸡蛋', '/upload/recipe-cover/import/placeholder.png', '银鱼浦鸡蛋，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1111, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300546, '长岛冰茶', '/upload/recipe-cover/import/placeholder.png', '长岛冰茶是一款口感酷似冰茶、入口柔和但酒精度颇高的经典鸡尾酒。它本身营养价值不高，偶尔小酌可放松身心，但切勿过量。做法非常简单，只需按比例混合四种基酒、甜酒和果汁，新手也能轻松调制。从准备到完成仅需 大约 5 分钟。', 2, 281.00, 5, 1, 1008, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300547, '阳春面', '/upload/recipe-cover/import/placeholder.png', '阳春面，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300548, '阳朔啤酒鱼', '/upload/recipe-cover/import/r300548.png', '阳朔啤酒鱼是广西阳朔的地方名菜，选用漓江鲜鱼带鳞煎制，以啤酒代水焖煮，鱼鳞酥脆、鱼肉鲜嫩，啤酒香与番茄微酸交融，风味浓郁独特。鱼肉富含优质蛋白和矿物质，搭配番茄、辣椒，维生素丰富且开胃助食。制作难度中等，对新手稍具挑战，但跟着步骤操作也能成功，预计 30 分钟即可完成。', 3, 1092.00, 30, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300549, '陈皮排骨汤', '/upload/recipe-cover/import/placeholder.png', '一道清润滋补的广式炖汤，汤色清亮，入口甘醇，带有陈皮的独特清香。排骨提供优质蛋白，搭配西洋参、石斛等食材，能润肺健脾、生津止渴，适合经常熬夜的人群。制作难度中等，只需要将材料处理好放进炖盅，慢炖约两小时即可完成。', 4, 357.00, 30, 1, 1005, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300550, '陕北熬豆角', '/upload/recipe-cover/import/placeholder.png', '这是一道西北农家风味的炖菜，豆角绵软、土豆沙糯、番茄汤汁浓郁，酸香开胃。富含膳食纤维、维生素和碳水化合物，营养均衡。做法极其简单，食材用量可随喜好调整，几乎没有失败的可能，对新手特别友好。从备料到出锅，大约只需 30 分钟。', 2, 191.00, 30, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300551, '陕西油泼面', '/upload/recipe-cover/import/r300551.png', '这道西北传统面食以筋道的扯面和热油泼出的香辣风味著称，是陕西家喻户晓的日常主食。面条富含碳水化合物，搭配青菜和豆芽，能快速补充能量，膳食搭配合理。整个流程简单明了，对新手十分友好，从备料到出锅大约只需 30 分钟。', 2, 771.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300552, '雪花酥', '/upload/recipe-cover/import/r300552.jpg', '雪花酥是一道口感酥脆香甜、奶香浓郁的小甜点，属于简单快手的家常烘焙，也很适合装盒送礼。由于含有黄油、奶粉和混合坚果，能提供丰富的能量和蛋白质，不过热量较高，适合偶尔享用。制作难度适中，对新手有一定挑战，但只要注意火候和搅拌手法，一般只需 30 分钟就能完成。', 3, 1313.00, 30, 1, 1109, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300553, '雪菜肉丝面', '/upload/recipe-cover/import/r300553.png', '雪菜肉丝面，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300554, '雷椒皮蛋', '/upload/recipe-cover/import/placeholder.png', '雷椒皮蛋是一道卖相朴实但风味十足的家常凉菜，青椒的焦香与皮蛋的醇滑交融，酸辣开胃，尤其适合夏日佐餐。皮蛋富含蛋白质和矿物质，青椒提供丰富的维生素 C，大蒜则有助增进食欲。整道菜操作简单，新手也能轻松驾驭，从备料到完成大约只需 15 分钟。', 2, 448.00, 15, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300555, '青椒土豆炒肉', '/upload/recipe-cover/import/r300555.jpg', '青椒土豆炒肉是一道荤素搭配的家常小炒，口感鲜香脆嫩，酱香浓郁，特别下饭。土豆富含碳水化合物和维生素 C，青椒提供丰富的维生素 C 和膳食纤维，搭配猪肉的优质蛋白质，营养均衡。这道菜做法不复杂，对新手比较友好，从备料到出锅大约只需 1 小时。', 3, 1288.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300556, '青椒毛豆米', '/upload/recipe-cover/import/placeholder.png', '青椒毛豆米，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300557, '青椒炒豆芽', '/upload/recipe-cover/import/r300557.jpg', '青椒炒豆芽，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300558, '青椒炒鸡蛋', '/upload/recipe-cover/import/r300558.jpg', '青椒炒鸡蛋，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300559, '青椒蒸豆米', '/upload/recipe-cover/import/placeholder.png', '青椒蒸豆米，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300560, '青椒酿', '/upload/recipe-cover/import/r300560.jpeg', '这道广西经典家常菜以青椒包裹调好味的肉馅或虾滑，煎至表皮起皱呈虎皮色后焖煮入味，青椒清香与馅料鲜美交融，咸香微辣，十分下饭。猪肉和虾仁提供优质蛋白质，青椒富含维生素 C，营养均衡。制作需要一点耐心酿馅，但整体流程清晰，跟着步骤操作一般 30 分钟就能完成。', 3, 1403.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300561, '韩国麻药鸡蛋', '/upload/recipe-cover/import/placeholder.png', '一道甜辣浓郁的韩式溏心蛋小菜，酱汁挂满蛋白，入口嫩滑，回味微辛。鸡蛋提供优质蛋白与卵磷脂，营养饱腹。做法极为简单，新手也能轻松上手，从煮蛋到冷藏入味大约需要一个半小时。', 1, 669.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300562, '韩式拌饭', '/upload/recipe-cover/import/r300562.png', '韩式拌饭是一道色彩缤纷、口感丰富的韩国家常料理，甜辣酱汁包裹着米饭、蔬菜、牛肉和溏心蛋，拌匀后一口满足。多种蔬菜提供维生素和膳食纤维，牛肉和鸡蛋补充优质蛋白，营养均衡。制作简单但备菜步骤稍多，新手也能从容完成，从准备到上桌大约需要 45 分钟。', 3, 1080.00, 45, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300563, '韭菜炒蛋', '/upload/recipe-cover/import/placeholder.png', '韭菜炒蛋是一道经典的家常菜，韭菜香气浓郁，鸡蛋嫩滑鲜美，简单易做，营养丰富。韭菜含有丰富的维生素和纤维素，鸡蛋提供优质蛋白质。这道菜制作简单，原材料易得，特别适合厨房新手入门，从头备菜到盛盘出锅大约只需 10 分钟。', 2, 180.00, 10, 1, 1102, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300564, '韭菜盒子', '/upload/recipe-cover/import/placeholder.png', '韭菜盒子是一道传统中式面点，外皮金黄酥脆，内馅鲜香多汁。韭菜搭配虾仁和鸡蛋，富含维生素与优质蛋白质。做法简单，对新手也很友好，从和面到出锅大约需要 2.5 小时。', 3, 794.00, 30, 1, 1002, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300565, '风干牛肉蒸白干', '/upload/recipe-cover/import/r300565.jpg', '风干牛肉蒸白干，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1101, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300566, '饭团', '/upload/recipe-cover/import/r300566.png', '饭团，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300567, '馒头', '/upload/recipe-cover/import/r300567.png', '馒头，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1001, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300568, '香干肉丝', '/upload/recipe-cover/import/placeholder.png', '香干肉丝是一道咸香下饭的家常小炒，肉丝嫩滑，香干柔韧，青椒爽脆。富含动物性与植物性双重蛋白质，搭配青椒补充维生素。难度适中，新手稍加练习即可掌握，预计制作时长约 30 分钟。', 3, 472.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300569, '香干芹菜炒肉', '/upload/recipe-cover/import/r300569.jpg', '香干芹菜炒肉是一道家常小炒，豆干柔韧、芹菜爽脆、猪肉嫩滑，咸鲜微辣。芹菜富含膳食纤维，豆干和猪肉提供优质植物蛋白与动物蛋白。做法简单，对新手友好，从备料到出锅大约只需 30 分钟。', 3, 741.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300570, '香椿炒鸡蛋', '/upload/recipe-cover/import/r300570.jpg', '香椿炒鸡蛋，家常做法，具体用量与火候见下方步骤。', 3, 0.00, 30, 1, 1104, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300571, '香煎五花肉', '/upload/recipe-cover/import/r300571.jpg', '香煎五花肉是一道家常风味的快手荤菜，五花肉片煎得焦香微脆、肥而不腻，搭配脆爽的生菜叶和咸鲜豆瓣酱，入口酱香浓郁又解腻。猪肉富含优质蛋白质和脂肪，能快速补充能量，生菜则提供膳食纤维和维生素，营养更均衡。这道菜适合有一定下厨基础的朋友，新手只要注意火候和防溅油也能轻松上手，从备料到出锅大约半小时即可享用。', 3, 2985.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
INSERT INTO `recipe` VALUES (300572, '香煎翘嘴鱼', '/upload/recipe-cover/import/r300572.jpeg', '香煎翘嘴鱼是一道风味浓郁的家常河鲜，鱼身经腌晒后干香紧实，煎至外皮金黄酥脆，肉质细腻咸鲜，带着豆瓣与青椒的微辣回甜。鱼肉富含优质蛋白和不饱和脂肪酸，营养易吸收。制作需要提前腌晒两到四天，烹饪时间约半小时，煎鱼时需耐心控火，对新手稍有挑战，但成菜后香气扑鼻，格外下饭。', 4, 820.00, 30, 1, 1110, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
