INSERT INTO `recipe` VALUES (300581, '香菇滑鸡', '/upload/recipe-cover/import/r300581.jpg', '香菇滑鸡是一道以鸡腿肉和香菇为主料的家常菜，鸡腿肉经过煸炒和焖煮后口感滑嫩，搭配香菇独特的菌香，汤汁浓郁鲜美，属于老少皆宜的粤式风味。鸡肉富含优质蛋白质和多种氨基酸，香菇含有香菇多糖和膳食纤维，有助于增强免疫力和促进消化。这道菜需要一些刀工和火候控制，对新手有一定挑战，整体制作约需 1 小时。', 3, 608.00, 30, 1, 1103, 1, 0, 0, 1, NULL, '2026-08-23 15:56:43', '2026-08-23 15:56:43', 0);
