INSERT INTO `recipe_ingredient` VALUES (404401, 300634, 210403, 1.00, '克', 0, 1, '粉', 5);
INSERT INTO `recipe_ingredient` VALUES (404402, 300634, 211141, 0.00, '克', 0, 0, '腌料', 6);
INSERT INTO `recipe_ingredient` VALUES (404403, 300634, 2015, 1.00, '克', 0, 1, '盐量 = 份数 1 克', 7);
INSERT INTO `recipe_ingredient` VALUES (404404, 300634, 210366, 10.00, '毫升', 0, 1, '花生油 = 份数 10ml （实际上油量是依据菜量变动的，如对牛肉的量有增减请按对应比例变动）', 8);
INSERT INTO `recipe_ingredient` VALUES (404405, 300635, 211142, 200.00, '克', 0, 1, '黔式腊肠 200g', 1);
