INSERT INTO `recipe_step` VALUES (500001, 300001, 1, '在利口酒杯的最底层倒入甘露咖啡酒到 1/3 处。(10ml)', NULL);
INSERT INTO `recipe_step` VALUES (500002, 300001, 2, '顺着吧勺缓缓倒入爱尔兰百利甜酒，也是 1/3 处 (10ml)。注意要慢，保证层次分明。（太快甜酒会和咖啡混合）', NULL);
INSERT INTO `recipe_step` VALUES (500003, 300001, 3, '最后在上层倒入蓝天原味伏特加 （10ml)', NULL);
INSERT INTO `recipe_step` VALUES (500004, 300001, 4, '用打火机热一下杯口', NULL);
INSERT INTO `recipe_step` VALUES (500005, 300001, 5, '最后一步点火： 看到淡蓝色的小火苗了吗？', NULL);
INSERT INTO `recipe_step` VALUES (500006, 300002, 1, '将切成半块的青柠之一切成小块，放入海波杯，随后用研杵将其捣出汁；', NULL);
INSERT INTO `recipe_step` VALUES (500007, 300002, 2, '用 3-4 珠薄荷叶沿着杯口涂抹，随后将其放入杯中；', NULL);
INSERT INTO `recipe_step` VALUES (500008, 300002, 3, '加入 糖浆 20ml；', NULL);
INSERT INTO `recipe_step` VALUES (500009, 300002, 4, '加入 金色朗姆酒 45ml；', NULL);
INSERT INTO `recipe_step` VALUES (500010, 300002, 5, '将剩下的半块青柠压出汁水放入杯中；', NULL);
INSERT INTO `recipe_step` VALUES (500011, 300002, 6, '轻轻搅拌，使砂糖/糖浆处于半融合状态；', NULL);
INSERT INTO `recipe_step` VALUES (500012, 300002, 7, '将打碎的冰块放入杯中，直到占杯中 3/4；', NULL);
INSERT INTO `recipe_step` VALUES (500013, 300002, 8, '加入冰镇苏打水直到刚好淹没碎冰；', NULL);
INSERT INTO `recipe_step` VALUES (500014, 300002, 9, '旋转搅拌半分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500015, 300002, 10, '使用碎冰将海波杯补满；', NULL);
INSERT INTO `recipe_step` VALUES (500016, 300002, 11, '将剩下的一株薄荷叶拍醒，插入碎冰，作装饰。', NULL);
INSERT INTO `recipe_step` VALUES (500017, 300003, 1, '汤底制作（15份）：将5600g水、15g盐、40g鸡精、15g味精、65g浓缩鸡汁混合烧开备用；', NULL);
INSERT INTO `recipe_step` VALUES (500018, 300003, 2, '取16个虾滑馄饨放入面篓，沸水中煮制5分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500019, 300003, 3, '取350g汤底、15g熟猪油、1g白胡椒粉、1g紫菜放入面碗中，再倒入馄饨，最后加入10g烫制10秒的蛋丝，出品点缀1g葱花。', NULL);
INSERT INTO `recipe_step` VALUES (500020, 300004, 1, '每 150g 三色杂菜中放入 6g 大豆油、1g 鸡精、1g 盐、1g 白糖，拌匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (500021, 300004, 2, '将调味后的三色杂菜平铺于餐具底部；', NULL);
INSERT INTO `recipe_step` VALUES (500022, 300004, 3, '将去腥、上浆后的 6 颗虾仁平铺在杂菜上；', NULL);
INSERT INTO `recipe_step` VALUES (500023, 300004, 4, '蒸柜上汽后，蒸制 8 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (500024, 300005, 1, '娃娃菜洗净, 竖着切开切成段。', NULL);
INSERT INTO `recipe_step` VALUES (500025, 300005, 2, '葱 3g 切 小段。蒜 10g 切片。姜 10g 切小片。', NULL);
INSERT INTO `recipe_step` VALUES (500026, 300005, 3, '皮蛋切成丁, 火腿肠或者午餐肉切成丁（1cm 大小的丁）', NULL);
INSERT INTO `recipe_step` VALUES (500027, 300005, 4, '金针菇洗净撕开', NULL);
INSERT INTO `recipe_step` VALUES (500028, 300005, 5, '烧热水娃娃菜放进去十秒钟出一下水捞出。', NULL);
INSERT INTO `recipe_step` VALUES (500029, 300005, 6, '热锅凉油, 加热锅倒入油过一遍就倒出来, 重新倒入一点油。', NULL);
INSERT INTO `recipe_step` VALUES (500030, 300005, 7, '调至小火加入葱姜蒜，煎炒出香味即可。', NULL);
INSERT INTO `recipe_step` VALUES (500031, 300005, 8, '加入适 300g 清水（水量没过娃娃菜即可）, 放入娃娃菜, 金针菇, 午餐肉', NULL);
INSERT INTO `recipe_step` VALUES (500032, 300005, 9, '加入调味料蚝油、糖、盐、味精烧开。', NULL);
INSERT INTO `recipe_step` VALUES (500033, 300005, 10, '煮 3 分钟, 煮开后开始装盘, 盛出娃娃菜后皮蛋放在上面把汤汁浇上去就可以了', NULL);
INSERT INTO `recipe_step` VALUES (500034, 300006, 1, '【准备原料】取肉沫（解冻），加入 1/2 所有上述调料（油、盐、糖、酱油、风味调料）和全部的生粉，搅拌均匀，腌制 30 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500035, 300006, 2, '【准备原料】将面粉加入碗中，加入鸡蛋，加入剩下 1/2 所有上述调料，加入相当于面粉 1/2 的水（使得面粉相对粘稠但可以流动），搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (500036, 300006, 3, '【准备原料】蒜头切为蒜末。', NULL);
INSERT INTO `recipe_step` VALUES (500037, 300006, 4, '【准备原料】大葱切段。', NULL);
INSERT INTO `recipe_step` VALUES (500038, 300006, 5, '【准备原料】胡萝卜切末（作为馅料用，所以要求尽量细碎，可用乱刀）', NULL);
INSERT INTO `recipe_step` VALUES (500039, 300006, 6, '【烹饪】热锅冷油，宽油起锅。', NULL);
INSERT INTO `recipe_step` VALUES (500040, 300006, 7, '【烹饪】待油烧热后，放入蒜末爆香。', NULL);
INSERT INTO `recipe_step` VALUES (500041, 300006, 8, '【烹饪】加入腌制的肉沫，翻炒，直至断生。', NULL);
INSERT INTO `recipe_step` VALUES (500042, 300006, 9, '【烹饪】将胡萝卜末加入肉沫中一同翻炒，直至油被染为金黄色（这是为了萃取胡萝卜的风味）。', NULL);
INSERT INTO `recipe_step` VALUES (500043, 300006, 10, '【烹饪】关火。冷却 2 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500044, 300006, 11, '【烹饪】将炒好的肉沫倒入生面糊中，搅匀。', NULL);
INSERT INTO `recipe_step` VALUES (500045, 300006, 12, '【烹饪】重新开火，平底锅铺底油。', NULL);
INSERT INTO `recipe_step` VALUES (500046, 300006, 13, '【烹饪】调至小火，将面糊倒入锅中均匀铺满。保证厚度不要过高。可以端起锅，让面糊流过锅底来完成这一操作。', NULL);
INSERT INTO `recipe_step` VALUES (500047, 300006, 14, '【烹饪】在饼的表面尚为液态时，撒上大葱段。', NULL);
INSERT INTO `recipe_step` VALUES (500048, 300006, 15, '【烹饪】保持小火，直到底面凝固。', NULL);
INSERT INTO `recipe_step` VALUES (500049, 300006, 16, '【烹饪】将饼翻面，继续小火煎烤，直至另一侧凝固。', NULL);
INSERT INTO `recipe_step` VALUES (500050, 300006, 17, '【烹饪】之后，每一面再额外煎 20 秒。', NULL);
INSERT INTO `recipe_step` VALUES (500051, 300006, 18, '【烹饪】关火出锅。', NULL);
INSERT INTO `recipe_step` VALUES (500052, 300007, 1, '【鸭肉焯水以去腥去血水】鸭肉清洗一遍放进锅中', NULL);
INSERT INTO `recipe_step` VALUES (500053, 300007, 2, '【鸭肉焯水以去腥去血水】加清水淹没鸭肉', NULL);
INSERT INTO `recipe_step` VALUES (500054, 300007, 3, '【鸭肉焯水以去腥去血水】加 20 ml 料酒', NULL);
INSERT INTO `recipe_step` VALUES (500055, 300007, 4, '【鸭肉焯水以去腥去血水】加备用的 1 根 大葱', NULL);
INSERT INTO `recipe_step` VALUES (500056, 300007, 5, '【鸭肉焯水以去腥去血水】加生姜 ,拍散的 2 厘米', NULL);
INSERT INTO `recipe_step` VALUES (500057, 300007, 6, '【鸭肉焯水以去腥去血水】开火烧滚', NULL);
INSERT INTO `recipe_step` VALUES (500058, 300007, 7, '【鸭肉焯水以去腥去血水】捞出浮沫', NULL);
INSERT INTO `recipe_step` VALUES (500059, 300007, 8, '【鸭肉焯水以去腥去血水】鸭肉捞出，清水洗干净备用', NULL);
INSERT INTO `recipe_step` VALUES (500060, 300007, 9, '【开始煮】锅清洗干净烧热，加 60ml 的花生油', NULL);
INSERT INTO `recipe_step` VALUES (500061, 300007, 10, '【开始煮】油温到 60 度的时候，加一把花椒（ 30 颗）', NULL);
INSERT INTO `recipe_step` VALUES (500062, 300007, 11, '【开始煮】加鸭肉翻炒 4 分钟 2 分钟后加入所有的香料 3 分钟的时候加入所有的料头（生姜，大蒜，小米辣）', NULL);
INSERT INTO `recipe_step` VALUES (500063, 300007, 12, '【开始煮】加入 1000 ml 的啤酒', NULL);
INSERT INTO `recipe_step` VALUES (500064, 300007, 13, '【开始煮】烧鸭肉 30 分钟 10 分钟的时候加 盐 （3 克） 生抽( 10 ml ) 老抽( 5 ml) 20 分钟 加入所有的辅料 （青椒和红椒段） 29 分钟加入 蒜苗段 和 大葱段 翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500065, 300007, 14, '【开始煮】出锅', NULL);
INSERT INTO `recipe_step` VALUES (500066, 300008, 1, '大白菜只取内部嫩叶（黄色部分），去除菜帮，用手撕成半个巴掌大的块，不要用刀切（手撕截面粗糙更易挂酱）', NULL);
INSERT INTO `recipe_step` VALUES (500067, 300008, 2, '将撕好的白菜叶冲洗干净，充分控干水分，水分残留会导致酱汁无法挂附', NULL);
INSERT INTO `recipe_step` VALUES (500068, 300008, 3, '碗中加入 30g 芝麻酱，先加入 45ml 陈醋，沿同一方向搅拌，将麻酱慢慢稀释开，直至成细线状滴落为止（切勿来回搅拌，会导致芝麻酱\"走油\"）', NULL);
INSERT INTO `recipe_step` VALUES (500069, 300008, 4, '向麻酱汁中加入 5g 白糖，搅拌均匀；再加入 1g 食盐，搅拌均匀；最后加入 5ml 香油，搅拌均匀（各调料需分次加入并分别搅拌，边加边感受稀稠度）', NULL);
INSERT INTO `recipe_step` VALUES (500070, 300008, 5, '将调好的麻酱汁均匀淋在白菜叶上，用手轻轻抓拌，使每片菜叶都裹上酱汁', NULL);
INSERT INTO `recipe_step` VALUES (500071, 300008, 6, '撒上熟白芝麻，装盘即可食用；若时间充裕，可静置 5 分钟待其入味后再食用', NULL);
INSERT INTO `recipe_step` VALUES (500072, 300009, 1, '将大麦若叶拉面在煮面篓中煮约30 秒，捞出用直饮水冲凉，沥干水分后放入份盒中。按照每份面（煮熟后约220g）加入8g 菜籽油的比例，搅拌均匀；', NULL);
INSERT INTO `recipe_step` VALUES (500073, 300009, 2, '在面碗中，先放入220g 搅拌均匀的含油面条，然后均匀放入40g 自制拌面汁，最后依次摆入30g 蛋皮丝（需要在煮面篓中烫制10 秒后沥干水分）、30g 黄瓜丝、30g 焯水后绿豆芽、30g 焯水后胡萝卜丝、30g 老母鸡鸡丝，出品。', NULL);
INSERT INTO `recipe_step` VALUES (500074, 300010, 1, '锅中下入75g 大豆油，将250g 鸡蛋液炒成蛋片；', NULL);
INSERT INTO `recipe_step` VALUES (500075, 300010, 2, '下入150g 三色杂菜、100g 香肠丁，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (500076, 300010, 3, '再下入1500g 米饭、8g 盐，翻炒均匀。', NULL);
INSERT INTO `recipe_step` VALUES (500077, 300011, 1, '6 个鸡翅尖无需解冻直接放入170℃的油锅中炸制3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500078, 300012, 1, '底汤调配： 500g 冒烤鸭底料、2500g 白开水，搅拌融化后，熬煮 3 分钟备用；', NULL);
INSERT INTO `recipe_step` VALUES (500079, 300012, 2, '取 50g 绿豆芽、50g 千张丝下入沸水中汆烫 2 分钟，沥水后倒入餐具中，再加入 20g 蒜末和 30g 冒菜红油；', NULL);
INSERT INTO `recipe_step` VALUES (500080, 300012, 3, '锅中倒入 300g 底汤、300g 烤鸭块，煮 4 分钟后，倒在绿豆芽和千张丝上，出品撒 3g 白芝麻、2g 葱花和 2g 香菜点缀。', NULL);
INSERT INTO `recipe_step` VALUES (500081, 300013, 1, '备菜阶段：将猪肉切片，最好把肥瘦分开放。同时要把青椒和小米辣切成段，蒜片用刀背拍成末，姜切成丝。鸡蛋打到小碗中，用筷子打散。', NULL);
INSERT INTO `recipe_step` VALUES (500082, 300013, 2, '备好菜，就可正式煮菜了。先将油倒入锅中，锅中开小火，油热后将蛋液倒入锅中，将鸡蛋炒散，炒至断生即可，放回小碗中备用。', NULL);
INSERT INTO `recipe_step` VALUES (500083, 300013, 3, '将锅中继续加一点油，开小火，锅热后将之前切的肥猪肉倒入锅中逼出猪油。', NULL);
INSERT INTO `recipe_step` VALUES (500084, 300013, 4, '肥肉出现金黄色的时候，加大火力到中火，将瘦肉一起放入锅中翻炒。', NULL);
INSERT INTO `recipe_step` VALUES (500085, 300013, 5, '瘦肉全部炒至变色的时候加入备好的姜丝、蒜末和豆瓣酱翻炒均匀给猪肉上色。', NULL);
INSERT INTO `recipe_step` VALUES (500086, 300013, 6, '放入青红椒、炒至断生的鸡蛋后加入酱油和白糖，继续将它们翻炒到青椒微微断生，保持青椒清脆口感。', NULL);
INSERT INTO `recipe_step` VALUES (500087, 300013, 7, '出锅上菜！', NULL);
INSERT INTO `recipe_step` VALUES (500088, 300014, 1, '将200g肥肉片用60g大豆油煸炒至油脂渗出；', NULL);
INSERT INTO `recipe_step` VALUES (500089, 300014, 2, '下入60g蒜子炒香，再下入800g瘦肉片炒至肉片变色；', NULL);
INSERT INTO `recipe_step` VALUES (500090, 300014, 3, '下入150g小炒肉调料，炒至肉片均匀上色，盛出暂存；', NULL);
INSERT INTO `recipe_step` VALUES (500091, 300014, 4, '将60g大豆油烧热，加入940g螺丝椒、150g玉耳、6g盐，翻炒至辣椒断生；', NULL);
INSERT INTO `recipe_step` VALUES (500092, 300014, 5, '下入煸炒好的肉片，大火翻炒出锅。', NULL);
INSERT INTO `recipe_step` VALUES (500093, 300015, 1, '将200g肥肉片用60g大豆油煸炒至油脂渗出；', NULL);
INSERT INTO `recipe_step` VALUES (500094, 300015, 2, '下入60g蒜子炒香，再下入800g瘦肉片炒至肉片变色；', NULL);
INSERT INTO `recipe_step` VALUES (500095, 300015, 3, '下入150g小炒肉调料，炒至肉片均匀上色，盛出暂存；', NULL);
INSERT INTO `recipe_step` VALUES (500096, 300015, 4, '将60g大豆油烧热，加入940g螺丝椒和6g盐，翻炒至辣椒断生；', NULL);
INSERT INTO `recipe_step` VALUES (500097, 300015, 5, '下入100g鸡蛋干和煸炒好的肉片，大火翻炒出锅。', NULL);
INSERT INTO `recipe_step` VALUES (500098, 300016, 1, '将鸡蛋打成蛋液', NULL);
INSERT INTO `recipe_step` VALUES (500099, 300016, 2, '将 650g 鸡蛋液、30g鸡油、10g清酱汁、20g盐、1800g水、30g蚕豆酱混合，并用打蛋器搅拌均匀，直至蛋清、蛋黄完全打散；', NULL);
INSERT INTO `recipe_step` VALUES (500100, 300016, 3, '过滤：用过滤网滤出蚕豆酱残渣；', NULL);
INSERT INTO `recipe_step` VALUES (500101, 300016, 4, '蒸制：蒸柜上汽后，蒸 5 分钟，焖 1 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500102, 300017, 1, '准备冬瓜：将冬瓜去皮，去籽，切成小块（每块不超过 4cm）。', NULL);
INSERT INTO `recipe_step` VALUES (500103, 300017, 2, '加入冰糖：冬瓜加入冰糖，搅拌均匀，盖上保鲜膜放冰箱冷藏 2 小时以上。', NULL);
INSERT INTO `recipe_step` VALUES (500104, 300017, 3, '煮冬瓜： 此时冬瓜出了很多水, 倒入锅中 大火煮开，然后转中小火慢慢熬制 1~2 个小时，中途多搅拌防止糊锅。', NULL);
INSERT INTO `recipe_step` VALUES (500105, 300017, 4, '过滤冬瓜茶：使用过滤网将煮好的冬瓜茶液过滤，取出冬瓜块，只保留茶液。', NULL);
INSERT INTO `recipe_step` VALUES (500106, 300017, 5, '冷却：将冬瓜茶液放凉后，倒入干净的容器中，放入冰箱冷藏即可。', NULL);
INSERT INTO `recipe_step` VALUES (500107, 300017, 6, '享用: 熬好的冬瓜茶液是浓缩汁，根据个人喜好添加水或其他饮品，冷热皆宜。', NULL);
INSERT INTO `recipe_step` VALUES (500108, 300018, 1, '冬瓜去皮，切成 25cm 长 3cm 厚的片', NULL);
INSERT INTO `recipe_step` VALUES (500109, 300018, 2, '将切好的冬瓜放入碗中，放入 15g 盐，将冬瓜抹匀，放置 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500110, 300018, 3, '放置冬瓜的同时，换个碗放入肉末，葱姜末， 5g 盐，淀粉 5g，胡椒粉，生抽，胡椒粉', NULL);
INSERT INTO `recipe_step` VALUES (500111, 300018, 4, '使用筷子在肉末中进行顺时针搅拌，搅拌到食材颜色没有明显对比（约 2 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (500112, 300018, 5, '将腌制好的冬瓜（会变软）使用清水洗三遍', NULL);
INSERT INTO `recipe_step` VALUES (500113, 300018, 6, '拿出 1 片冬瓜片卷起来，并把肉塞进去', NULL);
INSERT INTO `recipe_step` VALUES (500114, 300018, 7, '放入碟子中摆到碟子的边缘', NULL);
INSERT INTO `recipe_step` VALUES (500115, 300018, 8, '打入 1 个鸡蛋到中间圆圈处', NULL);
INSERT INTO `recipe_step` VALUES (500116, 300018, 9, '放入普通铁锅中水烧开后，蒸 15 分钟，盖上锅盖', NULL);
INSERT INTO `recipe_step` VALUES (500117, 300018, 10, '开盖，取出蒸好的冬瓜酿肉', NULL);
INSERT INTO `recipe_step` VALUES (500118, 300018, 11, '将冬瓜酿肉碟子的水倒入锅中，放入水淀粉，加入 50ml 清水倒入锅中烧开', NULL);
INSERT INTO `recipe_step` VALUES (500119, 300018, 12, '淋到冬瓜酿肉上', NULL);
INSERT INTO `recipe_step` VALUES (500120, 300019, 1, '将凉白开倒入盆中；', NULL);
INSERT INTO `recipe_step` VALUES (500121, 300019, 2, '将冰粉籽全部用纱布包起来，开口处打结', NULL);
INSERT INTO `recipe_step` VALUES (500122, 300019, 3, '将包好的冰粉籽放入凉白开中，在凉白开中用力揉搓 6 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500123, 300019, 4, '然后将凉白开放置 2.5 小时，即可成型', NULL);
INSERT INTO `recipe_step` VALUES (500124, 300019, 5, '随后将石凉粉用勺子装进准备好的一次性透明塑料杯中，加入 10ml 薄荷汁或者 10g 薄荷粉（柠檬汁、山楂汁、桑椹汁也可），再放入遇水发光冰块，用勺子慢慢搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (500125, 300020, 1, '蒜、姜扒皮并剁碎备用，八角、桂皮、香叶、山奈、白蔻、小茴香洗净备用。', NULL);
INSERT INTO `recipe_step` VALUES (500126, 300020, 2, '干辣椒剪成 2 厘米的小段，洗净备用。', NULL);
INSERT INTO `recipe_step` VALUES (500127, 300020, 3, '小葱/大葱/洋葱洗净，洋葱切成小块。', NULL);
INSERT INTO `recipe_step` VALUES (500128, 300020, 4, '兔肉剁成 2 厘米的小块，加入盐、料酒、味精调味，腌制 15 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500129, 300020, 5, '锅中倒油，油温 4 成热下小葱/大葱/洋葱，中小火煸炒出香味，待到小葱/大葱/洋葱微焦，将其捞出。', NULL);
INSERT INTO `recipe_step` VALUES (500130, 300020, 6, '开大火升高油温，油温 8 成热时下入兔肉，炸制过程转中小火，炸至兔肉微微焦黄时捞出兔肉。', NULL);
INSERT INTO `recipe_step` VALUES (500131, 300020, 7, '升高油温，倒入干辣椒、青花椒、八角、桂皮、香叶、山奈、白蔻、小茴香；转小火将辣椒段炸脆。', NULL);
INSERT INTO `recipe_step` VALUES (500132, 300020, 8, '重新倒入兔肉，加入蚝油、翻炒几分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500133, 300020, 9, '关火，加入蒜、姜、白芝麻，翻炒均匀。', NULL);
INSERT INTO `recipe_step` VALUES (500134, 300020, 10, '放置一夜更加入味。', NULL);
INSERT INTO `recipe_step` VALUES (500135, 300021, 1, '泡发干木耳, 水量约为 400ml, 泡发约 45 分钟。 （湿木耳跳过此步骤）', NULL);
INSERT INTO `recipe_step` VALUES (500136, 300021, 2, '将泡发好的木耳, 进行去根处理（如图 4, 5, 6）, 并彻底洗净。', NULL);
INSERT INTO `recipe_step` VALUES (500137, 300021, 3, '起锅烧水，水开后放入木耳, 大火煮 1.5-2 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500138, 300021, 4, '将蒜瓣、小米辣切碎放入碗中 （可选取中大碗）, 并依次加入盐、糖、生抽、醋、香油、芥末, 用量如上。', NULL);
INSERT INTO `recipe_step` VALUES (500139, 300021, 5, '木耳盛出后沥水, 放入上一步碗中。', NULL);
INSERT INTO `recipe_step` VALUES (500140, 300021, 6, '搅拌充分，端盘。', NULL);
INSERT INTO `recipe_step` VALUES (500141, 300022, 1, '蒜拍碎切末', NULL);
INSERT INTO `recipe_step` VALUES (500142, 300022, 2, '醋，酱油，芝麻酱，香油，糖，蚝油，蒜末放到碗里搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (500143, 300022, 3, '油麦菜切段，每段不超过 4cm', NULL);
INSERT INTO `recipe_step` VALUES (500144, 300022, 4, '油麦菜放到一个大点的盆里，倒入上述碗中酱料，充分搅拌均匀.', NULL);
INSERT INTO `recipe_step` VALUES (500145, 300023, 1, '莴笋削皮，切小条。萝卜切条，一起放入大碗，加入盐搅拌，放置 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500146, 300023, 2, '放置后的莴笋用水清洗 1-2 遍', NULL);
INSERT INTO `recipe_step` VALUES (500147, 300023, 3, '起锅烧水，放入莴笋，水煮 1 分钟 捞出，沥干水分，放入大碗', NULL);
INSERT INTO `recipe_step` VALUES (500148, 300023, 4, '起锅烧油，放入姜片、蒜粒、小米椒煸炒 30-45 S ，倒入莴笋中', NULL);
INSERT INTO `recipe_step` VALUES (500149, 300023, 5, '搅拌充分，端盘', NULL);
INSERT INTO `recipe_step` VALUES (500150, 300024, 1, '将1100g 莴笋丝，清洗干净后用纯净水再次冲洗，沥干水分备用；', NULL);
INSERT INTO `recipe_step` VALUES (500151, 300024, 2, '冲洗后的莴笋丝加入12g 盐腌制10 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500152, 300024, 3, '将腌制后的莴笋丝沥干水分，加入15g 红椒、30g 芝麻香油、10g 鸡精、5g 白砂糖，翻拌均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (500153, 300025, 1, '将 豆腐 切成 2 cm 见方的小块，备用。', NULL);
INSERT INTO `recipe_step` VALUES (500154, 300025, 2, '锅中加入 500 ml 饮用水，大火烧开。', NULL);
INSERT INTO `recipe_step` VALUES (500155, 300025, 3, '放入 豆腐 块，煮 1-2 分钟，以去除豆腥味并使豆腐口感更紧实。', NULL);
INSERT INTO `recipe_step` VALUES (500156, 300025, 4, '将 煮好的 豆腐 块捞出，沥干水分，放入碗中，备用。', NULL);
INSERT INTO `recipe_step` VALUES (500157, 300025, 5, '将 小葱 洗净，切成葱花，备用。', NULL);
INSERT INTO `recipe_step` VALUES (500158, 300025, 6, '将 大蒜 去皮，切成蒜末，备用。', NULL);
INSERT INTO `recipe_step` VALUES (500159, 300025, 7, '在一个干净的小碗中，加入 15 ml 生抽，5 ml 香油，5 ml 醋（可选），2 g 白糖（可选）。', NULL);
INSERT INTO `recipe_step` VALUES (500160, 300025, 8, '加入切好的 大蒜末。', NULL);
INSERT INTO `recipe_step` VALUES (500161, 300025, 9, '搅拌均匀，使 白糖 充分溶解，酱汁混合均匀。', NULL);
INSERT INTO `recipe_step` VALUES (500162, 300025, 10, '将制作好的酱汁均匀淋在 豆腐 块上。', NULL);
INSERT INTO `recipe_step` VALUES (500163, 300025, 11, '撒上切好的 小葱花。', NULL);
INSERT INTO `recipe_step` VALUES (500164, 300025, 12, '根据个人喜好，淋上 5 ml 辣椒油（可选）。', NULL);
INSERT INTO `recipe_step` VALUES (500165, 300025, 13, '用 筷子 或勺子轻轻拌匀，即可食用。', NULL);
INSERT INTO `recipe_step` VALUES (500166, 300026, 1, '将 金针菇 根部切除，用清水冲洗干净，备用。', NULL);
INSERT INTO `recipe_step` VALUES (500167, 300026, 2, '将 小葱 洗净，切成葱花，备用。', NULL);
INSERT INTO `recipe_step` VALUES (500168, 300026, 3, '将 大蒜 去皮，切成蒜末，备用。', NULL);
INSERT INTO `recipe_step` VALUES (500169, 300026, 4, '锅中加入 1000 ml 饮用水，大火烧开。', NULL);
INSERT INTO `recipe_step` VALUES (500170, 300026, 5, '放入 金针菇，煮 1-2 分钟，至金针菇变软。', NULL);
INSERT INTO `recipe_step` VALUES (500171, 300026, 6, '将 煮好的 金针菇 捞出，沥干水分，放入一个较大的碗中，备用。', NULL);
INSERT INTO `recipe_step` VALUES (500172, 300026, 7, '在另一个干净的小碗中，加入 15 ml 生抽，10 ml 醋，3 g 白糖（可选），5 ml 香油（可选）。', NULL);
INSERT INTO `recipe_step` VALUES (500173, 300026, 8, '加入切好的 大蒜末。', NULL);
INSERT INTO `recipe_step` VALUES (500174, 300026, 9, '搅拌均匀，使 白糖 充分溶解，酱汁混合均匀。', NULL);
INSERT INTO `recipe_step` VALUES (500175, 300026, 10, '将制作好的酱汁均匀淋在 金针菇 上。', NULL);
INSERT INTO `recipe_step` VALUES (500176, 300026, 11, '撒上切好的 小葱花。', NULL);
INSERT INTO `recipe_step` VALUES (500177, 300026, 12, '根据个人喜好，淋上 5 ml 辣椒油（可选）。', NULL);
INSERT INTO `recipe_step` VALUES (500178, 300026, 13, '用 筷子 轻轻拌匀，即可食用。', NULL);
INSERT INTO `recipe_step` VALUES (500179, 300027, 1, '姜切片，备用', NULL);
INSERT INTO `recipe_step` VALUES (500180, 300027, 2, '锅中倒入 4 升水', NULL);
INSERT INTO `recipe_step` VALUES (500181, 300027, 3, '加入鸡胸肉、姜片', NULL);
INSERT INTO `recipe_step` VALUES (500182, 300027, 4, '倒入 20 毫升料酒', NULL);
INSERT INTO `recipe_step` VALUES (500183, 300027, 5, '开大火不盖盖将水烧开', NULL);
INSERT INTO `recipe_step` VALUES (500184, 300027, 6, '水开后转中火，用勺子将浮沫捞出', NULL);
INSERT INTO `recipe_step` VALUES (500185, 300027, 7, '继续煮 5-7 分钟，如果是非冷冻肉煮 5 分钟，冷冻肉煮 7 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500186, 300027, 8, '鸡胸肉大小会影响成熟时间，用筷子插入鸡胸肉，如果能轻松插入，代表鸡肉熟了。如果不熟需延长煮制时间', NULL);
INSERT INTO `recipe_step` VALUES (500187, 300027, 9, '用凉白开水冲泡鸡胸肉，使鸡胸肉降至室温', NULL);
INSERT INTO `recipe_step` VALUES (500188, 300027, 10, '顺着鸡胸肉纹理将鸡胸肉撕成细丝', NULL);
INSERT INTO `recipe_step` VALUES (500189, 300027, 11, '准备一个碗', NULL);
INSERT INTO `recipe_step` VALUES (500190, 300027, 12, '碗中加入准备好的麻油、生抽、香醋、白糖、盐', NULL);
INSERT INTO `recipe_step` VALUES (500191, 300027, 13, '搅拌料汁，使糖和盐尽量溶化', NULL);
INSERT INTO `recipe_step` VALUES (500192, 300027, 14, '将料汁倒入鸡丝中，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (500193, 300028, 1, '用菜刀将黄瓜拍扁，再剁成长 3 厘米的碎块', NULL);
INSERT INTO `recipe_step` VALUES (500194, 300028, 2, '将碎黄瓜装入碗中', NULL);
INSERT INTO `recipe_step` VALUES (500195, 300028, 3, '将蒜拍碎切成碎末', NULL);
INSERT INTO `recipe_step` VALUES (500196, 300028, 4, '将碗中放入 5 克白糖，搅拌均匀腌制 15 分钟（用糖腌制更好吃，且成色更好不会蔫）', NULL);
INSERT INTO `recipe_step` VALUES (500197, 300028, 5, '将醋，酱油，盐，蚝油和蒜依次倒入碗中搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (500198, 300028, 6, '将香油倒入碗中并均匀搅拌', NULL);
INSERT INTO `recipe_step` VALUES (500199, 300029, 1, '【准备工作】锅中加入 500ml 水。煮沸。', NULL);
INSERT INTO `recipe_step` VALUES (500200, 300029, 2, '【准备工作】将绿豆芽放入锅中，大火煮 60 秒。豆芽捞出，过凉水，放入盘中备用。', NULL);
INSERT INTO `recipe_step` VALUES (500201, 300029, 3, '【准备工作】黄瓜切丝放入盘中备用', NULL);
INSERT INTO `recipe_step` VALUES (500202, 300029, 4, '【准备工作】将 10g 蒜瓣剥皮、放入蒜臼中加入 1g 盐。锤成蒜泥，加入 10g 自来水。放置备用。', NULL);
INSERT INTO `recipe_step` VALUES (500203, 300029, 5, '【准备工作】注：超市购买来的凉皮表面一般会有食用油，可以使用自来水清洗。面筋同样。', NULL);
INSERT INTO `recipe_step` VALUES (500204, 300029, 6, '【准备工作】注：清洗面筋之后，请用手将面筋中的大量水分挤出（不需过于用力）。', NULL);
INSERT INTO `recipe_step` VALUES (500205, 300029, 7, '【盐水调配】准备小碗，加入 3g 盐、2g 鸡精、5g 生抽、1g 老抽、1g 香油、2g 蚝油、香醋 5g、（盐、香醋均可根据个人口味酌量添加，以上数据只是大众口味）。', NULL);
INSERT INTO `recipe_step` VALUES (500206, 300029, 8, '【盐水调配】以上调料加入 25-35g 温水（据个人咸淡程度），使用筷子将其拌匀、溶解。静置一旁冷却。', NULL);
INSERT INTO `recipe_step` VALUES (500207, 300029, 9, '【芝麻酱调配】注：以下计量均为一人份，如果有 n 人，请自觉将计量乘以 n', NULL);
INSERT INTO `recipe_step` VALUES (500208, 300029, 10, '【芝麻酱调配】拿出小碗，将准备好的芝麻酱放入其中。', NULL);
INSERT INTO `recipe_step` VALUES (500209, 300029, 11, '【芝麻酱调配】加入 4g 盐、3g 鸡精、5g 生抽、1g 老抽、3g 蚝油。', NULL);
INSERT INTO `recipe_step` VALUES (500210, 300029, 12, '【芝麻酱调配】使用筷子将其调料与芝麻酱拌匀。', NULL);
INSERT INTO `recipe_step` VALUES (500211, 300029, 13, '【芝麻酱调配】加入 10g 清水将其拌匀。', NULL);
INSERT INTO `recipe_step` VALUES (500212, 300029, 14, '【芝麻酱调配】上一步骤重复 2、3 次（次数根据个人对芝麻酱的浓稠程度而定）。', NULL);
INSERT INTO `recipe_step` VALUES (500213, 300029, 15, '【最终步骤】拿出之前准备好的小盆，加入之前准备好的凉皮。', NULL);
INSERT INTO `recipe_step` VALUES (500214, 300029, 16, '【最终步骤】倒入盐水，使用筷子将其拌匀。随之盛入小碗（盐水一并倒入碗中）。', NULL);
INSERT INTO `recipe_step` VALUES (500215, 300029, 17, '【最终步骤】豆芽放置凉皮上、面筋随后放上。', NULL);
INSERT INTO `recipe_step` VALUES (500216, 300029, 18, '【最终步骤】将调配好的芝麻酱从面筋上方倒下。', NULL);
INSERT INTO `recipe_step` VALUES (500217, 300029, 19, '【最终步骤】撒上黄瓜丝。', NULL);
INSERT INTO `recipe_step` VALUES (500218, 300029, 20, '【最终步骤】如有喜爱可以加入辣椒油。', NULL);
INSERT INTO `recipe_step` VALUES (500219, 300029, 21, '【最终步骤】色香味俱全的家常凉皮出炉！', NULL);
INSERT INTO `recipe_step` VALUES (500220, 300030, 1, '准备食材。', NULL);
INSERT INTO `recipe_step` VALUES (500221, 300030, 2, '把豌豆淀粉和水各 100 克混合搅拌。', NULL);
INSERT INTO `recipe_step` VALUES (500222, 300030, 3, '往锅中倒入 600g 水，大火煮开后转为小火。', NULL);
INSERT INTO `recipe_step` VALUES (500223, 300030, 4, '倒入淀粉水，边倒边不断的搅拌，搅拌到浓稠且色泽均匀。', NULL);
INSERT INTO `recipe_step` VALUES (500224, 300030, 5, '找一个容器，在容器中刷一层薄薄的食用油。', NULL);
INSERT INTO `recipe_step` VALUES (500225, 300030, 6, '将煮好的淀粉倒入容器中冷藏 2-4 小时。', NULL);
INSERT INTO `recipe_step` VALUES (500226, 300030, 7, '冷藏后取出，脱模，切条。', NULL);
INSERT INTO `recipe_step` VALUES (500227, 300030, 8, '大蒜和小米辣剁成沫，放上 10g 辣椒粉，5g 花生碎，热油搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (500228, 300030, 9, '再加入 10ml 酱油，10ml 醋，5g 白糖，3g 鸡精，3g 盐搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (500229, 300030, 10, '将调味料倒在凉粉上，然后撒上香菜即可。', NULL);
INSERT INTO `recipe_step` VALUES (500230, 300031, 1, '将咸鸡爪或咸鸭爪清洗干净，咸鸡爪蒸制 50 分钟或咸鸭爪蒸制 25 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500231, 300031, 2, '将 120g 豆米放入餐具，撒上 1g 盐、1g 鸡精、10g 鸡油；', NULL);
INSERT INTO `recipe_step` VALUES (500232, 300031, 3, '将 40g 蒸制后的爪子平铺在豆米上，并加入 20g 老鸡汤；', NULL);
INSERT INTO `recipe_step` VALUES (500233, 300031, 4, '蒸柜上汽后，蒸制 12 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500234, 300032, 1, '【制作利提馅料】在碗中混合烤鹰嘴豆粉 120g、切碎的洋葱、青辣椒、生姜', NULL);
INSERT INTO `recipe_step` VALUES (500235, 300032, 2, '【制作利提馅料】加入孜然籽 3g、芝麻 5g、红辣椒粉 3g、印度黑盐 3g、盐 3g', NULL);
INSERT INTO `recipe_step` VALUES (500236, 300032, 3, '【制作利提馅料】加入芥末油 15ml、柠檬汁 10ml、切碎的香菜叶', NULL);
INSERT INTO `recipe_step` VALUES (500237, 300032, 4, '【制作利提馅料】充分混合均匀，馅料应呈松散但可捏合的状态，备用', NULL);
INSERT INTO `recipe_step` VALUES (500238, 300032, 5, '【制作利提面团】将全麦面粉 200g 放入大碗中', NULL);
INSERT INTO `recipe_step` VALUES (500239, 300032, 6, '【制作利提面团】逐渐加入温水，边加边揉，揉成光滑柔软的面团', NULL);
INSERT INTO `recipe_step` VALUES (500240, 300032, 7, '【制作利提面团】面团静置 15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500241, 300032, 8, '【制作利提面团】将面团分成 8 个等大的小剂子', NULL);
INSERT INTO `recipe_step` VALUES (500242, 300032, 9, '【制作利提面团】每个剂子用手压成一个直径约 8cm 的圆形面片（中间稍厚）', NULL);
INSERT INTO `recipe_step` VALUES (500243, 300032, 10, '【制作利提面团】在面片中央放入约 15g 馅料', NULL);
INSERT INTO `recipe_step` VALUES (500244, 300032, 11, '【制作利提面团】将面片四周收拢包住馅料，封口处捏紧，搓成圆球', NULL);
INSERT INTO `recipe_step` VALUES (500245, 300032, 12, '【烤制利提】烤箱预热至 200°C', NULL);
INSERT INTO `recipe_step` VALUES (500246, 300032, 13, '【烤制利提】将利提放在烤盘上，烤 25-30 分钟，期间翻面一次，直至表面金棕色且有裂纹', NULL);
INSERT INTO `recipe_step` VALUES (500247, 300032, 14, '【烤制利提】如果使用明火：将利提直接放在炭火或煤气灶小火上烤，不断翻转，直至均匀焦黄', NULL);
INSERT INTO `recipe_step` VALUES (500248, 300032, 15, '【烤制利提】烤好后趁热将每个利提表面涂上酥油，使其浸润吸收', NULL);
INSERT INTO `recipe_step` VALUES (500249, 300032, 16, '【制作巧卡】将茄子、番茄、土豆放在明火上直接烤，或放入 200°C 烤箱烤 20-25 分钟，直至外皮焦黑、内部完全软烂', NULL);
INSERT INTO `recipe_step` VALUES (500250, 300032, 17, '【制作巧卡】烤好后去皮，将茄子、番茄、土豆分别用叉子或手捣碎', NULL);
INSERT INTO `recipe_step` VALUES (500251, 300032, 18, '【制作巧卡】将捣碎的蔬菜混合在一起', NULL);
INSERT INTO `recipe_step` VALUES (500252, 300032, 19, '【制作巧卡】加入切碎的大蒜、青辣椒、盐 4g、芥末油 15ml', NULL);
INSERT INTO `recipe_step` VALUES (500253, 300032, 20, '【制作巧卡】充分搅拌混合均匀', NULL);
INSERT INTO `recipe_step` VALUES (500254, 300032, 21, '【制作巧卡】撒上香菜叶装饰', NULL);
INSERT INTO `recipe_step` VALUES (500255, 300032, 22, '【上菜】将利提摆盘，旁边放上巧卡蔬菜泥', NULL);
INSERT INTO `recipe_step` VALUES (500256, 300032, 23, '【上菜】趁热食用，用手掰开利提蘸巧卡', NULL);
INSERT INTO `recipe_step` VALUES (500257, 300033, 1, '10 份混合鸡蛋液调配：800g 鸡蛋液、50g 剁椒、6g 盐；', NULL);
INSERT INTO `recipe_step` VALUES (500258, 300033, 2, '下入 170g 菜籽油、10 份混合鸡蛋液，炒成鸡蛋片，出锅备用；', NULL);
INSERT INTO `recipe_step` VALUES (500259, 300033, 3, '下入 80g 菜籽油、800g 木耳、60g 蒜子、6g 盐、6g 鸡精，大火爆炒 1 分 10 秒；', NULL);
INSERT INTO `recipe_step` VALUES (500260, 300033, 4, '最后下入鸡蛋片、60g 葱段，大火爆炒 30 秒出品。', NULL);
INSERT INTO `recipe_step` VALUES (500261, 300034, 1, '单份鱼头上均匀平铺 120g 剁椒鱼头料；', NULL);
INSERT INTO `recipe_step` VALUES (500262, 300034, 2, '蒸柜上汽后，蒸制 10 分钟，出品时撒 1g 葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (500263, 300035, 1, '单份鱼头上均匀平铺120g剁椒鱼头料；', NULL);
INSERT INTO `recipe_step` VALUES (500264, 300035, 2, '蒸柜上汽后，蒸制10分钟，出品时撒1g葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (500265, 300036, 1, '单份鱼头上均匀平铺120g剁椒鱼头料；', NULL);
INSERT INTO `recipe_step` VALUES (500266, 300036, 2, '蒸柜上汽后，蒸制25分钟，出品时撒1g葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (500267, 300037, 1, '香菇切片（每片厚度 0.5-1 cm,厚点相对薄点更有嚼劲），放入大碗中，倒入 2g 食用盐 浸泡 15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500268, 300037, 2, '生粉倒入小碗中，加入 50ml 水，搅拌生粉直至融化没有颗粒（即水淀粉）', NULL);
INSERT INTO `recipe_step` VALUES (500269, 300037, 3, '倒掉碗中的盐水，适当去掉香菇本身的水分（方便下一步煎炸）【可选】', NULL);
INSERT INTO `recipe_step` VALUES (500270, 300037, 4, '小火，倒入油，待油开始冒小泡（小火 30s ，看每个锅的功率），倒入香菇，每面煎 10s 【可选】', NULL);
INSERT INTO `recipe_step` VALUES (500271, 300037, 5, '倒入开水 300ml ，调中火再煮 3-5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500272, 300037, 6, '倒入水淀粉，适当搅拌锅中汤汁后，加入 3g 盐、3 g ，最后撒上葱花出锅', NULL);
INSERT INTO `recipe_step` VALUES (500273, 300038, 1, '蒸柜上汽后，手工香菇青菜包蒸制 10 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500274, 300038, 2, '手工鲜肉包、手工麻辣海带包、牛肉粉丝包蒸制 12 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500275, 300038, 3, '大肉包蒸制 15 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500276, 300039, 1, '下入200g大豆油、600g鸡蛋液，炒成蛋片，出锅备用；', NULL);
INSERT INTO `recipe_step` VALUES (500277, 300039, 2, '下入150g熟猪油、60g蒜子，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (500278, 300039, 3, '下入1200g圆包菜、200g胡萝卜丝、13g盐、10g鸡精、50g生抽，大火翻炒2分钟；再下入鸡蛋片，炒制1分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (500279, 300040, 1, '胡萝卜、包菜切丝备用', NULL);
INSERT INTO `recipe_step` VALUES (500280, 300040, 2, '粉丝先用冷水浸泡 1 小时，然后将粉丝放入锅中，加入开水烧至粉丝烫软捞出备用', NULL);
INSERT INTO `recipe_step` VALUES (500281, 300040, 3, '鸡蛋打入碗中，加入盐后搅拌 15 秒', NULL);
INSERT INTO `recipe_step` VALUES (500282, 300040, 4, '葱、蒜、辣椒切成小粒备用', NULL);
INSERT INTO `recipe_step` VALUES (500283, 300040, 5, '起锅烧油，倒入鸡蛋，打散炒熟盛出', NULL);
INSERT INTO `recipe_step` VALUES (500284, 300040, 6, '再倒入油，放入葱、蒜、干辣椒翻炒 8 秒', NULL);
INSERT INTO `recipe_step` VALUES (500285, 300040, 7, '下胡萝卜、包菜丝儿翻炒 30 秒', NULL);
INSERT INTO `recipe_step` VALUES (500286, 300040, 8, '放入粉丝', NULL);
INSERT INTO `recipe_step` VALUES (500287, 300040, 9, '放调料，生抽 15 ml，老抽 10 ml，蚝油 10 ml，盐 2 克', NULL);
INSERT INTO `recipe_step` VALUES (500288, 300040, 10, '放入之前炒好的鸡蛋，翻炒约 15 秒', NULL);
INSERT INTO `recipe_step` VALUES (500289, 300040, 11, '出锅摆盘', NULL);
INSERT INTO `recipe_step` VALUES (500290, 300041, 1, '【方法一 - 平底锅】热锅', NULL);
INSERT INTO `recipe_step` VALUES (500291, 300041, 2, '【方法一 - 平底锅】将 50 ml 清水倒入平底锅', NULL);
INSERT INTO `recipe_step` VALUES (500292, 300041, 3, '【方法一 - 平底锅】将面条放入，炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500293, 300041, 4, '【方法一 - 平底锅】将酱料倒入，翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500294, 300041, 5, '【方法一 - 平底锅】装盘即可', NULL);
INSERT INTO `recipe_step` VALUES (500295, 300041, 6, '【方法二 - 微波炉】将面条放入「可用于微波炉加热」的盘子中', NULL);
INSERT INTO `recipe_step` VALUES (500296, 300041, 7, '【方法二 - 微波炉】将附带的酱料倒在面条上', NULL);
INSERT INTO `recipe_step` VALUES (500297, 300041, 8, '【方法二 - 微波炉】倒入 50 ml 清水', NULL);
INSERT INTO `recipe_step` VALUES (500298, 300041, 9, '【方法二 - 微波炉】700W 加热 2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500299, 300041, 10, '【方法二 - 微波炉】取出拌匀即可', NULL);
INSERT INTO `recipe_step` VALUES (500300, 300042, 1, '猪五花肉先不切小块，切成能放入锅中的大块（约 5–6cm 宽）即可', NULL);
INSERT INTO `recipe_step` VALUES (500301, 300042, 2, '生姜切片（每片厚度约 3mm ）', NULL);
INSERT INTO `recipe_step` VALUES (500302, 300042, 3, '开水烧开', NULL);
INSERT INTO `recipe_step` VALUES (500303, 300042, 4, '凉水自来水即可', NULL);
INSERT INTO `recipe_step` VALUES (500304, 300042, 5, '小葱小葱白色的部分葱白切成小段（小葱最佳，大葱也可以）', NULL);
INSERT INTO `recipe_step` VALUES (500305, 300042, 6, '蒜中间切开，不要拍扁，否则难以捞出以至最后收汁时影响味道', NULL);
INSERT INTO `recipe_step` VALUES (500306, 300042, 7, '请将辅料分为两个\"预备包\"： A包（去腥用）：2 片姜、2 段葱段。 B包（炖煮用）：剩下的 4 片姜、葱白、蒜瓣、花椒、八角、香叶，统一放入一个小碗中备用。', NULL);
INSERT INTO `recipe_step` VALUES (500307, 300042, 8, '凉水锅中放入五花肉大块，加入 20ml 料酒 与 A包（2 片姜、2 段葱段），煮 15 分钟去掉血腥，捞出来后洗干净；', NULL);
INSERT INTO `recipe_step` VALUES (500308, 300042, 9, '将焯过水的五花肉捞出，稍微放凉（不烫手即可），切成边长约 3cm × 3cm × 3cm 的正方体块（焯水后肉质收紧，此时切块比生肉时更容易且成品大小更均匀。3cm 切块最终成品约为 2.5cm，是最适宜入口且容易烧透的尺寸）', NULL);
INSERT INTO `recipe_step` VALUES (500309, 300042, 10, '另起锅炒糖色，注意：在此菜谱中，请采用其中提到的\"操作 2\"来制作，即在糖液起密集小泡时，迅速将 B包（生姜、葱白、蒜、花椒、八角、香叶）倒入锅中爆香。', NULL);
INSERT INTO `recipe_step` VALUES (500310, 300042, 11, '爆出香味后（约 5-10 秒内），先不要加开水，而是立刻将焯过水的五花肉倒入锅中大火翻炒，让肉块均匀裹上糖色并煸炒出油脂。待闻到肉香后，再倒入开水至没过全部肉，盖上锅盖，转中小火炖煮 50 分钟-60 分钟（高压锅则为 40 分钟）；', NULL);
INSERT INTO `recipe_step` VALUES (500311, 300042, 12, '加入 10ml 料酒；', NULL);
INSERT INTO `recipe_step` VALUES (500312, 300042, 13, '盖上锅盖煮至沸腾后，每隔 25 分钟打开盖子将浮在表面的油和沫捞出；', NULL);
INSERT INTO `recipe_step` VALUES (500313, 300042, 14, '当水的高度减至肉最高的高度与锅底高度的 3/5 时，转中火，并捞出除肉和水以外的所有辅料，开始收汁；', NULL);
INSERT INTO `recipe_step` VALUES (500314, 300042, 15, '打开锅盖，待汤汁快没有的时粘稠状出锅（切记不可收干）；', NULL);
INSERT INTO `recipe_step` VALUES (500315, 300043, 1, '在不锈钢桶中放入 5000g 水、500g 卤料和 500g 卤油，大火烧开后，捞出料渣；', NULL);
INSERT INTO `recipe_step` VALUES (500316, 300043, 2, '解冻后的大排放入卤汤中，大火烧开后转小火卤制 10 分钟，关火焖 5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500317, 300044, 1, '在不锈钢桶中放入 5000g 水、500g 卤料和 500g 卤油，大火烧开后，捞出料渣；', NULL);
INSERT INTO `recipe_step` VALUES (500318, 300044, 2, '方干放入卤汤中，大火烧开后转小火卤制 5 分钟，关火焖 10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500319, 300045, 1, '解冻后的鸡翅根焯水，捞出备用；', NULL);
INSERT INTO `recipe_step` VALUES (500320, 300045, 2, '在不锈钢桶中放入 5000g 水、500g 卤料和 500g 卤油，大火烧开后，捞出料渣，备用；', NULL);
INSERT INTO `recipe_step` VALUES (500321, 300045, 3, '卤汤中下入鸡翅根，大火烧开后转小火卤 20 分钟，关火焖 10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500322, 300046, 1, '在不锈钢桶中放入5000g水、500g卤料和500g卤油，大火烧开后，捞出料渣，备用；', NULL);
INSERT INTO `recipe_step` VALUES (500323, 300046, 2, '解冻后的卤肉肠放入卤汤中，大火烧开后转小火卤10分钟，关火焖5分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500324, 300047, 1, '牛腱子提前浸泡在冷水中 3 小时以上，去除血水', NULL);
INSERT INTO `recipe_step` VALUES (500325, 300047, 2, '【准备卤水】准备糖色：锅中加入 30g 白糖，小火加热至糖完全融化并呈现棕褐色，加入 150ml 热水，搅拌均匀备用', NULL);
INSERT INTO `recipe_step` VALUES (500326, 300047, 3, '【准备卤水】将洋葱切块，生姜和大蒜拍碎，干辣椒掰断备用', NULL);
INSERT INTO `recipe_step` VALUES (500327, 300047, 4, '【准备卤水】在锅中加入足量的水，放入卤料包、洋葱、生姜、大蒜、干辣椒，大火烧开', NULL);
INSERT INTO `recipe_step` VALUES (500328, 300047, 5, '【准备卤水】加入黄豆酱、豆瓣酱、蚝油和南腐乳各 15ml，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (500329, 300047, 6, '【准备卤水】倒入准备好的糖色，混合均匀', NULL);
INSERT INTO `recipe_step` VALUES (500330, 300047, 7, '【准备卤水】加入生抽 120ml 和老抽 60ml，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (500331, 300047, 8, '【准备卤水】加入 10-15g 盐调味', NULL);
INSERT INTO `recipe_step` VALUES (500332, 300047, 9, '【准备卤水】倒入 1 罐啤酒(330ml)，再次烧开', NULL);
INSERT INTO `recipe_step` VALUES (500333, 300047, 10, '【卤制牛肉】牛腱子放入锅中焯水 2-3 分钟，捞出并用热水冲洗干净表面的浮沫', NULL);
INSERT INTO `recipe_step` VALUES (500334, 300047, 11, '【卤制牛肉】将焯水后的牛腱子放入已烧开的卤水中，确保卤水没过所有肉类', NULL);
INSERT INTO `recipe_step` VALUES (500335, 300047, 12, '【卤制牛肉】盖上高压锅盖，上汽后继续烹饪 25-30 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500336, 300047, 13, '【卤制牛肉】烹饪完成后，不要开盖保温，自然冷却并浸泡一晚上（这样会更入味）', NULL);
INSERT INTO `recipe_step` VALUES (500337, 300047, 14, '【卤制牛肉】将卤好的肉取出放入冰箱冷藏，使其成型', NULL);
INSERT INTO `recipe_step` VALUES (500338, 300047, 15, '【卤制牛肉】食用前取出切片，可直接食用或凉拌', NULL);
INSERT INTO `recipe_step` VALUES (500339, 300047, 16, '【保存卤水】卤水重复使用方法：每次卤完肉后，将卤水过滤，去除所有固体内容物，重新烧开杀菌，冷却后可冷藏或冷冻保存。使用时按原配方比例重新添加调味料。（加水量根据卤水使用情况而定）', NULL);
INSERT INTO `recipe_step` VALUES (500340, 300047, 17, '【保存卤水】卤水保存得当可以使用很长时间，且越老越香。', NULL);
INSERT INTO `recipe_step` VALUES (500341, 300047, 18, '【保存卤水】重要提示：如卤制素菜，必须另取一部分卤水，单独使用，并且卤制完素菜的卤水不可重复使用。', NULL);
INSERT INTO `recipe_step` VALUES (500342, 300047, 19, '【凉拌调料】将蒜末、葱花、白芝麻、辣椒粉按 1:1:1:1 的比例混合，依个人口味加小米辣，热植物油中加入少量芝麻油或藤椒油，分次泼在调料上，再加入生抽、醋、蚝油各 10ml，5ml 糖，味精/鸡精，最后 15ml 卤汤混合均匀。', NULL);
INSERT INTO `recipe_step` VALUES (500343, 300047, 20, '【凉拌调料】凉拌时可搭配拍黄瓜、木耳、油炸花生米、香菜等配菜。', NULL);
INSERT INTO `recipe_step` VALUES (500344, 300048, 1, '在不锈钢桶中放入 5000g 水、500g 卤料和 500g 卤油，大火烧开后，捞出料渣，备用；', NULL);
INSERT INTO `recipe_step` VALUES (500345, 300048, 2, '解冻后的卤鸡爪放入卤汤中，大火烧开后转小火卤 5 分钟，关火焖 5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500346, 300049, 1, '在不锈钢桶中放入 5000g 水、500g 卤料和 500g 卤油，大火烧开后，捞出料渣，备用；', NULL);
INSERT INTO `recipe_step` VALUES (500347, 300049, 2, '解冻后的卤鸡腿放入卤汤中，大火烧开后转小火卤 5 分钟，关火焖 5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500348, 300050, 1, '将土豆去皮切成约 2cm 的块状', NULL);
INSERT INTO `recipe_step` VALUES (500349, 300050, 2, '将花菜掰成均匀的小朵，大朵可用刀切小', NULL);
INSERT INTO `recipe_step` VALUES (500350, 300050, 3, '在炒锅中倒入 30ml 食用油，中火加热', NULL);
INSERT INTO `recipe_step` VALUES (500351, 300050, 4, '油热后放入孜然籽 3g，炸至孜然籽变深色且散发香味（约 10 秒，注意不要炸糊）', NULL);
INSERT INTO `recipe_step` VALUES (500352, 300050, 5, '放入切碎的洋葱，翻炒至洋葱变透明微黄（约 3-4 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (500353, 300050, 6, '加入生姜、大蒜和青辣椒，翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500354, 300050, 7, '加入切碎的番茄，翻炒至番茄软烂（约 2-3 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (500355, 300050, 8, '加入姜黄粉 3g、红辣椒粉 3g、香菜粉 5g、盐 5g', NULL);
INSERT INTO `recipe_step` VALUES (500356, 300050, 9, '翻炒 1 分钟，使香料与蔬菜融合', NULL);
INSERT INTO `recipe_step` VALUES (500357, 300050, 10, '放入土豆块，翻炒 2 分钟使土豆表面裹上香料', NULL);
INSERT INTO `recipe_step` VALUES (500358, 300050, 11, '放入花菜朵，轻轻翻拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (500359, 300050, 12, '盖上锅盖，转中小火，焖 12-15 分钟，期间每 3-4 分钟打开翻炒一次防止粘锅', NULL);
INSERT INTO `recipe_step` VALUES (500360, 300050, 13, '当土豆用筷子可轻松戳透、花菜略有焦边时，撒入印度综合香料粉 3g', NULL);
INSERT INTO `recipe_step` VALUES (500361, 300050, 14, '翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500362, 300050, 15, '关火，撒上香菜叶，盛盘', NULL);
INSERT INTO `recipe_step` VALUES (500363, 300051, 1, '将生姜拍碎（不用切太碎，拍开即可释放姜汁）', NULL);
INSERT INTO `recipe_step` VALUES (500364, 300051, 2, '将小豆蔻用刀背拍开，露出里面的籽', NULL);
INSERT INTO `recipe_step` VALUES (500365, 300051, 3, '将黑胡椒粒拍碎', NULL);
INSERT INTO `recipe_step` VALUES (500366, 300051, 4, '在小奶锅中倒入 120ml 水', NULL);
INSERT INTO `recipe_step` VALUES (500367, 300051, 5, '放入拍碎的生姜、小豆蔻、肉桂棒、丁香、黑胡椒粒', NULL);
INSERT INTO `recipe_step` VALUES (500368, 300051, 6, '大火煮沸后转小火，煮 2 分钟，让香料的味道充分释出', NULL);
INSERT INTO `recipe_step` VALUES (500369, 300051, 7, '加入红茶 8g，继续小火煮 2 分钟，直至茶汤颜色变深', NULL);
INSERT INTO `recipe_step` VALUES (500370, 300051, 8, '倒入全脂牛奶 120ml', NULL);
INSERT INTO `recipe_step` VALUES (500371, 300051, 9, '中火加热，注意观察，当奶茶开始冒泡上升时立即转小火（牛奶极易溢出）', NULL);
INSERT INTO `recipe_step` VALUES (500372, 300051, 10, '小火煮 2-3 分钟，期间可以将锅提起倒回（反复提拉 3-4 次），使茶汤与牛奶充分融合', NULL);
INSERT INTO `recipe_step` VALUES (500373, 300051, 11, '加入糖，搅拌溶解', NULL);
INSERT INTO `recipe_step` VALUES (500374, 300051, 12, '关火', NULL);
INSERT INTO `recipe_step` VALUES (500375, 300051, 13, '用滤网过滤到茶盏中，去除茶叶和香料残渣', NULL);
INSERT INTO `recipe_step` VALUES (500376, 300051, 14, '趁热饮用', NULL);
INSERT INTO `recipe_step` VALUES (500377, 300052, 1, '【和面与发酵】将干酵母 3g 和糖 10g 溶解在 100ml 温水中（水温约 40°C，不可过烫）', NULL);
INSERT INTO `recipe_step` VALUES (500378, 300052, 2, '【和面与发酵】静置 5 分钟，直至表面冒出细泡沫（说明酵母已激活）', NULL);
INSERT INTO `recipe_step` VALUES (500379, 300052, 3, '【和面与发酵】在大碗中放入中筋面粉 300g 和盐 5g，混合均匀', NULL);
INSERT INTO `recipe_step` VALUES (500380, 300052, 4, '【和面与发酵】倒入酵母水、酸奶 60ml 和食用油 15ml', NULL);
INSERT INTO `recipe_step` VALUES (500381, 300052, 5, '【和面与发酵】用手揉成光滑柔软的面团（面团应比普通面团稍软，微微粘手是正常的）', NULL);
INSERT INTO `recipe_step` VALUES (500382, 300052, 6, '【和面与发酵】揉面 8-10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500383, 300052, 7, '【和面与发酵】在面团表面涂 3ml 油防止干裂', NULL);
INSERT INTO `recipe_step` VALUES (500384, 300052, 8, '【和面与发酵】用湿布或保鲜膜盖住碗口', NULL);
INSERT INTO `recipe_step` VALUES (500385, 300052, 9, '【和面与发酵】放置在温暖处发酵 至少 1 小时，直至面团膨胀至约两倍大', NULL);
INSERT INTO `recipe_step` VALUES (500386, 300052, 10, '【分剂与擀制】将发酵好的面团取出，轻揉排气', NULL);
INSERT INTO `recipe_step` VALUES (500387, 300052, 11, '【分剂与擀制】分成 6 个等大的小剂子（每个约 80g）', NULL);
INSERT INTO `recipe_step` VALUES (500388, 300052, 12, '【分剂与擀制】取一个剂子，手上沾 3ml 面粉或油', NULL);
INSERT INTO `recipe_step` VALUES (500389, 300052, 13, '【分剂与擀制】用擀面杖擀成长椭圆形或泪滴形面饼，厚度约 4-5mm', NULL);
INSERT INTO `recipe_step` VALUES (500390, 300052, 14, '【分剂与擀制】如果制作蒜蓉烤饼：在面饼表面撒上切碎的大蒜和香菜叶，轻轻擀压使其嵌入面饼', NULL);
INSERT INTO `recipe_step` VALUES (500391, 300052, 15, '【分剂与擀制】可在面饼表面撒上芝麻', NULL);
INSERT INTO `recipe_step` VALUES (500392, 300052, 16, '【烤制】将平底锅（铸铁锅最佳）大火加热至非常烫（滴水立即蒸发的程度）', NULL);
INSERT INTO `recipe_step` VALUES (500393, 300052, 17, '【烤制】在面饼一面刷一层薄薄的水', NULL);
INSERT INTO `recipe_step` VALUES (500394, 300052, 18, '【烤制】将刷水一面朝下放入锅中', NULL);
INSERT INTO `recipe_step` VALUES (500395, 300052, 19, '【烤制】烤 1-2 分钟，直至底面出现金棕色斑点且面饼开始鼓泡', NULL);
INSERT INTO `recipe_step` VALUES (500396, 300052, 20, '【烤制】翻面，继续烤 1-2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500397, 300052, 21, '【烤制】如果有煤气灶：翻面后可用夹子夹起面饼，将其直接放在明火上烤 数秒钟，面饼会迅速鼓起', NULL);
INSERT INTO `recipe_step` VALUES (500398, 300052, 22, '【烤制】取出后立即在表面涂上酥油或黄油', NULL);
INSERT INTO `recipe_step` VALUES (500399, 300052, 23, '【烤制】烤箱预热至最高温度（通常 250°C）', NULL);
INSERT INTO `recipe_step` VALUES (500400, 300052, 24, '【烤制】将面饼放在烤盘上', NULL);
INSERT INTO `recipe_step` VALUES (500401, 300052, 25, '【烤制】烤 3-5 分钟，直至表面金黄且鼓起', NULL);
INSERT INTO `recipe_step` VALUES (500402, 300052, 26, '【烤制】取出后涂上酥油或黄油', NULL);
INSERT INTO `recipe_step` VALUES (500403, 300052, 27, '【上菜】趁热食用', NULL);
INSERT INTO `recipe_step` VALUES (500404, 300052, 28, '【上菜】适合搭配任何印度咖喱，如黄油鸡、红芸豆咖喱等', NULL);
INSERT INTO `recipe_step` VALUES (500405, 300053, 1, '【腌制鸡肉（提前 1 小时）】在大碗中混合酸奶、磨碎的生姜和大蒜、红辣椒粉、姜黄粉、印度综合香料粉、盐、柠檬汁', NULL);
INSERT INTO `recipe_step` VALUES (500406, 300053, 2, '【腌制鸡肉（提前 1 小时）】放入鸡肉块，均匀裹上腌料', NULL);
INSERT INTO `recipe_step` VALUES (500407, 300053, 3, '【腌制鸡肉（提前 1 小时）】盖保鲜膜，冷藏腌制至少 1 小时（过夜更佳）', NULL);
INSERT INTO `recipe_step` VALUES (500408, 300053, 4, '【准备藏红花牛奶和炸洋葱】将藏红花 0.5g 放入 30ml 温牛奶中浸泡 15 分钟，备用', NULL);
INSERT INTO `recipe_step` VALUES (500409, 300053, 5, '【准备藏红花牛奶和炸洋葱】在锅中倒入 50ml 食用油，中火加热', NULL);
INSERT INTO `recipe_step` VALUES (500410, 300053, 6, '【准备藏红花牛奶和炸洋葱】放入洋葱薄片，翻炒至深金棕色且酥脆（约 12-15 分钟，需耐心）', NULL);
INSERT INTO `recipe_step` VALUES (500411, 300053, 7, '【准备藏红花牛奶和炸洋葱】捞出炸洋葱，用厨房纸吸油，备用', NULL);
INSERT INTO `recipe_step` VALUES (500412, 300053, 8, '【煮半熟米饭】将浸泡好的巴斯马蒂香米沥干', NULL);
INSERT INTO `recipe_step` VALUES (500413, 300053, 9, '【煮半熟米饭】在大锅中烧开 2000ml 水', NULL);
INSERT INTO `recipe_step` VALUES (500414, 300053, 10, '【煮半熟米饭】加入月桂叶、小豆蔻、丁香、肉桂棒、八角和盐 10g', NULL);
INSERT INTO `recipe_step` VALUES (500415, 300053, 11, '【煮半熟米饭】放入米饭，大火煮 5-6 分钟，直至米粒约七成熟（外部软、芯部仍有硬度）', NULL);
INSERT INTO `recipe_step` VALUES (500416, 300053, 12, '【煮半熟米饭】立即沥干，丢弃全香料，备用', NULL);
INSERT INTO `recipe_step` VALUES (500417, 300053, 13, '【组装与焖制】在厚底锅底部涂抹酥油 15g', NULL);
INSERT INTO `recipe_step` VALUES (500418, 300053, 14, '【组装与焖制】第一层：将腌制好的鸡肉均匀铺在锅底', NULL);
INSERT INTO `recipe_step` VALUES (500419, 300053, 15, '【组装与焖制】第二层：铺上一半的半熟米饭', NULL);
INSERT INTO `recipe_step` VALUES (500420, 300053, 16, '【组装与焖制】撒上一半的炸洋葱、薄荷叶、香菜叶、青辣椒', NULL);
INSERT INTO `recipe_step` VALUES (500421, 300053, 17, '【组装与焖制】第三层：铺上剩余的米饭', NULL);
INSERT INTO `recipe_step` VALUES (500422, 300053, 18, '【组装与焖制】撒上剩余的炸洋葱、薄荷叶、香菜叶', NULL);
INSERT INTO `recipe_step` VALUES (500423, 300053, 19, '【组装与焖制】将藏红花牛奶均匀淋在最上层米饭表面', NULL);
INSERT INTO `recipe_step` VALUES (500424, 300053, 20, '【组装与焖制】放上剩余的酥油 15g（切小块散放）', NULL);
INSERT INTO `recipe_step` VALUES (500425, 300053, 21, '【组装与焖制】密封锅盖：用面粉加水和成面团条，沿锅口边缘封住缝隙（传统方法），或用锡纸包裹锅口再盖锅盖', NULL);
INSERT INTO `recipe_step` VALUES (500426, 300053, 22, '【组装与焖制】先用大火加热 3 分钟，直至锅内开始冒蒸汽', NULL);
INSERT INTO `recipe_step` VALUES (500427, 300053, 23, '【组装与焖制】然后转最小火，焖 25-30 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500428, 300053, 24, '【组装与焖制】关火后不要开盖，再焖 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500429, 300053, 25, '【组装与焖制】开盖，用大铲子从底部轻轻翻拌，使各层混合均匀', NULL);
INSERT INTO `recipe_step` VALUES (500430, 300053, 26, '【组装与焖制】盛盘，搭配酸奶(Raita)食用', NULL);
INSERT INTO `recipe_step` VALUES (500431, 300054, 1, '【制作丸子】将瓠瓜去皮，用刨丝器刨成细丝', NULL);
INSERT INTO `recipe_step` VALUES (500432, 300054, 2, '【制作丸子】用手将瓠瓜丝中的水分挤干，尽量挤干，否则丸子炸不成型', NULL);
INSERT INTO `recipe_step` VALUES (500433, 300054, 3, '【制作丸子】在挤干水分的瓠瓜丝中加入鹰嘴豆粉 80g、盐 3g、红辣椒粉 3g、香菜粉 3g', NULL);
INSERT INTO `recipe_step` VALUES (500434, 300054, 4, '【制作丸子】用手充分混合均匀，揉成不粘手的面团状', NULL);
INSERT INTO `recipe_step` VALUES (500435, 300054, 5, '【制作丸子】将混合物搓成直径约 3cm 的小丸子，备用', NULL);
INSERT INTO `recipe_step` VALUES (500436, 300054, 6, '【制作丸子】在深锅中倒入 500ml 食用油，中火加热至油温约 170°C（放入一小块面团，能快速浮起且冒泡即可）', NULL);
INSERT INTO `recipe_step` VALUES (500437, 300054, 7, '【制作丸子】将丸子分批放入油中，炸 4-5 分钟，直至表面金黄酥脆', NULL);
INSERT INTO `recipe_step` VALUES (500438, 300054, 8, '【制作丸子】炸好的丸子用厨房纸吸去多余油分，备用', NULL);
INSERT INTO `recipe_step` VALUES (500439, 300054, 9, '【制作酱汁】在炒锅中倒入 30ml 食用油，中火加热 10 秒', NULL);
INSERT INTO `recipe_step` VALUES (500440, 300054, 10, '【制作酱汁】放入切碎的洋葱，翻炒至洋葱变成金棕色（约 5-7 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (500441, 300054, 11, '【制作酱汁】加入磨碎的生姜和大蒜，翻炒 1 分钟至香味散出', NULL);
INSERT INTO `recipe_step` VALUES (500442, 300054, 12, '【制作酱汁】加入切碎的番茄，翻炒至番茄完全软烂出油（约 5 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (500443, 300054, 13, '【制作酱汁】加入姜黄粉 3g、红辣椒粉 5g、香菜粉 5g、孜然粉 3g、盐 5g', NULL);
INSERT INTO `recipe_step` VALUES (500444, 300054, 14, '【制作酱汁】翻炒 2 分钟，使香料与番茄充分融合', NULL);
INSERT INTO `recipe_step` VALUES (500445, 300054, 15, '【制作酱汁】加入 200ml 水，搅拌均匀，煮沸后转小火炖 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500446, 300054, 16, '【制作酱汁】将炸好的丸子轻轻放入酱汁中，小火炖 3-5 分钟，使丸子吸收酱汁', NULL);
INSERT INTO `recipe_step` VALUES (500447, 300054, 17, '【制作酱汁】撒上印度综合香料粉 3g 和切碎的青辣椒', NULL);
INSERT INTO `recipe_step` VALUES (500448, 300054, 18, '【制作酱汁】关火，撒上香菜叶装饰，盛盘', NULL);
INSERT INTO `recipe_step` VALUES (500449, 300055, 1, '将 500g 干黄豆在 2000g 水中浸泡 8 小时，清洗干净备用；', NULL);
INSERT INTO `recipe_step` VALUES (500450, 300055, 2, '在豆浆机内加入 1250g 湿黄豆、5000g 水磨制。', NULL);
INSERT INTO `recipe_step` VALUES (500451, 300056, 1, '40g 豆浆粉用 270g 温开水（60-90℃）冲调，搅拌均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (500452, 300057, 1, '将 500g 干黄豆在 2000g 水中浸泡 8 小时，清洗干净备用；', NULL);
INSERT INTO `recipe_step` VALUES (500453, 300057, 2, '在豆浆机内加入 1250g 湿黄豆、5000g 水磨制。', NULL);
INSERT INTO `recipe_step` VALUES (500454, 300058, 1, '芋头切长条（稍微大条一点，翻炒过程不容易烂）', NULL);
INSERT INTO `recipe_step` VALUES (500455, 300058, 2, '加入可以没过芋头的油，等油温起来（插入筷子冒小泡即可）', NULL);
INSERT INTO `recipe_step` VALUES (500456, 300058, 3, '放进芋头到油里，去炸到芋头浮起来，一般是微微泛黄并且可以用筷子很轻松戳洞', NULL);
INSERT INTO `recipe_step` VALUES (500457, 300058, 4, '炸芋头的油放起来别浪费，后面炒菜啥的都能用', NULL);
INSERT INTO `recipe_step` VALUES (500458, 300058, 5, '接下来关键的一步，把糖(30g)和水(15g)按照 2：1 比例，加热至不变色且冒小泡', NULL);
INSERT INTO `recipe_step` VALUES (500459, 300058, 6, '倒入葱花和芋头，关火翻炒，此时等温度下来，糖就会有反沙的效果', NULL);
INSERT INTO `recipe_step` VALUES (500460, 300058, 7, '装盘上桌！', NULL);
INSERT INTO `recipe_step` VALUES (500461, 300059, 1, '姜切片，1 颗小葱，15 颗花椒备用', NULL);
INSERT INTO `recipe_step` VALUES (500462, 300059, 2, '鸡肉洗干净，放入锅中，清水没过鸡肉，放入姜片、小葱和花椒，开大火烧开。', NULL);
INSERT INTO `recipe_step` VALUES (500463, 300059, 3, '大火烧开后，转中小火 20 分钟关火', NULL);
INSERT INTO `recipe_step` VALUES (500464, 300059, 4, '取出鸡肉，放入冰水中，直至冰凉', NULL);
INSERT INTO `recipe_step` VALUES (500465, 300059, 5, '取出鸡肉，切块摆盘子中，备用', NULL);
INSERT INTO `recipe_step` VALUES (500466, 300059, 6, '小火把锅烧热，导入花生，烘烤至表皮爆裂。（注意随时翻动，不要糊了）', NULL);
INSERT INTO `recipe_step` VALUES (500467, 300059, 7, '一颗葱切成段，蒜拍成末，花椒 15 颗，花生去皮切碎。', NULL);
INSERT INTO `recipe_step` VALUES (500468, 300059, 8, '锅内导入油烧热后，放入葱段，花椒和一半蒜末，炒香', NULL);
INSERT INTO `recipe_step` VALUES (500469, 300059, 9, '炒至油温 8 成热，关火，滤出热油', NULL);
INSERT INTO `recipe_step` VALUES (500470, 300059, 10, '将热油倒入放辣椒粉的碗中，搅拌，并滤出红油', NULL);
INSERT INTO `recipe_step` VALUES (500471, 300059, 11, '红油中放入剩余蒜末、生抽、醋、盐、味精、糖、香油、花椒粉。拌匀放凉', NULL);
INSERT INTO `recipe_step` VALUES (500472, 300059, 12, '在鸡肉上撒上花生碎，把红油淋到切好的鸡肉上，撒上香菜。成盘', NULL);
INSERT INTO `recipe_step` VALUES (500473, 300060, 1, '将柠檬对半切（刀方向垂直于柠檬的头尾连线），并从其中的一半中切取一片柠檬备用', NULL);
INSERT INTO `recipe_step` VALUES (500474, 300060, 2, '再次将柠檬对半切，将得到的 4 角柠檬用压汁器压出柠檬汁置于容器中备用', NULL);
INSERT INTO `recipe_step` VALUES (500475, 300060, 3, '将挤压过的柠檬置于容器中备用', NULL);
INSERT INTO `recipe_step` VALUES (500476, 300060, 4, '选择一个杯子，建议使用容量在大约 1 升的大型玻璃杯或铁皮酒桶', NULL);
INSERT INTO `recipe_step` VALUES (500477, 300060, 5, '将冰块和挤压过的柠檬入杯中（可根据个人喜好设计柠檬与冰块的摆放）', NULL);
INSERT INTO `recipe_step` VALUES (500478, 300060, 6, '倒入 15 毫升柠檬汁（如果喜酸可以加多点或全加）', NULL);
INSERT INTO `recipe_step` VALUES (500479, 300060, 7, '沿杯壁缓慢倒入可口可乐至距离杯口 3/4 处（控制可乐和威士忌的比例约在 5:1 ）', NULL);
INSERT INTO `recipe_step` VALUES (500480, 300060, 8, '倒入威士忌直至满杯', NULL);
INSERT INTO `recipe_step` VALUES (500481, 300061, 1, '将锅烧热后，加入 25 ml 油，放两个鸡蛋，煎至底部完全凝固', NULL);
INSERT INTO `recipe_step` VALUES (500482, 300061, 2, '翻面，煎至两面完全凝固', NULL);
INSERT INTO `recipe_step` VALUES (500483, 300061, 3, '关火，将鸡蛋取出，剪成 2-5 cm² 的小块后放回锅中（也可以直接用锅铲铲碎）', NULL);
INSERT INTO `recipe_step` VALUES (500484, 300061, 4, '重新开火，倒入可乐、生抽、老抽、豆瓣酱、蚝油，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (500485, 300061, 5, '加热到锅内液体剩 1/3，倒入米饭和火腿肠翻炒', NULL);
INSERT INTO `recipe_step` VALUES (500486, 300061, 6, '翻炒均匀后，改小火，锅内食物中心挖一个洞，打入 1 个鸡蛋，盖上锅盖，焖 2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500487, 300061, 7, '开盖翻炒至第三颗鸡蛋熟透，撒上葱花和胡椒粉，出锅', NULL);
INSERT INTO `recipe_step` VALUES (500488, 300062, 1, '鸡翅入锅，倒入冷水淹没。放生姜 1 片和料酒 10 ～ 20 毫升。大火煮开（ 大约 2 分钟 ）后，撇去浮沫，沥出水分 这一步针对冰鲜鸡翅，刚买来的鸡翅直接改刀用生抽进行腌制即可。', NULL);
INSERT INTO `recipe_step` VALUES (500489, 300062, 2, '捞出鸡翅，可用刀将两边各划上两口改刀。生抽约 10 克腌制鸡翅 10 分钟（生抽能完全包裹鸡翅表面入味就行）', NULL);
INSERT INTO `recipe_step` VALUES (500490, 300062, 3, '锅重新小火起油，先将剩余姜片爆香，然后下入腌好的鸡翅。将鸡翅煎至金黄翻面（直到两面金黄），用炒菜勺子翻动一下鸡翅，与姜片一起翻炒 4～5 下（目的是防止鸡翅和姜片粘黏）。', NULL);
INSERT INTO `recipe_step` VALUES (500491, 300062, 4, '鸡翅金黄，倒入可乐没过鸡翅，开大火将锅中可乐煮沸，然后撇去漂浮的黑色浮沫（包含血水）。此时加入葱结。', NULL);
INSERT INTO `recipe_step` VALUES (500492, 300062, 5, '调味：加入食用盐 2 克，白糖 10 克，生抽 3 克调味（可以适当用老抽调底色，3 克）。', NULL);
INSERT INTO `recipe_step` VALUES (500493, 300062, 6, '等到葱结变黄，和姜片一起捞出，转中火继续慢煮可乐鸡翅。', NULL);
INSERT INTO `recipe_step` VALUES (500494, 300062, 7, '等到可乐呈现挂丝状态，关小火让汁牢牢挂在鸡翅上。出锅，装盘。', NULL);
INSERT INTO `recipe_step` VALUES (500495, 300063, 1, '带皮五花肉切成 $0.7cm（长）\\times 0.7cm（宽） \\times 2.5cm（高）$ 的细长条', NULL);
INSERT INTO `recipe_step` VALUES (500496, 300063, 2, '红葱头、大蒜切末备用', NULL);
INSERT INTO `recipe_step` VALUES (500497, 300063, 3, '鸡蛋煮熟剥壳，并用刀划破蛋白（便于入味），备用。', NULL);
INSERT INTO `recipe_step` VALUES (500498, 300063, 4, '大火热锅，锅内放入 15 ml 食用油，让油滑满锅底即可。 放油的目的是防止五花肉刚下锅时粘锅。等待 5s 使油温稍微升高。', NULL);
INSERT INTO `recipe_step` VALUES (500499, 300063, 5, '放入五花肉条，翻炒至肉色稍微变白，沿锅边淋入米酒 10ml 。继续翻炒至五花肉不再出油。', NULL);
INSERT INTO `recipe_step` VALUES (500500, 300063, 6, '将切好的红葱头加入锅中，翻炒 1 分钟爆出油葱香味。', NULL);
INSERT INTO `recipe_step` VALUES (500501, 300063, 7, '将切好的红葱头加入锅中，翻炒 30 秒。', NULL);
INSERT INTO `recipe_step` VALUES (500502, 300063, 8, '把猪肉推到旁边，放入冰糖加热到融化冒泡变成焦糖，再把猪肉一起翻拌，让焦糖均匀附着。', NULL);
INSERT INTO `recipe_step` VALUES (500503, 300063, 9, '加入生抽炒出香气。', NULL);
INSERT INTO `recipe_step` VALUES (500504, 300063, 10, '呛入米酒 25 ml ，水加到淹过猪肉，加入白胡椒粉、五香粉、八角、香叶、水煮蛋，沸腾后转小火卤 1 小时。 注意: 不同酱油的咸淡不一，卤的时候务必试味道，太甜加酱油，太咸加点糖或水调整。 小火炖煮过程中，每隔 15 分钟 搅拌检查一次，防止粘锅。 如发现过干，则可加入 100ml 清水继续炖煮。', NULL);
INSERT INTO `recipe_step` VALUES (500505, 300063, 11, '1 小时后，开大火收汁直到酱汁浓稠，呈现有光泽的琥珀色，即完成。', NULL);
INSERT INTO `recipe_step` VALUES (500506, 300063, 12, '炖煮结束后，乘一碗米饭，将软烂的卤肉浇在米饭上，并加上卤蛋，开始享用。', NULL);
INSERT INTO `recipe_step` VALUES (500507, 300064, 1, '将吐司放入面包机', NULL);
INSERT INTO `recipe_step` VALUES (500508, 300064, 2, '设置好档位，时间到了会自动弹出', NULL);
INSERT INTO `recipe_step` VALUES (500509, 300064, 3, '两分钟后吐司加热完成弹出', NULL);
INSERT INTO `recipe_step` VALUES (500510, 300064, 4, '先取出一片吐司，涂满果酱再盖上另一片吐司即可', NULL);
INSERT INTO `recipe_step` VALUES (500511, 300064, 5, '用餐巾纸包一下可以边走边吃也可以吃完再出门', NULL);
INSERT INTO `recipe_step` VALUES (500512, 300065, 1, '将梅头猪肉（100 克）洗净，然后用厨房纸抹干水份，将猪肉切成比想要的成品小一圈的大小。', NULL);
INSERT INTO `recipe_step` VALUES (500513, 300065, 2, '用盐（1/2 茶匙）腌制梅头猪肉 20 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500514, 300065, 3, '将青椒（25 克）切碎。', NULL);
INSERT INTO `recipe_step` VALUES (500515, 300065, 4, '将菠萝片（75 克）切件。', NULL);
INSERT INTO `recipe_step` VALUES (500516, 300065, 5, '在碗中加入茄汁（4 汤匙）﹑白醋（2 茶匙）﹑蒜蓉（1 汤匙）﹑生抽（½ 茶匙）﹑生粉（2½ 茶匙）﹑白砂糖（2 汤匙）﹑盐（¼ 茶匙）和水（200 毫升），拌匀成酱汁。', NULL);
INSERT INTO `recipe_step` VALUES (500517, 300065, 6, '将梅头猪肉粒沾上生粉（6 汤匙）。', NULL);
INSERT INTO `recipe_step` VALUES (500518, 300065, 7, '加入油（500 毫升）中火加热。', NULL);
INSERT INTO `recipe_step` VALUES (500519, 300065, 8, '将梅头猪肉粒放至锅里中火炸 5 分钟，然后盛起。', NULL);
INSERT INTO `recipe_step` VALUES (500520, 300065, 9, '加入梅头猪肉粒，再大火翻炸 1 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500521, 300065, 10, '加入油（1 茶匙）和酱汁，中火加热 3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500522, 300065, 11, '加入青椒和菠萝，大火加热 2 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500523, 300065, 12, '将已炸好的梅头猪肉粒与酱汁拌匀即可。', NULL);
INSERT INTO `recipe_step` VALUES (500524, 300066, 1, '将定量淡奶油，椰树牌椰汁，espresso，椰子水混合备用。', NULL);
INSERT INTO `recipe_step` VALUES (500525, 300066, 2, '将以上液体加热 1 分钟，温度达到 50-60 度即可。', NULL);
INSERT INTO `recipe_step` VALUES (500526, 300066, 3, '（可选）如果格外嗜甜可以加额外的糖。', NULL);
INSERT INTO `recipe_step` VALUES (500527, 300066, 4, '倒入吉利丁，搅拌至融化，煮 1 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500528, 300066, 5, '（可选）过筛 （这一步可以让椰奶冻口感更佳顺畅）。', NULL);
INSERT INTO `recipe_step` VALUES (500529, 300066, 6, '放入模具。', NULL);
INSERT INTO `recipe_step` VALUES (500530, 300066, 7, '（可选）过滤掉表层的泡泡。这一步可以让椰奶冻口感更好，并且看着也会更棒。', NULL);
INSERT INTO `recipe_step` VALUES (500531, 300066, 8, '放入冰箱冷藏区，等待 3 小时。', NULL);
INSERT INTO `recipe_step` VALUES (500532, 300067, 1, '肉蟹掀盖后对半砍开，蟹钳用刀背轻轻拍裂，切口和蟹钳蘸一下生粉，不要太多。撒 5g 生粉到蟹盖中，盖住蟹黄，备用', NULL);
INSERT INTO `recipe_step` VALUES (500533, 300067, 2, '洋葱切成洋葱碎，备用', NULL);
INSERT INTO `recipe_step` VALUES (500534, 300067, 3, '大蒜切碎，备用', NULL);
INSERT INTO `recipe_step` VALUES (500535, 300067, 4, '烧一壶开水，备用', NULL);
INSERT INTO `recipe_step` VALUES (500536, 300067, 5, '起锅烧油，倒入约 20ml 食用油，等待 10 秒让油温升高', NULL);
INSERT INTO `recipe_step` VALUES (500537, 300067, 6, '将螃蟹切口朝下，轻轻放入锅中，煎 20 秒，这一步主要是封住蟹黄，蟹肉。然后翻面，每面煎 10 秒。煎完将螃蟹取出备用', NULL);
INSERT INTO `recipe_step` VALUES (500538, 300067, 7, '将螃蟹盖放入锅中，使用勺子舀起锅中热油泼到蟹盖中，煎封住蟹盖中的蟹黄，煎 20 秒后取出备用', NULL);
INSERT INTO `recipe_step` VALUES (500539, 300067, 8, '不用刷锅，再倒入 10ml 食用油，大火让油温升高至轻微冒烟，将大蒜末，洋葱碎倒入，炒 10 秒钟', NULL);
INSERT INTO `recipe_step` VALUES (500540, 300067, 9, '将咖喱块放入锅中炒化（10 秒），放入煎好的螃蟹，翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (500541, 300067, 10, '倒入开水 300ml，焖煮 3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500542, 300067, 11, '焖煮完后，倒入椰浆和蛋清，关火，关火后不断翻炒，一直到酱汁变浓稠。', NULL);
INSERT INTO `recipe_step` VALUES (500543, 300067, 12, '出锅', NULL);
INSERT INTO `recipe_step` VALUES (500544, 300068, 1, '洋葱切成条状、胡萝卜以及土豆切成块状，备用', NULL);
INSERT INTO `recipe_step` VALUES (500545, 300068, 2, '烧一锅开水，水沸时将肥牛卷下锅，捞出血沫后放在一边沥水，备用', NULL);
INSERT INTO `recipe_step` VALUES (500546, 300068, 3, '热锅，锅内放入 10ml - 15ml 食用油，等待 10 秒让油温升高', NULL);
INSERT INTO `recipe_step` VALUES (500547, 300068, 4, '放入洋葱，翻炒至洋葱变软变透明', NULL);
INSERT INTO `recipe_step` VALUES (500548, 300068, 5, '放入土豆以及胡萝卜翻炒 2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500549, 300068, 6, '加入冷水至淹没所有食材即可', NULL);
INSERT INTO `recipe_step` VALUES (500550, 300068, 7, '将香叶、咖喱块投入锅中，盖上锅盖，待水沸腾后将火调小然后等待直至土豆块以及胡萝卜块炖至软烂（可用筷子确认）', NULL);
INSERT INTO `recipe_step` VALUES (500551, 300068, 8, '加入肥牛卷以及牛奶，盖上锅盖再小火煮 2-3 分钟即可出锅（用勺子搅拌食材，注意力度，避免肥牛卷破碎）', NULL);
INSERT INTO `recipe_step` VALUES (500552, 300069, 1, '如果加入冬笋，切薄片后冷水下锅煮 10 分钟去涩味', NULL);
INSERT INTO `recipe_step` VALUES (500553, 300069, 2, '咸肉切 1 cm 小丁', NULL);
INSERT INTO `recipe_step` VALUES (500554, 300069, 3, '咸肉和冬笋冷锅下 10 g 猪油、料酒、白糖，中小火煸炒到透明冒泡', NULL);
INSERT INTO `recipe_step` VALUES (500555, 300069, 4, '青菜切碎，菜梗和菜叶分开放，菜梗切成 0.5 cm 边长的正方形小块，菜叶切成长 2-3 cm，宽 1-1.5 cm 的长方形小块', NULL);
INSERT INTO `recipe_step` VALUES (500556, 300069, 5, '菜梗下锅炒到翡翠色', NULL);
INSERT INTO `recipe_step` VALUES (500557, 300069, 6, '米淘净后倒进电饭煲，加水', NULL);
INSERT INTO `recipe_step` VALUES (500558, 300069, 7, '把炒好的咸肉和菜梗铺在米上', NULL);
INSERT INTO `recipe_step` VALUES (500559, 300069, 8, '正常煮饭模式启动，最后 10 分钟开盖快速铺入菜叶', NULL);
INSERT INTO `recipe_step` VALUES (500560, 300069, 9, '煮好后焖 5 分钟，再淋 5 g 猪油、白胡椒粉疯狂翻拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (500561, 300070, 1, '咸蛋黄狮子头放入卤汤中，卤制10分钟再关火焖10分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500562, 300071, 1, '狮子头蒸制20分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500563, 300071, 2, '出品撒1g葱花。', NULL);
INSERT INTO `recipe_step` VALUES (500564, 300072, 1, '将鳝鱼切成三段后切成细丝', NULL);
INSERT INTO `recipe_step` VALUES (500565, 300072, 2, '加入 0.5 g 胡椒粉、3 g 料酒搅拌均匀，再加入 5 g 香油腌制', NULL);
INSERT INTO `recipe_step` VALUES (500566, 300072, 3, '热油滑锅', NULL);
INSERT INTO `recipe_step` VALUES (500567, 300072, 4, '加入植物油，烧到 6 成热', NULL);
INSERT INTO `recipe_step` VALUES (500568, 300072, 5, '加入一半蒜末和全部姜末，翻炒几下', NULL);
INSERT INTO `recipe_step` VALUES (500569, 300072, 6, '加入鳝丝，中火爆炒 30 秒', NULL);
INSERT INTO `recipe_step` VALUES (500570, 300072, 7, '边缘淋入 10 g 料酒，翻炒几下', NULL);
INSERT INTO `recipe_step` VALUES (500571, 300072, 8, '加入生抽，炒匀', NULL);
INSERT INTO `recipe_step` VALUES (500572, 300072, 9, '加入蚝油、老抽，翻炒几下', NULL);
INSERT INTO `recipe_step` VALUES (500573, 300072, 10, '加入食用盐、白糖、3 g 胡椒粉，炒匀', NULL);
INSERT INTO `recipe_step` VALUES (500574, 300072, 11, '淀粉和水混合为水淀粉，倒入锅中，收汁至浓稠', NULL);
INSERT INTO `recipe_step` VALUES (500575, 300072, 12, '装盘，撒上蒜蓉、葱花', NULL);
INSERT INTO `recipe_step` VALUES (500576, 300072, 13, '另起锅烧热，加入猪油，烧至七成热，浇在鳝丝上', NULL);
INSERT INTO `recipe_step` VALUES (500577, 300073, 1, '将肉刮洗干净，入煮锅煮至六成熟（变色为白），捞出趁热用蜂蜜、醋涂抹肉皮。', NULL);
INSERT INTO `recipe_step` VALUES (500578, 300073, 2, '炒锅内放入熟猪油，用旺火烧至八成熟（约 200 度，油表有大量青烟，油状平静），将肉块皮朝下投入，炸至呈金红色时，捞入凉肉煮锅（之前煮完的煮锅）中泡软，放在案板上，切成三寸(10 cm)长、两分(0.6 cm)厚的片，仍然皮朝下，整齐装入蒸碗内。', NULL);
INSERT INTO `recipe_step` VALUES (500579, 300073, 3, '将 5 克大葱切成 2.4 cm 长的段，5 克切成 2.4 cm 长的斜形片。姜去皮洗净，1.5 克切成片，5 克切成末，摊的鸡蛋皮切成 2.4 cm 长的等腰三角形片。', NULL);
INSERT INTO `recipe_step` VALUES (500580, 300073, 4, '商芝入沸水锅中煮软捞出，去除老茎、杂质，淘洗干净，切成 3 cm 长的段，放入碗中,加酱油（5 克）、精盐（1 克）、熟猪油（10 克）拌匀，盖在肉片上，另将鸡汤（100 克）放入一小碗中，加酱油（5 克）、精盐（0.5 克）、料酒（15 克）搅匀，浇入蒸碗，再放入姜片、葱段、八角上笼用旺火蒸约半小时后，转用小火继续蒸约一小时三十分钟，熟烂后取出，拣去姜、葱、八角，倒、过滤原汁，将肉扣入汤盘。', NULL);
INSERT INTO `recipe_step` VALUES (500581, 300073, 5, '炒锅内，放入鸡汤（100 克），加入原汁，用旺火烧沸，下入姜末、葱片、味精后搅匀，投入摊鸡蛋皮，淋芝麻油，浇入汤盘即成。', NULL);
INSERT INTO `recipe_step` VALUES (500582, 300074, 1, '把鸭子切成 3 cm 小块，鸭肉冷水下锅，加姜片、料酒，焯一遍水，盛出沥干水分，备用。', NULL);
INSERT INTO `recipe_step` VALUES (500583, 300074, 2, '炒锅烧热，放入约 100ml 食用油，大火待油烧开，鸭肉入锅翻炒至上色。', NULL);
INSERT INTO `recipe_step` VALUES (500584, 300074, 3, '待鸭肉完全变色（肉眼可见泛白），将鸭肉拨到锅的一边，倒入豆瓣酱和糖，小火翻炒出香味和糖色。', NULL);
INSERT INTO `recipe_step` VALUES (500585, 300074, 4, '加入丁香、八角、香叶、干辣椒、生抽、老抽、蒜，翻炒出香味。', NULL);
INSERT INTO `recipe_step` VALUES (500586, 300074, 5, '倒入啤酒，没过鸭肉，加入盐、鸡精，然后中火将鸭子烧 30 分钟（牙口不好的话可以再多烧 5 分钟）。', NULL);
INSERT INTO `recipe_step` VALUES (500587, 300074, 6, '出锅盛盘，上桌食用。', NULL);
INSERT INTO `recipe_step` VALUES (500588, 300075, 1, '油炸炉升温至170℃；', NULL);
INSERT INTO `recipe_step` VALUES (500589, 300075, 2, '炸制时间：香脆鸡腿炸制7 分钟，鸡肉洋葱圈、鸡翅尖、薯饼、鸡米花均炸制3 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500590, 300075, 3, '出品组合：1 个鸡腿、2 个洋葱圈、2 个鸡翅尖、1 个薯饼、3 个鸡米花。', NULL);
INSERT INTO `recipe_step` VALUES (500591, 300076, 1, '钵钵鸡汤底：锅中加入2000g 水，放入320g 钵钵鸡汤底料、450g 钵钵鸡红油、60g 白芝麻，搅拌均匀，备用；', NULL);
INSERT INTO `recipe_step` VALUES (500592, 300076, 2, '将解冻好的10 串钵钵鸡串串，焯水1 分30 秒；', NULL);
INSERT INTO `recipe_step` VALUES (500593, 300076, 3, '将串串浸泡在钵钵鸡汤底中，小火烧开后焖5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500594, 300077, 1, '10 份泡椒骨汤汤底调制：2900g 开水中加入140g 骨汤调味料、700g 泡椒调味料，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (500595, 300077, 2, '奶锅中加入370g 泡椒骨汤汤底烧开；', NULL);
INSERT INTO `recipe_step` VALUES (500596, 300077, 3, '下入50g 西红柿片、50g 娃娃菜、20g 木耳丝，20g 海带丝烧开后煮2 分钟，倒入红底座锅中；', NULL);
INSERT INTO `recipe_step` VALUES (500597, 300077, 4, '将250g 湿米线在沸水中煮2 分30 秒后，倒入红底座锅中，放入60g 炸制好的鸡米花出品。', NULL);
INSERT INTO `recipe_step` VALUES (500598, 300078, 1, '7 份番茄汤底调制：2500g 开水中加入 500g 番茄汤膏，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (500599, 300078, 2, '取 400g 番茄汤底倒入奶锅中烧开；', NULL);
INSERT INTO `recipe_step` VALUES (500600, 300078, 3, '下入 120g 娃娃菜、50g 金针菇、50g 木耳、50g 青菜煮 1 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500601, 300078, 4, '最后下入 100g 肥牛卷煮 1 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (500602, 300079, 1, '10 份米线汤底调制：3500g 开水中加入400g 豆米骨汤调味料、350g 泡椒调味料，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (500603, 300079, 2, '奶锅中加入420g 米线汤底烧开，下入70g 小叶酸菜，烧开；', NULL);
INSERT INTO `recipe_step` VALUES (500604, 300079, 3, '下入120g 鱼片烧开后煮2 分钟，倒入红底座锅中；', NULL);
INSERT INTO `recipe_step` VALUES (500605, 300079, 4, '将250g 湿米线在沸水中煮2 分30 秒后，倒入红底座锅中出品。', NULL);
INSERT INTO `recipe_step` VALUES (500606, 300080, 1, '10 份底汤调制：3100g 开水中加入 400g 豆米骨汤调味料，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (500607, 300080, 2, '取 350g 底汤加入奶锅中烧开；', NULL);
INSERT INTO `recipe_step` VALUES (500608, 300080, 3, '下入 120g 娃娃菜、80g 西红柿片、50g 金针菇、50g 木耳、50g 青菜煮 2 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (500609, 300081, 1, '【五花肉一段处理】锅烧热，用手将五花肉紧紧压在锅上炙皮 这一步是为了处理猪皮上的汗腺（或者买肉的时候让师傅烧一下皮，喜欢汗腺的可以无视）', NULL);
INSERT INTO `recipe_step` VALUES (500610, 300081, 2, '【五花肉一段处理】用钢丝球把皮刷干净，至黑色部分碳化部分被完全去除，不刷干净会有苦味', NULL);
INSERT INTO `recipe_step` VALUES (500611, 300081, 3, '【五花肉一段处理】将五花肉放入锅中，放入能淹没五花肉的冷水，放入生姜片、料酒和小葱（取 2 棵小葱打结）', NULL);
INSERT INTO `recipe_step` VALUES (500612, 300081, 4, '【五花肉一段处理】开大火煮，水开后撇去浮沫，继续煮 15 分钟，煮至瘦肉部分可以用筷子轻松刺穿', NULL);
INSERT INTO `recipe_step` VALUES (500613, 300081, 5, '【配菜处理】青红椒切圈', NULL);
INSERT INTO `recipe_step` VALUES (500614, 300081, 6, '【配菜处理】蒜苗切段', NULL);
INSERT INTO `recipe_step` VALUES (500615, 300081, 7, '【配菜处理】生姜切小薄片', NULL);
INSERT INTO `recipe_step` VALUES (500616, 300081, 8, '【配菜处理】将 5ml 豆瓣酱和 5ml 生抽提前混合', NULL);
INSERT INTO `recipe_step` VALUES (500617, 300081, 9, '【五花肉二段处理】将煮熟的五花肉捞出放入冷水晾凉', NULL);
INSERT INTO `recipe_step` VALUES (500618, 300081, 10, '【五花肉二段处理】擦干五花肉的水，切成上肥下瘦的 2mm 的薄片（切厚了口感不好，而且很油）', NULL);
INSERT INTO `recipe_step` VALUES (500619, 300081, 11, '【开始炒肉】锅烧热，放入一层底油滑锅', NULL);
INSERT INTO `recipe_step` VALUES (500620, 300081, 12, '【开始炒肉】放入五花肉煸炒至肥肉透明，肉片微卷（欲称起灯盏窝），二刀肉效果最佳。', NULL);
INSERT INTO `recipe_step` VALUES (500621, 300081, 13, '【开始炒肉】倒入豆瓣生抽混合物，5g 味精翻炒 15 秒', NULL);
INSERT INTO `recipe_step` VALUES (500622, 300081, 14, '【开始炒肉】放入青红椒圈和小姜片，放入另 5ml 豆瓣酱翻炒 30 秒', NULL);
INSERT INTO `recipe_step` VALUES (500623, 300081, 15, '【开始炒肉】放入蒜苗翻炒 60 秒', NULL);
INSERT INTO `recipe_step` VALUES (500624, 300081, 16, '【开始炒肉】出锅', NULL);
INSERT INTO `recipe_step` VALUES (500625, 300081, 17, '【简易版本】选用冰冻五花肉常量放置 0.5 小时 或者鲜五花肉放冰箱冷藏 1 个小时，切成 2-5 mm 薄片', NULL);
INSERT INTO `recipe_step` VALUES (500626, 300081, 18, '【简易版本】开中火，辣椒放过锅中干煸 30-45 秒后取出', NULL);
INSERT INTO `recipe_step` VALUES (500627, 300081, 19, '【简易版本】锅烧热，放入一层底油滑锅，放入姜片煸炒 15 秒', NULL);
INSERT INTO `recipe_step` VALUES (500628, 300081, 20, '【简易版本】倒入五花肉，间隔 10 S 翻炒一次，待五花肉出现焦黄色（翻炒时间越久五花肉口感越硬）', NULL);
INSERT INTO `recipe_step` VALUES (500629, 300081, 21, '【简易版本】倒入之前干煸过的辣椒、10ml 豆瓣酱，生抽调味，继续翻炒 60 秒', NULL);
INSERT INTO `recipe_step` VALUES (500630, 300081, 22, '【简易版本】倒入切成段的蒜苗翻炒 10 秒', NULL);
INSERT INTO `recipe_step` VALUES (500631, 300081, 23, '【简易版本】出锅', NULL);
INSERT INTO `recipe_step` VALUES (500632, 300082, 1, '【预处理：食材切配与防氧化】处理土豆： 将 300g 土豆去皮，切成不规则的滚刀块 。切好后立刻泡入一盆清水中，隔绝氧气防止表面氧化发黑，备用。', NULL);
INSERT INTO `recipe_step` VALUES (500633, 300082, 2, '【预处理：食材切配与防氧化】处理葱姜： 将 30g 姜全部切成薄片（分成两份 15g）。将 25g 小葱处理好：15g 挽成一个葱结，剩余 10g 切成细小葱花备用。', NULL);
INSERT INTO `recipe_step` VALUES (500634, 300082, 3, '【预处理：调料封装与异步任务】封装酱汁碗（一键调用）： 拿一个小碗，依次加入 10ml 生抽、5ml 老抽、5ml 蚝油、5ml 黄豆酱，彻底搅拌均匀，放在灶台触手可及处备用。', NULL);
INSERT INTO `recipe_step` VALUES (500635, 300082, 4, '【预处理：调料封装与异步任务】封装香料碟（一键调用）： 拿一个小碟，放入 5g 干辣椒、1g 八角（约 1-2 颗）、1g 花椒（约 10 粒）、1g 桂皮（一小块），以及刚才切好的 15g 姜片，备用。', NULL);
INSERT INTO `recipe_step` VALUES (500636, 300082, 5, '【预处理：调料封装与异步任务】开启异步水程： 按下电热水壶开关，开始烧制 700ml 开水。（确保炒制完成时，开水刚好就绪）。', NULL);
INSERT INTO `recipe_step` VALUES (500637, 300082, 6, '【初步加工：排骨焯水与脱水】冷水焯水： 将 750g 肋排冷水下锅，加入 15g 葱结、15g 姜片、15ml 料酒。大火煮沸后，继续保持沸腾焯水 2 分钟，逼出内部血沫。', NULL);
INSERT INTO `recipe_step` VALUES (500638, 300082, 7, '【初步加工：排骨焯水与脱水】热洗冷防： 捞出排骨，必须用热水将排骨表面残留的浮沫清洗干净（遇冷水肉质会剧烈收缩变硬）。', NULL);
INSERT INTO `recipe_step` VALUES (500639, 300082, 8, '【初步加工：排骨焯水与脱水】绝对脱水（防爆防溅）： 洗净的排骨必须用厨房纸彻底吸干表面水分，装盘放在炒锅旁边备用（防止后续下入高温糖色时发生剧烈炸锅）。', NULL);
INSERT INTO `recipe_step` VALUES (500640, 300082, 9, '【核心炒制：糖色与爆香（高并发阶段）】炒制糖色： 热锅凉油，加入 20ml 食用油。将 10g 白糖倒入锅中，中小火不停搅拌。翻炒至白糖完全融化冒泡，并呈现红棕色的焦糖色 。', NULL);
INSERT INTO `recipe_step` VALUES (500641, 300082, 10, '【核心炒制：糖色与爆香（高并发阶段）】上色煎制： 迅速加入彻底脱水的 750g 排骨，转中大火翻炒。煎制约 2-3 分钟，至排骨两面微微金黄，且均匀裹满焦糖色。', NULL);
INSERT INTO `recipe_step` VALUES (500642, 300082, 11, '【核心炒制：糖色与爆香（高并发阶段）】一键爆香： 在锅中拨出一小块空地，直接倒入【香料碟】。利用锅底的热油爆香约 10 秒，激发出香料的脂溶性香气。', NULL);
INSERT INTO `recipe_step` VALUES (500643, 300082, 12, '【核心炒制：糖色与爆香（高并发阶段）】一键调味： 顺着热锅边缘淋入剩余的 10ml 料酒激发出锅气。紧接着直接倒入【酱汁碗】，翻炒约 30 秒，让酱料完全包裹排骨并炒出浓郁酱香。', NULL);
INSERT INTO `recipe_step` VALUES (500644, 300082, 13, '【炖煮收汁：挂霜与出锅】加水长炖： 此时电热水壶已沸腾，直接加入 700ml 滚烫的开水（水量需没过排骨），大火烧开。随后盖上锅盖，转小火持续焖煮 40 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500645, 300082, 14, '【炖煮收汁：挂霜与出锅】加入土豆： 40 分钟后打开锅盖，将泡在水里的 300g 土豆捞出沥干，下入锅中。重新盖上锅盖，继续小火焖煮 15-20 分钟，直到用筷子能轻松扎透土豆块。', NULL);
INSERT INTO `recipe_step` VALUES (500646, 300082, 15, '【炖煮收汁：挂霜与出锅】调味收汁： 打开锅盖，加入 3g 盐（此时可尝一下汤汁，根据个人口味酌情微调）。转大火开始翻炒收汁，大约需要 3-5 分钟。直到汤汁变得浓稠，均匀地挂在排骨和土豆上即可关火。', NULL);
INSERT INTO `recipe_step` VALUES (500647, 300082, 16, '【炖煮收汁：挂霜与出锅】点缀出锅： 盛盘出锅，在表面均匀撒上预处理好的 10g 葱花作为 UI 点缀即可。', NULL);
INSERT INTO `recipe_step` VALUES (500648, 300083, 1, '锅中下入2130g 牛腩汤料、750g 土豆、300g 胡萝卜；', NULL);
INSERT INTO `recipe_step` VALUES (500649, 300083, 2, '混合炖烧10 分钟，期间不断翻拌防止糊锅，出品时撒1g葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (500650, 300084, 1, '【准备原料】土豆、茄子、尖椒洗净。', NULL);
INSERT INTO `recipe_step` VALUES (500651, 300084, 2, '【准备原料】土豆去皮。', NULL);
INSERT INTO `recipe_step` VALUES (500652, 300084, 3, '【准备原料】茄子、土豆均切成 15g 的不规则的小块。', NULL);
INSERT INTO `recipe_step` VALUES (500653, 300084, 4, '【准备原料】尖椒用手顺着纹路撕即可，撕成比土豆、茄子略大 25%的块。', NULL);
INSERT INTO `recipe_step` VALUES (500654, 300084, 5, '【准备原料】尽可能除去青椒表面的水分，避免后续炸的时候炸水。考虑使用厨房纸或风干半小时。', NULL);
INSERT INTO `recipe_step` VALUES (500655, 300084, 6, '【准备原料】葱切 0.5cm 小段，共取 5g。蒜剁碎成蒜蓉取 15g，分成两份，各 7.5g。姜切沫取 5g。', NULL);
INSERT INTO `recipe_step` VALUES (500656, 300084, 7, '【准备原料】拿一个空碗，放入生抽 10ml、糖 10g、淀粉 8g，加入 80ml 清水，彻底搅拌均匀，作为调料碗，备用。', NULL);
INSERT INTO `recipe_step` VALUES (500657, 300084, 8, '【初步煎炸】热锅，加入 150ml 油。', NULL);
INSERT INTO `recipe_step` VALUES (500658, 300084, 9, '【初步煎炸】加入土豆，煎炸大约 3-4 分钟，以显示金黄色、筷子能轻松扎透为准。', NULL);
INSERT INTO `recipe_step` VALUES (500659, 300084, 10, '【初步煎炸】捞出土豆，留下油。', NULL);
INSERT INTO `recipe_step` VALUES (500660, 300084, 11, '【初步煎炸】加入茄子，煎炸大约 2-3 分钟，待其到大约 7 分熟，以茄子变软、边缘微焦且吐出多余油脂为准。', NULL);
INSERT INTO `recipe_step` VALUES (500661, 300084, 12, '【初步煎炸】捞出茄子，留下油。（也可能没有残余的油了）', NULL);
INSERT INTO `recipe_step` VALUES (500662, 300084, 13, '【初步煎炸】如果锅内已经没有流动的油，可以考虑补充 15ml 油。', NULL);
INSERT INTO `recipe_step` VALUES (500663, 300084, 14, '【初步煎炸】加入尖椒块，煎炸大约 15 秒，边缘稍微起虎皮后，立刻捞出。倒出锅里的油。', NULL);
INSERT INTO `recipe_step` VALUES (500664, 300084, 15, '【最终煎炸】重新热锅，重新加入 15ml 新底油。', NULL);
INSERT INTO `recipe_step` VALUES (500665, 300084, 16, '【最终煎炸】放入葱 5g，姜 5g，蒜 7.5g。中小火爆香。', NULL);
INSERT INTO `recipe_step` VALUES (500666, 300084, 17, '【最终煎炸】放入豆瓣酱 15ml。转小火，炒出红油和酱香味。', NULL);
INSERT INTO `recipe_step` VALUES (500667, 300084, 18, '【最终煎炸】倒入调料碗。立刻转大火，高速搅拌避免糊锅！大约 10 秒后汤汁就会开始冒泡并变得黏稠。', NULL);
INSERT INTO `recipe_step` VALUES (500668, 300084, 19, '【最终煎炸】立刻放入之前准备好的全部土豆、茄子和尖椒。', NULL);
INSERT INTO `recipe_step` VALUES (500669, 300084, 20, '【最终煎炸】翻炒 20 秒，让浓稠的酱汁均匀挂在食材上。', NULL);
INSERT INTO `recipe_step` VALUES (500670, 300084, 21, '【最终煎炸】关火，撒入 7.5g 蒜。翻拌均匀，盛盘。', NULL);
INSERT INTO `recipe_step` VALUES (500671, 300085, 1, '【酵头的制作】首先，将酵母和 30℃ 的温水 用刮刀或厨具混合均匀，静置 5 分钟。之后与面粉混合，搅拌均匀。此时的酵头应该是特别粘稠的面糊。', NULL);
INSERT INTO `recipe_step` VALUES (500672, 300085, 2, '【酵头的制作】用布盖上面糊，将面糊放置到温暖的地方进行发酵，时长为 45 ~ 60 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500673, 300085, 3, '【酵头的制作】最终的面糊应该是表面有很多气泡的且体积明显增大。', NULL);
INSERT INTO `recipe_step` VALUES (500674, 300085, 4, '【面团的制作】将剩下的原料全部与酵头用刮刀混合、搅拌。在搅拌时一定要刮壁，使其充分混合。在形成面团且没有干粉时，用干净的干燥的一只手按压面团，另一只手扶住容器，使其形成一个大的面团，然后倒在面板或硅胶垫上操作', NULL);
INSERT INTO `recipe_step` VALUES (500675, 300085, 5, '【面团的制作】用手掌下部推开面团，然后对折再次推开，直至表面没有干粉结块。这时的面团还不是很光滑。', NULL);
INSERT INTO `recipe_step` VALUES (500676, 300085, 6, '【面团的制作】使用喷壶将至少是当前面团三倍大的容器内喷上一层植物油（也可用手涂抹均匀），将面团放入并盖上布，发酵 1 小时。', NULL);
INSERT INTO `recipe_step` VALUES (500677, 300085, 7, '【面团的制作】此时面团应该有原来的两倍大。在面板或硅胶垫上撒上薄薄的一层面粉（可以看见面板或硅胶垫的厚度即可），然后将面团拿出，用手压瘪面团排气。', NULL);
INSERT INTO `recipe_step` VALUES (500678, 300085, 8, '【面团的制作】之后使用擀面杖，擀成 1 cm 的厚片。并紧实、不留空隙地从一边卷起来。', NULL);
INSERT INTO `recipe_step` VALUES (500679, 300085, 9, '【面团的制作】然后旋转 90° ，重复步骤 4、步骤 5 。', NULL);
INSERT INTO `recipe_step` VALUES (500680, 300085, 10, '【面团的制作】将面包整形，放到垫了硅油纸的烤盘或者涂抹油脂的模具内。注意接缝处朝下。', NULL);
INSERT INTO `recipe_step` VALUES (500681, 300085, 11, '【面团的制作】在托盘或模具内，发酵 30 ~ 45 分钟 。', NULL);
INSERT INTO `recipe_step` VALUES (500682, 300085, 12, '【面团的制作】于此同时，预热烤箱。', NULL);
INSERT INTO `recipe_step` VALUES (500683, 300085, 13, '【面团的制作】在面包上用剪子或者刀划开几条缝作为面包的花纹。', NULL);
INSERT INTO `recipe_step` VALUES (500684, 300085, 14, '【面团的制作】用刷子刷上蛋液。（可选）', NULL);
INSERT INTO `recipe_step` VALUES (500685, 300085, 15, '【面团的制作】放入烤箱，上下火 180℃ 烤制 30 分钟，然后调 165 ℃ 再烤 10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500686, 300085, 16, '【面团的制作】放凉后装入食品袋内，可保存一个星期。冷冻可保存一个月。', NULL);
INSERT INTO `recipe_step` VALUES (500687, 300086, 1, '锅中倒入 250g 大豆油烧热，将 800g 鸡蛋液炒成鸡蛋片状，盛装出锅备用；', NULL);
INSERT INTO `recipe_step` VALUES (500688, 300086, 2, '下入20g 大豆油、20g 鲜红小米辣、200g 青豌豆，炒出香', NULL);
INSERT INTO `recipe_step` VALUES (500689, 300086, 3, '下入1000g 外婆菜、加25g 鸡精、40g 生抽，大火爆炒2', NULL);
INSERT INTO `recipe_step` VALUES (500690, 300086, 4, '加入鸡蛋片，翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (500691, 300087, 1, '牛腩烧制：', NULL);
INSERT INTO `recipe_step` VALUES (500692, 300087, 2, '10 份底汤调制：2400g 开水中加入120g 汤料，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (500693, 300087, 3, '将130g 鲜面和25g 青菜在沸水中煮2 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500694, 300087, 4, '面碗中加入20g 牛肉面汤底料、20g 红油、5g 蒜蓉、5g熟猪油、250g 底汤，放入煮好的面条；', NULL);
INSERT INTO `recipe_step` VALUES (500695, 300087, 5, '将80g 牛腩和25g 青菜摆放在面条上，加入20g 牛腩汤汁，撒入5g 香菜、5g 葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (500696, 300088, 1, '大排卤制：', NULL);
INSERT INTO `recipe_step` VALUES (500697, 300088, 2, '10 份面条汤底配制：不锈钢桶中加入3500g 水烧开，下入150g 熟猪油、30g 盐、10g 老抽烧开，保温备用；', NULL);
INSERT INTO `recipe_step` VALUES (500698, 300088, 3, '将110g 手工挂面和3 颗青菜在沸水中煮3 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500699, 300088, 4, '舀取350g 面条汤底放入面碗中，再放入煮好的面条；', NULL);
INSERT INTO `recipe_step` VALUES (500700, 300088, 5, '将1 块大排、3 颗青菜、半个卤蛋放于面条上，加入30g卤汤，撒入5g 蒜花出品。', NULL);
INSERT INTO `recipe_step` VALUES (500701, 300089, 1, '鸡块制作：', NULL);
INSERT INTO `recipe_step` VALUES (500702, 300089, 2, '下入350g 菜籽油、200g 猪油、清洗好沥干水分的3200g鸡块，煸炒至表皮微黄；', NULL);
INSERT INTO `recipe_step` VALUES (500703, 300089, 3, '下入50g 葱、140g 姜、200g 蒜，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (500704, 300089, 4, '下入800g 肥肠鸡酱料，翻炒均匀；', NULL);
INSERT INTO `recipe_step` VALUES (500705, 300089, 5, '下入3000g 水、40g 盐，煮制2 分钟即可倒出，鸡块和汤备用。', NULL);
INSERT INTO `recipe_step` VALUES (500706, 300089, 6, '面片制作：', NULL);
INSERT INTO `recipe_step` VALUES (500707, 300089, 7, '解冻完全的每个面胚扯成30-35cm 长的面片；', NULL);
INSERT INTO `recipe_step` VALUES (500708, 300089, 8, '放入沸水中，煮制2 分钟，放入餐具中；', NULL);
INSERT INTO `recipe_step` VALUES (500709, 300089, 9, '锅里放入450g 炒好的鸡块、70g 焯水的芋艿、40g 肥肠，烧开煮3 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500710, 300089, 10, '再下入8g 线椒、5g 鲜红小米辣、10g 芝麻香油、5g 花椒油，继续煮制1 分钟，关火倒入餐具中；', NULL);
INSERT INTO `recipe_step` VALUES (500711, 300089, 11, '20g 大豆油烧热，加入2g 干青花椒、5g 干红辣椒段，炸出香味后均匀淋到菜上；', NULL);
INSERT INTO `recipe_step` VALUES (500712, 300089, 12, '最后点缀5g 白芝麻、5g 香菜段出品。', NULL);
INSERT INTO `recipe_step` VALUES (500713, 300090, 1, '【可控火候微波炉】准备一个小碗，倒入在上一步计算好的油，撒盐，搅拌均匀。倾斜碗使油沾在碗表面。', NULL);
INSERT INTO `recipe_step` VALUES (500714, 300090, 2, '【可控火候微波炉】取出一个鸡蛋，打入小碗。', NULL);
INSERT INTO `recipe_step` VALUES (500715, 300090, 3, '【可控火候微波炉】蛋黄表面戳孔。牙签戳 5 个或筷子戳 1 个。', NULL);
INSERT INTO `recipe_step` VALUES (500716, 300090, 4, '【可控火候微波炉】放入微波炉，中火 3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500717, 300090, 5, '【不可控火候微波炉】准备一个小碗，倒入在上一步计算好的油，撒盐，搅拌均匀。倾斜碗使油沾在碗表面。', NULL);
INSERT INTO `recipe_step` VALUES (500718, 300090, 6, '【不可控火候微波炉】取出一个鸡蛋，打入小碗。', NULL);
INSERT INTO `recipe_step` VALUES (500719, 300090, 7, '【不可控火候微波炉】蛋黄表面戳孔。牙签戳 5 个或筷子戳 1 个。', NULL);
INSERT INTO `recipe_step` VALUES (500720, 300090, 8, '【不可控火候微波炉】放入微波炉，1 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500721, 300090, 9, '【不可控火候微波炉】while（太阳蛋 否 大面积成固体状） 用微波炉打(30s);', NULL);
INSERT INTO `recipe_step` VALUES (500722, 300091, 1, '将猕猴桃切成两半，每半再分四份小块', NULL);
INSERT INTO `recipe_step` VALUES (500723, 300091, 2, '将苹果切丁', NULL);
INSERT INTO `recipe_step` VALUES (500724, 300091, 3, '将菠菜叶去梗，只留叶子部分', NULL);
INSERT INTO `recipe_step` VALUES (500725, 300091, 4, '将菠菜切碎', NULL);
INSERT INTO `recipe_step` VALUES (500726, 300091, 5, '一起倒入榨汁机搅拌杯', NULL);
INSERT INTO `recipe_step` VALUES (500727, 300091, 6, '注水', NULL);
INSERT INTO `recipe_step` VALUES (500728, 300091, 7, '加入白砂糖', NULL);
INSERT INTO `recipe_step` VALUES (500729, 300091, 8, '启动搅拌机，搅拌约 4 个 15 秒（每 15 秒停下看状态）', NULL);
INSERT INTO `recipe_step` VALUES (500730, 300092, 1, '将奥利奥拧开后去除利利（夹心），备用', NULL);
INSERT INTO `recipe_step` VALUES (500731, 300092, 2, '用筷子将奥奥剁碎，需要有一半奥奥变成粉状，另一半的奥奥最大长度小于 0.5 厘米，备用（某宝可搜“奥利奥饼干碎”，节省时间精力^-^）', NULL);
INSERT INTO `recipe_step` VALUES (500732, 300092, 3, '将奶油全部倒置于深容器中，并加入准备好的糖', NULL);
INSERT INTO `recipe_step` VALUES (500733, 300092, 4, '开始用电动打蛋器高速挡 搅打至 电动打蛋器提起后下方会出现悬挂住的奶油（ 0.5 厘米 - 1 厘米），而不是全部像液体一样滴下（部分滴下是正常现象）。', NULL);
INSERT INTO `recipe_step` VALUES (500734, 300092, 5, '搅打完成后将奥奥放入奶油中，搅拌均匀直至底部有奥奥。', NULL);
INSERT INTO `recipe_step` VALUES (500735, 300092, 6, '可选：将混合物倒入冰淇淋模具中', NULL);
INSERT INTO `recipe_step` VALUES (500736, 300092, 7, '放置冰箱冷冻室（ -18 度） 4 小时以上可取出', NULL);
INSERT INTO `recipe_step` VALUES (500737, 300093, 1, '解冻手枪腿鸡腿并洗净。', NULL);
INSERT INTO `recipe_step` VALUES (500738, 300093, 2, '手枪腿鸡腿改花刀：在每只手枪腿鸡腿的\"枪管\"处，平行于\"枪管\"用小刀切 4-6 刀，下刀尽可能深。', NULL);
INSERT INTO `recipe_step` VALUES (500739, 300093, 3, '拿一个锅，加入 15 - 20 g 新奥尔良烤翅调料粉、5 g 盐，≥30 mL 水。', NULL);
INSERT INTO `recipe_step` VALUES (500740, 300093, 4, '将改完花刀的手枪腿鸡腿放入锅内，搅匀。', NULL);
INSERT INTO `recipe_step` VALUES (500741, 300093, 5, '将整个锅放入冰箱冷藏层冷藏 2 - 4 小时，时间越长越入味。', NULL);
INSERT INTO `recipe_step` VALUES (500742, 300093, 6, '在烤盘上放一张铝箔纸，将鸡腿取出，皮面向下放上去（不要弄破铝箔纸）。丢弃锅内剩余的液体。', NULL);
INSERT INTO `recipe_step` VALUES (500743, 300093, 7, '放入烤箱中上层，按照如下参数烘烤：', NULL);
INSERT INTO `recipe_step` VALUES (500744, 300093, 8, '取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）', NULL);
INSERT INTO `recipe_step` VALUES (500745, 300093, 9, '对所有手枪腿鸡腿翻面。', NULL);
INSERT INTO `recipe_step` VALUES (500746, 300093, 10, '放入烤箱上层，按照如下参数烘烤：', NULL);
INSERT INTO `recipe_step` VALUES (500747, 300093, 11, '取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）', NULL);
INSERT INTO `recipe_step` VALUES (500748, 300093, 12, '放入烤箱上层，按照如下参数烘烤：', NULL);
INSERT INTO `recipe_step` VALUES (500749, 300093, 13, '取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）', NULL);
INSERT INTO `recipe_step` VALUES (500750, 300093, 14, '取一个小碗，按照 10:1 - 2:1 体积比，加入大碗中的油脂和豉油调味汁。调味汁越多越咸，具体加入量取决于个人口味。', NULL);
INSERT INTO `recipe_step` VALUES (500751, 300093, 15, '抓住手枪腿鸡腿根部，蘸取小碗中的液体，可使用餐巾纸或手套隔油。现在可以直接从烤盘铝箔纸上享用奥尔良风味烤鸡腿了。', NULL);
INSERT INTO `recipe_step` VALUES (500752, 300094, 1, '腌制流程老乡鸡官方未提供，请根据个人口味酌情处理。', NULL);
INSERT INTO `recipe_step` VALUES (500753, 300094, 2, '蒸制版：将解冻好的奥尔良鸡翅放入上汽后的蒸柜中，蒸制 20 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500754, 300094, 3, '炸制版：将解冻好的奥尔良鸡翅，放入 170℃油中，炸制 8 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (500755, 300095, 1, '白蘑菇切片备用，洋葱切末备用。', NULL);
INSERT INTO `recipe_step` VALUES (500756, 300095, 2, '平底锅中放入黄油，小火融化后加入洋葱炒至透明。', NULL);
INSERT INTO `recipe_step` VALUES (500757, 300095, 3, '加入白蘑菇翻炒至出水变软，撒入面粉搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (500758, 300095, 4, '加入牛奶和清水，搅拌均匀后小火煮沸，保持搅拌防止糊底。', NULL);
INSERT INTO `recipe_step` VALUES (500759, 300095, 5, '转小火煮约 10 分钟，汤汁浓稠。', NULL);
INSERT INTO `recipe_step` VALUES (500760, 300095, 6, '倒入淡奶油继续加热 1 分钟，加入盐和黑胡椒调味。', NULL);
INSERT INTO `recipe_step` VALUES (500761, 300095, 7, '熄火后可用料理机打成细腻浓汤（可选）。', NULL);
INSERT INTO `recipe_step` VALUES (500762, 300096, 1, '6 盒牛奶加热到 43℃；', NULL);
INSERT INTO `recipe_step` VALUES (500763, 300096, 2, '加入 2L 稀奶油、400g 糖、2 罐炼乳、80g 基料粉，搅拌升温到 70℃；', NULL);
INSERT INTO `recipe_step` VALUES (500764, 300096, 3, '降温到 43℃ 以下，加入 1g 菌粉搅拌均匀；', NULL);
INSERT INTO `recipe_step` VALUES (500765, 300096, 4, '按照 80g/杯分装，醒发 8 小时后再冷藏 8 小时，出品。', NULL);
INSERT INTO `recipe_step` VALUES (500766, 300097, 1, '取袋泡红茶 2 包放入杯中，加入 180-200mL 沸水。', NULL);
INSERT INTO `recipe_step` VALUES (500767, 300097, 2, '等待 20 - 30 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500768, 300097, 3, '称取 11-12g 奶粉和 5-7g 砂糖，分别加入前一步骤得到的液体中。', NULL);
INSERT INTO `recipe_step` VALUES (500769, 300097, 4, '搅拌均匀即可饮用。', NULL);
INSERT INTO `recipe_step` VALUES (500770, 300098, 1, '奶酪要磨成碎末', NULL);
INSERT INTO `recipe_step` VALUES (500771, 300098, 2, '洋葱切成条状', NULL);
INSERT INTO `recipe_step` VALUES (500772, 300098, 3, '通心粉用微咸的水煮 6 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500773, 300098, 4, '中火', NULL);
INSERT INTO `recipe_step` VALUES (500774, 300098, 5, '锅中放入黄油，等待融化', NULL);
INSERT INTO `recipe_step` VALUES (500775, 300098, 6, '加入洋葱', NULL);
INSERT INTO `recipe_step` VALUES (500776, 300098, 7, '洋葱软化后加入大蒜', NULL);
INSERT INTO `recipe_step` VALUES (500777, 300098, 8, '大蒜香味出来后，加入肉类，等待 5 秒', NULL);
INSERT INTO `recipe_step` VALUES (500778, 300098, 9, '小火', NULL);
INSERT INTO `recipe_step` VALUES (500779, 300098, 10, '分四次加入牛奶，每次搅拌 5 秒后再加下一次', NULL);
INSERT INTO `recipe_step` VALUES (500780, 300098, 11, '加入面粉并充分搅拌', NULL);
INSERT INTO `recipe_step` VALUES (500781, 300098, 12, '加入奶酪并搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (500782, 300098, 13, '将通心粉和奶酪搅拌', NULL);
INSERT INTO `recipe_step` VALUES (500783, 300098, 14, '如果不打算烘烤，可以直接吃了', NULL);
INSERT INTO `recipe_step` VALUES (500784, 300098, 15, '烘烤：', NULL);
INSERT INTO `recipe_step` VALUES (500785, 300098, 16, '预热烤箱至 180°C', NULL);
INSERT INTO `recipe_step` VALUES (500786, 300098, 17, '将额外的 50g 芝士铺在通心粉之上', NULL);
INSERT INTO `recipe_step` VALUES (500787, 300098, 18, '等待烤箱预热至 180°C 后，将通心粉放入', NULL);
INSERT INTO `recipe_step` VALUES (500788, 300098, 19, '烤至表面金黄,约 24 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500789, 300099, 1, '蒸柜上汽后，蒸制 8 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500790, 300100, 1, '鸡尽量剁成 1cm 的小块，洗净后滤干，再放生抽腌和料酒腌制 30 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500791, 300100, 2, '大先热锅到微微冒烟，放入食用油，等 5 秒', NULL);
INSERT INTO `recipe_step` VALUES (500792, 300100, 3, '下入姜片后转中火炒 30 秒，', NULL);
INSERT INTO `recipe_step` VALUES (500793, 300100, 4, '下入鸡块翻炒 3 分钟，炒干水分，炒出鸡油', NULL);
INSERT INTO `recipe_step` VALUES (500794, 300100, 5, '放入各种剁碎的辣椒和大蒜子，加盐和老抽继续翻炒 30 秒', NULL);
INSERT INTO `recipe_step` VALUES (500795, 300100, 6, '倒入啤酒，中小火焖 2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500796, 300100, 7, '大火收汁盛盘', NULL);
INSERT INTO `recipe_step` VALUES (500797, 300101, 1, '四个鸡腿清洗干净，放入碗中', NULL);
INSERT INTO `recipe_step` VALUES (500798, 300101, 2, '碗中加入盐焗鸡粉和 5ml 油，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (500799, 300101, 3, '让鸡腿静置腌制 15 分钟， 同时准备蒸锅并把水煮开', NULL);
INSERT INTO `recipe_step` VALUES (500800, 300101, 4, '鸡腿腌制完成后， 放入水开后的蒸锅中，蒸制 20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500801, 300101, 5, '将姜根据个人口味切成 1）姜蓉或 2）姜丝或 3）姜粒', NULL);
INSERT INTO `recipe_step` VALUES (500802, 300101, 6, '将葱切成 0.5cm 小段', NULL);
INSERT INTO `recipe_step` VALUES (500803, 300101, 7, '将葱姜放入蘸料碗，并加入盐和糖', NULL);
INSERT INTO `recipe_step` VALUES (500804, 300101, 8, '将剩余的油倒入另一个锅中加热至六至七层热', NULL);
INSERT INTO `recipe_step` VALUES (500805, 300101, 9, '将热油淋入葱姜碗中', NULL);
INSERT INTO `recipe_step` VALUES (500806, 300101, 10, '鸡腿蒸好后将其撕碎成鸡丝，不需要特别细，大概 1cm 粗就可以', NULL);
INSERT INTO `recipe_step` VALUES (500807, 300101, 11, '姜葱姜油淋在鸡丝上，搅拌均匀即可', NULL);
INSERT INTO `recipe_step` VALUES (500808, 300102, 1, '用盐揉搓鸡表皮，冷藏20 分钟；每500g 老母鸡，加入15g 盐，28g 调味料（鸡汤专用），50g 鸡油，2500g 水，烧开后炖制60 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500809, 300102, 2, '面碗中放入250g 老鸡汤、煮好的面条，再倒入菌菇包，并加入50g 老鸡块，出品撒葱花。', NULL);
INSERT INTO `recipe_step` VALUES (500810, 300103, 1, '首先将小米椒切碎，和孜然粒一起放入捣药罐捣碎成颗粒，这样更入味。如果时间紧张可跳过捣碎步骤', NULL);
INSERT INTO `recipe_step` VALUES (500811, 300103, 2, '青椒切头去籽（喜欢辣的可不去），切成丝。葱切段。', NULL);
INSERT INTO `recipe_step` VALUES (500812, 300103, 3, '牛肉提前解冻，过一边水洗干净，晾干或用厨用纸吸干，将牛肉顺着纹理切成片', NULL);
INSERT INTO `recipe_step` VALUES (500813, 300103, 4, '然后进行腌肉，加入生抽，淀粉，油，均匀搅拌，静止 30 分钟。腌肉方法也可参考学习腌', NULL);
INSERT INTO `recipe_step` VALUES (500814, 300103, 5, '热锅下油，放入葱，爆出香味后放入腌好的牛肉煸炒', NULL);
INSERT INTO `recipe_step` VALUES (500815, 300103, 6, '牛肉变色后均匀放入孜然辣椒颗粒并炒熟', NULL);
INSERT INTO `recipe_step` VALUES (500816, 300103, 7, '然后下入青椒丝，断生后放盐', NULL);
INSERT INTO `recipe_step` VALUES (500817, 300103, 8, '大🔥炒 1 分钟后关火再翻炒 30 秒保证受热均匀即可出锅', NULL);
INSERT INTO `recipe_step` VALUES (500818, 300104, 1, '准备两锅水： A 锅维持 100°C 沸水， B 锅维持 30°C 温水', NULL);
INSERT INTO `recipe_step` VALUES (500819, 300104, 2, '用漏勺将鸡蛋放入 A 锅，启动定时器', NULL);
INSERT INTO `recipe_step` VALUES (500820, 300104, 3, '精准每 2 分钟将鸡蛋转移至另一锅水', NULL);
INSERT INTO `recipe_step` VALUES (500821, 300104, 4, '重复转移操作共 16 次（总时长 32 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (500822, 300104, 5, '最后一次转移后，在 B 锅静置 30 秒', NULL);
INSERT INTO `recipe_step` VALUES (500823, 300104, 6, '立即放入冰水（ 0 摄氏度）终止加热（维持 30 秒）', NULL);
INSERT INTO `recipe_step` VALUES (500824, 300104, 7, '剥壳时从钝端气室处开始，沿纵轴剥离蛋膜', NULL);
INSERT INTO `recipe_step` VALUES (500825, 300105, 1, '【简易版本】手枪腿用剪刀去骨，鸡肉面用刀背拍打一遍，切条后切至 1.5cm 见方肉丁；泡于清水 10 分钟，捞出控干备用（若是鸡胸脯肉，则可以直接进行切丁以及之后的动作）', NULL);
INSERT INTO `recipe_step` VALUES (500826, 300105, 2, '【简易版本】取大葱葱绿与姜片 5g 于碗中，倒入 50g 开水备用；葱白切 1.5cm 圆粒备用；取花生放入微波炉高火 5 分钟焙干备用', NULL);
INSERT INTO `recipe_step` VALUES (500827, 300105, 3, '【简易版本】鸡丁中加入盐 2g，老抽酱油 5g，料酒 15g，淀粉 15g 搅拌均匀，至微微发干；缓慢加入部分葱姜水，搅拌鸡丁至粘手；保鲜膜密封，放入冰箱腌制 1 小时', NULL);
INSERT INTO `recipe_step` VALUES (500828, 300105, 4, '【简易版本】干辣椒切段；起锅，大火烧热转小火；放入干辣椒焙干至微微发糊，捞起备用；花椒焙干至有香味，捞起备用', NULL);
INSERT INTO `recipe_step` VALUES (500829, 300105, 5, '【简易版本】转大火，倒入 20g 植物油，7 成热（竹筷子起泡）下入鸡丁，煎至上面开始发白，用锅铲翻面，煎 30s 后翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (500830, 300105, 6, '【简易版本】下入葱粒翻炒，加入余下葱姜水不够 100g 再加一点清水（务必是热水）；盖上锅盖，转中小火焖 2 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500831, 300105, 7, '【简易版本】转大火，下入熟花生，干辣椒和花椒；加入鸡精 2g，香醋 5g，白糖 2g，翻炒均匀；', NULL);
INSERT INTO `recipe_step` VALUES (500832, 300105, 8, '【简易版本】淀粉 10g 加 50g 清水调成水淀粉，加入锅中，翻炒均匀，收汁到自己想要的浓度', NULL);
INSERT INTO `recipe_step` VALUES (500833, 300105, 9, '【简易版本】关火，淋入芝麻油 10g，即可出锅', NULL);
INSERT INTO `recipe_step` VALUES (500834, 300105, 10, '【稍加复杂但是更加令人垂涎欲滴的版本】莴笋去皮切至 1cm 见方的小块，备用；', NULL);
INSERT INTO `recipe_step` VALUES (500835, 300105, 11, '【稍加复杂但是更加令人垂涎欲滴的版本】二荆条切成 1cm 长段；', NULL);
INSERT INTO `recipe_step` VALUES (500836, 300105, 12, '【稍加复杂但是更加令人垂涎欲滴的版本】手枪腿用剪刀去骨，鸡肉面用刀背拍打一遍，切条后切至 1.5cm 见方肉丁；泡于清水 10 分钟，捞出控干备用（若是鸡胸脯肉，则可以直接进行切丁以及之后的动作）；', NULL);
INSERT INTO `recipe_step` VALUES (500837, 300105, 13, '【稍加复杂但是更加令人垂涎欲滴的版本】取大葱葱绿与姜片 5g 于碗中，倒入 50g 开水备用；葱白切 1.5cm 圆粒备用', NULL);
INSERT INTO `recipe_step` VALUES (500838, 300105, 14, '【稍加复杂但是更加令人垂涎欲滴的版本】鸡丁中加入盐 2g，老抽酱油 5g，料酒 15g，淀粉 15g 搅拌均匀，至微微发干；缓慢加入部分葱姜水，搅拌鸡丁至粘手；保鲜膜密封，放入冰箱腌制 1 小时', NULL);
INSERT INTO `recipe_step` VALUES (500839, 300105, 15, '【稍加复杂但是更加令人垂涎欲滴的版本】转中火，倒入 20g 植物油，放入生花生翻炒至其表面微微焦糊，捞起花生但是油留在锅内；', NULL);
INSERT INTO `recipe_step` VALUES (500840, 300105, 16, '【稍加复杂但是更加令人垂涎欲滴的版本】继续加热，7 成热（竹筷子起泡）下入鸡丁，放入豆瓣酱，翻炒大概 1 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500841, 300105, 17, '【稍加复杂但是更加令人垂涎欲滴的版本】加入备好的莴笋丁，继续翻炒 1 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500842, 300105, 18, '【稍加复杂但是更加令人垂涎欲滴的版本】下入葱粒翻炒，加入余下葱姜水不够 100g 再加一点清水（务必是热水）；加入二荆条段；盖上锅盖，转中小火焖 2 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500843, 300105, 19, '【稍加复杂但是更加令人垂涎欲滴的版本】转大火，下入先前捞起来备用的花生，花椒；加入鸡精 2g，香醋 5g，白糖 2g，翻炒均匀；', NULL);
INSERT INTO `recipe_step` VALUES (500844, 300105, 20, '【稍加复杂但是更加令人垂涎欲滴的版本】淀粉 10g 加 50g 清水调成水淀粉，加入锅中，翻炒均匀，收汁到自己想要的浓度', NULL);
INSERT INTO `recipe_step` VALUES (500845, 300105, 21, '【稍加复杂但是更加令人垂涎欲滴的版本】关火，淋入芝麻油 10g 与油泼辣子 5g 再翻炒 10s，即可出锅', NULL);
INSERT INTO `recipe_step` VALUES (500846, 300106, 1, '将 1800g 土豆片，在沸水中焯水至七分熟，捞出备用；', NULL);
INSERT INTO `recipe_step` VALUES (500847, 300106, 2, '下入 100g 大豆油、30g 蒜子、7g 干红椒、30g 泡小米辣，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (500848, 300106, 3, '下入焯水后的土豆片、炒菜基料 1 袋，大火爆炒 2 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (500849, 300106, 4, '下入葱段，翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (500850, 300107, 1, '锅中下入 180g 大豆油，将 60g 蒜子炒香；', NULL);
INSERT INTO `recipe_step` VALUES (500851, 300107, 2, '加入 500g 肉丝炒至变色；', NULL);
INSERT INTO `recipe_step` VALUES (500852, 300107, 3, '加入 300g 木耳丝、300g 胡萝卜丝、70g 调味料、10g 老抽、500g 芹菜段，翻炒至上色；', NULL);
INSERT INTO `recipe_step` VALUES (500853, 300107, 4, '加入 200g 油片丝，大火爆炒 20 秒出品。', NULL);
INSERT INTO `recipe_step` VALUES (500854, 300108, 1, '胡萝卜切片，尖椒切薄块，葱蒜碎切好', NULL);
INSERT INTO `recipe_step` VALUES (500855, 300108, 2, '把买好的日本豆腐打开袋子切好，切成大概 1 cm 厚的圆柱体', NULL);
INSERT INTO `recipe_step` VALUES (500856, 300108, 3, '生粉放到平盘中，准备给豆腐裹面', NULL);
INSERT INTO `recipe_step` VALUES (500857, 300108, 4, '轻轻把豆腐放到面粉上，上下两面和周边都裹上面粉，注意不要包裹的太厚', NULL);
INSERT INTO `recipe_step` VALUES (500858, 300108, 5, '在平底锅里放 150 ml 油，油能没过豆腐一大半即可，看边缘颜色变成金黄，翻面煎就可以了', NULL);
INSERT INTO `recipe_step` VALUES (500859, 300108, 6, '两边都煎好的时候捞出来放在干净的盘里备用', NULL);
INSERT INTO `recipe_step` VALUES (500860, 300108, 7, '在炒锅中倒入 10-15 ml 油，放入葱蒜，爆香后放入青椒、胡萝卜、火腿肠、黑木耳', NULL);
INSERT INTO `recipe_step` VALUES (500861, 300108, 8, '加入蚝油、生抽、盐、鸡精、白砂糖、番茄酱', NULL);
INSERT INTO `recipe_step` VALUES (500862, 300108, 9, '轻轻翻炒至颜色均匀', NULL);
INSERT INTO `recipe_step` VALUES (500863, 300109, 1, '锅中倒入120g 大豆油烧至160℃，将500g 蛋液炒制成鸡蛋丁状，盛出锅备用；', NULL);
INSERT INTO `recipe_step` VALUES (500864, 300109, 2, '再次倒入120g 大豆油，加入100g 蒜子、50g 鲜红小米辣；', NULL);
INSERT INTO `recipe_step` VALUES (500865, 300109, 3, '爆香后加入800g 青椒丁煸炒30 秒，撒入14g 盐翻炒；', NULL);
INSERT INTO `recipe_step` VALUES (500866, 300109, 4, '加入500g 河虾、70g 小炒河虾料、鸡蛋丁均匀翻炒1 分钟出品', NULL);
INSERT INTO `recipe_step` VALUES (500867, 300110, 1, '五花肉切片', NULL);
INSERT INTO `recipe_step` VALUES (500868, 300110, 2, '把肉放入器皿内，加入淀粉、老抽、盐搅拌腌制半小时', NULL);
INSERT INTO `recipe_step` VALUES (500869, 300110, 3, '葱切段', NULL);
INSERT INTO `recipe_step` VALUES (500870, 300110, 4, '小米椒、朝天椒斜刀切好', NULL);
INSERT INTO `recipe_step` VALUES (500871, 300110, 5, '热锅、倒油', NULL);
INSERT INTO `recipe_step` VALUES (500872, 300110, 6, '油热后加入五花肉煸炒。炒至变色后盛出来', NULL);
INSERT INTO `recipe_step` VALUES (500873, 300110, 7, '向锅中加蒜，煸出香味，加入豆豉，翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (500874, 300110, 8, '加入豆瓣酱翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (500875, 300110, 9, '加入炒好的五花肉继续的翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (500876, 300110, 10, '加入小米椒、朝天椒、葱段翻炒 40 秒', NULL);
INSERT INTO `recipe_step` VALUES (500877, 300110, 11, '出锅。', NULL);
INSERT INTO `recipe_step` VALUES (500878, 300111, 1, '锅中下入120g大豆油、500g五花肉肉片，煸炒至油色清亮，颜色发黄；', NULL);
INSERT INTO `recipe_step` VALUES (500879, 300111, 2, '下入50g鲜红小米辣、100g拍蒜、90g调味料，炒至上色；', NULL);
INSERT INTO `recipe_step` VALUES (500880, 300111, 3, '下入1200g笋片、100g青蒜段，翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (500881, 300112, 1, '取900g 花菜过油15 秒，捞出备用；', NULL);
INSERT INTO `recipe_step` VALUES (500882, 300112, 2, '下入60g 大豆油、200g 五花肉，炒至肉片颜色微微泛黄；', NULL);
INSERT INTO `recipe_step` VALUES (500883, 300112, 3, '下入50g 鲜红小米辣、100g 蒜子，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (500884, 300112, 4, '下入炒菜基料1 袋，炒至肉片完全上色；', NULL);
INSERT INTO `recipe_step` VALUES (500885, 300112, 5, '最后下入备好的花菜，大火翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (500886, 300113, 1, '大葱、小米辣切小段，备用', NULL);
INSERT INTO `recipe_step` VALUES (500887, 300113, 2, '莲藕去皮，切成不超过 3cm 的小块，放入水中备用（防止氧化发黑）', NULL);
INSERT INTO `recipe_step` VALUES (500888, 300113, 3, '取炒锅，锅内放入 500ml 凉水，煮沸', NULL);
INSERT INTO `recipe_step` VALUES (500889, 300113, 4, '将藕丁下入沸水中，焯水 2 分钟后，取出放入盘中备用', NULL);
INSERT INTO `recipe_step` VALUES (500890, 300113, 5, '将锅中水倒掉后，将锅加热干燥，加入 10-15 ml 食用油', NULL);
INSERT INTO `recipe_step` VALUES (500891, 300113, 6, '待油温升高后，下入葱花，小米辣爆香', NULL);
INSERT INTO `recipe_step` VALUES (500892, 300113, 7, '将处理好的藕丁下入锅中，大火翻炒', NULL);
INSERT INTO `recipe_step` VALUES (500893, 300113, 8, '加入生抽、老抽、耗油', NULL);
INSERT INTO `recipe_step` VALUES (500894, 300113, 9, '翻炒 2 分钟即可出锅', NULL);
INSERT INTO `recipe_step` VALUES (500895, 300114, 1, '下入 100g 大豆油、60g 熟猪油、60g 蒜子，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (500896, 300114, 2, '下入 1000g 面筋丝、炒菜基料 1 袋，大火爆炒 1 分 30 秒；', NULL);
INSERT INTO `recipe_step` VALUES (500897, 300114, 3, '最后下入 600g 青椒、100g 红椒，大火爆炒 1 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (500898, 300115, 1, '下入 100g 大豆油、100g 熟猪油、60g 拍蒜、10g 鲜红小米辣，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (500899, 300115, 2, '下入 1900g 香干、炒菜基料 1 袋、400g 青椒，大火爆炒出品。', NULL);
INSERT INTO `recipe_step` VALUES (500900, 300116, 1, '取 150g 大豆油烧热，加入 1400g 鸡丁煸炒至变色；', NULL);
INSERT INTO `recipe_step` VALUES (500901, 300116, 2, '下入 60g 蒜子炒香；', NULL);
INSERT INTO `recipe_step` VALUES (500902, 300116, 3, '下入 70g 调味料、15g 老抽翻炒上色；', NULL);
INSERT INTO `recipe_step` VALUES (500903, 300116, 4, '加入 270g 线椒、100g 小米辣、20g 藤椒油大火爆炒 1 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (500904, 300117, 1, '鸡肝清洗，备用', NULL);
INSERT INTO `recipe_step` VALUES (500905, 300117, 2, '蒜苗清洗，切段，备用', NULL);
INSERT INTO `recipe_step` VALUES (500906, 300117, 3, '大葱清洗，取 100g 切段，取 50g 切片，备用', NULL);
INSERT INTO `recipe_step` VALUES (500907, 300117, 4, '姜清晰，取 70g 切片， 取 50g 切丁，备用', NULL);
INSERT INTO `recipe_step` VALUES (500908, 300117, 5, '第一步：焯水 清洗后的鸡肝放入锅内，加入凉水淹没鸡肝，并放入 100g 切段的大葱、70g 切片的姜和 30ml 料酒 开大火，待水沸腾调至中火并撇去浮沫后等待5-10分钟 关火，捞出过凉水并清洗干净 清洗干净后切片，备用', NULL);
INSERT INTO `recipe_step` VALUES (500909, 300117, 6, '第二步：炒制 开中火。锅内加入 30ml 食用油，等待 10 秒使油升温 加入 50g 切片的大葱和 50g 切丁的姜，翻炒爆香 爆香后加入切片的鸡肝，翻炒至微微发黄 加入蒜苗，翻炒 30 秒，断生后调至为小火 加入调味料 食用盐 5g 鸡精（味精） 5g 五香粉（十三香） 5g 胡椒粉 5g 烧烤料或 10g （可选） 调至为大火，快速翻炒 30 秒防止糊锅，关火 盛出盘内，可以撒入 5g 芝麻作为装饰，如果不喜欢或者没有则可以不用添加。', NULL);
INSERT INTO `recipe_step` VALUES (500910, 300118, 1, '牛里脊切成不超过 3cm 宽，3mm 厚的薄片，倒入 6ml 酱油，用手抓匀备用', NULL);
INSERT INTO `recipe_step` VALUES (500911, 300118, 2, '芹菜切成不超过 5cm 的小段，备用', NULL);
INSERT INTO `recipe_step` VALUES (500912, 300118, 3, '小米椒切成丝状，备用', NULL);
INSERT INTO `recipe_step` VALUES (500913, 300118, 4, '野山椒切成颗粒，备用', NULL);
INSERT INTO `recipe_step` VALUES (500914, 300118, 5, '香菜切成成不超过 3cm 的小段，备用', NULL);
INSERT INTO `recipe_step` VALUES (500915, 300118, 6, '热锅，锅内放入 15ml 食用油，大火等待 30 秒让油温升高', NULL);
INSERT INTO `recipe_step` VALUES (500916, 300118, 7, '放入小米椒和野山椒爆香', NULL);
INSERT INTO `recipe_step` VALUES (500917, 300118, 8, '放入牛里脊和芹菜，然后大火翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500918, 300118, 9, '关火，撒上香菜，盛盘', NULL);
INSERT INTO `recipe_step` VALUES (500919, 300119, 1, '将300g 小黄米淘洗沥干；', NULL);
INSERT INTO `recipe_step` VALUES (500920, 300119, 2, '将400g 南瓜丁和4600g 水放入不锈钢桶内，大火烧开后，下入淘洗过的小黄米，搅拌均匀，熬制40 分钟即可出品。', NULL);
INSERT INTO `recipe_step` VALUES (500921, 300120, 1, '小米 100 克，放入碗中，用水轻淘一遍（用手搅拌一下，将水倒掉，只是去掉外面的浮灰，不可搓洗！！！）', NULL);
INSERT INTO `recipe_step` VALUES (500922, 300120, 2, '水烧开，务必烧开！！！', NULL);
INSERT INTO `recipe_step` VALUES (500923, 300120, 3, '水烧开沸腾时，将小米倒入锅内。（很容易被忽视的一个很重要的环节）', NULL);
INSERT INTO `recipe_step` VALUES (500924, 300120, 4, '搅拌使得小米不会粘连锅底，继续用大火熬 6-10 分钟，注意用中间穿插搅拌几次。', NULL);
INSERT INTO `recipe_step` VALUES (500925, 300120, 5, '改中火、文火熬 15-20 分钟，锅盖要错开一条缝，千万不能让小米油溜掉哟，中间继续搅拌几次，不要糊锅底', NULL);
INSERT INTO `recipe_step` VALUES (500926, 300121, 1, '将小米辣洗净，斜刀切大一点', NULL);
INSERT INTO `recipe_step` VALUES (500927, 300121, 2, '肉的话，想切丝切丝，想切片切片，倒入调料（生抽、蚝油、盐）腌制 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500928, 300121, 3, '热锅倒油，先把肉炒好盛起', NULL);
INSERT INTO `recipe_step` VALUES (500929, 300121, 4, '姜蒜爆香，倒入豆瓣酱翻炒，到入切好的小米辣，再倒入瘦肉，翻炒一下，放点生抽、鸡精、盐、糖翻炒', NULL);
INSERT INTO `recipe_step` VALUES (500930, 300122, 1, '【葱姜水制作】老姜切丝，小葱不用切。', NULL);
INSERT INTO `recipe_step` VALUES (500931, 300122, 2, '【葱姜水制作】根据计算公式倒入料酒、清水。', NULL);
INSERT INTO `recipe_step` VALUES (500932, 300122, 3, '【葱姜水制作】用手捏揉 5 分钟，使姜葱的味道充分溶解在水中。', NULL);
INSERT INTO `recipe_step` VALUES (500933, 300122, 4, '【猪肉处理】将猪肉去皮洗净', NULL);
INSERT INTO `recipe_step` VALUES (500934, 300122, 5, '【猪肉处理】切成长度 8~10 厘米，厚度 1.5 厘米的肉条。', NULL);
INSERT INTO `recipe_step` VALUES (500935, 300122, 6, '【猪肉处理】根据上面的计算公式加入盐，十三香、胡椒粉、味精、鸡精、花椒碎、花椒粒、生抽。', NULL);
INSERT INTO `recipe_step` VALUES (500936, 300122, 7, '【猪肉处理】倒入前面制作好的葱姜水', NULL);
INSERT INTO `recipe_step` VALUES (500937, 300122, 8, '【猪肉处理】抓匀并且充分揉制 10 分钟，直至肉吸收所有水分并且变得粘手。', NULL);
INSERT INTO `recipe_step` VALUES (500938, 300122, 9, '【猪肉处理】封上保鲜膜放冷藏室静置 30 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500939, 300122, 10, '【猪肉裹粉】将面粉、红薯粉倒入腌制好的肉中，加入鸡蛋清。', NULL);
INSERT INTO `recipe_step` VALUES (500940, 300122, 11, '【猪肉裹粉】充分揉制 15 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500941, 300122, 12, '【初炸定形状】锅中倒入植物油，根据锅大小控制油量，油面高度 3 厘米以上。', NULL);
INSERT INTO `recipe_step` VALUES (500942, 300122, 13, '【初炸定形状】大火将温加热至 150° 后，转小火保持温度。', NULL);
INSERT INTO `recipe_step` VALUES (500943, 300122, 14, '【初炸定形状】将裹好粉的肉条用筷子夹入油锅中，捋成自己喜欢的形状，炸 3~5 分钟定型。目测颜色微黄，用锅铲翻动感受倒略微有些硬了就可以。具体时间受肉块大小、油温、裹粉程度影响。', NULL);
INSERT INTO `recipe_step` VALUES (500944, 300122, 15, '【初炸定形状】捞出沥油。', NULL);
INSERT INTO `recipe_step` VALUES (500945, 300122, 16, '【复炸出成品】将油温升至 180° 放入初炸好的肉条，炸至金黄色即可捞出。', NULL);
INSERT INTO `recipe_step` VALUES (500946, 300123, 1, '锅中下入80g大豆油烧至180℃；', NULL);
INSERT INTO `recipe_step` VALUES (500947, 300123, 2, '加入1900g鸡块，煸炒至鸡块泛黄出油；', NULL);
INSERT INTO `recipe_step` VALUES (500948, 300123, 3, '加入300g小鸡炖蘑菇酱料，炒制1分钟使鸡块上色入味；', NULL);
INSERT INTO `recipe_step` VALUES (500949, 300123, 4, '加入1200g水烧开；', NULL);
INSERT INTO `recipe_step` VALUES (500950, 300123, 5, '加入500g滑子菇，继续烧5分钟至汤汁浓稠出品。', NULL);
INSERT INTO `recipe_step` VALUES (500951, 300124, 1, '小龙虾刷干净去虾线，葱切 2cm 葱段，姜蒜切末。', NULL);
INSERT INTO `recipe_step` VALUES (500952, 300124, 2, '烧油，油微热, 下香叶、八角、桂皮、青花椒、花椒、子弹头辣椒。', NULL);
INSERT INTO `recipe_step` VALUES (500953, 300124, 3, '香料出香气之后下锅葱姜蒜', NULL);
INSERT INTO `recipe_step` VALUES (500954, 300124, 4, '葱姜蒜爆香后，加入郫县豆瓣、黄豆酱，炒出红油。', NULL);
INSERT INTO `recipe_step` VALUES (500955, 300124, 5, '下小龙虾，翻炒至变色。', NULL);
INSERT INTO `recipe_step` VALUES (500956, 300124, 6, '加入啤酒，等啤酒烧开后加入生抽，盐。', NULL);
INSERT INTO `recipe_step` VALUES (500957, 300124, 7, '将小龙虾完全煮熟后出锅。', NULL);
INSERT INTO `recipe_step` VALUES (500958, 300125, 1, '牛蛙肉洗净后控干水分，加入 10 克以上的盐巴和 50ml 以上的啤酒，用手抓 5 分钟，去除牛蛙肉的腥味', NULL);
INSERT INTO `recipe_step` VALUES (500959, 300125, 2, '然后对着清水冲洗，直至不再流出血水和杂质，控干水分，放到合适的器皿中，准备腌制', NULL);
INSERT INTO `recipe_step` VALUES (500960, 300125, 3, '加入 5 克盐，30 克生粉，10ml 料酒，5 克胡椒粉，用手抓均匀，腌制 5-10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500961, 300125, 4, '将泡姜 泡椒 野山椒 切丝或者片（根据自己刀工选择），青红辣椒切成圈圈 大蒜拨开即可', NULL);
INSERT INTO `recipe_step` VALUES (500962, 300125, 5, '起锅烧热，加入 200ml 食用油（锅底比较平的可以再加 100ml）,烧至 6 成油温（有小气泡出现），将腌制好的牛蛙倒入，快速过油炸制，10 秒钟后捞出（不能超时太多，否则会导致蛙肉老柴）', NULL);
INSERT INTO `recipe_step` VALUES (500963, 300125, 6, '捞出蛙肉后，控油，并将锅中的热油倒出到碗中，保留 30ml,加入 20ml 猪油（如果没有，则在锅中保留总共 50ml 食用油）', NULL);
INSERT INTO `recipe_step` VALUES (500964, 300125, 7, '待油温 6 成热，加入泡姜、泡椒、野山椒、大蒜，超出香味，加入豆瓣酱 20 克，中火翻炒至出红油（时间控制在 30 秒），倒入 400ml 啤酒，', NULL);
INSERT INTO `recipe_step` VALUES (500965, 300125, 8, '然后倒入炸过的牛蛙肉，用勺子推着翻，不要用力搅拌，加入 5 克胡椒粉，加入 5ml 藤椒油，中火慢焖 3 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500966, 300125, 9, '加大火力，大火收汁半分钟，加入青红辣椒圈，再煮 10 秒准备起锅', NULL);
INSERT INTO `recipe_step` VALUES (500967, 300125, 10, '盛到盆里，撒上葱花，可以开动了！', NULL);
INSERT INTO `recipe_step` VALUES (500968, 300126, 1, '【配菜处理】蒜剁成蒜泥', NULL);
INSERT INTO `recipe_step` VALUES (500969, 300126, 2, '【配菜处理】葱切段', NULL);
INSERT INTO `recipe_step` VALUES (500970, 300126, 3, '【配菜处理】姜切成姜片', NULL);
INSERT INTO `recipe_step` VALUES (500971, 300126, 4, '【配菜处理】尖椒切成段', NULL);
INSERT INTO `recipe_step` VALUES (500972, 300126, 5, '【牛肉的预处理】牛肉放入碗中', NULL);
INSERT INTO `recipe_step` VALUES (500973, 300126, 6, '【牛肉的预处理】加姜、盐、酱油、糖进行腌制 30-40 分钟', NULL);
INSERT INTO `recipe_step` VALUES (500974, 300126, 7, '【牛肉的预处理】腌制完姜可以去掉', NULL);
INSERT INTO `recipe_step` VALUES (500975, 300126, 8, '【炒熟】冷油下锅，待油变热至偶有气泡', NULL);
INSERT INTO `recipe_step` VALUES (500976, 300126, 9, '【炒熟】加入蒜泥', NULL);
INSERT INTO `recipe_step` VALUES (500977, 300126, 10, '【炒熟】蒜泥变金黄后加入尖椒', NULL);
INSERT INTO `recipe_step` VALUES (500978, 300126, 11, '【炒熟】待尖椒表皮微皱，加入腌制好的牛肉翻炒', NULL);
INSERT INTO `recipe_step` VALUES (500979, 300126, 12, '【炒熟】翻炒变熟之前加入葱，继续翻炒', NULL);
INSERT INTO `recipe_step` VALUES (500980, 300126, 13, '【炒熟】翻炒至牛肉变熟，关火出锅', NULL);
INSERT INTO `recipe_step` VALUES (500981, 300127, 1, '木耳提前泡发好，如果着急可以用热水泡发。', NULL);
INSERT INTO `recipe_step` VALUES (500982, 300127, 2, '猪里脊切片放入碗中，加 20ml 生抽、料酒、花椒粉，打入一个鸡蛋，拿自己的小手搅拌均匀，加入淀粉（建议红薯淀粉）拌匀，倒入 300ml 食用油封浆，腌制 15 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (500983, 300127, 3, '蒜苔切段大约 3cm，葱头切菱形块备用。', NULL);
INSERT INTO `recipe_step` VALUES (500984, 300127, 4, '起锅烧油油要多一点，油温五成热，下入腌制好的肉片，将肉片打散，捞出控油备用。', NULL);
INSERT INTO `recipe_step` VALUES (500985, 300127, 5, '将锅中多余油倒出，留 10ml 油炒菜，油温七成热', NULL);
INSERT INTO `recipe_step` VALUES (500986, 300127, 6, '下入葱姜蒜爆香，先下蒜苔炒至断生，再下入木耳葱头，加入生抽，花椒粉，翻炒几下将之前炸好的肉片下入翻炒', NULL);
INSERT INTO `recipe_step` VALUES (500987, 300127, 7, '加 10g 的盐，起锅前加 10ml 的醋和鸡精，起锅装盘。', NULL);
INSERT INTO `recipe_step` VALUES (500988, 300128, 1, '全部螺丝椒切成段状，备用', NULL);
INSERT INTO `recipe_step` VALUES (500989, 300128, 2, '全部番茄打成番茄蓉，备用', NULL);
INSERT INTO `recipe_step` VALUES (500990, 300128, 3, '牛肉切成 2cm 的小块，洗净备用', NULL);
INSERT INTO `recipe_step` VALUES (500991, 300128, 4, '炒锅中倒入一层油（用来防止番茄蓉沸腾蒸发）', NULL);
INSERT INTO `recipe_step` VALUES (500992, 300128, 5, '倒入番茄蓉，持续搅拌 2-3 分钟，等待它越变越红', NULL);
INSERT INTO `recipe_step` VALUES (500993, 300128, 6, '加入 5g 蒜粉，5g 姜粉和 1 包 50g 的 Masala 粉，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (500994, 300128, 7, '加入牛肉和螺丝椒段，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (500995, 300128, 8, '加入 1 盒酸奶（为了让整个酱汁变得粘稠），搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (500996, 300128, 9, '将整锅材料转移到电饭煲/电炖锅，并加入 250 ml 的水，开启炖肉/慢炖档，设定时间 2-3 个小时', NULL);
INSERT INTO `recipe_step` VALUES (500997, 300128, 10, '等待完成，开锅检查牛肉软糯，就可以吃了', NULL);
INSERT INTO `recipe_step` VALUES (500998, 300129, 1, '将肘子刮洗干净，肘头朝外、肘把（脚爪）朝里、肘皮朝下放在案板上。', NULL);
INSERT INTO `recipe_step` VALUES (500999, 300129, 2, '用刀在正中由肘头向肘把沿着腿骨将皮剖开，剔去腿骨两边的肉（三面离肉），底部骨与肉相连，使骨头露出，然后将两节腿骨由中间用刀背（还是用斧头吧）砸断。', NULL);
INSERT INTO `recipe_step` VALUES (501000, 300129, 3, '肘子放入煮锅煮至七成熟捞出（外观正常，内部淡红色），用干净抹布擦干水，趁热用红酱油涂抹肉皮。', NULL);
INSERT INTO `recipe_step` VALUES (501001, 300129, 4, '取蒸锅一个，锅底放入八角、桂皮，先将肘把的关节处用手掰断，不伤外皮，再将肘皮朝下装进蒸锅内，装锅时根据肘子体型，将肘把贴住锅边窝着装进锅内，成为圆形。', NULL);
INSERT INTO `recipe_step` VALUES (501002, 300129, 5, '撒入精盐，用消过毒的干净纱布盖在肉上，再将甜面酱（50 克）、葱（75 克）、红豆腐乳、红酱油、白酱油、姜、蒜等在纱布上抹开，用旺火蒸大约三小时（以蒸烂为准）。', NULL);
INSERT INTO `recipe_step` VALUES (501003, 300129, 6, '蒸完取出，揭去纱布，扣入盘中，拣去八角，上桌时另带葱段和甜面酱小碟（或将甜面酱抹到肘面上，另带葱段小碟亦可）。', NULL);
INSERT INTO `recipe_step` VALUES (501004, 300130, 1, '阿根廷红虾解冻，最好是提前 1 天从速冻取出放到冷藏里自然解冻，能更好保持风味和口感。可买已经开背去虾线的，节省了不少时间', NULL);
INSERT INTO `recipe_step` VALUES (501005, 300130, 2, '解冻好的红虾洗净擦干备用，注意这里一定要沥干水分，赶时间可以用厨房用纸吸干水分', NULL);
INSERT INTO `recipe_step` VALUES (501006, 300130, 3, '生姜切片，洋葱切小方块，香菜洗干净后，叶茎分离，把香菜叶切碎，大蒜压碎切成小块碎末', NULL);
INSERT INTO `recipe_step` VALUES (501007, 300130, 4, '大火热锅，热锅后倒入两调羹橄榄油，等油温升高后，放入生姜片，洋葱块和香菜茎煸炒', NULL);
INSERT INTO `recipe_step` VALUES (501008, 300130, 5, '约 1 分钟后取出生姜，洋葱和香菜茎，弃用', NULL);
INSERT INTO `recipe_step` VALUES (501009, 300130, 6, '调中大火，放入红虾开始煎，注意所有虾需要单面都完整接触平底锅，煎约 2 分钟，同时给每只虾刷上一层油', NULL);
INSERT INTO `recipe_step` VALUES (501010, 300130, 7, '待底面虾壳有微微焦黄时翻面，并撒入大蒜碎末，轻微晃动平底锅使得受热均匀', NULL);
INSERT INTO `recipe_step` VALUES (501011, 300130, 8, '约 1 分钟后添加 20ml 白葡萄酒', NULL);
INSERT INTO `recipe_step` VALUES (501012, 300130, 9, '再煎 1 分钟后调中小火，均匀撒上一层盐和黑胡椒', NULL);
INSERT INTO `recipe_step` VALUES (501013, 300130, 10, '给每只虾滴上一滴生抽', NULL);
INSERT INTO `recipe_step` VALUES (501014, 300130, 11, '撒上香菜叶，装盘', NULL);
INSERT INTO `recipe_step` VALUES (501015, 300130, 12, '切好柠檬片，摆放到盘边即可', NULL);
INSERT INTO `recipe_step` VALUES (501016, 300131, 1, '鸡腿去骨（如使用鸡腿排可忽略此步骤），鸡腿肉用刀背砸一砸，切成 2cm 的块。', NULL);
INSERT INTO `recipe_step` VALUES (501017, 300131, 2, '鸡腿肉中加入盐、鸡精（可选）、胡椒粉、生抽、老抽、料酒，抓拌至粘手时加入淀粉拌匀，加入食用油防止粘连，腌制 30 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501018, 300131, 3, '土豆去皮，切成 2cm 的块，沸水煮 5 分钟后捞出，控干水分，防止油炸时爆锅。', NULL);
INSERT INTO `recipe_step` VALUES (501019, 300131, 4, '青椒去籽，切成 2cm 小片，放在笊篱中备用。', NULL);
INSERT INTO `recipe_step` VALUES (501020, 300131, 5, '锅中加入宽油（根据锅的形状，能没过食材即可），油温烧至 180℃ 时，下入土豆块炸 3 分钟后捞出。', NULL);
INSERT INTO `recipe_step` VALUES (501021, 300131, 6, '待油温再次升高到 180℃时，下入鸡块炸 2 分钟后捞出。', NULL);
INSERT INTO `recipe_step` VALUES (501022, 300131, 7, '待油温再次升高到 180℃时，下入鸡块复炸 1 分钟后捞出。', NULL);
INSERT INTO `recipe_step` VALUES (501023, 300131, 8, '待油温再次升高到 180℃时，下入土豆块复炸 1 分钟后，将锅中的油和土豆块经过笊篱过滤倒出，让笊篱上的青椒片断生。', NULL);
INSERT INTO `recipe_step` VALUES (501024, 300131, 9, '锅中加入 5ml 食用油，小火煸炒蒜瓣至发黄，下入红油豆瓣酱煸炒出香，下入白糖炒融化，下入花椒碎，加 40ml 清水，不停搅拌至酱汁粘稠。', NULL);
INSERT INTO `recipe_step` VALUES (501025, 300131, 10, '下入炸好的鸡块、土豆块、青椒片，搅拌均匀后出锅。', NULL);
INSERT INTO `recipe_step` VALUES (501026, 300132, 1, '花菜朵朝下，没入淡盐水中浸泡 20 分钟。然后洗净用小刀拆成小朵', NULL);
INSERT INTO `recipe_step` VALUES (501027, 300132, 2, '入开水锅中焯水 1 分钟，捞出立即用冷水冲淋至完全凉透，沥水备用', NULL);
INSERT INTO `recipe_step` VALUES (501028, 300132, 3, '五花肉切成薄片，大蒜白色切下用刀背拍扁，小红辣椒切成段', NULL);
INSERT INTO `recipe_step` VALUES (501029, 300132, 4, '锅烧热放油，油热下大葱白爆香', NULL);
INSERT INTO `recipe_step` VALUES (501030, 300132, 5, '下五花肉片入锅，用中火煸炒至表面全部变色，继续煸炒一会儿，把肥肉部分的油份逼出一部分', NULL);
INSERT INTO `recipe_step` VALUES (501031, 300132, 6, '倒入红辣椒段和花菜，翻炒几下', NULL);
INSERT INTO `recipe_step` VALUES (501032, 300132, 7, '加入 10 ml 生抽', NULL);
INSERT INTO `recipe_step` VALUES (501033, 300132, 8, '再加入 5 g 白糖，转大火不断翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501034, 300132, 9, '把大蒜叶部分切成段，放入锅中，翻炒几下后，关火盖上盖子焖 1 分钟即可', NULL);
INSERT INTO `recipe_step` VALUES (501035, 300133, 1, '【开始制作】萝卜滚到切块备用', NULL);
INSERT INTO `recipe_step` VALUES (501036, 300133, 2, '【开始制作】牛腩整块焯水，加入 2 片姜和一把葱结，等水开之后煮 5-10 分钟，然后捞出切件', NULL);
INSERT INTO `recipe_step` VALUES (501037, 300133, 3, '【开始制作】将牛腩切块，切成自己喜欢的大小（牛腩焯过水，待会儿焖的时候基本不会缩水了，大块的会焖相对就一点的时间）', NULL);
INSERT INTO `recipe_step` VALUES (501038, 300133, 4, '【开始制作】准备焖牛腩的酱料，将南乳、柱侯酱、酱油、蚝油、糖、盐按上面的量调和（冰糖刚刚没了换成了白糖）', NULL);
INSERT INTO `recipe_step` VALUES (501039, 300133, 5, '【开始制作】热锅下油，将姜蒜爆香，放入牛腩，炒至干身，加入调好的酱料，炒香，如果喜欢色泽浓一点的可以加一点老抽润色一下', NULL);
INSERT INTO `recipe_step` VALUES (501040, 300133, 6, '【开始制作】调料充分混合之后倒入热水', NULL);
INSERT INTO `recipe_step` VALUES (501041, 300133, 7, '【开始制作】将牛腩换到汤锅中，放入桂皮、八角、香叶和干辣椒，焖大概 2 个小时', NULL);
INSERT INTO `recipe_step` VALUES (501042, 300133, 8, '【开始制作】牛腩焖到半软之后加入白萝卜继续焖 30 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501043, 300133, 9, '【开始制作】等到萝卜焖软之后就完成，一锅浓香的萝卜牛腩就完成了', NULL);
INSERT INTO `recipe_step` VALUES (501044, 300134, 1, '将米淘洗干净后倒入 饭碗 内，加入 400ml 的水，盖上盖', NULL);
INSERT INTO `recipe_step` VALUES (501045, 300134, 2, '放入微波炉，高火，6 分钟，煮饭途中准备原料 切好腊肠 洗好青菜 切好红萝卜片 切好葱花 青菜碗 中放入青菜、红萝卜片，倒入 10 ml 油，放入 5 g 盐 小碗 中倒入 10 ml 生抽、5 ml 油', NULL);
INSERT INTO `recipe_step` VALUES (501046, 300134, 3, '6 分钟后，用毛巾或隔热手套取出碗，可以看见米饭已经八分熟', NULL);
INSERT INTO `recipe_step` VALUES (501047, 300134, 4, '在米饭上摆入切片的腊肠，继续高火 2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501048, 300134, 5, '取出腊肠饭，放入 青菜碗，高火 4-5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501049, 300134, 6, '在腊肠饭上摆好青菜，磕入鸡蛋，看个人喜好继续高火 40-60 秒', NULL);
INSERT INTO `recipe_step` VALUES (501050, 300134, 7, '取出腊肠饭，此时已经基本完成。', NULL);
INSERT INTO `recipe_step` VALUES (501051, 300134, 8, '将 小碗 放入，继续高火 30 秒', NULL);
INSERT INTO `recipe_step` VALUES (501052, 300134, 9, '在腊肠饭上淋上叮热的生抽，撒上葱花即可', NULL);
INSERT INTO `recipe_step` VALUES (501053, 300134, 10, '多余的青菜可以沾着酱油吃', NULL);
INSERT INTO `recipe_step` VALUES (501054, 300135, 1, '将鸡蛋打入小碗中，用筷子在所有鸡蛋黄上扎 2 个洞，避免加热弄脏微波炉', NULL);
INSERT INTO `recipe_step` VALUES (501055, 300135, 2, '然后向碗内倒入常温饮用水', NULL);
INSERT INTO `recipe_step` VALUES (501056, 300135, 3, '再向碗内倒入食用盐', NULL);
INSERT INTO `recipe_step` VALUES (501057, 300135, 4, '最后加入芝麻油', NULL);
INSERT INTO `recipe_step` VALUES (501058, 300135, 5, '将放好材料的碗放入微波炉中，高火加热 80 秒', NULL);
INSERT INTO `recipe_step` VALUES (501059, 300135, 6, '到达设定时间后，使用抹布垫着手取出成品', NULL);
INSERT INTO `recipe_step` VALUES (501060, 300136, 1, '将鸡蛋打散，加入温水/高汤、盐、生抽，轻轻搅匀，尽量不要起泡。', NULL);
INSERT INTO `recipe_step` VALUES (501061, 300136, 2, '将蛋液过筛倒入耐热碗中，表面若有气泡可用牙签轻戳。', NULL);
INSERT INTO `recipe_step` VALUES (501062, 300136, 3, '覆盖保鲜膜并扎 8-10 个小孔，或使用微波炉专用盖（留缝隙）。', NULL);
INSERT INTO `recipe_step` VALUES (501063, 300136, 4, '放入微波炉中加热： 700W：1 分 30 秒 → 视情况再加热 20-30 秒至表面刚凝。 600W：约 1 分 40 秒–2 分 10 秒。 800W：约 1 分 10 秒–1 分 40 秒。', NULL);
INSERT INTO `recipe_step` VALUES (501064, 300136, 5, '加热完成后取出静置 1 分钟，让余温使中心完全熟化。', NULL);
INSERT INTO `recipe_step` VALUES (501065, 300136, 6, '淋上香油，撒葱花即可食用。', NULL);
INSERT INTO `recipe_step` VALUES (501066, 300137, 1, '加入以下食材，注意不要超过容器的 3/4 挖半个鸡蛋大的黄油放进容器, 在微波炉加热 15 秒至融化 将巧克力/香蕉 融化/搅碎成 颗粒/糊状 打入一个鸡蛋并打散搅和 15g 白（红）糖（甜党可以多加些） （见附 4） 加入 1g 盐 (如果后续的口味食材含盐需自己斟酌) 加入 2.5g 泡打粉 加入 15g 面粉（筋度没太大影响） 加入任何喜欢的口味食材!（坚果与饼干等干食材不是现在放） 搅和至看不见干粉的稠酸奶状 加入可选的干燥食材（不包括冲泡粉）在顶端', NULL);
INSERT INTO `recipe_step` VALUES (501067, 300137, 2, '夸赞一下自己🥰', NULL);
INSERT INTO `recipe_step` VALUES (501068, 300137, 3, '微波炉（高火）加热 1分钟 （至蓬松蛋糕形态）', NULL);
INSERT INTO `recipe_step` VALUES (501069, 300137, 4, '取出杯子（烫手啊啊啊啊↑）并拍朋友圈就可以吃了', NULL);
INSERT INTO `recipe_step` VALUES (501070, 300138, 1, '将鸡蛋打入可使用微波炉加热的陶瓷碗中，使用筷子将其打散。', NULL);
INSERT INTO `recipe_step` VALUES (501071, 300138, 2, '加入水和盐，搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501072, 300138, 3, '将虾皮放入碗中，搅拌均匀，保证所有虾皮不会堆积在一起。', NULL);
INSERT INTO `recipe_step` VALUES (501073, 300138, 4, '葱切碎至边长 0.6±3mm 状，放入碗中搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501074, 300138, 5, '将此碗及内容物放入微波炉中，容器表面覆盖保鲜膜或以可微波瓷盘加盖（注意：不得密封，必须留有涨缩量）加热 2 分钟(500W)。', NULL);
INSERT INTO `recipe_step` VALUES (501075, 300138, 6, '小心地取下保鲜膜或其他覆盖物，然后继续加热 2 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501076, 300138, 7, '若微波炉不带旋转式加热盘，将碗缓慢的水平旋转 180 度，以确保内容物加热均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501077, 300138, 8, '放入芝麻油。', NULL);
INSERT INTO `recipe_step` VALUES (501078, 300138, 9, '小心地从微波炉中拿出碗（真的很烫）。', NULL);
INSERT INTO `recipe_step` VALUES (501079, 300138, 10, '如果选择放入酱油，则确保酱油在鸡蛋羹表面流动后能以最薄的形式沾满鸡蛋羹表面即可。', NULL);
INSERT INTO `recipe_step` VALUES (501080, 300138, 11, '开心的享受鸡蛋羹', NULL);
INSERT INTO `recipe_step` VALUES (501081, 300139, 1, '鱼片分别放入密封袋，鱼皮向下放在盘子中。', NULL);
INSERT INTO `recipe_step` VALUES (501082, 300139, 2, '取葱白切丝 25g，姜去皮后切丝，10g，混合在一起后分成两半，分别放在袋内鱼片上。', NULL);
INSERT INTO `recipe_step` VALUES (501083, 300139, 3, '每个袋子倒入 2.5mL 料酒。', NULL);
INSERT INTO `recipe_step` VALUES (501084, 300139, 4, '封好密封袋，放入微波炉中，中火（800 瓦）微波至不透明且容易散开时（约 3.5-5 分钟），从袋中取出鱼片。', NULL);
INSERT INTO `recipe_step` VALUES (501085, 300139, 5, '去除青葱和姜。', NULL);
INSERT INTO `recipe_step` VALUES (501086, 300139, 6, '取酱油 25mL，芝麻油 2mL，混合均匀后平均淋在两片鱼片上。', NULL);
INSERT INTO `recipe_step` VALUES (501087, 300139, 7, '取葱绿切细丝 10g，姜去皮后切丝 3g，混合后分成两份撒在鱼片上。', NULL);
INSERT INTO `recipe_step` VALUES (501088, 300139, 8, '取花生油 50mL，在小锅中加热至 190℃。', NULL);
INSERT INTO `recipe_step` VALUES (501089, 300139, 9, '将热油淋到放油葱绿的鱼片上，立刻上桌。', NULL);
INSERT INTO `recipe_step` VALUES (501090, 300140, 1, '五花肉切块，每块 2-3 cm 大小', NULL);
INSERT INTO `recipe_step` VALUES (501091, 300140, 2, '锅中加入 150 ml 食用油，倒入五花肉，煎炸 2 分钟 后，加入盐，翻炒五花肉，2 分钟 后出锅', NULL);
INSERT INTO `recipe_step` VALUES (501092, 300140, 3, '锅中加入 50 ml 食用油，倒入白砂糖，翻炒到咖啡色', NULL);
INSERT INTO `recipe_step` VALUES (501093, 300140, 4, '倒入五花肉，翻炒 30 S ，加入姜片、蒜头后翻炒 30 S', NULL);
INSERT INTO `recipe_step` VALUES (501094, 300140, 5, '加入料酒，五香粉、葱，加入水没过五花肉，盖上锅盖煮 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501095, 300140, 6, '加入生抽、老抽、蚝油，中火煮 20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501096, 300140, 7, '开锅，大火烧汁，端盘', NULL);
INSERT INTO `recipe_step` VALUES (501097, 300141, 1, '鸡排无需解冻直接放入170℃的油锅中炸制8 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501098, 300142, 1, '【鸡肉的预处理】鸡腿肉涂上盐、黑胡椒、橄榄油和蒜末', NULL);
INSERT INTO `recipe_step` VALUES (501099, 300142, 2, '【鸡肉的预处理】放入预热至 180 度的烤箱中，烤 30-40 分钟或至熟', NULL);
INSERT INTO `recipe_step` VALUES (501100, 300142, 3, '【佐料的准备】欧芹切成碎末备用', NULL);
INSERT INTO `recipe_step` VALUES (501101, 300142, 4, '【佐料的准备】柠檬挤出汁备用', NULL);
INSERT INTO `recipe_step` VALUES (501102, 300142, 5, '【烤制】烤好的鸡肉取出，淋上柠檬汁', NULL);
INSERT INTO `recipe_step` VALUES (501103, 300142, 6, '【烤制】撒上欧芹碎即可', NULL);
INSERT INTO `recipe_step` VALUES (501104, 300143, 1, '锅中加水，烧开后放入意面（等待 6 - 12 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (501105, 300143, 2, '在烧水的时候可以进行下面这些步骤，但请注意煮面的时间', NULL);
INSERT INTO `recipe_step` VALUES (501106, 300143, 3, '洋葱切成小丁', NULL);
INSERT INTO `recipe_step` VALUES (501107, 300143, 4, '空锅中倒油，中火下入洋葱碎', NULL);
INSERT INTO `recipe_step` VALUES (501108, 300143, 5, '时刻搅拌，注意不要让洋葱烧糊，直到洋葱变成半透明状', NULL);
INSERT INTO `recipe_step` VALUES (501109, 300143, 6, '下入肉沫，继续搅拌（搅散），直到肉末变成棕色', NULL);
INSERT INTO `recipe_step` VALUES (501110, 300143, 7, '加入意大利面酱，稍微搅拌一下即可', NULL);
INSERT INTO `recipe_step` VALUES (501111, 300143, 8, '把煮好的意大利面沥干水分并倒入肉酱中搅拌均匀即可（或者直接把做好的肉酱倒在意面上也行）', NULL);
INSERT INTO `recipe_step` VALUES (501112, 300144, 1, '将意式猪肉香肠去肠衣备用；洋葱切小丁；甜椒切细丝。', NULL);
INSERT INTO `recipe_step` VALUES (501113, 300144, 2, '在宽口平底锅中倒入 10ml - 15ml 橄榄油，中火加热。', NULL);
INSERT INTO `recipe_step` VALUES (501114, 300144, 3, '放入处理好的香肠或午餐肉，翻炒至边缘金黄酥脆（如果使用生香肠，翻炒时用勺子将其捣碎变色）。', NULL);
INSERT INTO `recipe_step` VALUES (501115, 300144, 4, '将洋葱丁和甜椒丝加入锅中与肉一起翻炒，持续翻炒 4 - 5 分钟，直到蔬菜变软，洋葱呈半透明状。', NULL);
INSERT INTO `recipe_step` VALUES (501116, 300144, 5, '倒入百味来拿坡里意面酱，搅拌均匀。将火调至中低火，保持微沸炖煮 2 - 3 分钟。（如果酱汁看起来太稠，可以加入 15ml 水）。', NULL);
INSERT INTO `recipe_step` VALUES (501117, 300144, 6, '用勺子的背面在锅内的酱汁中挖出 3 - 4 个小“坑”。', NULL);
INSERT INTO `recipe_step` VALUES (501118, 300144, 7, '依次小心地将鸡蛋打入每个坑中。', NULL);
INSERT INTO `recipe_step` VALUES (501119, 300144, 8, '盖上平底锅的盖子，利用蒸汽焖熟蛋白。等待 3 - 5 分钟。注意：请频繁检查状态。当蛋白变得不透明且凝固，但轻轻摇晃平底锅时蛋黄仍能晃动（溏心状态）时即可结束这一步。', NULL);
INSERT INTO `recipe_step` VALUES (501120, 300144, 9, '关火。根据个人喜好撒上磨碎的帕马森干酪、新鲜欧芹或干辣椒碎。', NULL);
INSERT INTO `recipe_step` VALUES (501121, 300144, 10, '将平底锅直接端上桌，配以硬壳面包蘸取蛋黄与酱汁食用。', NULL);
INSERT INTO `recipe_step` VALUES (501122, 300145, 1, '烤箱 200 度，预热 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501123, 300145, 2, '在烤盘上放上蛋挞皮，蛋挞皮中倒入蛋挞液约 10ml，具体分量需要看蛋挞皮大小，通常倒入 4/5 即可', NULL);
INSERT INTO `recipe_step` VALUES (501124, 300145, 3, '将烤盘放入烤箱内，上下火 190 度，烤 10 - 20 分。如果想快速烤出蛋挞液上的焦褐斑点，需要上火更高一些，通常是 200 - 210 度', NULL);
INSERT INTO `recipe_step` VALUES (501125, 300145, 4, '蛋挞液烤出焦褐斑点，蛋挞皮完全蓬松冒油即可', NULL);
INSERT INTO `recipe_step` VALUES (501126, 300146, 1, '【前期分离操作】从冰箱中取出新鲜的鸡蛋', NULL);
INSERT INTO `recipe_step` VALUES (501127, 300146, 2, '【前期分离操作】准备两个容器并擦干，分别盛放蛋清与蛋黄', NULL);
INSERT INTO `recipe_step` VALUES (501128, 300146, 3, '【前期分离操作】对盛放蛋清的容器，可稍有水珠，但不能有任何油；盛放蛋黄的容器不能有水珠', NULL);
INSERT INTO `recipe_step` VALUES (501129, 300146, 4, '【前期分离操作】打蛋，手工或利用分蛋器，将蛋清与蛋黄分离到两个容器中。', NULL);
INSERT INTO `recipe_step` VALUES (501130, 300146, 5, '【前期分离操作】分离过程中蛋黄不能破碎，蛋清中不能混有任何蛋黄，否则会严重影响打发。（白色系带可进入蛋清，不影响）', NULL);
INSERT INTO `recipe_step` VALUES (501131, 300146, 6, '【前期分离操作】（注意，不使用厨房机的情况下，盛放蛋清的容器也是打蛋的容器，为避免溢出，加入全部蛋清后不要超过容器的 1/8）', NULL);
INSERT INTO `recipe_step` VALUES (501132, 300146, 7, '【搅拌蛋黄液（后蛋法）】准备一个新的空碗，加入配方中全部的食用油和全部的牛奶', NULL);
INSERT INTO `recipe_step` VALUES (501133, 300146, 8, '【搅拌蛋黄液（后蛋法）】用打蛋器手动快速搅拌，直到油水完全融合，呈现乳白色悬浊液状态（完成乳化）', NULL);
INSERT INTO `recipe_step` VALUES (501134, 300146, 9, '【搅拌蛋黄液（后蛋法）】将配方中全部的低筋面粉过筛，加入上述乳化液中。用刮刀以”Z 字形”划拌至没有明显干粉即可（此时面糊可能会有些粗糙，属于正常现象）', NULL);
INSERT INTO `recipe_step` VALUES (501135, 300146, 10, '【搅拌蛋黄液（后蛋法）】将分离好的全部蛋黄加入碗中，继续用刮刀”Z 字形”划拌', NULL);
INSERT INTO `recipe_step` VALUES (501136, 300146, 11, '【搅拌蛋黄液（后蛋法）】此时面糊会变得非常细腻顺滑，且不易产生面筋。将其静置备用', NULL);
INSERT INTO `recipe_step` VALUES (501137, 300146, 12, '【打发蛋白】准备好剩余 3/4 的白糖。分为三份，每份为总量的 1/4', NULL);
INSERT INTO `recipe_step` VALUES (501138, 300146, 13, '【打发蛋白】蛋清中加入柠檬汁或白醋（可选）', NULL);
INSERT INTO `recipe_step` VALUES (501139, 300146, 14, '【打发蛋白】打蛋器中速，打发蛋白至有粗大气泡的状态，加入第一份白糖', NULL);
INSERT INTO `recipe_step` VALUES (501140, 300146, 15, '【打发蛋白】打蛋器高速，打发蛋白至气泡较细腻的状态，加入第二份白糖', NULL);
INSERT INTO `recipe_step` VALUES (501141, 300146, 16, '【打发蛋白】打蛋器高速，打发蛋白至”湿性发泡”的状态，加入第三份白糖', NULL);
INSERT INTO `recipe_step` VALUES (501142, 300146, 17, '【打发蛋白】打蛋器中低速，打发蛋白至”干性发泡”的状态', NULL);
INSERT INTO `recipe_step` VALUES (501143, 300146, 18, '【打发蛋白】此时蛋白打发程度已符合要求 关于蛋白状态的判断可参考附件链接中的图片。） 打蛋器应尽量贴近容器底部，防止出现上面浮着的表层打发，底部仍然是液体的情况）', NULL);
INSERT INTO `recipe_step` VALUES (501144, 300146, 19, '【混合搅拌】简单搅拌几下蛋黄液', NULL);
INSERT INTO `recipe_step` VALUES (501145, 300146, 20, '【混合搅拌】用刮刀取 1/3 的蛋白霜，加入到蛋黄糊中', NULL);
INSERT INTO `recipe_step` VALUES (501146, 300146, 21, '【混合搅拌】采用“翻拌”的手法，此手法是为了避免消泡 翻拌手法是 先用右手拿刮刀从搅拌盆中心插入面糊底部 向 8 点钟方向刮去直到碰到盆壁，顺势舀起面糊提到空中，然后再移回盆中心将面糊放入盆内 左手握住搅拌盆从 9 点钟方向转到 7 点钟方向，刚好旋转了 60 度，就完成了一次循环 速度大约是 1 秒钟两下 此方法出自《小岛老师的蛋糕教室》。用接地气的话说就是，像炒菜一样翻炒。', NULL);
INSERT INTO `recipe_step` VALUES (501147, 300146, 22, '【混合搅拌】将 1/3 的蛋白霜与蛋黄液的混合液倒入剩余 2/3 的蛋白霜中，继续翻拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (501148, 300146, 23, '【混合搅拌】将蛋糕糊倒入模具，震荡几下避免大气泡', NULL);
INSERT INTO `recipe_step` VALUES (501149, 300146, 24, '【烘烤】烘烤总时间：6 寸蛋糕 30-35 分钟，8 寸蛋糕 50 分钟。根据自己烤箱特性灵活调整，一般不超过 $\\pm 5$ 分钟。（最后几分钟时可在烤箱前观察）', NULL);
INSERT INTO `recipe_step` VALUES (501150, 300146, 25, '【烘烤】以上管 150 摄氏度，下管 160 摄氏度预热烘烤，约 10 分钟可到达预定温度。', NULL);
INSERT INTO `recipe_step` VALUES (501151, 300146, 26, '【烘烤】预热完成后，将模具放入烤箱下层', NULL);
INSERT INTO `recipe_step` VALUES (501152, 300146, 27, '【烘烤】选择变温烘烤，分为两个阶段。 第一阶段烤箱设定温度为：上管 150 摄氏度，下管 160 摄氏度； 烘烤总时长的前 3/5 为第一阶段烘烤 第二阶段温度为：上管 160 摄氏度，下管 170 摄氏度； 烘烤总时长的后 2/5 为第二阶段烘烤。直接调整烤箱温度即可切换。', NULL);
INSERT INTO `recipe_step` VALUES (501153, 300146, 28, '【烘烤】烤好后，出炉 此操作可能会烫手，注意用毛巾辅助', NULL);
INSERT INTO `recipe_step` VALUES (501154, 300146, 29, '【空气炸锅特别操作指南（以 6 寸为例）】预热：空气炸锅设置 130°C 预热 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501155, 300146, 30, '【空气炸锅特别操作指南（以 6 寸为例）】入锅与遮盖：将装有蛋糕糊的模具放入炸锅。立刻在模具上方盖上一层锡纸（亮面朝上，哑光面接触食物），锡纸边缘捏紧，防止被热风吹开', NULL);
INSERT INTO `recipe_step` VALUES (501156, 300146, 31, '【空气炸锅特别操作指南（以 6 寸为例）】第一阶段烘烤：设置 130°C，烘烤 35 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501157, 300146, 32, '【空气炸锅特别操作指南（以 6 寸为例）】第二阶段上色：打开炸锅，撤掉锡纸。将温度调高至 150°C，继续烘烤 10–15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501158, 300146, 33, '【空气炸锅特别操作指南（以 6 寸为例）】判断熟透：蛋糕顶部膨胀且上色呈金黄色即可出锅。用牙签扎入中心，拔出后没有湿润面糊带出即代表已烤熟', NULL);
INSERT INTO `recipe_step` VALUES (501159, 300146, 34, '【空气炸锅特别操作指南（以 6 寸为例）】出锅后的震热气与倒扣脱模操作，与烤箱版完全一致', NULL);
INSERT INTO `recipe_step` VALUES (501160, 300146, 35, '【冷却与脱模】（可选） 将模具从高处落下，震出其中的热气', NULL);
INSERT INTO `recipe_step` VALUES (501161, 300146, 36, '【冷却与脱模】模具倒扣 10 分钟，使蛋糕冷却 没有冷却的蛋糕立刻脱模会损伤蛋糕 此操作可能会烫手，注意用毛巾辅助', NULL);
INSERT INTO `recipe_step` VALUES (501162, 300146, 37, '【冷却与脱模】脱模，食用', NULL);
INSERT INTO `recipe_step` VALUES (501163, 300147, 1, '春卷放入 190℃的油中炸制 4 分钟（两面各 2 分钟）。', NULL);
INSERT INTO `recipe_step` VALUES (501164, 300148, 1, '【制作饺子皮】盆中加入所有面粉', NULL);
INSERT INTO `recipe_step` VALUES (501165, 300148, 2, '【制作饺子皮】加入芝麻香油', NULL);
INSERT INTO `recipe_step` VALUES (501166, 300148, 3, '【制作饺子皮】面粉中央挖小洞', NULL);
INSERT INTO `recipe_step` VALUES (501167, 300148, 4, '【制作饺子皮】分 4-5 次加入水，并搅和，当出现碎末状的稍微干燥面团时', NULL);
INSERT INTO `recipe_step` VALUES (501168, 300148, 5, '【制作饺子皮】取消加水，用手将面团压实', NULL);
INSERT INTO `recipe_step` VALUES (501169, 300148, 6, '【制作饺子皮】面团压实至可把盆周围的面粉纳入即可，此步骤为面光盆光', NULL);
INSERT INTO `recipe_step` VALUES (501170, 300148, 7, '【制作饺子皮】将面团置于桌上，盆倒扣于桌上，环境温度为 25 度，使面团醒发约 45 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501171, 300148, 8, '【制作饺子皮】醒发完成后，将面团搓成条状，合成一团，再次搓成条，重复 3 次', NULL);
INSERT INTO `recipe_step` VALUES (501172, 300148, 9, '【制作饺子皮】擀成条状，切成 20 份均匀大小面团，并搓成直径约 3-3.5cm 的球状', NULL);
INSERT INTO `recipe_step` VALUES (501173, 300148, 10, '【制作饺子皮】压扁面团，在手上，桌上，擀面杖上，及面团上撒上面粉，此步骤防止面团发粘', NULL);
INSERT INTO `recipe_step` VALUES (501174, 300148, 11, '【制作饺子皮】用擀面杖将面团擀平，约 8cm 直径，厚约 2mm，中间略微比四周厚 1mm', NULL);
INSERT INTO `recipe_step` VALUES (501175, 300148, 12, '【拌馅】猪肉去皮，保留部分肥肉,切成小块', NULL);
INSERT INTO `recipe_step` VALUES (501176, 300148, 13, '【拌馅】菜刀（建议两把）将猪肉剁成肉沫，放入碗中', NULL);
INSERT INTO `recipe_step` VALUES (501177, 300148, 14, '【拌馅】葱、姜切成末，放入肉碗中搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (501178, 300148, 15, '【拌馅】韭菜洗净，切短至 3mm 以下长度', NULL);
INSERT INTO `recipe_step` VALUES (501179, 300148, 16, '【拌馅】韭菜和肉沫混合，加入蚝油、生抽、香油各 2ml，加入一个鸡蛋的蛋清，用手混合搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (501180, 300148, 17, '【拌馅】放置 30 分钟即可开始包饺子', NULL);
INSERT INTO `recipe_step` VALUES (501181, 300148, 18, '【包饺子】左手上放面皮，放饺子馅一面尽量不要粘到面粉，防止无法合拢', NULL);
INSERT INTO `recipe_step` VALUES (501182, 300148, 19, '【包饺子】右手用筷子夹约面皮 1/2 直径的馅', NULL);
INSERT INTO `recipe_step` VALUES (501183, 300148, 20, '【包饺子】沿饺子皮圆周进行合拢，捏实，个人吃无需捏花，饺子皮不漏即可', NULL);
INSERT INTO `recipe_step` VALUES (501184, 300148, 21, '【煮饺子】使用可放下 20 只饺子的锅，或分批量煮', NULL);
INSERT INTO `recipe_step` VALUES (501185, 300148, 22, '【煮饺子】烧水，水约 3/4 锅的高度', NULL);
INSERT INTO `recipe_step` VALUES (501186, 300148, 23, '【煮饺子】大火烧开水后放入饺子，调至中火', NULL);
INSERT INTO `recipe_step` VALUES (501187, 300148, 24, '【煮饺子】第一次放入饺子，且水冒泡后，锅边加入 50ml 冷水（重复此步骤两次）', NULL);
INSERT INTO `recipe_step` VALUES (501188, 300148, 25, '【煮饺子】第三次水开后加入冷水 50ml，水开后调至小火等 60s 即可出锅', NULL);
INSERT INTO `recipe_step` VALUES (501189, 300149, 1, '蒸柜上汽后，蒸制 10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501190, 300150, 1, '面粉放入碗中，加入开水搅拌成絮状，再加入冷水揉成光滑面团，覆盖湿布静置 20 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501191, 300150, 2, '面团分成每份约 100 克，搓圆，擀成薄片。', NULL);
INSERT INTO `recipe_step` VALUES (501192, 300150, 3, '表面均匀涂抹食用油，撒上盐，卷成蜗牛状，松弛 10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501193, 300150, 4, '面团再次擀成薄饼，厚度均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501194, 300150, 5, '热锅中倒入油，小火煎至两面金黄起泡。', NULL);
INSERT INTO `recipe_step` VALUES (501195, 300150, 6, '煎好的饼依次铺入煎蛋、生菜、火腿、芝士片等配料，卷起即可。', NULL);
INSERT INTO `recipe_step` VALUES (501196, 300151, 1, '包菜对半切开，去掉中间白色部分【参见图一】', NULL);
INSERT INTO `recipe_step` VALUES (501197, 300151, 2, '手撕包菜，碗中放入 2 g 盐，清洗包菜并沥干备用【参见图二】', NULL);
INSERT INTO `recipe_step` VALUES (501198, 300151, 3, '姜片、蒜头、小米辣、蒜苗处理后备用【参见图三】', NULL);
INSERT INTO `recipe_step` VALUES (501199, 300151, 4, '五花肉切片，清水清洗后备用', NULL);
INSERT INTO `recipe_step` VALUES (501200, 300151, 5, '锅中加入 30 ml 食用油，倒入包菜翻炒，大火翻炒 1 分钟 后，加入 3 g 盐 ，继续翻炒 2 分钟 后取出备用', NULL);
INSERT INTO `recipe_step` VALUES (501201, 300151, 6, '锅中加入 30 ml 食用油，倒入五花肉，大火翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501202, 300151, 7, '倒入姜片等材料，翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501203, 300151, 8, '倒入包菜翻炒后，加入 香醋、料酒、鸡精、料酒，大火继续翻炒，2 分钟 后出锅', NULL);
INSERT INTO `recipe_step` VALUES (501204, 300152, 1, '解冻后的鸡腿放入蒸柜中，蒸5 分钟，备用；', NULL);
INSERT INTO `recipe_step` VALUES (501205, 300152, 2, '将蒸好的大鸡腿放入170℃的油锅中炸制2 分30 秒。', NULL);
INSERT INTO `recipe_step` VALUES (501206, 300153, 1, '胡萝卜切丁 0.2cm0.2cm0.2cm，备用', NULL);
INSERT INTO `recipe_step` VALUES (501207, 300153, 2, '午餐肉切丁 0.2cm0.2cm0.2cm，备用', NULL);
INSERT INTO `recipe_step` VALUES (501208, 300153, 3, '葱分别取葱白和葱绿，各切成 0.25-0.5cm 的小段，分开备用', NULL);
INSERT INTO `recipe_step` VALUES (501209, 300153, 4, '在碗中打入鸡蛋液，均匀搅拌，备用', NULL);
INSERT INTO `recipe_step` VALUES (501210, 300153, 5, '将胡萝卜，青豆，玉米粒煮熟捞出，备用（水别倒）', NULL);
INSERT INTO `recipe_step` VALUES (501211, 300153, 6, '将虾煮熟，捞出备用（水可以倒了）', NULL);
INSERT INTO `recipe_step` VALUES (501212, 300153, 7, '热锅热油，可以参考学习炒与煎中的热锅双油 第二次倒油需使用 20-30ml 油，等到第二次凉油热了以后，缓慢倒入鸡蛋（控制碗到油直接的流注直径大约在 0.5cm）不要搅拌', NULL);
INSERT INTO `recipe_step` VALUES (501213, 300153, 8, '鸡蛋凝固后立刻捞出，备用', NULL);
INSERT INTO `recipe_step` VALUES (501214, 300153, 9, '将午餐肉，青豆，胡萝卜，玉米粒，虾倒入锅中翻炒 1-2 分钟，装盘备用', NULL);
INSERT INTO `recipe_step` VALUES (501215, 300153, 10, '水冲一下锅，将杂物冲干净，保证锅内干净（可以有油但是不能有杂质）', NULL);
INSERT INTO `recipe_step` VALUES (501216, 300153, 11, '热锅热油(10ml)，将葱白放入爆香', NULL);
INSERT INTO `recipe_step` VALUES (501217, 300153, 12, '调至小火（如果油温过高可以关火 1-2 分钟），放入米饭，用铲子快速砸击米饭并翻炒，保证米饭均匀沾到油且粒粒分明', NULL);
INSERT INTO `recipe_step` VALUES (501218, 300153, 13, '倒入鸡蛋，继续砸击，使鸡蛋碎开并与米饭充分混合', NULL);
INSERT INTO `recipe_step` VALUES (501219, 300153, 14, '转大火，倒入其他所有备用配料，快速翻炒 1-2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501220, 300153, 15, '撒入盐，并翻炒至充分混合', NULL);
INSERT INTO `recipe_step` VALUES (501221, 300153, 16, '撒入葱绿，翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501222, 300153, 17, '关火，装盘', NULL);
INSERT INTO `recipe_step` VALUES (501223, 300154, 1, '在不锈钢桶中放入6500g水和500g卤料，大火烧开后，捞出料渣，备用；', NULL);
INSERT INTO `recipe_step` VALUES (501224, 300154, 2, '将把子肉放入卤汤中，大火烧开后转小火卤1小时；', NULL);
INSERT INTO `recipe_step` VALUES (501225, 300155, 1, '用准备好的温水把酵母粉化开，稍微搅拌小就好，备用', NULL);
INSERT INTO `recipe_step` VALUES (501226, 300155, 2, '取准备好的面粉，依次添加盐、橄榄油、白砂糖', NULL);
INSERT INTO `recipe_step` VALUES (501227, 300155, 3, '准备混合水和面粉，边加水边搅拌直至水全部加完', NULL);
INSERT INTO `recipe_step` VALUES (501228, 300155, 4, '搅拌至看不到干米粉为止', NULL);
INSERT INTO `recipe_step` VALUES (501229, 300155, 5, '用差不多三倍大面团的容器装好，密封，冰箱冷藏（4 度） 等待 8~12 小时，一般晚上做第二天就可以用', NULL);
INSERT INTO `recipe_step` VALUES (501230, 300155, 6, '观察面团醒发完毕 差不多是原始大小大约两倍算醒发完毕', NULL);
INSERT INTO `recipe_step` VALUES (501231, 300155, 7, '取醒发好的面团，均匀分成四份，分别用保鲜膜盖好，备用', NULL);
INSERT INTO `recipe_step` VALUES (501232, 300155, 8, '案板撒稍微多一点的干面粉，准备开始揉面', NULL);
INSERT INTO `recipe_step` VALUES (501233, 300155, 9, '因为是比较湿的面团，所以粘上干面粉后才没那么粘手，不用揉太多次，面团表面稍微光滑一点就可以了', NULL);
INSERT INTO `recipe_step` VALUES (501234, 300155, 10, '用手拉扯，或者擀面杖擀平，也不一定非得擀圆，只要厚度均匀，烤箱放得进去就好', NULL);
INSERT INTO `recipe_step` VALUES (501235, 300155, 11, '铺好油纸，放上饼皮，依照个人口味，把准备好的食材放上去，撒上芝士碎', NULL);
INSERT INTO `recipe_step` VALUES (501236, 300155, 12, '水果烤箱上 180 度，下 220 度，16 分钟即可', NULL);
INSERT INTO `recipe_step` VALUES (501237, 300155, 13, '肉蔬菜烤箱上 200 度，下 230 度，18 分钟即可', NULL);
INSERT INTO `recipe_step` VALUES (501238, 300155, 14, '挤上沙拉酱或者其他自己喜欢的酱即可享用~', NULL);
INSERT INTO `recipe_step` VALUES (501239, 300156, 1, '土豆去皮，切均匀的小块。放入淀粉（不加水）搅拌，使得淀粉覆盖土豆表面', NULL);
INSERT INTO `recipe_step` VALUES (501240, 300156, 2, '起锅烧油，放入土豆块，缓缓翻滚煎炸 5-7 分钟 ，直至筷子可以插进土豆', NULL);
INSERT INTO `recipe_step` VALUES (501241, 300156, 3, '取出土豆，放入大碗备用', NULL);
INSERT INTO `recipe_step` VALUES (501242, 300156, 4, '锅中加入水、白砂糖，沿着一个方向慢慢搅动白砂糖，直到白砂糖颜色变成褐色', NULL);
INSERT INTO `recipe_step` VALUES (501243, 300156, 5, '重新倒入土豆，翻炒 30 S 后 出锅', NULL);
INSERT INTO `recipe_step` VALUES (501244, 300156, 6, '土豆盛盘，散上芝麻', NULL);
INSERT INTO `recipe_step` VALUES (501245, 300157, 1, '食材预处理： 将胡萝卜洗净去皮，切成大约 3cm 的滚刀块。 玉米洗净，剁成大约 4cm 的圆柱状小块。 山药去皮（建议佩戴手套，防止粘液导致皮肤过敏），切成大约 4cm 的长段，备用。', NULL);
INSERT INTO `recipe_step` VALUES (501246, 300157, 2, '排骨焯水： 锅中加入足量冷水，放入洗净的排骨。 加入大约 10g 姜片、葱结和 15ml 料酒。 大火煮沸，沸腾后等待 3 分钟，期间用勺子撇去表面浮沫。 捞出排骨，用大约 40℃ 的温水洗净杂质，沥干备用。', NULL);
INSERT INTO `recipe_step` VALUES (501247, 300157, 3, '翻炒排骨： 热锅，倒入 10ml 食用油，等待 10 秒让油温升高。 放入剩余大约 10g 姜片爆香。 放入全部准备好的排骨，保持中火翻炒大约 1 分钟，至排骨表面微焦。', NULL);
INSERT INTO `recipe_step` VALUES (501248, 300157, 4, '炖煮过程： 在锅中一次性加入 1500ml - 2000ml 饮用水。 放入全部准备好的胡萝卜、玉米和山药。 大火烧开后转小火，盖上锅盖，慢炖 40 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501249, 300157, 5, '调味与出锅： 加入 6g - 8g 食盐，用勺子搅拌均匀。 保持小火继续炖煮 2 分钟使盐分入味。 关火，根据个人喜好撒入小葱末，盛盘。', NULL);
INSERT INTO `recipe_step` VALUES (501250, 300158, 1, '排骨洗净，切到约 4cm ±2cm 3 ± 2cm 的小块（如没有剁排骨的工具，可以求助摊主）', NULL);
INSERT INTO `recipe_step` VALUES (501251, 300158, 2, '炒锅倒入冷水 700ml 和排骨一起加热至煮沸，关火捞出排骨', NULL);
INSERT INTO `recipe_step` VALUES (501252, 300158, 3, '苦瓜中间切为两半，清除干净内部的种子和苦瓜瓤，切为 0.5 ± 0.3 cm 的苦瓜条，洗净 汤锅倒入水 1100ml 和排骨，大火 等待水沸腾后将苦瓜和虾皮下锅转小火，放等待 120~240 分钟（在 120 分钟之后可以捞出一块肉进行品尝，若肉可以较为轻松的从骨头上分离即可关火） 出锅时加盐和白胡椒，推荐量为每 250ml 0.3 到 0.6g 盐，0.1 到 0.5g 白胡椒 倒入 1000ml 水和排骨，虾皮和苦瓜 选择炖汤功能，进行烹饪（一般为加压烹饪 45 分钟） 出锅，和汤锅一样进行加盐和胡椒', NULL);
INSERT INTO `recipe_step` VALUES (501253, 300159, 1, '分离蛋黄蛋清', NULL);
INSERT INTO `recipe_step` VALUES (501254, 300159, 2, '盛有蛋白的碗中加 10g 白砂糖湿性打发', NULL);
INSERT INTO `recipe_step` VALUES (501255, 300159, 3, '盛有蛋黄的碗中将 40g 白砂糖分三次加入，搅拌至均匀', NULL);
INSERT INTO `recipe_step` VALUES (501256, 300159, 4, '蛋黄中分三次加入马斯卡彭芝士，搅拌至均匀', NULL);
INSERT INTO `recipe_step` VALUES (501257, 300159, 5, '蛋黄中最后加入朗姆酒，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (501258, 300159, 6, '将打发好的蛋白分三次加入蛋黄芝士液中', NULL);
INSERT INTO `recipe_step` VALUES (501259, 300159, 7, '手指饼干两面浸湿咖啡液，平铺入容器', NULL);
INSERT INTO `recipe_step` VALUES (501260, 300159, 8, '两层芝士液两层饼干交替放入容器（这一步按照大家意愿及容器高度酌情处理）', NULL);
INSERT INTO `recipe_step` VALUES (501261, 300159, 9, '放入冰箱冷藏四个小时（心急的小伙伴可以提早拿出来）', NULL);
INSERT INTO `recipe_step` VALUES (501262, 300159, 10, '取出后在表面筛上可可粉，即可享用啦', NULL);
INSERT INTO `recipe_step` VALUES (501263, 300160, 1, '肉先剁好，块状，用清水+盐浸泡 5 分钟，去除血水，去腥，然后空干水', NULL);
INSERT INTO `recipe_step` VALUES (501264, 300160, 2, '葱蒜辣椒土豆等洗干净，土豆削皮', NULL);
INSERT INTO `recipe_step` VALUES (501265, 300160, 3, '葱白切长段，长度 4cm 一段，菜椒和线椒切块状', NULL);
INSERT INTO `recipe_step` VALUES (501266, 300160, 4, '土豆切成滚刀土豆，即切一刀动滚动一下，一块土豆大概有 4cm4cm 大小即可', NULL);
INSERT INTO `recipe_step` VALUES (501267, 300160, 5, '炒糖色：先将油加入锅中，然后将白砂糖放入，用锅铲来回搅拌，将糖炒化，然后炒出焦黄色，此时将空干水的鸡肉倒入锅中翻炒，进行上色', NULL);
INSERT INTO `recipe_step` VALUES (501268, 300160, 6, '放入花椒，香叶，香果，干线椒等进行翻炒', NULL);
INSERT INTO `recipe_step` VALUES (501269, 300160, 7, '放入 5g 盐，生抽 7ml，蚝油 10g ，料酒 100g，倒入 1 升清水，料酒可以用啤酒代替', NULL);
INSERT INTO `recipe_step` VALUES (501270, 300160, 8, '调至中火，将水烧开，调制中小火慢炖入味', NULL);
INSERT INTO `recipe_step` VALUES (501271, 300160, 9, '当水收至鸡肉即将露出时，将土豆放在锅表面：注意不要翻动土豆，就盖在表面，不然翻到下面容易粘锅，继续盖锅盖炖，炖一会后将大葱，菜椒和甜椒放入，继续炖。', NULL);
INSERT INTO `recipe_step` VALUES (501272, 300160, 10, '炖到汁收的差不多时可以进行翻面，将土豆与汤汁相吸，最后关火盛出。', NULL);
INSERT INTO `recipe_step` VALUES (501273, 300161, 1, '制作面团：将面粉，牛奶（建议加热到 40°，本人使用微波炉 15 - 20s），酵母，鸡蛋，面粉，糖和盐混合起来。', NULL);
INSERT INTO `recipe_step` VALUES (501274, 300161, 2, '搅拌面团，将原料混合均匀成团。', NULL);
INSERT INTO `recipe_step` VALUES (501275, 300161, 3, '加入黄油混合。', NULL);
INSERT INTO `recipe_step` VALUES (501276, 300161, 4, '继续搅拌 + 手揉，均匀混合。', NULL);
INSERT INTO `recipe_step` VALUES (501277, 300161, 5, '开始发面，使用保鲜膜覆盖容器，普通气温(10 - 20°)放置 1 - 2 小时，稍长时间对效果影响不大。', NULL);
INSERT INTO `recipe_step` VALUES (501278, 300161, 6, '明显看到面团发酵变大（2 倍）即可开始切分面团, 此时面团应该不再十分黏手。', NULL);
INSERT INTO `recipe_step` VALUES (501279, 300161, 7, '切分面团：理想状态每一份 60g（美观），可根据喜好适当调整大小。', NULL);
INSERT INTO `recipe_step` VALUES (501280, 300161, 8, '将每一份小面团使用擀面杖擀成舌状后卷起, 再次醒面 10。', NULL);
INSERT INTO `recipe_step` VALUES (501281, 300161, 9, '再次使用擀面杖擀成舌状后卷起, 从中间切开（一个变成两个）。', NULL);
INSERT INTO `recipe_step` VALUES (501282, 300161, 10, '再次使用擀面杖擀成舌状后卷起, 从中间切开（两个变成四个）。（此步骤可以按照自己的时间多擀/卷几次, 把握一份的大小就行）', NULL);
INSERT INTO `recipe_step` VALUES (501283, 300161, 11, '烤盘放入油纸并倒入花生油, （每份卷好的）底部蘸水 + 面粉后放入烤盘。', NULL);
INSERT INTO `recipe_step` VALUES (501284, 300161, 12, '再次醒发（盖上保鲜膜）, 这一步可以放入冰箱, 第二天再烤。', NULL);
INSERT INTO `recipe_step` VALUES (501285, 300161, 13, '刷上蛋液。', NULL);
INSERT INTO `recipe_step` VALUES (501286, 300161, 14, '烤箱 180°(355°F), 18 - 20 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501287, 300161, 15, '出炉后, 刷上蜂蜜水, 撒上芝麻。', NULL);
INSERT INTO `recipe_step` VALUES (501288, 300162, 1, '【鸡爪处理】用剪刀 / 刀 把鸡爪上的指甲的部分全部剪掉 包括指甲下面的肉和骨头，让它一点指甲都不剩', NULL);
INSERT INTO `recipe_step` VALUES (501289, 300162, 2, '【鸡爪处理】用水把他们洗干净，放一边', NULL);
INSERT INTO `recipe_step` VALUES (501290, 300162, 3, '【鸡爪处理】把鸡爪放入大锅中，准备去腥味', NULL);
INSERT INTO `recipe_step` VALUES (501291, 300162, 4, '【鸡爪处理】大葱，料酒，姜 全放进去', NULL);
INSERT INTO `recipe_step` VALUES (501292, 300162, 5, '【鸡爪处理】加水没过鸡爪', NULL);
INSERT INTO `recipe_step` VALUES (501293, 300162, 6, '【鸡爪处理】大火煮开 中途可以把浮末捞起来', NULL);
INSERT INTO `recipe_step` VALUES (501294, 300162, 7, '【鸡爪处理】水开100度，沸腾后等 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501295, 300162, 8, '【鸡爪处理】关火，捞出来，把水沥干，洗干净，放入盆里', NULL);
INSERT INTO `recipe_step` VALUES (501296, 300162, 9, '【去骨】放入冰箱，冷冻层 20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501297, 300162, 10, '【去骨】把全部放入不是冷冻层的冰箱，然后分批10个一批拿出来去骨', NULL);
INSERT INTO `recipe_step` VALUES (501298, 300162, 11, '【去骨】从手指（鸡爪的）最前端开始，每只手指都要用刀划开划到它的手背部分', NULL);
INSERT INTO `recipe_step` VALUES (501299, 300162, 12, '【去骨】再从手背部用刀分划开至整个手臂', NULL);
INSERT INTO `recipe_step` VALUES (501300, 300162, 13, '【去骨】把每只手指关节处都掰一掰按手指出声音时那种', NULL);
INSERT INTO `recipe_step` VALUES (501301, 300162, 14, '【去骨】按着它的手指最前端，往里推，每只手指都一样，先推到中间手掌手背部分', NULL);
INSERT INTO `recipe_step` VALUES (501302, 300162, 15, '【去骨】每只手指皮脱离后，从手掌开始往手臂部分推直到整个脱下来了', NULL);
INSERT INTO `recipe_step` VALUES (501303, 300162, 16, '【去骨】放入碗中，备用', NULL);
INSERT INTO `recipe_step` VALUES (501304, 300162, 17, '【调配腌料】小米辣 切均匀小颗', NULL);
INSERT INTO `recipe_step` VALUES (501305, 300162, 18, '【调配腌料】大蒜，洋葱，香菜切碎', NULL);
INSERT INTO `recipe_step` VALUES (501306, 300162, 19, '【调配腌料】柠檬对半切开，把柠檬汁挤入鸡爪的容器里', NULL);
INSERT INTO `recipe_step` VALUES (501307, 300162, 20, '【调配腌料】把全部调料倒入装鸡爪的容器，小米辣，大蒜，洋葱和香菜也放进去', NULL);
INSERT INTO `recipe_step` VALUES (501308, 300162, 21, '【调配腌料】抓拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (501309, 300162, 22, '【调配腌料】放入冰箱一个晚上（6 个小时）', NULL);
INSERT INTO `recipe_step` VALUES (501310, 300162, 23, '【调配腌料】调配好后全部放入准备好的鸡爪', NULL);
INSERT INTO `recipe_step` VALUES (501311, 300163, 1, '【1. 食材准备】胡萝卜去头尾，去皮，滚刀切', NULL);
INSERT INTO `recipe_step` VALUES (501312, 300163, 2, '【1. 食材准备】洋葱剥去外层去芯，切成月牙状', NULL);
INSERT INTO `recipe_step` VALUES (501313, 300163, 3, '【1. 食材准备】土豆去皮、切大块', NULL);
INSERT INTO `recipe_step` VALUES (501314, 300163, 4, '【1. 食材准备】肉切块状', NULL);
INSERT INTO `recipe_step` VALUES (501315, 300163, 5, '【1. 食材准备】剥蒜拍平切碎', NULL);
INSERT INTO `recipe_step` VALUES (501316, 300163, 6, '【1. 食材准备】咖喱块切碎，增加接触面积加速溶解', NULL);
INSERT INTO `recipe_step` VALUES (501317, 300163, 7, '【2. 烧煮过程】热油锅放入蒜和肉，快速翻炒至肉表面变白', NULL);
INSERT INTO `recipe_step` VALUES (501318, 300163, 8, '【2. 烧煮过程】加入胡萝卜，快速翻炒至均匀受热', NULL);
INSERT INTO `recipe_step` VALUES (501319, 300163, 9, '【2. 烧煮过程】加入洋葱，快速翻炒至洋葱变透明状', NULL);
INSERT INTO `recipe_step` VALUES (501320, 300163, 10, '【2. 烧煮过程】加入土豆，保持翻炒至土豆变软（可以用筷子确认）', NULL);
INSERT INTO `recipe_step` VALUES (501321, 300163, 11, '【2. 烧煮过程】加水没过所有食材，沸腾后等待 15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501322, 300163, 12, '【2. 烧煮过程】关火，加咖喱并搅拌', NULL);
INSERT INTO `recipe_step` VALUES (501323, 300163, 13, '【2. 烧煮过程】等待咖喱融化后再开火，缓慢搅拌 10 分钟，防止糊锅', NULL);
INSERT INTO `recipe_step` VALUES (501324, 300163, 14, '【2. 烧煮过程】在外观呈粘稠状态关火结束制作', NULL);
INSERT INTO `recipe_step` VALUES (501325, 300163, 15, '【3.冷藏后加热】微波炉：单人份高火 2-3 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501326, 300163, 16, '【3.冷藏后加热】锅：需额外加 50ml 水，加热时保持搅拌', NULL);
INSERT INTO `recipe_step` VALUES (501327, 300164, 1, '【1. 食材准备】洋葱剥去外层去芯，切成月牙状', NULL);
INSERT INTO `recipe_step` VALUES (501328, 300164, 2, '【1. 食材准备】葱洗净切成 0.5cm 的小段', NULL);
INSERT INTO `recipe_step` VALUES (501329, 300164, 3, '【1. 食材准备】热锅直接放入白芝麻，前后晃动锅体使芝麻均匀受热至略呈金黄色', NULL);
INSERT INTO `recipe_step` VALUES (501330, 300164, 4, '【1. 食材准备】肥牛焯水 1 分钟后捞出', NULL);
INSERT INTO `recipe_step` VALUES (501331, 300164, 5, '【1. 食材准备】将 40g 味淋（或 30g 料酒），30g 酱油，20g 耗油，5g 糖，5g 老抽（可选，用于调色），在碗中搅拌混合成调料（该步骤可直接将碗放在电子秤上进行）', NULL);
INSERT INTO `recipe_step` VALUES (501332, 300164, 6, '【2. 烧煮过程】热油锅放入洋葱，快速翻炒至洋葱变透明状', NULL);
INSERT INTO `recipe_step` VALUES (501333, 300164, 7, '【2. 烧煮过程】关小火，加入 250g 水（或出汁），开回大火加热等待 3 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501334, 300164, 8, '【2. 烧煮过程】加入牛肉和调料', NULL);
INSERT INTO `recipe_step` VALUES (501335, 300164, 9, '【2. 烧煮过程】不断翻动所有食材 10 分钟，防止食材粘锅', NULL);
INSERT INTO `recipe_step` VALUES (501336, 300164, 10, '【2. 烧煮过程】关火', NULL);
INSERT INTO `recipe_step` VALUES (501337, 300164, 11, '【2. 烧煮过程】盛装肥牛丼至米饭上（注意要把汁水淋一些在饭上）', NULL);
INSERT INTO `recipe_step` VALUES (501338, 300164, 12, '【2. 烧煮过程】撒上葱花和白芝麻，制作完成。', NULL);
INSERT INTO `recipe_step` VALUES (501339, 300164, 13, '【3.冷藏后加热】微波炉：单人份高火 2-3 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501340, 300164, 14, '【3.冷藏后加热】锅：需额外加 50ml 水，加热时需不断翻动', NULL);
INSERT INTO `recipe_step` VALUES (501341, 300165, 1, '鱼处理好后洗净，（特别注意肚内的血丝、不洗干净会有腥味），放入大碗中，倒入料酒、10g 姜片、5g 盐，腌制 15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501342, 300165, 2, '豆腐切块，放入凉水浸泡 5 分钟，捞出备用', NULL);
INSERT INTO `recipe_step` VALUES (501343, 300165, 3, '煎鱼前，先用生姜片擦一下锅防止粘锅，倒入油（油量为 15ml 鱼的条数 ），烧热后放入鱼煎 2~3 分钟，期间需要晃动一下鱼，防止粘底，且需要翻一次身', NULL);
INSERT INTO `recipe_step` VALUES (501344, 300165, 4, '待鱼全部煎好之后，倒入开水、5ml 料酒、姜片，小火转至大火，盖上锅盖、大火煮 10 分钟（水要稍微多一些，后面会蒸发掉一些）', NULL);
INSERT INTO `recipe_step` VALUES (501345, 300165, 5, '见汤变白后倒入准备好的豆腐，调中火再煮 5 分钟，加入 10g 盐、3g 胡椒粉调味，最后撒上葱花出锅', NULL);
INSERT INTO `recipe_step` VALUES (501346, 300166, 1, '鸡蛋在碗中打散，再倒入香油。', NULL);
INSERT INTO `recipe_step` VALUES (501347, 300166, 2, '水烧开后，在沸腾状态下快速倒入盛有鸡蛋的碗中。', NULL);
INSERT INTO `recipe_step` VALUES (501348, 300166, 3, '放入白糖。', NULL);
INSERT INTO `recipe_step` VALUES (501349, 300167, 1, '血肠用牙签多扎一些小孔，然后放水中小火煮十分钟，不要让水烧开，保持 80 度，否则血肠非常容易爆开。', NULL);
INSERT INTO `recipe_step` VALUES (501350, 300167, 2, '煮好的血肠切块备用。', NULL);
INSERT INTO `recipe_step` VALUES (501351, 300167, 3, '排骨放料酒焯水，控干水分备用。', NULL);
INSERT INTO `recipe_step` VALUES (501352, 300167, 4, '锅内放入菜籽油，放蒜瓣，干辣椒，姜粉炒香。', NULL);
INSERT INTO `recipe_step` VALUES (501353, 300167, 5, '放入排骨翻炒至表面金黄。', NULL);
INSERT INTO `recipe_step` VALUES (501354, 300167, 6, '酸菜洗净拧干水分，放入锅中，加入香油翻炒，香油可以更好的去除酸味而且让酸菜更香，大火翻炒二分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501355, 300167, 7, '加入 600 毫升热水。', NULL);
INSERT INTO `recipe_step` VALUES (501356, 300167, 8, '转入电压力锅，加香叶，八角，葱结，盐。', NULL);
INSERT INTO `recipe_step` VALUES (501357, 300167, 9, '浓香模式压 40 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501358, 300167, 10, '到时间后放气开盖。加入血肠和枸杞，盖上锅盖焖二分钟即可，血肠是熟的，不需再加热。', NULL);
INSERT INTO `recipe_step` VALUES (501359, 300167, 11, '倒入盆中，按照上表调制蘸料，即可开吃。', NULL);
INSERT INTO `recipe_step` VALUES (501360, 300168, 1, '将500g 杂粮、2kg 大米清洗干净放入泡米桶，加水至5kg，静置浸泡3 小时；', NULL);
INSERT INTO `recipe_step` VALUES (501361, 300168, 2, '将浸泡后的米（含水）倒入煮饭锅，加入30g 大豆油，蒸40 分钟，焖10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501362, 300169, 1, '奇亚籽泡牛奶 10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501363, 300169, 2, '泡籽之时，把半粒芒果、葡萄柚去皮切丁，放入杯中。', NULL);
INSERT INTO `recipe_step` VALUES (501364, 300169, 3, '半粒芒果切小块放入调理机加冰块、椰奶打成泥。', NULL);
INSERT INTO `recipe_step` VALUES (501365, 300169, 4, '倒入杯中，放上点缀材料（如有）。', NULL);
INSERT INTO `recipe_step` VALUES (501366, 300169, 5, '一边享用一边写代码！！', NULL);
INSERT INTO `recipe_step` VALUES (501367, 300170, 1, '玉米粒和胡萝卜丁提前焯水 1 分钟，捞出沥干备用', NULL);
INSERT INTO `recipe_step` VALUES (501368, 300170, 2, '热锅凉油，放入胡萝卜丁略炒，再加入玉米粒翻炒', NULL);
INSERT INTO `recipe_step` VALUES (501369, 300170, 3, '加入白砂糖和盐，炒匀', NULL);
INSERT INTO `recipe_step` VALUES (501370, 300170, 4, '混合水与淀粉成水淀粉，倒入锅中快速翻炒使汤汁略稠', NULL);
INSERT INTO `recipe_step` VALUES (501371, 300170, 5, '加入熟松仁翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (501372, 300170, 6, '出锅装盘', NULL);
INSERT INTO `recipe_step` VALUES (501373, 300171, 1, '蒸柜上汽后，蒸制10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501374, 300172, 1, '准备工作: 香菇提前浸泡 2 - 3 小时至变软。腐竹提前浸泡 30 分钟至变软', NULL);
INSERT INTO `recipe_step` VALUES (501375, 300172, 2, '准备酱汁 1: 南乳、柱侯酱、20g 腐乳、老抽放入同个小碗中搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (501376, 300172, 3, '准备酱汁 2: 20g 腐乳、砂糖、辣椒油放入同个小碗搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (501377, 300172, 4, '泡好的香菇去除根部', NULL);
INSERT INTO `recipe_step` VALUES (501378, 300172, 5, '泡好的腐竹切成 5cm 的小段，挤干水分', NULL);
INSERT INTO `recipe_step` VALUES (501379, 300172, 6, '洋葱去皮切丝。也可以用去皮红葱头进行替代，口味更佳。', NULL);
INSERT INTO `recipe_step` VALUES (501380, 300172, 7, '小葱切成大约 5cm 的葱段', NULL);
INSERT INTO `recipe_step` VALUES (501381, 300172, 8, '羊腩冷水下锅，放入 2 - 3 片姜片，倒入凉水，大火煮至水滚后关火', NULL);
INSERT INTO `recipe_step` VALUES (501382, 300172, 9, '捞出羊腩，放入准备好的冷水盆中放凉，使其更有嚼劲', NULL);
INSERT INTO `recipe_step` VALUES (501383, 300172, 10, '锅烧热后放入冷油，放入 4 - 5 片姜片、洋葱/红葱头、葱白段、7 - 8 瓣蒜瓣进行爆香', NULL);
INSERT INTO `recipe_step` VALUES (501384, 300172, 11, '放入冷却好的羊腩，用筷子搅拌大约 2 - 5 分钟直至出现金黄色', NULL);
INSERT INTO `recipe_step` VALUES (501385, 300172, 12, '放入调好的酱汁 1 ，翻炒大约 2 分钟至颜色均匀', NULL);
INSERT INTO `recipe_step` VALUES (501386, 300172, 13, '倒入清水至刚好没过食材', NULL);
INSERT INTO `recipe_step` VALUES (501387, 300172, 14, '放入香菇、冰糖、香叶、八角、桂皮', NULL);
INSERT INTO `recipe_step` VALUES (501388, 300172, 15, '加盖转小火炖 90 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501389, 300172, 16, '开盖加入腐竹，加盖转中火煮 20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501390, 300172, 17, '开盖加入酱汁 2 搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (501391, 300172, 18, '关火，出锅前加入葱绿段或香菜', NULL);
INSERT INTO `recipe_step` VALUES (501392, 300173, 1, '将400g 莴笋条，加入4g 盐、4g 白砂糖拌匀，腌制1 小时后纯净水冲洗，沥干水分备用；', NULL);
INSERT INTO `recipe_step` VALUES (501393, 300173, 2, '将1 包柠檬拆骨鸡爪与腌制后的莴笋条拌匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (501394, 300174, 1, '称 40~45 克柠檬，放入雪克杯中', NULL);
INSERT INTO `recipe_step` VALUES (501395, 300174, 2, '雪克杯盖盖子锤大约 10 次', NULL);
INSERT INTO `recipe_step` VALUES (501396, 300174, 3, '加入果蜜 40~45 克', NULL);
INSERT INTO `recipe_step` VALUES (501397, 300174, 4, '补水', NULL);
INSERT INTO `recipe_step` VALUES (501398, 300174, 5, '摇晃均匀', NULL);
INSERT INTO `recipe_step` VALUES (501399, 300174, 6, '最后根据喜好加冰', NULL);
INSERT INTO `recipe_step` VALUES (501400, 300175, 1, '先把辅料备好： 碗 1：姜切成 1.5cm\\1.5cm 的小块，半头蒜剥好皮，如果有小米辣切成 1cm 小段 碗 2：放入 2 片香叶，0.5g 花椒，2 个八角，3 个干辣椒，3 个丁香， 2 片甘草 碗 3: 放入 2 块南乳 碗 4: 放入 15g 豆瓣酱 碗 5: 放入 10g 冰糖 碗 6：倒入花雕酒 10g 和白酒 10g 碗 7：加入 50g 柱候酱，20g 蚝油，20g 叉烧酱，5g 老抽，60g 生抽', NULL);
INSERT INTO `recipe_step` VALUES (501401, 300175, 2, '牛肉不用切，直接冷水下锅，开大火焯水，水沸腾时将牛肉捞出', NULL);
INSERT INTO `recipe_step` VALUES (501402, 300175, 3, '冲洗牛肉表面的杂质后，切成 4cm\\4cm\\4cm 的大块，控干水后放入碗中备用', NULL);
INSERT INTO `recipe_step` VALUES (501403, 300175, 4, '大火，热锅下油，把碗 1（姜、蒜、小米辣）倒入锅中，炒香', NULL);
INSERT INTO `recipe_step` VALUES (501404, 300175, 5, '中小火，倒入碗 2（香料），翻炒均匀，大概 30 秒', NULL);
INSERT INTO `recipe_step` VALUES (501405, 300175, 6, '中小火，放入碗 3（南乳），用锅铲把南乳压碎', NULL);
INSERT INTO `recipe_step` VALUES (501406, 300175, 7, '中小火，放入碗 4（豆瓣酱），翻炒均匀，大概 30 秒', NULL);
INSERT INTO `recipe_step` VALUES (501407, 300175, 8, '中小火，放入碗 5（冰糖），炒至融化', NULL);
INSERT INTO `recipe_step` VALUES (501408, 300175, 9, '中小火，下入牛腩，炒至牛肉上色', NULL);
INSERT INTO `recipe_step` VALUES (501409, 300175, 10, '大火，沿锅边淋入碗 6（酒），快速翻炒，炒至牛肉表面略微焦褐', NULL);
INSERT INTO `recipe_step` VALUES (501410, 300175, 11, '倒入碗 7（酱料），快速翻炒，留意底层汁水，炒至不停冒小气泡，汤汁略微浓稠', NULL);
INSERT INTO `recipe_step` VALUES (501411, 300175, 12, '将锅内全部食材转移至另一个炖煮锅或高压锅，加水淹过食材', NULL);
INSERT INTO `recipe_step` VALUES (501412, 300175, 13, '根据使用的锅来选择炖肉的时间： a. 普通炖煮锅：小火炖煮 3 个小时 b. 高压锅：压 40 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501413, 300175, 14, '时间到后开盖调味，如果不够咸加盐或生抽（少量加，不断尝味道，直到合适），不够甜则同理加糖', NULL);
INSERT INTO `recipe_step` VALUES (501414, 300175, 15, '调好味道后便可以把牛腩先捞出', NULL);
INSERT INTO `recipe_step` VALUES (501415, 300175, 16, '如果要吃萝卜土豆，则削皮切成 2cm 厚片倒入锅中煮 10 - 15 分钟（或煮至想要吃的口感），如果是高压锅则在加压煮 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501416, 300175, 17, '煮好后捞出萝卜土豆和牛腩放一起', NULL);
INSERT INTO `recipe_step` VALUES (501417, 300175, 18, '把汤汁过滤淋入碗中', NULL);
INSERT INTO `recipe_step` VALUES (501418, 300176, 1, '将桂圆肉扒出，用清水洗两次，放入碗中浸泡 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501419, 300176, 2, '红枣用清水洗两次，放入碗中浸泡 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501420, 300176, 3, '糯米放入电饭锅中，清水淘米两次后，加入 2000ml 水', NULL);
INSERT INTO `recipe_step` VALUES (501421, 300176, 4, '将桂圆和红枣加入电饭锅', NULL);
INSERT INTO `recipe_step` VALUES (501422, 300176, 5, '打开电饭锅煮饭模式，1 小时后粥成', NULL);
INSERT INTO `recipe_step` VALUES (501423, 300177, 1, '【核心思路】青椒酿：青椒去籽挖空 → 塞入猪肉馅或虾滑 → 煎至虎皮色 → 酱汁焖煮', NULL);
INSERT INTO `recipe_step` VALUES (501424, 300177, 2, '【核心思路】田螺酿：田螺焯水取肉 → 螺肉与猪肉剁碎混合 → 塞回螺壳 → 紫苏薄荷焖煮', NULL);
INSERT INTO `recipe_step` VALUES (501425, 300177, 3, '【核心思路】猪肉馅：最基础通用的选择，肥瘦 3:7 口感最佳', NULL);
INSERT INTO `recipe_step` VALUES (501426, 300177, 4, '【核心思路】虾滑馅：鲜甜弹牙，青椒酿里常用', NULL);
INSERT INTO `recipe_step` VALUES (501427, 300177, 5, '【核心思路】螺肉猪肉混合馅：田螺酿的灵魂，螺肉与猪肉 1:1，加紫苏薄荷', NULL);
INSERT INTO `recipe_step` VALUES (501428, 300177, 6, '【核心思路】混合馅：猪肉 + 虾滑混搭，鲜甜与油脂香兼得', NULL);
INSERT INTO `recipe_step` VALUES (501429, 300178, 1, '锅中放入 700g 水、2100g 卤鸡爪翅，烧制 7 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (501430, 300178, 2, '关火加入 150g 炸制梅菜，翻拌均匀；', NULL);
INSERT INTO `recipe_step` VALUES (501431, 300178, 3, '出品时撒入 1g 葱花、1g 红椒丁点缀。', NULL);
INSERT INTO `recipe_step` VALUES (501432, 300179, 1, '梅菜放到清水中，浸泡 1 小时', NULL);
INSERT INTO `recipe_step` VALUES (501433, 300179, 2, '锅中倒入 50 ml 食用油，将整个五花肉猪皮朝下，放到锅中 1 分钟 ，取出挂掉猪皮 【可选】', NULL);
INSERT INTO `recipe_step` VALUES (501434, 300179, 3, '锅中加入开水，放入五花肉，大火煮 20 分钟 （筷子可以插进五花肉），取出五花肉', NULL);
INSERT INTO `recipe_step` VALUES (501435, 300179, 4, '在五花肉表面涂抹均匀老抽、五香粉、白砂糖，放置 15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501436, 300179, 5, '起锅烧油，加入五花肉，中火油炸直至两面金黄色（3-5 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (501437, 300179, 6, '起锅烧油，倒入梅菜，加上小米椒、蒜蓉、鸡精、食用盐后翻炒，直至炒干梅干菜水分', NULL);
INSERT INTO `recipe_step` VALUES (501438, 300179, 7, '五花肉切片（后端 0.5-1 cm）,放在大碗中，散上梅干菜', NULL);
INSERT INTO `recipe_step` VALUES (501439, 300179, 8, '中火蒸 45 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501440, 300179, 9, '拿个盘子倒盖在五花肉大碗中，将五花肉倒在盘子中', NULL);
INSERT INTO `recipe_step` VALUES (501441, 300180, 1, '棒棒虾无需解冻直接放入170℃的油锅中炸制8 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501442, 300181, 1, '大排洗干净，剔骨，用刀面拍松，切成厚片，再改成粗条。', NULL);
INSERT INTO `recipe_step` VALUES (501443, 300181, 2, '加入椒盐粉，搅匀，待到出胶质了分次加入葱姜水，放入冰箱腌制 20 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501444, 300181, 3, '制作炸糊。放入 80 g 面粉，20 g 淀粉（注意是 20 g 淀粉，剩下 60 g 备用），2 - 3 g 吉士粉，盐 1 g。', NULL);
INSERT INTO `recipe_step` VALUES (501445, 300181, 4, '打入一个鸡蛋，搅拌，再分次加入水 100 g ，再加 10 g 油，反复搅拌。直到炸糊完全调开，略粘稠即可。', NULL);
INSERT INTO `recipe_step` VALUES (501446, 300181, 5, '取出剩余的 60 g 淀粉，取出排条，裹上一层淀粉，再裹上面糊。', NULL);
INSERT INTO `recipe_step` VALUES (501447, 300181, 6, '锅中加入油，能没过食材即可，加热到大约 150 ℃ - 160 ℃ 。下入排条炸成浅金黄色后捞出。刚下入排条时可能会有粘连，不要动。待排条定型后可用筷子翻动，即可分开。', NULL);
INSERT INTO `recipe_step` VALUES (501448, 300181, 7, '待油温再次升高到 150 ℃ - 160 ℃ 时，下入排条复炸至金黄色后捞出。', NULL);
INSERT INTO `recipe_step` VALUES (501449, 300181, 8, '撒上椒盐粉，搅拌均匀后出锅。', NULL);
INSERT INTO `recipe_step` VALUES (501450, 300182, 1, '玉米粒都是剥好的，直接解冻即可，温水泡 15 分钟或者灶上开水煮 5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501451, 300182, 2, '拿出一个簸箕，将其假设为 BoxA，垫上吸油纸，倒进解冻好的玉米粒。', NULL);
INSERT INTO `recipe_step` VALUES (501452, 300182, 3, 'shaking shaking shaking! - 直到吸油纸全部变湿为止。', NULL);
INSERT INTO `recipe_step` VALUES (501453, 300182, 4, '拿出第二个簸箕 BoxB，垫上吸油纸，将 BoxA 的玉米粒全部倒入 BoxB 中。', NULL);
INSERT INTO `recipe_step` VALUES (501454, 300182, 5, 'shaking shaking shaking! - 直到吸油纸全部变湿为止。', NULL);
INSERT INTO `recipe_step` VALUES (501455, 300182, 6, '重复上述操作多次，直到玉米表面没有明显可见的水滴但保持湿润的状态。', NULL);
INSERT INTO `recipe_step` VALUES (501456, 300182, 7, '倒入大量淀粉，能够完全盖住玉米粒。', NULL);
INSERT INTO `recipe_step` VALUES (501457, 300182, 8, 'shaking shaking shaking! - 直到淀粉裹住了玉米粒', NULL);
INSERT INTO `recipe_step` VALUES (501458, 300182, 9, '开灶 - 放锅 - 倒入油 尽量铺满锅底 但不要太多。', NULL);
INSERT INTO `recipe_step` VALUES (501459, 300182, 10, '油热 8 成，倒入裹上了淀粉的玉米粒。', NULL);
INSERT INTO `recipe_step` VALUES (501460, 300182, 11, '中火先煎 30s，不要翻炒，不然淀粉会掉。', NULL);
INSERT INTO `recipe_step` VALUES (501461, 300182, 12, '轻微翻炒 3 分钟即可出锅。', NULL);
INSERT INTO `recipe_step` VALUES (501462, 300182, 13, '最重要的一步：撒上 3g 椒盐，撒上芝麻粒！', NULL);
INSERT INTO `recipe_step` VALUES (501463, 300182, 14, '香喷喷的”椒盐玉米“就做好了', NULL);
INSERT INTO `recipe_step` VALUES (501464, 300183, 1, '将四季豆洗净，并把筋撕干净，然后切成大小均匀的颗粒备用。', NULL);
INSERT INTO `recipe_step` VALUES (501465, 300183, 2, '将大蒜拍碎剁成蒜末备用。', NULL);
INSERT INTO `recipe_step` VALUES (501466, 300183, 3, '将小米辣切成大小均匀的颗粒备用。', NULL);
INSERT INTO `recipe_step` VALUES (501467, 300183, 4, '将五花肉去皮，然后剁成肉末备用。', NULL);
INSERT INTO `recipe_step` VALUES (501468, 300183, 5, '将锅烧热，然后加入 20ml 油滑锅，锅滑好之后将热油倒出，然后加入 10ml 冷油，这就是传说中热锅冷油，这么做主要是防止肉末粘锅。', NULL);
INSERT INTO `recipe_step` VALUES (501469, 300183, 6, '如果家里没有晾油瓶的话，也可以不用滑锅，放入油之后，直接加入肉末开始煸炒，小火煸炒两分钟，炒出猪油。', NULL);
INSERT INTO `recipe_step` VALUES (501470, 300183, 7, '肉末炒香之后加入蒜末，橄榄菜和小米辣，炒出香味。', NULL);
INSERT INTO `recipe_step` VALUES (501471, 300183, 8, '加入四季豆开中火煸炒，四季豆至少要炒 5 分钟，一定要保证四季豆熟透，否则可能会食物中毒。', NULL);
INSERT INTO `recipe_step` VALUES (501472, 300183, 9, '四季豆炒熟后加入 2ml 酱油从锅边淋入，然后加入 2g 盐、1g 鸡精、1g 胡椒粉和 0.5g 糖。', NULL);
INSERT INTO `recipe_step` VALUES (501473, 300183, 10, '将调料翻炒均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501474, 300183, 11, '出锅，装盘。', NULL);
INSERT INTO `recipe_step` VALUES (501475, 300184, 1, '锅中混合 130g 菜籽油和 40g 熟猪油，烧至油温 180℃；', NULL);
INSERT INTO `recipe_step` VALUES (501476, 300184, 2, '倒入 1500g 鸡块，煸炒至鸡肉表面泛黄；', NULL);
INSERT INTO `recipe_step` VALUES (501477, 300184, 3, '鸡肉中加入 60g 蒜子、60g 姜片、50g 剁椒翻炒;', NULL);
INSERT INTO `recipe_step` VALUES (501478, 300184, 4, '炒香后放入 150g 毛豆烧鸡料炒至鸡块上色；', NULL);
INSERT INTO `recipe_step` VALUES (501479, 300184, 5, '加入 120g 皮冻、280g 水一起烧开；', NULL);
INSERT INTO `recipe_step` VALUES (501480, 300184, 6, '倒入 750g 豆米烧制 3 分钟后大火收汁，出锅前加入 30g 葱段翻拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501481, 300185, 1, '洗净蔬菜', NULL);
INSERT INTO `recipe_step` VALUES (501482, 300185, 2, '锅中加入 150ml 水，并烧开。（水不需要能完全没过蔬菜）', NULL);
INSERT INTO `recipe_step` VALUES (501483, 300185, 3, '加入 3g 盐', NULL);
INSERT INTO `recipe_step` VALUES (501484, 300185, 4, '（可选）加入 3ml 蚝油', NULL);
INSERT INTO `recipe_step` VALUES (501485, 300185, 5, '加入 2ml 食用油', NULL);
INSERT INTO `recipe_step` VALUES (501486, 300185, 6, '下菜， 翻拌一下，然后盖上锅盖焖 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501487, 300185, 7, '盛盘', NULL);
INSERT INTO `recipe_step` VALUES (501488, 300186, 1, '牛肉洗干净切片。', NULL);
INSERT INTO `recipe_step` VALUES (501489, 300186, 2, '加入 15g 姜丝，1 个鸡蛋，15g 淀粉，8g 蚝油，10ml 料酒搅拌均匀，腌制 15 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501490, 300186, 3, '香菜洗干净切好。', NULL);
INSERT INTO `recipe_step` VALUES (501491, 300186, 4, '锅里倒油，加入豆瓣酱，5g 姜丝，蒜片。', NULL);
INSERT INTO `recipe_step` VALUES (501492, 300186, 5, '倒入开水，煮成红汤。', NULL);
INSERT INTO `recipe_step` VALUES (501493, 300186, 6, '豆芽洗干净去掉尾须，放进开水里焯熟。', NULL);
INSERT INTO `recipe_step` VALUES (501494, 300186, 7, '将豆芽铺入碗底。', NULL);
INSERT INTO `recipe_step` VALUES (501495, 300186, 8, '将牛肉片一片一片的放进红汤中，煮熟以后捞出。', NULL);
INSERT INTO `recipe_step` VALUES (501496, 300186, 9, '将牛肉铺在豆芽上，撒上香菜梗。', NULL);
INSERT INTO `recipe_step` VALUES (501497, 300186, 10, '撒上香菜叶，辣椒粉，辣椒圈。', NULL);
INSERT INTO `recipe_step` VALUES (501498, 300186, 11, '另起锅烧热油，将热油淋在菜上面，就完成了。', NULL);
INSERT INTO `recipe_step` VALUES (501499, 300187, 1, '将新鲜玉米剥去外皮，剩部分玉米皮入锅', NULL);
INSERT INTO `recipe_step` VALUES (501500, 300187, 2, '加入淹过玉米约半节指头的水，加盐和糖', NULL);
INSERT INTO `recipe_step` VALUES (501501, 300187, 3, '水煮开之后转至小火，加盖继续煮 15-20 分钟，玉米煮久点没事。', NULL);
INSERT INTO `recipe_step` VALUES (501502, 300187, 4, '煮熟后沥干水分，冷却后食用。', NULL);
INSERT INTO `recipe_step` VALUES (501503, 300188, 1, '里脊肉改刀成小块，再切成 2 毫米薄片（可根据自己的口感改进），放入碗中，加入清水清洗两遍来去除血水和杂质，捞出挤干水分备用。', NULL);
INSERT INTO `recipe_step` VALUES (501504, 300188, 2, '碗中加入食用盐 1.5g，胡椒粉 1g，生抽酱油 5g，料酒 3g，然后朝着一个方向搅拌 2 分钟，使其入味。', NULL);
INSERT INTO `recipe_step` VALUES (501505, 300188, 3, '另外准备一个碗，加入一个鸡蛋清，加入 7g 土豆淀粉，一个方向搅拌均匀，倒入肉中 再次一个方向搅拌均匀（肉表面就形成了润滑膜，这样会使肉更加鲜嫩） 最后再加入 30g 植物油轻轻搅拌（防止肉片粘连）。', NULL);
INSERT INTO `recipe_step` VALUES (501506, 300188, 4, '绿豆芽 100g，凤尾 1 根（改刀成小条），芹菜 3 根切成小段，蒜苗 2 根拍散切成小段。', NULL);
INSERT INTO `recipe_step` VALUES (501507, 300188, 5, '大蒜 20g 剁碎，生姜小块剁碎，红泡椒 20g 剁碎。', NULL);
INSERT INTO `recipe_step` VALUES (501508, 300188, 6, '小米辣干辣椒 15g，青花椒 3g，锅内加入油滑锅，油稍许热了将多余的倒出备用留 50g 底油，下入干辣椒、花椒，开小火炒香，切记不要炒糊（颜色要变黑即可），倒出在菜板上剁细。', NULL);
INSERT INTO `recipe_step` VALUES (501509, 300188, 7, '锅烧热，放入 100g 植物油烧至 6 成热，加入 2g 青花椒、干辣椒爆香，配菜下锅，加入 1g 食用盐，炒至断生，盛入碗中垫底备用。', NULL);
INSERT INTO `recipe_step` VALUES (501510, 300188, 8, '锅洗干净，加入 150g 植物油烧至 6 成热，加入制作好的姜蒜红泡椒，爆香后加入豆瓣 10g，开小火把豆瓣爆香炒出红油即可。', NULL);
INSERT INTO `recipe_step` VALUES (501511, 300188, 9, '加入 800 毫升清水（根据实际情况选择），大火烧开，转小火调味，加入食用盐 2.5g，鸡精 1.5g，1g 白砂糖提鲜，1g 胡椒粉，5g 水淀粉（根据实际情况选择）将汤汁收浓稠一点。', NULL);
INSERT INTO `recipe_step` VALUES (501512, 300188, 10, '汤汁开后，开小火将腌制好的肉片分开依次下锅，然后开中火将肉片烫熟，用锅铲轻轻推动一下避免粘连，待汤汁烧开，肉片熟后捞出放入碗中配菜上，再将原汤倒入（不超过菜品）。', NULL);
INSERT INTO `recipe_step` VALUES (501513, 300188, 11, '碗中均匀撒上刀口辣椒、蒜蓉和葱花。', NULL);
INSERT INTO `recipe_step` VALUES (501514, 300188, 12, '锅洗干净，加入 200g 菜籽油，烧至 7 成热，然后一次性均匀泼在碗中肉片上（注意安全），美味完成。', NULL);
INSERT INTO `recipe_step` VALUES (501515, 300189, 1, '蒸柜上汽后，蒸制 8 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501516, 300190, 1, '准备：巴沙鱼若是从冷冻柜里取出，需要放室温自然解冻 5 小时再做切片处理。', NULL);
INSERT INTO `recipe_step` VALUES (501517, 300190, 2, '切片：巴沙鱼撇成薄片，约 5cm 长，3cm 宽。', NULL);
INSERT INTO `recipe_step` VALUES (501518, 300190, 3, '腌制：将切好片的巴沙鱼放入大不锈钢碗中', NULL);
INSERT INTO `recipe_step` VALUES (501519, 300190, 4, '加入 30g 豆瓣酱，3g 盐，10ml 藤椒油，3g 白胡椒粉', NULL);
INSERT INTO `recipe_step` VALUES (501520, 300190, 5, '用手抓匀后加入 5ml 菜籽油收尾封住口味', NULL);
INSERT INTO `recipe_step` VALUES (501521, 300190, 6, '常温静置至少 30 分钟入味。', NULL);
INSERT INTO `recipe_step` VALUES (501522, 300190, 7, '备菜：大蒜切成蒜末。以 300g 花菜，200g 生菜为例，将花菜与生菜洗净。', NULL);
INSERT INTO `recipe_step` VALUES (501523, 300190, 8, '焯水与炒菜：花菜开水锅焯水备用；将生菜洗净晾干，炒熟备用（不用放油）。', NULL);
INSERT INTO `recipe_step` VALUES (501524, 300190, 9, '炒豆瓣酱：热锅冷油（菜籽油 20ml），加入 10g 豆瓣酱，10g 豆豉（可选），加入蒜末，中火慢炒。', NULL);
INSERT INTO `recipe_step` VALUES (501525, 300190, 10, '汆鱼片：加入 150ml 热水，水很快开后加入腌制好的鱼片，轻轻翻动让鱼片在水中散开，加入 2g 盐和 2g 糖调味（此时可根据个人口味调整盐的用量）。水再次沸腾后即可盛盘。', NULL);
INSERT INTO `recipe_step` VALUES (501526, 300190, 11, '盛盘：先将熟的蔬菜盛至大碗中，然后将热的鱼片盛在蔬菜上面，浇上锅中剩余热汤即可！', NULL);
INSERT INTO `recipe_step` VALUES (501527, 300191, 1, '先将菜类材料切成边长不超过 4cm 的块状，便于煮熟', NULL);
INSERT INTO `recipe_step` VALUES (501528, 300191, 2, '如有生肉，则先放入冷水中，盖上锅盖，煮沸腾，先捞出上层血沫，再关火，捞出半熟的肉备用', NULL);
INSERT INTO `recipe_step` VALUES (501529, 300191, 3, '先大火将水加热至沸腾，后调至中火', NULL);
INSERT INTO `recipe_step` VALUES (501530, 300191, 4, '将较难煮熟的食材放入锅中（比如半熟肉类、香菇类、等最先放入锅中）。为保证煮熟，可在沸腾后计时 10 分钟，特别难熟的大块食材可追加 5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501531, 300191, 5, '将面食放入锅中，适当搅拌确保面和汤充分接触，使液面保持轻微沸腾，煮 5 分钟。加入面后液面易产生白色泡沫，可适当抬起锅盖通气或者撤下锅盖。', NULL);
INSERT INTO `recipe_step` VALUES (501532, 300191, 6, '将易于煮熟的食材如青菜类放入锅中，适当搅拌以充分浸没，煮 2-5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501533, 300191, 7, '关火，随后加入盐、胡椒粉、香油等自己喜欢的调味料，适当搅拌即可出锅食用', NULL);
INSERT INTO `recipe_step` VALUES (501534, 300192, 1, '【第一次蒸】起锅加 7 成水，水开，上蒸篦子', NULL);
INSERT INTO `recipe_step` VALUES (501535, 300192, 2, '【第一次蒸】将挂面，均匀铺开放置，淋 5ml 油并抹匀，蒸 15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501536, 300192, 3, '【第一次蒸】将挂面和蒸篦子取出，放置一边，并倒掉锅中的水', NULL);
INSERT INTO `recipe_step` VALUES (501537, 300192, 4, '【切菜】五花肉，切成 2mm 厚度的肉片', NULL);
INSERT INTO `recipe_step` VALUES (501538, 300192, 5, '【切菜】蒜薹，切成 3cm 段', NULL);
INSERT INTO `recipe_step` VALUES (501539, 300192, 6, '【切菜】葱，切成 0.2cm 薄片', NULL);
INSERT INTO `recipe_step` VALUES (501540, 300192, 7, '【切菜】姜，切成 1mm x 1mm x 3cm 的细丝', NULL);
INSERT INTO `recipe_step` VALUES (501541, 300192, 8, '【切菜】蒜，放在砧板上拍碎，切成 1mm 的粒度', NULL);
INSERT INTO `recipe_step` VALUES (501542, 300192, 9, '【炒制】起锅，烧干水分，加 3ml 食用油', NULL);
INSERT INTO `recipe_step` VALUES (501543, 300192, 10, '【炒制】手持锅柄，摇晃锅，使食用油充分挂满锅的 2/3', NULL);
INSERT INTO `recipe_step` VALUES (501544, 300192, 11, '【炒制】中火，加入肉片，翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501545, 300192, 12, '【炒制】加入葱姜蒜，料酒，继续翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501546, 300192, 13, '【炒制】将蒜薹段，放入锅中，翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501547, 300192, 14, '【炒制】开始调味，加入老抽、生抽、蚝油、盐、鸡精、十三香，翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501548, 300192, 15, '【炒制】加入 500ML 水，没过蔬菜，炖煮 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501549, 300192, 16, '【炒制】将蒸好的挂面放入，不断搅拌 3 分钟，待挂面全部均匀上色，关火', NULL);
INSERT INTO `recipe_step` VALUES (501550, 300192, 17, '【炒制】将搅拌好的挂面和菜，全部倒入额外的盆中', NULL);
INSERT INTO `recipe_step` VALUES (501551, 300192, 18, '【第二次蒸】起锅，加冷水 7 成，放上蒸篦子，将拌好的面条和菜，均匀的铺在上面', NULL);
INSERT INTO `recipe_step` VALUES (501552, 300192, 19, '【第二次蒸】水开后，大火烧 15 分钟，出锅', NULL);
INSERT INTO `recipe_step` VALUES (501553, 300192, 20, '【第二次蒸】淋上 10g 的麻油，即可食用', NULL);
INSERT INTO `recipe_step` VALUES (501554, 300193, 1, '拿出蒜头掰 2 个小蒜头去皮', NULL);
INSERT INTO `recipe_step` VALUES (501555, 300193, 2, '拿出砧板剁碎小蒜头、小米椒', NULL);
INSERT INTO `recipe_step` VALUES (501556, 300193, 3, '拿出碗倒入花生油', NULL);
INSERT INTO `recipe_step` VALUES (501557, 300193, 4, '油热放入其他配料和小葱,等到香料变焦，捞出扔掉', NULL);
INSERT INTO `recipe_step` VALUES (501558, 300193, 5, '拿出铁锅将碗内的油放入加热 2 分钟（菜籽油烧至冒烟）', NULL);
INSERT INTO `recipe_step` VALUES (501559, 300193, 6, '此时是空碗', NULL);
INSERT INTO `recipe_step` VALUES (501560, 300193, 7, '往空碗加入干辣椒面、白芝麻、蒜末、小米椒、盐、五香粉、草寇作为\"调料\"', NULL);
INSERT INTO `recipe_step` VALUES (501561, 300193, 8, '关火将油温冷却至 210 摄氏度', NULL);
INSERT INTO `recipe_step` VALUES (501562, 300193, 9, '将锅内热油倒入碗内并用勺子搅拌即可（可以在 165 摄氏度时加入同样\"调料\"的碗最后进行混合进行增辣）', NULL);
INSERT INTO `recipe_step` VALUES (501563, 300193, 10, '倒入热油稍微搅拌后放入白醋，此时会重新沸腾。继续进行搅拌，白醋增香。', NULL);
INSERT INTO `recipe_step` VALUES (501564, 300193, 11, '油泼辣子冷却到温热放白糖和味精，白糖可以使辣味柔和，不会那么地呛口', NULL);
INSERT INTO `recipe_step` VALUES (501565, 300194, 1, '下入 100g 鸡油、80g 熟猪油、60g 蒜子、60g 生姜、7g 干红椒，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (501566, 300194, 2, '下入 200g 油渣，翻炒均匀；', NULL);
INSERT INTO `recipe_step` VALUES (501567, 300194, 3, '下入 300g 水、5g 盐、1 袋炒菜基料、2200g 大白菜，炖烧入味出品。', NULL);
INSERT INTO `recipe_step` VALUES (501568, 300195, 1, '剪虾枪到根上，虾须虾爪都剪掉，沙包挑掉，开背虾线挑出来，洗净备用', NULL);
INSERT INTO `recipe_step` VALUES (501569, 300195, 2, '炸料油 油温三成热放花椒，油热离火，放葱姜（不要让油变色最好）葱稍微变黄沥油 （葱油弄多了可以留着作为拌面使用）。', NULL);
INSERT INTO `recipe_step` VALUES (501570, 300195, 3, '下油，虾摆放整齐，两面变色后轻轻摁虾头 放姜米（姜切成细颗粒） 黄酒 30g 水两小碗 盐 3g 冰糖 10 克', NULL);
INSERT INTO `recipe_step` VALUES (501571, 300195, 4, '大火烧开转小火盖盖子闷（中途不能再加汤水，不要开盖）', NULL);
INSERT INTO `recipe_step` VALUES (501572, 300195, 5, '皮亮虾弯就可以起锅，虾摆盘', NULL);
INSERT INTO `recipe_step` VALUES (501573, 300195, 6, '收汁（过滤后倒回锅里收浓，放葱油 ） 汤汁剩余 1/4 时。', NULL);
INSERT INTO `recipe_step` VALUES (501574, 300195, 7, '浇汁', NULL);
INSERT INTO `recipe_step` VALUES (501575, 300195, 8, '完成', NULL);
INSERT INTO `recipe_step` VALUES (501576, 300195, 9, '开吃✅', NULL);
INSERT INTO `recipe_step` VALUES (501577, 300196, 1, '面粉盛小碗里，加入盐', NULL);
INSERT INTO `recipe_step` VALUES (501578, 300196, 2, '加入 200 度的热油', NULL);
INSERT INTO `recipe_step` VALUES (501579, 300196, 3, '用筷子将其搅拌成无固状物体的糊状。', NULL);
INSERT INTO `recipe_step` VALUES (501580, 300197, 1, '鸡蛋不需打散，直接打入碗中备用', NULL);
INSERT INTO `recipe_step` VALUES (501581, 300197, 2, '香葱切 3cm 长小段即可', NULL);
INSERT INTO `recipe_step` VALUES (501582, 300197, 3, '蒜瓣和小米辣放入打蒜器，打成沫', NULL);
INSERT INTO `recipe_step` VALUES (501583, 300197, 4, '将香醋、生抽、蚝油、白糖、水加入小碗，搅拌均匀作为糖醋料汁', NULL);
INSERT INTO `recipe_step` VALUES (501584, 300197, 5, '油热倒入鸡蛋，等鸡蛋凝固之后铲成大块，倒入蒜沫、小米辣沫、倒入糖醋料汁', NULL);
INSERT INTO `recipe_step` VALUES (501585, 300197, 6, '大火收汁、快出锅时加入葱段即可', NULL);
INSERT INTO `recipe_step` VALUES (501586, 300198, 1, '起锅烧油，依次爆香蒜姜、泡椒酱、泡红椒，再下入鸡肝、鸡肫、调味料，加水烧开后转中火收浓汤汁，最后下香葱翻匀出锅；', NULL);
INSERT INTO `recipe_step` VALUES (501587, 300198, 2, '水烧开，将1 包手擀面放入面篓中并用筷子搅散，煮制约2 分钟；同时下入青菜，烫制20 秒；', NULL);
INSERT INTO `recipe_step` VALUES (501588, 300198, 3, '面碗中放入250g 老鸡汤、100g 泡椒鸡杂（汤汁）、煮好的面条，再加入120g 泡椒鸡杂（固形物）、20g 青菜、半个茶叶蛋，出品。', NULL);
INSERT INTO `recipe_step` VALUES (501589, 300199, 1, '600cc 水大火烧开', NULL);
INSERT INTO `recipe_step` VALUES (501590, 300199, 2, '在过滤袋中装入 20g 茶粉，开水倒入过滤袋中，过滤 20 遍', NULL);
INSERT INTO `recipe_step` VALUES (501591, 300199, 3, '使用克称量取 24g 炼乳、24g 白糖和 18ml 牛奶放入 1000ml 以上的水壶中', NULL);
INSERT INTO `recipe_step` VALUES (501592, 300199, 4, '将过滤好的茶水倒入水壶中搅拌，直到白糖融化', NULL);
INSERT INTO `recipe_step` VALUES (501593, 300199, 5, '将水壶放到冰箱 4 小时以上', NULL);
INSERT INTO `recipe_step` VALUES (501594, 300199, 6, '喝前可以加 6-8 颗冰块', NULL);
INSERT INTO `recipe_step` VALUES (501595, 300200, 1, '洋葱切片，猪肉，蒜头拍碎，以及混合上述调味料备用', NULL);
INSERT INTO `recipe_step` VALUES (501596, 300200, 2, '炒锅内倒入 1 大匙食用油（等待 10 秒让油温升高），倒入猪肉', NULL);
INSERT INTO `recipe_step` VALUES (501597, 300200, 3, '炒至变色后下蒜头炒香盛起备用', NULL);
INSERT INTO `recipe_step` VALUES (501598, 300200, 4, '原锅下洋葱翻炒 3~4 分钟后加入调味料炒匀', NULL);
INSERT INTO `recipe_step` VALUES (501599, 300200, 5, '下刚盛起备用的猪肉翻炒至猪肉熟后', NULL);
INSERT INTO `recipe_step` VALUES (501600, 300200, 6, '待猪肉熟后再翻炒 1、2 分钟即可起锅', NULL);
INSERT INTO `recipe_step` VALUES (501601, 300201, 1, '鸡蛋打入大碗中，加入洋葱片、盐后搅拌 60 S', NULL);
INSERT INTO `recipe_step` VALUES (501602, 300201, 2, '起锅烧油，倒入鸡蛋，一面煎炸 30-45 S ，翻面继续翻炒，反复 2-3 分钟 后散上料酒出锅', NULL);
INSERT INTO `recipe_step` VALUES (501603, 300201, 3, '鸡蛋装盘，散上葱花', NULL);
INSERT INTO `recipe_step` VALUES (501604, 300202, 1, '蒸柜上汽后，蒸制 30 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501605, 300203, 1, '取170g 西兰花，在沸水中汆烫60 秒；', NULL);
INSERT INTO `recipe_step` VALUES (501606, 300203, 2, '2. 将烫好的西兰花放入餐具中，淋上30g 豉油汁出品。', NULL);
INSERT INTO `recipe_step` VALUES (501607, 300204, 1, '10 份汤底调制：1000g 开水中加入50g 汤料，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (501608, 300204, 2, '老鸡汤熬制：', NULL);
INSERT INTO `recipe_step` VALUES (501609, 300204, 3, '鸡块制作：', NULL);
INSERT INTO `recipe_step` VALUES (501610, 300204, 4, '将130g 鲜面、1 份鸡块、25g 青菜在沸水中煮2 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (501611, 300204, 5, '舀取200g 老鸡汤、100g 汤底于面碗中，放入煮好的面条和配菜，撒上5g 葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (501612, 300205, 1, '在不锈钢桶中放入6500g水和500g卤料，大火烧开后，捞出料渣，备用；', NULL);
INSERT INTO `recipe_step` VALUES (501613, 300205, 2, '将海带扣放入卤汤中，大火烧开后转小火卤30分钟；', NULL);
INSERT INTO `recipe_step` VALUES (501614, 300206, 1, '柠檬洗净切出一片', NULL);
INSERT INTO `recipe_step` VALUES (501615, 300206, 2, '选择一个杯子，建议使用容量在 350~400 毫升的透明玻璃杯', NULL);
INSERT INTO `recipe_step` VALUES (501616, 300206, 3, '放入大冰块，用搅拌棒搅拌冰杯', NULL);
INSERT INTO `recipe_step` VALUES (501617, 300206, 4, '加入红石榴糖浆', NULL);
INSERT INTO `recipe_step` VALUES (501618, 300206, 5, '让橙汁沿搅拌棒导入酒杯，到就被一半就行', NULL);
INSERT INTO `recipe_step` VALUES (501619, 300206, 6, '轻轻搅拌半圈', NULL);
INSERT INTO `recipe_step` VALUES (501620, 300206, 7, '倒入苏打水', NULL);
INSERT INTO `recipe_step` VALUES (501621, 300206, 8, '拿出调酒杯，加入白朗姆 + 蓝橙力娇酒 + 柠檬汁 + 冰块。然后 shake，shake', NULL);
INSERT INTO `recipe_step` VALUES (501622, 300206, 9, '轻轻倒入酒杯中', NULL);
INSERT INTO `recipe_step` VALUES (501623, 300206, 10, '插上柠檬和吸管', NULL);
INSERT INTO `recipe_step` VALUES (501624, 300207, 1, '五花肉切成厚度不超过 2cm 长的块，并串成串。（五花肉可以预先腌制一下，味道更佳）', NULL);
INSERT INTO `recipe_step` VALUES (501625, 300207, 2, '大葱切成 5cm 长的葱段，备用', NULL);
INSERT INTO `recipe_step` VALUES (501626, 300207, 3, '芝麻酱加 10ml 温水调稀，与甜面酱混合均匀，备用（可以换成\"芝麻盐\"）', NULL);
INSERT INTO `recipe_step` VALUES (501627, 300207, 4, '点燃炭火，等待炭火烧至通红无明火状态（约 15 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (501628, 300207, 5, '将五花肉串均匀摆在在烤网上，烤至底面焦黄出油后翻面', NULL);
INSERT INTO `recipe_step` VALUES (501629, 300207, 6, '继续烤制约 2 - 3 分钟，至两面焦黄、边缘微焦后取下', NULL);
INSERT INTO `recipe_step` VALUES (501630, 300207, 7, '取一张小薄面饼平铺，抹上 3 - 4g 混合酱料', NULL);
INSERT INTO `recipe_step` VALUES (501631, 300207, 8, '放上烤好的肉片和 1 - 2 段大葱，卷起即可食用', NULL);
INSERT INTO `recipe_step` VALUES (501632, 300208, 1, '下入 50g 大豆油、100g 熟猪油、70g 蒜子，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (501633, 300208, 2, '下入 1700g 春菜、12g 盐、12g 鸡精、4g 白砂糖、100g水，大火爆炒断生出品。', NULL);
INSERT INTO `recipe_step` VALUES (501634, 300209, 1, '下入 30g 大豆油、30g 熟猪油、50g 蒜子，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (501635, 300209, 2, '下入 1300g 毛白菜、10g 盐、6g 鸡精、3g 白砂糖，大火爆炒至断生；', NULL);
INSERT INTO `recipe_step` VALUES (501636, 300209, 3, '最后下入 30g 大豆油、30g 熟猪油，翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (501637, 300210, 1, '下入 100g 大豆油、50g 熟猪油、1300g 油麦菜、15g 盐、10g 鸡精', NULL);
INSERT INTO `recipe_step` VALUES (501638, 300210, 2, '大火爆炒 2 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (501639, 300211, 1, '将 花菜 洗净，用刀或手掰成小朵，粗茎部分可以切片，备用。', NULL);
INSERT INTO `recipe_step` VALUES (501640, 300211, 2, '将 大蒜 去皮，切成蒜片，备用。', NULL);
INSERT INTO `recipe_step` VALUES (501641, 300211, 3, '锅中加入 1000 ml 饮用水，大火烧开。', NULL);
INSERT INTO `recipe_step` VALUES (501642, 300211, 4, '放入 花菜 朵，煮 2-3 分钟，至花菜颜色变浅，口感稍微软化。', NULL);
INSERT INTO `recipe_step` VALUES (501643, 300211, 5, '将 煮好的 花菜 捞出，沥干水分，备用。', NULL);
INSERT INTO `recipe_step` VALUES (501644, 300211, 6, '热锅，加入 15 ml 食用油，大火烧热。', NULL);
INSERT INTO `recipe_step` VALUES (501645, 300211, 7, '放入 蒜片，快速煸炒出香味。', NULL);
INSERT INTO `recipe_step` VALUES (501646, 300211, 8, '放入 焯好水的 花菜 朵，转中大火，快速翻炒约 2 分钟，使花菜均匀受热。', NULL);
INSERT INTO `recipe_step` VALUES (501647, 300211, 9, '加入 3 g 盐，继续翻炒均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501648, 300211, 10, '沿锅边淋入 50 ml 饮用水，盖上锅盖，焖 1 分钟，帮助花菜完全熟透入味。', NULL);
INSERT INTO `recipe_step` VALUES (501649, 300211, 11, '开盖，快速翻炒均匀，即可出锅。', NULL);
INSERT INTO `recipe_step` VALUES (501650, 300212, 1, '锅中下入 70g 大豆油、40g 熟猪油、30g 蒜子、20g 鲜红小米辣，煸炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (501651, 300212, 2, '下入 1800g 莴笋、18g 蒸鱼豉油、9g 鸡精、9g 盐、2g 白砂糖，大火爆炒 3 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (501652, 300213, 1, '锅中倒入 100g 大豆油、30g 熟猪油、30g 蒜子，爆出香味', NULL);
INSERT INTO `recipe_step` VALUES (501653, 300213, 2, '下入 1400g 菜心、3g 鸡精、1g 白砂糖、9g 盐，大火爆炒 3 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (501654, 300214, 1, '下入 150g 大豆油、60g 蒜子，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (501655, 300214, 2, '下入 2000g 西兰花、15g 盐、10g 鸡精，大火爆炒 1 分 30 秒出品。', NULL);
INSERT INTO `recipe_step` VALUES (501656, 300215, 1, '锅中下入 100g 大豆油、40g 熟猪油、1300g 青菜、12g 盐、6g鸡精、3g 白砂糖', NULL);
INSERT INTO `recipe_step` VALUES (501657, 300215, 2, '大火爆炒 2 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (501658, 300216, 1, '将 南瓜 外皮洗净，去除瓜瓤和籽。', NULL);
INSERT INTO `recipe_step` VALUES (501659, 300216, 2, '将 南瓜 切成厚度大约 2 cm 的片，备用。', NULL);
INSERT INTO `recipe_step` VALUES (501660, 300216, 3, '在 蒸锅 的锅中加入 1000 ml 饮用水。', NULL);
INSERT INTO `recipe_step` VALUES (501661, 300216, 4, '将切好的 南瓜 片均匀摆放在盘中。', NULL);
INSERT INTO `recipe_step` VALUES (501662, 300216, 5, '待蒸锅中的水烧开后，将装有 南瓜 的盘子放入蒸锅中。', NULL);
INSERT INTO `recipe_step` VALUES (501663, 300216, 6, '盖上锅盖，保持大火蒸 15-20 分钟，直至南瓜变软，可以用筷子轻松穿透。', NULL);
INSERT INTO `recipe_step` VALUES (501664, 300216, 7, '关火，小心取出盘子。', NULL);
INSERT INTO `recipe_step` VALUES (501665, 300217, 1, '将生蚝用刷子刷干净（没有刷子用牙刷）。', NULL);
INSERT INTO `recipe_step` VALUES (501666, 300217, 2, '蒸锅中放水，将蒸屉放上之后，将 6 个生蚝平铺在蒸屉，使用 50%功率，蒸 3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501667, 300217, 3, '用右手拿着湿抹布掀开烫锅盖，将每个生蚝的外壳掀开一半去掉，生蚝的凸面向下，平面向上，每个放 1 根姜丝,10g 蒜末放到生蚝上。', NULL);
INSERT INTO `recipe_step` VALUES (501668, 300217, 4, '关上烫锅盖，100%功率蒸 3.5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501669, 300217, 5, '停火，用右手拿着抹布掀开烫锅盖，每个放 5ml 酱油。', NULL);
INSERT INTO `recipe_step` VALUES (501670, 300217, 6, '盛盘。', NULL);
INSERT INTO `recipe_step` VALUES (501671, 300218, 1, '姜切片切丝、香葱的葱白切段，葱绿切丝，切丝后放入冷水浸泡备用。', NULL);
INSERT INTO `recipe_step` VALUES (501672, 300218, 2, '鲈鱼处理好后洗净，用厨房纸擦干，两面分别划几刀，用盐洗掉鱼身的粘液，并用 10g 盐抹遍鱼身的内外，腌制 10 分钟以上。', NULL);
INSERT INTO `recipe_step` VALUES (501673, 300218, 3, '补充一个鲈鱼改刀和摆盘的方法，改刀后可以让鲈鱼立起来蒸，均匀受热，同时吃起来更加方便，无需翻面。', NULL);
INSERT INTO `recipe_step` VALUES (501674, 300218, 4, '鱼肚内塞上姜和葱白，鱼身也撒上姜和葱白，量为备用的一半。蒸鱼的碟子用筷子将鱼跟碟子隔开蒸', NULL);
INSERT INTO `recipe_step` VALUES (501675, 300218, 5, '水烧热感觉到水温后放进入鱼', NULL);
INSERT INTO `recipe_step` VALUES (501676, 300218, 6, '大火清蒸 10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501677, 300218, 7, '蒸好的鱼，用干净的盘子装起来并去除身上姜蒜', NULL);
INSERT INTO `recipe_step` VALUES (501678, 300218, 8, '鱼身浇上 15ml 蒸鱼豉油', NULL);
INSERT INTO `recipe_step` VALUES (501679, 300218, 9, '鱼身重新撒上姜和葱丝，锅内加上 10ml 食用油并烧热，将食用油淋至鱼身即可出菜', NULL);
INSERT INTO `recipe_step` VALUES (501680, 300219, 1, '食材处理： 鳜鱼从腹部切开，去除鱼鳃和内脏，打去鱼鳞，用到在表皮上刮去粘液（这一步也可让热心摊主处理） 鳜鱼身上打上花刀，放姜片，有条件的可以放点猪油，装盘在下面垫一个筷子，便于蒸制时受热均匀 大葱划开后去除中间的芯，只保留外面两层 小葱划开备用 红椒去除辣椒籽和里层辣椒肉备用 将准备好的大葱、小葱、辣椒码在一起，切成丝泡在水里备用', NULL);
INSERT INTO `recipe_step` VALUES (501681, 300219, 2, '炒制过程： 锅里加水，水量大一些，水热后放入鳜鱼，盖上锅盖，大火蒸制 8 - 10 分钟，蒸鱼四字窍门：汽大火足 蒸鱼过程，另起一个过热油，油需要烧到冒烟 蒸制结束后，倒掉蒸鱼的水，去除姜片，放上葱丝，浇上热油 在倒入生抽或蒸鱼豉油即可上桌', NULL);
INSERT INTO `recipe_step` VALUES (501682, 300220, 1, '【煮蛋】在锅中盛装一定量自来水，确保水面没过约鸡蛋 3cm，水中插入温度计', NULL);
INSERT INTO `recipe_step` VALUES (501683, 300220, 2, '【煮蛋】开火或打开电磁炉，逐渐调整电磁炉功率或火苗大小，使得水温保持在 70 摄氏度', NULL);
INSERT INTO `recipe_step` VALUES (501684, 300220, 3, '【煮蛋】将鸡蛋放入锅中。鸡蛋不可互相堆叠，应皆在底部，并留有空间可以晃动', NULL);
INSERT INTO `recipe_step` VALUES (501685, 300220, 4, '【煮蛋】保持当前温度 25 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501686, 300220, 5, '【煮蛋】准备一杯冰水', NULL);
INSERT INTO `recipe_step` VALUES (501687, 300220, 6, '【煮蛋】捞出鸡蛋，并立刻放入冰水中，等待 3 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501688, 300220, 7, '【煮蛋】将鸡蛋打入小碗，完成制作', NULL);
INSERT INTO `recipe_step` VALUES (501689, 300221, 1, '带皮五花肉洗净冷水下锅，加入姜片 2~3 片去腥味，煮到沸腾捞出冷水冲净白沫', NULL);
INSERT INTO `recipe_step` VALUES (501690, 300221, 2, '五花肉切块，尺寸 1.5cm1.5cm 块状大小', NULL);
INSERT INTO `recipe_step` VALUES (501691, 300221, 3, '热锅加入油，加入冰糖小火搅拌至焦糖色即可，加入切好的五花肉，中火翻炒上色', NULL);
INSERT INTO `recipe_step` VALUES (501692, 300221, 4, '加入备好的姜片、八角、桂皮、生抽、老抽、料酒、干小米椒、盐，小火翻炒 1 分钟，加开水没过肉', NULL);
INSERT INTO `recipe_step` VALUES (501693, 300221, 5, '加盖中火煮沸，转小火慢顿 30 分钟，慢炖期间，间隔 10 分钟搅拌一次防止粘锅', NULL);
INSERT INTO `recipe_step` VALUES (501694, 300221, 6, '小火慢炖汤汁剩三分之一的时，调成中火收汁出锅。', NULL);
INSERT INTO `recipe_step` VALUES (501695, 300222, 1, '将糯米粉、粘米粉、蒸肉粉、细辣椒粉、5 克盐、白胡椒粉倒一起搅匀', NULL);
INSERT INTO `recipe_step` VALUES (501696, 300222, 2, '鸭子让热心摊主剁成蒸煮块，姜切片，蒜子剥皮，五花肉切片即可', NULL);
INSERT INTO `recipe_step` VALUES (501697, 300222, 3, '热锅凉油煸炒五花肉出油，再加食用油烧热，下入鸭子煸炒', NULL);
INSERT INTO `recipe_step` VALUES (501698, 300222, 4, '鸭子煸炒到表皮焦变色，下入姜蒜和盐继续煸炒香味', NULL);
INSERT INTO `recipe_step` VALUES (501699, 300222, 5, '关小火倒入米粉翻炒，鸭肉均匀裹满米粉子，加入开水，少量多次的加，边加边翻炒', NULL);
INSERT INTO `recipe_step` VALUES (501700, 300222, 6, '翻炒鸭肉和米粉有湿感，铲出入碗中，高压锅放水蒸 20-25 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501701, 300222, 7, '出锅前撒点葱花即可享用了', NULL);
INSERT INTO `recipe_step` VALUES (501702, 300223, 1, '将鸡蛋放入电锅中。鸡蛋不可互相堆叠，应皆在底部，并留有空间可以晃动', NULL);
INSERT INTO `recipe_step` VALUES (501703, 300223, 2, '倒入淹过鸡蛋约 2 公分的冷水', NULL);
INSERT INTO `recipe_step` VALUES (501704, 300223, 3, '开盖，使用最大功率加热至水滚起（大约 85 - 95 度，稍微滚动，不需完全沸腾）', NULL);
INSERT INTO `recipe_step` VALUES (501705, 300223, 4, '关火，盖上盖子，让鸡蛋静置。 想要中央有流动的蛋黄，需静置 6 分钟 若想要完全煮熟的易碎蛋黄，需静置 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501706, 300223, 5, '沥干水分，用冷水冲洗鸡蛋约 1 分钟，即可去壳食用。', NULL);
INSERT INTO `recipe_step` VALUES (501707, 300224, 1, '将 200g 牛肉末放入碗中，加入 1 汤匙生抽、半汤匙白糖和 2g 黑胡椒，搅拌均匀，等待腌制 10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501708, 300224, 2, '将半个洋葱切成小丁，备用。', NULL);
INSERT INTO `recipe_step` VALUES (501709, 300224, 3, '调制料汁：在碗中加入 2 汤匙生抽、2 汤匙番茄酱、1 汤匙料酒、1 汤匙淀粉、半汤匙老抽和 50ml 清水，搅拌均匀备用。', NULL);
INSERT INTO `recipe_step` VALUES (501710, 300224, 4, '另起一锅，制作一个水波蛋或半熟煎蛋，备用。', NULL);
INSERT INTO `recipe_step` VALUES (501711, 300224, 5, '热锅，放入 10g 黄油。待黄油融化后，放入洋葱丁，小火煎熟至散发香味。', NULL);
INSERT INTO `recipe_step` VALUES (501712, 300224, 6, '加入腌制好的牛肉末，与洋葱一起翻炒至牛肉变色。', NULL);
INSERT INTO `recipe_step` VALUES (501713, 300224, 7, '倒入调好的料汁，撒上 2g 黑胡椒，继续炒制直至汤汁变粘稠后关火。', NULL);
INSERT INTO `recipe_step` VALUES (501714, 300224, 8, '将炒好的免治牛肉浇在热米饭上，放上提前准备好的水波蛋或半熟煎蛋。', NULL);
INSERT INTO `recipe_step` VALUES (501715, 300224, 9, '（可选）表面撒上 5g 切好的小葱花作装饰。', NULL);
INSERT INTO `recipe_step` VALUES (501716, 300225, 1, '将米饭和水放到电饭锅里，点击米饭模式，等待完成', NULL);
INSERT INTO `recipe_step` VALUES (501717, 300225, 2, '冷冻玉米粒和青豆放到锅里，加水没过所有食材，沸腾后静待 2 分钟后，捞出。', NULL);
INSERT INTO `recipe_step` VALUES (501718, 300225, 3, '火腿切成 1cm 的方块', NULL);
INSERT INTO `recipe_step` VALUES (501719, 300225, 4, '与此同时，加入 10ml 食用油，加入火腿翻炒至火腿上色', NULL);
INSERT INTO `recipe_step` VALUES (501720, 300225, 5, '将米饭，火腿，海苔碎，青豆，玉米粒，沙拉酱放入碗中，混合均匀即可', NULL);
INSERT INTO `recipe_step` VALUES (501721, 300225, 6, '装盘（如果有的话）', NULL);
INSERT INTO `recipe_step` VALUES (501722, 300226, 1, '凉粉改刀切麻将块大小', NULL);
INSERT INTO `recipe_step` VALUES (501723, 300226, 2, '开小火，起锅烧油，锅烧微热后，下入蒜末爆香后加入豆瓣酱炒出红油', NULL);
INSERT INTO `recipe_step` VALUES (501724, 300226, 3, '将凉粉块下入锅中，翻炒 10 秒', NULL);
INSERT INTO `recipe_step` VALUES (501725, 300226, 4, '加入生抽提味，老抽上色，翻炒均匀后加入辣椒面继续翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (501726, 300226, 5, '加入食盐、十三香继续翻炒 10 秒', NULL);
INSERT INTO `recipe_step` VALUES (501727, 300226, 6, '加入准备好的矿泉水，再次翻炒 10 秒，待汤汁浓稠后，关火出锅装盘', NULL);
INSERT INTO `recipe_step` VALUES (501728, 300226, 7, '撒上葱花即可完成', NULL);
INSERT INTO `recipe_step` VALUES (501729, 300227, 1, '锅中加水烧开，煮熟年糕，碗中加水确保年糕不会粘连，捞起年糕备用。', NULL);
INSERT INTO `recipe_step` VALUES (501730, 300227, 2, '小葱切葱花（将葱白和葱叶分开），青菜切小段备用。', NULL);
INSERT INTO `recipe_step` VALUES (501731, 300227, 3, '（可选） 制作炒蛋，见西红柿炒蛋。', NULL);
INSERT INTO `recipe_step` VALUES (501732, 300227, 4, '热锅，加入 30ml 食用油。', NULL);
INSERT INTO `recipe_step` VALUES (501733, 300227, 5, '将葱白倒入锅中，直至大部分葱白变成焦黄色且发出香味，倒出葱油备用。', NULL);
INSERT INTO `recipe_step` VALUES (501734, 300227, 6, '重新热锅，加入 20ml 食用油。', NULL);
INSERT INTO `recipe_step` VALUES (501735, 300227, 7, '加入所有辅料（鸡蛋，青菜等），翻炒均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501736, 300227, 8, '将年糕的水倒掉，向锅中加入年糕。', NULL);
INSERT INTO `recipe_step` VALUES (501737, 300227, 9, '加入酱油和盐，翻炒均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501738, 300227, 10, '关火，加入葱油，翻炒均匀，乘盘。', NULL);
INSERT INTO `recipe_step` VALUES (501739, 300228, 1, '加入 250 克水 / 人', NULL);
INSERT INTO `recipe_step` VALUES (501740, 300228, 2, '待水烧开，下入面条，中火煮 15 - 20 分钟（这个面通常比较硬，捞起来之前最好尝一下，中心如果有一点硬，需要继续煮）', NULL);
INSERT INTO `recipe_step` VALUES (501741, 300228, 3, '捞出面条，盛入盘中备用', NULL);
INSERT INTO `recipe_step` VALUES (501742, 300228, 4, '热锅倒入食用油，待油温中热，下入面条翻炒一分钟（如果太干，加入少量水）', NULL);
INSERT INTO `recipe_step` VALUES (501743, 300228, 5, '放入 10 克番茄酱、肥牛、加入 2g 食盐，继续翻炒一分钟', NULL);
INSERT INTO `recipe_step` VALUES (501744, 300228, 6, '起锅', NULL);
INSERT INTO `recipe_step` VALUES (501745, 300229, 1, '【火腿肠预处理】将火腿肠撕开包装，切成宽度 1cm 的小块。', NULL);
INSERT INTO `recipe_step` VALUES (501746, 300229, 2, '【面的处理】向煮锅中加入 1200 ml 水，实际以没过面饼为准。完全煮沸，不要在未沸腾时加面。', NULL);
INSERT INTO `recipe_step` VALUES (501747, 300229, 3, '【面的处理】加入方便面面饼，煮 45 秒。煮的过程中将其挑动，把面条打散。', NULL);
INSERT INTO `recipe_step` VALUES (501748, 300229, 4, '【面的处理】面条打散后立刻关火。不要煮熟！', NULL);
INSERT INTO `recipe_step` VALUES (501749, 300229, 5, '【面的处理】从锅中舀出 80ml 热面汤备用。', NULL);
INSERT INTO `recipe_step` VALUES (501750, 300229, 6, '【面的处理】将面汤和面分离。用凉水冲一下面条。', NULL);
INSERT INTO `recipe_step` VALUES (501751, 300229, 7, '【面的处理】沥干面条上的水分。不要长时间将面泡在水中。', NULL);
INSERT INTO `recipe_step` VALUES (501752, 300229, 8, '【酱料处理】准备一个小碗，将方便面的调料包挤进去。 挤进去所有菜包 挤进去所有酱包 挤进去 50% - 80% 的粉包。（全部粉包都挤进去会很咸）', NULL);
INSERT INTO `recipe_step` VALUES (501753, 300229, 9, '【酱料处理】将上一步的 80ml 热面汤全部倒入小碗，搅匀，得到调料碗。', NULL);
INSERT INTO `recipe_step` VALUES (501754, 300229, 10, '【鸡蛋的预处理】取出计算好的数量的鸡蛋，打入一个小碗。不要加盐！（鸡蛋最终会混合锅里食材的盐味）', NULL);
INSERT INTO `recipe_step` VALUES (501755, 300229, 11, '【鸡蛋的预处理】热锅 20s，加入份数 8ml 油。', NULL);
INSERT INTO `recipe_step` VALUES (501756, 300229, 12, '【鸡蛋的预处理】加入刚刚准备好的一碗鸡蛋。翻炒大约 20s 至鸡蛋形成固态即可。', NULL);
INSERT INTO `recipe_step` VALUES (501757, 300229, 13, '【鸡蛋的预处理】将煎鸡蛋取出暂存。不需要洗锅。但一般锅内不会残余太多油。', NULL);
INSERT INTO `recipe_step` VALUES (501758, 300229, 14, '【最终步骤】重新热锅 20s，向锅内加入油：份数 10ml。', NULL);
INSERT INTO `recipe_step` VALUES (501759, 300229, 15, '【最终步骤】加入第一步处理的火腿肠。翻炒 10 秒。', NULL);
INSERT INTO `recipe_step` VALUES (501760, 300229, 16, '【最终步骤】加入第二步的面。翻炒 30 秒。', NULL);
INSERT INTO `recipe_step` VALUES (501761, 300229, 17, '【最终步骤】加入第三步的调料碗。翻炒 30 秒。', NULL);
INSERT INTO `recipe_step` VALUES (501762, 300229, 18, '【最终步骤】加入第四步的煎鸡蛋。翻炒 30 秒。', NULL);
INSERT INTO `recipe_step` VALUES (501763, 300229, 19, '【最终步骤】关火盛盘即可。', NULL);
INSERT INTO `recipe_step` VALUES (501764, 300230, 1, '【准备工作】小葱切碎（葱白和葱叶分开）、蒜瓣拍碎，丢案板上备用。', NULL);
INSERT INTO `recipe_step` VALUES (501765, 300230, 2, '【准备工作】打碎鸡蛋，捞一点蛋清到一只碗中，剩下的丢入另一只碗中备用。', NULL);
INSERT INTO `recipe_step` VALUES (501766, 300230, 3, '【准备工作】将绿豆芽放入锅中，大火煮 60 秒。豆芽捞出，过凉水，放入盘中备用。', NULL);
INSERT INTO `recipe_step` VALUES (501767, 300230, 4, '【准备工作】黄瓜切丝放入盘中备用，可和豆芽丢一起。', NULL);
INSERT INTO `recipe_step` VALUES (501768, 300230, 5, '【准备工作】处理面筋，单独丢一个盘中。', NULL);
INSERT INTO `recipe_step` VALUES (501769, 300230, 6, '【准备工作】肉切细条状，加入淀粉与刚刚碗中的鸡蛋清、胡椒粉，顺时针拌匀。', NULL);
INSERT INTO `recipe_step` VALUES (501770, 300230, 7, '【准备工作】注：超市购买来的凉皮表面一般会有食用油，可以使用自来水清洗。面筋同样。', NULL);
INSERT INTO `recipe_step` VALUES (501771, 300230, 8, '【准备工作】注：清洗面筋之后，请用手将面筋中的大量水分挤出（不需过于用力）。', NULL);
INSERT INTO `recipe_step` VALUES (501772, 300230, 9, '【热锅炒肉】加入食用油，锅热倒出。', NULL);
INSERT INTO `recipe_step` VALUES (501773, 300230, 10, '【热锅炒肉】倒入处理好的肉，翻炒均匀至变色，倒入碗中备用。', NULL);
INSERT INTO `recipe_step` VALUES (501774, 300230, 11, '【炒制河粉】趁锅热，加入 20g 食用油（高血压人群可降低用量），倒入葱白、蒜爆炒出香。', NULL);
INSERT INTO `recipe_step` VALUES (501775, 300230, 12, '【炒制河粉】加入河粉，淋入老抽提色，翻炒均匀后再加入河粉炒料，继续翻炒。', NULL);
INSERT INTO `recipe_step` VALUES (501776, 300230, 13, '【炒制河粉】河粉即将透明时，放入炒制好的肉丝与面筋，并加入生抽提鲜，简单翻炒两次。', NULL);
INSERT INTO `recipe_step` VALUES (501777, 300230, 14, '【炒制河粉】加入豆芽与黄瓜丝，翻炒至河粉完全透明。', NULL);
INSERT INTO `recipe_step` VALUES (501778, 300230, 15, '【炒制河粉】关火！', NULL);
INSERT INTO `recipe_step` VALUES (501779, 300230, 16, '【最终步骤】撒入葱叶点缀，把锅端起。', NULL);
INSERT INTO `recipe_step` VALUES (501780, 300230, 17, '【最终步骤】倒入盘中，开始干饭。', NULL);
INSERT INTO `recipe_step` VALUES (501781, 300231, 1, '鸡蛋加入牛奶以及 5ml 食用油搅拌均匀，备用', NULL);
INSERT INTO `recipe_step` VALUES (501782, 300231, 2, '大火烧热平底锅约 30s, 加入 5ml 食用油', NULL);
INSERT INTO `recipe_step` VALUES (501783, 300231, 3, '烧 30s 转小火, 并且放入搅拌好的鸡蛋', NULL);
INSERT INTO `recipe_step` VALUES (501784, 300231, 4, '在锅中静置 5 秒后，用锅铲将蛋液从边缘缓慢推向中间', NULL);
INSERT INTO `recipe_step` VALUES (501785, 300231, 5, '翻炒至鸡蛋大致凝固后关火，装盘', NULL);
INSERT INTO `recipe_step` VALUES (501786, 300232, 1, '将茄子洗净，一刀分为两段（竖切）。每段的茄子切菱形块，将切好的茄子放入碗中待命。', NULL);
INSERT INTO `recipe_step` VALUES (501787, 300232, 2, '将香葱洗净，并切成葱花放到案板上待命。', NULL);
INSERT INTO `recipe_step` VALUES (501788, 300232, 3, '切好八角，放到案板上待命。', NULL);
INSERT INTO `recipe_step` VALUES (501789, 300232, 4, '如果打算放肉末，先用 10 ml（如果是纯瘦肉，用 15 ml）油中火炒至变色（约 1 分钟），然后盛出备用。', NULL);
INSERT INTO `recipe_step` VALUES (501790, 300232, 5, '开火热锅，直至锅内没有水。', NULL);
INSERT INTO `recipe_step` VALUES (501791, 300232, 6, '往锅内倒食用油，没过锅底的两倍（油可以多加，但不可少加）。', NULL);
INSERT INTO `recipe_step` VALUES (501792, 300232, 7, '热油约 6 成熟，放入八角、虾皮、香葱这三种可选性材料。', NULL);
INSERT INTO `recipe_step` VALUES (501793, 300232, 8, '如果没有八角等可选材料，热油至 9 成熟。', NULL);
INSERT INTO `recipe_step` VALUES (501794, 300232, 9, '待锅内的油到 9 成熟，将碗中的茄子倒入锅内用锅铲进行翻炒。', NULL);
INSERT INTO `recipe_step` VALUES (501795, 300232, 10, '翻炒约 40 秒，将锅铲悬空，与锅平行，把酱油倒入锅铲内。一人约 2.5 锅铲（酱油可以少加，但不可多加，会咸）。', NULL);
INSERT INTO `recipe_step` VALUES (501796, 300232, 11, '茄子炒到半软时（约 1 分钟后），放回预炒的肉末，快速搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501797, 300232, 12, '如果打算加入糖和醋，加入糖和醋。', NULL);
INSERT INTO `recipe_step` VALUES (501798, 300232, 13, '继续进行翻炒。', NULL);
INSERT INTO `recipe_step` VALUES (501799, 300232, 14, '等到锅内所有茄子变色且变软时捞出。', NULL);
INSERT INTO `recipe_step` VALUES (501800, 300233, 1, '青菜掰成小瓣，用清水洗净，备用。', NULL);
INSERT INTO `recipe_step` VALUES (501801, 300233, 2, '将蒜瓣剁碎，备用', NULL);
INSERT INTO `recipe_step` VALUES (501802, 300233, 3, '中火或大火热锅后，锅内放入 10-15ml 食用油。再等待 30 秒让油温升高。', NULL);
INSERT INTO `recipe_step` VALUES (501803, 300233, 4, '将准备好的青菜倒入锅中，翻炒至青菜变软（约 1 分钟）。', NULL);
INSERT INTO `recipe_step` VALUES (501804, 300233, 5, '放入剁碎的蒜瓣', NULL);
INSERT INTO `recipe_step` VALUES (501805, 300233, 6, '倒入计算好的清水，水位应当完全浸润或即将没过青菜，加入食盐 （2g 份数），继续翻炒约 1 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501806, 300233, 7, '最后加入白糖小火加热 2 分钟，加热时盖上锅盖。', NULL);
INSERT INTO `recipe_step` VALUES (501807, 300233, 8, '盛盘。', NULL);
INSERT INTO `recipe_step` VALUES (501808, 300234, 1, '将馒头切成小块或小片。', NULL);
INSERT INTO `recipe_step` VALUES (501809, 300234, 2, '选有鸡蛋的话将鸡蛋打进碗里，打散（可加盐和五香粉各 1g 或不加，等炒的过程中加）。', NULL);
INSERT INTO `recipe_step` VALUES (501810, 300234, 3, '鸡蛋浇在馒头上，拌匀，鸡蛋不宜过多。', NULL);
INSERT INTO `recipe_step` VALUES (501811, 300234, 4, '大火热锅，倒入食用油（不锈钢锅怕伤锅的话可以先倒油，烧至油热也可也可）', NULL);
INSERT INTO `recipe_step` VALUES (501812, 300234, 5, '将馍丁放进去翻炒，翻炒均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501813, 300234, 6, '将火调小，炒至馍丁呈金黄色。', NULL);
INSERT INTO `recipe_step` VALUES (501814, 300234, 7, '放入盐，胡椒粉，五香粉。', NULL);
INSERT INTO `recipe_step` VALUES (501815, 300234, 8, '最后将葱花放入一起翻炒几下。', NULL);
INSERT INTO `recipe_step` VALUES (501816, 300234, 9, '关火出锅。', NULL);
INSERT INTO `recipe_step` VALUES (501817, 300235, 1, '所有原料在容器内混合，搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501818, 300235, 2, '锅里烧热油，油的用量以在容器内没过所有原材料为佳。', NULL);
INSERT INTO `recipe_step` VALUES (501819, 300235, 3, '分三次淋入热油，每次 1/3，同时搅拌。', NULL);
INSERT INTO `recipe_step` VALUES (501820, 300235, 4, '最后放入香油 10ml，生抽 10ml，花椒油 10ml，蚝油 10ml。', NULL);
INSERT INTO `recipe_step` VALUES (501821, 300236, 1, '预处理：用剪刀将肉肠交叉剪6-7下，呈现开花状态；', NULL);
INSERT INTO `recipe_step` VALUES (501822, 300236, 2, '炸制：油温升至170℃，放入肉肠炸3分30秒至肉肠浮起。', NULL);
INSERT INTO `recipe_step` VALUES (501823, 300237, 1, '【开封薯条】开封大分量半成品薯条注意开口要小，可以有效减少长久储藏下薯条表面结霜。', NULL);
INSERT INTO `recipe_step` VALUES (501824, 300237, 2, '【预热空气炸锅】插电，200℃预热 5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501825, 300237, 3, '【预热空气炸锅】预热的目的是为了确保放入食材的时候锅内温度已经处于烹饪所需温度。', NULL);
INSERT INTO `recipe_step` VALUES (501826, 300237, 4, '【预热空气炸锅】注意，预热完再拿出薯条，不应等薯条软化后再炸制。', NULL);
INSERT INTO `recipe_step` VALUES (501827, 300237, 5, '【炸薯条】取出薯条放入空气炸锅，200℃20 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501828, 300237, 6, '【炸薯条】取出薯条的时候注意半成品薯条已经有油，所以要异步去做客户端内刀斯林的话需要使用夹持工具。', NULL);
INSERT INTO `recipe_step` VALUES (501829, 300237, 7, '【炸薯条】5~10 分钟时可以拿出锅体晃动使薯条受热均匀也防止粘连。', NULL);
INSERT INTO `recipe_step` VALUES (501830, 300237, 8, '【脆化（可选项）】10 分钟~15 分钟时，拿出锅体，往已经干了的薯条表面喷 1 层面积为薯条表面积 2/3 的油。', NULL);
INSERT INTO `recipe_step` VALUES (501831, 300237, 9, '【取出&装盘】喜欢脆薯条的，取出后拿着锅体跳舞让空气经过薯条表面后装盘；喜欢软薯条的直接装盘。配合蘸酱或浇上酱汁更佳。', NULL);
INSERT INTO `recipe_step` VALUES (501832, 300238, 1, '菜码切丝备用。', NULL);
INSERT INTO `recipe_step` VALUES (501833, 300238, 2, '葱切碎。油锅烧热，下葱和肉，炒至肉完全熟透（无红色）', NULL);
INSERT INTO `recipe_step` VALUES (501834, 300238, 3, '下豆瓣酱和甜面酱，继续炒至微微粘稠。盛出，得到炸酱。', NULL);
INSERT INTO `recipe_step` VALUES (501835, 300238, 4, '取大碗，加凉水备用。', NULL);
INSERT INTO `recipe_step` VALUES (501836, 300238, 5, '煮面条至断生（无白芯），盛入第 4 步装有凉水的碗中。', NULL);
INSERT INTO `recipe_step` VALUES (501837, 300238, 6, '立即控水捞出，盛入干净的碗中。', NULL);
INSERT INTO `recipe_step` VALUES (501838, 300238, 7, '取第 3 步炸酱，倒入碗中，拌匀。然后取第 1 步菜码，倒入碗中，拌匀。', NULL);
INSERT INTO `recipe_step` VALUES (501839, 300239, 1, '从牛奶中取出 80ml，与玉米淀粉混合，搅拌至没有可见颗粒', NULL);
INSERT INTO `recipe_step` VALUES (501840, 300239, 2, '将剩余的 170ml 牛奶和白糖倒入锅中，小火加热并持续搅拌，直至白糖完全溶解', NULL);
INSERT INTO `recipe_step` VALUES (501841, 300239, 3, '再次搅匀玉米淀粉液，将其缓慢倒入锅中，同时持续搅拌', NULL);
INSERT INTO `recipe_step` VALUES (501842, 300239, 4, '保持小火加热并不断搅拌约 3 - 5 分钟，直至奶糊浓稠，刮过锅底后留下的纹路能保持 3 秒不消失', NULL);
INSERT INTO `recipe_step` VALUES (501843, 300239, 5, '在耐热容器内壁均匀涂抹约 2ml 食用油，倒入奶糊并将表面抹平，使奶糊厚度约为 2cm', NULL);
INSERT INTO `recipe_step` VALUES (501844, 300239, 6, '奶糊冷却至室温后盖好，放入冰箱冷藏至少 2 小时；轻按表面不粘手且整体不会流动时即可取出', NULL);
INSERT INTO `recipe_step` VALUES (501845, 300239, 7, '将定型后的奶糊脱模，切成约 6cm × 2cm × 2cm 的长条，共约 12 条', NULL);
INSERT INTO `recipe_step` VALUES (501846, 300239, 8, '将面粉、打散的鸡蛋液和面包糠分别放入 3 个容器', NULL);
INSERT INTO `recipe_step` VALUES (501847, 300239, 9, '每块奶条依次均匀裹上面粉、鸡蛋液和面包糠，确保各面都被覆盖', NULL);
INSERT INTO `recipe_step` VALUES (501848, 300239, 10, '锅中倒入 700ml 食用油，中火加热至 165 - 175℃；没有温度计时，可放入少量面包糠测试，面包糠应在 2 秒内浮起并持续冒出小气泡', NULL);
INSERT INTO `recipe_step` VALUES (501849, 300239, 11, '将奶条分 2 - 3 批放入油中，每批炸约 60 - 90 秒；期间翻动 1 - 2 次，使各面受热均匀', NULL);
INSERT INTO `recipe_step` VALUES (501850, 300239, 12, '奶条表面呈均匀金黄色时捞出，放在厨房纸上沥油约 2 分钟后食用', NULL);
INSERT INTO `recipe_step` VALUES (501851, 300240, 1, '雪花鸡排无需解冻直接放入170℃的油锅中炸制8 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501852, 300241, 1, '鸡排放入170℃的油锅中炸制8分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501853, 300242, 1, '裹粉：将鸡排均匀裹上面包糠；', NULL);
INSERT INTO `recipe_step` VALUES (501854, 300242, 2, '炸制：油温升至170℃，放入鸡排炸2分30秒至鸡排浮起。', NULL);
INSERT INTO `recipe_step` VALUES (501855, 300243, 1, '解冻后的鸡腿放入170℃油中，炸制7 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501856, 300244, 1, '110g 意面放入沸水烫制1 分钟，捞起倒入圆盘餐具中心位置；', NULL);
INSERT INTO `recipe_step` VALUES (501857, 300244, 2, '将30g 蒸制后的番茄肉酱淋在意面上；', NULL);
INSERT INTO `recipe_step` VALUES (501858, 300244, 3, '取餐厅炸制后的鸡腿1 个、烫制后的西兰花2 颗（30g）、熟玉米1 块（40-45g）、熟南瓜1 块（25-30g）均匀摆放在餐具上，摆盘出品。', NULL);
INSERT INTO `recipe_step` VALUES (501859, 300245, 1, '将 400g 面粉倒入盆中，一半用凉水和面，一半用热水和面，搅拌成面絮，用手揉成团。用保鲜膜封起来，醒面 40 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501860, 300245, 2, '离醒面完成时间还有 10 分钟时，请查看小技巧中的油酥做法（热油酥效果更好）', NULL);
INSERT INTO `recipe_step` VALUES (501861, 300245, 3, '醒好的面不用揉，稍微摁一下，用一横刀一竖刀将其分成四份。', NULL);
INSERT INTO `recipe_step` VALUES (501862, 300245, 4, '搓圆，擀开，擀成与电饼铛大小差不多的饼，取 1/4 的油酥，将饼表面涂抹均匀', NULL);
INSERT INTO `recipe_step` VALUES (501863, 300245, 5, '沿饼的半径切开，从外圈将其卷成圆锥形，然后将圆锥尾部捏好，防止油酥外漏。', NULL);
INSERT INTO `recipe_step` VALUES (501864, 300245, 6, '按压面饼圆锥尖的地方，将其压扁，然后再次擀成与电饼铛大小差不多的面饼（厚度约为 3mm）', NULL);
INSERT INTO `recipe_step` VALUES (501865, 300245, 7, '将电饼铛预热，涂上凉油（热锅凉油），将擀好的饼放入电饼铛中，将饼的上方也刷点油，涂抹均匀（锁住水分），盖上盖子', NULL);
INSERT INTO `recipe_step` VALUES (501866, 300245, 8, '大火烙一分钟，打开盖子，将饼翻个面再烙一分钟', NULL);
INSERT INTO `recipe_step` VALUES (501867, 300245, 9, '重复以上动作，完成饼的烙制', NULL);
INSERT INTO `recipe_step` VALUES (501868, 300246, 1, '奶油奶酪软化，微波炉 10s + 10s。', NULL);
INSERT INTO `recipe_step` VALUES (501869, 300246, 2, '奶油奶酪加入白砂糖，打蛋器打至顺滑。', NULL);
INSERT INTO `recipe_step` VALUES (501870, 300246, 3, '加入 2 个全蛋 + 1 个蛋黄，搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501871, 300246, 4, '加入淡奶油，搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501872, 300246, 5, '加入低筋面粉，搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501873, 300246, 6, '烤箱 220°(425°F)，20 - 25 分钟（本人一般 20 或者 22 分钟）。', NULL);
INSERT INTO `recipe_step` VALUES (501874, 300246, 7, '放凉之后放入冰箱，最好过夜。', NULL);
INSERT INTO `recipe_step` VALUES (501875, 300247, 1, '解冻后的烤肠放入120℃烤肠机中烤20 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501876, 300248, 1, '将酱油、孜然、食用盐、蒜蓉和切碎的小米椒置于碗中，均匀搅拌备用', NULL);
INSERT INTO `recipe_step` VALUES (501877, 300248, 2, '茄子洗净，用纸巾擦干表面的水分', NULL);
INSERT INTO `recipe_step` VALUES (501878, 300248, 3, '用叉子在茄子的一侧扎 4-8 下', NULL);
INSERT INTO `recipe_step` VALUES (501879, 300248, 4, '使用 15-25ml 的食用油涂满茄子表面', NULL);
INSERT INTO `recipe_step` VALUES (501880, 300248, 5, '将烤箱温度设置为 200℃ （打开烤箱风扇 大火），预热 2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501881, 300248, 6, '将茄子放入烤箱中层或者上层，烤制 12-15 分钟 （茄子表面有褶皱，且能按压 0.3-0.5cm 的深度即可）', NULL);
INSERT INTO `recipe_step` VALUES (501882, 300248, 7, '取出茄子，用刀茄子上竖着划一个口子。口子居中，上下距 1-1.5cm', NULL);
INSERT INTO `recipe_step` VALUES (501883, 300248, 8, '用小刀或者叉子伸入口子，竖着切割茄子内部', NULL);
INSERT INTO `recipe_step` VALUES (501884, 300248, 9, '将口子微微掰开，倒入第一步准备的酱料', NULL);
INSERT INTO `recipe_step` VALUES (501885, 300248, 10, '再次将茄子放入烤箱，将烤箱温度设置为 200℃ ，烤制 4-7 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501886, 300248, 11, '取出，关闭烤箱电源', NULL);
INSERT INTO `recipe_step` VALUES (501887, 300249, 1, '将碗置于克数称上 称量 450 克 淡奶油（淡奶油密度在此处记为 1 ）', NULL);
INSERT INTO `recipe_step` VALUES (501888, 300249, 2, '加入 80 克白砂糖 （甜度中等 可按个人口味增减 建议范围 60-100 克）', NULL);
INSERT INTO `recipe_step` VALUES (501889, 300249, 3, '加入 200 克牛奶 （牛奶密度在此处记为 1 ）', NULL);
INSERT INTO `recipe_step` VALUES (501890, 300249, 4, '取 8 个蛋黄加入 蛋清可留作他用', NULL);
INSERT INTO `recipe_step` VALUES (501891, 300249, 5, '均匀搅拌所有材料直至白砂糖全部融化', NULL);
INSERT INTO `recipe_step` VALUES (501892, 300249, 6, '使用网筛对搅拌完成的食材进行过滤 滤除鸡蛋黏膜 鸡蛋壳 未融化的白砂糖 结块的淡奶油', NULL);
INSERT INTO `recipe_step` VALUES (501893, 300249, 7, '此时请将烤箱设置 220 摄氏度开始预热（约 10 分钟） 记得拿出烤盘', NULL);
INSERT INTO `recipe_step` VALUES (501894, 300249, 8, '将蛋挞皮以 0.5 厘米的间隔均匀放置于烤盘中', NULL);
INSERT INTO `recipe_step` VALUES (501895, 300249, 9, '将过滤完成的食材倒入蛋挞皮中 液面距离蛋挞皮上沿 0.5 厘米即可不宜过多', NULL);
INSERT INTO `recipe_step` VALUES (501896, 300249, 10, '截止此步骤 半成品蛋挞的制作已经完成 可直接放入冰箱速冻 12 小时以上保存', NULL);
INSERT INTO `recipe_step` VALUES (501897, 300249, 11, '将半成品蛋挞放入烤箱中进行烤制 温度为 200 摄氏度 时间为 25 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501898, 300249, 12, '烤制结束后即可食用', NULL);
INSERT INTO `recipe_step` VALUES (501899, 300250, 1, '草鱼（一般 3 斤 ）从背部切开，两面沿着鱼的背部往下划几刀，不要划到鱼肚皮，不然不易定型 可以用热水浇在鱼身上洗去粘液或者用刷子在流动水龙头下面不停的刷洗，直到摸着没有黏糊糊的手感。', NULL);
INSERT INTO `recipe_step` VALUES (501900, 300250, 2, '把鱼放到容器中，加入料酒，10g 白胡椒粉，5g 食盐抹匀腌制二十分钟入味。', NULL);
INSERT INTO `recipe_step` VALUES (501901, 300250, 3, '把半根大葱切成一块一块，大蒜粒中间切开，和八角香叶桂皮放在一个容器中', NULL);
INSERT INTO `recipe_step` VALUES (501902, 300250, 4, '干辣椒段中间一分为二切开并和灯笼椒装在一个容器中', NULL);
INSERT INTO `recipe_step` VALUES (501903, 300250, 5, '芹菜切小段', NULL);
INSERT INTO `recipe_step` VALUES (501904, 300250, 6, '豆芽焯水', NULL);
INSERT INTO `recipe_step` VALUES (501905, 300250, 7, '千张焯水切成丝', NULL);
INSERT INTO `recipe_step` VALUES (501906, 300250, 8, '洋葱切成丝。', NULL);
INSERT INTO `recipe_step` VALUES (501907, 300250, 9, '烤制鱼 家里有烤箱的可以在烤盘刷上底油，鱼皮朝下，直到烤制两面金黄，然后撒上孜然粉 如果没有烤箱，可以热锅热油，锅的两边撒上 2g 食盐，下入草鱼开始煎，刚下入的时候不要着急翻动，等一面定型后再翻面，煎制两面金黄，撒上孜然粉，出锅装在盘子里准备。', NULL);
INSERT INTO `recipe_step` VALUES (501908, 300250, 10, '锅中撒上 20ml 食用油，等到油热后，把大葱大蒜八角香叶倒入炒香', NULL);
INSERT INTO `recipe_step` VALUES (501909, 300250, 11, '加上一包火锅底料的一半和 15-20g 豆瓣酱，炒出红油', NULL);
INSERT INTO `recipe_step` VALUES (501910, 300250, 12, '加入 5g 白糖，10g 食盐，5ml 生抽调味，倒入和食材齐平的清水煮开', NULL);
INSERT INTO `recipe_step` VALUES (501911, 300250, 13, '依次下入芹菜段，豆芽，千张丝，不用煮熟，稍微烫一下后铺上洋葱丝，放上烤鱼', NULL);
INSERT INTO `recipe_step` VALUES (501912, 300250, 14, '加入干辣椒，灯笼椒，青花椒', NULL);
INSERT INTO `recipe_step` VALUES (501913, 300250, 15, '另一个锅烧油，油热后浇在刚加入的辣椒上面激发出香味', NULL);
INSERT INTO `recipe_step` VALUES (501914, 300250, 16, '最后撒上熟花生米，葱花，白芝麻，香菜', NULL);
INSERT INTO `recipe_step` VALUES (501915, 300250, 17, '煮 5-6 分钟，美味即成。', NULL);
INSERT INTO `recipe_step` VALUES (501916, 300251, 1, '【鸡翅的预处理】鸡翅放入碗中', NULL);
INSERT INTO `recipe_step` VALUES (501917, 300251, 2, '【鸡翅的预处理】加盐、黑胡椒粉、酱油、料酒进行腌制 30-40 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501918, 300251, 3, '【烤制过程】将烤箱预热至 200℃', NULL);
INSERT INTO `recipe_step` VALUES (501919, 300251, 4, '【烤制过程】将腌制好的鸡翅均匀地放在烤盘上', NULL);
INSERT INTO `recipe_step` VALUES (501920, 300251, 5, '【烤制过程】将烤盘放入烤箱中层，烤 15-20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501921, 300251, 6, '【烤制过程】取出烤盘，将鸡翅翻面，再烤 15-20 分钟，直到熟透', NULL);
INSERT INTO `recipe_step` VALUES (501922, 300252, 1, '放入 1 包茶包（3g)，倒入 150ml 开水，盖上盖子闷泡 3 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (501923, 300252, 2, '捞出茶包 （茶包不可重复使用），倒入 150ml 生椰乳。', NULL);
INSERT INTO `recipe_step` VALUES (501924, 300253, 1, '水煮沸，并加入碱水面，焯烫 25 秒钟捞起', NULL);
INSERT INTO `recipe_step` VALUES (501925, 300253, 2, '撒上食盐、鸡精和胡椒粉', NULL);
INSERT INTO `recipe_step` VALUES (501926, 300253, 3, '芝麻酱用 90ml 水稀释，搅匀，然后加入', NULL);
INSERT INTO `recipe_step` VALUES (501927, 300253, 4, '加入 5ml 酱油，加入 30ml 肉汤汁和蒜水', NULL);
INSERT INTO `recipe_step` VALUES (501928, 300253, 5, '加入萝卜干，肉末，酸豆角，葱花', NULL);
INSERT INTO `recipe_step` VALUES (501929, 300253, 6, '拌均匀后开吃', NULL);
INSERT INTO `recipe_step` VALUES (501930, 300254, 1, '将羊排按照骨头分布，切成块状。', NULL);
INSERT INTO `recipe_step` VALUES (501931, 300254, 2, '炒锅中加入冷水，放入全部羊排块，水沸腾后继续焯水 2 - 3 分钟，捞出备用。', NULL);
INSERT INTO `recipe_step` VALUES (501932, 300254, 3, '将焯好水的羊排、桂皮、花椒、八角、白芷、香叶、料酒放入锅中（高压锅或普通锅）。', NULL);
INSERT INTO `recipe_step` VALUES (501933, 300254, 4, '加入饮用水没过所有食材。如果使用高压锅，上汽后压 30 分钟。如果使用普通锅，炖煮 80 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501934, 300254, 5, '将炖煮完成的羊排捞出，沥干水分，放入无油无水的炒锅 / 煎锅中。', NULL);
INSERT INTO `recipe_step` VALUES (501935, 300254, 6, '中大火煎 6 - 7 分钟，直至羊排中的油脂被煎出，表面呈金黄酥脆状态。', NULL);
INSERT INTO `recipe_step` VALUES (501936, 300254, 7, '锅中保留煎出的羊油，加入辣椒粉、孜然粒、烧烤撒料、孜然粉、白芝麻，翻炒均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501937, 300254, 8, '加入糖和盐（如果在炖煮步骤中未添加），翻炒均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501938, 300254, 9, '翻炒均匀后即可关火，盛盘。', NULL);
INSERT INTO `recipe_step` VALUES (501939, 300255, 1, '取出平底锅（不沾平底锅最佳）', NULL);
INSERT INTO `recipe_step` VALUES (501940, 300255, 2, '加入 10ml - 15 ml 食用油', NULL);
INSERT INTO `recipe_step` VALUES (501941, 300255, 3, '开火，放入饺子（尽量平均铺开，不宜堆叠）', NULL);
INSERT INTO `recipe_step` VALUES (501942, 300255, 4, '立刻加入清水，水线没过饺子平均高度的 1/2', NULL);
INSERT INTO `recipe_step` VALUES (501943, 300255, 5, '盖上锅盖（此时炉灶应该处于大火）', NULL);
INSERT INTO `recipe_step` VALUES (501944, 300255, 6, '等待 8 - 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501945, 300255, 7, '当锅中水分仅剩 2mm 时， 转中火开始煎制', NULL);
INSERT INTO `recipe_step` VALUES (501946, 300255, 8, '当水分全部蒸发后，摇晃平底锅使饺子受热均匀', NULL);
INSERT INTO `recipe_step` VALUES (501947, 300255, 9, '放入黑芝麻和葱花再焖 10s', NULL);
INSERT INTO `recipe_step` VALUES (501948, 300255, 10, '1 - 2 分钟夹出一个饺子观察底部，若出现金黄色脆皮立即取出', NULL);
INSERT INTO `recipe_step` VALUES (501949, 300256, 1, '取一只鸡腿，鸡皮朝下放在砧板上', NULL);
INSERT INTO `recipe_step` VALUES (501950, 300256, 2, '用刀尖沿着鸡腿骨头的轮廓轻轻划开，从一端到另一端', NULL);
INSERT INTO `recipe_step` VALUES (501951, 300256, 3, '用手指或刀背慢慢推开鸡肉，让骨头暴露出来。如果遇到筋膜，用刀尖切断', NULL);
INSERT INTO `recipe_step` VALUES (501952, 300256, 4, '当鸡肉完全分离后，握住骨头一端，轻轻扭转并拔出', NULL);
INSERT INTO `recipe_step` VALUES (501953, 300256, 5, '重复上述步骤将所有鸡腿去骨', NULL);
INSERT INTO `recipe_step` VALUES (501954, 300256, 6, '去骨鸡腿加入黑胡椒粉、黑胡椒碎、盐、姜片腌制 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501955, 300256, 7, '碗里加入料酒、生抽、蜂蜜、老抽清水拌匀', NULL);
INSERT INTO `recipe_step` VALUES (501956, 300256, 8, '蔬菜焯水 1-2 分钟煮熟捞起', NULL);
INSERT INTO `recipe_step` VALUES (501957, 300256, 9, '热锅放油 15 ml 放入拍碎的大蒜爆香', NULL);
INSERT INTO `recipe_step` VALUES (501958, 300256, 10, '放入鸡腿中小火煎至两面金黄，如果感觉锅中太干，补 5-10 ml 油', NULL);
INSERT INTO `recipe_step` VALUES (501959, 300256, 11, '加入调好的酱汁，盖好盖子中小火（在燃气灶上使用小火）焖 5-10 分钟熟透，酱汁浓稠起泡即可', NULL);
INSERT INTO `recipe_step` VALUES (501960, 300256, 12, '切件，和蔬菜一起摆在饭面，淋入煎鸡腿的酱汁就可以慢慢享用啦', NULL);
INSERT INTO `recipe_step` VALUES (501961, 300257, 1, '先将水加热至沸腾（火候不做严格要求，使用热水会更快）', NULL);
INSERT INTO `recipe_step` VALUES (501962, 300257, 2, '将取出的面饼放入锅中', NULL);
INSERT INTO `recipe_step` VALUES (501963, 300257, 3, '将泡面里附带的佐料放入锅中', NULL);
INSERT INTO `recipe_step` VALUES (501964, 300257, 4, '取出筷子轻微拨动泡面，使佐料充分溶解，面饼充分浸泡受热', NULL);
INSERT INTO `recipe_step` VALUES (501965, 300257, 5, '盖上锅盖等待约 1 分钟至锅内水再次沸腾', NULL);
INSERT INTO `recipe_step` VALUES (501966, 300257, 6, '去壳鸡蛋，加入锅中', NULL);
INSERT INTO `recipe_step` VALUES (501967, 300257, 7, '等待约 3 至 4 分钟，即可', NULL);
INSERT INTO `recipe_step` VALUES (501968, 300258, 1, '清洗大米', NULL);
INSERT INTO `recipe_step` VALUES (501969, 300258, 2, '将米和水加入煮锅', NULL);
INSERT INTO `recipe_step` VALUES (501970, 300258, 3, '大火煮至水沸腾', NULL);
INSERT INTO `recipe_step` VALUES (501971, 300258, 4, '搅拌底部防止粘黏', NULL);
INSERT INTO `recipe_step` VALUES (501972, 300258, 5, '盖上锅盖，转小火加热 10-15 分钟（根据对软糯程度的喜好），中途切勿打开锅盖', NULL);
INSERT INTO `recipe_step` VALUES (501973, 300258, 6, '关火，静置 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501974, 300258, 7, 'Enjoy :)', NULL);
INSERT INTO `recipe_step` VALUES (501975, 300259, 1, '将牛奶与干燕麦混合搅拌均匀至黏稠状。', NULL);
INSERT INTO `recipe_step` VALUES (501976, 300259, 2, '将鸡蛋搅拌均匀至颜色单一程度。', NULL);
INSERT INTO `recipe_step` VALUES (501977, 300259, 3, '将鸡蛋液倒入燕麦牛奶中继续搅拌至黏稠、均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501978, 300259, 4, '平底锅中加入一层黄油并覆盖均匀。', NULL);
INSERT INTO `recipe_step` VALUES (501979, 300259, 5, '下入搅拌好的食材，并摊开至饼状。', NULL);
INSERT INTO `recipe_step` VALUES (501980, 300259, 6, '小火加热两到三分钟。如想要加入蔬菜，可以在加热过程中加入碎菜叶。', NULL);
INSERT INTO `recipe_step` VALUES (501981, 300259, 7, '翻面继续加热两分钟。', NULL);
INSERT INTO `recipe_step` VALUES (501982, 300259, 8, '出锅，搭配剩下的牛奶作为早餐。', NULL);
INSERT INTO `recipe_step` VALUES (501983, 300260, 1, '锅中下入180g大豆油和30g牛油烧至180℃，下入200g蒜子、380g剁椒爆香；', NULL);
INSERT INTO `recipe_step` VALUES (501984, 300260, 2, '下入700g调理牛肉片大火快速炒散至变色；', NULL);
INSERT INTO `recipe_step` VALUES (501985, 300260, 3, '下入180g小炒黄牛肉汁、500g香芹翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (501986, 300261, 1, '【燕麦烹饪常规方法】将牛奶倒入早餐杯（冷的即可）', NULL);
INSERT INTO `recipe_step` VALUES (501987, 300261, 2, '【燕麦烹饪常规方法】准备好 200ml 水，如果是直饮水直接加入燕麦，否则请烧开后加入燕麦', NULL);
INSERT INTO `recipe_step` VALUES (501988, 300261, 3, '【燕麦烹饪常规方法】水沸后 2 分钟，燕麦煮好', NULL);
INSERT INTO `recipe_step` VALUES (501989, 300261, 4, '【燕麦烹饪常规方法】煮好的燕麦捞出倒入牛奶中（尽量不要将煮燕麦的水也倒入牛奶，影响口感）', NULL);
INSERT INTO `recipe_step` VALUES (501990, 300261, 5, '【燕麦烹饪快速方法】将燕麦替换为快煮燕麦', NULL);
INSERT INTO `recipe_step` VALUES (501991, 300261, 6, '【燕麦烹饪快速方法】将牛奶倒入装有快煮燕麦的容器中并搅拌', NULL);
INSERT INTO `recipe_step` VALUES (501992, 300261, 7, '【燕麦烹饪快速方法】将混合物放入微波炉中', NULL);
INSERT INTO `recipe_step` VALUES (501993, 300261, 8, '【燕麦烹饪快速方法】中等火力微波 4 分钟', NULL);
INSERT INTO `recipe_step` VALUES (501994, 300261, 9, '【煎蛋烹饪方法】热锅，锅内放一层底油，油热后煎鸡蛋，每面煎 20s，考虑调底味（3g 椒盐，可选）', NULL);
INSERT INTO `recipe_step` VALUES (501995, 300261, 10, '【煎蛋烹饪方法】关火，装盘', NULL);
INSERT INTO `recipe_step` VALUES (501996, 300262, 1, '【备料】从冰箱中取出牛排解冻。 如果牛排处于冰冻状态，需提前一晚转移至冷藏室，并在烹饪前半小时放置在常温中。 请勿将牛排置于水中或加热解冻。', NULL);
INSERT INTO `recipe_step` VALUES (501997, 300262, 2, '【备料】将小番茄，小土豆和口蘑洗净，对半切开备用。', NULL);
INSERT INTO `recipe_step` VALUES (501998, 300262, 3, '【备料】将大蒜剥皮，留 5-8 个较大的蒜瓣，用刀背压扁备用。', NULL);
INSERT INTO `recipe_step` VALUES (501999, 300262, 4, '【备料】牛排的预处理 对于肉眼牛排（见如何选择不同种类的牛排），使用厨房剪刀竖直插入到肉眼牛排中心的结缔组织，剪 1-2 刀。这是因为肉眼牛排的“肉眼”（即这块结缔组织）在高温下会剧烈收缩导致牛排变形，使得牛排无法均匀受热。 对于西冷牛排，如果您不喜欢西冷牛排边上的油脂，可以用刀慢慢将其剔除。 随后，使用厨房纸包裹牛排，将牛排上附着的水全部吸干，直至牛排放在案板上拿起后不留下明显水渍即可。', NULL);
INSERT INTO `recipe_step` VALUES (502000, 300262, 5, '【烹饪】将炉灶打开高火（见附录对于火力大小的说明），同时锅中加入橄榄油，热锅 15-30 秒。', NULL);
INSERT INTO `recipe_step` VALUES (502001, 300262, 6, '【烹饪】腌制牛排。将海盐和黑胡椒均匀的洒在牛排的全部表面并用手涂抹，揉搓，使得盐和胡椒颗粒尽量嵌入到肉中。注意，腌制完成后牛排需要立即下锅，不推荐提前腌制牛排。这是因为外表涂抹的盐会析出牛肉中的水分，影响烹饪的同时丧失风味。', NULL);
INSERT INTO `recipe_step` VALUES (502002, 300262, 7, '【烹饪】热锅至油温 6-8 成（参见油温判断技巧），将牛排由近及远的缓慢放入锅中。', NULL);
INSERT INTO `recipe_step` VALUES (502003, 300262, 8, '【烹饪】如果您使用了土豆作为配菜，可以将土豆放入碗中，然后放进微波炉加热 10 分钟，或者放入开水煮 3-5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502004, 300262, 9, '【烹饪】单面煎制 1.5 分钟（这个时间适用于 2-3cm 厚大约的牛排。如果您的牛排更薄，考虑将这个时间缩短为 1 分钟。如果您的牛排更厚，考虑将这个时间增加至 2-2.5 分钟。）', NULL);
INSERT INTO `recipe_step` VALUES (502005, 300262, 10, '【烹饪】翻面，再煎制 1.5 分钟。 对于西冷牛排和菲力牛排，您需要使用筷子或者锅铲将牛排竖起来，煎它的侧面约 30 秒。', NULL);
INSERT INTO `recipe_step` VALUES (502006, 300262, 11, '【烹饪】将炉灶切换至中火，随后按顺序快速加入黄油、大蒜、百里香。用锅铲推动黄油在锅中快速涂抹直至完全融化。将大蒜压在牛排下以增加风味。', NULL);
INSERT INTO `recipe_step` VALUES (502007, 300262, 12, '【烹饪】将平底锅倾斜地放在灶上，使得油全部流到锅的一侧。', NULL);
INSERT INTO `recipe_step` VALUES (502008, 300262, 13, '【烹饪】将香料和大蒜放置在牛排上，用汤匙舀起锅中的油，不断地淋在牛排上。这个过程持续 30 秒，随后将牛排翻面，再重复这个过程 30 秒。 您可以通过观察油淋在牛排表面时的状态来判断当前的火候。如果油淋在牛排上时冒泡并且油的颜色没有变成深褐色，则油温合适。 如果您的牛排没有擦干净或使用了不推荐的方式解冻，或者使用盐进行了提前腌制，这个时候锅中会出现大量水，导致牛排最后是被“煮熟”的，从而丧失风味。 如果牛排表面出现大量的油泡并且油的颜色变成深褐色，则说明油温过高，您需要将锅移开灶台，稍等片刻再继续淋油。', NULL);
INSERT INTO `recipe_step` VALUES (502009, 300262, 14, '【烹饪】将牛排盛出放在案板上，用锡箔纸包裹，等待 5-10 分钟。这个过程（称为醒肉）的作用是利用牛排自身的温度继续加热，锁住水分。', NULL);
INSERT INTO `recipe_step` VALUES (502010, 300262, 15, '【烹饪】将配菜（土豆，番茄，蘑菇）倒入锅中，开中火煎 5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502011, 300262, 16, '【烹饪】取出牛排，用刀切成宽度 1.5cm 宽度的肉条，此时您可以观察到牛肉的熟度。', NULL);
INSERT INTO `recipe_step` VALUES (502012, 300262, 17, '【烹饪】取出配菜，装盘，淋上锅中剩余的油或者牛排酱汁（可选）', NULL);
INSERT INTO `recipe_step` VALUES (502013, 300263, 1, '将牛油果对半切开，去核，剥去外皮，将果肉切成小块备用。', NULL);
INSERT INTO `recipe_step` VALUES (502014, 300263, 2, '在搅拌机中加入 120ml 原味酸奶、切好的牛油果块、1 汤匙蜂蜜以及 60ml 冷牛奶。', NULL);
INSERT INTO `recipe_step` VALUES (502015, 300263, 3, '（可选）加入一小撮小豆蔻粉以增加独特风味。', NULL);
INSERT INTO `recipe_step` VALUES (502016, 300263, 4, '启动搅拌机，搅拌大约 1 分钟直至液体变得完全顺滑和浓郁。', NULL);
INSERT INTO `recipe_step` VALUES (502017, 300263, 5, '将打好的饮品倒入杯中。', NULL);
INSERT INTO `recipe_step` VALUES (502018, 300263, 6, '（可选）在表面放上几片薄荷叶或撒上 5g 切碎的坚果作为装饰。', NULL);
INSERT INTO `recipe_step` VALUES (502019, 300264, 1, '锅置旺火（大火）放入牛油烧至 八成热(240±10°C) 时放入 老姜、大葱、洋葱、大蒜 (各100g)，炸干（吸尽异味（牛油腥味））后捞出扔掉。', NULL);
INSERT INTO `recipe_step` VALUES (502020, 300264, 2, '放入 (色拉油 || 菜籽油)、纯猪油，等待锅中油温下降到 五成热(150±10°C) 时放入 糍粑辣椒 持续翻炒 5-8 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502021, 300264, 3, '放入 豆瓣 炒散，转用 中小火 慢炒至料渣略发白翻砂（发出沙沙声）。', NULL);
INSERT INTO `recipe_step` VALUES (502022, 300264, 4, '油在外观呈现樱桃红时放入 姜片(150g)、大蒜(100g) 炒香，大约 15 秒。', NULL);
INSERT INTO `recipe_step` VALUES (502023, 300264, 5, '放入 豆鼓、豆母子 炒香，放入 红花椒、小茴香 炒香。', NULL);
INSERT INTO `recipe_step` VALUES (502024, 300264, 6, '（老油） 此刻放入 颗粒香料', NULL);
INSERT INTO `recipe_step` VALUES (502025, 300264, 7, '放入 麦芽粉 炒散，放入 白酒 炒散。', NULL);
INSERT INTO `recipe_step` VALUES (502026, 300264, 8, '【作为底料】起锅装入容器中，静置于温度低的环境(10-20) 5 天后再使用效果最佳。', NULL);
INSERT INTO `recipe_step` VALUES (502027, 300264, 9, '【作为老油】起锅装入容器中放入 干辣椒面 搅匀置放 24 小时，等待制作 老油。', NULL);
INSERT INTO `recipe_step` VALUES (502028, 300264, 10, '【作为老油】将底料倒入锅中，加入 3/5 的开水用大火烧开 （底料:2/5 开水:3/5）。', NULL);
INSERT INTO `recipe_step` VALUES (502029, 300264, 11, '【作为老油】烧开后表面会出现泡沫，将泡沫撇净。', NULL);
INSERT INTO `recipe_step` VALUES (502030, 300264, 12, '【作为老油】转用 中小火 慢熬出味（约 25-30 分钟），过滤去渣。', NULL);
INSERT INTO `recipe_step` VALUES (502031, 300264, 13, '【作为老油】等待容器中 油水分离 后，将表面的 油 撇净（将油打出来） 装入另外的容器。', NULL);
INSERT INTO `recipe_step` VALUES (502032, 300264, 14, '【作为老油】将上一步所 撇 出来的 油 重新倒入 净锅 中，直至 炼干 油中水分起锅装入容器即为 火锅老油。', NULL);
INSERT INTO `recipe_step` VALUES (502033, 300265, 1, '牛肉盒放入 190℃的油中油炸 4 分钟（两面各炸 2 分钟）。', NULL);
INSERT INTO `recipe_step` VALUES (502034, 300266, 1, '将1 份热干面拆袋倒入面篓中，沸水烫煮6~7 秒，在水中轻微抖动；', NULL);
INSERT INTO `recipe_step` VALUES (502035, 300266, 2, '烫好的面控水2-3 秒；', NULL);
INSERT INTO `recipe_step` VALUES (502036, 300266, 3, '将烫好后的面装入碗中，依次加入5g 胡萝卜丁、3.5g 热干面复合调味粉、25g 煮面水、13g 热干面调味汁、17g 稀释芝麻酱(芝麻酱：大豆油=1:1）。', NULL);
INSERT INTO `recipe_step` VALUES (502037, 300267, 1, '每只鸡用2g 盐均匀揉搓鸡表皮，冷藏20 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502038, 300267, 2, '每500g 老母鸡，加入16g 盐，60g 鸡油，2500g 水，烧开', NULL);
INSERT INTO `recipe_step` VALUES (502039, 300267, 3, '取18 个馄饨放入沸水中煮制5 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502040, 300267, 4, '舀取350g 老鸡汤倒入面碗，捞起馄饨，沥水后倒入碗中，撒入1g 葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (502041, 300268, 1, '碗底铺猪油', NULL);
INSERT INTO `recipe_step` VALUES (502042, 300268, 2, '加入米饭', NULL);
INSERT INTO `recipe_step` VALUES (502043, 300268, 3, '淋上酱油与蚝油', NULL);
INSERT INTO `recipe_step` VALUES (502044, 300268, 4, '撒上葱花和猪油渣', NULL);
INSERT INTO `recipe_step` VALUES (502045, 300268, 5, '搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502046, 300269, 1, '将猪皮，剁成不超过 10cm 小块，用清水浸泡 12 小时，然后冷水下锅，加入姜 10g、料酒 50ml 后，汆烫 5-10 分钟，捞出放入冷水中', NULL);
INSERT INTO `recipe_step` VALUES (502047, 300269, 2, '将焯过水的猪皮，放到案板上，将里面的白肉部分全部剔除，然后再切成成不超过 3mm 的长条，放入盆中', NULL);
INSERT INTO `recipe_step` VALUES (502048, 300269, 3, '加入白醋 20g，盐 5g，用力搓洗 3 分钟，再用清水洗净，这时的猪皮已经基本没什么腥味', NULL);
INSERT INTO `recipe_step` VALUES (502049, 300269, 4, '锅内加入 4kg 水，放入猪皮，葱 10g，姜片 10g，八角 10g，花椒 5g，大火烧开后，小火煲煮 90 分钟至猪皮软烂', NULL);
INSERT INTO `recipe_step` VALUES (502050, 300269, 5, '再加入盐 8g、味精 10g、鸡精 15g、生抽 50ml、老抽 20ml 调味后，倒入盘中，将葱姜，八角拣出，晾凉至果冻状', NULL);
INSERT INTO `recipe_step` VALUES (502051, 300269, 6, '放冰箱冷藏即可，食用时，切成小块或者厚片', NULL);
INSERT INTO `recipe_step` VALUES (502052, 300270, 1, '大葱切段；生姜 50 克切段， 50 克切末；大蒜切末，备用。', NULL);
INSERT INTO `recipe_step` VALUES (502053, 300270, 2, '全部酸菜切丝，用水冲洗 2 ～ 3 遍备用。', NULL);
INSERT INTO `recipe_step` VALUES (502054, 300270, 3, '排骨和五花肉入锅，倒入冷水淹没。放入全部葱段， 50 克生姜段和料酒 20 毫升。大火煮开后，等待 5 分钟。关火，将排骨和五花肉捞出，冷水冲洗掉浮沫，备用', NULL);
INSERT INTO `recipe_step` VALUES (502055, 300270, 4, '煮好的五花肉切片或者切块，备用。', NULL);
INSERT INTO `recipe_step` VALUES (502056, 300270, 5, '将之前的锅洗干净，并且擦干（不然加入油会崩出来）。', NULL);
INSERT INTO `recipe_step` VALUES (502057, 300270, 6, '锅中加入油，开中火，放入姜蒜末爆香，放入五花肉和排骨。将五花肉和排骨煎至金黄，倒入 10 克五香粉和 15 克 生抽酱油，用铲子翻动 1 ～ 2 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502058, 300270, 7, '将冲洗好的酸菜丝加入锅中，翻炒 3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502059, 300270, 8, '倒入纯净水至刚好没过食材，加入 2 颗大料，转大火，直到锅中水沸腾。转中火，盖锅盖焖煮。', NULL);
INSERT INTO `recipe_step` VALUES (502060, 300270, 9, '等待 1.5 ～ 2 小时，直至五花肉软烂 （可以用筷子轻松扎穿）', NULL);
INSERT INTO `recipe_step` VALUES (502061, 300270, 10, '掀开锅盖，开大火收汤，翻动锅中食材直至锅中剩余水分只覆盖锅底，转小火，准备调味。', NULL);
INSERT INTO `recipe_step` VALUES (502062, 300270, 11, '调味：加入食用盐 10 克，搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (502063, 300270, 12, '关火，出锅。', NULL);
INSERT INTO `recipe_step` VALUES (502064, 300271, 1, '将 50g 猴头菇山药玉米粉，加入 400g 的 65-90°C 温开水，用筷子搅拌均匀即可出品。', NULL);
INSERT INTO `recipe_step` VALUES (502065, 300272, 1, '【备菜】大葱切成 3-4cm 的大段，用刀背拍一下', NULL);
INSERT INTO `recipe_step` VALUES (502066, 300272, 2, '【备菜】玉米剁成小块', NULL);
INSERT INTO `recipe_step` VALUES (502067, 300272, 3, '【备菜】胡箩卜切成滚刀块', NULL);
INSERT INTO `recipe_step` VALUES (502068, 300272, 4, '【备菜】生姜去皮切大片', NULL);
INSERT INTO `recipe_step` VALUES (502069, 300272, 5, '【备菜】新鲜的排骨砍成小块', NULL);
INSERT INTO `recipe_step` VALUES (502070, 300272, 6, '【操作】排骨凉水下锅，放入大葱、生姜、料酒开始焯水，大火烧开，撇去浮沫，捞出排骨，沥干水分', NULL);
INSERT INTO `recipe_step` VALUES (502071, 300272, 7, '【操作】热锅凉油，切大片的生姜和排骨一起下锅煸炒，待排骨表面微微焦黄，放入醋（可加速肉质软烂），继续煸炒一分钟', NULL);
INSERT INTO `recipe_step` VALUES (502072, 300272, 8, '【操作】冲入开水，一次给足，之后就不要再加了，大火烧开', NULL);
INSERT INTO `recipe_step` VALUES (502073, 300272, 9, '【操作】先下入玉米，放入胡椒粉，盖盖小火炖二十分钟，然后放入胡萝卜，盖盖继续小火炖四十分钟', NULL);
INSERT INTO `recipe_step` VALUES (502074, 300272, 10, '【操作】调味很简单，出锅前三分钟，除了盐什么都不用放，最后撒上一把小葱花即可', NULL);
INSERT INTO `recipe_step` VALUES (502075, 300273, 1, '黄油隔热水融化、将蛋黄磨碎备用。', NULL);
INSERT INTO `recipe_step` VALUES (502076, 300273, 2, '在融化的黄油中添加糖、盐、以及碾碎的鸡蛋黄，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502077, 300273, 3, '加入低筋面粉与玉米淀粉，揉成面团', NULL);
INSERT INTO `recipe_step` VALUES (502078, 300273, 4, '将面团均匀分割成大约 8 克重的小面团，然后将它们搓成球状。', NULL);
INSERT INTO `recipe_step` VALUES (502079, 300273, 5, '使用大拇指轻压在每个小面团上，以形成裂纹。', NULL);
INSERT INTO `recipe_step` VALUES (502080, 300273, 6, '预热烤箱至 150℃，将小面团放入烤箱中，烘烤 20 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502081, 300273, 7, '微微放凉即可食用', NULL);
INSERT INTO `recipe_step` VALUES (502082, 300274, 1, '油条放入190℃的油中炸制1 分钟（油条两面各炸30 秒），至', NULL);
INSERT INTO `recipe_step` VALUES (502083, 300275, 1, '不锈钢桶中放入8500g 水，用大火烧开；', NULL);
INSERT INTO `recipe_step` VALUES (502084, 300275, 2, '将100g 糯米、80g 大米、320g 粥米、100g 麻豆（绿豆）清洗干净，放入水中烧开，再加入3g 碱粉搅匀；', NULL);
INSERT INTO `recipe_step` VALUES (502085, 300275, 3, '熬制40 分钟即可出品。', NULL);
INSERT INTO `recipe_step` VALUES (502086, 300276, 1, '将4颗珍珠糯米肉丸放入上汽后的蒸柜蒸制15分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502087, 300277, 1, '将 4 个新鲜鸡全翅取出，在翅中两根骨头之间用刀划开表皮，正反面各一刀', NULL);
INSERT INTO `recipe_step` VALUES (502088, 300277, 2, '将 4 个鸡全翅放入碗中，加入生抽 45ml ， 老抽 15ml ， 蒜粉 10g ， 胡椒粉 5g ， 糖 10g ， 甜椒粉 10g ，辣椒粉 5g ， 蚝油 15ml ， 水 20ml 以及油 10ml', NULL);
INSERT INTO `recipe_step` VALUES (502089, 300277, 3, '用勺子将酱汁均匀的抹在鸡全翅上，尤其是翅中的刀口处，大约花费 3 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502090, 300277, 4, '用保鲜膜盖住防油腌制中鸡全翅的碗，放入冰箱冷藏格静置 120 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502091, 300277, 5, '取出鸡全翅，锡纸盘中放入鸡全翅 4 个，将碗中残余酱料均匀倒在鸡全翅上', NULL);
INSERT INTO `recipe_step` VALUES (502092, 300277, 6, '锡纸盘放入空气炸锅的烤篮上，用 200 摄氏度烤 25 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502093, 300277, 7, '打开空气炸锅，小心取出锡纸盘，将鸡全翅翻面', NULL);
INSERT INTO `recipe_step` VALUES (502094, 300277, 8, '继续 200 摄氏度烤 25 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502095, 300277, 9, '取出即可食用', NULL);
INSERT INTO `recipe_step` VALUES (502096, 300278, 1, '下入菜籽油和熟猪油烧至180℃；', NULL);
INSERT INTO `recipe_step` VALUES (502097, 300278, 2, '下姜片、干红椒段、拍蒜炒香；', NULL);
INSERT INTO `recipe_step` VALUES (502098, 300278, 3, '下甜辣风味酱，炒至鸡块上色；', NULL);
INSERT INTO `recipe_step` VALUES (502099, 300278, 4, '加水烧开后，5档继续烧4分30秒；', NULL);
INSERT INTO `recipe_step` VALUES (502100, 300278, 5, '下入年糕烧开后，继续烧1分30秒至汤汁浓稠。', NULL);
INSERT INTO `recipe_step` VALUES (502101, 300279, 1, '【剁肉】肉改刀切开，肥瘦三七分', NULL);
INSERT INTO `recipe_step` VALUES (502102, 300279, 2, '【剁肉】上刀剁一剁，用刀背砸一砸，把肉筋打开打松疏', NULL);
INSERT INTO `recipe_step` VALUES (502103, 300279, 3, '【剁肉】剁一剁，砸一砸，剁成肉末，要想好吃得自己剁，机器打的太黏糊了', NULL);
INSERT INTO `recipe_step` VALUES (502104, 300279, 4, '【调味】每斤肉，6 克盐，1 克胡椒粉', NULL);
INSERT INTO `recipe_step` VALUES (502105, 300279, 5, '【调味】上手抓匀', NULL);
INSERT INTO `recipe_step` VALUES (502106, 300279, 6, '【调味】葱姜花椒水分次加，边加边搅，用手揉匀，让肉吸饱水。每斤肉末 80 克葱姜花椒水', NULL);
INSERT INTO `recipe_step` VALUES (502107, 300279, 7, '【调味】放入鸡蛋清，继续顺着一个方向搅', NULL);
INSERT INTO `recipe_step` VALUES (502108, 300279, 8, '【调味】加入 40 克土豆淀粉，搅匀', NULL);
INSERT INTO `recipe_step` VALUES (502109, 300279, 9, '【调味】加入熟豆油，这是为了保持其嫩滑弹的状态', NULL);
INSERT INTO `recipe_step` VALUES (502110, 300279, 10, '【汆丸子】起锅烧水，烧开，改小火，似开非开的样子', NULL);
INSERT INTO `recipe_step` VALUES (502111, 300279, 11, '【汆丸子】上手，挤丸子，', NULL);
INSERT INTO `recipe_step` VALUES (502112, 300279, 12, '【汆丸子】全部漂起来，用小火煮 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502113, 300279, 13, '【制作丸子汤】粉丝放碗底', NULL);
INSERT INTO `recipe_step` VALUES (502114, 300279, 14, '【制作丸子汤】加木耳，黄花，小香葱并用盐、胡椒粉、鸡粉打底调味', NULL);
INSERT INTO `recipe_step` VALUES (502115, 300279, 15, '【制作丸子汤】连汤带丸子冲如碗中', NULL);
INSERT INTO `recipe_step` VALUES (502116, 300279, 16, '【制作丸子汤】淋 3-5 滴香油', NULL);
INSERT INTO `recipe_step` VALUES (502117, 300279, 17, '【制作丸子汤】加一小颗香菜', NULL);
INSERT INTO `recipe_step` VALUES (502118, 300280, 1, '下入 80g 大豆油、80g 熟猪油、60g 蒜子，爆出香味；', NULL);
INSERT INTO `recipe_step` VALUES (502119, 300280, 2, '下入 1300g 上海青、12g 鸡精、12g 盐，大火爆炒 3 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (502120, 300281, 1, '生炸大鸡腿解冻后放入170℃的油锅中炸制8 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502121, 300282, 1, '【吐沙（提前半天）】上午买回田螺，放入清水盆中，静置一下午吐沙', NULL);
INSERT INTO `recipe_step` VALUES (502122, 300282, 2, '【吐沙（提前半天）】可在水中滴几滴香油（或者芥末~）加速吐沙', NULL);
INSERT INTO `recipe_step` VALUES (502123, 300282, 3, '【处理田螺】用刷子将田螺外壳刷洗干净（这一步可以时间久一些）', NULL);
INSERT INTO `recipe_step` VALUES (502124, 300282, 4, '【处理田螺】用老虎钳或菜刀剪去田螺尾部（约剪掉 1/3 到一半）', NULL);
INSERT INTO `recipe_step` VALUES (502125, 300282, 5, '【处理田螺】大锅烧水，水开后放入田螺焯烫 1-2 分钟（时间不可太久，螺肉会老）', NULL);
INSERT INTO `recipe_step` VALUES (502126, 300282, 6, '【处理田螺】捞出后用牙签挑出螺肉，去掉螺盖和黑色泥肠', NULL);
INSERT INTO `recipe_step` VALUES (502127, 300282, 7, '【处理田螺】螺壳用水冲洗干净，甩干水分备用', NULL);
INSERT INTO `recipe_step` VALUES (502128, 300282, 8, '【制作馅料】螺肉用盐抓洗干净，剁成碎粒（不要剁成泥，保留颗粒感才有嚼头）', NULL);
INSERT INTO `recipe_step` VALUES (502129, 300282, 9, '【制作馅料】猪肉剁成肉末', NULL);
INSERT INTO `recipe_step` VALUES (502130, 300282, 10, '【制作馅料】薄荷叶、紫苏叶切碎，姜切末，葱切葱花', NULL);
INSERT INTO `recipe_step` VALUES (502131, 300282, 11, '【制作馅料】将螺肉碎、猪肉末、薄荷碎、紫苏碎、姜末、葱花放入碗中', NULL);
INSERT INTO `recipe_step` VALUES (502132, 300282, 12, '【制作馅料】加入三花酒 15ml、生抽 15ml、食盐 3g', NULL);
INSERT INTO `recipe_step` VALUES (502133, 300282, 13, '【制作馅料】可选加入：蚝油 10ml、白胡椒粉 2g、淀粉 10g', NULL);
INSERT INTO `recipe_step` VALUES (502134, 300282, 14, '【制作馅料】朝一个方向搅拌至馅料粘稠上劲', NULL);
INSERT INTO `recipe_step` VALUES (502135, 300282, 15, '【制作馅料】图省事上面的所有东西直接放入打肉机直接打。', NULL);
INSERT INTO `recipe_step` VALUES (502136, 300282, 16, '【酿制】将馅料用筷子塞入田螺壳中，尽量塞满塞紧，但不要撑破螺壳', NULL);
INSERT INTO `recipe_step` VALUES (502137, 300282, 17, '【酿制】依次酿完所有田螺', NULL);
INSERT INTO `recipe_step` VALUES (502138, 300282, 18, '【焖煮】热锅，倒入 30ml 食用油，可选放入酸笋和干辣椒炒出香味', NULL);
INSERT INTO `recipe_step` VALUES (502139, 300282, 19, '【焖煮】倒入清水或高汤约 300ml，加生抽 15ml、食盐 2g，大火烧开', NULL);
INSERT INTO `recipe_step` VALUES (502140, 300282, 20, '【焖煮】将酿好的田螺放入锅中，盖上锅盖，中小火焖煮 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502141, 300282, 21, '【焖煮】焖煮过程中不要频繁翻动，等肉馅六七成熟定型后再轻轻翻动', NULL);
INSERT INTO `recipe_step` VALUES (502142, 300282, 22, '【焖煮】开盖，放入剩余的新鲜薄荷叶和紫苏叶，再焖 2-3 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502143, 300282, 23, '【焖煮】大火收汁至汤汁浓稠，即可出锅', NULL);
INSERT INTO `recipe_step` VALUES (502144, 300283, 1, '三文鱼去鳞，去骨', NULL);
INSERT INTO `recipe_step` VALUES (502145, 300283, 2, '金菇、冬菇切碎', NULL);
INSERT INTO `recipe_step` VALUES (502146, 300283, 3, '洗米三次', NULL);
INSERT INTO `recipe_step` VALUES (502147, 300283, 4, '把三文鱼、米、牛油放入电饭煲', NULL);
INSERT INTO `recipe_step` VALUES (502148, 300283, 5, '想口感浓厚一点，可以加多一汤匙牛油', NULL);
INSERT INTO `recipe_step` VALUES (502149, 300283, 6, '根据电饭煲的刻度放水', NULL);
INSERT INTO `recipe_step` VALUES (502150, 300283, 7, '把电饭煲調較至煲飯模式，等待大約 30 - 45 分鐘', NULL);
INSERT INTO `recipe_step` VALUES (502151, 300284, 1, '清洗米', NULL);
INSERT INTO `recipe_step` VALUES (502152, 300284, 2, '将米和水一起加入电饭煲中。', NULL);
INSERT INTO `recipe_step` VALUES (502153, 300284, 3, '连接电饭煲电源，进入加热模式。等待大约 30 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502154, 300284, 4, '待电饭煲自动进入保温模式后。', NULL);
INSERT INTO `recipe_step` VALUES (502155, 300284, 5, '将米在电饭煲中闷 10-15 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502156, 300284, 6, '盛出米。', NULL);
INSERT INTO `recipe_step` VALUES (502157, 300285, 1, '【配菜处理】牛肉切成薄片', NULL);
INSERT INTO `recipe_step` VALUES (502158, 300285, 2, '【配菜处理】番茄切成小块', NULL);
INSERT INTO `recipe_step` VALUES (502159, 300285, 3, '【配菜处理】葱切成葱花', NULL);
INSERT INTO `recipe_step` VALUES (502160, 300285, 4, '【配菜处理】姜切成姜片', NULL);
INSERT INTO `recipe_step` VALUES (502161, 300285, 5, '【配菜处理】蒜剁成蒜泥', NULL);
INSERT INTO `recipe_step` VALUES (502162, 300285, 6, '【牛肉的预处理】牛肉放入碗中', NULL);
INSERT INTO `recipe_step` VALUES (502163, 300285, 7, '【牛肉的预处理】加盐、胡椒粉腌制 15-20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502164, 300285, 8, '【煮汤】加水煮开', NULL);
INSERT INTO `recipe_step` VALUES (502165, 300285, 9, '【煮汤】加入姜片和牛肉片，煮至牛肉变色', NULL);
INSERT INTO `recipe_step` VALUES (502166, 300285, 10, '【煮汤】加入番茄块，煮至番茄变软', NULL);
INSERT INTO `recipe_step` VALUES (502167, 300285, 11, '【煮汤】打散鸡蛋液，缓慢地倒入锅中，用筷子搅拌形成蛋花', NULL);
INSERT INTO `recipe_step` VALUES (502168, 300285, 12, '【煮汤】加入盐和胡椒粉调味', NULL);
INSERT INTO `recipe_step` VALUES (502169, 300285, 13, '【煮汤】最后加入葱花，即可出锅', NULL);
INSERT INTO `recipe_step` VALUES (502170, 300286, 1, '将胡萝卜、芹菜、洋葱切碎，蒜瓣切片。', NULL);
INSERT INTO `recipe_step` VALUES (502171, 300286, 2, '加入 10ml 橄榄油，热油下锅蔬菜，大火翻炒开始略微变色后盛出。', NULL);
INSERT INTO `recipe_step` VALUES (502172, 300286, 3, '锅内加油 10ml，加蒜翻炒 10 秒，加入碎牛肉、糖、盐、胡椒粉和香料将牛肉炒脆（有颗粒感）。', NULL);
INSERT INTO `recipe_step` VALUES (502173, 300286, 4, '加入炒好的蔬菜们和番茄酱继续翻炒，搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (502174, 300286, 5, '分多次缓缓倒入牛奶，中小火煮 30 分钟，完成。', NULL);
INSERT INTO `recipe_step` VALUES (502175, 300287, 1, '汤底调配：750g开水与125g番茄汤膏，搅拌均匀；', NULL);
INSERT INTO `recipe_step` VALUES (502176, 300287, 2, '将100g西红柿块放入餐具底部、再放上5个肉丸；', NULL);
INSERT INTO `recipe_step` VALUES (502177, 300287, 3, '将15g菌菇平铺在上，并加入80g番茄汤底；', NULL);
INSERT INTO `recipe_step` VALUES (502178, 300287, 4, '待蒸柜上汽后，蒸制6分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502179, 300288, 1, '番茄底汤调制（8 份）：3000g 开水中加入500g 番茄汤膏，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (502180, 300288, 2, '将110g 手工挂面在沸水中煮4 分钟，放入25g 青菜烫制30 秒；', NULL);
INSERT INTO `recipe_step` VALUES (502181, 300288, 3, '面碗中舀取400g 番茄底汤，放入煮好的面条；', NULL);
INSERT INTO `recipe_step` VALUES (502182, 300288, 4, '将150g 西红柿炒鸡蛋菜品和25g 青菜放在面条上，撒5g 葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (502183, 300289, 1, '土豆去皮、对半切开，再切成约 2mm 的薄片，备用', NULL);
INSERT INTO `recipe_step` VALUES (502184, 300289, 2, '蒜苗洗净，切成约 1cm 的段，备用', NULL);
INSERT INTO `recipe_step` VALUES (502185, 300289, 3, '瘦肉洗净切成约 2mm 的薄片，放入碗中，加入 5g 生粉、5g 生抽、3g 老抽腌制十分钟，备用', NULL);
INSERT INTO `recipe_step` VALUES (502186, 300289, 4, '瘦肉腌制时，烧一锅开水，将土豆片放入锅中，焯水，约 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502187, 300289, 5, '热锅，锅内放入 10ml - 15ml 食用油。等待 10 秒让油温升高', NULL);
INSERT INTO `recipe_step` VALUES (502188, 300289, 6, '放入瘦肉，翻炒至变色，倒入蒜苗一起炒，蒜苗炒约 20 秒', NULL);
INSERT INTO `recipe_step` VALUES (502189, 300289, 7, '放入土豆，保持翻炒，加入 2g 食用盐、5g 生抽，', NULL);
INSERT INTO `recipe_step` VALUES (502190, 300289, 8, '炒约 3 分钟，盛盘', NULL);
INSERT INTO `recipe_step` VALUES (502191, 300290, 1, '白切鸡料配制（15 份）：生抽 40g、味极鲜 200g、纯净水 200g、白砂糖 50g、葱花 20g、芝麻香油 10g；', NULL);
INSERT INTO `recipe_step` VALUES (502192, 300290, 2, '将整鸡分切为宽度 1.5cm、长度 6cm 的块状;', NULL);
INSERT INTO `recipe_step` VALUES (502193, 300290, 3, '每份白切鸡出品时，淋上 30g 白切鸡料。', NULL);
INSERT INTO `recipe_step` VALUES (502194, 300291, 1, '菜心洗净，去除根部比较硬或老的地方。此处还用刀刮了刮菜心根茎部分，刮掉外面那层比较硬的，菜心内部更可口，但要注意根茎白灼时长，时间太长的话根茎不脆了', NULL);
INSERT INTO `recipe_step` VALUES (502195, 300291, 2, '大蒜切成蒜末，有洋葱顺便加了点洋葱', NULL);
INSERT INTO `recipe_step` VALUES (502196, 300291, 3, '调制灵魂料汁：生抽 5g 吧、蚝油 5g，加 3g 糖和 100g 清水半碗成一碗汁儿', NULL);
INSERT INTO `recipe_step` VALUES (502197, 300291, 4, '一锅 500ml 清水加 5g 盐和 10g 食用油烧开', NULL);
INSERT INTO `recipe_step` VALUES (502198, 300291, 5, '将菜心根茎在沸水中烫 1 分钟，直到根茎颜色变成深绿。再将整个菜心放到锅中烫熟 1 分钟，捞起来码入盘中', NULL);
INSERT INTO `recipe_step` VALUES (502199, 300291, 6, '开另一小锅将兑好的料汁倒入，小火烧开，放入一半的蒜末，一点点姜丝和小米椒碎。在制作时加了一点点洋葱碎和大蒜，先在锅底倒油，五成热后倒入蒜末、洋葱，稍稍爆香后再加入料汁，加入小米辣煮开', NULL);
INSERT INTO `recipe_step` VALUES (502200, 300291, 7, '料汁稍微收汁，煮沸后稍等十来秒吧，后直接浇在菜心上，不要特别多，但蒜末还是很给力的不要少蒜', NULL);
INSERT INTO `recipe_step` VALUES (502201, 300292, 1, '洋葱切小块，姜切片，平铺平底锅。', NULL);
INSERT INTO `recipe_step` VALUES (502202, 300292, 2, '活虾冲洗一下（去除虾线、剪刀减掉虾腿虾须子都是可选操作），控水，铺在平底锅的洋葱、姜片之上。', NULL);
INSERT INTO `recipe_step` VALUES (502203, 300292, 3, '锅内倒入料酒，盖上锅盖，中火 1 分钟，小火 5 分钟，关火 5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502204, 300292, 4, '和上一步并行操作，制作蘸料： 葱切成葱花、蒜切碎、倒入酱油、芝麻、香醋，搅拌之。 油烧热，淋入蘸料。', NULL);
INSERT INTO `recipe_step` VALUES (502205, 300292, 5, '虾出锅，用干净的盘子装好。', NULL);
INSERT INTO `recipe_step` VALUES (502206, 300293, 1, '锅洗净，倒入足量水，烧开后下入白灼虾、姜片、葱段；', NULL);
INSERT INTO `recipe_step` VALUES (502207, 300293, 2, '烧煮后捞出虾，淋上30g葱油料，点缀葱花。', NULL);
INSERT INTO `recipe_step` VALUES (502208, 300294, 1, '将320g 粥米、80g 大米、100g 糯米清洗干净和8500g 水放入', NULL);
INSERT INTO `recipe_step` VALUES (502209, 300295, 1, '下入 50g 大豆油、70g 熟猪油、30g 蒜子，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (502210, 300295, 2, '下入 900g 水、炒菜基料包 1 袋、3 盒豆腐，炖烧入味；', NULL);
INSERT INTO `recipe_step` VALUES (502211, 300295, 3, '下入 800g 白菜段，烧开后转小火，再次炖烧入味。', NULL);
INSERT INTO `recipe_step` VALUES (502212, 300296, 1, '锅内烧水，水开后放入干粉条，煮 5 分钟后同水一起倒出容器中，盖上盖子继续浸泡泡 备用（第一步先做这个，期间可以进行以下步骤）', NULL);
INSERT INTO `recipe_step` VALUES (502213, 300296, 2, '五花肉切 3mm 的肉片，备用', NULL);
INSERT INTO `recipe_step` VALUES (502214, 300296, 3, '大白菜嫩叶与白菜帮子分开切成 2 份菜片，备用', NULL);
INSERT INTO `recipe_step` VALUES (502215, 300296, 4, '热锅，锅内放入 10ml - 15ml 食用油。等待 10 秒让油温升高', NULL);
INSERT INTO `recipe_step` VALUES (502216, 300296, 5, '放入五花肉，保持翻炒至肉变色', NULL);
INSERT INTO `recipe_step` VALUES (502217, 300296, 6, '加入老抽，炒 1 分钟，给肉上色', NULL);
INSERT INTO `recipe_step` VALUES (502218, 300296, 7, '加入白菜帮子，加入食用盐、生抽，炒一分钟（如果粘锅，烹入 10ml 水）', NULL);
INSERT INTO `recipe_step` VALUES (502219, 300296, 8, '加水没过所有食材，加入鸡精 ，十三香，沸腾后，将火调小然后等待 20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502220, 300296, 9, '粉条滤水切成小段放入碗中 备用', NULL);
INSERT INTO `recipe_step` VALUES (502221, 300296, 10, '加入白菜嫩叶，炒匀后将粉条放在菜上方，加盖再煮 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502222, 300296, 11, '尝味、关火，收汁', NULL);
INSERT INTO `recipe_step` VALUES (502223, 300297, 1, '将4个百叶包放入上汽后的蒸柜蒸制10分钟，淋入30g老鸡汤，撒上1g葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (502224, 300298, 1, '百香果腌制（因为量小不好配置，这里是两次的分量） 将三个百香果的果肉取出来（里面的汁也不能放过），置于容器中 称量 30 克白砂糖放入 称量 10 克蜂蜜放入（如果没有可以用 5 克白砂糖代替） 搅拌均匀 容器保鲜膜封口，放入冰箱中进行 12~24 小时的腌制', NULL);
INSERT INTO `recipe_step` VALUES (502225, 300298, 2, '茉莉绿茶调配（推荐比例=茶 : 水 : 冰 = 1~2 : 50 : 30） 称量 3~6 克茶叶置于容器，加入 150 毫升开水，泡 6 分钟 往泡好的绿茶中放入 90 克冰块冷却，可搅拌加速冷却 待冰块消失后，将茶叶过滤得到茉莉绿茶茶水约 240 毫升', NULL);
INSERT INTO `recipe_step` VALUES (502226, 300298, 3, '橙子的处理（可在泡茶期间处理） 将橙子对半切（刀方向垂直于橙子的头尾连线），并从其中的一半中切取一片橙子备用 再次将橙子对半切，将得到的 4 角橙子用压汁器压出橙汁置于容器中备用', NULL);
INSERT INTO `recipe_step` VALUES (502227, 300298, 4, '正式调配 选择一个杯子，建议使用容量在 350~400 毫升的透明玻璃杯 将 70 克冰块放置在杯底，并将所有橙汁倒入 将之前准备的一片橙子贴杯内壁放置 将一次分量的腌制百香果浇在冰上 缓慢注入茉莉绿茶直至满杯，便于分层 在液面放置好装饰用的绿叶（可选）', NULL);
INSERT INTO `recipe_step` VALUES (502228, 300299, 1, '【主料】大米 - 洗净 - 放入电饭锅内胆 - 加入 1 升 饮用水', NULL);
INSERT INTO `recipe_step` VALUES (502229, 300299, 2, '【主料】瘦肉 - 洗净 - 简易晾去水分 - 加入 10ml 食用油 - 揉搓均匀 - 放入电饭锅内胆', NULL);
INSERT INTO `recipe_step` VALUES (502230, 300299, 3, '【主料】皮蛋 - 去壳 - 洗净 - 对半切开 - 分离蛋白蛋黄 - 蛋白简单切碎块 - 蛋黄揉碎 - 放入电饭锅内胆', NULL);
INSERT INTO `recipe_step` VALUES (502231, 300299, 4, '【主料】生姜 - 洗净 - 削皮 - 去除枯黄枯黑无法食用部分 - 切丝 - 放入电饭锅内胆', NULL);
INSERT INTO `recipe_step` VALUES (502232, 300299, 5, '【配料】小葱 - 洗净 - 去除根部 - 去除枯黄枯黑无法食用部分 - 切碎 - 放入小碗备用', NULL);
INSERT INTO `recipe_step` VALUES (502233, 300299, 6, '【配料】香菜 - 洗净 - 去除根部 - 去除枯黄枯黑无法食用部分 - 切碎 - 放入小碗备用', NULL);
INSERT INTO `recipe_step` VALUES (502234, 300299, 7, '【配料】生菜 - 洗净 - 去除根部 - 去除枯黄枯黑无法食用部分 - 切碎 - 放入小碗备用', NULL);
INSERT INTO `recipe_step` VALUES (502235, 300299, 8, '【酱料】酱油 + 蚝油 + 盐 + 胡椒粉 - 搅拌均匀 - 放入小碗备用', NULL);
INSERT INTO `recipe_step` VALUES (502236, 300299, 9, '【烹饪过程】主料 - 使用电饭锅煮粥模式煮熟', NULL);
INSERT INTO `recipe_step` VALUES (502237, 300299, 10, '【烹饪过程】配料 - 待主料煮熟后，生菜单独过一次热水，并与其余配料一同开盖加入主料中搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502238, 300299, 11, '【烹饪过程】酱料 - 待主料煮熟后，与其余配料一同开盖加入主料中搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502239, 300300, 1, '先把皮蛋剥壳，切成四瓣。', NULL);
INSERT INTO `recipe_step` VALUES (502240, 300300, 2, '嫩豆腐切块或者切片放中间。', NULL);
INSERT INTO `recipe_step` VALUES (502241, 300300, 3, '将生抽、白砂糖、醋、香油、辣椒油调成酱汁，淋上去。', NULL);
INSERT INTO `recipe_step` VALUES (502242, 300300, 4, '最后可选撒上花生碎、葱花、香菜。', NULL);
INSERT INTO `recipe_step` VALUES (502243, 300301, 1, '500ml 瓶装椰汁倒掉 200ml，立刻拧紧瓶盖。', NULL);
INSERT INTO `recipe_step` VALUES (502244, 300301, 2, '将这瓶椰汁放入冰箱冷冻区并冷冻 10 小时以上。', NULL);
INSERT INTO `recipe_step` VALUES (502245, 300301, 3, '将这瓶椰汁取出，若确认瓶中椰汁已彻底冻结，则在墙角、椅背、桌角等坚硬表面上用力抽打。（请务必确认表面不会因此受到损伤）', NULL);
INSERT INTO `recipe_step` VALUES (502246, 300301, 4, '当抽打到冻结椰汁变成冰沙状态，打开瓶盖倒出冰沙。', NULL);
INSERT INTO `recipe_step` VALUES (502247, 300301, 5, '在冰沙表面均匀撒上咖啡调糖或坚果碎。', NULL);
INSERT INTO `recipe_step` VALUES (502248, 300301, 6, '完成', NULL);
INSERT INTO `recipe_step` VALUES (502249, 300302, 1, '锅中倒入 1050g 三鲜豆腐汤料直至烧开；', NULL);
INSERT INTO `recipe_step` VALUES (502250, 300302, 2, '下入 1200g 豆腐，烧开后炖煮 5 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502251, 300302, 3, '取 60g 木耳、50g 白玉菇，炖煮 3 分钟，放置备用；', NULL);
INSERT INTO `recipe_step` VALUES (502252, 300302, 4, '均匀舀取 260g 炖好的三鲜豆腐、80g 汤汁至砂锅；', NULL);
INSERT INTO `recipe_step` VALUES (502253, 300302, 5, '将 3 颗焯水后的开背虾放置于豆腐上，汤汁烧开后煮 1 分钟，撒上 1g 葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (502254, 300303, 1, '每只鸡用2g 盐均匀揉搓鸡表皮，冷藏20 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502255, 300303, 2, '每500g 老母鸡，加入16g 盐、60g 鸡油、2500g 水，烧开后炖制60 分钟，备用；', NULL);
INSERT INTO `recipe_step` VALUES (502256, 300303, 3, '砂锅中放入50g 西红柿、50g 木耳、20g 青菜、50g 鸡块、2g 盐、400g 老鸡汤，烧开后，下入250g 湿米线，烧开出品。', NULL);
INSERT INTO `recipe_step` VALUES (502257, 300304, 1, '10 份糖水调制：锅中下入 750g 水、125g 冰糖，大火烧开后转小火熬制 5 分钟，备用；', NULL);
INSERT INTO `recipe_step` VALUES (502258, 300304, 2, '将 8g 陈皮丝平铺在砂锅底部，放入 160g 木瓜块，加入 50g 糖水，烧开后煮制 3 分钟，以桂花点缀出品。', NULL);
INSERT INTO `recipe_step` VALUES (502259, 300305, 1, '10 份泡椒汤底调制：2900g 开水中加入140g 汤料、700g泡椒调味料，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (502260, 300305, 2, '砂锅中加入50g 西红柿片、50g 娃娃菜、20g 木耳丝、20g海带丝、370g 泡椒汤底，烧开后，下入250g 湿米线，烧开放入60g 炸制好的鸡米花出品。', NULL);
INSERT INTO `recipe_step` VALUES (502261, 300306, 1, '将100g 白萝卜片平铺在砂锅底部，放入加热后的210g 牛杂、100g 汤汁；', NULL);
INSERT INTO `recipe_step` VALUES (502262, 300306, 2, '烧开后煮 1 分钟，撒上 10g 蒜花出品。', NULL);
INSERT INTO `recipe_step` VALUES (502263, 300307, 1, '番茄汤底调制（10 份）：3000g 开水中加入500g 番茄汤膏，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (502264, 300307, 2, '砂锅中加入50g 西红柿片、50g 木耳、20g 青菜、2g 盐、370g 番茄汤底，烧开后，下入250g 湿米线，烧开出品。', NULL);
INSERT INTO `recipe_step` VALUES (502265, 300308, 1, '10 份姜油炒制：100g 大豆油烧至180℃，下入30g 姜末，炒香备用；', NULL);
INSERT INTO `recipe_step` VALUES (502266, 300308, 2, '将20g 洋葱丝平铺在砂锅底部，放入150g 切好的盐焗鸡，淋入25g 姜油，烧开后出品。', NULL);
INSERT INTO `recipe_step` VALUES (502267, 300309, 1, '汤底调制（10份）：2600g开水中加入400g原味酸菜鱼底料，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (502268, 300309, 2, '将50g金针菇、50g湿粉丝、70g小叶酸菜平铺在砂锅中；', NULL);
INSERT INTO `recipe_step` VALUES (502269, 300309, 3, '砂锅中加入300g调制好的汤底，烧开；', NULL);
INSERT INTO `recipe_step` VALUES (502270, 300309, 4, '下入100g黑鱼片，烧开后撇去浮沫，浇上15g糊辣油，撒入1g葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (502271, 300310, 1, '炒螺丝椒片：锅中下入30g菜籽油烧至160℃，下入200g螺丝椒片炒制约30秒，倒入份盒备用；', NULL);
INSERT INTO `recipe_step` VALUES (502272, 300310, 2, '素鸡烧制：锅中加入1包素鸡汤料包、2400g水、1400g素鸡片、200g木耳烧煮，最后下入60g蒜子，搅拌均匀；', NULL);
INSERT INTO `recipe_step` VALUES (502273, 300310, 3, '砂锅煲制（单份出品）：砂锅中加入270g固形物、150g汤汁，加入20g炒螺丝椒片，加盖烧开后煮约2分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (502274, 300311, 1, '10 份腐竹半成品烧制：', NULL);
INSERT INTO `recipe_step` VALUES (502275, 300311, 2, '① 锅中下入 80g 大豆油、80g 熟猪油烧至 160℃；', NULL);
INSERT INTO `recipe_step` VALUES (502276, 300311, 3, '② 下入 50g 拍蒜、400g 蛋皮，炒香；', NULL);
INSERT INTO `recipe_step` VALUES (502277, 300311, 4, '③ 下入 3000g 开水，烧开后煮 2 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502278, 300311, 5, '④ 下入 1500g 泡好的腐竹、15g 盐，烧开后煮 3 分钟，备用。', NULL);
INSERT INTO `recipe_step` VALUES (502279, 300311, 6, '取 400g 腐竹半成品放入砂锅中，烧开后煮 1 分钟，撒', NULL);
INSERT INTO `recipe_step` VALUES (502280, 300312, 1, '每只鸡用2g 盐均匀揉搓鸡表皮，冷藏20 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502281, 300312, 2, '每500g 老母鸡，加入16g 盐、60g 鸡油、2500g 水，烧开后炖制60 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502282, 300312, 3, '砂锅中加入350g 老鸡汤、50g 西红柿片、25g 木耳烧开后，再下入16 只芥菜鲜肉大馄饨煮熟，下入20g 青菜煮熟出品。', NULL);
INSERT INTO `recipe_step` VALUES (502283, 300313, 1, '调味酱配制（10 份）：600g 蒜蓉酱、50g 红椒粒，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (502284, 300313, 2, '将50g 金针菇、100g 湿粉丝平铺在砂锅中；', NULL);
INSERT INTO `recipe_step` VALUES (502285, 300313, 3, '6 个开背虾尾部朝中间摆放一圈；', NULL);
INSERT INTO `recipe_step` VALUES (502286, 300313, 4, '将65g 调味酱平铺虾肉上，淋上30g 豉油汁，烧开后煮4 分30 秒，撒1g 葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (502287, 300314, 1, '炒线椒：锅中水分烧干，下入50g大豆油烧至160℃，加入300g线椒圈炒制约10秒，备用；', NULL);
INSERT INTO `recipe_step` VALUES (502288, 300314, 2, '鸡块炒制：锅中下入80g菜籽油、40g熟猪油烧至180℃，下入1700g鸡块，炒至鸡块表面泛黄出油；下入60g姜片、60g蒜子，炒香，下入水、350g酱料烧煮；', NULL);
INSERT INTO `recipe_step` VALUES (502289, 300314, 3, '砂锅煲制（单份出品）：砂锅中加入150g豆花豆腐、100g熟鸡块、120g汤汁加盖烧开后转小火煮约2分钟，加入30g炒线椒，出品。', NULL);
INSERT INTO `recipe_step` VALUES (502290, 300315, 1, '汤底调制（10 份）：3400g 开水中加入 480g 金汤，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (502291, 300315, 2, '将 50g 金针菇、50g 湿粉丝、70g 小叶酸菜平铺在砂锅中；', NULL);
INSERT INTO `recipe_step` VALUES (502292, 300315, 3, '砂锅中加入 350g 调制好的汤底并烧开；', NULL);
INSERT INTO `recipe_step` VALUES (502293, 300315, 4, '下入 130g 巴沙鱼片，烧开后撇去浮沫，浇上 15g 糊辣油，撒入 1g 葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (502294, 300316, 1, '鱿鱼炒制：锅中下入100g大豆油烧至160℃，下入30g姜片、60g拍蒜、10g鲜红小米辣段，炒至爆香；下入1100g鱿鱼条、800g焯水后的土豆条翻炒均匀；下入400g香辣爆炒酱，翻炒均匀，之后再下入50g水，炒香；', NULL);
INSERT INTO `recipe_step` VALUES (502295, 300316, 2, '砂锅煲制（单份出品）：砂锅中加入10g大豆油、60g洋葱丝、210g鱿鱼，加盖烧开，撒入1g葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (502296, 300317, 1, '卤肉复热：蒸柜中蒸10 分钟，盖在饭上出品。', NULL);
INSERT INTO `recipe_step` VALUES (502297, 300318, 1, '将酱油、糖和醋混合在一起,搅匀料汁备用', NULL);
INSERT INTO `recipe_step` VALUES (502298, 300318, 2, '另一个碗中加入鸡肉、鸡蛋、1/2 料汁和压碎的丽滋饼干。搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502299, 300318, 3, '空气炸锅用箔纸碗铺底，加入肉饼混合物，将剩余的料汁均匀的倒在上面', NULL);
INSERT INTO `recipe_step` VALUES (502300, 300318, 4, '350°F(177°C) 炸40 分钟。最好在米饭上食用', NULL);
INSERT INTO `recipe_step` VALUES (502301, 300318, 5, '在外观呈金黄酥脆后出锅，切块盛盘', NULL);
INSERT INTO `recipe_step` VALUES (502302, 300319, 1, '羊排放入碗中清水洗净血水', NULL);
INSERT INTO `recipe_step` VALUES (502303, 300319, 2, '羊排用厨房纸吸干水分，双面抹上黑椒混合调味料、蒜蓉酱，静置腌制 20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502304, 300319, 3, '锡纸碗放上烤架，羊排放在烤架上，撒上罗勒碎，黄油或烧烤料放在羊排上，空气炸锅 180° 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502305, 300319, 4, '羊排翻面，撒上罗勒碎，黄油（从锡纸碗里舀上来）或烧烤料放在羊排上，空气炸锅 180° 5 分钟（可以视个人喜好加一点时间，这里写的是不会焦的时间）', NULL);
INSERT INTO `recipe_step` VALUES (502306, 300320, 1, '【腌制鸡翅（提前一晚）】鸡翅中清洗后擦干水分，每个鸡翅两面各划 2 刀，方便入味。', NULL);
INSERT INTO `recipe_step` VALUES (502307, 300320, 2, '【腌制鸡翅（提前一晚）】调制腌料：生抽 15ml、蒜粉 8g、红甜椒粉 5g、洋葱粉 3g、黑胡椒粉 3g，牛奶或希腊酸奶 5ml（可选，让鸡肉更滑嫩）搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (502308, 300320, 3, '【腌制鸡翅（提前一晚）】将腌料和鸡翅中一起放到大 zip 保鲜袋里充分搅拌按摩，在冰箱里静置一晚。', NULL);
INSERT INTO `recipe_step` VALUES (502309, 300320, 4, '【裹粉准备】裹粉：中筋面粉 60g、淀粉 30g、蒜粉 5g、红甜椒粉 5g、洋葱粉 2g、黑胡椒粉 2g、泡打粉 1g（可选，让外壳更酥脆）搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (502310, 300320, 5, '【裹粉准备】裹浆（可选）：鸡蛋 1 个，牛奶或水 5ml，充分打散。', NULL);
INSERT INTO `recipe_step` VALUES (502311, 300320, 6, '【裹粉】裹粉：将鸡翅中抖干水分，放入裹粉中轻轻按压，抖落多余的粉，一旁静置 10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502312, 300320, 7, '【裹粉】裹浆（可选）：如想要更饱满的外壳，可以再裹一层浆，然后重复裹粉步骤。 将裹粉静置后的鸡翅放入裹浆，然后轻轻抖落多余的浆。 再次放入裹粉，轻轻按压，抖落多余的粉。 一旁静置 20 分钟（如有条件可以更久一点，外壳更牢固不易脱落）。', NULL);
INSERT INTO `recipe_step` VALUES (502313, 300320, 8, '【炸制】空气炸锅预热到 180°C，预热 5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502314, 300320, 9, '【炸制】炸篮内刷薄油，鸡皮面朝下，鸡翅上喷或者刷薄油。', NULL);
INSERT INTO `recipe_step` VALUES (502315, 300320, 10, '【炸制】设定空气炸锅 180°C，先炸 10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502316, 300320, 11, '【炸制】打开炸篮翻面，在鸡翅表面补喷或者刷薄油，再以 180°C 炸 6 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502317, 300320, 12, '【炸制】观察鸡皮颜色，并用牙签扎一下最厚的部分，看是否有血水流出。', NULL);
INSERT INTO `recipe_step` VALUES (502318, 300320, 13, '【炸制】如需要再以 200°C 炸 1-2 分钟补脆上色（可迭代进行，先炸 1 分钟观察再决定是否继续）。', NULL);
INSERT INTO `recipe_step` VALUES (502319, 300321, 1, '取出两片面包片（建议使用粗粮面包片）', NULL);
INSERT INTO `recipe_step` VALUES (502320, 300321, 2, '将面包片垂直放入空气炸锅', NULL);
INSERT INTO `recipe_step` VALUES (502321, 300321, 3, '200°C 烘烤 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502322, 300321, 4, '取出即可使用', NULL);
INSERT INTO `recipe_step` VALUES (502323, 300322, 1, '鸡翅从冰箱拿出来，鸡翼面朝下放入锡纸烤盘，撒上罗勒碎，盖上保鲜膜自然解冻 20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502324, 300322, 2, '撒上罗勒碎，空气炸锅 200°C，10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502325, 300322, 3, '翻面，撒上罗勒碎，空气炸锅 200°C，7 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502326, 300323, 1, '取 70g 清水笋丝放于餐具中；', NULL);
INSERT INTO `recipe_step` VALUES (502327, 300323, 2, '在笋丝上均匀平铺 75g 鸡翅块；', NULL);
INSERT INTO `recipe_step` VALUES (502328, 300323, 3, '将 70g 鸡翅调料平铺在鸡翅块上；', NULL);
INSERT INTO `recipe_step` VALUES (502329, 300323, 4, '蒸柜上汽后，蒸制 20 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (502330, 300324, 1, '汤底制作（10 份）:3000g 农夫山泉水、16g 花雕酒、16g 盐、12g 冰糖；', NULL);
INSERT INTO `recipe_step` VALUES (502331, 300324, 2, '取 700g 鸡块、200g 猪肉汆烫后备用；', NULL);
INSERT INTO `recipe_step` VALUES (502332, 300324, 3, '在每个汤盅内放入 17g 菌菇、55g 汆水后鸡块、15g汆水后的瘦肉块、1g 姜片、290g 汤底；', NULL);
INSERT INTO `recipe_step` VALUES (502333, 300324, 4, '汤盅放入蒸柜蒸制 35 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502334, 300324, 5, '出品时撇去浮油。', NULL);
INSERT INTO `recipe_step` VALUES (502335, 300325, 1, '锅中下入2600g 笋干和五花肉，烧制5 分钟，出品撒1g 葱花', NULL);
INSERT INTO `recipe_step` VALUES (502336, 300326, 1, '【1. 剁椒鸡丁炒制】①180g 大豆油烧至 180℃、下入 700g 鸡丁炒熟；', NULL);
INSERT INTO `recipe_step` VALUES (502337, 300326, 2, '【1. 剁椒鸡丁炒制】②下入 8g 老抽、5g 鸡精、2g 盐，将鸡丁炒制上色；', NULL);
INSERT INTO `recipe_step` VALUES (502338, 300326, 3, '【1. 剁椒鸡丁炒制】③下入 120g 剁椒酱、300g 焯水罗汉笋块，一起炒香；', NULL);
INSERT INTO `recipe_step` VALUES (502339, 300326, 4, '【1. 剁椒鸡丁炒制】④下入 36g 蒜花翻炒均匀，备用；', NULL);
INSERT INTO `recipe_step` VALUES (502340, 300326, 5, '【2. 菜苔烫制】取 70g 菜苔，在沸水中烫 1 分钟，备用；', NULL);
INSERT INTO `recipe_step` VALUES (502341, 300326, 6, '【3. 装配】餐盒中放入 300g 米饭，将 170g 剁椒鸡丁、70g 菜苔、半个卤蛋放在米饭上，菜苔上淋入 15g 豉油汁出品。', NULL);
INSERT INTO `recipe_step` VALUES (502342, 300327, 1, '笋子鸡丁炒制：(1) 180g大豆油烧至180℃、下入700g鸡丁炒熟；(2) 下入8g老抽、5g鸡精、2g盐，将鸡丁炒制上色；(3) 下入120g剁椒酱、300g焯水罗汉笋块，一起炒香；(4) 下入36g蒜花翻炒均匀，备用；', NULL);
INSERT INTO `recipe_step` VALUES (502343, 300327, 2, '包菜烫制：取70g包菜，在沸水中烫1分钟，备用；', NULL);
INSERT INTO `recipe_step` VALUES (502344, 300327, 3, '餐盒中放入300g米饭，将170g笋子鸡丁、70g包菜、半个卤蛋放在米饭上，包菜上淋入10g豉油汁出品。', NULL);
INSERT INTO `recipe_step` VALUES (502345, 300328, 1, '笋子鸡丁炒制：(1) 180g大豆油烧至180℃、下入700g鸡丁炒熟；(2) 下入8g老抽、5g鸡精、2g盐，将鸡丁炒制上色；(3) 下入120g剁椒酱、300g焯水罗汉笋块，一起炒香；(4) 下入36g蒜花翻炒均匀，备用；', NULL);
INSERT INTO `recipe_step` VALUES (502346, 300328, 2, '菜苔烫制：取70g菜苔，在沸水中烫1分钟，备用；', NULL);
INSERT INTO `recipe_step` VALUES (502347, 300328, 3, '餐盒中放入300g米饭，将170g笋子鸡丁、70g菜苔、半个卤蛋放在米饭上，菜苔上淋入15g豉油汁出品。', NULL);
INSERT INTO `recipe_step` VALUES (502348, 300329, 1, '开火，并向锅中倒入 100ml 开水', NULL);
INSERT INTO `recipe_step` VALUES (502349, 300329, 2, '再向锅中倒入 100ml 油，与第一步间隔越短越好，此时锅为大火中火都可以，着急的话可以大火', NULL);
INSERT INTO `recipe_step` VALUES (502350, 300329, 3, '放入冰糖（如果冰糖过于耦合，可以提前敲碎，做到耦合度越低越好）', NULL);
INSERT INTO `recipe_step` VALUES (502351, 300329, 4, '调整火力为中火', NULL);
INSERT INTO `recipe_step` VALUES (502352, 300329, 5, '开始搅拌 要一直一直一直搅拌，变成棕褐色，此时转为小火 再变稀，变红茶色，再变成酱红色后起小泡泡，准备好执行下面的操作1or操作2 小泡泡会逐渐消失，之后会出现大泡泡，大泡泡出现时糖色完成 需要在此时快速进行下一步操作（无论哪种操作都一定要提前准备好并快速！否则火候过大糖色发苦），根据菜品派别以及个人口味作出选择 操作 1：可以直接加 400ml 开水降温 操作 2（进阶调味版）：在糖液变成枣红色并起密集小泡时，迅速加入提前备好的葱姜蒜、花椒等辅料进行翻炒。爆出香味后（约 5-10 秒内），必须立刻倒入 400ml 开水降温中止反应。（注：若后续菜谱需要翻炒肉类上色，请在此步先下入肉类翻炒，最后再加水。）', NULL);
INSERT INTO `recipe_step` VALUES (502353, 300330, 1, '【原材料准备】猪五花肉切大块（约 4.5cm ，冷冻半小时至一小时更好切）', NULL);
INSERT INTO `recipe_step` VALUES (502354, 300330, 2, '【原材料准备】豆皮切 2cm 的宽度', NULL);
INSERT INTO `recipe_step` VALUES (502355, 300330, 3, '【原材料准备】生姜切片（每片厚度约 3mm ）', NULL);
INSERT INTO `recipe_step` VALUES (502356, 300330, 4, '【原材料准备】水烧开', NULL);
INSERT INTO `recipe_step` VALUES (502357, 300330, 5, '【原材料准备】鹌鹑蛋煮熟并用叉子/牙签扎孔（尽量多些好入味）', NULL);
INSERT INTO `recipe_step` VALUES (502358, 300330, 6, '【原材料准备】大葱大葱白色的部分葱白', NULL);
INSERT INTO `recipe_step` VALUES (502359, 300330, 7, '【开始制作】冷水锅中放入切好的猪五花肉，加入料酒与葱姜，煮 15 分钟去掉血腥', NULL);
INSERT INTO `recipe_step` VALUES (502360, 300330, 8, '【开始制作】锅中放入两片生姜提味', NULL);
INSERT INTO `recipe_step` VALUES (502361, 300330, 9, '【开始制作】开中小火后直接加入五花肉，不需要放入食用油，每块五花肉六个面都煎一下，煎至出油即可', NULL);
INSERT INTO `recipe_step` VALUES (502362, 300330, 10, '【开始制作】将煎出的油倒出备用，并将五花肉推至一边，加入 15g 冰糖，翻炒至冰糖融化；', NULL);
INSERT INTO `recipe_step` VALUES (502363, 300330, 11, '【开始制作】融化后将五花肉与冰糖炒至融合上色，加入 生抽 10ml 老抽 15ml 料酒 5ml 翻炒至上色；', NULL);
INSERT INTO `recipe_step` VALUES (502364, 300330, 12, '【开始制作】加入烧好的开水炖煮 40 分钟（刀工差的同学切的过大请自觉延长炖煮时间），并放入 生姜 2 片 香叶 3 片 八角 2 个', NULL);
INSERT INTO `recipe_step` VALUES (502365, 300330, 13, '【开始制作】盖上锅盖煮至沸腾后，加入煮好扎好孔的鹌鹑蛋和豆皮，开中小火，等待 40 分钟。（中途可适当翻搅防止粘锅）；', NULL);
INSERT INTO `recipe_step` VALUES (502366, 300330, 14, '【开始制作】打开锅盖，待汤汁快没有的时候开大火收汁（切记不可收干）；', NULL);
INSERT INTO `recipe_step` VALUES (502367, 300330, 15, '【开始制作】加入 2-3g 盐，翻炒一下，就可以出锅了。', NULL);
INSERT INTO `recipe_step` VALUES (502368, 300331, 1, '（可选）将 Mo ml 的油与洗净的米混合，尽量确保完全混合，即每粒米上至少都沾上少量油', NULL);
INSERT INTO `recipe_step` VALUES (502369, 300331, 2, '（可选）将 米-油混合物品冷藏保存，冷藏时间 Tc。', NULL);
INSERT INTO `recipe_step` VALUES (502370, 300331, 3, '将米和水加入锅中。', NULL);
INSERT INTO `recipe_step` VALUES (502371, 300331, 4, '开大火，加热到 T1。', NULL);
INSERT INTO `recipe_step` VALUES (502372, 300331, 5, '在 T1 之前将火关小。如果忘记此步骤，水可能会漫出而熄灭火焰。非常危险！', NULL);
INSERT INTO `recipe_step` VALUES (502373, 300331, 6, '加热到 Tr。在 Tr 时关闭火源。', NULL);
INSERT INTO `recipe_step` VALUES (502374, 300332, 1, '将5kg 大米清洗干净后放入泡米桶，加入70g 大豆油，', NULL);
INSERT INTO `recipe_step` VALUES (502375, 300332, 2, '将浸泡后的米（含水）倒入煮饭锅，煮40 分钟，闷10分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502376, 300333, 1, '将五花肉洗净，切成长约 5cm、宽约 3cm、厚度约 0.5cm 的肉片', NULL);
INSERT INTO `recipe_step` VALUES (502377, 300333, 2, '将姜、蒜切成颗粒直径不大于 1mm 的细末', NULL);
INSERT INTO `recipe_step` VALUES (502378, 300333, 3, '取一大碗，放入切好的五花肉、15ml 生抽、10ml 老抽、15ml 料酒、10g 郫县豆瓣酱、10g 姜末、10g 蒜末、5g 白砂糖', NULL);
INSERT INTO `recipe_step` VALUES (502379, 300333, 4, '用筷子搅拌均匀后，盖上保鲜膜，室温(20°C - 25°C)静置腌制 30 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502380, 300333, 5, '腌制完成后，加入 100g 蒸肉米粉，继续翻拌 2 分钟，确保每片肉都均匀裹粉', NULL);
INSERT INTO `recipe_step` VALUES (502381, 300333, 6, '土豆去皮，切片厚度控制在 0.8cm，片面积约为 5cm x 5cm，重量控制在 300g', NULL);
INSERT INTO `recipe_step` VALUES (502382, 300333, 7, '在直径 20cm 的深碗底部铺满土豆片，尽量无重叠', NULL);
INSERT INTO `recipe_step` VALUES (502383, 300333, 8, '将拌好粉的五花肉均匀铺在土豆片上，压实', NULL);
INSERT INTO `recipe_step` VALUES (502384, 300333, 9, '蒸锅中加入 2000ml 清水，开火加热至水面持续冒泡(100°C)', NULL);
INSERT INTO `recipe_step` VALUES (502385, 300333, 10, '将装好食材的碗放入蒸锅内，盖好锅盖', NULL);
INSERT INTO `recipe_step` VALUES (502386, 300333, 11, '保持中火蒸 60 分钟（火力保持在可持续沸腾的程度，约 600W 热功率）', NULL);
INSERT INTO `recipe_step` VALUES (502387, 300333, 12, '时间结束后，用筷子插入肉块中央，若能轻松穿透并无明显阻力，则表明蒸熟', NULL);
INSERT INTO `recipe_step` VALUES (502388, 300333, 13, '若未达到此状态，则继续加热 10 - 15 分钟，直至肉质软烂，油脂渗出', NULL);
INSERT INTO `recipe_step` VALUES (502389, 300333, 14, '取出盛盘，即可食用', NULL);
INSERT INTO `recipe_step` VALUES (502390, 300334, 1, '将南瓜90g（两块）、红薯100g(两块）、玉米100g（两块）放入蒸柜中蒸制25 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502391, 300335, 1, '粢饭糕放入 190℃的油中油炸 3 分钟（两面各炸 1 分 30 秒）。', NULL);
INSERT INTO `recipe_step` VALUES (502392, 300336, 1, '糍糕放入190℃的油中油炸5～6 分钟（炸制3 分钟后翻面）。', NULL);
INSERT INTO `recipe_step` VALUES (502393, 300337, 1, '用刀将西红柿皮米字型划开', NULL);
INSERT INTO `recipe_step` VALUES (502394, 300337, 2, '用筷子插入西红柿的菊花，在燃气上转动烤 10 秒（或用开水冲 30 秒），直到西红柿皮卷边', NULL);
INSERT INTO `recipe_step` VALUES (502395, 300337, 3, '把西红柿的衣服脱光', NULL);
INSERT INTO `recipe_step` VALUES (502396, 300337, 4, '再西红柿大卸八块（沿纹路切可以更多的留汁水），去掉头部根蒂部，备用', NULL);
INSERT INTO `recipe_step` VALUES (502397, 300337, 5, '全部切好后，将西红柿在盘子中均匀码一层', NULL);
INSERT INTO `recipe_step` VALUES (502398, 300337, 6, '撒上白糖，重复上面一步直到全部西红柿放完', NULL);
INSERT INTO `recipe_step` VALUES (502399, 300337, 7, '放入冰箱冷藏 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502400, 300337, 8, '一盘糖拌西红柿就好了，营养美味，酸甜爽口，夏日解暑又解腻', NULL);
INSERT INTO `recipe_step` VALUES (502401, 300338, 1, '糖糕放入 190℃ 的油中炸制 5 分钟（两面各炸 2 分 30 秒）。', NULL);
INSERT INTO `recipe_step` VALUES (502402, 300339, 1, '排骨与姜片放入冷水中，大火加热至水沸腾、出现大量泡沫后转中火，待水持续沸腾时再转小火焯水 2–3 分钟，捞出备用。', NULL);
INSERT INTO `recipe_step` VALUES (502403, 300339, 2, '用开水反复清洗排骨 2–3 遍，确保彻底去除血沫。', NULL);
INSERT INTO `recipe_step` VALUES (502404, 300339, 3, '在锅中倒入足够量的食用油进行深炸（油量依据锅具大小而定，建议约 300 ml 供一般家庭使用），待油温升至约 170°C 后，下排骨炸制 3–5 分钟，直至表面略呈金黄色，捞出控油。', NULL);
INSERT INTO `recipe_step` VALUES (502405, 300339, 4, '另取干净锅，置于小火上加热 50 ml 热水，加入白砂糖 30 g，轻轻搅拌直至糖完全溶解，并略呈淡黄色。此步骤的重点在于观察糖溶解情况，无需过分依赖颜色变化。', NULL);
INSERT INTO `recipe_step` VALUES (502406, 300339, 5, '将炸好的排骨倒入炒制糖水的锅中，迅速翻炒 30 秒后，依次加入香醋 5 ml、生抽 5 ml、蚝油 5 ml、鸡精 2 g、番茄酱 10 g、五香粉 0.5 g，再次翻炒 30 秒，使调料均匀裹覆排骨，然后加入开水至刚好没过排骨。', NULL);
INSERT INTO `recipe_step` VALUES (502407, 300339, 6, '用大火将锅中液体煮沸后，加入老抽 5 ml 进行上色，并快速收汁；若排骨块较大，可转小火焖煮 5–10 分钟以便更好地入味，切勿采用中火长时间炖煮 20 分钟，以免损伤口感。', NULL);
INSERT INTO `recipe_step` VALUES (502408, 300339, 7, '起锅装盘，撒上芝麻 2 g，即可享用。', NULL);
INSERT INTO `recipe_step` VALUES (502409, 300340, 1, '按照比例将各调料在小碗中搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502410, 300340, 2, '按不同菜肴的方式处理完毕后，将配制好的糖醋汁倒入锅中', NULL);
INSERT INTO `recipe_step` VALUES (502411, 300340, 3, '根据各菜肴的不同，烹制 5-10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502412, 300340, 4, '大火收汁，可增加菜的浓度、香味和光泽', NULL);
INSERT INTO `recipe_step` VALUES (502413, 300341, 1, '腌肉：将猪里脊肉先切厚片，用刀背拍一拍，把肉拍松一点。切成一个手指头粗的条，加料酒，生抽，蚝油，食盐，白胡椒粉，一个鸡蛋，将肉用手抓匀，腌制 20 分钟以上。', NULL);
INSERT INTO `recipe_step` VALUES (502414, 300341, 2, '调酱：番茄酱+10g 醋+30g 白糖+150ml 清水，搅拌至糖融化，备用。', NULL);
INSERT INTO `recipe_step` VALUES (502415, 300341, 3, '裹粉：先把粉全部裹好再来炸，这样在炸的时候就不会手忙脚乱。准备一个大碗，里面放淀粉，把每一根肉条都满满裹上淀粉。', NULL);
INSERT INTO `recipe_step` VALUES (502416, 300341, 4, '炸制：油温 160 摄氏度下里脊，可以拿一个干筷子放在油里面试一下，周围冒小泡就可以下锅。', NULL);
INSERT INTO `recipe_step` VALUES (502417, 300341, 5, '炸到表面微黄可以捞出，全程中火。然后等油温升高到 200 摄氏度，把里脊倒进去重新炸一次，只需 40 秒，表皮就会很脆，马上捞出。', NULL);
INSERT INTO `recipe_step` VALUES (502418, 300341, 6, '裹酱：另外拿一个锅，锅里放底油，把调好的酱汁倒进去，煮到冒泡，把炸好的里脊放进去，翻炒，让每一根都裹上酱汁。', NULL);
INSERT INTO `recipe_step` VALUES (502419, 300341, 7, '下炸好的里脊肉翻炒，关火盛出。', NULL);
INSERT INTO `recipe_step` VALUES (502420, 300342, 1, '将鱼清洗干净，确保无鱼鳞等异物', NULL);
INSERT INTO `recipe_step` VALUES (502421, 300342, 2, '将鱼头朝左，鱼肚朝下，右手持刀。刀竖直切下 1cm，按紧鱼身往左片 3-4cm，再将鱼片中间轻轻划一刀', NULL);
INSERT INTO `recipe_step` VALUES (502422, 300342, 3, '将鱼放进盆里，然后将大姜切片，大葱切段（随便切切就行了，主要是需要去腥味）', NULL);
INSERT INTO `recipe_step` VALUES (502423, 300342, 4, '用吃奶的力气将大葱大姜里的汁水挤到盆中', NULL);
INSERT INTO `recipe_step` VALUES (502424, 300342, 5, '加入 20g 盐，25g 料酒，然后给鲤鱼搓个澡，涂抹均匀', NULL);
INSERT INTO `recipe_step` VALUES (502425, 300342, 6, '找个干净的盆，加入 100g 面粉、200g 淀粉、180g 水、5g 盐，用手将其搅拌均匀，面糊此时粘稠呈可拉丝状态，然后打入一个鸡蛋，再次搅匀', NULL);
INSERT INTO `recipe_step` VALUES (502426, 300342, 7, '等待 30 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502427, 300342, 8, '将鱼放在案板上，用干毛巾将鱼身上的水擦干（这样可以更好的挂糊）', NULL);
INSERT INTO `recipe_step` VALUES (502428, 300342, 9, '将盆冲洗干净，用干毛巾擦干', NULL);
INSERT INTO `recipe_step` VALUES (502429, 300342, 10, '起锅烧油，加入约 1L 的油，将油温烧至 7 成热，约 200-240 度', NULL);
INSERT INTO `recipe_step` VALUES (502430, 300342, 11, '捏起鱼的尾巴，将鱼头沉入锅底，用勺子往鱼的身上淋热油，待面糊成型后，将鱼慢慢放入锅中，拿锅铲轻轻铲起鱼的头部，然后垫上笊篱。防止底部炸糊。', NULL);
INSERT INTO `recipe_step` VALUES (502431, 300342, 12, '准备一个盛鱼的盘子，放在锅的旁边。', NULL);
INSERT INTO `recipe_step` VALUES (502432, 300342, 13, '用锅铲从鱼身处轻轻铲入，两个工具配合鱼翻个身。再炸两分钟，还是同样的方式（笊篱托着鱼头，锅铲托着鱼身，将鱼盛入盘中）', NULL);
INSERT INTO `recipe_step` VALUES (502433, 300342, 14, '将锅中的油倒入擦干的盆中，放置一边，然后将锅刷干净', NULL);
INSERT INTO `recipe_step` VALUES (502434, 300342, 15, '将 50g 清水、40g 番茄酱、20g 白糖、10g 白醋放入小碗中，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502435, 300342, 16, '再准备一个小碗加入 10g 淀粉、10g 水，搅拌成水淀粉', NULL);
INSERT INTO `recipe_step` VALUES (502436, 300342, 17, '开大火将锅烧热，然后倒入之前准备的料汁，大火烧开，转小火', NULL);
INSERT INTO `recipe_step` VALUES (502437, 300342, 18, '加入调好的水淀粉，边倒边搅拌，然后 20 秒后关火', NULL);
INSERT INTO `recipe_step` VALUES (502438, 300342, 19, '将熬好的糖醋汁用勺子均匀地浇在鱼身上，可以加点香菜或葱花点缀，糖醋鲤鱼就做好了', NULL);
INSERT INTO `recipe_step` VALUES (502439, 300343, 1, '蒸柜上汽后，蒸制 25 分钟，出品。', NULL);
INSERT INTO `recipe_step` VALUES (502440, 300344, 1, '葱切花，蒜切沫，备用。', NULL);
INSERT INTO `recipe_step` VALUES (502441, 300344, 2, '生抽、老抽、耗油、盐混合调料汁，备用。', NULL);
INSERT INTO `recipe_step` VALUES (502442, 300344, 3, '小米椒切圈，备用。', NULL);
INSERT INTO `recipe_step` VALUES (502443, 300344, 4, '豆角去筋，45° 斜切4-10cm小段，备用。', NULL);
INSERT INTO `recipe_step` VALUES (502444, 300344, 5, '起锅烧油(10ml - 15ml)，冒烟后放入葱、小米椒，翻炒至闻到香味；', NULL);
INSERT INTO `recipe_step` VALUES (502445, 300344, 6, '加入豆角，翻炒30s,', NULL);
INSERT INTO `recipe_step` VALUES (502446, 300344, 7, '加入料汁，开大火翻炒2分钟', NULL);
INSERT INTO `recipe_step` VALUES (502447, 300344, 8, '倒入 150ml 水', NULL);
INSERT INTO `recipe_step` VALUES (502448, 300344, 9, '转中小火，盖上锅盖焖制 8-10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502449, 300344, 10, '加入蒜切沫，出锅。', NULL);
INSERT INTO `recipe_step` VALUES (502450, 300345, 1, '底汤制作：不锈钢桶内加入3500g 水，将水烧开后加入150g 熟猪油、30g 盐、50g 鸡精、10g 老抽搅拌均匀，再次烧开后关火，转80℃保温备用；', NULL);
INSERT INTO `recipe_step` VALUES (502451, 300345, 2, '取15g 青蒜花置于面碗中，倒入350g 底汤，将110g 挂面放入面篓中煮制4 分钟，捞起沥干倒入碗中。', NULL);
INSERT INTO `recipe_step` VALUES (502452, 300346, 1, '干紫菜用清水泡 15 分钟，捞起沥干水份备用。', NULL);
INSERT INTO `recipe_step` VALUES (502453, 300346, 2, '热锅，倒入 1.5 升清水、5ml 油、2g 盐。待水开后放入紫菜。', NULL);
INSERT INTO `recipe_step` VALUES (502454, 300346, 3, '紫菜烧开后 3 分钟，将打好的蛋液徐徐倒入锅内，30 秒既可起锅。', NULL);
INSERT INTO `recipe_step` VALUES (502455, 300346, 4, '撒上葱花，转小火 20 秒。', NULL);
INSERT INTO `recipe_step` VALUES (502456, 300346, 5, '关火，出锅前放入几滴香油，也有的会放入一点虾皮，味道也不错。', NULL);
INSERT INTO `recipe_step` VALUES (502457, 300347, 1, '将2kg杂粮、3kg大米清洗干净放入泡米桶，加水至11kg，浸泡3小时；', NULL);
INSERT INTO `recipe_step` VALUES (502458, 300347, 2, '将浸泡后的米（含水）倒入煮饭锅，加入60g大豆油，蒸40分钟，焖制10分钟左右。', NULL);
INSERT INTO `recipe_step` VALUES (502459, 300348, 1, '锡纸盘里打入鸡蛋 2 个， 加入红柚果肉 20g', NULL);
INSERT INTO `recipe_step` VALUES (502460, 300348, 2, '锡纸盘中倒入 15ml 油并摇晃锡纸盘时期均匀覆盖盘底', NULL);
INSERT INTO `recipe_step` VALUES (502461, 300348, 3, '锡纸盘中放入 10g 糖， 以及 40g 面粉和 40ml 水', NULL);
INSERT INTO `recipe_step` VALUES (502462, 300348, 4, '用筷子顺时针方向搅拌至淡黄色糊状', NULL);
INSERT INTO `recipe_step` VALUES (502463, 300348, 5, '锡纸盘中放入 5g 糖， 以及 40g 面粉和 40ml 水', NULL);
INSERT INTO `recipe_step` VALUES (502464, 300348, 6, '继续用筷子搅拌至淡黄色糊状', NULL);
INSERT INTO `recipe_step` VALUES (502465, 300348, 7, '锡纸盘放入空气炸锅的烤篮上，用 180 摄氏度烤 15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502466, 300348, 8, '打开空气炸锅，小心取出锡纸盘，用筷子或勺子将蛋糕翻面', NULL);
INSERT INTO `recipe_step` VALUES (502467, 300348, 9, '继续 180 摄氏度烤 8 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502468, 300348, 10, '取出即可食用', NULL);
INSERT INTO `recipe_step` VALUES (502469, 300349, 1, '冬瓜去皮，切 边长不超过 2cm 小块', NULL);
INSERT INTO `recipe_step` VALUES (502470, 300349, 2, '起锅烧油，放入冬瓜，缓缓翻滚煎炸 2 分钟 ，直至冬瓜表面泛金黄色', NULL);
INSERT INTO `recipe_step` VALUES (502471, 300349, 3, '取出冬瓜，放入大碗备用', NULL);
INSERT INTO `recipe_step` VALUES (502472, 300349, 4, '利用锅中的剩余油，依次放入姜末、生抽、蚝油，翻炒 15 S', NULL);
INSERT INTO `recipe_step` VALUES (502473, 300349, 5, '重新倒入冬瓜，翻炒 30 S 后，加入开水，水要没过冬瓜表面，大火煮 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502474, 300349, 6, '加入老抽上色，继续煮，直至冬瓜软糯（筷子可以轻松插近冬瓜）', NULL);
INSERT INTO `recipe_step` VALUES (502475, 300349, 7, '加入鸡精、料酒、香葱翻炒后 30 S， 取出冬瓜到大碗中', NULL);
INSERT INTO `recipe_step` VALUES (502476, 300349, 8, '锅中剩余汤汁保留，倒入水淀粉，煮开后汤汁浇灌在冬瓜表面', NULL);
INSERT INTO `recipe_step` VALUES (502477, 300350, 1, '【开始制作】冷水锅中放入热心摊主剁好的猪蹄，加入 20 ml 料酒与葱姜，煮 15 分钟去掉血腥', NULL);
INSERT INTO `recipe_step` VALUES (502478, 300350, 2, '【开始制作】热锅冷油，倒入 30ml 食用油，放入 7-8 粒冰糖，开小火，熬成糖色，期间用锅铲把冰糖压碎，大概熬 2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502479, 300350, 3, '【开始制作】熬成糖色后，放入焯过水的猪蹄，继续小火，翻炒猪蹄，直至所有猪蹄两面微黄', NULL);
INSERT INTO `recipe_step` VALUES (502480, 300350, 4, '【开始制作】加入香叶 2 片、桂皮 1 块、八角 4 个、生抽 20 ml、老抽 20 ml、料酒 10 ml、姜 3 片、盐 8 克，转中火、继续翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502481, 300350, 5, '【开始制作】加入开水或者冷水，水需要没过猪蹄，盖上锅盖，大火烧开，烧开之后关火', NULL);
INSERT INTO `recipe_step` VALUES (502482, 300350, 6, '【开始制作】把锅内的食材全部倒入高压锅中，高压锅中需要 15 分钟（如果同学没有高压锅，可放在锅中大火转小火熬制即可）', NULL);
INSERT INTO `recipe_step` VALUES (502483, 300350, 7, '【开始制作】15 分钟之后，把高压锅的食材倒入炒锅中，开大火收汁，此时可用筷子尝下味道、淡的话可以加 2~3g 盐', NULL);
INSERT INTO `recipe_step` VALUES (502484, 300350, 8, '【开始制作】大火收汁时长根据锅中的水来算，一般 30 秒即可，多留点也无碍、红烧猪蹄汤也是很下饭的', NULL);
INSERT INTO `recipe_step` VALUES (502485, 300351, 1, '青茄子、青辣椒、西红柿、洋葱、大葱洗净。', NULL);
INSERT INTO `recipe_step` VALUES (502486, 300351, 2, '大葱切 5 毫米宽的葱花，大蒜扒皮并拍碎，西红柿切 6 立方厘米的块，青辣椒、洋葱切 5g 的块。', NULL);
INSERT INTO `recipe_step` VALUES (502487, 300351, 3, '茄子切菱形块（先切 2 公分厚的片，然后再把片切成 2 公分的条，最后斜刀切块儿...）。', NULL);
INSERT INTO `recipe_step` VALUES (502488, 300351, 4, '将面粉倒入盆中，依次加入少量水，搅拌均匀，呈粘稠糊状。', NULL);
INSERT INTO `recipe_step` VALUES (502489, 300351, 5, '加入淀粉，加入 30 克水，搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (502490, 300351, 6, '将鸡蛋打到盆中，加入（面粉 / 20）克的盐，搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (502491, 300351, 7, '将茄块倒入面糊中，搅拌使茄块的每一面都能沾上面糊。', NULL);
INSERT INTO `recipe_step` VALUES (502492, 300351, 8, '开大火，热锅，加入 500 毫升的油，当能看到锅里的油冒出一丝烟时，调至小火，将茄块用筷子夹入到油锅，待所有的茄块下锅之后，调至中火，直到茄块变金黄色时捞出，将油倒出。', NULL);
INSERT INTO `recipe_step` VALUES (502493, 300351, 9, '加入（份数 5）g 的油，放入大蒜、葱花，翻炒 15 秒，放入青辣椒块翻炒 30 秒，放入西红柿翻炒 30 秒。', NULL);
INSERT INTO `recipe_step` VALUES (502494, 300351, 10, '放入炸好的茄块，加水面高度为锅内食材的 0.8 倍。', NULL);
INSERT INTO `recipe_step` VALUES (502495, 300351, 11, '放入酱油和（份数 3）g 的盐。', NULL);
INSERT INTO `recipe_step` VALUES (502496, 300351, 12, '等待，直到汤汁呈粘稠状（水位大概为剩余食材高度的 0.2-0.3 倍），开盖，盛出菜，关火。', NULL);
INSERT INTO `recipe_step` VALUES (502497, 300352, 1, '【原材料准备】姜蒜准备好，切碎', NULL);
INSERT INTO `recipe_step` VALUES (502498, 300352, 2, '【原材料准备】干辣椒切碎，和姜蒜一起', NULL);
INSERT INTO `recipe_step` VALUES (502499, 300352, 3, '【最终步骤】加入 30-50ml 油，等待锅热...', NULL);
INSERT INTO `recipe_step` VALUES (502500, 300352, 4, '【最终步骤】放入擦干水分的鱼（不想被热油溅一身的话），然后晃动锅，用热油煎鱼，注意这过程一定要小火', NULL);
INSERT INTO `recipe_step` VALUES (502501, 300352, 5, '【最终步骤】将鱼翻面，重复上面油煎过程', NULL);
INSERT INTO `recipe_step` VALUES (502502, 300352, 6, '【最终步骤】放入姜蒜辣椒，翻炒出香味', NULL);
INSERT INTO `recipe_step` VALUES (502503, 300352, 7, '【最终步骤】倒入料酒，稍微多一点，此过程注意安全，会起大量油烟', NULL);
INSERT INTO `recipe_step` VALUES (502504, 300352, 8, '【最终步骤】倒入醋（喜欢醋可以多放一点）', NULL);
INSERT INTO `recipe_step` VALUES (502505, 300352, 9, '【最终步骤】然后放入白砂糖，酱油（老抽)', NULL);
INSERT INTO `recipe_step` VALUES (502506, 300352, 10, '【最终步骤】加入冷水，以刚好淹没鱼身为宜，然后调成中火，盖上锅盖，大概 1 分钟后将鱼翻身，继续盖上锅盖', NULL);
INSERT INTO `recipe_step` VALUES (502507, 300352, 11, '【最终步骤】3-4 分钟后，加入盐、小米椒、蚝油（味精、鸡精等），然后继续盖上锅盖，后续继续要翻身', NULL);
INSERT INTO `recipe_step` VALUES (502508, 300352, 12, '【最终步骤】当锅内汤汁收汁到鱼的脊背线上的鱼鳍下面一点点的时候（或者汤汁不多的时候），转小火，加入香菜，葱花，然后盖上锅盖 20 秒，关火', NULL);
INSERT INTO `recipe_step` VALUES (502509, 300352, 13, '【最终步骤】起锅', NULL);
INSERT INTO `recipe_step` VALUES (502510, 300353, 1, '锅中下入1300g 水、50g 鸡油、10g 盐、700g 红烧鱼块料，大火烧开；', NULL);
INSERT INTO `recipe_step` VALUES (502511, 300353, 2, '下入800g 炸制鱼块炖烧7 分钟，出品撒1g 葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (502512, 300354, 1, '【原材料准备】葱、姜、蒜、香菜、美人椒分别清洗干净。', NULL);
INSERT INTO `recipe_step` VALUES (502513, 300354, 2, '【原材料准备】干辣椒与八角稍微冲洗即可。', NULL);
INSERT INTO `recipe_step` VALUES (502514, 300354, 3, '【原材料准备】大葱切两半。后半段大葱（葱白处）切段，每段长度约 4cm。前半段（葱叶处）先切段，再将每段劈为四瓣。', NULL);
INSERT INTO `recipe_step` VALUES (502515, 300354, 4, '【原材料准备】姜切片，每片厚度约 3mm。', NULL);
INSERT INTO `recipe_step` VALUES (502516, 300354, 5, '【原材料准备】大蒜拍碎。', NULL);
INSERT INTO `recipe_step` VALUES (502517, 300354, 6, '【原材料准备】拿出两棵香菜去根，切为 1.5cm 香菜碎。', NULL);
INSERT INTO `recipe_step` VALUES (502518, 300354, 7, '【原材料准备】将美人椒切为厚度为 3mm 的辣椒圈。', NULL);
INSERT INTO `recipe_step` VALUES (502519, 300354, 8, '【原材料准备】干辣椒切四段。', NULL);
INSERT INTO `recipe_step` VALUES (502520, 300354, 9, '【腌制鱼头】注：下文所述的鱼身是购买鱼头时所附带的鱼肉。', NULL);
INSERT INTO `recipe_step` VALUES (502521, 300354, 10, '【腌制鱼头】将鱼头去鳞，清洗鱼头处未被清理干净的内脏。', NULL);
INSERT INTO `recipe_step` VALUES (502522, 300354, 11, '【腌制鱼头】剁去鱼鳍、清理鱼鳃。', NULL);
INSERT INTO `recipe_step` VALUES (502523, 300354, 12, '【腌制鱼头】将鱼头下巴与鱼身连接的地方剁开，鱼身剁块，鱼头剁成四/六瓣。 注：鱼的处理很难用文字完全表述，可以搜索鱼头处理相关视频。', NULL);
INSERT INTO `recipe_step` VALUES (502524, 300354, 13, '【腌制鱼头】将剁好的鱼头进行清洗，最好洗掉鱼块上滞留的血水。', NULL);
INSERT INTO `recipe_step` VALUES (502525, 300354, 14, '【腌制鱼头】将清洗好的鱼块放入盆中，加入 5g 盐、10g 生抽、10g 料酒。放入葱（前半段切碎的那个）、1/3 姜片。将其拌匀，静置 1-2 小时。', NULL);
INSERT INTO `recipe_step` VALUES (502526, 300354, 15, '【最终步骤】加入 30ml 油，等待锅热...', NULL);
INSERT INTO `recipe_step` VALUES (502527, 300354, 16, '【最终步骤】油热，将锅关至小火 如果不明白为何要这样做，请查看学习炒与煎中的翻炒辅料。', NULL);
INSERT INTO `recipe_step` VALUES (502528, 300354, 17, '【最终步骤】放入姜片，慢慢翻炒，以姜片中的大部分汁水被炒出，以金黄色为准。', NULL);
INSERT INTO `recipe_step` VALUES (502529, 300354, 18, '【最终步骤】放入葱段，翻炒至葱段略显发白。', NULL);
INSERT INTO `recipe_step` VALUES (502530, 300354, 19, '【最终步骤】放入蒜碎、八角、干辣椒，翻炒 5 秒。', NULL);
INSERT INTO `recipe_step` VALUES (502531, 300354, 20, '【最终步骤】将腌制好的鱼头倒入锅中，翻炒 2-3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502532, 300354, 21, '【最终步骤】倒入 500ml 清水，加入 2g 盐、3g 鸡精、5g 生抽、3g 老抽、5g 料酒、2g 黑胡椒粉、3g 陈醋。', NULL);
INSERT INTO `recipe_step` VALUES (502533, 300354, 22, '【最终步骤】将两棵香菜放入锅中，盖上锅盖。', NULL);
INSERT INTO `recipe_step` VALUES (502534, 300354, 23, '【最终步骤】调至大火，将水烧开。', NULL);
INSERT INTO `recipe_step` VALUES (502535, 300354, 24, '【最终步骤】调至中火，慢焖入味。', NULL);
INSERT INTO `recipe_step` VALUES (502536, 300354, 25, '【最终步骤】当汤汁减少一半时，打开锅盖。', NULL);
INSERT INTO `recipe_step` VALUES (502537, 300354, 26, '【最终步骤】调至大火收汁，汤汁剩余 1/3 时，关火盛至小盆中。', NULL);
INSERT INTO `recipe_step` VALUES (502538, 300354, 27, '【最终步骤】注：将锅中的汤汁均匀淋到鱼头上，盛盘时可以将锅中煮的香菜放入小盆底部，这样能让成品菜好看又好吃。', NULL);
INSERT INTO `recipe_step` VALUES (502539, 300354, 28, '【最终步骤】将香菜放至已经盛出的鱼头上，把切好的美人椒圈放在香菜之上。', NULL);
INSERT INTO `recipe_step` VALUES (502540, 300354, 29, '【最终步骤】色香味俱全的红烧鱼头出炉！', NULL);
INSERT INTO `recipe_step` VALUES (502541, 300355, 1, '葱、姜、蒜、干辣椒分别清洗干净。', NULL);
INSERT INTO `recipe_step` VALUES (502542, 300355, 2, '葱白处切段，每段长度约 4cm，再将每段劈为四瓣。', NULL);
INSERT INTO `recipe_step` VALUES (502543, 300355, 3, '姜切片，每片厚度约 3mm。', NULL);
INSERT INTO `recipe_step` VALUES (502544, 300355, 4, '一个大蒜拍碎切末，其余蒜切为二瓣。', NULL);
INSERT INTO `recipe_step` VALUES (502545, 300355, 5, '干辣椒切四段。', NULL);
INSERT INTO `recipe_step` VALUES (502546, 300355, 6, '五花肉切片，约 4cm4cm。', NULL);
INSERT INTO `recipe_step` VALUES (502547, 300355, 7, '清洗鱼。', NULL);
INSERT INTO `recipe_step` VALUES (502548, 300355, 8, '鱼背肉厚处拉几道斜口，方便入味', NULL);
INSERT INTO `recipe_step` VALUES (502549, 300355, 9, '锅里多倒点油，烧至 7 成热（刚刚开始冒烟），下入鱼炸 1 分钟至鱼皮稍稍变硬捞出备用（注意不要一下锅就拨弄鱼，等炸一会再拨弄、翻面），炸鱼的油倒出，锅里留一点底油', NULL);
INSERT INTO `recipe_step` VALUES (502550, 300355, 10, '将锅里底油烧热，下入五花肉，煸出香味。', NULL);
INSERT INTO `recipe_step` VALUES (502551, 300355, 11, '放入干辣椒、葱、姜、蒜瓣，翻炒 1 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502552, 300355, 12, '将炸好的鱼倒入锅中。', NULL);
INSERT INTO `recipe_step` VALUES (502553, 300355, 13, '沿锅边倒入 50ml 料酒 50ml 陈醋 50ml 味极鲜 20ml 老抽调色 5ml 蚝油提鲜 5g 匙盐 50g 白糖 清水没过鱼面。', NULL);
INSERT INTO `recipe_step` VALUES (502554, 300355, 14, '调至中火，将水烧开。', NULL);
INSERT INTO `recipe_step` VALUES (502555, 300355, 15, '调至小火，慢焖入味。', NULL);
INSERT INTO `recipe_step` VALUES (502556, 300355, 16, '15 分钟 后，打开锅盖，挑出锅里的葱、姜、蒜、干辣椒。', NULL);
INSERT INTO `recipe_step` VALUES (502557, 300355, 17, '调至大火收汁，汤汁剩余 1/4 时，撒点蒜末，关火盛出。', NULL);
INSERT INTO `recipe_step` VALUES (502558, 300355, 18, '红烧鲤鱼出锅！', NULL);
INSERT INTO `recipe_step` VALUES (502559, 300356, 1, '将鸡翅洗净。用刀在鸡翅厚处划三刀，背面扎一刀，便于入味。', NULL);
INSERT INTO `recipe_step` VALUES (502560, 300356, 2, '如果鸡翅不新鲜，可在打完花刀之后用姜水泡 10-20 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502561, 300356, 3, '将 10g 姜片（3-4 片）、15g 葱段（2-3 段）备好；3-4 瓣大蒜（约 15g）用刀拍散（无需剁碎）；1 片香叶、1 个八角、2 个干辣椒（可选）整理好备用。', NULL);
INSERT INTO `recipe_step` VALUES (502562, 300356, 4, '起锅开火，锅中加入清水没过所有鸡翅，冷水下锅放入处理好的鸡翅，加入 20ml 黄酒或料酒、2 片姜片（约 5g），开大火烧至沸腾，沸腾后保持大火继续煮 2-3 分钟，撇去浮沫。', NULL);
INSERT INTO `recipe_step` VALUES (502563, 300356, 5, '煮好后将鸡翅捞出，用温水清洗 2 遍，彻底去除血沫，控干水分备用。', NULL);
INSERT INTO `recipe_step` VALUES (502564, 300356, 6, '另起锅，开火烧热后放入 10-15ml 食用油。', NULL);
INSERT INTO `recipe_step` VALUES (502565, 300356, 7, '待油温至 5 成热，加入 15g 冰糖，开大火将冰糖熬至完全融化，冰糖融化变色后转小火，继续炒至冰糖呈枣红色，立即放入控干水分的鸡翅，快速翻炒 1-2 分钟，使每只鸡翅均匀裹上糖色。', NULL);
INSERT INTO `recipe_step` VALUES (502566, 300356, 8, '加入准备好的 1 片香叶、1 个八角、2 个干辣椒（可选）、剩下的 2 片姜片（约 5g）、15g 葱段、拍散的大蒜，继续煸炒 30 秒至香料香味完全释放。', NULL);
INSERT INTO `recipe_step` VALUES (502567, 300356, 9, '沿锅边淋入 15ml 料酒或黄酒，15ml 生抽，快速翻炒 10 秒。', NULL);
INSERT INTO `recipe_step` VALUES (502568, 300356, 10, '加入温水（水温约 50-60℃），水量以稍微没过所有鸡翅为准。', NULL);
INSERT INTO `recipe_step` VALUES (502569, 300356, 11, '加入 5ml 老抽、3g 盐、2g 白糖、1g 胡椒粉，用炒勺轻轻搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (502570, 300356, 12, '盖上锅盖，开中火烧煮 7-8 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502571, 300356, 13, '打开锅盖，用筷子将锅中的香叶、八角、姜片、葱段、大蒜捡出丢弃。', NULL);
INSERT INTO `recipe_step` VALUES (502572, 300356, 14, '转大火，保持不断翻炒，将汤汁烧至粘稠状态（约 1-2 分钟）。', NULL);
INSERT INTO `recipe_step` VALUES (502573, 300356, 15, '关火，将鸡翅盛入盘中，淋上锅中剩余的粘稠汤汁。', NULL);
INSERT INTO `recipe_step` VALUES (502574, 300356, 16, '最后撒上 3g 白芝麻和 5g 小葱花，完成制作。', NULL);
INSERT INTO `recipe_step` VALUES (502575, 300357, 1, '【准备工作（提前 8 小时）】将干红芸豆用清水浸泡至少 8 小时（过夜），浸泡后体积会膨胀约两倍', NULL);
INSERT INTO `recipe_step` VALUES (502576, 300357, 2, '【煮红芸豆】将浸泡好的红芸豆沥干', NULL);
INSERT INTO `recipe_step` VALUES (502577, 300357, 3, '【煮红芸豆】使用高压锅：放入红芸豆和 600ml 水，盖好锅盖，大火上气后转中火，压 15-20 分钟，直至豆子用手指可轻松压碎', NULL);
INSERT INTO `recipe_step` VALUES (502578, 300357, 4, '【煮红芸豆】使用普通锅：放入红芸豆和足量水，大火煮沸后转中火，煮 60-90 分钟，直至豆子完全软烂', NULL);
INSERT INTO `recipe_step` VALUES (502579, 300357, 5, '【煮红芸豆】煮好后保留煮豆汤水，备用', NULL);
INSERT INTO `recipe_step` VALUES (502580, 300357, 6, '【炒制咖喱】在炒锅中倒入 30ml 食用油，中火加热', NULL);
INSERT INTO `recipe_step` VALUES (502581, 300357, 7, '【炒制咖喱】放入月桂叶 2 片，炸至散出香味（约 10 秒）', NULL);
INSERT INTO `recipe_step` VALUES (502582, 300357, 8, '【炒制咖喱】放入切碎的洋葱，翻炒至金棕色（约 6-8 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (502583, 300357, 9, '【炒制咖喱】加入磨碎的生姜和大蒜，翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502584, 300357, 10, '【炒制咖喱】加入切碎的番茄，翻炒至番茄完全软烂出油（约 5 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (502585, 300357, 11, '【炒制咖喱】加入姜黄粉 3g、红辣椒粉 5g、香菜粉 5g、孜然粉 3g、盐 6g', NULL);
INSERT INTO `recipe_step` VALUES (502586, 300357, 12, '【炒制咖喱】翻炒 2 分钟，使香料与番茄融合', NULL);
INSERT INTO `recipe_step` VALUES (502587, 300357, 13, '【炒制咖喱】将煮好的红芸豆连同汤水一起倒入锅中', NULL);
INSERT INTO `recipe_step` VALUES (502588, 300357, 14, '【炒制咖喱】加入青辣椒，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502589, 300357, 15, '【炒制咖喱】大火煮沸后转小火，炖 15-20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502590, 300357, 16, '【炒制咖喱】期间用铲子背面压碎一部分豆子，使汤汁变得浓稠', NULL);
INSERT INTO `recipe_step` VALUES (502591, 300357, 17, '【炒制咖喱】加入印度综合香料粉 3g，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502592, 300357, 18, '【炒制咖喱】关火，撒上香菜叶', NULL);
INSERT INTO `recipe_step` VALUES (502593, 300357, 19, '【蒸米饭】将大米淘洗干净', NULL);
INSERT INTO `recipe_step` VALUES (502594, 300357, 20, '【蒸米饭】放入电饭锅，加入 400ml 水', NULL);
INSERT INTO `recipe_step` VALUES (502595, 300357, 21, '【蒸米饭】正常蒸煮即可', NULL);
INSERT INTO `recipe_step` VALUES (502596, 300357, 22, '【上菜】将米饭盛入盘中', NULL);
INSERT INTO `recipe_step` VALUES (502597, 300357, 23, '【上菜】将红芸豆咖喱浇在米饭上或旁边', NULL);
INSERT INTO `recipe_step` VALUES (502598, 300357, 24, '【上菜】可搭配洋葱沙拉和柠檬角', NULL);
INSERT INTO `recipe_step` VALUES (502599, 300358, 1, '放入上汽蒸柜中蒸制 5 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (502600, 300359, 1, '锅中混合90g菜籽油和40g熟猪油，烧至180℃；', NULL);
INSERT INTO `recipe_step` VALUES (502601, 300359, 2, '倒入1700g鸡块，煸炒至鸡块表面泛黄出油；', NULL);
INSERT INTO `recipe_step` VALUES (502602, 300359, 3, '下入60g姜片、60g拍蒜、50g剁椒，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (502603, 300359, 4, '下入毛豆烧鸡料快速翻炒使鸡块上色入味；', NULL);
INSERT INTO `recipe_step` VALUES (502604, 300359, 5, '加入水和120g皮冻烧开；', NULL);
INSERT INTO `recipe_step` VALUES (502605, 300359, 6, '下入750g豆米，大火收汁，出锅前加入30g葱段翻拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (502606, 300360, 1, '【切配准备】洋葱、胡萝卜、欧芹切 1cm 见方小丁', NULL);
INSERT INTO `recipe_step` VALUES (502607, 300360, 2, '【切配准备】红肠、马铃薯切 2cm 块', NULL);
INSERT INTO `recipe_step` VALUES (502608, 300360, 3, '【切配准备】包菜去梗后，手撕至 2cm 片', NULL);
INSERT INTO `recipe_step` VALUES (502609, 300360, 4, '【切配准备】牛肉撒盐 3 g 、黑胡椒 3 g 腌制 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502610, 300360, 5, '【煎制过程】平底锅烧热，加入植物油', NULL);
INSERT INTO `recipe_step` VALUES (502611, 300360, 6, '【煎制过程】煎制牛肉，直至表面焦黄色（可以带生，千万别糊了），取出备用。', NULL);
INSERT INTO `recipe_step` VALUES (502612, 300360, 7, '【烹制过程1（前一小时）】汤锅烧热，加入橄榄油、洋葱丁、胡萝卜丁、欧芹丁', NULL);
INSERT INTO `recipe_step` VALUES (502613, 300360, 8, '【烹制过程1（前一小时）】炒至洋葱透明，加入番茄膏、番茄罐头', NULL);
INSERT INTO `recipe_step` VALUES (502614, 300360, 9, '【烹制过程1（前一小时）】加入牛肉、马铃薯丁，翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (502615, 300360, 10, '【烹制过程1（前一小时）】加水没过食材，中火烹制 1 小时', NULL);
INSERT INTO `recipe_step` VALUES (502616, 300360, 11, '【烹制过程2（后半小时）】开锅加入包菜丁、红肠丁，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502617, 300360, 12, '【烹制过程2（后半小时）】中火烹制半小时', NULL);
INSERT INTO `recipe_step` VALUES (502618, 300360, 13, '【烹制过程2（后半小时）】开盖加入剩余 15 g 盐，混合均匀后盛盘', NULL);
INSERT INTO `recipe_step` VALUES (502619, 300361, 1, '羊肉冷水下锅焯水，水开了之后把血沫撇掉，捞出羊肉。', NULL);
INSERT INTO `recipe_step` VALUES (502620, 300361, 2, '切好生姜（ 4 片)，放入干辣椒与花椒在碗里备用。', NULL);
INSERT INTO `recipe_step` VALUES (502621, 300361, 3, '在炒锅加入油。（多一点也没关系）', NULL);
INSERT INTO `recipe_step` VALUES (502622, 300361, 4, '油热之后，放入白砂糖，给羊肉炒出焦糖色。', NULL);
INSERT INTO `recipe_step` VALUES (502623, 300361, 5, '羊肉水份炒干之后，放入盐、老抽，以及备好的调味料。', NULL);
INSERT INTO `recipe_step` VALUES (502624, 300361, 6, '加入清水没过羊肉，大火煮沸之后，让其继续煮 10 分钟，之后小火炖煮 30 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502625, 300361, 7, '在此期间，可以和面。和面的量以及操作方法在附加内容里讲解 （注 1）。', NULL);
INSERT INTO `recipe_step` VALUES (502626, 300361, 8, '放入青椒，甜椒，大葱，以及面皮进行翻炒。', NULL);
INSERT INTO `recipe_step` VALUES (502627, 300361, 9, '翻炒均匀之后，即可出锅。', NULL);
INSERT INTO `recipe_step` VALUES (502628, 300362, 1, '羊肉切成长 5cm 宽 0.5cm 的块', NULL);
INSERT INTO `recipe_step` VALUES (502629, 300362, 2, '大葱切成小段', NULL);
INSERT INTO `recipe_step` VALUES (502630, 300362, 3, '羊肉放入锅中，加入 1000ml 常温水，加入料酒、大葱', NULL);
INSERT INTO `recipe_step` VALUES (502631, 300362, 4, '煮沸 2 分钟后，捞出羊肉，使用常温水洗净，沥干水分', NULL);
INSERT INTO `recipe_step` VALUES (502632, 300362, 5, '热锅加入食用油，加入羊肉，翻炒 2 分钟至羊肉表面微黄', NULL);
INSERT INTO `recipe_step` VALUES (502633, 300362, 6, '加入开水，开到大火档位', NULL);
INSERT INTO `recipe_step` VALUES (502634, 300362, 7, '5 分钟后，加入白胡椒粉、盐，继续煮沸 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502635, 300362, 8, '出锅之后，加入香菜、孜然粉，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502636, 300363, 1, '鸡蛋打入大碗中，加盐搅打至起泡，静置 15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502637, 300363, 2, '黄油切小块入锅，倒入蛋液，开小火不断搅拌', NULL);
INSERT INTO `recipe_step` VALUES (502638, 300363, 3, '黄油一融化，就快速翻动蛋液，将其打碎成细密状，在蛋液大体凝固前关火', NULL);
INSERT INTO `recipe_step` VALUES (502639, 300363, 4, '加入牛奶搅拌 15 秒，至炒蛋湿润绵密，装盘', NULL);
INSERT INTO `recipe_step` VALUES (502640, 300364, 1, '全部猪肉用料酒、盐、生抽、生粉、胡椒粉倒在一个碗里调味，备用', NULL);
INSERT INTO `recipe_step` VALUES (502641, 300364, 2, '热锅不放油，下全部酸笋把水份炒干，炒干的酸笋中间留点空间', NULL);
INSERT INTO `recipe_step` VALUES (502642, 300364, 3, '放入 10ml - 15ml 食用油与全部大蒜、 剁椒、 豆豉到炒干的酸笋中间，全部推到中间炒出香味', NULL);
INSERT INTO `recipe_step` VALUES (502643, 300364, 4, '放入全部调味好的猪肉，持续放入 10ml 生抽炒一分钟', NULL);
INSERT INTO `recipe_step` VALUES (502644, 300364, 5, '放入 5ml 米醋、 10ml 生抽、450ml 清水一起煮开', NULL);
INSERT INTO `recipe_step` VALUES (502645, 300364, 6, '水煮开后，放入温水泡好的米粉，继续煮 3 分钟就可以盛盘', NULL);
INSERT INTO `recipe_step` VALUES (502646, 300365, 1, '【开始制作】200g 白芸豆提前一晚清水浸泡备用', NULL);
INSERT INTO `recipe_step` VALUES (502647, 300365, 2, '【开始制作】准备猪前蹄，买菜的时候让师傅从中间劈开，用喷火枪去除毛囊，拿回家清洗', NULL);
INSERT INTO `recipe_step` VALUES (502648, 300365, 3, '【开始制作】冷水锅中加入猪蹄、大葱段、姜片、料酒，焯水十分钟，撇去浮沫，捞出洗干净备用', NULL);
INSERT INTO `recipe_step` VALUES (502649, 300365, 4, '【开始制作】高压锅中放入猪蹄、当归、白芷、白胡椒粉、姜片，上汽后压三十分钟，放入白芸豆，再压十分钟，这个时候如果汤底是奶白色，那么恭喜是正确的（如果中途需要加水，只能加热水）', NULL);
INSERT INTO `recipe_step` VALUES (502650, 300365, 5, '【开始制作】揭盖后加入盐、鸡精、葱花调味', NULL);
INSERT INTO `recipe_step` VALUES (502651, 300365, 6, '【开始制作】调制灵魂汁子：放入葱、蒜、小米椒，白胡椒粉、生抽、香醋、油泼辣子、花椒油、猪蹄原汤', NULL);
INSERT INTO `recipe_step` VALUES (502652, 300365, 7, '【开始制作】灵魂汁子，浇给', NULL);
INSERT INTO `recipe_step` VALUES (502653, 300366, 1, '将水倒入锅中并煮沸', NULL);
INSERT INTO `recipe_step` VALUES (502654, 300366, 2, '将面均匀放入锅中', NULL);
INSERT INTO `recipe_step` VALUES (502655, 300366, 3, '在煮的过程注意搅拌，避免面粘成一坨', NULL);
INSERT INTO `recipe_step` VALUES (502656, 300366, 4, '当用筷子挑起一根面且该面能自然地从筷子上滑落时再等 30 秒关火', NULL);
INSERT INTO `recipe_step` VALUES (502657, 300366, 5, '将面夹入碗中', NULL);
INSERT INTO `recipe_step` VALUES (502658, 300366, 6, '按照上面的计量放入老干妈和酱油', NULL);
INSERT INTO `recipe_step` VALUES (502659, 300366, 7, '用筷子将碗里的面、老干妈、酱油拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502660, 300366, 8, '吃', NULL);
INSERT INTO `recipe_step` VALUES (502661, 300367, 1, '处理猪肉： 将猪通脊肉切成厚度 8mm 的均匀肉片，去除白色筋膜。 用清水冲洗肉片，去除血水。 可选：加入小苏打 5g，抓匀，静置 5 分钟。 用清水冲洗 1-2 次，去除多余小苏打。', NULL);
INSERT INTO `recipe_step` VALUES (502662, 300367, 2, '腌制肉片： 在肉片中加入盐 3g、料酒 5ml，拌匀，腌制 15 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502663, 300367, 3, '挂浆： 方法一（推荐）： 将土豆淀粉 170g 加入过量清水，搅匀，静置 60 分钟，等待淀粉沉降分层。 倒出上层全部的的清水，保留底部淀粉浆（形如非牛顿流体）。 放入肉片，放入 5ml 清水，放入 3ml 食用油，搅拌均匀。 方法二： 将土豆淀粉 210g 和中筋面粉 70g 混合。 少量多次加入清水，搅拌至酸奶状，提起可拉丝，浆糊能在盆中堆积。 加入食用油 10ml，小苏打 1g，搅拌均匀。 将腌制好的肉片放入浆糊中，拌匀，使每片肉均匀裹上浆。', NULL);
INSERT INTO `recipe_step` VALUES (502664, 300367, 4, '调制糖醋汁： 混合白糖 65g、白醋 55g、生抽 4g、盐 2g，搅拌均匀，备用。 可选：水 4g、玉米淀粉 1.5g，用于糖醋汁更加粘稠。', NULL);
INSERT INTO `recipe_step` VALUES (502665, 300367, 5, '准备配菜： 大葱、姜、胡萝卜切丝，香菜切段，蒜切片。', NULL);
INSERT INTO `recipe_step` VALUES (502666, 300367, 6, '炸制肉片： 第一次炸制： 锅中加入食用油，加热至 170℃（六成热）。 将肉片逐片放入油中，炸至表面定型，表面挂浆不粘筷子，肉上浮，颜色浅黄，约 30 秒（取决于肉片大小），捞出备用。 第二次炸制： 油温升至 200℃（七成热）。 将所有肉片放入油中，炸至外壳金黄酥脆，约 30 秒，捞出备用。 第三次炸制（可选）： 油温升至 220℃（八成热）。 将肉片快速复炸，直到能看到肉片黄里透红，约 30 秒（取决于油温维持能力），增强酥脆度，捞出沥油。', NULL);
INSERT INTO `recipe_step` VALUES (502667, 300367, 7, '炒制： 锅中留 20ml 底油， 倒入调好的糖醋汁，大火加热至沸腾，熬至汤汁粘稠，约 30-60 秒。 可选：盛出 1/2 的糖醋汁，可以让后面翻炒更加方便 放入炸好的肉片、葱丝、蒜片、胡萝卜丝、香菜段，浇上前面盛出的糖醋汁，快速翻炒 3 次，使汤汁均匀裹在肉片上。', NULL);
INSERT INTO `recipe_step` VALUES (502668, 300367, 8, '出锅装盘： 将锅包肉盛入盘中，撒上白熟芝麻（可无），即可上桌。', NULL);
INSERT INTO `recipe_step` VALUES (502669, 300368, 1, '用盐揉搓鸡表皮，冷藏20 分钟；每500g 老母鸡，加入15g 盐、28g 调味料（鸡汤专用）、50g 鸡油、2500g 水，烧开后炖制60 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502670, 300368, 2, '将鲜Q 面、青菜放入面篓，煮熟；', NULL);
INSERT INTO `recipe_step` VALUES (502671, 300368, 3, '舀取350g 的老鸡汤放入碗中，加入面条、1 个老母鸡鸡腿、20g 青菜、1 个茶叶蛋，最后撒5g 葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (502672, 300369, 1, '蒸柜上汽后，蒸制 10 分钟，出品。', NULL);
INSERT INTO `recipe_step` VALUES (502673, 300370, 1, '蒸柜上汽后，蒸制10 分钟，出品。', NULL);
INSERT INTO `recipe_step` VALUES (502674, 300371, 1, '每只鸡用2g 盐均匀揉搓鸡表皮，冷藏20 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502675, 300371, 2, '每500g 老母鸡，加入16g 盐、60g 鸡油、2500g 水，烧开后炖制60 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502676, 300371, 3, '扬米面在温水浸泡8 小时，备用；', NULL);
INSERT INTO `recipe_step` VALUES (502677, 300371, 4, '面碗中舀取400g 老鸡汤，备用；', NULL);
INSERT INTO `recipe_step` VALUES (502678, 300371, 5, '将65g 鸡块、260g 扬米面、3 颗青菜、20g 蛋皮在沸水中煮15 秒，捞出，放入面碗中，撒上3g 葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (502679, 300372, 1, '每只鸡用 2g 盐均匀揉搓鸡表皮，冷藏 20 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502680, 300372, 2, '每 500g 老母鸡，加入 16g 盐、60g 鸡油、2500g 水，烧开后炖制 60 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502681, 300373, 1, '茉莉绿茶调配（推荐比例=茶 : 水 : 冰 = 1~2 : 50 : 30） 称量 2~4 克茶叶置于容器，加入 100 毫升开水，泡 6 分钟 往泡好的绿茶中放入 60 克冰块冷却，可搅拌加速冷却 待冰块消失后，将茶叶过滤得到茉莉绿茶茶水约 160 毫升', NULL);
INSERT INTO `recipe_step` VALUES (502682, 300373, 2, '正式调配 选择一个杯子，建议使用容量在大约 300 毫升的透明玻璃杯 取出耙耙柑的肉瓣，并将外皮剥去，取得果肉 取 130 克果肉和 130 毫升茉莉绿茶放入搅拌机中 倒入 10 克蔗糖糖浆（可选，如果喜甜可放） 封盖启动搅拌机，搅拌 20 秒后将搅拌产物倒入杯中 取一点果肉撕碎撒在液面上', NULL);
INSERT INTO `recipe_step` VALUES (502683, 300374, 1, '锅洗净，将2000g水和1包素鸡包调味料（含肉片）、1000g素鸡片倒入锅中烧开；', NULL);
INSERT INTO `recipe_step` VALUES (502684, 300374, 2, '烧开后转小火，下入拍蒜60g、木耳150g、白砂糖10g，烧制10分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (502685, 300375, 1, '煮好米饭，通常使用买米赠送的量杯，一杯米 240g', NULL);
INSERT INTO `recipe_step` VALUES (502686, 300375, 2, '锅中放油 30ml', NULL);
INSERT INTO `recipe_step` VALUES (502687, 300375, 3, '放入肉馅，调中火煎至两面微焦', NULL);
INSERT INTO `recipe_step` VALUES (502688, 300375, 4, '将鸡蛋打入锅中，不要打散，盖上锅盖', NULL);
INSERT INTO `recipe_step` VALUES (502689, 300375, 5, '调一个碗汁，碗中放入计算中的对应数量的老抽，生抽，醋，糖，红葱油，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502690, 300375, 6, '打开锅盖，将碗汁倒入锅中，等待三分钟', NULL);
INSERT INTO `recipe_step` VALUES (502691, 300375, 7, '关火，将肉蛋盖到米饭上', NULL);
INSERT INTO `recipe_step` VALUES (502692, 300375, 8, '安全检查，开始食用盖饭', NULL);
INSERT INTO `recipe_step` VALUES (502693, 300376, 1, '土豆切块为各边均为 3 cm 的立方体，青/红椒切成边长 4 cm 的菱形片，洋葱切成 3 cm 宽的月牙瓣，年糕切成 1 cm 厚片', NULL);
INSERT INTO `recipe_step` VALUES (502694, 300376, 2, '螃蟹切成 50-80 g 的块，裹薄淀粉，180 °C 油温炸 1 分钟捞出', NULL);
INSERT INTO `recipe_step` VALUES (502695, 300376, 3, '锅中放油，蒜姜干辣椒爆香，放所有酱料 + 冰糖小火炒出红油，注意别糊底', NULL);
INSERT INTO `recipe_step` VALUES (502696, 300376, 4, '加螃蟹、土豆、啤酒和清水，烧开转小火炖 12 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502697, 300376, 5, '放年糕和青红椒，开大火收汁到汤汁可以附着在物品表面，最后撒白胡椒粉', NULL);
INSERT INTO `recipe_step` VALUES (502698, 300377, 1, '在碗中加入猪肉末、料酒、生抽、白胡椒粉、鸡蛋和芝麻香油，搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (502699, 300377, 2, '将调好味的猪肉末铺在盘子里，肉末中间用勺子挖一个洞，往洞中打入 1 个鸡蛋。', NULL);
INSERT INTO `recipe_step` VALUES (502700, 300377, 3, '锅中加水至 1/4 高度，水烧开后，将盘子放入锅中，盖上锅盖，蒸 15 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502701, 300378, 1, '肉饼蒸蛋汁调配（9 份）：180g 老鸡汤、20g 生抽，搅拌均匀；', NULL);
INSERT INTO `recipe_step` VALUES (502702, 300378, 2, '肉馅调配（9 份）：取 1000g 调理肉丝剁碎，加入 10g 鸡精和 100g 水，搅拌上劲后再加 100g 水，再次搅拌上劲，加入 20g 淀粉，搅拌均匀；', NULL);
INSERT INTO `recipe_step` VALUES (502703, 300378, 3, '肉饼蒸蛋操作（1份）：在餐具中放130g肉馅，用汤勺将肉馅中心部按压出凹陷小窝，并打入一颗鸡蛋；', NULL);
INSERT INTO `recipe_step` VALUES (502704, 300378, 4, '蒸柜上汽后，蒸制 15 分钟，出品时撒 1g 葱花和 1g 红椒', NULL);
INSERT INTO `recipe_step` VALUES (502705, 300379, 1, '调味水调配（10份）：调味料（鸡汤专用）10g，生抽10g、白开水250g。', NULL);
INSERT INTO `recipe_step` VALUES (502706, 300379, 2, '肉馅调配（10份）：取1300g调理肉馅，加入150g水，顺时针搅拌上劲；', NULL);
INSERT INTO `recipe_step` VALUES (502707, 300379, 3, '肉饼蒸蛋制作（1份）：称取130g肉馅，平铺在餐具底部，在肉饼中心处打入一颗鸡蛋；蒸柜上汽后，蒸制15分钟，出品时浇淋25g调味水，撒1g葱花和1g红椒丁点缀。', NULL);
INSERT INTO `recipe_step` VALUES (502708, 300380, 1, '调味水调配（10份）：调味料（鸡汤专用）10g，生抽10g、白开水250g。', NULL);
INSERT INTO `recipe_step` VALUES (502709, 300380, 2, '肉馅调配（10份）：取1300g调理肉馅，加入150g水，顺时针搅拌上劲；', NULL);
INSERT INTO `recipe_step` VALUES (502710, 300380, 3, '肉饼蒸蛋制作（1份）：称取130g肉馅，平铺在餐具底部，在肉饼中心处打入一颗鸡蛋；蒸柜上汽后，蒸制15分钟，出品时浇淋25g调味水，撒1g葱花和1g红椒丁点缀。', NULL);
INSERT INTO `recipe_step` VALUES (502711, 300381, 1, '【鸡块制作】下入 350g 菜籽油、200g 猪油、清洗好沥干水分的 3200g 鸡块，煸炒至表皮微黄；', NULL);
INSERT INTO `recipe_step` VALUES (502712, 300381, 2, '【鸡块制作】下入 50g 葱、140g 姜、200g 蒜，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (502713, 300381, 3, '【鸡块制作】下入 800g 肥肠鸡酱料，翻炒均匀；', NULL);
INSERT INTO `recipe_step` VALUES (502714, 300381, 4, '【鸡块制作】下入 3000g 水、40g 盐，煮制 2 分钟即可倒出，鸡块和汤备用。', NULL);
INSERT INTO `recipe_step` VALUES (502715, 300381, 5, '【配菜制作】锅中加入适量的水和盐，烧开后倒入蔬菜；', NULL);
INSERT INTO `recipe_step` VALUES (502716, 300381, 6, '【配菜制作】再次烧开后煮制 1 分钟，捞出冲凉备用。', NULL);
INSERT INTO `recipe_step` VALUES (502717, 300381, 7, '【肥肠鸡制作】将泡发好的 50g 宽粉和焯水后的 60g 土豆片、80g 莴笋片烫制20 秒，沥干水分放入盘中；', NULL);
INSERT INTO `recipe_step` VALUES (502718, 300381, 8, '【肥肠鸡制作】锅中放入 200g 煮制鸡块、80g 肥肠、70g 芋艿、250g 汤、50g泡菜，煮制 3 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502719, 300381, 9, '【肥肠鸡制作】再下入 8g 线椒、5g 鲜红小米辣、10g 芝麻香油、5g 花椒油，继续煮制 1 分钟，关火倒入盘中；', NULL);
INSERT INTO `recipe_step` VALUES (502720, 300381, 10, '【肥肠鸡制作】向 20g 热大豆油加入 2g 干青花椒、5g 干红辣椒段，炸出糊辣味后均匀淋到菜上；', NULL);
INSERT INTO `recipe_step` VALUES (502721, 300381, 11, '【肥肠鸡制作】最后点缀 5g 白芝麻、5g 香菜段，即可出品。', NULL);
INSERT INTO `recipe_step` VALUES (502722, 300382, 1, '每 1 只鸡使用 2g 盐均匀揉搓鸡的表皮，处理后冷藏 20 分钟;', NULL);
INSERT INTO `recipe_step` VALUES (502723, 300382, 2, '在锅中加入 1 只鸡、75g 鸡油料、5500g 农夫山泉水炖煮20分钟（根据鸡的大小，调味品适度增减）;', NULL);
INSERT INTO `recipe_step` VALUES (502724, 300382, 3, '将肥西老母鸡捞出后冷却至常温，剁成 1.0cm×2.0cm×3.0cm 的块状;', NULL);
INSERT INTO `recipe_step` VALUES (502725, 300382, 4, '剁好的鸡块放入汤中，加入 35g 盐炖煮 15 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502726, 300382, 5, '出品前捞去浮沫。', NULL);
INSERT INTO `recipe_step` VALUES (502727, 300383, 1, '每只鸡用2g 盐均匀揉搓鸡表皮，冷藏20 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502728, 300383, 2, '每500g 老母鸡，加入16g 盐、60g 鸡油、2500g 水，烧开后炖制60 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502729, 300383, 3, '将130g 鲜面和25g 青菜在沸水中煮2 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502730, 300383, 4, '舀取350g 的老鸡汤于面碗中，放入煮好的面条和配菜；', NULL);
INSERT INTO `recipe_step` VALUES (502731, 300383, 5, '将60g 鸡丝、25g 青菜和20g 蛋皮依次摆放在面条上，撒上5g 葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (502732, 300384, 1, '锅中混合100g 大豆油、50g 熟猪油,烧至油温160℃；', NULL);
INSERT INTO `recipe_step` VALUES (502733, 300384, 2, '下入1500g 胡萝卜片、60g 生抽、6g 盐、6g 鸡精、300g 木耳，大火爆炒至熟透；', NULL);
INSERT INTO `recipe_step` VALUES (502734, 300384, 3, '3. 下入100g 蒜花，翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (502735, 300385, 1, '下入150g大豆油炒肉丝，将500g肉丝炒至变色；', NULL);
INSERT INTO `recipe_step` VALUES (502736, 300385, 2, '下入60g蒜子、20g剁椒，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (502737, 300385, 3, '下入900g胡萝卜丝、10g盐、10g鸡精、5g老抽，大火爆炒至全熟；', NULL);
INSERT INTO `recipe_step` VALUES (502738, 300385, 4, '最后下入30g香葱段，翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (502739, 300386, 1, '下入 160g 大豆油烧肉，将 400g 肉片炒至变色；', NULL);
INSERT INTO `recipe_step` VALUES (502740, 300386, 2, '下入 1300g 胡萝卜片和 100g 木耳，加入 60g 生抽、6g 盐、6g 鸡精，大火爆炒至全熟；', NULL);
INSERT INTO `recipe_step` VALUES (502741, 300386, 3, '最后下入 100g 蒜花，翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (502742, 300387, 1, '下入 200g 大豆油、600g 鸡蛋液，炒成鸡蛋片，出锅备用；', NULL);
INSERT INTO `recipe_step` VALUES (502743, 300387, 2, '下入 100g 大豆油、1500g 胡萝卜丝、14g 盐、14g 鸡精，炒制 2 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502744, 300387, 3, '最后下入鸡蛋片，大火爆炒 1 分 40 秒，最后下入 30g 葱段，翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (502745, 300388, 1, '餐具中加入 110g 胡萝卜片；', NULL);
INSERT INTO `recipe_step` VALUES (502746, 300388, 2, '取 55g 红烧牛肉片平铺在胡萝卜上，再加入 70g 红烧牛肉汤汁；', NULL);
INSERT INTO `recipe_step` VALUES (502747, 300388, 3, '蒸柜上汽后，蒸制 25 分钟，出品时撒 1g 葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (502748, 300389, 1, '将胡萝卜去皮，用刨丝器刨成细丝', NULL);
INSERT INTO `recipe_step` VALUES (502749, 300389, 2, '在厚底锅中倒入酥油 20g（一半量），中火加热融化', NULL);
INSERT INTO `recipe_step` VALUES (502750, 300389, 3, '放入胡萝卜丝，翻炒 3-5 分钟，直至胡萝卜丝变软且散发香味', NULL);
INSERT INTO `recipe_step` VALUES (502751, 300389, 4, '倒入全脂牛奶 500ml，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502752, 300389, 5, '大火煮沸后转中小火，保持缓慢沸腾状态', NULL);
INSERT INTO `recipe_step` VALUES (502753, 300389, 6, '持续翻搅 25-30 分钟，直至牛奶几乎完全被胡萝卜吸收蒸发（这是最关键的步骤，需要耐心且不断搅拌防止糊底）', NULL);
INSERT INTO `recipe_step` VALUES (502754, 300389, 7, '当锅中几乎没有液体时，加入糖 80g，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502755, 300389, 8, '加糖后会重新出水，继续中小火翻炒 5-8 分钟，直至水分再次蒸发', NULL);
INSERT INTO `recipe_step` VALUES (502756, 300389, 9, '加入剩余的酥油 20g 和小豆蔻粉 3g，翻炒 2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502757, 300389, 10, '在另一个小锅中，用少量酥油将腰果、杏仁片和葡萄干分别炸至金黄（约 1 分钟），注意葡萄干会膨胀', NULL);
INSERT INTO `recipe_step` VALUES (502758, 300389, 11, '将炸好的坚果和葡萄干的一半拌入胡萝卜甜糕中', NULL);
INSERT INTO `recipe_step` VALUES (502759, 300389, 12, '盛盘，将剩余坚果和葡萄干撒在表面作为装饰', NULL);
INSERT INTO `recipe_step` VALUES (502760, 300390, 1, '鸡蛋搅拌形成蛋液放置备用', NULL);
INSERT INTO `recipe_step` VALUES (502761, 300390, 2, '配置酱料 （20 g 生抽+10 g 蚝油+5 g 老抽+10 g 白糖+10 g 玉米淀粉+200 ml 清水）', NULL);
INSERT INTO `recipe_step` VALUES (502762, 300390, 3, '老豆腐切片 （个人建议，仅供参考 人 5 片，厚度 1.2 cm）', NULL);
INSERT INTO `recipe_step` VALUES (502763, 300390, 4, '玉米淀粉倒入盘中，将老豆腐片粘上淀粉后，粘上蛋液，放置一旁', NULL);
INSERT INTO `recipe_step` VALUES (502764, 300390, 5, '热锅，锅内放入 18ml 食用油。等待 10 秒让油温升高', NULL);
INSERT INTO `recipe_step` VALUES (502765, 300390, 6, '将粘上蛋液的老豆腐片均匀放入锅中，铺好锅底，小火煎至金黄翻面', NULL);
INSERT INTO `recipe_step` VALUES (502766, 300390, 7, '待两面煎至金黄后，倒入酱料，让每块豆腐都沐浴在酱料中，大火 3 分钟至酱汁浓稠', NULL);
INSERT INTO `recipe_step` VALUES (502767, 300390, 8, '关火', NULL);
INSERT INTO `recipe_step` VALUES (502768, 300391, 1, '鸡翅放入170℃的油锅中炸制4分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502769, 300392, 1, '提前洗净好绿豆、红豆、花生、黄豆、豌豆、红腰豆，并用干净的玻璃碗盛放好，注入 3/4 玻璃碗大小的饮用水，浸泡一夜（或最少 8 小时）。', NULL);
INSERT INTO `recipe_step` VALUES (502770, 300392, 2, '提前洗净好大米、糯米、薏米、黑米、小米、莲子，并用干净的玻璃碗盛放好，注入 3/4 玻璃碗大小的饮用水，浸泡 3 小时。', NULL);
INSERT INTO `recipe_step` VALUES (502771, 300392, 3, '将步骤 1 中准备好的盛有绿豆、红豆、花生、黄豆、豌豆、红腰豆的玻璃碗中的水分分离倒出，其余原料倒入粥锅中，加入 1 升饮用水（或漫过食材 1 拇指块），大火煮沸，煮沸后合上锅盖，小火煮 30 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502772, 300392, 4, '将步骤 2 中准备好的盛有大米、糯米、薏米、黑米、小米、莲子的玻璃碗中的水分分离倒出，其余原料继续倒入粥锅中，合上锅盖，小火煮 60 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502773, 300392, 5, '洗净好红枣、桂圆、栗子、核桃、葡萄干（其中红枣切成小片）、冰糖，倒入锅中，合上锅盖，小火煮 60 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502774, 300392, 6, '确认煮出的粥粘稠后即可关火、盛盘、食用。', NULL);
INSERT INTO `recipe_step` VALUES (502775, 300393, 1, '五花肉切成长宽 2.5 cm 的小块', NULL);
INSERT INTO `recipe_step` VALUES (502776, 300393, 2, '冷水放料酒姜片，五花肉放入开火慢慢加入到水沸腾后捞出', NULL);
INSERT INTO `recipe_step` VALUES (502777, 300393, 3, '玫瑰腐乳块和腐乳汁碾成泥，加冰糖、老抽调成酱汁', NULL);
INSERT INTO `recipe_step` VALUES (502778, 300393, 4, '热锅冷油爆香葱姜，下肉块煸到金黄', NULL);
INSERT INTO `recipe_step` VALUES (502779, 300393, 5, '倒入腐乳酱炒匀加热水焖煮', NULL);
INSERT INTO `recipe_step` VALUES (502780, 300393, 6, '小火慢炖 40 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502781, 300393, 7, '大火收汁，看到汤汁冒浓稠鱼眼泡时关火', NULL);
INSERT INTO `recipe_step` VALUES (502782, 300394, 1, '【鸡块制作】下入 350g 菜籽油、200g 猪油、清洗好沥干水分的 3200g 鸡块，煸炒至表皮微黄；', NULL);
INSERT INTO `recipe_step` VALUES (502783, 300394, 2, '【鸡块制作】下入 50g 葱、140g 姜、200g 蒜，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (502784, 300394, 3, '【鸡块制作】下入 800g 肥肠鸡酱料，翻炒均匀；', NULL);
INSERT INTO `recipe_step` VALUES (502785, 300394, 4, '【鸡块制作】下入 3000g 水、40g 盐、60g 鸡精，煮制 2 分钟即可倒出，鸡块和汤备用。', NULL);
INSERT INTO `recipe_step` VALUES (502786, 300394, 5, '【配菜制作】锅中加入适量的水和盐，烧开后倒入蔬菜；', NULL);
INSERT INTO `recipe_step` VALUES (502787, 300394, 6, '【配菜制作】再次烧开后煮制 1 分钟，捞出冲凉备用。', NULL);
INSERT INTO `recipe_step` VALUES (502788, 300394, 7, '【芋儿鸡制作】将泡发好的 50g 宽粉和焯水后 60g 土豆片、80g 莴笋片烫制 20秒，沥干水分放入盘中；', NULL);
INSERT INTO `recipe_step` VALUES (502789, 300394, 8, '【芋儿鸡制作】锅中放入 200g 煮制鸡块、70g 芋艿、250g 汤、50g 泡菜，煮制3 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502790, 300394, 9, '【芋儿鸡制作】再下入 8g 线椒、5g 鲜红小米辣、10g 芝麻香油、5g 花椒油，继续煮制 1 分钟，关火倒入盘中；', NULL);
INSERT INTO `recipe_step` VALUES (502791, 300394, 10, '【芋儿鸡制作】向 20g 热大豆油加入 2g 干青花椒、5g 干红辣椒段，炸出糊辣味后均匀淋到菜上；', NULL);
INSERT INTO `recipe_step` VALUES (502792, 300394, 11, '【芋儿鸡制作】最后点缀 5g 白芝麻、5g 香菜段，即可出品。', NULL);
INSERT INTO `recipe_step` VALUES (502793, 300395, 1, '芋头切块，大火煮熟至软（40 分钟即可），全部放入料理机', NULL);
INSERT INTO `recipe_step` VALUES (502794, 300395, 2, '向内加入 30g 牛奶，25g 淡奶油，将其打成泥状', NULL);
INSERT INTO `recipe_step` VALUES (502795, 300395, 3, '再向内加入 3g 紫薯粉，18g 白砂糖，继续搅拌打成细腻芋泥', NULL);
INSERT INTO `recipe_step` VALUES (502796, 300395, 4, '取出另一个碗，加入全部糯米粉 b，22g 玉米淀粉，135g 牛奶，50g 白砂糖，混匀并过筛一遍，保鲜膜盖上并扎小洞，中火蒸半个小时', NULL);
INSERT INTO `recipe_step` VALUES (502797, 300395, 5, '在蒸的过程中，将糯米粉 a 放入平底锅小火翻炒至微微发黄（即炒熟），作为手粉备用', NULL);
INSERT INTO `recipe_step` VALUES (502798, 300395, 6, '将中火蒸完半小时的糯米牛奶混合物（果冻状）趁热加入黄油 30g，将黄油揉至面团完全吸收，然后放冰箱冷藏一小时', NULL);
INSERT INTO `recipe_step` VALUES (502799, 300395, 7, '取出另一只碗，加入 120g 淡奶油，8g 白砂糖，打发至有纹路，装进裱花袋备用', NULL);
INSERT INTO `recipe_step` VALUES (502800, 300395, 8, '取出冷藏后的面团，搓揉 5 分钟，分成 30g 一个，均匀撒上 2g 手粉防粘，擀成圆形，先挤上 5g 裱花奶油，然后放上 30g 芋泥，最后将面饼像包包子一样包起来（可以减去多余的皮）', NULL);
INSERT INTO `recipe_step` VALUES (502801, 300395, 9, '包好后再均匀撒 2g 手粉防粘', NULL);
INSERT INTO `recipe_step` VALUES (502802, 300395, 10, '重复以上两步直至原材料用光', NULL);
INSERT INTO `recipe_step` VALUES (502803, 300396, 1, '面团：300 克面粉，3 克酵母粉，3 克白糖，180 克温水，20 克食用油，醒面 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502804, 300396, 2, '油酥：小碗放 30 克面粉，2 克盐，4 克十三香，20 克食用油，拌匀后，静置', NULL);
INSERT INTO `recipe_step` VALUES (502805, 300396, 3, '做饼：面擀成长方形，抹上调好的油酥，从一头卷起，切成 7 个面剂子，对折，用虎口收拢即可，先沾水再沾白芝麻，擀成小圆饼', NULL);
INSERT INTO `recipe_step` VALUES (502806, 300396, 4, '烙饼：将电饼铛预热，倒入凉油（锅底铺满油），将擀好的饼放入电饼铛中，将饼的上方也刷点油，涂抹均匀盖上盖子，选大饼档,听到叮的一声出锅即可', NULL);
INSERT INTO `recipe_step` VALUES (502807, 300397, 1, '处理虾： 将虾从背部切开，去除虾线和沙袋，也可从腹部切开，炸出来会胀开，成菜比较漂亮 用清水洗干净，控干水分后可拍上生粉，也可不拍', NULL);
INSERT INTO `recipe_step` VALUES (502808, 300397, 2, '蒜蓉及碗汁处理： 将 2 颗大蒜切成蒜末 准备碗汁，放入生抽、蚝油、白糖、胡椒粉、盐，依据个人口味挤入芥末，加清水稀释后加入生粉化开', NULL);
INSERT INTO `recipe_step` VALUES (502809, 300397, 3, '炒制过程： 锅热倒入食用油，大概能覆盖锅底 放入控干水分的罗氏虾，慢慢煎制 虾油煎出来后（表现为锅中出现大量气泡），加入准备好的蒜蓉及小米辣 闻到蒜蓉的香味后，加入黄油 黄油融化后翻拌均匀，加入准备好的碗汁 盖锅盖焖煮 2 分钟汤汁浓稠后出锅', NULL);
INSERT INTO `recipe_step` VALUES (502810, 300398, 1, '将罗氏虾剪掉头尾尖刺、触须和脚，剪刀把虾身开背，去除虾线。', NULL);
INSERT INTO `recipe_step` VALUES (502811, 300398, 2, '提前搅拌好芥末酱汁：酱油、蚝油、芥末、盐、糖，搅拌均匀！', NULL);
INSERT INTO `recipe_step` VALUES (502812, 300398, 3, '洗好香菜，切段备用。', NULL);
INSERT INTO `recipe_step` VALUES (502813, 300398, 4, '罗氏虾沥干水，锅中加入油，直接放入罗氏虾，中火，外表煎至金黄，捞出。', NULL);
INSERT INTO `recipe_step` VALUES (502814, 300398, 5, '下入蒜蓉，大火，利用煎虾剩下的油继续煎炒蒜蓉，等到锅中白雾冒出，蒜蓉已经煎出香味，下虾和黄油，让虾充分吸收黄油香味', NULL);
INSERT INTO `recipe_step` VALUES (502815, 300398, 6, '下入调好的酱汁，继续大火煮沸，翻炒虾，至酱汁收汁，加入酒（料酒、啤酒可以放 30g，朗姆酒味道浓郁放 15g 即可。）', NULL);
INSERT INTO `recipe_step` VALUES (502816, 300398, 7, '在等酱汁稍微收汁，加入香菜翻炒两下，即可出锅。', NULL);
INSERT INTO `recipe_step` VALUES (502817, 300399, 1, '蒸柜上汽后，蒸制10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502818, 300400, 1, '（如果是芹菜苗这一步略过）用热水壶烧一壶热水，备用', NULL);
INSERT INTO `recipe_step` VALUES (502819, 300400, 2, '新鲜的芹菜苗或者芹菜摘去黄叶清洗，备用', NULL);
INSERT INTO `recipe_step` VALUES (502820, 300400, 3, '（如果是芹菜苗这一步略过）将芹菜摘去叶子单独放一个盆中，将芹菜茎用刀划成 2-3 毫米宽的芹菜条备用，这一步的目的是让芹菜断生的更快更均匀，吃起来更脆更爽口', NULL);
INSERT INTO `recipe_step` VALUES (502821, 300400, 4, '芹菜苗切成 4cm 的芹菜段，备用', NULL);
INSERT INTO `recipe_step` VALUES (502822, 300400, 5, '（如果是芹菜苗这一步略过）起锅开火，将热水壶的开水倒入锅中待水起泡沸腾', NULL);
INSERT INTO `recipe_step` VALUES (502823, 300400, 6, '（如果是芹菜苗这一步略过）将切好的芹菜条放入锅中焯水，大约 20 秒放入芹菜叶,5 秒后关火全部捞出过凉水，备用', NULL);
INSERT INTO `recipe_step` VALUES (502824, 300400, 7, '将盆中焯好的芹菜或者芹菜苗撒上准备好的食盐，香油，蚝油和味极鲜搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502825, 300400, 8, '将茶树菇倒入盆中搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502826, 300400, 9, '装盘', NULL);
INSERT INTO `recipe_step` VALUES (502827, 300400, 10, '开吃', NULL);
INSERT INTO `recipe_step` VALUES (502828, 300401, 1, '下入 120g 大豆油、1100g 芹菜、500g 香干、60g 红椒、15g 盐、10g 鸡精', NULL);
INSERT INTO `recipe_step` VALUES (502829, 300401, 2, '大火爆炒 3 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (502830, 300402, 1, '下入 150g 大豆油、350g 调理肉丝，炒至肉丝变色；', NULL);
INSERT INTO `recipe_step` VALUES (502831, 300402, 2, '下入 5g 老抽，炒至肉丝上色；', NULL);
INSERT INTO `recipe_step` VALUES (502832, 300402, 3, '最后下入 1000g 芹菜、500g 香干、60g 红椒、15g 盐、10g 鸡精，大火爆炒 2 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (502833, 300403, 1, '用冷水下锅水开 3 分钟后捞出', NULL);
INSERT INTO `recipe_step` VALUES (502834, 300403, 2, '鸡蛋捞出，放入冰水中剥壳更快速也更完整', NULL);
INSERT INTO `recipe_step` VALUES (502835, 300403, 3, '用芝士片包裹鸡蛋', NULL);
INSERT INTO `recipe_step` VALUES (502836, 300403, 4, '培根片包裹鸡蛋', NULL);
INSERT INTO `recipe_step` VALUES (502837, 300403, 5, '手抓饼两端切除以矩形包裹鸡蛋', NULL);
INSERT INTO `recipe_step` VALUES (502838, 300403, 6, '油温 6 成下锅（油面波动，有青烟，筷子插入油中周围泛起气泡即是 6 成温度） 炸制金黄即可', NULL);
INSERT INTO `recipe_step` VALUES (502839, 300403, 7, '空气炸锅 160 度 15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502840, 300403, 8, '切开即可食用', NULL);
INSERT INTO `recipe_step` VALUES (502841, 300404, 1, '鸡蛋打散，称量出 30g 蛋液放入干净容器中，放入全量淡奶油和奶油奶酪混合均匀。如果奶酪太硬可以水浴加热至大约 40 度再混合。', NULL);
INSERT INTO `recipe_step` VALUES (502842, 300404, 2, '将低筋面粉，盐，糖，泡打粉放入干净容器中混合均匀', NULL);
INSERT INTO `recipe_step` VALUES (502843, 300404, 3, '黄油切成小块，放入上一步的混合物中，用手将黄油捏入混合物中，呈粗玉米粉质地', NULL);
INSERT INTO `recipe_step` VALUES (502844, 300404, 4, '将第一步的蛋奶混合液倒入上一步得到的粉油混合物种，搅拌均接近。叠压成均匀面团', NULL);
INSERT INTO `recipe_step` VALUES (502845, 300404, 5, '面团放到案板上，擀成 1.5cm 厚的面片，用刀或者模具分切成合适的形状', NULL);
INSERT INTO `recipe_step` VALUES (502846, 300404, 6, '用刷子蘸取剩余的 20g 鸡蛋液，刷在司康表面', NULL);
INSERT INTO `recipe_step` VALUES (502847, 300404, 7, '烤箱预热 180 度，烤制 27 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502848, 300405, 1, '放入 1 包茶包（3g)，倒入 150ml 开水，盖上盖子闷泡 3 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502849, 300405, 2, '捞出茶包 （茶包不可重复使用）。', NULL);
INSERT INTO `recipe_step` VALUES (502850, 300406, 1, '将茄子、土豆、辣椒洗净，蒜扒皮并拍碎。', NULL);
INSERT INTO `recipe_step` VALUES (502851, 300406, 2, '将茄子、土豆切成约 6 立方厘米的块，辣椒切成 5 克的小块，肉切成 3 厘米的丝。', NULL);
INSERT INTO `recipe_step` VALUES (502852, 300406, 3, '开火，热锅，加入份数 13 毫升的油。', NULL);
INSERT INTO `recipe_step` VALUES (502853, 300406, 4, '当能看到锅里的油冒出一丝烟时，放入辣椒。', NULL);
INSERT INTO `recipe_step` VALUES (502854, 300406, 5, '煸出辣椒香气后，立刻放入肉，用铲子翻炒 30 秒。', NULL);
INSERT INTO `recipe_step` VALUES (502855, 300406, 6, '放入土豆，翻炒 30 秒。', NULL);
INSERT INTO `recipe_step` VALUES (502856, 300406, 7, '放入茄子，翻炒 30 秒。', NULL);
INSERT INTO `recipe_step` VALUES (502857, 300406, 8, '放入酱油和盐，继续翻炒 5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502858, 300406, 9, '加入水，水面高度为锅内食材高度的 0.9 倍，并盖上锅盖。', NULL);
INSERT INTO `recipe_step` VALUES (502859, 300406, 10, '等待，直到锅内水的高度剩余食材高度的 0.1 倍时，开盖，放入蒜，搅拌均匀，关火。', NULL);
INSERT INTO `recipe_step` VALUES (502860, 300407, 1, '将茄子去皮后切成片，将腊肉切成片，备用', NULL);
INSERT INTO `recipe_step` VALUES (502861, 300407, 2, '依次向盆中加入 250g 米粉（大米研磨成的粉）、50g 面粉和 1 个鸡蛋', NULL);
INSERT INTO `recipe_step` VALUES (502862, 300407, 3, '边用筷子搅拌，边加入清水（清水用于调节粘稠度），使米粉、面粉、鸡蛋混合成面糊,当面糊能够附着在茄片、肉片上而不掉落时停止加水，而后将所有茄片和肉片放入面糊中，用面糊充分包裹', NULL);
INSERT INTO `recipe_step` VALUES (502863, 300407, 4, '平底锅加入食用油10-30ml，开小火', NULL);
INSERT INTO `recipe_step` VALUES (502864, 300407, 5, '用筷子或勺子把裹了面糊的茄片、肉片放入锅中，先煎至两面金黄，再煎3-6分钟（煎的过程中，食用油会变少，可再添加食用油）', NULL);
INSERT INTO `recipe_step` VALUES (502865, 300407, 6, '撒盐，翻炒均匀，起锅装盘', NULL);
INSERT INTO `recipe_step` VALUES (502866, 300408, 1, '【准备】茭白切片，每片厚度 0.5 cm', NULL);
INSERT INTO `recipe_step` VALUES (502867, 300408, 2, '【准备】瘦肉切条，厚度 0.3-0.5 cm，加入料酒、生粉、盐、水搅拌', NULL);
INSERT INTO `recipe_step` VALUES (502868, 300408, 3, '【准备】姜切片、蒜头剁碎', NULL);
INSERT INTO `recipe_step` VALUES (502869, 300408, 4, '【制作】起锅水烧开，放入茭白，水煮 60-90 S 后取出沥干', NULL);
INSERT INTO `recipe_step` VALUES (502870, 300408, 5, '【制作】起锅，倒入 15 ml 油，倒入瘦肉，反复翻炒 60 S 取出', NULL);
INSERT INTO `recipe_step` VALUES (502871, 300408, 6, '【制作】起锅，倒入 15 ml 油，倒入姜、蒜翻炒 30S，加入茭白继续翻炒 30 S', NULL);
INSERT INTO `recipe_step` VALUES (502872, 300408, 7, '【制作】继续加入瘦肉翻炒 60 S，加入 20 ml 水，加入盐、鸡精后翻炒 60S 出锅', NULL);
INSERT INTO `recipe_step` VALUES (502873, 300409, 1, '用冷水将鸡蛋煮熟，大火大约 8 分钟（根据自家厨具决定）', NULL);
INSERT INTO `recipe_step` VALUES (502874, 300409, 2, '鸡蛋捞出，过冷水', NULL);
INSERT INTO `recipe_step` VALUES (502875, 300409, 3, '将鸡蛋互相碰撞，使每个鸡蛋产生裂缝', NULL);
INSERT INTO `recipe_step` VALUES (502876, 300409, 4, '将鸡蛋下锅，放入八角，香叶，桂皮，茴香，冰糖，红茶，生抽，老抽，食盐', NULL);
INSERT INTO `recipe_step` VALUES (502877, 300409, 5, '加水直至没过鸡蛋', NULL);
INSERT INTO `recipe_step` VALUES (502878, 300409, 6, '大火煮开之后，转中小火煮 15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502879, 300410, 1, '先做草莓糖浆。把草莓洗干净，去掉顶部叶子。将草莓切成 5mm 的小块。保留一半切碎的草莓，稍后折叠成冰淇淋。', NULL);
INSERT INTO `recipe_step` VALUES (502880, 300410, 2, '将另一半切碎的草莓和糖一起放入酱汁锅中。用中火搅拌和烹饪，直到草莓释放液体并在锅中形成糖浆。', NULL);
INSERT INTO `recipe_step` VALUES (502881, 300410, 3, '让草莓在糖浆中加热，不时搅拌，直到它们分解并变形，糖浆稍微变稠。', NULL);
INSERT INTO `recipe_step` VALUES (502882, 300410, 4, '当糖浆保持分开 3秒钟 时，就已经准备好了。把糖浆从火上移开，加入香草和盐搅拌。将草莓糖浆放在一边冷却。', NULL);
INSERT INTO `recipe_step` VALUES (502883, 300410, 5, '当糖浆冷却时，准备冰淇淋基料。在碗中加入甜炼乳、浓奶油、香草精和盐。使用手动搅拌器搅打混合物，直到它变得轻盈蓬松，并形成柔软的尖峰。', NULL);
INSERT INTO `recipe_step` VALUES (502884, 300410, 6, '将保留的切碎的新鲜草莓折叠到冰淇淋底座中。将生过的冰淇淋底座转移到冷冻安全容器中。将冷却的草莓糖浆淋在冰淇淋上，然后轻轻地将其旋入混合物中。', NULL);
INSERT INTO `recipe_step` VALUES (502885, 300410, 7, '盖上冰淇淋并冷冻 八小时 ，然后舀取和食用。', NULL);
INSERT INTO `recipe_step` VALUES (502886, 300411, 1, '草莓洗净去叶', NULL);
INSERT INTO `recipe_step` VALUES (502887, 300411, 2, '将草莓切碎放入合适的碗中', NULL);
INSERT INTO `recipe_step` VALUES (502888, 300411, 3, '将白糖倒入碗中与草莓搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (502889, 300411, 4, '碗用保鲜膜覆盖静置 1 小时', NULL);
INSERT INTO `recipe_step` VALUES (502890, 300411, 5, '将静置的草莓和糖的混合物倒入不粘锅中开大火烧开', NULL);
INSERT INTO `recipe_step` VALUES (502891, 300411, 6, '烧开后转小火不断搅拌直至果酱呈粘稠状关火', NULL);
INSERT INTO `recipe_step` VALUES (502892, 300411, 7, '待草莓酱冷却后装入准备好的密封罐中', NULL);
INSERT INTO `recipe_step` VALUES (502893, 300412, 1, '瘦肉切块（每块 2-3 cm ），放入大碗中，加入鸡蛋 1 个 、生粉 50 g 、生抽 3 ml 、鸡精 2 g', NULL);
INSERT INTO `recipe_step` VALUES (502894, 300412, 2, '充分搅拌，直至生粉包裹住瘦肉块（太稀则继续加生粉，太干则加水），然后加入 5 ml 油，在充分搅拌后备用', NULL);
INSERT INTO `recipe_step` VALUES (502895, 300412, 3, '在准备一个碗，加入番茄酱、鸡精 3 g 、生抽 2 ml 、姜末、白砂糖、生粉 10 g \\香醋、凉水 200 ml ,充分搅拌后备用', NULL);
INSERT INTO `recipe_step` VALUES (502896, 300412, 4, '切一个凤梨, 准备 6 个 （每个 1.5-2 cm）凤梨块', NULL);
INSERT INTO `recipe_step` VALUES (502897, 300412, 5, '起锅烧油，倒入 500 ml 油，一直烧油直到听到油炸声', NULL);
INSERT INTO `recipe_step` VALUES (502898, 300412, 6, '将瘦肉一个一个放入锅中（切记不可以整碗倒入），保证每个肉不要粘在一起', NULL);
INSERT INTO `recipe_step` VALUES (502899, 300412, 7, '全部放入瘦肉后，每 30 S 用勺子来回两面翻转瘦肉块，直至瘦肉块表面金黄', NULL);
INSERT INTO `recipe_step` VALUES (502900, 300412, 8, '取出瘦肉，一分钟后倒入油锅中继续炸，直至瘦肉块表面出现焦黄后，取出放入大碗备用', NULL);
INSERT INTO `recipe_step` VALUES (502901, 300412, 9, '起锅，倒入汤汁，30 S 后倒入瘦肉块、凤梨块，充分翻炒后 出锅', NULL);
INSERT INTO `recipe_step` VALUES (502902, 300412, 10, '摆上芝麻', NULL);
INSERT INTO `recipe_step` VALUES (502903, 300413, 1, '蒸柜上汽后，蒸制 10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (502904, 300414, 1, '把荷兰豆去掉蒂，有时间的也可以同时把尾部去掉', NULL);
INSERT INTO `recipe_step` VALUES (502905, 300414, 2, '买腊肠之前可以问老板是生的还是熟的，如果是生的，需要提前蒸一下，如果是熟的可以直接使用', NULL);
INSERT INTO `recipe_step` VALUES (502906, 300414, 3, '把荷兰豆清洗一下，然后焯一下水，大概 45s，荷兰豆焯至变色即可，捞出过凉水备用', NULL);
INSERT INTO `recipe_step` VALUES (502907, 300414, 4, '热锅，锅内放入大约 10ml 食用油。等待 10 秒让油温升高', NULL);
INSERT INTO `recipe_step` VALUES (502908, 300414, 5, '放入腊肠，保持翻炒至腊肠微微卷边，注意这里一定要保持小火，小到不能小的那种，不然容易糊', NULL);
INSERT INTO `recipe_step` VALUES (502909, 300414, 6, '放入荷兰豆，转为中大火，翻炒 30s 放入生抽，接着再翻炒 20-30s 即可', NULL);
INSERT INTO `recipe_step` VALUES (502910, 300415, 1, '锅中倒入 200g 大豆油烧热，将 600g 鸡蛋液炒成鸡蛋片状，盛装出锅备用；', NULL);
INSERT INTO `recipe_step` VALUES (502911, 300415, 2, '锅中下入 50g 大豆油、1300g 莴笋丝、15g 盐、10g 鸡精，大火爆炒至莴笋丝断生；', NULL);
INSERT INTO `recipe_step` VALUES (502912, 300415, 3, '下入鸡蛋片，翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (502913, 300416, 1, '莴笋叶剁碎，加入鸡蛋、生粉、生抽、鸡精搅拌均匀备用', NULL);
INSERT INTO `recipe_step` VALUES (502914, 300416, 2, '起锅烧油，倒入莴笋叶浆汁，均匀平铺在锅面上', NULL);
INSERT INTO `recipe_step` VALUES (502915, 300416, 3, '第一面炸 120 S 后，翻面再炸 60 S 后出锅', NULL);
INSERT INTO `recipe_step` VALUES (502916, 300417, 1, '冷水洗干净热心摊主处理好的乳鸽', NULL);
INSERT INTO `recipe_step` VALUES (502917, 300417, 2, '冷水锅中放入洗干净的乳鸽，加入 15ml 料酒与姜，水煮开即可捞出乳鸽，要不然会丢失营养', NULL);
INSERT INTO `recipe_step` VALUES (502918, 300417, 3, '把乳鸽放到高压缩或者瓦罐中、倒入的水要没过乳鸽，放入生姜 20 g，玉米 200 g、菌菇 100 g', NULL);
INSERT INTO `recipe_step` VALUES (502919, 300417, 4, '时间到了，盛到碗中，加入 3~5g 盐 即可', NULL);
INSERT INTO `recipe_step` VALUES (502920, 300418, 1, '老母鸡鸡块用流水清洗干净。锅中放入足量水，下入鸡块，水烧开立即关火。鸡块捞出后冷水冲洗干净备用。', NULL);
INSERT INTO `recipe_step` VALUES (502921, 300418, 2, '取特色鸡汤盅，放入焯水后的老母鸡鸡块40g、菌菇混合包20g、姜片1g、菌菇鸡汤汤底320g，盖上鸡汤盅盖，再放入上汽蒸柜中蒸制90分钟，出品。', NULL);
INSERT INTO `recipe_step` VALUES (502922, 300419, 1, '菠菜去根，洗净，放在篮子里，焯水', NULL);
INSERT INTO `recipe_step` VALUES (502923, 300419, 2, '将鸡蛋打入碗中，搅匀', NULL);
INSERT INTO `recipe_step` VALUES (502924, 300419, 3, '热锅，加入 10ml 油', NULL);
INSERT INTO `recipe_step` VALUES (502925, 300419, 4, '油热后，倒入鸡蛋液，中火翻炒 15 秒，先煎成蛋饼，然后再用锅铲切成小块', NULL);
INSERT INTO `recipe_step` VALUES (502926, 300419, 5, '关火，将鸡蛋块 盛到盘子中，不要洗锅', NULL);
INSERT INTO `recipe_step` VALUES (502927, 300419, 6, '重新开火，倒入 5ml 油，油热后，放入菠菜，大火 翻炒 15 秒后，倒入鸡蛋块，翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (502928, 300419, 7, '加入 5g 盐、100ml 饮用水，大火 翻炒 10 秒', NULL);
INSERT INTO `recipe_step` VALUES (502929, 300419, 8, '关火，盛盘', NULL);
INSERT INTO `recipe_step` VALUES (502930, 300420, 1, '菠菜焯水：取 1330g 菠菜，在沸水中汆烫 60 秒捞出，纯净水冲凉，挤干水分，切成段状，备用；', NULL);
INSERT INTO `recipe_step` VALUES (502931, 300420, 2, '在备好的菠菜段、200g 蛋皮丝中加入 6g 盐、6g 鸡精、3g 白砂糖、10g 红椒、30g 芝麻香油、20g 大豆油，拌匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (502932, 300421, 1, '1200g 咕咾肉放入 170℃油中，炸至表面微黄，出锅备用；', NULL);
INSERT INTO `recipe_step` VALUES (502933, 300421, 2, '炒锅中下入 80g 大豆油，将 500g 果味糖醋酱烧沸，下入 600g 菠萝块炒至菠萝中心完全受热；', NULL);
INSERT INTO `recipe_step` VALUES (502934, 300421, 3, '下入炸好的咕咾肉，炒至咕咾肉均匀裹上果味糖醋酱。', NULL);
INSERT INTO `recipe_step` VALUES (502935, 300422, 1, '炒饭：', NULL);
INSERT INTO `recipe_step` VALUES (502936, 300422, 2, '组合：', NULL);
INSERT INTO `recipe_step` VALUES (502937, 300423, 1, '杯子里依次加入冰块，咖啡液，菠萝汁和苏打水', NULL);
INSERT INTO `recipe_step` VALUES (502938, 300423, 2, '奶油加糖打发至湿性发泡，加入朗姆酒和牛奶均匀只有流动性', NULL);
INSERT INTO `recipe_step` VALUES (502939, 300423, 3, '在第一部混合液上方倒入奶油', NULL);
INSERT INTO `recipe_step` VALUES (502940, 300423, 4, '奶油顶面撒上海盐', NULL);
INSERT INTO `recipe_step` VALUES (502941, 300424, 1, '萝卜去皮、滚刀切成 3-5cm 的大块，备用', NULL);
INSERT INTO `recipe_step` VALUES (502942, 300424, 2, '羊排在购买时可以让卖家切好，因为家用刀一般难以切动，备用', NULL);
INSERT INTO `recipe_step` VALUES (502943, 300424, 3, '羊肉冷水下锅，加入一半的料酒，一半的葱姜，煮 10 分钟去掉血腥，（可选）把焯的过程中出现的血沫子可以用勺子盛出来', NULL);
INSERT INTO `recipe_step` VALUES (502944, 300424, 4, '另起一锅冷水，放入切好的白萝卜，放入一半的冰糖，等水开后煮 5 分钟去掉白萝卜的辣味', NULL);
INSERT INTO `recipe_step` VALUES (502945, 300424, 5, '盛出来焯好的羊排，放入高压锅中，加水没过所有食材后再增加大约 300ml 的水', NULL);
INSERT INTO `recipe_step` VALUES (502946, 300424, 6, '将剩余的葱姜料酒，花椒，冰糖，白芷（可选），盐放入锅中，盖锅等待上汽后计时，中火炖大约 15 分钟。 如没有高压锅，则放入普通锅中，炖大约 40 分钟到 1 小时。', NULL);
INSERT INTO `recipe_step` VALUES (502947, 300424, 7, '关火，等待高压锅放气完毕，开盖，加入之前焯好的萝卜，调味，加入 3-10g 的食盐或者水，品尝汤的咸淡，', NULL);
INSERT INTO `recipe_step` VALUES (502948, 300424, 8, '再开火，中火，高压锅上汽再炖 10 分钟，普通锅盖盖再炖 20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502949, 300424, 9, '关火，盛盘', NULL);
INSERT INTO `recipe_step` VALUES (502950, 300425, 1, '开洋泡入 50 度温水中，加入 10ml 料酒去腥，泡 10 分钟后取出沥干水分', NULL);
INSERT INTO `recipe_step` VALUES (502951, 300425, 2, '葱，香菜洗净，切成 5cm 长的段，擦干表面水份', NULL);
INSERT INTO `recipe_step` VALUES (502952, 300425, 3, '洋葱切成丝，在锅里用热水煮 5 分钟，取出沥干水份', NULL);
INSERT INTO `recipe_step` VALUES (502953, 300425, 4, '姜去皮，切成片', NULL);
INSERT INTO `recipe_step` VALUES (502954, 300425, 5, '锅里倒入全部油，放入上述预处理好的材料，开中小火炸 20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502955, 300426, 1, '【制作葱油酱汁】将 小葱 洗净，切成长段（约 5-7 cm）。葱白和葱绿可以分开。', NULL);
INSERT INTO `recipe_step` VALUES (502956, 300426, 2, '【制作葱油酱汁】锅中加入 100 ml 食用油，中火烧热。先放入葱白段，煸炒至微黄。', NULL);
INSERT INTO `recipe_step` VALUES (502957, 300426, 3, '【制作葱油酱汁】加入葱绿段，转小火，继续煸炒。', NULL);
INSERT INTO `recipe_step` VALUES (502958, 300426, 4, '【制作葱油酱汁】保持小火，耐心煸炒约 15-20 分钟，直至葱段变得焦黄酥脆。', NULL);
INSERT INTO `recipe_step` VALUES (502959, 300426, 5, '【制作葱油酱汁】将焦黄的葱段捞出（葱油保留在锅中）。', NULL);
INSERT INTO `recipe_step` VALUES (502960, 300426, 6, '【制作葱油酱汁】在锅中的葱油中，加入 60 ml 生抽，20 ml 老抽，15 g 白糖。小火加热并搅拌，约 1 分钟，至糖溶解，酱汁混合均匀。立即关火。将制作好的葱油酱汁倒入容器中，放凉后密封保存。', NULL);
INSERT INTO `recipe_step` VALUES (502961, 300426, 7, '【煮面条 （按份操作）】取 80 g 干面条。', NULL);
INSERT INTO `recipe_step` VALUES (502962, 300426, 8, '【煮面条 （按份操作）】锅中加入 1000 ml 饮用水，大火烧开。', NULL);
INSERT INTO `recipe_step` VALUES (502963, 300426, 9, '【煮面条 （按份操作）】放入 面条，根据面条包装说明，煮至熟透（通常 3-8 分钟，以包装说明为准）。', NULL);
INSERT INTO `recipe_step` VALUES (502964, 300426, 10, '【煮面条 （按份操作）】将 煮好的 面条 捞出，沥干水分，放入碗中。', NULL);
INSERT INTO `recipe_step` VALUES (502965, 300426, 11, '【混合拌面 （按份操作）】在装有 面条 的碗中，加入 15 ml 之前做好的 葱油酱汁。', NULL);
INSERT INTO `recipe_step` VALUES (502966, 300426, 12, '【混合拌面 （按份操作）】可以加入之前炸好的葱段（可选）。', NULL);
INSERT INTO `recipe_step` VALUES (502967, 300426, 13, '【混合拌面 （按份操作）】用 筷子 快速搅拌均匀，即可食用。', NULL);
INSERT INTO `recipe_step` VALUES (502968, 300427, 1, '去菜市场买已经处理好的鱼（自己处理的话最好不要内脏），将鱼身表面的所有鳞片刮干净', NULL);
INSERT INTO `recipe_step` VALUES (502969, 300427, 2, '用厨房用纸将鱼肚子里的贴骨血和黑膜擦干净（帖骨血会影响口感，黑膜是鱼腥味的来源）', NULL);
INSERT INTO `recipe_step` VALUES (502970, 300427, 3, '用菜刀在鱼身表面来回刮几次，将鱼身的黏液刮掉，进一步去除腥味，然后用清水将鱼内外冲洗干净', NULL);
INSERT INTO `recipe_step` VALUES (502971, 300427, 4, '将鱼平放在砧板，使用厨房纸将鱼内外的水分擦干，然后鱼头朝左，尾朝右，从鱼鳃边开始，每隔 3cm 纵向划一刀，深度达到鱼的脊椎骨即可，另一面使用同样的处理方式', NULL);
INSERT INTO `recipe_step` VALUES (502972, 300427, 5, '将鱼平放在盆中，确保盘中没有多余水分', NULL);
INSERT INTO `recipe_step` VALUES (502973, 300427, 6, '取一块 50g 姜（鸡蛋大小），用削皮刀把表面的皮去除并洗干净，然后切成厚度为 3mm 的姜片', NULL);
INSERT INTO `recipe_step` VALUES (502974, 300427, 7, '将小米辣洗干净、去蒂，切成厚度为 2mm 的小圆片（或切成 1mm 宽度的丝状）', NULL);
INSERT INTO `recipe_step` VALUES (502975, 300427, 8, '将小葱洗干净，去除根须，切成 3cm 的小段，稍微粗一点的小葱，可以沿着小葱生长的方向沿中间劈开', NULL);
INSERT INTO `recipe_step` VALUES (502976, 300427, 9, '加入 8g 盐，25g 料酒到盆中，带上一次性手套，然后对鱼进行全身按摩 1 分钟，确保鱼身每个部位都均匀涂抹了盐和料酒', NULL);
INSERT INTO `recipe_step` VALUES (502977, 300427, 10, '按摩好鱼后，在鱼身的每一个刀口中塞入一片姜片，鱼肚子中放入 3 片姜片，腌制 10 分钟（建议不要腌制太久，否则鱼的鲜度降低）', NULL);
INSERT INTO `recipe_step` VALUES (502978, 300427, 11, '在鱼腌制期间，在蒸锅中加入 5L 清水，烧开后，在蒸锅上放上蒸笼', NULL);
INSERT INTO `recipe_step` VALUES (502979, 300427, 12, '鱼腌制好后，会析出水分，将多余水分和腌制用料酒、姜片倒掉，用清水冲洗干净鱼身和鱼肚，用厨房纸擦干鱼身和鱼肚', NULL);
INSERT INTO `recipe_step` VALUES (502980, 300427, 13, '将鱼平放在蒸鱼盘中，重新在鱼身、鱼肚刀口处塞入姜片', NULL);
INSERT INTO `recipe_step` VALUES (502981, 300427, 14, '然后将蒸鱼盘放入蒸笼中，盖上盖子，中火蒸 20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (502982, 300427, 15, '期间水蒸气会附着整个鱼和盘子上，凝结后形成鱼汤，出锅后千万不要倒掉这个汤，这个汤汁是鲜味精华', NULL);
INSERT INTO `recipe_step` VALUES (502983, 300427, 16, '用防烫夹将蒸鱼盘夹出，在鱼身和鱼周围淋上 10g 蒸鱼豉油', NULL);
INSERT INTO `recipe_step` VALUES (502984, 300427, 17, '然后在鱼身和周围均匀撒上小葱段和小米辣', NULL);
INSERT INTO `recipe_step` VALUES (502985, 300427, 18, '在铁锅中倒入 15g 植物油，用中小火慢熬 5 分钟，不要用大火，否则油会挥发很快', NULL);
INSERT INTO `recipe_step` VALUES (502986, 300427, 19, '将出锅后的热油均匀地慢慢地淋在鱼身上，鲜掉眉毛的葱油桂鱼就出炉啦！', NULL);
INSERT INTO `recipe_step` VALUES (502987, 300428, 1, '取180g生菜，在沸水中汆烫10秒；', NULL);
INSERT INTO `recipe_step` VALUES (502988, 300428, 2, '将烫好的生菜放入餐具中，淋上30g豉油汁出品。', NULL);
INSERT INTO `recipe_step` VALUES (502989, 300429, 1, '取 150g 菜心，在沸水中汆烫 60 秒；', NULL);
INSERT INTO `recipe_step` VALUES (502990, 300429, 2, '将烫好的菜心放入餐具中，淋上 30g 豉油汁出品。', NULL);
INSERT INTO `recipe_step` VALUES (502991, 300430, 1, '取 140g 菜苔，在沸水中汆烫 30 秒；', NULL);
INSERT INTO `recipe_step` VALUES (502992, 300430, 2, '将烫好的菜苔放入餐具中，淋上 30g 豉油汁出品。', NULL);
INSERT INTO `recipe_step` VALUES (502993, 300431, 1, '取175g青菜，在沸水中汆烫30秒；', NULL);
INSERT INTO `recipe_step` VALUES (502994, 300431, 2, '将烫好的青菜放入餐具中，淋入35g豉油汁出品。', NULL);
INSERT INTO `recipe_step` VALUES (502995, 300432, 1, '葱油鸡调料配制（1 份）：40g 味极鲜酱油、10g 葱油、25g纯净水；', NULL);
INSERT INTO `recipe_step` VALUES (502996, 300432, 2, '每 500g 鸡用 5g 盐、3g 鸡精、4g 葱段、2g 姜片腌制 20 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502997, 300432, 3, '腌制好的小母鸡放入蒸柜中蒸制 25 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (502998, 300432, 4, '将蒸制后的小母鸡取出，分切为宽度 1.5 厘米、长度 6cm的块状；', NULL);
INSERT INTO `recipe_step` VALUES (502999, 300432, 5, '菜品出品之前放入蒸柜蒸制 5 分钟，出品时淋上 75g 葱油鸡调料，撒上 1g 葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (503000, 300433, 1, '葱油鸡调料配制（1份）：27g味极鲜酱油、7g葱油、17g纯净水；', NULL);
INSERT INTO `recipe_step` VALUES (503001, 300433, 2, '每500g鸡用5g盐、3g鸡精、3g葱段、3g姜片腌制20分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503002, 300433, 3, '腌制好的小母鸡放入蒸柜中蒸制20-35分钟，将蒸制后的小母鸡取出，分切为宽度1.5-2厘米，长度6-8cm的块状，每份鸡块标准重量为190g；', NULL);
INSERT INTO `recipe_step` VALUES (503003, 300433, 4, '菜品出品之前放入蒸柜蒸制3分钟，出品时淋入50g葱油鸡调料，撒上1g葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (503004, 300434, 1, '葱油鸡调料配制（1份）：27g味极鲜酱油、7g葱油、17g纯净水；', NULL);
INSERT INTO `recipe_step` VALUES (503005, 300434, 2, '将鸡腿、鸡翅、鸡身切分为宽度1.5-2cm、长度6-8cm的块状，鸡脖、鸡爪分切为宽度约1.5cm的块状，每份鸡块标准重量为190g；', NULL);
INSERT INTO `recipe_step` VALUES (503006, 300434, 3, '出品之前放入蒸柜蒸制3分钟，出品时淋上50g葱油鸡调料，撒上1g葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (503007, 300435, 1, '葱油鸡调料配制（1份）：27g味极鲜酱油、7g葱油、17g纯净水；', NULL);
INSERT INTO `recipe_step` VALUES (503008, 300435, 2, '锅中加水、盐、完全解冻沥干水分的鸡排腿，开最大档位烧开后，转1档煮40分钟，关火继续在锅中浸泡10分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503009, 300435, 3, '待鸡排腿冷却完全后，分切成长5-8厘米，宽2-2.5厘米的块状，每份鸡块标准重量为190g；', NULL);
INSERT INTO `recipe_step` VALUES (503010, 300435, 4, '菜品出品之前放入蒸柜蒸制3分钟，出品时淋入50g葱油鸡调料，撒上1g葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (503011, 300436, 1, '葱白切成 1cm 的段，备用。', NULL);
INSERT INTO `recipe_step` VALUES (503012, 300436, 2, '海参切成 1cm 的段，备用。', NULL);
INSERT INTO `recipe_step` VALUES (503013, 300436, 3, '准备一个空碗，倒入 20g 蚝油， 10g 生抽， 2g 白糖，搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (503014, 300436, 4, '另一个空碗倒入淀粉，水，制备水淀粉，勾芡用。', NULL);
INSERT INTO `recipe_step` VALUES (503015, 300436, 5, '热锅，锅内放入 20ml - 25ml 食用油。等待 10 秒让油温升高。', NULL);
INSERT INTO `recipe_step` VALUES (503016, 300436, 6, '放入葱白，调小火，注意不要让葱白变焦。大概煎 3-5 分钟即可。', NULL);
INSERT INTO `recipe_step` VALUES (503017, 300436, 7, '用筷子夹出葱白，放入盘中备用。', NULL);
INSERT INTO `recipe_step` VALUES (503018, 300436, 8, '倒入调好的料汁，炒香，等待 1 - 2 分钟 。', NULL);
INSERT INTO `recipe_step` VALUES (503019, 300436, 9, '放入切好的海参，翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503020, 300436, 10, '加入 100 ml 的水， 中小火， 等待 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503021, 300436, 11, '等待锅中汤汁快干的时候，加入水淀粉，加入前面取出的葱白', NULL);
INSERT INTO `recipe_step` VALUES (503022, 300436, 12, '在外观呈粘稠状态后关火，盛盘', NULL);
INSERT INTO `recipe_step` VALUES (503023, 300437, 1, '鸡腿去骨：用剪刀从鸡腿大的那头伸进去，贴着骨头把肉剪开，再沿骨剪两下把骨肉分离，最后把骨头整根抽出。比用刀去骨更安全。', NULL);
INSERT INTO `recipe_step` VALUES (503024, 300437, 2, '去骨后的鸡腿肉切成 2-3cm 的丁。', NULL);
INSERT INTO `recipe_step` VALUES (503025, 300437, 3, '大葱切厚片（约 0.5cm 厚），小葱切 1cm 长的小段。', NULL);
INSERT INTO `recipe_step` VALUES (503026, 300437, 4, '鸡腿丁加入 10ml 料酒、5ml 生抽、2g 盐、1g 白胡椒粉抓匀，腌制 10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503027, 300437, 5, '取一个小碗调好料汁：10ml 生抽 + 5ml 老抽 + 10ml 蚝油 + 5g 糖，搅匀备用。', NULL);
INSERT INTO `recipe_step` VALUES (503028, 300437, 6, '热锅，锅内放入 15-20ml 食用油。', NULL);
INSERT INTO `recipe_step` VALUES (503029, 300437, 7, '放入姜片和花椒，保持小火炸到姜片微微焦黄、花椒颜色变深。', NULL);
INSERT INTO `recipe_step` VALUES (503030, 300437, 8, '用漏勺把姜片和花椒捞出丢弃，留底油。', NULL);
INSERT INTO `recipe_step` VALUES (503031, 300437, 9, '保持中大火，将腌好的鸡腿丁平铺下锅，不要急着翻动。', NULL);
INSERT INTO `recipe_step` VALUES (503032, 300437, 10, '等待 2-3 分钟让鸡腿丁底部煎出焦壳，再翻炒到所有面都变色、鸡肉完全断生。', NULL);
INSERT INTO `recipe_step` VALUES (503033, 300437, 11, '下入大葱片，保持中大火翻炒 1 分钟炒出葱香。', NULL);
INSERT INTO `recipe_step` VALUES (503034, 300437, 12, '倒入调好的料汁，翻炒均匀后盖上锅盖。', NULL);
INSERT INTO `recipe_step` VALUES (503035, 300437, 13, '等待 2 分钟让料汁和葱香完全融合到鸡肉里。', NULL);
INSERT INTO `recipe_step` VALUES (503036, 300437, 14, '开盖，下入小葱段和 2g 熟白芝麻（可选），翻炒 5-10 秒即可关火出锅。', NULL);
INSERT INTO `recipe_step` VALUES (503037, 300438, 1, '豆腐洗净。切约 5 mm 厚度，置于碟中。', NULL);
INSERT INTO `recipe_step` VALUES (503038, 300438, 2, '葱洗净，除去根部，切成葱花，备用。', NULL);
INSERT INTO `recipe_step` VALUES (503039, 300438, 3, '辣椒洗净，切开，去籽，切成 1cm 1cm 状，备用、', NULL);
INSERT INTO `recipe_step` VALUES (503040, 300438, 4, '热锅，加入份数 9ml 油。', NULL);
INSERT INTO `recipe_step` VALUES (503041, 300438, 5, '油入锅后，使其均匀布于锅底，均匀放入豆腐，小火煎至金黄翻面。', NULL);
INSERT INTO `recipe_step` VALUES (503042, 300438, 6, '待两面金黄，盛入碟中备用。', NULL);
INSERT INTO `recipe_step` VALUES (503043, 300438, 7, '补油至覆盖锅底，倒入辣椒大火翻炒，并铲碾 3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503044, 300438, 8, '倒入豆腐，翻炒，加入盐与鸡精，中火翻炒 1 分钟后倒入 10 ML 水，大火收汁。', NULL);
INSERT INTO `recipe_step` VALUES (503045, 300438, 9, '出锅前撒上之前计算好的葱花，起锅盛盘。', NULL);
INSERT INTO `recipe_step` VALUES (503046, 300439, 1, '蒸柜上汽后，蒸制 15 分钟，出品。', NULL);
INSERT INTO `recipe_step` VALUES (503047, 300440, 1, '取 2100g 菠菜段，置于沸水中汆烫 30 秒；', NULL);
INSERT INTO `recipe_step` VALUES (503048, 300440, 2, '锅中下入 150g 大豆油、50g 熟猪油、60g 蒜子，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (503049, 300440, 3, '下入烫制后的菠菜段、20g 盐、12g 鸡精，大火翻炒均匀后出品。', NULL);
INSERT INTO `recipe_step` VALUES (503050, 300441, 1, '下入150g大豆油、60g蒜子，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (503051, 300441, 2, '下入1400g蒜苔，炒制约30秒；', NULL);
INSERT INTO `recipe_step` VALUES (503052, 300441, 3, '下入300g湿木耳、20g生抽、14g盐、10g鸡精，炒制约2分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503053, 300441, 4, '再下入60g红椒丝，炒制约1分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503054, 300442, 1, '蒜苔切成 5cm 小段，备用', NULL);
INSERT INTO `recipe_step` VALUES (503055, 300442, 2, '五花肉切成 5mm 5cm 丝状，备用', NULL);
INSERT INTO `recipe_step` VALUES (503056, 300442, 3, '蒜瓣拍碎切成末，备用', NULL);
INSERT INTO `recipe_step` VALUES (503057, 300442, 4, '热锅，锅内放入 10ml 食用油。等待 10 秒让油温升高', NULL);
INSERT INTO `recipe_step` VALUES (503058, 300442, 5, '放入蒜末，中火翻炒 10 秒 将蒜末炒出香味', NULL);
INSERT INTO `recipe_step` VALUES (503059, 300442, 6, '放入五花肉和 5ml 生抽，中火翻炒 30 秒 将肉炒熟并上色', NULL);
INSERT INTO `recipe_step` VALUES (503060, 300442, 7, '将蒜苔放入锅内并加入 10ml 生抽，翻炒 30 秒', NULL);
INSERT INTO `recipe_step` VALUES (503061, 300442, 8, '锅内加入 20g 水，中火翻炒 5 分钟 将蒜苔炒至稍稍变软', NULL);
INSERT INTO `recipe_step` VALUES (503062, 300442, 9, '最后加入 2g 食盐，中火翻炒 30 秒，即可出锅装盘', NULL);
INSERT INTO `recipe_step` VALUES (503063, 300443, 1, '下入120g菜籽油、60g熟猪油、1000g蒜苔、15g盐、10g鸡精，大火炒制1分40秒；', NULL);
INSERT INTO `recipe_step` VALUES (503064, 300443, 2, '再下入500g香干、200g红椒，炒制1分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503065, 300444, 1, '下入200g菜籽油，烧至180℃后，下入100g姜片、1000g鸡胗片，迅速翻炒至鸡胗片熟化，关火盛出备用；', NULL);
INSERT INTO `recipe_step` VALUES (503066, 300444, 2, '锅洗净，下入熟猪油50g，油热后下入550g蒜苔、100g小米辣、100g混合剁椒、150g拍蒜，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (503067, 300444, 3, '下入140g小炒河虾料、鸡胗，翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (503068, 300445, 1, '调味料配制（12 份）：500g 蒜蓉酱、18g 盐、10g 鸡精、5g 白砂糖、20g 剁椒、15g 蒸鱼豉油；', NULL);
INSERT INTO `recipe_step` VALUES (503069, 300445, 2, '取 150g 娃娃菜上加入 40g 调味料；', NULL);
INSERT INTO `recipe_step` VALUES (503070, 300445, 3, '蒸柜上汽后，蒸制 8 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503071, 300446, 1, '芹菜摘去大部分叶子，只保留少量嫩叶。如果梗部较粗，纵向剖开一刀使其粗细一致，然后切成不超过 5 cm 的段（约大拇指长度，太长容易卡嗓子）', NULL);
INSERT INTO `recipe_step` VALUES (503072, 300446, 2, '蒜切成蒜末，备用', NULL);
INSERT INTO `recipe_step` VALUES (503073, 300446, 3, '芹菜段入锅前尽可能沥干水分，甩得越干越好', NULL);
INSERT INTO `recipe_step` VALUES (503074, 300446, 4, '炒锅烧热，放入 15 ml 猪油，油热后先撒入 2 g 盐', NULL);
INSERT INTO `recipe_step` VALUES (503075, 300446, 5, '放入蒜末，小火炒 10 秒煸香', NULL);
INSERT INTO `recipe_step` VALUES (503076, 300446, 6, '转大火，倒入芹菜段，快速翻炒 30 秒，立即出锅', NULL);
INSERT INTO `recipe_step` VALUES (503077, 300446, 7, '出锅标准：芹菜看起来半生不熟、颜色翠绿、没有炒软塌，这时的口感最脆', NULL);
INSERT INTO `recipe_step` VALUES (503078, 300447, 1, '空心菜洗净，去掉烂叶或者老梗，均匀切成 2 段或者 3 段（防止过长不好炒）', NULL);
INSERT INTO `recipe_step` VALUES (503079, 300447, 2, '锅里先倒少量油，烧至微微冒烟，此时拿起锅将国内的热油向四周浸润，让油均匀覆盖锅底，然后再倒入剩余的油(热锅凉油法)。', NULL);
INSERT INTO `recipe_step` VALUES (503080, 300447, 3, '放入蒜末，小火炒 10 到 15 秒煸香', NULL);
INSERT INTO `recipe_step` VALUES (503081, 300447, 4, '尽快均匀地放入空心菜，开大火，左手拿铲子，右手拿筷子，配合将空心菜不停翻动，直至软化变绿。', NULL);
INSERT INTO `recipe_step` VALUES (503082, 300447, 5, '接着不需使用筷子，而是使用铲子快速翻炒已软化的空心菜 15 - 20 秒，使之受热更均匀，撒入盐 2 g ，白糖 3 g，生抽 8 ml。', NULL);
INSERT INTO `recipe_step` VALUES (503083, 300447, 6, '继续大火翻炒 10 秒，即可出锅。', NULL);
INSERT INTO `recipe_step` VALUES (503084, 300448, 1, '调味汁配比：400g 味极鲜酱油，250g 纯净水，100g 葱油；', NULL);
INSERT INTO `recipe_step` VALUES (503085, 300448, 2, '将 7 个开背虾首尾交错摆放在 85g 泡发好的粉丝上；', NULL);
INSERT INTO `recipe_step` VALUES (503086, 300448, 3, '25g 蒜蓉酱和 2g 红椒丁混匀后平铺于虾肉上，蒸柜上汽后，蒸制 5 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503087, 300448, 4, '出品时淋 20g 调味汁，撒 1g 葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (503088, 300449, 1, '用刀从虾头中间切开，切到距离虾尾 1 cm', NULL);
INSERT INTO `recipe_step` VALUES (503089, 300449, 2, '将蒜蓉酱铺在虾身中间，放在盘子中', NULL);
INSERT INTO `recipe_step` VALUES (503090, 300449, 3, '锅中倒入热水，将盘子放入锅中，大火蒸 3 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503091, 300449, 4, '烧热油，倒入虾盘中，倒入生抽', NULL);
INSERT INTO `recipe_step` VALUES (503092, 300450, 1, '将 西兰花 切成小朵，清洗干净。', NULL);
INSERT INTO `recipe_step` VALUES (503093, 300450, 2, '将 大蒜 去皮，切成蒜末，备用。', NULL);
INSERT INTO `recipe_step` VALUES (503094, 300450, 3, '锅中加入 1000 ml 饮用水，大火烧开。', NULL);
INSERT INTO `recipe_step` VALUES (503095, 300450, 4, '放入 西兰花，保持大火 煮 2-3 分钟，至 西兰花 颜色变翠绿，口感变软。', NULL);
INSERT INTO `recipe_step` VALUES (503096, 300450, 5, '将 煮好的 西兰花 捞出，沥干水分，摆入盘中，备用。', NULL);
INSERT INTO `recipe_step` VALUES (503097, 300450, 6, '热锅，加入 10 ml 食用油。油温升高后，放入 大蒜末，小火煸炒出香味。', NULL);
INSERT INTO `recipe_step` VALUES (503098, 300450, 7, '加入 10 ml 生抽，5 ml 蚝油，2 g 白糖，加入 30 ml 饮用水。', NULL);
INSERT INTO `recipe_step` VALUES (503099, 300450, 8, '将锅中汤汁烧开。', NULL);
INSERT INTO `recipe_step` VALUES (503100, 300450, 9, '将烧好的蒜蓉汁 均匀淋在盘中的 西兰花 上。', NULL);
INSERT INTO `recipe_step` VALUES (503101, 300451, 1, '拍碎蒜头', NULL);
INSERT INTO `recipe_step` VALUES (503102, 300451, 2, '往蘸料碟中加入酱油', NULL);
INSERT INTO `recipe_step` VALUES (503103, 300451, 3, '起锅，加入花生油，等到油温滚烫后加入拍好的蒜头，炸半分钟', NULL);
INSERT INTO `recipe_step` VALUES (503104, 300451, 4, '半分钟后，关火，把热油倒入蘸料碟，用筷子搅拌即可', NULL);
INSERT INTO `recipe_step` VALUES (503105, 300452, 1, '大虾去头去壳留尾，用牙签挑去虾线，洗净后用厨房纸吸干水分', NULL);
INSERT INTO `recipe_step` VALUES (503106, 300452, 2, '大蒜切成蒜末，备用', NULL);
INSERT INTO `recipe_step` VALUES (503107, 300452, 3, '中火加热平底锅，放入 10ml 橄榄油', NULL);
INSERT INTO `recipe_step` VALUES (503108, 300452, 4, '油热后放入大虾，每面煎 1-1.5 分钟至变色，取出备用', NULL);
INSERT INTO `recipe_step` VALUES (503109, 300452, 5, '同一锅中加入黄油，融化后放入蒜末，小火炒香（约 30 秒）', NULL);
INSERT INTO `recipe_step` VALUES (503110, 300452, 6, '如使用白葡萄酒，此时加入并煮至酒精挥发（约 1 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (503111, 300452, 7, '将虾放回锅中，与蒜香黄油酱汁翻炒均匀（约 1 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (503112, 300452, 8, '挤入柠檬汁，翻炒均匀后立即关火', NULL);
INSERT INTO `recipe_step` VALUES (503113, 300452, 9, '装盘，淋上锅中剩余酱汁', NULL);
INSERT INTO `recipe_step` VALUES (503114, 300453, 1, '下入200g大豆油、600g鸡蛋液，炒成蛋片，出锅备用；', NULL);
INSERT INTO `recipe_step` VALUES (503115, 300453, 2, '下入50g大豆油、1500g蒜黄、60g红椒、15g盐、10g鸡精，大火翻炒1分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503116, 300453, 3, '再下入鸡蛋片，炒制1分钟，出品。', NULL);
INSERT INTO `recipe_step` VALUES (503117, 300454, 1, '茄子削皮、横着切成两段', NULL);
INSERT INTO `recipe_step` VALUES (503118, 300454, 2, '蒸 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503119, 300454, 3, '纵向切开，不要切断，在两边切面各划 2~3 刀至可以摊平', NULL);
INSERT INTO `recipe_step` VALUES (503120, 300454, 4, '煎至两面金黄', NULL);
INSERT INTO `recipe_step` VALUES (503121, 300454, 5, '往茄子上浇蒲烧汁至没过 1/2 茄子高度', NULL);
INSERT INTO `recipe_step` VALUES (503122, 300454, 6, '煎至背面上色，翻面 同时收汁，若无法收汁可以加入水淀粉（生粉和水的比例在 1:4 到 1:10 根据收汁情况而定）', NULL);
INSERT INTO `recipe_step` VALUES (503123, 300454, 7, '把剩下的蒲烧汁浇在茄子上', NULL);
INSERT INTO `recipe_step` VALUES (503124, 300454, 8, '出锅，一份茄子烧蒲烧汁就烧好了', NULL);
INSERT INTO `recipe_step` VALUES (503125, 300455, 1, '取南瓜块220g，红枣1颗点缀；', NULL);
INSERT INTO `recipe_step` VALUES (503126, 300455, 2, '蒸柜上汽后，蒸制25-30分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503127, 300456, 1, '【备料】猪肉去皮，切成 2 cm 6 cm 0.5 cm 薄片备用', NULL);
INSERT INTO `recipe_step` VALUES (503128, 300456, 2, '【备料】芹菜去叶，去掉根部 2cm，然后从中对半切开，切成 2cm 段备用', NULL);
INSERT INTO `recipe_step` VALUES (503129, 300456, 3, '【备料】大蒜去皮切粒备用，葱切 0.2cm 薄片备用，姜切细丝备用', NULL);
INSERT INTO `recipe_step` VALUES (503130, 300456, 4, '【预制】炒锅烧热至冒烟后，倒入 3ml 食用油滑锅后倒出底油', NULL);
INSERT INTO `recipe_step` VALUES (503131, 300456, 5, '【预制】重新加入食用油，加入肉片，葱姜蒜，干红椒，炒 1 分钟，注意不停匀速翻炒', NULL);
INSERT INTO `recipe_step` VALUES (503132, 300456, 6, '【预制】加入料酒，生抽，老抽，再翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503133, 300456, 7, '【预制】续入 500ml 热水。盖上锅盖炖煮 3 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503134, 300456, 8, '【预制】将芹菜，青椒倒入锅中，加入盐，五香粉调味，盖上锅盖继续炖煮 3 分钟 后关火', NULL);
INSERT INTO `recipe_step` VALUES (503135, 300456, 9, '【预制】蒸锅加入 1000ml 水，烧开上汽后，将面条摊平在笼屉上放入锅中，蒸 15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503136, 300456, 10, '【预制】面条蒸熟后取出，用筷子和无情铁手扒拉散开在案板上，室温冷却', NULL);
INSERT INTO `recipe_step` VALUES (503137, 300456, 11, '【再加工】将面条放入菜锅中搅拌，搅拌方式为一手持筷，一手持锅铲将菜翻至面条上面，以面条以全部均匀上色为搅拌完成标准', NULL);
INSERT INTO `recipe_step` VALUES (503138, 300456, 12, '【再加工】将搅拌后的面条再次放在整屉上，再次蒸 10 分钟 关火', NULL);
INSERT INTO `recipe_step` VALUES (503139, 300457, 1, '180g嫩豆腐，再加上1g盐、1g鸡精、10g熟猪油；', NULL);
INSERT INTO `recipe_step` VALUES (503140, 300457, 2, '蒸柜上汽后，蒸制12分钟，最后淋上10g豉油汁出品。', NULL);
INSERT INTO `recipe_step` VALUES (503141, 300458, 1, '鸡蛋打入碗中，打散', NULL);
INSERT INTO `recipe_step` VALUES (503142, 300458, 2, '取其他容器，倒入 1.5 倍（半个蛋壳为 0.5 倍水）于蛋液的温水（温度 20~30），将盐倒入水中化开', NULL);
INSERT INTO `recipe_step` VALUES (503143, 300458, 3, '将盐水倒入鸡蛋液中，顺时针或逆时针单方向搅拌均匀，气泡之类的可以用舀出丢弃，过筛则口感更加。', NULL);
INSERT INTO `recipe_step` VALUES (503144, 300458, 4, '使用锡纸包裹盛蛋液的碗（或用盘子盖住），置入提前带盖并加入大约 3cm 深度水的锅中', NULL);
INSERT INTO `recipe_step` VALUES (503145, 300458, 5, '中火烧至水开，转最小的火继续蒸 4 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503146, 300459, 1, '一个鸡蛋放入碗中打散', NULL);
INSERT INTO `recipe_step` VALUES (503147, 300459, 2, '向碗中加入鸡蛋体积 1.0-1.5 倍 60 度纯净水，并且搅拌均匀 正确范围内水越少弹，水越多越嫩 注意：超出范围后，水越少会口感变得太弹，水越多会变得太稀', NULL);
INSERT INTO `recipe_step` VALUES (503148, 300459, 3, '加入食用盐 1g 盐起到了重要的增加底味和凝固作用', NULL);
INSERT INTO `recipe_step` VALUES (503149, 300459, 4, '加入食用油 5ml', NULL);
INSERT INTO `recipe_step` VALUES (503150, 300459, 5, '过滤蛋液，去掉蛋液中的浮沫（可选，不过滤蒸出来的蛋会有气泡导致不好看）', NULL);
INSERT INTO `recipe_step` VALUES (503151, 300459, 6, '确认蒸箱的水源已经补充至足够（若不确定，可把水槽补满）', NULL);
INSERT INTO `recipe_step` VALUES (503152, 300459, 7, '将已经完全搅拌均匀的鸡蛋液碗放入蒸箱', NULL);
INSERT INTO `recipe_step` VALUES (503153, 300459, 8, '调节至100摄氏度蒸 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503154, 300459, 9, '打开蒸箱 （注意：蒸箱在开启时会有蒸气瞬间喷出，注意缓慢开启）', NULL);
INSERT INTO `recipe_step` VALUES (503155, 300459, 10, '出锅（可加入生抽调味）', NULL);
INSERT INTO `recipe_step` VALUES (503156, 300459, 11, '享用', NULL);
INSERT INTO `recipe_step` VALUES (503157, 300460, 1, '从花卷的包装袋中取出 5 个花卷', NULL);
INSERT INTO `recipe_step` VALUES (503158, 300460, 2, '把花卷平铺在碟子上，尽量不用重叠', NULL);
INSERT INTO `recipe_step` VALUES (503159, 300460, 3, '往锅里倒入 400ml 水，把蒸架放里面，把装花卷的碟子放在蒸架上，盖上锅盖。', NULL);
INSERT INTO `recipe_step` VALUES (503160, 300460, 4, '开大火加热，直至水沸腾。', NULL);
INSERT INTO `recipe_step` VALUES (503161, 300460, 5, '转中火加热 15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503162, 300460, 6, '开盖用手感受花卷的表面温度，如果不够热，就继续盖上盖子加热，否则就可以关火出锅。', NULL);
INSERT INTO `recipe_step` VALUES (503163, 300460, 7, '碟子取出放凉至 50 度即可食用', NULL);
INSERT INTO `recipe_step` VALUES (503164, 300461, 1, '将称好的白砂糖的饮用水于容器混匀', NULL);
INSERT INTO `recipe_step` VALUES (503165, 300461, 2, '容器封盖放冰箱冷藏', NULL);
INSERT INTO `recipe_step` VALUES (503166, 300462, 1, '炒合菜（3 份）：(1) 下入 40g 大豆油、125g 混合鸡蛋液（125g 蛋液+0.5g 盐），炒制蛋片，出锅；(2) 下入大豆油 20g，下入包菜丝 150g、胡萝卜丝 50g、盐 1g、鸡精 4g、蚝油 6g、生抽 15g；(3) 加入 83g 粉丝（80g 泡发粉丝+3g 老抽），最后下入鸡蛋块，炒制约 30 秒；下入葱花，翻搅均匀关火。', NULL);
INSERT INTO `recipe_step` VALUES (503167, 300462, 2, '卷制：蒸制好的饼皮放入 100g 炒合菜，卷制成型。', NULL);
INSERT INTO `recipe_step` VALUES (503168, 300463, 1, '来货薄皮青椒，清洗干净后去蒂去籽，放入190℃的油炸炉中，炸制15秒即可，捞出；', NULL);
INSERT INTO `recipe_step` VALUES (503169, 300463, 2, '沥油后备用；在不锈钢桶中放入6500g水和500g卤料，大火烧开后，捞出料渣，备用；', NULL);
INSERT INTO `recipe_step` VALUES (503170, 300463, 3, '将过油后的青椒放入卤汤中，卤10分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503171, 300464, 1, '薯条放入170℃的油锅中炸制8分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503172, 300465, 1, '【预处理】猪肘解冻后水泡 1 小时去除血水。', NULL);
INSERT INTO `recipe_step` VALUES (503173, 300465, 2, '【预处理】如有火焰喷枪，则使用火焰喷枪灼烧猪肘皮表面至棕黑色以去除猪毛，破坏汗腺。注意不要长时间炙烤同一个位置以避免烧焦，当猪肘皮几乎完全呈现棕黑色时则停止灼烧。', NULL);
INSERT INTO `recipe_step` VALUES (503174, 300465, 3, '【预处理】如无火焰喷枪，将铁锅烧至 200 以上，将猪肘直接放入锅内，用锅铲或筷子使猪肘皮充分接触铁锅表面，当猪肘皮与铁锅接触位置呈现出棕色时，更换位置继续烫猪肘皮，直到整个猪肘被充分烫过。注意再次过程中注意铁锅温度，不要使铁锅红热。', NULL);
INSERT INTO `recipe_step` VALUES (503175, 300465, 4, '【预处理】使用清洁球在水中刷洗猪肘，将其表面烧焦的部分去除。刷洗结束后，猪肘再次呈现出未被灼烧前的状态。', NULL);
INSERT INTO `recipe_step` VALUES (503176, 300465, 5, '【预处理】将猪肘置于铁锅中，加尽量多的冷水，具体视铁锅深度与猪肘大小而定，在保证可以拿得动铁锅及其内容物的情况下，能浸没猪肘 3/4 以上为最佳。', NULL);
INSERT INTO `recipe_step` VALUES (503177, 300465, 6, '【去腥】取 1 棵葱的葱白，分成 3 段，放入锅中。', NULL);
INSERT INTO `recipe_step` VALUES (503178, 300465, 7, '【去腥】取 3 粒蒜，分别用刀身拍扁，放入锅中。', NULL);
INSERT INTO `recipe_step` VALUES (503179, 300465, 8, '【去腥】取 3 克姜，放入锅中。', NULL);
INSERT INTO `recipe_step` VALUES (503180, 300465, 9, '【去腥】将 2 汤匙料酒加入锅中。', NULL);
INSERT INTO `recipe_step` VALUES (503181, 300465, 10, '【去腥】锅中水烧开后，等待五分钟，随后将猪肘取出，捡出锅中所有配料，更换容器保留所有肉汤备用。', NULL);
INSERT INTO `recipe_step` VALUES (503182, 300465, 11, '【油炸】向锅中加入冷油，以之前水量为参考，能浸没猪肘 3/5 以上为佳，开中火加热。', NULL);
INSERT INTO `recipe_step` VALUES (503183, 300465, 12, '【油炸】当油温达到五成时，转为小火，放入猪肘油炸。', NULL);
INSERT INTO `recipe_step` VALUES (503184, 300465, 13, '【油炸】在油炸过程中烹饪者应注意人身安全。', NULL);
INSERT INTO `recipe_step` VALUES (503185, 300465, 14, '【油炸】在油炸过程中，使用锅铲或其他耐高温厨具将锅中的油均匀淋到猪肘未被浸没的部分，如果条件允许应以 3 分钟的间隔翻转猪肘，使其油炸均匀。', NULL);
INSERT INTO `recipe_step` VALUES (503186, 300465, 15, '【油炸】油炸过程持续大约 20 分钟，当观察到猪肘皮已经全部呈现出浅棕色，而瘦肉部分已经微焦，则可捞出备用。', NULL);
INSERT INTO `recipe_step` VALUES (503187, 300465, 16, '【油炸】炸制完后的油可用于制作其他油炸类食物，但注意不要使用太多次。', NULL);
INSERT INTO `recipe_step` VALUES (503188, 300465, 17, '【炒糖色】炒糖色200ml 备用。', NULL);
INSERT INTO `recipe_step` VALUES (503189, 300465, 18, '【炖煮】将猪肘加入高压锅内，加入所有肉汤、糖色、香叶、肉桂皮、豆蔻、花椒、大料、老抽、生抽、白醋。如果喜欢甜口，可以再额外加入 2-3 克冰糖。', NULL);
INSERT INTO `recipe_step` VALUES (503190, 300465, 19, '【炖煮】取 1 棵葱的葱白，分成 3 段，放入锅中。', NULL);
INSERT INTO `recipe_step` VALUES (503191, 300465, 20, '【炖煮】取 3 粒蒜，分别用刀身拍扁，放入锅中。', NULL);
INSERT INTO `recipe_step` VALUES (503192, 300465, 21, '【炖煮】取 3 克姜，放入锅中。', NULL);
INSERT INTO `recipe_step` VALUES (503193, 300465, 22, '【炖煮】盖上锅盖，加压炖煮 40 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503194, 300465, 23, '【收汁】在炖煮期间调制水淀粉。取碗 1 个，加入 1 汤匙淀粉，100ml 水，搅拌使其成为白色悬浊液', NULL);
INSERT INTO `recipe_step` VALUES (503195, 300465, 24, '【收汁】炖煮时间结束后，打开高压锅锅盖，捡出锅中所有的配料，只保留猪肘。', NULL);
INSERT INTO `recipe_step` VALUES (503196, 300465, 25, '【收汁】将高压锅中剩余的肉汤转移至铁锅内，猪肘转移至盘子或盆内', NULL);
INSERT INTO `recipe_step` VALUES (503197, 300465, 26, '【收汁】将铁锅置于灶台上，开大火。在收汁过程中可以用筷子头蘸取锅内汤汁判断咸淡，并根据口味添加盐。注意，汤汁多的时候味道会比汤汁少的时候味道更淡，加入盐时需要考虑这一点。', NULL);
INSERT INTO `recipe_step` VALUES (503198, 300465, 27, '【收汁】当肉汤沸腾时，注意观察剩余肉汤余量', NULL);
INSERT INTO `recipe_step` VALUES (503199, 300465, 28, '【收汁】当剩余肉汤少于原肉汤体积的 1/2 时，再次搅拌之前调制好的水淀粉，并加入一半', NULL);
INSERT INTO `recipe_step` VALUES (503200, 300465, 29, '【收汁】等待肉汤沸腾，加入剩下的一半', NULL);
INSERT INTO `recipe_step` VALUES (503201, 300465, 30, '【收汁】等待肉汤沸腾，沸腾后等待 1-2 分钟关火，此时锅内的肉汤呈红棕色粘稠状', NULL);
INSERT INTO `recipe_step` VALUES (503202, 300465, 31, '【收汁】用汤匙舀起肉汤均匀地淋在猪肘上，尽量使猪肘的每一处都淋到汤汁。如果在猪肘被完全淋到前汤汁已经用完则可直接上桌，否则剩余汤汁不需要再淋，可直接上桌。', NULL);
INSERT INTO `recipe_step` VALUES (503203, 300466, 1, '去掉青椒蒂，用自来水冲洗干净。', NULL);
INSERT INTO `recipe_step` VALUES (503204, 300466, 2, '青椒切长片，平均一个青椒纵向切成 3-4 片即可。', NULL);
INSERT INTO `recipe_step` VALUES (503205, 300466, 3, '大蒜去皮，切成碎末，体积在 2mm x 2mm x 2mm 即可。', NULL);
INSERT INTO `recipe_step` VALUES (503206, 300466, 4, '调料 1：拿一个小碗倒入 20ml 油，将大蒜末放入其中。', NULL);
INSERT INTO `recipe_step` VALUES (503207, 300466, 5, '调料 2：白糖、生抽、醋、盐全部倒入砵（碗）等容器，搅拌。', NULL);
INSERT INTO `recipe_step` VALUES (503208, 300466, 6, '将 调料 1 倒入锅中，开火加热 5 成放入青椒，青椒片不要叠在一起，单独成片放置锅中。', NULL);
INSERT INTO `recipe_step` VALUES (503209, 300466, 7, '用锅铲不停的按压青椒，合适的时候翻面。', NULL);
INSERT INTO `recipe_step` VALUES (503210, 300466, 8, '翻炒约 2 分钟，待青椒表皮出现褶皱时，倒入 调料 2。', NULL);
INSERT INTO `recipe_step` VALUES (503211, 300466, 9, '加大火候继续翻炒 30s 后即可出锅盛入盘中。', NULL);
INSERT INTO `recipe_step` VALUES (503212, 300467, 1, '调制蛋液：将鸡蛋打成蛋液，然后将 600g 鸡蛋液、30g 鸡油、10g 清酱汁、17g 盐、1700g 水、30g 蚕豆酱混合并用打蛋器搅拌均匀，直至蛋清、蛋黄完全打散；', NULL);
INSERT INTO `recipe_step` VALUES (503213, 300467, 2, '蛋液过滤：用过滤网滤出蚕豆酱残渣；', NULL);
INSERT INTO `recipe_step` VALUES (503214, 300467, 3, '蛋液蒸制：蒸柜上汽后，蒸 5 分钟，焖 1 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503215, 300467, 4, '虾仁蒸制：蒸柜上汽后，蒸 15 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503216, 300467, 5, '最后在蒸制好的鸡蛋上面，加入 1 颗蒸熟的虾仁，淋上3g蒸鱼豉油、2g芝麻香油。', NULL);
INSERT INTO `recipe_step` VALUES (503217, 300468, 1, '红薯粉丝提前泡软，泡水时间为 20 分钟，备用', NULL);
INSERT INTO `recipe_step` VALUES (503218, 300468, 2, '将蒜、姜分别剁碎，备用', NULL);
INSERT INTO `recipe_step` VALUES (503219, 300468, 3, '锅烧热，加入 10ml 食用油，加入蒜末、姜末炒香', NULL);
INSERT INTO `recipe_step` VALUES (503220, 300468, 4, '加入猪肉末翻炒至肉色发白且微微出油', NULL);
INSERT INTO `recipe_step` VALUES (503221, 300468, 5, '加入郫县豆瓣酱，炒至红油析出', NULL);
INSERT INTO `recipe_step` VALUES (503222, 300468, 6, '加入生抽和老抽，翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (503223, 300468, 7, '倒入 300ml 清水，煮沸', NULL);
INSERT INTO `recipe_step` VALUES (503224, 300468, 8, '放入泡软沥干的粉丝，用筷子轻轻拨动防止粘连', NULL);
INSERT INTO `recipe_step` VALUES (503225, 300468, 9, '中小火煮约 5 分钟，直至粉丝完全吸收汤汁、呈现微微收干状态', NULL);
INSERT INTO `recipe_step` VALUES (503226, 300468, 10, '依据口味可撒入小葱末，关火装盘', NULL);
INSERT INTO `recipe_step` VALUES (503227, 300469, 1, '锅洗净，下入200g大豆油烧热，下入60g拍蒜炒香；', NULL);
INSERT INTO `recipe_step` VALUES (503228, 300469, 2, '下入450g虾仁、100g红椒片翻炒均匀；', NULL);
INSERT INTO `recipe_step` VALUES (503229, 300469, 3, '下入1400g蚕豆瓣翻炒均匀；', NULL);
INSERT INTO `recipe_step` VALUES (503230, 300469, 4, '下入12g盐、12g鸡精翻炒，出品。', NULL);
INSERT INTO `recipe_step` VALUES (503231, 300470, 1, '下入600g 鸡蛋液、200g 大豆油，炒成鸡蛋片，出锅备用；', NULL);
INSERT INTO `recipe_step` VALUES (503232, 300470, 2, '下入50g 大豆油、900g 蚕豆、100g 红椒、13g 盐、6g 鸡', NULL);
INSERT INTO `recipe_step` VALUES (503233, 300470, 3, '最后下入鸡蛋片，翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (503234, 300471, 1, '蟹味菇、白玉菇 去掉根部泥土，掰散菌朵', NULL);
INSERT INTO `recipe_step` VALUES (503235, 300471, 2, '香菇切片（每片厚度 0.5-1 cm，厚点相对薄点更有嚼劲）', NULL);
INSERT INTO `recipe_step` VALUES (503236, 300471, 3, '生粉倒入小碗中，加入 50ml 水，搅拌生粉直至融化没有颗粒（即水淀粉）备用', NULL);
INSERT INTO `recipe_step` VALUES (503237, 300471, 4, '水开，放入西蓝花，清水煮 3 分钟，放入碗中备用', NULL);
INSERT INTO `recipe_step` VALUES (503238, 300471, 5, '洗锅烧开水，加入 5 g 食用盐，倒入蟹味菇、白玉菇、香菇，水煮 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503239, 300471, 6, '1 分钟后，捞出沥干水分', NULL);
INSERT INTO `recipe_step` VALUES (503240, 300471, 7, '起锅烧油，待油开始冒小泡，放入姜末、小米辣、菜椒 煸炒 30 S', NULL);
INSERT INTO `recipe_step` VALUES (503241, 300471, 8, '倒入三鲜菇，然后依次倒入生抽、蚝油、鸡精，翻炒均匀后，倒入水淀粉', NULL);
INSERT INTO `recipe_step` VALUES (503242, 300471, 9, '中火烧干汁，加入料酒、葱花 出锅', NULL);
INSERT INTO `recipe_step` VALUES (503243, 300471, 10, '摆上西蓝花', NULL);
INSERT INTO `recipe_step` VALUES (503244, 300472, 1, '生菜洗净并去掉烂菜叶。', NULL);
INSERT INTO `recipe_step` VALUES (503245, 300472, 2, '热锅，先放 1 L 清水（凉），然后在锅内放入 2 ml - 3 ml 食用油和 0.5 g 盐，等待锅中的水煮沸。', NULL);
INSERT INTO `recipe_step` VALUES (503246, 300472, 3, '水沸后，放入生菜，将每一片生菜叶都焯水 10 s。', NULL);
INSERT INTO `recipe_step` VALUES (503247, 300472, 4, '捞出生菜，控干水份，摆盘 。', NULL);
INSERT INTO `recipe_step` VALUES (503248, 300472, 5, '调汁：将生抽 10 ml 、蚝油 6-8 ml 、盐 0.5 g 、 白糖 1 g 放入碗中调匀，并加入 10-15 ml 清水（凉）搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (503249, 300472, 6, '再开火，热锅，放入食用油 5-8 ml，油热放入蒜泥。', NULL);
INSERT INTO `recipe_step` VALUES (503250, 300472, 7, '等待有蒜香飘出，倒入调好的汁，煮沸即可，立马关火。', NULL);
INSERT INTO `recipe_step` VALUES (503251, 300472, 8, '将锅中的汤汁均匀地浇在生菜上。', NULL);
INSERT INTO `recipe_step` VALUES (503252, 300473, 1, '洋葱、胡萝卜、火腿肠或鸡胸肉切成小丁，备用', NULL);
INSERT INTO `recipe_step` VALUES (503253, 300473, 2, '热锅，锅中倒入 10ml 食用油，等待 10 秒加热', NULL);
INSERT INTO `recipe_step` VALUES (503254, 300473, 3, '先放入洋葱丁翻炒 1 分钟，出香味后加入胡萝卜、玉米粒、青豆继续翻炒 2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503255, 300473, 4, '加入火腿肠或鸡胸肉丁，炒至变色', NULL);
INSERT INTO `recipe_step` VALUES (503256, 300473, 5, '加入米饭炒散后，加入番茄酱 20ml，翻炒均匀，炒饭完成，盛出备用', NULL);
INSERT INTO `recipe_step` VALUES (503257, 300473, 6, '鸡蛋打散，加入 10ml 牛奶搅匀', NULL);
INSERT INTO `recipe_step` VALUES (503258, 300473, 7, '锅中放入 5ml 食用油，倒入蛋液，轻晃锅底让蛋液均匀铺满锅面', NULL);
INSERT INTO `recipe_step` VALUES (503259, 300473, 8, '用小火加热，待蛋液表面半熟状态时，将炒饭放入蛋液中央', NULL);
INSERT INTO `recipe_step` VALUES (503260, 300473, 9, '用铲子将蛋皮折叠包住米饭，形成椭圆形状', NULL);
INSERT INTO `recipe_step` VALUES (503261, 300473, 10, '用锅铲轻轻推至盘中，整理外形，可在表面挤上少量番茄酱装饰', NULL);
INSERT INTO `recipe_step` VALUES (503262, 300474, 1, '米饭提前用铲子铲成小块', NULL);
INSERT INTO `recipe_step` VALUES (503263, 300474, 2, '火腿肠、胡萝卜、黄瓜等根据需求切片或者块状', NULL);
INSERT INTO `recipe_step` VALUES (503264, 300474, 3, '如果家里有熟肉 准备好味道更佳', NULL);
INSERT INTO `recipe_step` VALUES (503265, 300474, 4, '将蛋白，蛋黄分开，分别打入一个大碗里，各自搅匀。注意，不要在这一步加盐。', NULL);
INSERT INTO `recipe_step` VALUES (503266, 300474, 5, '大火热锅，待锅里冒烟放入食用油，放入蛋白，待主体凝固后盛出备用。', NULL);
INSERT INTO `recipe_step` VALUES (503267, 300474, 6, '如果油够，则直接放入蛋黄，如果油不够则放入食用油并等其升温到大火热锅', NULL);
INSERT INTO `recipe_step` VALUES (503268, 300474, 7, '待主体凝固后，将火调至中小火，倒入火腿肠、熟肉，胡萝卜、黄瓜等备料、翻炒 10 秒钟（到爆香）', NULL);
INSERT INTO `recipe_step` VALUES (503269, 300474, 8, '重新倒入蛋白，翻炒 5s 钟，迅速倒入米饭大火翻炒，为的就是每一粒饭都裹上鸡蛋。', NULL);
INSERT INTO `recipe_step` VALUES (503270, 300474, 9, '翻炒过程中将米饭的块状捣碎、这一步过程会比较长、待米饭全部捣碎再翻炒均匀即可', NULL);
INSERT INTO `recipe_step` VALUES (503271, 300474, 10, '调至小火、加盐、胡椒粉、生抽', NULL);
INSERT INTO `recipe_step` VALUES (503272, 300474, 11, '进一步翻炒均匀，能看到一些米饭在锅里有“跳起来”的时候其实就已经差不多了', NULL);
INSERT INTO `recipe_step` VALUES (503273, 300474, 12, '最后倒入香葱再翻炒 10s', NULL);
INSERT INTO `recipe_step` VALUES (503274, 300474, 13, '关火、盛入碗中', NULL);
INSERT INTO `recipe_step` VALUES (503275, 300475, 1, '把糍粑切成长方形小块，便于后面煎', NULL);
INSERT INTO `recipe_step` VALUES (503276, 300475, 2, '碗里打入一个鸡蛋并把鸡蛋搅碎，加入 2g 食用盐', NULL);
INSERT INTO `recipe_step` VALUES (503277, 300475, 3, '将切好的小糍粑依此放入搅碎的鸡蛋里面，涂抹完糍粑双面为止', NULL);
INSERT INTO `recipe_step` VALUES (503278, 300475, 4, '锅里倒入植物油 10ml ，把涂抹好的糍粑小块放进去小火慢慢煎软。', NULL);
INSERT INTO `recipe_step` VALUES (503279, 300475, 5, '将剩下的鸡蛋液慢慢倒在糍粑表面', NULL);
INSERT INTO `recipe_step` VALUES (503280, 300475, 6, '用筷子或者勺子为糍粑翻面，来回煎至金黄色后开吃', NULL);
INSERT INTO `recipe_step` VALUES (503281, 300476, 1, '将 500g 面粉、650g 水、250g 鸡蛋液、50g 葱花、16g 盐搅拌成面糊；', NULL);
INSERT INTO `recipe_step` VALUES (503282, 300476, 2, '舀取 2 勺（150g）面糊置于电饼铛中间位置，均匀平摊成圆形；', NULL);
INSERT INTO `recipe_step` VALUES (503283, 300476, 3, '煎至单面微黄（约 2 分钟），再翻面煎制微黄（约 2 分钟）出品。', NULL);
INSERT INTO `recipe_step` VALUES (503284, 300477, 1, '烧开水，将蛏子放入水中，水煮 2 分钟后，捞上来去壳，放入大碗', NULL);
INSERT INTO `recipe_step` VALUES (503285, 300477, 2, '往大碗中加入洋葱、生抽、料酒、鸡精、生粉后，充分搅拌', NULL);
INSERT INTO `recipe_step` VALUES (503286, 300477, 3, '往大碗中打入 2 个 鸡蛋，继续搅拌', NULL);
INSERT INTO `recipe_step` VALUES (503287, 300477, 4, '起锅烧油，倒入碗中蛏子，煎炸至单面金黄后，翻面继续煎炸', NULL);
INSERT INTO `recipe_step` VALUES (503288, 300478, 1, '150g 南瓜，再加上 15g 白砂糖、20g 水；', NULL);
INSERT INTO `recipe_step` VALUES (503289, 300478, 2, '蒸柜上汽后，蒸制 20 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503290, 300479, 1, '锅中加水，将水烧开', NULL);
INSERT INTO `recipe_step` VALUES (503291, 300479, 2, '下米粉，煮 3-5 分钟，期间用筷子搅拌，防止米粉粘在一起', NULL);
INSERT INTO `recipe_step` VALUES (503292, 300479, 3, '下汤料包，按个人口味添加', NULL);
INSERT INTO `recipe_step` VALUES (503293, 300479, 4, '下一部分配料包，如木耳，花生，螺蛳（这部分配料需要煮一会才入味）', NULL);
INSERT INTO `recipe_step` VALUES (503294, 300479, 5, '下调味包，按个人口味添加', NULL);
INSERT INTO `recipe_step` VALUES (503295, 300479, 6, '搅拌后捞出，放入碗中', NULL);
INSERT INTO `recipe_step` VALUES (503296, 300479, 7, '下剩下的配料包，如酸笋，豆皮（这部分配料不适合被汤泡太久）', NULL);
INSERT INTO `recipe_step` VALUES (503297, 300479, 8, '享用美食', NULL);
INSERT INTO `recipe_step` VALUES (503298, 300480, 1, '鲜仔鸭肉切成约 3cm 小块，加料酒、姜片，去除血水。', NULL);
INSERT INTO `recipe_step` VALUES (503299, 300480, 2, '炒锅烧热，放入约 100ml 食用油，大火待油烧开，放入腌制好的鲜鸭肉，不断翻炒。', NULL);
INSERT INTO `recipe_step` VALUES (503300, 300480, 3, '待鸭肉完全变色（肉眼可见泛白），放入酒，再加入 200ml 开水，刚好淹没鸭肉即可，盖上锅盖中火煮 15 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503301, 300480, 4, '水开之后，打开锅盖放入姜蒜，翻炒一遍，盖上锅盖持续加热 10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503302, 300480, 5, '打开锅盖放入辣椒，不断翻炒，待至肉眼可见辣椒炒软，放入鲜鸭血，此时需要不断翻炒，确保每块鸭肉和每片辣椒都有鸭血的浸润（此乃血浆鸭的精髓）。', NULL);
INSERT INTO `recipe_step` VALUES (503303, 300480, 6, '翻炒至肉眼可见鸭血均为黑色，加入盐，鸡精，香葱，（喜欢食用山胡椒油的朋友也可以在此时放入 3-6 滴山胡椒油）再次翻炒一到二次即可。', NULL);
INSERT INTO `recipe_step` VALUES (503304, 300480, 7, '出锅盛盘，上桌食用。', NULL);
INSERT INTO `recipe_step` VALUES (503305, 300481, 1, '锅热后下入100g大豆油，油温180℃后下入600g鸡胸肉片，待表面定型后轻轻翻炒；', NULL);
INSERT INTO `recipe_step` VALUES (503306, 300481, 2, '下入60g蒜子，炒香；', NULL);
INSERT INTO `recipe_step` VALUES (503307, 300481, 3, '下入1600g西兰花、150g胡萝卜片、160g鸡胸肉调味汁，大火炒制1分钟，出品。', NULL);
INSERT INTO `recipe_step` VALUES (503308, 300482, 1, '备菜: 土豆去皮、切成 5cm 大块，备用 西红柿切十字花刀，开水烫后去皮，把中间的芯去掉，切 3cm 小块备用 葱切 4g 的葱花出来，剩下的掰成 5-8cm 大段 牛肉泡凉水半小时去血水，或凉水下锅煮至表面变白捞出，期间撇去浮末 洋葱切 0.5-1cm 小粒', NULL);
INSERT INTO `recipe_step` VALUES (503309, 300482, 2, '制作 全程中火 凉水没过牛肉，放入高压锅，放入葱段，姜片，放入 20g 料酒，上汽压 20 分钟 取出牛肉后，切 5cm 大块，挑出姜，汤盛到一个大碗里一会炖煮用 倒油，油四到五成热以后下花椒八角香叶，出香味之后糊之前挑出不用 下入牛肉，葱姜，炒香，炒多久都无所谓，看着有点要糊可以舀 10ml 汤，此下同理 炒香后加入生抽 15ml，料酒 15ml，胡椒粉，5-10g 番茄膏番茄酱或一个番茄罐头，加入洋葱炒至透明 （可选）可以加一点点盐使洋葱出水不容易糊，不要加太多，后面再调味 加入西红柿炒至西红柿化开软烂，倒入剩下的汤', NULL);
INSERT INTO `recipe_step` VALUES (503310, 300482, 3, '炖煮 中火开锅后，全程小火 出锅前 30-40 分钟 加土豆并调味 依据个人口味边尝边加糖盐，合适为止 筷子戳牛肉软烂后出锅！', NULL);
INSERT INTO `recipe_step` VALUES (503311, 300483, 1, '西红柿洗净', NULL);
INSERT INTO `recipe_step` VALUES (503312, 300483, 2, '可选：去掉西红柿的外表皮 开水烫表皮，然后将西红柿放入冷水，剥去外皮', NULL);
INSERT INTO `recipe_step` VALUES (503313, 300483, 3, '西红柿去蒂，切成边长不超过 4cm 的小块，即为 西红柿块', NULL);
INSERT INTO `recipe_step` VALUES (503314, 300483, 4, '将鸡蛋打入碗中，加入 1g 份数 的盐，搅匀，即为 鸡蛋液 可以考虑向鸡蛋中加入 1ml 醋，这可以去除腥味，令鸡蛋更蓬松', NULL);
INSERT INTO `recipe_step` VALUES (503315, 300483, 5, '热锅，加入食用油', NULL);
INSERT INTO `recipe_step` VALUES (503316, 300483, 6, '油热后，倒入 鸡蛋液。翻炒至鸡蛋结为固体且颜色微微发黄，即为 半熟鸡蛋', NULL);
INSERT INTO `recipe_step` VALUES (503317, 300483, 7, '关火。将 半熟鸡蛋 盛盘，重新开火 注意：不要洗锅', NULL);
INSERT INTO `recipe_step` VALUES (503318, 300483, 8, '加入 西红柿块，锅铲拍打并翻炒 20 秒，或至西红柿软烂', NULL);
INSERT INTO `recipe_step` VALUES (503319, 300483, 9, '向锅中加入 半熟鸡蛋，翻炒均匀 可以考虑加入 10ml 番茄酱和 50ml 清水，增加汤汁 可以额外加入一些其它熟肉和材料', NULL);
INSERT INTO `recipe_step` VALUES (503320, 300483, 10, '加入剩余的盐、糖（可选，如果倾向于甜味版本）、葱花（可选），翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (503321, 300483, 11, '关火，盛盘', NULL);
INSERT INTO `recipe_step` VALUES (503322, 300484, 1, '西红柿炒鸡蛋炒制：下入200g大豆油、575g鸡蛋液，炒成蛋片，出锅备用；再下入50g大豆油、1800g西红柿块、8g盐、8g鸡精，大火翻炒；再下入鸡蛋片、24g水淀粉，翻炒均匀。', NULL);
INSERT INTO `recipe_step` VALUES (503323, 300484, 2, '卤鸡腿卤制：在不锈钢桶中放入5000g水、500g卤料和500g卤油，大火烧开后，捞出料渣，备用；解冻后的卤鸡腿放入卤汤中，大火烧开后转小火卤5分钟，关火焖5分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503324, 300484, 3, '盖饭出品：餐盒中放入300g米饭，将1份西红柿炒鸡蛋、1个卤鸡腿放在米饭上，鸡腿上淋入20g卤汤，出品。', NULL);
INSERT INTO `recipe_step` VALUES (503325, 300485, 1, '牛腩切条、切块成长宽高均 2cm ，冷水下锅，开锅煮制 2 分钟去除血水，捞出冲洗干净', NULL);
INSERT INTO `recipe_step` VALUES (503326, 300485, 2, '另起锅 2L 水烧开，加入 2cm 两段葱段、两片姜片、八角、料/黄酒 5-10ml，放入焯好的牛肉，盖盖炖制（砂锅 1 小时，高压锅炖肉模式 45 分钟），筷子能轻松插透就证明炖好了', NULL);
INSERT INTO `recipe_step` VALUES (503327, 300485, 3, '西红柿去皮：西红柿头部滑十字至腰线，筷子/刀叉从果蒂捅入，煤气灶小火，一边转动一边烤，及时拿下来查看，起皮后撕下来，切块。越小越好 撕皮小心烫，去皮后的西红柿特别滑，慢切注意安全', NULL);
INSERT INTO `recipe_step` VALUES (503328, 300485, 4, '起锅烧油，油温 7 成热，葱、姜各 10g，番茄下锅，炒透炒出番茄红色，加入煮好的牛腩和原汤，原汤刚刚没过牛肉即可', NULL);
INSERT INTO `recipe_step` VALUES (503329, 300485, 5, '根据个人口味放入盐、糖、生抽调味盖盖', NULL);
INSERT INTO `recipe_step` VALUES (503330, 300485, 6, '开锅后大火继续炒制 3-5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503331, 300485, 7, '待番茄汁呈中等粘稠程度后关火，散入葱花，盛盘', NULL);
INSERT INTO `recipe_step` VALUES (503332, 300486, 1, '西红柿切成小丁、鸡蛋打入碗中搅拌、豆腐切块备用', NULL);
INSERT INTO `recipe_step` VALUES (503333, 300486, 2, '起锅烧油，放入姜片 5 S 后倒入入西红柿翻炒 30 S', NULL);
INSERT INTO `recipe_step` VALUES (503334, 300486, 3, '锅中加入开水，汤水烧开，60 S 后到入鸡蛋液、豆腐块', NULL);
INSERT INTO `recipe_step` VALUES (503335, 300486, 4, '汤水重新烧开后，加入水淀粉，沿一个方向搅拌 2 圈', NULL);
INSERT INTO `recipe_step` VALUES (503336, 300486, 5, '加入鸡精、盐、香葱，30 S 后起锅', NULL);
INSERT INTO `recipe_step` VALUES (503337, 300487, 1, '【食材的预处理】小葱洗净并切成葱花', NULL);
INSERT INTO `recipe_step` VALUES (503338, 300487, 2, '【食材的预处理】西红柿切块儿，如果不太会切建议先百度一下~', NULL);
INSERT INTO `recipe_step` VALUES (503339, 300487, 3, '【食材的预处理】青椒切成菱形块', NULL);
INSERT INTO `recipe_step` VALUES (503340, 300487, 4, '【食材的预处理】生鸡蛋打入一个小碗并打散，如果鸡蛋有点腥味可以加 2g 白醋去腥', NULL);
INSERT INTO `recipe_step` VALUES (503341, 300487, 5, '【鸡蛋的预处理】起锅烧热，倒入 15~20g 食用油，鸡蛋炒嫩滑就得多一点油，同时为后面煸炒西红柿留一些底油', NULL);
INSERT INTO `recipe_step` VALUES (503342, 300487, 6, '【鸡蛋的预处理】待油温到七成热时（手掌隔大概 10cm，能感觉到热），倒入蛋液快速划散', NULL);
INSERT INTO `recipe_step` VALUES (503343, 300487, 7, '【鸡蛋的预处理】鸡蛋滑到凝固后，一点不会有蛋液了后倒入小碗备用，此处留一些底油', NULL);
INSERT INTO `recipe_step` VALUES (503344, 300487, 8, '【制作西红柿鸡蛋臊子】锅中留底油后先加入葱白、蒜末炒香', NULL);
INSERT INTO `recipe_step` VALUES (503345, 300487, 9, '【制作西红柿鸡蛋臊子】加入西红柿块、青椒，待西红柿炒出一点汁水', NULL);
INSERT INTO `recipe_step` VALUES (503346, 300487, 10, '【制作西红柿鸡蛋臊子】此时速速加入 5g 酱油和 2g 白砂糖', NULL);
INSERT INTO `recipe_step` VALUES (503347, 300487, 11, '【制作西红柿鸡蛋臊子】翻炒十几秒后加入一碗清水（刚刚好即将没过西红柿即可）', NULL);
INSERT INTO `recipe_step` VALUES (503348, 300487, 12, '【制作西红柿鸡蛋臊子】煮沸后加入炒好的鸡蛋，加入蚝油 5g 或者 2g 鸡精用于提鲜', NULL);
INSERT INTO `recipe_step` VALUES (503349, 300487, 13, '【制作西红柿鸡蛋臊子】中小火收汁，期间要搅拌防止粘锅，收汁到下图后加一点葱花（剩下的葱绿部分）和香油（不加也可以），臊子制作完成', NULL);
INSERT INTO `recipe_step` VALUES (503350, 300487, 14, '【最后煮面条】可以不用洗锅，直接加清水 500ml', NULL);
INSERT INTO `recipe_step` VALUES (503351, 300487, 15, '【最后煮面条】煮沸加入挂面，挂面煮软后加入 100ml 清水', NULL);
INSERT INTO `recipe_step` VALUES (503352, 300487, 16, '【最后煮面条】再次煮沸后，若面条飘起来了，再加入 100ml 清水', NULL);
INSERT INTO `recipe_step` VALUES (503353, 300487, 17, '【最后煮面条】煮沸后看面条两侧是否呈透明状，透明状则熟了', NULL);
INSERT INTO `recipe_step` VALUES (503354, 300487, 18, '【最后煮面条】捞面到臊子碗中，拌面即可啦~', NULL);
INSERT INTO `recipe_step` VALUES (503355, 300488, 1, '将西红柿洗净，切块。', NULL);
INSERT INTO `recipe_step` VALUES (503356, 300488, 2, '葱姜蒜切碎。', NULL);
INSERT INTO `recipe_step` VALUES (503357, 300488, 3, '鸡蛋打到碗中，用筷子（或打蛋器）搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (503358, 300488, 4, '热锅，并放入 15 毫升的油，待能从油中看到冒出一丝烟时，放入葱姜蒜翻炒 30 秒。', NULL);
INSERT INTO `recipe_step` VALUES (503359, 300488, 5, '放入西红柿翻炒 1 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503360, 300488, 6, '倒入水，水的高度大约为锅内菜品高度的 1.2 倍，并放入盐。', NULL);
INSERT INTO `recipe_step` VALUES (503361, 300488, 7, '待开锅后，将鸡蛋液放入，并用筷子将鸡蛋打散，放入味素和香油。', NULL);
INSERT INTO `recipe_step` VALUES (503362, 300488, 8, '等待 30 秒，关火出锅。', NULL);
INSERT INTO `recipe_step` VALUES (503363, 300489, 1, '锅中倒入足量水，下入1500g西芹段、完全解冻冲洗的300g虾仁、300g胡萝卜片，焯水至熟透，捞出沥干水分；', NULL);
INSERT INTO `recipe_step` VALUES (503364, 300489, 2, '锅中下入50g大豆油，油热下入焯水完成的西芹段、虾仁、胡萝卜片，翻炒均匀；', NULL);
INSERT INTO `recipe_step` VALUES (503365, 300489, 3, '下入已经混合均匀的10g盐、10g白砂糖、10g鸡精、5g玉米淀粉、20g水，翻炒均匀后出品。', NULL);
INSERT INTO `recipe_step` VALUES (503366, 300490, 1, '取800g 西芹、400g 花生米、30g 红椒，放入沸水中汆烫1分钟捞出；', NULL);
INSERT INTO `recipe_step` VALUES (503367, 300490, 2, '汆烫好的配菜用纯净水冲凉后备用；', NULL);
INSERT INTO `recipe_step` VALUES (503368, 300490, 3, '在冷却后的西芹、花生米、红椒中加入6g 盐、6g 鸡精、30g芝麻香油，翻拌出品。', NULL);
INSERT INTO `recipe_step` VALUES (503369, 300491, 1, '西红柿洗净，切成小块，备用', NULL);
INSERT INTO `recipe_step` VALUES (503370, 300491, 2, '西葫芦洗净，切成边长约为 4cm 的菱形，备用', NULL);
INSERT INTO `recipe_step` VALUES (503371, 300491, 3, '打三个鸡蛋到碗里，打散搅匀，备用', NULL);
INSERT INTO `recipe_step` VALUES (503372, 300491, 4, '热锅，锅内放入 5ml - 10ml 食用油', NULL);
INSERT INTO `recipe_step` VALUES (503373, 300491, 5, '倒入鸡蛋，保持翻炒至鸡蛋成固体，用锅铲分成小块后盛到碗里，备用', NULL);
INSERT INTO `recipe_step` VALUES (503374, 300491, 6, '锅内放入 5ml - 10ml 食用油，倒入西红柿，炒至变软', NULL);
INSERT INTO `recipe_step` VALUES (503375, 300491, 7, '倒入西葫芦一起翻炒均匀，放入 6g 食用盐，将火调小然后等待 4 - 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503376, 300491, 8, '倒入备用的鸡蛋，中火翻炒 15 秒', NULL);
INSERT INTO `recipe_step` VALUES (503377, 300491, 9, '关火，盛盘', NULL);
INSERT INTO `recipe_step` VALUES (503378, 300492, 1, '清水加入食用盐，毛豆浸泡 15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503379, 300492, 2, '加入开水，倒入毛豆、话梅，水煮 20-30 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503380, 300492, 3, '起锅开吃', NULL);
INSERT INTO `recipe_step` VALUES (503381, 300493, 1, '下入50g大豆油、50g熟猪油、30g蒜子，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (503382, 300493, 2, '下入1100g毛白菜、90g湿豆腐皮、10g盐、5g鸡精、大火爆炒2分30秒出品。', NULL);
INSERT INTO `recipe_step` VALUES (503383, 300494, 1, '【准备动作】将豆角切成 5cm - 6cm 的小段。', NULL);
INSERT INTO `recipe_step` VALUES (503384, 300494, 2, '【准备动作】将葱切成 1cm - 2cm 小段。', NULL);
INSERT INTO `recipe_step` VALUES (503385, 300494, 3, '【准备动作】将姜切成 1mm x 1mm x 3cm 的长条', NULL);
INSERT INTO `recipe_step` VALUES (503386, 300494, 4, '【准备动作】将蒜放在砧板上拍碎，切成 1mm 的粒度。', NULL);
INSERT INTO `recipe_step` VALUES (503387, 300494, 5, '【准备动作】将五花肉切成 2mm 厚度的肉片。', NULL);
INSERT INTO `recipe_step` VALUES (503388, 300494, 6, '【准备动作】首先将锅烧热，烧去锅内全部水汽，手放过内距离锅底 10cm 处，感觉明显有些许烤手。', NULL);
INSERT INTO `recipe_step` VALUES (503389, 300494, 7, '【准备动作】加入上述定量的食用油，手持锅柄，离灶 5cm 处，摇晃锅，使食用油充分挂满锅的三分之二（自下而上）。', NULL);
INSERT INTO `recipe_step` VALUES (503390, 300494, 8, '【准备动作】放入全部的姜和全部的葱段，翻炒爆香 5 秒（注意！此时有油飞溅的危险，建议带上手套或做好防护措施）。', NULL);
INSERT INTO `recipe_step` VALUES (503391, 300494, 9, '【准备动作】放入全部的肉片，放入以后不着急饭锅，静置 5 秒后，再翻炒，使所有的肉都裹满食用油。', NULL);
INSERT INTO `recipe_step` VALUES (503392, 300494, 10, '【准备动作】不断翻炒肉片，待到全部肉片都已经变色，沿锅边均匀淋如准备好的生抽，翻炒均匀。', NULL);
INSERT INTO `recipe_step` VALUES (503393, 300494, 11, '【准备动作】依次加入准备好的盐、老抽、耗油、十三香、鸡精以及全部准备好的豆角，翻炒 2 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503394, 300494, 12, '【准备动作】加入准备好的热水。', NULL);
INSERT INTO `recipe_step` VALUES (503395, 300494, 13, '【准备动作】水开使用勺子舀出锅内 2 分之一菜汤（注意！不要将菜舀出）。', NULL);
INSERT INTO `recipe_step` VALUES (503396, 300494, 14, '【准备动作】将所有面条平铺在菜的上方。', NULL);
INSERT INTO `recipe_step` VALUES (503397, 300494, 15, '【准备动作】盖上锅盖，中火焖 5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503398, 300494, 16, '【准备动作】打开锅盖，将舀出的菜汤使用勺子，以每次一勺的量，均匀撒在面条上。', NULL);
INSERT INTO `recipe_step` VALUES (503399, 300494, 17, '【准备动作】盖上锅盖，中火焖 3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503400, 300494, 18, '【准备动作】打开锅盖，将所有的蒜、味精均匀撒入。', NULL);
INSERT INTO `recipe_step` VALUES (503401, 300494, 19, '【准备动作】使用筷子不断翻炒，将菜与肉均匀搅拌。', NULL);
INSERT INTO `recipe_step` VALUES (503402, 300494, 20, '【准备动作】关火', NULL);
INSERT INTO `recipe_step` VALUES (503403, 300495, 1, '食材处理： 油麦菜洗净后切段 鲮鱼罐头打开后，把鲮鱼主刺去除，切成小段后备用 大蒜切成末', NULL);
INSERT INTO `recipe_step` VALUES (503404, 300495, 2, '炒制过程： 锅热倒入食用油，油热后加入洗净的油麦菜，炒到萎蔫出水后盛出备用，倒掉炒制出的水分 重新热锅后，加入鲮鱼罐头中的油，放入蒜末煸香 蒜末煸香后加入鲮鱼罐头中的豆豉，翻拌后加入切碎的鲮鱼块，再次翻拌 翻拌均匀后加入油麦菜，加入生抽和糖调味 调味加入后简单翻拌即可出锅装盘', NULL);
INSERT INTO `recipe_step` VALUES (503405, 300496, 1, '将排骨用冷水浸泡 10 分钟泡去血水，换水重复 2 次，用厨房纸吸干', NULL);
INSERT INTO `recipe_step` VALUES (503406, 300496, 2, '将豆豉放入水中浸泡 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503407, 300496, 3, '将所有食材混合（食用油放 10 ml），腌制 8-30 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503408, 300496, 4, '水开后上锅蒸 18 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503409, 300496, 5, '焖 2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503410, 300496, 6, '锅中倒入 10 ml 热油，加热到 180-200 ℃', NULL);
INSERT INTO `recipe_step` VALUES (503411, 300496, 7, '均匀撒上葱花和白芝麻，热油浇在撒料上', NULL);
INSERT INTO `recipe_step` VALUES (503412, 300497, 1, '检查与清洗白鱔： 购买时已请鱼贩去内脏、刮去黏液并切成约 5 厘米长的段。 回家后检查白鱔，冲洗干净，确保无残留黏液或杂质。 可选：用 3g 盐和 1 茶匙生粉轻搓白鱔段，腌制 5 分钟后冲洗干净，去腥并增加嫩滑口感。', NULL);
INSERT INTO `recipe_step` VALUES (503413, 300497, 2, '准备酱汁： 在小碗中混合 1 汤匙豆豉、2 瓣蒜末、1.5 汤匙生抽、0.5 茶匙老抽、0.5 茶匙糖、0.5 茶匙麻油和 1 汤匙水，搅拌均匀。 若喜欢更浓郁的豉汁，可多加 0.5 汤匙豆豉。', NULL);
INSERT INTO `recipe_step` VALUES (503414, 300497, 3, '摆盘： 将已切好的白鱔段平铺在耐热盘中，尽量不重叠。 将姜丝均匀撒在白鱔上。 将调好的豉汁均匀淋在白鱔上。', NULL);
INSERT INTO `recipe_step` VALUES (503415, 300497, 4, '蒸制： 在蒸锅或电蒸炉中加入水 (500ml)，烧开。 将装有白鱔的盘子放入蒸锅，盖上锅盖。 用中大火蒸约 8-10 分钟 （视白鱔段大小调整时间），至白鱔熟透但不过老 （肉质变白，无血水）。', NULL);
INSERT INTO `recipe_step` VALUES (503416, 300497, 5, '装饰与完成： 蒸好后取出，撒上葱丝和红椒丝 （可选） 作装饰。 可再淋热麻油提升香气。 趁热上桌，搭配白饭享用。', NULL);
INSERT INTO `recipe_step` VALUES (503417, 300498, 1, '鱼块解冻清洗干净，蒸柜上汽后，蒸制8分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503418, 300498, 2, '倒出蒸汽水后，每块鱼块淋入20g蒸鱼调味汁，出品时点缀红椒丝、葱姜丝。', NULL);
INSERT INTO `recipe_step` VALUES (503419, 300499, 1, '150g甜青豌豆、25g肉末、10g胡萝卜，蒸制5分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503420, 300500, 1, '在锅中加入和锅一半高度的油，将切成长条的土豆先炸至表面金黄然后捞出备用，等油温上至烤手时候将切好的鸡块放入锅中炸，并放入切好的生姜片和花椒', NULL);
INSERT INTO `recipe_step` VALUES (503421, 300500, 2, '刚开始炸鸡的时候，油是浑浊的，因为鸡块里面有水的原因，等到油炸至清澈，鸡块就炸好了，然后捞出备用', NULL);
INSERT INTO `recipe_step` VALUES (503422, 300500, 3, '现在锅里面的油可以捞三分之一出来，现在用不到这么多的油', NULL);
INSERT INTO `recipe_step` VALUES (503423, 300500, 4, '将锅中剩余的油加热，加入糍粑辣椒，豆瓣酱，生姜片，炒出红油状，将炸好的鸡块翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (503424, 300500, 5, '等到鸡块都上色，加入老抽，倒入啤酒，啤酒一定要盖过鸡块，加上香叶盖上盖，闷十分钟，期间间隔翻炒', NULL);
INSERT INTO `recipe_step` VALUES (503425, 300500, 6, '然后加入土豆条，大蒜（不用切，一颗一颗的最好），然后再闷 20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503426, 300500, 7, '最后加入酒糟翻炒均匀再加入切好的蒜苗，就可以出锅了', NULL);
INSERT INTO `recipe_step` VALUES (503427, 300501, 1, '300g 菜籽油烧至180℃；', NULL);
INSERT INTO `recipe_step` VALUES (503428, 300501, 2, '下入800g 辣子鸡酱料和150g 蒜子，炒至酱料沸腾；', NULL);
INSERT INTO `recipe_step` VALUES (503429, 300501, 3, '加入1700g 炸制鸡块，翻炒4 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503430, 300502, 1, '将 250g 红豆泡制 1 小时，清洗后加入 550g 水，放入蒸柜蒸 1.5 小时；', NULL);
INSERT INTO `recipe_step` VALUES (503431, 300502, 2, '不锈钢桶内放入 4000g 水、190g 冰糖，大火烧沸，加入255g 豆沙、770g 熟红豆，搅拌均匀，下入小元宵；', NULL);
INSERT INTO `recipe_step` VALUES (503432, 300502, 3, '大火烧沸，边搅拌边缓慢倒入藕粉水，大火烧沸 1 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503433, 300503, 1, '将青椒洗净，去除青椒把以及青椒籽，再用滚刀手法切好备用。', NULL);
INSERT INTO `recipe_step` VALUES (503434, 300503, 2, '大蒜用刀拍一下，再横切成蒜瓣，生姜切碎成姜末。', NULL);
INSERT INTO `recipe_step` VALUES (503435, 300503, 3, '将猪瘦肉切成肉片（顺着猪肉的纹理切，即刀和肉的纹理呈水平线，出来的肉片，纹路呈“川”字）。', NULL);
INSERT INTO `recipe_step` VALUES (503436, 300503, 4, '将切好的猪肉洗净，放入空碗，再加入计算好的生抽、蚝油、盐搅拌均匀，腌制 10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503437, 300503, 5, '热锅，不用倒油，把切好的青椒放入锅中，大火干煸至虎皮状后，再加 2g盐继续翻炒 1 分钟 后捞起。', NULL);
INSERT INTO `recipe_step` VALUES (503438, 300503, 6, '不用洗锅，大火热锅，加入份数 8ml油，等待 30s，加入蒜瓣、姜末翻炒 15s。', NULL);
INSERT INTO `recipe_step` VALUES (503439, 300503, 7, '加入腌制好的猪肉倒入锅内翻炒 2 分钟，再加入干煸过的青椒翻炒 1 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503440, 300503, 8, '根据个人口味喜好加入豆豉，最后加入酱油，继续翻炒 30s。', NULL);
INSERT INTO `recipe_step` VALUES (503441, 300503, 9, '出锅，盛盘。', NULL);
INSERT INTO `recipe_step` VALUES (503442, 300504, 1, '中火，将水倒入锅中，静候水煮沸。', NULL);
INSERT INTO `recipe_step` VALUES (503443, 300504, 2, '将饺子倒入锅中。', NULL);
INSERT INTO `recipe_step` VALUES (503444, 300504, 3, '倒入锅前可以适当用水过一下。', NULL);
INSERT INTO `recipe_step` VALUES (503445, 300504, 4, '倒入饺子后，可以用炒菜勺子或铲子搅水，但要注意不要铲到饺子上，以避免粘锅上撕破皮或互相粘连造成粘连处夹生。', NULL);
INSERT INTO `recipe_step` VALUES (503446, 300504, 5, '频率不需要太高，平均每 30 秒摇 3 秒，饺子浮起后不需要再做此步。', NULL);
INSERT INTO `recipe_step` VALUES (503447, 300504, 6, '饺子浮起及水再次煮沸后，用炒菜勺子盛起一个饺子观察，如果面皮有夹生可用炒菜勺子舀入 80ml 凉水，将水降温，然后继续煮至沸腾，此间重复此观察、搅拌操作，最多加两次水就能全熟。', NULL);
INSERT INTO `recipe_step` VALUES (503448, 300504, 7, '所有饺子浮起后（下饺子后约 8 分钟）用铲子或漏勺把饺子铲入盘或碗中，装盘后即可食用。', NULL);
INSERT INTO `recipe_step` VALUES (503449, 300504, 8, '吃完饺子后，等锅内水温降低，将水倒掉并用洗洁精及时刷锅，不然过段时间锅内煮过的面粉会在锅壁形成黏糊糊的物质。', NULL);
INSERT INTO `recipe_step` VALUES (503450, 300505, 1, '取出速冻汤圆，放入碗中。', NULL);
INSERT INTO `recipe_step` VALUES (503451, 300505, 2, '倒入开水，直至浸没汤圆。', NULL);
INSERT INTO `recipe_step` VALUES (503452, 300505, 3, '微波炉高火 4 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503453, 300505, 4, '假如汤圆均已吸水膨胀，则已熟。', NULL);
INSERT INTO `recipe_step` VALUES (503454, 300505, 5, '如果没熟，再加热 1 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503455, 300506, 1, '【烧开水】将水倒入电饭煲中，按炖或煮的模式运行 35 分钟，此时揭开电饭煲应看到水为沸腾状态。', NULL);
INSERT INTO `recipe_step` VALUES (503456, 300506, 2, '【下馄饨】将速冻馄饨小心放入水中，注意不要烫伤。', NULL);
INSERT INTO `recipe_step` VALUES (503457, 300506, 3, '【下馄饨】放入电饭煲前可以适当用水过一下。', NULL);
INSERT INTO `recipe_step` VALUES (503458, 300506, 4, '【下馄饨】如果馄饨有调料包，此时可一并加入水中。', NULL);
INSERT INTO `recipe_step` VALUES (503459, 300506, 5, '【煮馄饨】盖上电饭煲，按同样炖或煮的模式运行 20 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503460, 300506, 6, '【盛馄饨】将所有馄饨连同能没过所有馄饨的水一同盛入碗中。', NULL);
INSERT INTO `recipe_step` VALUES (503461, 300506, 7, '【盛馄饨】如果此前没有加入调料包，此时可按自身口味轻重加入盐、鸡精、胡椒粉、香油调味。', NULL);
INSERT INTO `recipe_step` VALUES (503462, 300506, 8, '【盛馄饨】也可撒上 5~8 片香菜叶佐味（仅适用于对香菜味道不敏感的人）。', NULL);
INSERT INTO `recipe_step` VALUES (503463, 300507, 1, '将 400g 酒酿、5250g 水、210g 白砂糖大火烧开加入淀粉水（130g 玉米淀粉+150g 水）；', NULL);
INSERT INTO `recipe_step` VALUES (503464, 300507, 2, '完全沸腾关火，淋入鸡蛋液，再次烧开，出品。', NULL);
INSERT INTO `recipe_step` VALUES (503465, 300508, 1, '将 800g 糯米淘洗干净放入电饭煲，加入 720g 清水选择蒸饭模式', NULL);
INSERT INTO `recipe_step` VALUES (503466, 300508, 2, '蒸熟后将米饭倒出摊凉，使用干净的工具将其摊至 30°C （用温度计测量为宜，体感温热但不烫手）', NULL);
INSERT INTO `recipe_step` VALUES (503467, 300508, 3, '将 8g 安琪甜酒曲用 20ml 温水（约 30°C）化开，均匀撒在糯米饭中，同时翻拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (503468, 300508, 4, '向糯米饭中加入 600g 清水帮助酒曲翻拌均匀。静置 2-3 分钟后发现糯米饭吸饱水分。这次加水可以让酒酿首次发酵便汤汁丰富', NULL);
INSERT INTO `recipe_step` VALUES (503469, 300508, 5, '用擀面杖在糯米饭中央挖一个小洞（便于出酒）', NULL);
INSERT INTO `recipe_step` VALUES (503470, 300508, 6, '将混合好的米饭装入干净容器中，轻轻压平表面，盖上盖子或保鲜膜密封好', NULL);
INSERT INTO `recipe_step` VALUES (503471, 300508, 7, '放置于 28 ～ 32°C 环境下发酵 24 ～ 48 小时。发酵期间不可剧烈摇晃或移动', NULL);
INSERT INTO `recipe_step` VALUES (503472, 300508, 8, '发酵成功标准为：中间凹槽有透明酒液渗出，整体略带酒香，无异味、不酸败', NULL);
INSERT INTO `recipe_step` VALUES (503473, 300508, 9, '发酵结束后可立即冷藏保存（过程中可以加入桂花），每次食用用干净工具取出，可冷藏保存 7 ～ 10 天', NULL);
INSERT INTO `recipe_step` VALUES (503474, 300508, 10, '可以继续二次发酵，加入 500ml 清水增加酒酿产量（800g 水以内即可）', NULL);
INSERT INTO `recipe_step` VALUES (503475, 300508, 11, '酒酿会一直持续发酵。如果想停止发酵，可以上锅蒸 10 分钟杀菌，或放入冰箱冷藏', NULL);
INSERT INTO `recipe_step` VALUES (503476, 300508, 12, '【进阶版本 1：提前泡米版本】将 800g 糯米淘洗干净，倒入清水中浸泡 6 ～ 8 小时（冬季建议泡 8 ～ 10 小时），泡至米粒饱满', NULL);
INSERT INTO `recipe_step` VALUES (503477, 300508, 13, '【进阶版本 1：提前泡米版本】沥干糯米，放入蒸布中，隔水蒸 40 ～ 60 分钟。每 20 分钟打开锅盖翻动一次确保蒸熟均匀', NULL);
INSERT INTO `recipe_step` VALUES (503478, 300508, 14, '【进阶版本 1：提前泡米版本】蒸熟后将米饭倒出摊凉，加入酒曲，后续步骤同上', NULL);
INSERT INTO `recipe_step` VALUES (503479, 300508, 15, '【进阶版本 2：混合米】当然，酒酿老手可以随意尝试不同米搭配。可以替换 20%的糯米为小米、燕麦、黄米、血糯米等', NULL);
INSERT INTO `recipe_step` VALUES (503480, 300509, 1, '酥皮萝卜丝馅饼放入190℃的油中油炸3 分钟（两面各炸1 分30 秒）。', NULL);
INSERT INTO `recipe_step` VALUES (503481, 300510, 1, '荞麦面下冷水煮熟，8-10 分钟 后捞出沥干备用', NULL);
INSERT INTO `recipe_step` VALUES (503482, 300510, 2, '黄瓜、萝卜 切成小条', NULL);
INSERT INTO `recipe_step` VALUES (503483, 300510, 3, '将荞麦面、黄瓜、萝卜放入盘子，放上老干妈，搅拌', NULL);
INSERT INTO `recipe_step` VALUES (503484, 300511, 1, '起锅烧热水，放入排骨、姜片、料酒，煮开后用勺子舀去白色油沫，2-3 分钟后出锅', NULL);
INSERT INTO `recipe_step` VALUES (503485, 300511, 2, '冷水清洗排骨，清洗 2-3 遍', NULL);
INSERT INTO `recipe_step` VALUES (503486, 300511, 3, '小火起锅，加入食用油，加入白砂糖 ，轻轻搅拌到糖水变成黄色', NULL);
INSERT INTO `recipe_step` VALUES (503487, 300511, 4, '倒入排骨翻炒 30 S 后，加入生抽、蚝油、五香粉、蒜、小米椒后翻炒 30 S 后，加入清水没过排骨', NULL);
INSERT INTO `recipe_step` VALUES (503488, 300511, 5, '大火煮 30 分钟，加入老抽上色，再煮 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503489, 300511, 6, '起锅摆盘', NULL);
INSERT INTO `recipe_step` VALUES (503490, 300512, 1, '30g 娃娃菜和 30g 玉耳下入沸水中汆烫 15 秒后，冲凉备用；', NULL);
INSERT INTO `recipe_step` VALUES (503491, 300512, 2, '120g 黑鱼片下入沸水中汆烫 30 秒后，冲凉备用；', NULL);
INSERT INTO `recipe_step` VALUES (503492, 300512, 3, '餐具中放入烫制后的娃娃菜和玉耳，再加入烫制后的黑鱼片，沿餐具边缘浇淋 10g 豉油汁，再将 50g 酱椒蒜香调味酱平铺在黑鱼片上；', NULL);
INSERT INTO `recipe_step` VALUES (503493, 300512, 4, '蒸柜上汽后，蒸制 6 分钟，出品撒 1g 葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (503494, 300513, 1, '把螃蟹刷洗干净，然后在砧板上对半劈开', NULL);
INSERT INTO `recipe_step` VALUES (503495, 300513, 2, '锅里下菜油，放入姜末和豆瓣酱爆香，加入冰糖炒化，直到冒小气泡就盛出', NULL);
INSERT INTO `recipe_step` VALUES (503496, 300513, 3, '在盘子里铺上一层酱，然后把切好的螃蟹切开面朝下，整齐排放在酱上', NULL);
INSERT INTO `recipe_step` VALUES (503497, 300513, 4, '放点葱段和姜片，建议敲个鸡蛋或在盘底铺肉末', NULL);
INSERT INTO `recipe_step` VALUES (503498, 300513, 5, '上锅蒸 10-12 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503499, 300514, 1, '牛腱子肉清洗干净，用清水浸泡 1 小时，去除血水', NULL);
INSERT INTO `recipe_step` VALUES (503500, 300514, 2, '用牙签或者叉子在牛腱子肉表面扎孔，加料酒、花椒、姜片后，用保鲜膜紧密包裹容器，腌制 4-6 小时', NULL);
INSERT INTO `recipe_step` VALUES (503501, 300514, 3, '牛腱子肉切成 8cm，不超过 10cm 的肉块', NULL);
INSERT INTO `recipe_step` VALUES (503502, 300514, 4, '牛腱子肉放入锅中，加入冷水至水面没过牛肉，开锅至水沸腾开始计时，同时捞出浮沫。3 分钟后停火，捞出牛肉，用温水洗净', NULL);
INSERT INTO `recipe_step` VALUES (503503, 300514, 5, '将洗净后的牛腱子肉放入砂锅或炖锅，加水没过牛腱子肉，开大火，放入除盐之外其他未使用的配料', NULL);
INSERT INTO `recipe_step` VALUES (503504, 300514, 6, '水开之后，大火转为小火，持续加热 90 分钟，加盐', NULL);
INSERT INTO `recipe_step` VALUES (503505, 300514, 7, '加盐后，继续小火 90 分钟（注：每 30 分钟确认水位线，要求至少达到牛肉面高度的 80%）', NULL);
INSERT INTO `recipe_step` VALUES (503506, 300514, 8, '加热 180 分钟后，捞出牛腱子肉，捞出牛腱子肉，用保鲜膜紧密包裹，放入冰箱冷藏数小时', NULL);
INSERT INTO `recipe_step` VALUES (503507, 300514, 9, '取出后沿牛肉纹路切片，上桌食用，其他牛腱子肉建议不切片冷藏', NULL);
INSERT INTO `recipe_step` VALUES (503508, 300515, 1, '将 1200g 白干、610g 酱蒸白干料、180g 蒜子，拌匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (503509, 300515, 2, '分装到餐具后，在上汽的蒸柜中，蒸制 20 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503510, 300516, 1, '取 160g 豆腐，辅以 60g 酱蒸白干料；', NULL);
INSERT INTO `recipe_step` VALUES (503511, 300516, 2, '蒸柜上汽后，蒸制 20 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503512, 300517, 1, '将50g 河虾和60g 酱料拌匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (503513, 300517, 2, '在餐具中放入80g 香干丁；', NULL);
INSERT INTO `recipe_step` VALUES (503514, 300517, 3, '将110g 拌匀的河虾平铺在香干丁上；', NULL);
INSERT INTO `recipe_step` VALUES (503515, 300517, 4, '蒸柜上汽后，蒸制12 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503516, 300518, 1, '吉利丁片剪成小片，泡入冷水中', NULL);
INSERT INTO `recipe_step` VALUES (503517, 300518, 2, '淡奶油和糖放入锅中，加热至 60 度', NULL);
INSERT INTO `recipe_step` VALUES (503518, 300518, 3, '关火，吉利丁从水中取出，控干水份，加入热淡奶油中，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (503519, 300518, 4, '淡奶油降温至 40 度，加入原味酸奶，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (503520, 300518, 5, '将上述步骤得到的混合物过两遍筛网', NULL);
INSERT INTO `recipe_step` VALUES (503521, 300518, 6, '分装入合适的容器，放入冰箱冷藏 4 小时以上', NULL);
INSERT INTO `recipe_step` VALUES (503522, 300519, 1, '冲洗材料（干桂花和冰糖除外）， 1.5 升水常温浸泡两小时以上（干桂花和冰糖除外）', NULL);
INSERT INTO `recipe_step` VALUES (503523, 300519, 2, '开中大火煮沸，盖盖，转小火煮 40 分钟，为头煎', NULL);
INSERT INTO `recipe_step` VALUES (503524, 300519, 3, '将冰糖放入盆内，再将沥好用材的头汤趁热倒入，搅拌至冰糖融化。', NULL);
INSERT INTO `recipe_step` VALUES (503525, 300519, 4, '药材重新装回锅内再 600 毫升的水，开大火煮沸，盖盖，转中火，再煮 20 分钟为二煎', NULL);
INSERT INTO `recipe_step` VALUES (503526, 300519, 5, '最后将二煎和冰糖水趁热混合为成品。在成品 60-70℃加入干桂花（不要超过 80℃）加盖晾凉再放入冰箱冷藏 3 小时以上。', NULL);
INSERT INTO `recipe_step` VALUES (503527, 300519, 6, '饮用时记得将干桂花沥出。如饮茶般细啜，冰凉振齿，酸醒人、甜适度，滋味丰满而悠长', NULL);
INSERT INTO `recipe_step` VALUES (503528, 300520, 1, '取饮用水 1177 克。', NULL);
INSERT INTO `recipe_step` VALUES (503529, 300520, 2, '放入酸梅晶固体饮料 60 克，使用汤匙顺时针搅拌 50 圈。', NULL);
INSERT INTO `recipe_step` VALUES (503530, 300520, 3, '再放入剩下 60 克酸梅晶固体饮料，再次使用汤匙顺时针搅拌 50 圈。', NULL);
INSERT INTO `recipe_step` VALUES (503531, 300520, 4, '放入 9 克的方糖，使用汤匙顺时针搅拌 100 圈。', NULL);
INSERT INTO `recipe_step` VALUES (503532, 300520, 5, '放入北京二锅头酒 48 克，用汤匙顺时针搅拌 30 圈。', NULL);
INSERT INTO `recipe_step` VALUES (503533, 300521, 1, '【1. 酸菜肥肠半成品烧制（5 份）】① 150g 菜籽油烧至 160℃；', NULL);
INSERT INTO `recipe_step` VALUES (503534, 300521, 2, '【1. 酸菜肥肠半成品烧制（5 份）】② 下入 50g 拍蒜、50g 泡小米辣，炒香；', NULL);
INSERT INTO `recipe_step` VALUES (503535, 300521, 3, '【1. 酸菜肥肠半成品烧制（5 份）】③ 下入 250g 泡椒调味料，炒香；', NULL);
INSERT INTO `recipe_step` VALUES (503536, 300521, 4, '【1. 酸菜肥肠半成品烧制（5 份）】④ 下入 300g 焯水后的肥肠、250g 焯水后的猪杂，炒香；', NULL);
INSERT INTO `recipe_step` VALUES (503537, 300521, 5, '【1. 酸菜肥肠半成品烧制（5 份）】⑤ 下入 1200g 水，烧开后，下入 5g 白糖、10g 老抽、10g陈醋、8g 藤椒油，煮 3 分钟备用。', NULL);
INSERT INTO `recipe_step` VALUES (503538, 300521, 6, '【2. 装配】将 80g 小叶酸菜平铺在砂锅底部，放入 230g 烧制后的肥肠，烧开后煮 1 分钟，撒 10g 蒜花出品。', NULL);
INSERT INTO `recipe_step` VALUES (503539, 300522, 1, '下入100g鸡油、40g熟猪油、60g蒜子、60g生姜、60g剁椒，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (503540, 300522, 2, '下入300g小叶酸菜，炒制约40秒；', NULL);
INSERT INTO `recipe_step` VALUES (503541, 300522, 3, '下入1000g水、1100g鸡血、2盒豆腐、5g盐、15g鸡精、80g生抽，烧开后转小火，炖烧入味；', NULL);
INSERT INTO `recipe_step` VALUES (503542, 300522, 4, '再下入100g青蒜，翻拌均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (503543, 300523, 1, '下入150g大豆油、60g蒜子、50g剁椒，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (503544, 300523, 2, '下入1800g包菜丝、18g盐、5g鸡精、4g白砂糖，炒制3分40秒；', NULL);
INSERT INTO `recipe_step` VALUES (503545, 300523, 3, '最后下入30g陈醋，翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (503546, 300524, 1, '土豆去皮、切丝（或用刨丝器）。', NULL);
INSERT INTO `recipe_step` VALUES (503547, 300524, 2, '切好的土豆丝用清水清洗，去除多余的淀粉，然后对土豆丝焯水 10 秒。沥干，备用。', NULL);
INSERT INTO `recipe_step` VALUES (503548, 300524, 3, '葱切成葱花；大蒜拍碎切成蒜末（分为两等份备用）；干辣椒切小段；青红椒切丝。', NULL);
INSERT INTO `recipe_step` VALUES (503549, 300524, 4, '热锅，小火热油，下入一半的葱花（葱白部分）、一半的蒜末和干辣椒爆香。', NULL);
INSERT INTO `recipe_step` VALUES (503550, 300524, 5, '加入青红椒翻炒几下，加入土豆丝翻炒至变色。', NULL);
INSERT INTO `recipe_step` VALUES (503551, 300524, 6, '加 5ml 生抽，10ml 陈醋，倒入剩下的一半蒜末和 2g 盐快速翻炒均匀。', NULL);
INSERT INTO `recipe_step` VALUES (503552, 300524, 7, '出锅前撒上剩余的葱花，翻匀即可装盘。', NULL);
INSERT INTO `recipe_step` VALUES (503553, 300525, 1, '下入100g大豆油、50g熟猪油、60g蒜子、30g剁椒，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (503554, 300525, 2, '下入1800g大白菜、5g鸡精、10g盐、35g生抽，炒制3分20秒；', NULL);
INSERT INTO `recipe_step` VALUES (503555, 300525, 3, '最后下入10g陈醋，翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (503556, 300526, 1, '下入 200g 大豆油、100g 蒜子、7g 干红椒、50g 剁椒，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (503557, 300526, 2, '加入 1400g 泡发后的海带丝、10g 盐、10g 鸡精、50g 生抽、40g 陈醋，大火爆炒 2 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503558, 300527, 1, '【蕨根粉的煮制】锅中加入约为深度 3/5 的水，烧开', NULL);
INSERT INTO `recipe_step` VALUES (503559, 300527, 2, '【蕨根粉的煮制】水沸腾后加入蕨根粉，中小火煮 8 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503560, 300527, 3, '【蕨根粉的煮制】出锅', NULL);
INSERT INTO `recipe_step` VALUES (503561, 300527, 4, '【酱料的调制】根据配比，加入酱油、醋、油泼辣子', NULL);
INSERT INTO `recipe_step` VALUES (503562, 300527, 5, '【酱料的调制】用筷子蘸取，尝一口', NULL);
INSERT INTO `recipe_step` VALUES (503563, 300527, 6, '【酱料的调制】如果觉得此时酱油味稍浓，加入准备好的盐', NULL);
INSERT INTO `recipe_step` VALUES (503564, 300527, 7, '【酱料的调制】如果觉得此时不够鲜，加入准备好的糖', NULL);
INSERT INTO `recipe_step` VALUES (503565, 300527, 8, '【酱料的调制】充分搅拌至大部分颗粒状调料溶解', NULL);
INSERT INTO `recipe_step` VALUES (503566, 300527, 9, '【装盘与完成步骤】取一个碗', NULL);
INSERT INTO `recipe_step` VALUES (503567, 300527, 10, '【装盘与完成步骤】加入上一步调制的酱料', NULL);
INSERT INTO `recipe_step` VALUES (503568, 300527, 11, '【装盘与完成步骤】将蕨根粉过冷水后放入酱料中', NULL);
INSERT INTO `recipe_step` VALUES (503569, 300527, 12, '【装盘与完成步骤】充分搅拌', NULL);
INSERT INTO `recipe_step` VALUES (503570, 300527, 13, '【装盘与完成步骤】将准备的葱、蒜、小米辣切碎后撒在粉上', NULL);
INSERT INTO `recipe_step` VALUES (503571, 300527, 14, '【装盘与完成步骤】完成啦(｡･∀･)ﾉﾞ', NULL);
INSERT INTO `recipe_step` VALUES (503572, 300528, 1, '排骨中加入 5 g 地瓜粉和水进行搅拌，清洗 2-3 遍后放入大碗备用', NULL);
INSERT INTO `recipe_step` VALUES (503573, 300528, 2, '排骨中加入鱼露、地瓜粉、鸡蛋黄 充分搅拌', NULL);
INSERT INTO `recipe_step` VALUES (503574, 300528, 3, '将排骨一个一个放入锅中（切记不可以整碗倒入），保证每个不要粘在一起', NULL);
INSERT INTO `recipe_step` VALUES (503575, 300528, 4, '全部放入后，每 30 S 用勺子来回两面翻转瘦肉块，直至排骨表面金黄', NULL);
INSERT INTO `recipe_step` VALUES (503576, 300528, 5, '取出排骨，一分钟后倒入油锅中继续炸，直至瘦肉块表面出现焦黄后，取出放入大碗备用', NULL);
INSERT INTO `recipe_step` VALUES (503577, 300528, 6, '准备一个小碗，加入蒜末、香醋、白砂糖、鱼露、番茄酱、葱花、芝麻搅拌均匀，倒入 5 ml 热油', NULL);
INSERT INTO `recipe_step` VALUES (503578, 300528, 7, '将汤汁浇灌入排骨，在充分搅拌后倒入盘中', NULL);
INSERT INTO `recipe_step` VALUES (503579, 300529, 1, '将水倒入锅中并煮沸', NULL);
INSERT INTO `recipe_step` VALUES (503580, 300529, 2, '放入小汤圆煮 8 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503581, 300529, 3, '放入醪糟和枸杞再煮 2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503582, 300529, 4, '盛入碗中根据个人口味加入白糖并搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (503583, 300529, 5, '吃', NULL);
INSERT INTO `recipe_step` VALUES (503584, 300530, 1, '将金枪鱼、蛋黄酱、俄式酸黄瓜汁倒入碗中，用勺子搅拌，保证将金枪鱼块搅碎，酱整体呈糊状，并备用', NULL);
INSERT INTO `recipe_step` VALUES (503585, 300530, 2, '将 1 片吐司放在轻食机上', NULL);
INSERT INTO `recipe_step` VALUES (503586, 300530, 3, '将做好的金枪鱼酱涂抹到吐司上，建议 10-15ml', NULL);
INSERT INTO `recipe_step` VALUES (503587, 300530, 4, '将另一片方形吐司片覆盖在上面，并按压轻食机，开机', NULL);
INSERT INTO `recipe_step` VALUES (503588, 300530, 5, '待轻食机自动停止加热，即可装盘使用', NULL);
INSERT INTO `recipe_step` VALUES (503589, 300531, 1, '将柠檬对半切（刀方向垂直于柠檬的头尾连线），并从其中的一半中切取一片柠檬备用', NULL);
INSERT INTO `recipe_step` VALUES (503590, 300531, 2, '再次将柠檬对半切，将得到的 4 角柠檬用压汁器压出柠檬汁置于容器中备用', NULL);
INSERT INTO `recipe_step` VALUES (503591, 300531, 3, '选择一个杯子，建议使用容量在 350~400 毫升的透明玻璃杯', NULL);
INSERT INTO `recipe_step` VALUES (503592, 300531, 4, '将 100 克冰块放置在杯底', NULL);
INSERT INTO `recipe_step` VALUES (503593, 300531, 5, '倒入 30~40 毫升金酒', NULL);
INSERT INTO `recipe_step` VALUES (503594, 300531, 6, '倒入 15 毫升柠檬汁（如果喜酸可以加多点或全加）', NULL);
INSERT INTO `recipe_step` VALUES (503595, 300531, 7, '用勺子搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (503596, 300531, 8, '将之前准备的一片柠檬放置好', NULL);
INSERT INTO `recipe_step` VALUES (503597, 300531, 9, '缓慢沿杯壁注入汤力水直至满杯（不要倒在冰上，避免起泡流失）', NULL);
INSERT INTO `recipe_step` VALUES (503598, 300531, 10, '用勺子轻轻上下提拉将液体搅拌均匀（不要旋转搅拌，避免起泡流失）', NULL);
INSERT INTO `recipe_step` VALUES (503599, 300531, 11, '在液面放置好装饰用的绿叶（可选）', NULL);
INSERT INTO `recipe_step` VALUES (503600, 300532, 1, '底汤调配（10 份）： 1700g 白开水中加入 240g 金汤，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (503601, 300532, 2, '150g 去皮巴沙鱼片下入沸水中汆烫至鱼肉变白，冲凉备用；', NULL);
INSERT INTO `recipe_step` VALUES (503602, 300532, 3, '餐具中加入 100g 小叶酸菜、烫制鱼片和 180g 底汤，蒸柜上汽后，蒸制 7 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503603, 300532, 4, '出品时浇淋 15g 糊辣油并撒 1g 葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (503604, 300533, 1, '底汤调配（5 份）： 2480g 白开水、350g 金汤，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (503605, 300533, 2, '80g 娃娃菜和泡发好的 85g 粉丝下入沸水中汆烫 10 秒，捞起沥水后倒入装有 80g 小叶酸菜的餐具中，再将 150g 黑鱼片下入沸水中汆烫 30 秒，捞起沥水后平铺在娃娃菜、玉耳上，倒入 500g 底汤；', NULL);
INSERT INTO `recipe_step` VALUES (503606, 300533, 3, '锅中倒入 20g 大豆油烧至 120℃，关火后下入 5g 干红椒、2g 干青花椒、5g 蒜末爆香 2 秒，倒入黑鱼片上，出品撒1g 芝麻和 1g 葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (503607, 300534, 1, '每1只鸡使用2g盐均匀揉搓鸡的表皮，处理后冷藏20分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503608, 300534, 2, '在锅中加入1一只鸡、75g调味料（鸡汤专用）、5500g农夫山泉水炖煮约60分钟（根据鸡的大小，调味品适度增减）；', NULL);
INSERT INTO `recipe_step` VALUES (503609, 300534, 3, '将肥西老母鸡捞出后冷却至常温，剁成1.0cm×2.0cm×3.0cm的块状；', NULL);
INSERT INTO `recipe_step` VALUES (503610, 300534, 4, '剁好的鸡块放入汤中，加入35g盐炖煮15分钟；出品前捞去浮沫。', NULL);
INSERT INTO `recipe_step` VALUES (503611, 300535, 1, '将柠檬对半切（刀方向垂直于柠檬的头尾连线），并从其中的一半中切取一片柠檬备用', NULL);
INSERT INTO `recipe_step` VALUES (503612, 300535, 2, '再次将柠檬对半切，将得到的 4 角柠檬用压汁器压出柠檬汁置于容器中备用', NULL);
INSERT INTO `recipe_step` VALUES (503613, 300535, 3, '选择一个杯子，建议使用容量在 350~400 毫升的透明玻璃杯', NULL);
INSERT INTO `recipe_step` VALUES (503614, 300535, 4, '将 100 克冰块放置在杯底', NULL);
INSERT INTO `recipe_step` VALUES (503615, 300535, 5, '倒入 30~40 毫升金酒', NULL);
INSERT INTO `recipe_step` VALUES (503616, 300535, 6, '倒入 20 毫升柠檬汁（如果喜酸可以加多点或全加）', NULL);
INSERT INTO `recipe_step` VALUES (503617, 300535, 7, '倒入 30~40 克蔗糖糖浆', NULL);
INSERT INTO `recipe_step` VALUES (503618, 300535, 8, '用勺子搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (503619, 300535, 9, '将之前准备的一片柠檬放置好', NULL);
INSERT INTO `recipe_step` VALUES (503620, 300535, 10, '缓慢沿杯壁注入苏打气泡水直至满杯（不要倒在冰上，避免起泡流失）', NULL);
INSERT INTO `recipe_step` VALUES (503621, 300535, 11, '用勺子轻轻上下提拉将液体搅拌均匀（不要旋转搅拌，避免起泡流失）', NULL);
INSERT INTO `recipe_step` VALUES (503622, 300535, 12, '在液面放置好装饰用的绿叶（可选）', NULL);
INSERT INTO `recipe_step` VALUES (503623, 300535, 13, '将冰块、金酒、柠檬汁、蔗糖糖浆倒入雪克瓶，雪克均匀', NULL);
INSERT INTO `recipe_step` VALUES (503624, 300535, 14, '将充分雪克的产物倒到杯子中（如果里面的冰太碎了，可以选择过滤其中的冰，重新往杯中补充冰块）', NULL);
INSERT INTO `recipe_step` VALUES (503625, 300536, 1, '豆腐切片，小火煎到两面金黄出锅备用。', NULL);
INSERT INTO `recipe_step` VALUES (503626, 300536, 2, '切蒜成蒜末；将生抽，蚝油，老抽，糖，100ml 水调汁备用。', NULL);
INSERT INTO `recipe_step` VALUES (503627, 300536, 3, '热锅放油，油热放小米椒、蒜末爆香，先放金针菇，炒软，把煎好的豆腐平铺在金针菇上，倒入2 配好的料汁，焖 5 分钟，大火收汁。', NULL);
INSERT INTO `recipe_step` VALUES (503628, 300537, 1, '金针菇徒手掰散，越散越好不然容易藏牙，洗净备用。', NULL);
INSERT INTO `recipe_step` VALUES (503629, 300537, 2, '用菜刀或者水果刀将上述金针菇段段切，可依据个人喜好，但长度不宜超过 5 cm。', NULL);
INSERT INTO `recipe_step` VALUES (503630, 300537, 3, '将金针菇放入锅中，加水没过约食材总高度 1.1 倍，沸腾后等待 3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503631, 300537, 4, '加入味精和食盐并搅拌。', NULL);
INSERT INTO `recipe_step` VALUES (503632, 300537, 5, '继续加热约 30 秒，关火装盘。', NULL);
INSERT INTO `recipe_step` VALUES (503633, 300538, 1, '鸡蛋冷水下锅，大火煮开转小火煮 8 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503634, 300538, 2, '用自来水冲凉，方便剥皮', NULL);
INSERT INTO `recipe_step` VALUES (503635, 300538, 3, '蒜切沫（粒径不大于 1 mm），线椒和小米辣切小粒（约 2-3 mm）', NULL);
INSERT INTO `recipe_step` VALUES (503636, 300538, 4, '每个熟鸡蛋沿短轴切成体积类似的 4 份', NULL);
INSERT INTO `recipe_step` VALUES (503637, 300538, 5, '如果打算沾淀粉，每片鸡蛋粘上淀粉，抖掉多余的淀粉', NULL);
INSERT INTO `recipe_step` VALUES (503638, 300538, 6, '锅内放入 25 ml 油（如果不沾淀粉，放 20 ml），放入熟鸡蛋片', NULL);
INSERT INTO `recipe_step` VALUES (503639, 300538, 7, '煎至微焦黄后，补 10 ml 油（如果不沾淀粉，补 10 ml），翻面', NULL);
INSERT INTO `recipe_step` VALUES (503640, 300538, 8, '第二面微黄后，加入线椒、小米辣、蒜末煎制约一分钟，翻面', NULL);
INSERT INTO `recipe_step` VALUES (503641, 300538, 9, '接着加豆瓣酱煎制约几十秒，翻面', NULL);
INSERT INTO `recipe_step` VALUES (503642, 300538, 10, '生抽、耗油、糖调成汁，轻轻颠锅后即可出锅', NULL);
INSERT INTO `recipe_step` VALUES (503643, 300539, 1, '汤底调制（10份）：1000g开水中加入330g肥牛汁，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (503644, 300539, 2, '安格斯肥牛煮制：(1) 奶锅中下入30g大豆油，烧至160℃; (2) 下入60g洋葱丝，炒至微黄; (3) 下入130g照烧肥牛汁、70g金针菇烧开; (4) 下入100g肥牛片煮至肥牛片完全熟透，倒入铜锅中出品。', NULL);
INSERT INTO `recipe_step` VALUES (503645, 300540, 1, '汤底调制（10份）：28000g开水中加入300g水煮料调味酱和400g毛血旺酱，搅拌均匀；', NULL);
INSERT INTO `recipe_step` VALUES (503646, 300540, 2, '铜锅川味水煮肉片煮制：(1) 奶锅中入300g汤底（需搅拌均匀）5档烧开；(2) 下入50g娃娃菜、50g莴笋片和30g木耳，煮制入味；(3) 下入100g调理肉片煮至变色，加入2g干红椒、5g蒜末，淋入10g烧至120℃的大豆油爆香，最后撒入1g葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (503647, 300541, 1, '汤底调制（10份）：3000g开水中加入500g番茄汤膏、15g白砂糖，搅拌均匀备用；', NULL);
INSERT INTO `recipe_step` VALUES (503648, 300541, 2, '铜锅番茄虾滑煮制：锅中加入330g番茄汤底、80g虾滑、50g西红柿片、40g金针菇、40g娃娃菜、20g青菜烧开煮约1分30秒，倒入铜锅中撒入1g葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (503649, 300542, 1, '汤底调制（8份）：1200g开水中加入350g青花椒风味酱，搅拌均匀备用：', NULL);
INSERT INTO `recipe_step` VALUES (503650, 300542, 2, '炒线椒：锅中水分烧干，下入50g大豆油烧至160℃，加入300g线椒圈炒制约10秒，备用；', NULL);
INSERT INTO `recipe_step` VALUES (503651, 300542, 3, '豆花鸡煮制：(1) 奶锅中加入180g青花椒汤底（需搅拌均匀）烧开；(2) 加入170g豆花豆腐、100g鸡腿肉、30g炒线椒烧开后，煮2分钟，倒入铜锅中出品。', NULL);
INSERT INTO `recipe_step` VALUES (503652, 300543, 1, '放入上汽蒸柜中蒸制 5 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503653, 300544, 1, '把银耳、莲子用清水浸泡 2 个小时，红枣浸泡 10 - 20 分钟，枸杞洗净，备用', NULL);
INSERT INTO `recipe_step` VALUES (503654, 300544, 2, '在锅中倒入 600ml 水，烧开后依次放入银耳、莲子、红枣', NULL);
INSERT INTO `recipe_step` VALUES (503655, 300544, 3, '等待水再次烧开后，盖上锅盖，转至中火继续熬', NULL);
INSERT INTO `recipe_step` VALUES (503656, 300544, 4, '熬到大约 1 小时后，放入 5g - 10g 冰糖和 5g - 6g 枸杞，转至小火熬', NULL);
INSERT INTO `recipe_step` VALUES (503657, 300544, 5, '小火继续熬 30 分钟，此时银耳开始呈现粘稠状态', NULL);
INSERT INTO `recipe_step` VALUES (503658, 300544, 6, '再次放入 5g - 10g 冰糖，用勺子搅拌 5 - 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503659, 300544, 7, '关火，用勺子盛出', NULL);
INSERT INTO `recipe_step` VALUES (503660, 300545, 1, '银鱼预处理：水开后下入银鱼烫制15秒，立刻捞出过凉水；', NULL);
INSERT INTO `recipe_step` VALUES (503661, 300545, 2, '锅洗净，下入120g熟猪油；', NULL);
INSERT INTO `recipe_step` VALUES (503662, 300545, 3, '油热后下入60g拍蒜、15g葱段炒香；', NULL);
INSERT INTO `recipe_step` VALUES (503663, 300545, 4, '下入500g蛋液炒成蛋片；', NULL);
INSERT INTO `recipe_step` VALUES (503664, 300545, 5, '下入1500g水、12g盐、12g鸡精、300g银鱼烧煮；', NULL);
INSERT INTO `recipe_step` VALUES (503665, 300545, 6, '水开后煮30秒，再均匀淋入500g蛋液、15g葱段，出品。', NULL);
INSERT INTO `recipe_step` VALUES (503666, 300546, 1, '柠檬对半切，挤出 30ml 柠檬汁至杯中；', NULL);
INSERT INTO `recipe_step` VALUES (503667, 300546, 2, '依次向杯中加入： 15ml 金酒， 15ml 龙舌兰酒， 15ml 伏特加， 15ml 白朗姆酒， 15ml 橙味甜酒；', NULL);
INSERT INTO `recipe_step` VALUES (503668, 300546, 3, '向杯中缓慢倒入 20ml 枫糖浆，边倒边搅拌；', NULL);
INSERT INTO `recipe_step` VALUES (503669, 300546, 4, '向杯中加入 75ml 可乐；', NULL);
INSERT INTO `recipe_step` VALUES (503670, 300546, 5, '向杯中加入冰块直至满杯；', NULL);
INSERT INTO `recipe_step` VALUES (503671, 300546, 6, '轻轻搅拌 20 秒；', NULL);
INSERT INTO `recipe_step` VALUES (503672, 300546, 7, '开始享用.', NULL);
INSERT INTO `recipe_step` VALUES (503673, 300547, 1, '汤底调配：4200g水烧开后加入24g盐、60g鸡精、15g老抽、6g十三香、25g浓缩鸡汁，烧开后关火备用；', NULL);
INSERT INTO `recipe_step` VALUES (503674, 300547, 2, '组合：取15g青蒜花、15g熟猪油、1g白胡椒粉置于面碗中，舀入350g底汤；再将110g挂面放入面篓中煮制4分钟，捞起沥水后放入碗中出品。', NULL);
INSERT INTO `recipe_step` VALUES (503675, 300548, 1, '鱼处理好内脏，保留鱼鳞，清洗干净，从腹部剖开成两半（背部相连），用 15ml 料酒、姜片、食盐 3g 腌制 15 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503676, 300548, 2, '番茄切块，青椒红椒切块，大蒜拍碎，生姜切片，葱切段（葱白葱叶分开）', NULL);
INSERT INTO `recipe_step` VALUES (503677, 300548, 3, '用姜片擦拭锅底，热锅后倒入 30ml 食用油，油热后放入鱼（鱼皮朝下），煎至两面金黄、鱼鳞酥脆，盛出备用', NULL);
INSERT INTO `recipe_step` VALUES (503678, 300548, 4, '锅中留底油，放入葱白、姜片、蒜瓣爆香', NULL);
INSERT INTO `recipe_step` VALUES (503679, 300548, 5, '加入 15g 桂林辣椒酱，炒出红油', NULL);
INSERT INTO `recipe_step` VALUES (503680, 300548, 6, '放入番茄块，翻炒至番茄出汁变软', NULL);
INSERT INTO `recipe_step` VALUES (503681, 300548, 7, '倒入整瓶啤酒，加入 15ml 生抽、5ml 老抽、5g 白糖、5g 食盐，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (503682, 300548, 8, '放入煎好的鱼，大火烧开后转中小火，盖上锅盖焖煮 15-20 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503683, 300548, 9, '开盖，放入青椒红椒块，继续煮 3-5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503684, 300548, 10, '大火收汁至汤汁浓稠，撒上葱叶段，出锅装盘', NULL);
INSERT INTO `recipe_step` VALUES (503685, 300549, 1, '【备菜】排骨用热水过一边，去血水', NULL);
INSERT INTO `recipe_step` VALUES (503686, 300549, 2, '【备菜】陈皮、麦冬、玉竹、石斛和西洋参，冲洗干净即可', NULL);
INSERT INTO `recipe_step` VALUES (503687, 300549, 3, '【备菜】煲汤盅洗干净', NULL);
INSERT INTO `recipe_step` VALUES (503688, 300549, 4, '【操作】打开煲汤盅，先放入排骨在底部，然后依次放入陈皮、麦冬、玉竹、石斛和西洋参', NULL);
INSERT INTO `recipe_step` VALUES (503689, 300549, 5, '【操作】加入热水进煲汤盅，水不宜太满', NULL);
INSERT INTO `recipe_step` VALUES (503690, 300549, 6, '【操作】煲汤容器加入水，炖煮 1.5 小时即可', NULL);
INSERT INTO `recipe_step` VALUES (503691, 300549, 7, '【操作】加入食盐，趁热饮用', NULL);
INSERT INTO `recipe_step` VALUES (503692, 300550, 1, '葱切花，蒜切沫，姜切丝，备用。', NULL);
INSERT INTO `recipe_step` VALUES (503693, 300550, 2, '豆角去筋，切2-10cm小段，备用。', NULL);
INSERT INTO `recipe_step` VALUES (503694, 300550, 3, '土豆去皮，切1cm³小块，备用。', NULL);
INSERT INTO `recipe_step` VALUES (503695, 300550, 4, '西红柿去皮，切1cm³小块，备用。', NULL);
INSERT INTO `recipe_step` VALUES (503696, 300550, 5, '辣椒去仔，切0.15cm 宽条，备用。', NULL);
INSERT INTO `recipe_step` VALUES (503697, 300550, 6, '起锅烧油(10ml - 15ml)，冒烟后放入葱姜蒜，翻炒至闻到葱姜蒜香味；', NULL);
INSERT INTO `recipe_step` VALUES (503698, 300550, 7, '加入豆角，翻炒至变色（青绿色变为翠绿色）；', NULL);
INSERT INTO `recipe_step` VALUES (503699, 300550, 8, '加入土豆块，翻炒 30s；', NULL);
INSERT INTO `recipe_step` VALUES (503700, 300550, 9, '加入热水（水面刚刚漫过菜），盖上锅盖熬至土豆变软（可以用筷子确认）；', NULL);
INSERT INTO `recipe_step` VALUES (503701, 300550, 10, '加入西红柿块，加入盐，生抽，蚝油，五香粉，辣椒，熬至西红柿成汁（注意搅拌，防止糊锅）；', NULL);
INSERT INTO `recipe_step` VALUES (503702, 300550, 11, '加入香菜碎，出锅。', NULL);
INSERT INTO `recipe_step` VALUES (503703, 300551, 1, '【备料】扯面的话，用擀面杖（没有擀面杖，用手也行）上下两边轻压，两手拽住左侧和右侧两端，轻轻拉开', NULL);
INSERT INTO `recipe_step` VALUES (503704, 300551, 2, '【备料】葱切成葱花，蒜切成蒜末备用', NULL);
INSERT INTO `recipe_step` VALUES (503705, 300551, 3, '【备料】青菜洗净，豆芽洗净备用（如使用）', NULL);
INSERT INTO `recipe_step` VALUES (503706, 300551, 4, '【煮面与调味】锅中加入足量清水，大火烧开后加入 1g 盐', NULL);
INSERT INTO `recipe_step` VALUES (503707, 300551, 5, '【煮面与调味】放入面条，用筷子轻轻搅动防止粘连，煮至面条浮起后再煮 1-2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503708, 300551, 6, '【煮面与调味】在煮面的最后 1 分钟，放入青菜和豆芽焯水', NULL);
INSERT INTO `recipe_step` VALUES (503709, 300551, 7, '【煮面与调味】将煮好的面条和青菜、豆芽捞出，沥干水分后放入碗中', NULL);
INSERT INTO `recipe_step` VALUES (503710, 300551, 8, '【煮面与调味】在面条上依次加入生抽、香醋、葱花、蒜末和干辣椒面, 也可放点芝麻', NULL);
INSERT INTO `recipe_step` VALUES (503711, 300551, 9, '【泼油】炒锅中倒入食用油，同时放入花椒、八角、桂皮、香叶（如使用），小火炸出香味后捞出香料', NULL);
INSERT INTO `recipe_step` VALUES (503712, 300551, 10, '【泼油】待油温升至七成热（微微冒烟）时，迅速均匀地泼在碗中的干辣椒面上，听到“滋啦”声即可', NULL);
INSERT INTO `recipe_step` VALUES (503713, 300551, 11, '【泼油】用筷子将所有调料和面条充分拌匀即可食用', NULL);
INSERT INTO `recipe_step` VALUES (503714, 300552, 1, '饼干超过一元硬币大小先切成小块', NULL);
INSERT INTO `recipe_step` VALUES (503715, 300552, 2, '无盐黄油加入锅中，小火加热至无盐黄油完全融化', NULL);
INSERT INTO `recipe_step` VALUES (503716, 300552, 3, '棉花糖加入锅中，使用刮刀搅拌，直至棉花糖融化并与无盐黄油均匀融合', NULL);
INSERT INTO `recipe_step` VALUES (503717, 300552, 4, '20g 奶粉加入锅中，使用刮刀搅拌，奶粉与黄油棉花糖混合物搅拌均匀后立即关火', NULL);
INSERT INTO `recipe_step` VALUES (503718, 300552, 5, '准备好的所有混合坚果与饼干趁热加入锅中，使用刮刀搅拌', NULL);
INSERT INTO `recipe_step` VALUES (503719, 300552, 6, '搅拌到温度下降到手可以接触的温度后，戴上一次塑料手套，在锅中搓揉或者双手拿起拉扯，让饼干混合坚果与棉花糖黄油奶粉混合物分散均匀。', NULL);
INSERT INTO `recipe_step` VALUES (503720, 300552, 7, '将上述步骤混合物压入模具中，边角压实，擀面杖擀平，未满的一边用手尽量压成直边', NULL);
INSERT INTO `recipe_step` VALUES (503721, 300552, 8, '室温放凉，完全冷却后脱模，按照模具纹路切块，或切成自己喜欢的大小，撒上剩余奶粉，尽量使雪花酥每面都沾上奶粉', NULL);
INSERT INTO `recipe_step` VALUES (503722, 300553, 1, '面条汤底制做（5 份）：将 250g 西红柿片用 100g 大豆油炒制表皮收缩；加入 2800g 水、140g 汤料、100g 千张丝、400g 雪菜肉丝、75g 炒菜基料大火烧开后煮 2 分钟，备用；', NULL);
INSERT INTO `recipe_step` VALUES (503723, 300553, 2, '将 275g 手擀面在沸水中煮 3 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503724, 300553, 3, '舀取 650g 面条汤底于面碗中，放入煮好的面条，撒 3g 葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (503725, 300554, 1, '青椒清洗，去除根部，侧面切开，去除内部的子后在案板压平，备用（一定要去除青椒子，否则会在锅里炸开）', NULL);
INSERT INTO `recipe_step` VALUES (503726, 300554, 2, '葱切成半厘米小段，备用', NULL);
INSERT INTO `recipe_step` VALUES (503727, 300554, 3, '蒜去皮，切成碎末，备用', NULL);
INSERT INTO `recipe_step` VALUES (503728, 300554, 4, '皮蛋去皮，备用', NULL);
INSERT INTO `recipe_step` VALUES (503729, 300554, 5, '小米辣，切成 5-10mm 的小段，备用', NULL);
INSERT INTO `recipe_step` VALUES (503730, 300554, 6, '热锅，锅内放入 10ml - 20ml 食用油', NULL);
INSERT INTO `recipe_step` VALUES (503731, 300554, 7, '放入全部青椒，改小火保持锅子温度，煎至青椒变软（可以用筷子试一下，插入即透即可）', NULL);
INSERT INTO `recipe_step` VALUES (503732, 300554, 8, '关火，将皮蛋和青椒放入小铁盆中', NULL);
INSERT INTO `recipe_step` VALUES (503733, 300554, 9, '方法 1： 有擀面杖且砸东西不会吵到邻居：用擀面杖的一头在小盆中砸击皮蛋和青椒，至皮蛋与青椒混合（选项）', NULL);
INSERT INTO `recipe_step` VALUES (503734, 300554, 10, '方法 2：将青椒用手撕开，撕成大约半厘米的条状，用叉子将皮蛋压碎（选项）', NULL);
INSERT INTO `recipe_step` VALUES (503735, 300554, 11, '小米辣', NULL);
INSERT INTO `recipe_step` VALUES (503736, 300554, 12, '倒入生抽，陈醋，白糖，香油，以及其他未使用的备用食材', NULL);
INSERT INTO `recipe_step` VALUES (503737, 300554, 13, '均匀搅拌', NULL);
INSERT INTO `recipe_step` VALUES (503738, 300555, 1, '青椒去除根蒂切小块，土豆去皮切 2mm 薄片，猪肉切 4mm 薄片，葱横纵切 3mm 小段，姜蒜去皮拍散剁碎末；土豆淀粉加入约 15g 水搅拌均匀至水淀粉。', NULL);
INSERT INTO `recipe_step` VALUES (503739, 300555, 2, '起锅烧油，加热至 7 成热放入猪肉片，缓缓翻滚炒至去肉红色，加入约 3ml 酱油，翻炒肉片均匀上色，放入约 2g 盐。', NULL);
INSERT INTO `recipe_step` VALUES (503740, 300555, 3, '转 5 成油温，加入葱姜蒜炒 5 秒，然后加入土豆片，转 7 成油温均匀翻炒，加入约 5ml 酱油和 2g 盐，炒至土豆断生，表面轻微焦黄。', NULL);
INSERT INTO `recipe_step` VALUES (503741, 300555, 4, '转 8 成油温加入青椒，大火煸炒出锅气（有白烟冒出），反复均匀翻炒 1 分钟上色，最后在锅周围倒入水淀粉转 4 成火勾芡。', NULL);
INSERT INTO `recipe_step` VALUES (503742, 300555, 5, '在外观呈粘稠状态后关火，盛盘', NULL);
INSERT INTO `recipe_step` VALUES (503743, 300556, 1, '锅中下入150g菜籽油，烧至油温160℃;', NULL);
INSERT INTO `recipe_step` VALUES (503744, 300556, 2, '下入60g蒜子，炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (503745, 300556, 3, '下入1500g豆米翻炒1分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503746, 300556, 4, '再下入13g盐、13g鸡精、13g白砂糖，翻炒1分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503747, 300556, 5, '最后下入400g青椒丝，炒制30秒出品。', NULL);
INSERT INTO `recipe_step` VALUES (503748, 300557, 1, '下入 120g 大豆油，1000g 绿豆芽、100g 青椒、12g 盐、12g鸡精，大火爆炒出品。', NULL);
INSERT INTO `recipe_step` VALUES (503749, 300558, 1, '锅中下入 200g 大豆油，将 600g 鸡蛋液炒成鸡蛋片，盛出备用；', NULL);
INSERT INTO `recipe_step` VALUES (503750, 300558, 2, '锅中下入 100g 大豆油、1400g 青椒、60g 蒜子、20g 盐、10g 鸡精，爆炒至青椒断生；', NULL);
INSERT INTO `recipe_step` VALUES (503751, 300558, 3, '最后加入鸡蛋片，翻炒均匀出品。', NULL);
INSERT INTO `recipe_step` VALUES (503752, 300559, 1, '餐具放入150g豆米，30g螺丝椒丁、2g盐、2g鸡精、20g熟猪油；', NULL);
INSERT INTO `recipe_step` VALUES (503753, 300559, 2, '蒸柜上汽后，蒸制12分钟，出品。', NULL);
INSERT INTO `recipe_step` VALUES (503754, 300560, 1, '【准备馅料】猪肉洗净剁成肉馅（或用绞肉机），姜切末，葱切葱花', NULL);
INSERT INTO `recipe_step` VALUES (503755, 300560, 2, '【准备馅料】肉馅中加入姜末、葱花、生抽 15ml、老抽 5ml、食盐 3g，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (503756, 300560, 3, '【准备馅料】可选加入：料酒 10ml、蚝油 10ml、鸡蛋 1 个、淀粉 5g、白胡椒粉 2g、白糖 5g', NULL);
INSERT INTO `recipe_step` VALUES (503757, 300560, 4, '【准备馅料】朝一个方向搅拌肉馅至粘稠上劲，腌制 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503758, 300560, 5, '【处理青椒】青椒洗净，去蒂，用筷子小心挖去内部的籽和白筋，保持青椒完整不破', NULL);
INSERT INTO `recipe_step` VALUES (503759, 300560, 6, '【处理青椒】可选在青椒内壁撒干淀粉约 5g，摇晃均匀，帮助肉馅粘附不脱落', NULL);
INSERT INTO `recipe_step` VALUES (503760, 300560, 7, '【酿入肉馅】将腌好的肉馅用筷子或裱花袋塞入青椒中，尽量填满但不要太紧以防撑破', NULL);
INSERT INTO `recipe_step` VALUES (503761, 300560, 8, '【酿入肉馅】全部酿好后备用', NULL);
INSERT INTO `recipe_step` VALUES (503762, 300560, 9, '【调酱汁】碗中加入生抽 15ml、老抽 5ml、清水 100ml，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (503763, 300560, 10, '【调酱汁】可选加入淀粉 5g，使汤汁更浓稠', NULL);
INSERT INTO `recipe_step` VALUES (503764, 300560, 11, '【煎制焖煮】热锅，倒入 30ml 食用油，油温五六成热时放入酿好的青椒（肉面朝下先煎）', NULL);
INSERT INTO `recipe_step` VALUES (503765, 300560, 12, '【煎制焖煮】中小火慢煎，翻面使青椒各面都煎至表皮起皱呈虎皮色，盛出备用', NULL);
INSERT INTO `recipe_step` VALUES (503766, 300560, 13, '【煎制焖煮】锅留底油，可选放入蒜末爆香', NULL);
INSERT INTO `recipe_step` VALUES (503767, 300560, 14, '【煎制焖煮】倒入调好的酱汁，烧开后放入煎好的青椒', NULL);
INSERT INTO `recipe_step` VALUES (503768, 300560, 15, '【煎制焖煮】转中小火，盖上锅盖焖煮 5-8 分钟，至汤汁浓稠、青椒变软', NULL);
INSERT INTO `recipe_step` VALUES (503769, 300560, 16, '【煎制焖煮】开盖大火收汁至汤汁油亮包裹青椒，即可出锅装盘', NULL);
INSERT INTO `recipe_step` VALUES (503770, 300560, 17, '【虾滑 fork 版本】虾仁 250g 去虾线，用刀背拍成虾泥（保留一定颗粒感，口感更好，直接买成品虾滑得了，买那种三角形的裱花一样直接塞进去）', NULL);
INSERT INTO `recipe_step` VALUES (503771, 300560, 18, '【虾滑 fork 版本】虾滑馅调味：姜末 5g、食盐 2g、淀粉 5g、生抽 10ml', NULL);
INSERT INTO `recipe_step` VALUES (503772, 300560, 19, '【虾滑 fork 版本】可选加入：料酒 5ml、白胡椒粉 1g、蛋清半个', NULL);
INSERT INTO `recipe_step` VALUES (503773, 300560, 20, '【虾滑 fork 版本】朝一个方向搅拌至虾滑上劲，腌制 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503774, 300560, 21, '【虾滑 fork 版本】后续酿入、煎制、焖煮步骤与猪肉版本一致', NULL);
INSERT INTO `recipe_step` VALUES (503775, 300560, 22, '【虾滑 fork 版本】虾滑易熟，焖煮时间可缩短至 4-5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503776, 300561, 1, '烧一锅开水，水沸腾后放入鸡蛋，煮 7 分钟（得到完美的溏心蛋状态）。', NULL);
INSERT INTO `recipe_step` VALUES (503777, 300561, 2, '煮鸡蛋的期间调制酱汁：将 4 汤匙酱油、4 汤匙清水、2 汤匙味淋、2 汤匙白糖倒入小锅中。', NULL);
INSERT INTO `recipe_step` VALUES (503778, 300561, 3, '加热酱汁至沸腾，煮开以挥发掉味淋中的酒精味，随后关火放凉备用。', NULL);
INSERT INTO `recipe_step` VALUES (503779, 300561, 4, '将切好的辣椒圈加入放凉的酱汁中。', NULL);
INSERT INTO `recipe_step` VALUES (503780, 300561, 5, '将煮好的鸡蛋捞出，放入冰水中冷却后剥去蛋壳。', NULL);
INSERT INTO `recipe_step` VALUES (503781, 300561, 6, '将剥好的鸡蛋放入调好的酱汁中，表面淋上 5ml 芝麻油并撒上葱花。', NULL);
INSERT INTO `recipe_step` VALUES (503782, 300561, 7, '放入冰箱冷藏等待 1 - 2 小时，让鸡蛋充分入味。', NULL);
INSERT INTO `recipe_step` VALUES (503783, 300562, 1, '蔬菜清洗 切丝 放锅中翻炒 食材变软 便可称出', NULL);
INSERT INTO `recipe_step` VALUES (503784, 300562, 2, '煮水 等沸腾时 焯牛肉卷 只需煮熟 大概三分钟即可捞出', NULL);
INSERT INTO `recipe_step` VALUES (503785, 300562, 3, '煎溏心蛋', NULL);
INSERT INTO `recipe_step` VALUES (503786, 300562, 4, '将米饭放在一个碗里 然后倒扣在大碗', NULL);
INSERT INTO `recipe_step` VALUES (503787, 300562, 5, '将准备好的蔬菜和肉卷依次绕圈放在米饭上面 将煎蛋放中间', NULL);
INSERT INTO `recipe_step` VALUES (503788, 300562, 6, '备酱汁 10ml 韩式辣酱（甜辣口）+ 5ml 生抽 + 两瓶盖雪碧（减肥的话 可以放无糖雪碧）+ 10g 芝麻 + 5ml 芝麻油 搅拌上述酱汁，可以再加生抽和盐', NULL);
INSERT INTO `recipe_step` VALUES (503789, 300562, 7, '将备好的酱汁倒在摆好盘的碗中', NULL);
INSERT INTO `recipe_step` VALUES (503790, 300563, 1, '韭菜洗净，沥干水分', NULL);
INSERT INTO `recipe_step` VALUES (503791, 300563, 2, '韭菜切成约 3cm 长的小段，即为 韭菜段', NULL);
INSERT INTO `recipe_step` VALUES (503792, 300563, 3, '将鸡蛋打入碗中，搅匀，即为 鸡蛋液', NULL);
INSERT INTO `recipe_step` VALUES (503793, 300563, 4, '热锅，加入食用油', NULL);
INSERT INTO `recipe_step` VALUES (503794, 300563, 5, '油热后，倒入 鸡蛋液，快速翻炒至鸡蛋凝固成块，盛出备用，即为 炒好的鸡蛋', NULL);
INSERT INTO `recipe_step` VALUES (503795, 300563, 6, '锅中再加 5ml 食用油，放入 韭菜段，大火快速翻炒 30 秒', NULL);
INSERT INTO `recipe_step` VALUES (503796, 300563, 7, '向锅中加入 炒好的鸡蛋，翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (503797, 300563, 8, '加入盐，翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (503798, 300563, 9, '关火，盛盘', NULL);
INSERT INTO `recipe_step` VALUES (503799, 300564, 1, '将面粉放入大碗中，加入水，搅拌成光滑的面团，静置 30 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503800, 300564, 2, '韭菜洗净切碎，加入打散的鸡蛋、5g 盐，搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (503801, 300564, 3, '将面团分成小剂子，擀成薄圆饼，包入韭菜、虾仁、鸡蛋液。', NULL);
INSERT INTO `recipe_step` VALUES (503802, 300564, 4, '热锅，加入食用油，放入包好的韭菜盒子，煎至两面金黄，约 3-4 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503803, 300564, 5, '盛盘，稍凉后即可享用。', NULL);
INSERT INTO `recipe_step` VALUES (503804, 300565, 1, '将 60g 风干牛肉和 50g 酱料、10g 水翻拌均匀；', NULL);
INSERT INTO `recipe_step` VALUES (503805, 300565, 2, '50g 白干平铺于餐具底部；', NULL);
INSERT INTO `recipe_step` VALUES (503806, 300565, 3, '120g 拌好的牛肉平铺于白干上；', NULL);
INSERT INTO `recipe_step` VALUES (503807, 300565, 4, '蒸柜上汽后，蒸制 25 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503808, 300566, 1, '紫米饭团蒸制 15 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503809, 300566, 2, '原味肉松饭团、蜜枣谷物饭团蒸制 20 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503810, 300567, 1, '蒸柜上汽后，蒸制10 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503811, 300568, 1, '【准备工作】肉丝（没有肉丝，自己切）用生抽(3ml)，生粉混合均匀待用。', NULL);
INSERT INTO `recipe_step` VALUES (503812, 300568, 2, '【准备工作】将青椒洗净，再用滚刀手法切好备用。', NULL);
INSERT INTO `recipe_step` VALUES (503813, 300568, 3, '【准备工作】大蒜横切成片，香干切丝。', NULL);
INSERT INTO `recipe_step` VALUES (503814, 300568, 4, '【准备工作】淀粉与水(10ml)混合，搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (503815, 300568, 5, '【起锅】干净锅 15ml 油，不用等油热就倒入肉丝慢慢划散，肉丝熟了，立马捞出，留油到锅里。', NULL);
INSERT INTO `recipe_step` VALUES (503816, 300568, 6, '【起锅】将蒜片和香干放入锅中，加入 2ml 生抽，翻炒均匀。', NULL);
INSERT INTO `recipe_step` VALUES (503817, 300568, 7, '【起锅】2-3 分钟，看火大小，将青椒丝放入锅中混合，翻炒。', NULL);
INSERT INTO `recipe_step` VALUES (503818, 300568, 8, '【起锅】1 分钟后，放入肉丝混合。', NULL);
INSERT INTO `recipe_step` VALUES (503819, 300568, 9, '【起锅】倒入淀粉与水的混合物勾芡，加入盐 3g，鸡精 2g，翻炒 2-3 分钟出锅。', NULL);
INSERT INTO `recipe_step` VALUES (503820, 300568, 10, '【起锅】成品。', NULL);
INSERT INTO `recipe_step` VALUES (503821, 300569, 1, '芹菜去叶切段、切成不超过 4cm 的条状，备用', NULL);
INSERT INTO `recipe_step` VALUES (503822, 300569, 2, '香干切条，宽约小拇指，备用', NULL);
INSERT INTO `recipe_step` VALUES (503823, 300569, 3, '蒜头切片或者剁成蒜泥都行，备用', NULL);
INSERT INTO `recipe_step` VALUES (503824, 300569, 4, '辣椒切圈或者斜切成条都行，备用', NULL);
INSERT INTO `recipe_step` VALUES (503825, 300569, 5, '热锅，锅内放入 10ml - 15ml 食用油。等待 10 秒让油温升高', NULL);
INSERT INTO `recipe_step` VALUES (503826, 300569, 6, '放入花椒、大蒜爆香（可以吃姜的也可以额外放入一些姜片/姜丝）', NULL);
INSERT INTO `recipe_step` VALUES (503827, 300569, 7, '加入猪肉炒至变色，再加入 8ml 老抽上色翻炒均匀（有豆瓣酱的，可以放入 3ml 豆瓣酱一起翻炒）', NULL);
INSERT INTO `recipe_step` VALUES (503828, 300569, 8, '加入香干翻炒均匀（大约 2 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (503829, 300569, 9, '加入辣椒翻炒均匀（大约 1-2 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (503830, 300569, 10, '加入芹菜，放入 5g 盐翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503831, 300569, 11, '加入 3g 鸡精、5ml 蚝油翻炒均匀，即可出锅', NULL);
INSERT INTO `recipe_step` VALUES (503832, 300570, 1, '下入250g 大豆油，将1500g 鸡蛋液炒成鸡蛋片状；', NULL);
INSERT INTO `recipe_step` VALUES (503833, 300570, 2, '下入300g 香椿、60g 红椒、10g 盐、6g 鸡精，大火爆炒80秒出品。', NULL);
INSERT INTO `recipe_step` VALUES (503834, 300571, 1, '将五花肉条沿长边切片，每片厚 1mm-1.5mm，备用', NULL);
INSERT INTO `recipe_step` VALUES (503835, 300571, 2, '将切好的五花肉放置碗中，依次加入 8g 酱油，1g 盐，1g 味精，10g 料酒，两片姜，两朵拍扁的大蒜腌制 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503836, 300571, 3, '将生菜叶直接用手扒下来，洗干净，备用', NULL);
INSERT INTO `recipe_step` VALUES (503837, 300571, 4, '热锅，倒入 5ml 食用油。油轻微冒烟后下入五花肉。单面煎制焦黄色后翻面，另一边同理。', NULL);
INSERT INTO `recipe_step` VALUES (503838, 300571, 5, '五花肉出锅后，装盘。', NULL);
INSERT INTO `recipe_step` VALUES (503839, 300571, 6, '将豆瓣酱抹到菜叶上，卷着五花肉即可食用', NULL);
INSERT INTO `recipe_step` VALUES (503840, 300572, 1, '鱼开背杀好（让卖鱼的杀好，千万不要剖腹杀鱼，切记是开背），清洗干净', NULL);
INSERT INTO `recipe_step` VALUES (503841, 300572, 2, '鱼表面用盐涂抹均匀，倒入料酒约 80ml,姜末 20g，放入冰箱保鲜层进行腌制 1-2 天', NULL);
INSERT INTO `recipe_step` VALUES (503842, 300572, 3, '取出腌制好的鱼，用绳挂起晾晒至半干（约 1-2 天，具体时间需结合气温与阳光）', NULL);
INSERT INTO `recipe_step` VALUES (503843, 300572, 4, '食用前请将鱼用清水清洗，沥干水分（防止水遇油飞溅）', NULL);
INSERT INTO `recipe_step` VALUES (503844, 300572, 5, '开大火将锅烧热，迅速改小火，锅中放油，尽量保持整个锅表面有油，将鱼沿锅边划入锅内（先煎鱼背面）', NULL);
INSERT INTO `recipe_step` VALUES (503845, 300572, 6, '鱼入锅后（和翻面后），不要着急移动鱼的位置（此时容易破皮），煎约 30 秒后，尝试晃动锅', NULL);
INSERT INTO `recipe_step` VALUES (503846, 300572, 7, '背面煎约 1 分钟后，翻面煎约 1-2 分钟，煎至两面金黄', NULL);
INSERT INTO `recipe_step` VALUES (503847, 300572, 8, '等两面都煎好时，把鱼推向锅边一点，留点空间放入豆瓣酱炒香味，放入姜蒜，', NULL);
INSERT INTO `recipe_step` VALUES (503848, 300572, 9, '炒出佐料香味后，加入料酒，生抽，老抽，倒入热水，水量和鱼平齐或者少点', NULL);
INSERT INTO `recipe_step` VALUES (503849, 300572, 10, '此时改中大火，煮 5-10 分钟，后放入青椒断，白糖，鸡精，十三香，陈醋', NULL);
INSERT INTO `recipe_step` VALUES (503850, 300572, 11, '改小火 2-5 分钟，放入葱，香菜，即可出锅', NULL);
INSERT INTO `recipe_step` VALUES (503851, 300573, 1, '香大元分切成片；18g生抽、12g调味料、300g水混匀成调味水；', NULL);
INSERT INTO `recipe_step` VALUES (503852, 300573, 2, '将100g香大元放入餐具，50g香肠平铺在上，并加入30g调味水；', NULL);
INSERT INTO `recipe_step` VALUES (503853, 300573, 3, '蒸柜上汽后，蒸制10分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503854, 300574, 1, '香肠分切成片；', NULL);
INSERT INTO `recipe_step` VALUES (503855, 300574, 2, '将 120g 豆米放入餐具底部，撒上 1g 盐、1g 鸡精、13g 鸡油；', NULL);
INSERT INTO `recipe_step` VALUES (503856, 300574, 3, '将 30g 香肠片平铺在豆米上,并加入 20g 老鸡汤；', NULL);
INSERT INTO `recipe_step` VALUES (503857, 300574, 4, '待蒸柜上汽后，蒸制 12 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503858, 300575, 1, '土豆丝饼放入 190℃ 的油中油炸 40-60 秒至金黄色（炸制 30 秒后翻面）。', NULL);
INSERT INTO `recipe_step` VALUES (503859, 300576, 1, '春卷放入190℃的油中炸制4～5 分钟（两面各2 分钟）。', NULL);
INSERT INTO `recipe_step` VALUES (503860, 300577, 1, '调味汁（10 份）：120g 恒顺陈醋、100g 芝麻香油、150g 味极鲜酱油、40g 白砂糖、60g 水、100g 红椒、50g 京葱；', NULL);
INSERT INTO `recipe_step` VALUES (503861, 300577, 2, '取 120g 木耳，在沸水中汆烫 10 秒；', NULL);
INSERT INTO `recipe_step` VALUES (503862, 300577, 3, '将烫好的木耳放入餐具中，加入 65g 调味汁出品。', NULL);
INSERT INTO `recipe_step` VALUES (503863, 300578, 1, '薯饼无需解冻直接放入170℃的油锅中炸制3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503864, 300579, 1, '香芋地瓜丸无需解冻，直接放入170℃的油锅中炸制6 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503865, 300580, 1, '调味水配制（3 份）：将 300g 热水、13g 调味粉和 9g 熟猪油混合均匀；', NULL);
INSERT INTO `recipe_step` VALUES (503866, 300580, 2, '取 100g 香芋块放入餐具，将 80g 调理排骨均匀平铺在香芋块上；', NULL);
INSERT INTO `recipe_step` VALUES (503867, 300580, 3, '加入 80g 调味水，直至没过香芋块；', NULL);
INSERT INTO `recipe_step` VALUES (503868, 300580, 4, '蒸柜上汽后，蒸制 18 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503869, 300581, 1, '温水泡发干香菇', NULL);
INSERT INTO `recipe_step` VALUES (503870, 300581, 2, '姜切小块，葱切段，蒜对半切小粒', NULL);
INSERT INTO `recipe_step` VALUES (503871, 300581, 3, '鸡腿去骨（不去骨也可，只是略影响程序员吃饭的效率而已），切成小块', NULL);
INSERT INTO `recipe_step` VALUES (503872, 300581, 4, '泡发的香菇一分为四，香菇水留着备用', NULL);
INSERT INTO `recipe_step` VALUES (503873, 300581, 5, '鸡腿肉焯水 1 分钟，去除血沫和杂质', NULL);
INSERT INTO `recipe_step` VALUES (503874, 300581, 6, '鸡腿肉中加料酒 15ml、生抽 15ml、盐 1.5g、老抽 15ml，抓匀', NULL);
INSERT INTO `recipe_step` VALUES (503875, 300581, 7, '油温 3 成，下入鸡腿肉煸炒，等鸡腿肉金黄后盛出备用', NULL);
INSERT INTO `recipe_step` VALUES (503876, 300581, 8, '锅留底油，下入葱、姜、蒜炒香，香菇入锅，大火翻匀', NULL);
INSERT INTO `recipe_step` VALUES (503877, 300581, 9, '等待 20 秒会有香菇香味从锅中飘出，此时下入煸炒过的鸡腿肉，下入香菇水（全部，本程序员认为的灵魂操作）、糖 15ml、生抽 30ml', NULL);
INSERT INTO `recipe_step` VALUES (503878, 300581, 10, '转中火不盖盖，咕嘟 2 分钟收浓汤汁，淋入香油 5ml，撒上葱花后即可关火、装盘', NULL);
INSERT INTO `recipe_step` VALUES (503879, 300582, 1, '蒸柜上汽后，蒸制 10 分钟，出品。', NULL);
INSERT INTO `recipe_step` VALUES (503880, 300583, 1, '下入60g大豆油、50g熟猪油、1300g青菜、150g香菇片、9g盐、7g鸡精、5g白砂糖，大火爆炒2分20秒出品。', NULL);
INSERT INTO `recipe_step` VALUES (503881, 300584, 1, '蒸柜上汽后，蒸制 10 分钟，出品。', NULL);
INSERT INTO `recipe_step` VALUES (503882, 300585, 1, '每只鸡用2g 盐均匀揉搓鸡表皮，冷藏20 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503883, 300585, 2, '每500g 老母鸡，加入16g 盐、60g 鸡油、2500g 水，烧开后炖制60 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503884, 300585, 3, '将110g 挂面在沸水中煮4 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503885, 300585, 4, '取65g 老母鸡块、1 个香菇、3 颗青菜和20g 蛋皮在沸水中烫30 秒；', NULL);
INSERT INTO `recipe_step` VALUES (503886, 300585, 5, '舀取500g 的老鸡汤于面碗中，放入煮好的面条和配菜。', NULL);
INSERT INTO `recipe_step` VALUES (503887, 300586, 1, '汤底调制：将150g 牛肉面汤料、20g 姜片、10g 香葱、5000g水，烧开后煮20 分钟，捞渣备用；', NULL);
INSERT INTO `recipe_step` VALUES (503888, 300586, 2, '香辣牛肉大火烧开，转小火焖煮5 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503889, 300586, 3, '将220g 手擀面和3 颗青菜放入沸水中煮2 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503890, 300586, 4, '舀取350g 的汤底于面碗中，放入煮好的面条；', NULL);
INSERT INTO `recipe_step` VALUES (503891, 300586, 5, '将50g 牛肉、3 颗青菜、1 个卤蛋摆放于面条上，浇上150g牛肉汤，撒上10g 蒜花和5g 香菜末出品。', NULL);
INSERT INTO `recipe_step` VALUES (503892, 300587, 1, '130g 生鲜面煮2 分钟，青菜烫制20 秒，红烧牛腩蒸制15 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503893, 300587, 2, '面碗中加入250g 汤底，放入85g 红烧牛腩、100g 牛腩汤汁，撒入香菜、蒜花出品。', NULL);
INSERT INTO `recipe_step` VALUES (503894, 300588, 1, '每500g鸡用5g盐、3g鸡精、3g葱段、3g姜片腌制20分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503895, 300588, 2, '香辣红油蘸料1包，添加20g陈醋、50g生抽、30g蒜末，充分搅拌均匀后备用；', NULL);
INSERT INTO `recipe_step` VALUES (503896, 300588, 3, '腌制好的小母鸡放入蒸柜中蒸制20-35分钟，将蒸制后的小母鸡取出，分切为宽度1.5-2厘米，长度6-8cm的块状，每份鸡块标准重量为190g；', NULL);
INSERT INTO `recipe_step` VALUES (503897, 300588, 4, '菜品出品之前放入蒸柜蒸制3分钟，出品时淋入40g调配好的蘸料，撒上1g葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (503898, 300589, 1, '香辣红油蘸料1包，添加20g陈醋、50g生抽、30g蒜末，充分搅拌均匀后备用；', NULL);
INSERT INTO `recipe_step` VALUES (503899, 300589, 2, '将鸡腿、鸡翅、鸡身切分为宽度1.5-2cm、长度6-8cm的块状，鸡脖、鸡爪分切为宽度约1.5cm的块状，每份鸡块标准重量为190g；', NULL);
INSERT INTO `recipe_step` VALUES (503900, 300589, 3, '取190g切好的白切鸡块放入餐具中，出品之前放入蒸柜蒸制3分钟，出品时淋入40g调配好的蘸料，撒上1g葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (503901, 300590, 1, '香辣红油蘸料1包，添加20g陈醋、50g生抽、30g蒜末，充分搅拌均匀后备用；', NULL);
INSERT INTO `recipe_step` VALUES (503902, 300590, 2, '锅中加水、盐、完全解冻沥干水分的鸡排腿，开最大档位烧开后，转1档煮40分钟，关火继续在锅中浸泡10分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503903, 300590, 3, '待鸡排腿冷却完全后，分切成长5-8厘米，宽2-2.5厘米的块状，每份鸡块标准重量为190g；', NULL);
INSERT INTO `recipe_step` VALUES (503904, 300590, 4, '菜品出品之前放入蒸柜蒸制3分钟，出品时淋入40g调配好的蘸料，撒上1g葱花点缀。', NULL);
INSERT INTO `recipe_step` VALUES (503905, 300591, 1, '取 180g 鸡血置于餐具中，在血旺上均匀倒入 50g 血旺料；', NULL);
INSERT INTO `recipe_step` VALUES (503906, 300591, 2, '蒸柜上汽后，蒸制 10 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (503907, 300592, 1, '香辣鸡丁炒制：', NULL);
INSERT INTO `recipe_step` VALUES (503908, 300592, 2, '将275g 手擀面或130g 鲜面、25g 青菜在沸水中煮3 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503909, 300592, 3, '面碗中加入15g 牛肉面汤底料、15g 拌菜红油、5g 蒜蓉、5g 熟猪油、15g 芝麻酱料，放入煮好的面条和青菜；', NULL);
INSERT INTO `recipe_step` VALUES (503910, 300592, 4, '舀取125g 香辣鸡丁放于面条上，撒上5g 葱花出品。', NULL);
INSERT INTO `recipe_step` VALUES (503911, 300593, 1, '将 3200g 水、1500g 鸡杂料、30g 盐倒入锅中，烧开后熬制 20 分钟，捞出料渣备用；', NULL);
INSERT INTO `recipe_step` VALUES (503912, 300593, 2, '料汁中倒入 1300g 清洗好的鸡肫炖煮 5 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503913, 300593, 3, '再加入 1500g 清洗好的鸡肝，继续炖煮 5 分钟；', NULL);
INSERT INTO `recipe_step` VALUES (503914, 300593, 4, '最后淋入 40g 芝麻香油，加入 40g 葱段。', NULL);
INSERT INTO `recipe_step` VALUES (503915, 300594, 1, '给鸡爪剪去指甲。如果买的鸡爪只有脚掌部分，对半切开即可。 如果是整只鸡爪，需要去骨。清水洗干净。', NULL);
INSERT INTO `recipe_step` VALUES (503916, 300594, 2, '鸡爪冷水下锅，葱姜料酒焯水，水开，撇去浮沫。', NULL);
INSERT INTO `recipe_step` VALUES (503917, 300594, 3, '加入香叶、八角、生抽、老抽，盖盖小火慢煮三十分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503918, 300594, 4, '捞出鸡爪，留一碗鸡汤备用。', NULL);
INSERT INTO `recipe_step` VALUES (503919, 300594, 5, '起锅烧油，用小火炒香姜末、蒜末、小米椒，能吃辣再放点辣椒面。加入生抽、老抽、蚝油、五香粉、盐，炒出酱香味。', NULL);
INSERT INTO `recipe_step` VALUES (503920, 300594, 6, '放入鸡爪，放一点盐调味，翻炒一两分钟，再倒入鸡汤，边炒边搅动。', NULL);
INSERT INTO `recipe_step` VALUES (503921, 300594, 7, '放入鸡精提鲜，撒入葱段搅拌均匀即可出锅。', NULL);
INSERT INTO `recipe_step` VALUES (503922, 300595, 1, '牛肉馅饼放入 190℃的油中炸制 3 分钟（两面各炸 1 分 30 秒）。', NULL);
INSERT INTO `recipe_step` VALUES (503923, 300596, 1, '6 个鸡米花无需解冻直接放入170℃的油锅中炸制3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503924, 300597, 1, '【预热烤箱】在准备蛋糕糊之前，可以开始预热烤箱至 350 ℉( 150 ℃)以节省时间', NULL);
INSERT INTO `recipe_step` VALUES (503925, 300597, 2, '【前期分离操作】从冰箱中取出新鲜的鸡蛋', NULL);
INSERT INTO `recipe_step` VALUES (503926, 300597, 3, '【前期分离操作】准备两个容器并擦干，分别盛放蛋清与蛋黄', NULL);
INSERT INTO `recipe_step` VALUES (503927, 300597, 4, '【前期分离操作】对盛放蛋清的容器，可稍有水珠，但不能有任何油；盛放蛋黄的容器不能有水珠', NULL);
INSERT INTO `recipe_step` VALUES (503928, 300597, 5, '【前期分离操作】打蛋，手工或利用分蛋器，将蛋清与蛋黄分离到两个容器中。', NULL);
INSERT INTO `recipe_step` VALUES (503929, 300597, 6, '【前期分离操作】分离过程中蛋黄不能破碎，蛋清中不能混有任何蛋黄，否则会严重影响打发。（白色系带可进入蛋清，不影响）', NULL);
INSERT INTO `recipe_step` VALUES (503930, 300597, 7, '【前期分离操作】（注意，不使用厨房机的情况下，盛放蛋清的容器也是打蛋的容器，为避免溢出，加入全部蛋清后不要超过容器的 1/8）', NULL);
INSERT INTO `recipe_step` VALUES (503931, 300597, 8, '【打发蛋白】蛋清中加入 1g 塔塔粉', NULL);
INSERT INTO `recipe_step` VALUES (503932, 300597, 9, '【打发蛋白】打蛋器高速，打发蛋白至粗大气泡的状态，加入 50g 赤藓糖醇', NULL);
INSERT INTO `recipe_step` VALUES (503933, 300597, 10, '【打发蛋白】打蛋器中低速，打发蛋白至干性发泡的状态（提起打蛋器头，有短小直立的尖角；倒扣容器，蛋白可粘住容器不掉下来）', NULL);
INSERT INTO `recipe_step` VALUES (503934, 300597, 11, '【打发蛋白】此时蛋白打发程度已符合要求 打蛋器应尽量贴近容器底部，防止出现上面浮着的表层打发，底部仍然是液体的情况）', NULL);
INSERT INTO `recipe_step` VALUES (503935, 300597, 12, '【混合其他原料】把分离的蛋黄加入打发的蛋清中，打蛋器中低速搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (503936, 300597, 13, '【混合其他原料】蛋清中加入 10g 可可粉和 10g 魔芋粉，先用餐刀翻拌，这是由于如果直接用打蛋器搅拌会造成粉末飞溅', NULL);
INSERT INTO `recipe_step` VALUES (503937, 300597, 14, '【混合其他原料】翻拌手法是 先用右手拿刮刀从搅拌盆中心插入面糊底部 向 8 点钟方向刮去直到碰到盆壁，顺势舀起面糊提到空中，然后再移回盆中心将面糊放入盆内 左手握住搅拌盆从 9 点钟方向转到 7 点钟方向，刚好旋转了 60 度，就完成了 1 次循环 速度大约是 1 秒钟 2 下 此方法出自《小岛老师的蛋糕教室》。用接地气的话说就是，像炒菜一样翻炒。', NULL);
INSERT INTO `recipe_step` VALUES (503938, 300597, 15, '【混合其他原料】翻拌结束后，打蛋器低速搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (503939, 300597, 16, '【烘烤】模具铺好烘焙纸，贴合底部与内壁', NULL);
INSERT INTO `recipe_step` VALUES (503940, 300597, 17, '【烘烤】将蛋糕糊倒入模具，然后用餐刀抹平，再然后震荡几下避免大气泡', NULL);
INSERT INTO `recipe_step` VALUES (503941, 300597, 18, '【烘烤】烘烤 25 分钟', NULL);
INSERT INTO `recipe_step` VALUES (503942, 300597, 19, '【烘烤】烤好后，戴好隔热手套取出', NULL);
INSERT INTO `recipe_step` VALUES (503943, 300597, 20, '【冷却与脱模】（可选） 将模具从高处落下，震出其中的热气', NULL);
INSERT INTO `recipe_step` VALUES (503944, 300597, 21, '【冷却与脱模】模具倒扣 10 分钟，使蛋糕冷却 没有冷却的蛋糕立刻脱模会损伤蛋糕 此操作可能会烫手，注意戴好隔热手套', NULL);
INSERT INTO `recipe_step` VALUES (503945, 300597, 22, '【冷却与脱模】脱模，餐刀切块食用', NULL);
INSERT INTO `recipe_step` VALUES (503946, 300598, 1, '【制作腌料和香碗汁】制作腌料：将下列原料混合： 生抽 5ml 料酒 5ml 淀粉 5g 水 20ml 蛋清 1 个', NULL);
INSERT INTO `recipe_step` VALUES (503947, 300598, 2, '【制作腌料和香碗汁】制作香汁：将下列原料混合： 生抽 5ml 醋 15ml 白糖 10 克 盐 1 克 淀粉 5g 水 20ml', NULL);
INSERT INTO `recipe_step` VALUES (503948, 300598, 3, '【处理原料】用腌料腌制里脊肉 15-30 分钟。注意将肉抓匀。', NULL);
INSERT INTO `recipe_step` VALUES (503949, 300598, 4, '【处理原料】干木耳泡 4 个小时，洗净，切成小块。', NULL);
INSERT INTO `recipe_step` VALUES (503950, 300598, 5, '【处理原料】青椒洗净，去蒂，切成丝。', NULL);
INSERT INTO `recipe_step` VALUES (503951, 300598, 6, '【处理原料】胡萝卜洗净，切成丝，将胡萝卜丝焯水。', NULL);
INSERT INTO `recipe_step` VALUES (503952, 300598, 7, '【处理原料】姜、蒜切沫。', NULL);
INSERT INTO `recipe_step` VALUES (503953, 300598, 8, '【处理原料】葱切成 5mm 的小段。', NULL);
INSERT INTO `recipe_step` VALUES (503954, 300598, 9, '【炒熟各种材料】将锅烧热，加入 15ml 油。', NULL);
INSERT INTO `recipe_step` VALUES (503955, 300598, 10, '【炒熟各种材料】向锅内倒入准备好的腌肉，快速滑散至变白，盛出备用。', NULL);
INSERT INTO `recipe_step` VALUES (503956, 300598, 11, '【炒熟各种材料】将锅烧热，加入 5ml 油。', NULL);
INSERT INTO `recipe_step` VALUES (503957, 300598, 12, '【炒熟各种材料】倒入全部葱、姜、蒜、豆瓣酱。', NULL);
INSERT INTO `recipe_step` VALUES (503958, 300598, 13, '【炒熟各种材料】倒入全部胡萝卜，翻炒 20s 后，放入青椒和木耳，翻炒 2 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (503959, 300598, 14, '【炒熟各种材料】倒入炒过的肉。快速翻炒均匀。注意不要炒超过 20 秒。', NULL);
INSERT INTO `recipe_step` VALUES (503960, 300598, 15, '【炒熟各种材料】倒入香汁。快速翻炒均匀。注意不要炒超过 15 秒。', NULL);
INSERT INTO `recipe_step` VALUES (503961, 300598, 16, '【炒熟各种材料】关火，盛盘。', NULL);
INSERT INTO `recipe_step` VALUES (503962, 300599, 1, '【1. 鱼香肉丝炒制】① 180g 大豆油烧至 180℃，下入 500g 调理肉丝煸炒至肉丝变色；', NULL);
INSERT INTO `recipe_step` VALUES (503963, 300599, 2, '【1. 鱼香肉丝炒制】② 下入 600g 笋丝、300g 胡萝卜丝、300g 木耳丝翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (503964, 300599, 3, '【1. 鱼香肉丝炒制】③ 下入 300g 鱼香风味酱翻炒 2 分钟出品吗，备用。', NULL);
INSERT INTO `recipe_step` VALUES (503965, 300599, 4, '【2. 菜苔烫制】取 70g 菜苔，在沸水中烫 1 分钟，备用；', NULL);
INSERT INTO `recipe_step` VALUES (503966, 300599, 5, '【3. 装配】餐盒中放入 300g 米饭，将 1 份鱼香肉丝、70g 菜苔、半个卤蛋放在米饭，菜苔上淋入 15g 豉油汁，出品。', NULL);
INSERT INTO `recipe_step` VALUES (503967, 300600, 1, '鱼香肉丝炒制（10份）：(1) 180g大豆油烧至180℃，下入500g调理肉丝煸炒至肉丝变色；(2) 下入600g笋丝、300g胡萝卜丝、300g木耳丝翻炒均匀；(3) 下入300g鱼香风味酱翻炒2分钟，备用。', NULL);
INSERT INTO `recipe_step` VALUES (503968, 300600, 2, '包菜烫制：取70g包菜，在沸水中烫1分钟，备用；', NULL);
INSERT INTO `recipe_step` VALUES (503969, 300600, 3, '组合出品：餐盒中放入300g米饭，将1份鱼香肉丝、70g包菜、半个茶叶蛋放在米饭上，包菜上淋入10g豉油汁，出品。', NULL);
INSERT INTO `recipe_step` VALUES (503970, 300601, 1, '鱼香肉丝炒制（10份）：(1) 180g大豆油烧至180℃，下入500g调理肉丝煸炒至肉丝变色；(2) 下入600g笋丝、300g胡萝卜丝、300g木耳丝翻炒均匀；(3) 下入300g鱼香风味酱翻炒2分钟，备用。', NULL);
INSERT INTO `recipe_step` VALUES (503971, 300601, 2, '菜苔烫制：取70g菜苔，在沸水中烫1分钟，备用；', NULL);
INSERT INTO `recipe_step` VALUES (503972, 300601, 3, '组合出品：餐盒中放入300g米饭，将1份鱼香肉丝、70g菜苔、半个茶叶蛋放在米饭上，菜苔上淋入15g豉油汁，出品。', NULL);
INSERT INTO `recipe_step` VALUES (503973, 300602, 1, '将茄子切成条。', NULL);
INSERT INTO `recipe_step` VALUES (503974, 300602, 2, '将肉切成肉沫，葱姜蒜切碎、小米椒切丁。', NULL);
INSERT INTO `recipe_step` VALUES (503975, 300602, 3, '调鱼香汁：碗中放入盐、味精、糖、生抽、老抽、醋、水淀粉搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (503976, 300602, 4, '锅中倒入 300ml 油，开小火（小火容易掌控），等油温七成热（小火大约 40 秒，有烟冒出）放入茄子炸两分钟，当茄子边缘微黄就捞出。多出的油可以盛出以后炒菜用。', NULL);
INSERT INTO `recipe_step` VALUES (503977, 300602, 5, '锅中留 15-30ml 油，倒入肉沫炒至颜色变白就盛出来。', NULL);
INSERT INTO `recipe_step` VALUES (503978, 300602, 6, '锅中倒入 15-30ml 油，放入豆瓣酱、葱白、姜、蒜炒香，然后倒入肉沫翻炒均匀。', NULL);
INSERT INTO `recipe_step` VALUES (503979, 300602, 7, '加入 80-150ml 清水（水面预计茄子八成高度为准），倒入茄子、倒入料汁，爆炒入味收汁。最后放入葱翻炒均匀，就可以起锅了。', NULL);
INSERT INTO `recipe_step` VALUES (503980, 300603, 1, '（低脂版本）取 10 mL 冷水，加入复配食品增稠剂，调成糊糊', NULL);
INSERT INTO `recipe_step` VALUES (503981, 300603, 2, '（低脂版本）加入 25 mL 开水，搅拌至半透明凝胶', NULL);
INSERT INTO `recipe_step` VALUES (503982, 300603, 3, '（低脂版本）冷却后混入 280 g 纯瘦肉糜 + 15 g 融化猪油（或鸡油）', NULL);
INSERT INTO `recipe_step` VALUES (503983, 300603, 4, '将猪肉末与生姜末、葱末混合，加入酱油、料酒、盐、糖、白胡椒粉，顺一个方向搅拌上劲', NULL);
INSERT INTO `recipe_step` VALUES (503984, 300603, 5, '如果使用浓汤宝，取浓汤宝块加入 15 mL 热水混合，搅拌至乳浊液完全分散，再加入 15 mL 常温水', NULL);
INSERT INTO `recipe_step` VALUES (503985, 300603, 6, '慢慢加入水或高汤，继续搅拌，直到馅料吸收水分，变得粘稠，如果觉得肉馅太稠，补 5 mL 水继续搅拌', NULL);
INSERT INTO `recipe_step` VALUES (503986, 300603, 7, '加入可选配料（冬笋、皮冻、香菇），最后淋上芝麻油，拌匀。冷藏 30 分钟，让味道融合', NULL);
INSERT INTO `recipe_step` VALUES (503987, 300603, 8, '取一张烧卖皮，放上约 20-25 g 馅料（别太贪心，否则包不住）', NULL);
INSERT INTO `recipe_step` VALUES (503988, 300603, 9, '用虎口轻轻收拢皮子边缘，形成“花瓶”状，顶部留开口', NULL);
INSERT INTO `recipe_step` VALUES (503989, 300603, 10, '用手指轻轻压实底部，确保站立稳定', NULL);
INSERT INTO `recipe_step` VALUES (503990, 300603, 11, '如果要加虾仁，在顶部加一颗虾仁', NULL);
INSERT INTO `recipe_step` VALUES (503991, 300603, 12, '重复包烧卖的步骤，直到包好', NULL);
INSERT INTO `recipe_step` VALUES (503992, 300603, 13, '放在蒸笼里，间隔开，避免粘连', NULL);
INSERT INTO `recipe_step` VALUES (503993, 300603, 14, '大火蒸 8-10 分钟即可', NULL);
INSERT INTO `recipe_step` VALUES (503994, 300604, 1, '盛好米饭，放入玉米粒拌好', NULL);
INSERT INTO `recipe_step` VALUES (503995, 300604, 2, '放入鲣鱼海苔碎', NULL);
INSERT INTO `recipe_step` VALUES (503996, 300605, 1, '鲤鱼清洗干净，改刀（在鱼身上多划几个伤口，方便入味）', NULL);
INSERT INTO `recipe_step` VALUES (503997, 300605, 2, '娃娃菜清洗干净放入盘中备用', NULL);
INSERT INTO `recipe_step` VALUES (503998, 300605, 3, '锅中加油，等油热放入“少盐” “姜” “蒜” “郫县豆瓣酱” “桂皮” “八角” 炒出香味', NULL);
INSERT INTO `recipe_step` VALUES (503999, 300605, 4, '把鱼放锅里煎（3 分钟）每（30 秒）需要翻面', NULL);
INSERT INTO `recipe_step` VALUES (504000, 300605, 5, '加入“水”（水量尽量和鱼平齐，可以少一点点） 放入 “生抽” “老抽” “娃娃菜”', NULL);
INSERT INTO `recipe_step` VALUES (504001, 300605, 6, '大火炖 15-20 分钟，汤汁快干时添加 “盐” 即可出锅', NULL);
INSERT INTO `recipe_step` VALUES (504002, 300606, 1, '鳊鱼改刀，放上姜片和料酒腌制 5-10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (504003, 300606, 2, '老豆腐切块后放入水中备用', NULL);
INSERT INTO `recipe_step` VALUES (504004, 300606, 3, '锅中加油，可以放点盐在锅里，防止煎鱼的时候粘锅，把腌制的鱼用厨房纸擦干水分，把鱼放到锅中，两面都煎一下', NULL);
INSERT INTO `recipe_step` VALUES (504005, 300606, 4, '等两面都煎好时，把鱼推向锅边一点，留点空间放入葱姜蒜，干辣椒，香叶，八角炒出味道', NULL);
INSERT INTO `recipe_step` VALUES (504006, 300606, 5, '炒出佐料香味后，加入料酒，生抽，老抽，冰糖，桂皮，倒入热水，水量和鱼平齐或者少点', NULL);
INSERT INTO `recipe_step` VALUES (504007, 300606, 6, '大火烧开后，放入老豆腐，豆腐贴在锅边，加入食盐，转小火', NULL);
INSERT INTO `recipe_step` VALUES (504008, 300606, 7, '小火烧 10-15 分钟，然后大火收点汁，即可出锅', NULL);
INSERT INTO `recipe_step` VALUES (504009, 300607, 1, '称取5000g水，烧开加入375g木耳碎、120g鸡丝、60g沙汤调味粉、100g沙汤骨汤料、6g黑胡椒粉，再次烧开；淋入淀粉水（200g淀粉+250g水），继续大火烧开；', NULL);
INSERT INTO `recipe_step` VALUES (504010, 300607, 2, '碗中打入1个鸡蛋，舀入400g汤，出品淋入12g芝麻香油，2g香菜点缀。', NULL);
INSERT INTO `recipe_step` VALUES (504011, 300608, 1, '用盐揉搓鸡表皮，冷藏20分钟；每500g老母鸡，加入15g盐，28g调味料（鸡汤专用），50g鸡油，2500g水，烧开后炖制60分钟；', NULL);
INSERT INTO `recipe_step` VALUES (504012, 300608, 2, '水烧开，下入220g手擀面，煮熟；', NULL);
INSERT INTO `recipe_step` VALUES (504013, 300608, 3, '舀取300g老鸡汤，煮好的面条捞出沥水倒入碗中，将190g香辣鸡杂摆放上层，出品撒葱花。', NULL);
INSERT INTO `recipe_step` VALUES (504014, 300609, 1, '蒸柜上汽后，蒸制 12 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (504015, 300610, 1, '取 6000g 水，下入 240g 辣糊汤调料、60g 鸡丝、15g 海带丝 and 230g 干丝煮沸；', NULL);
INSERT INTO `recipe_step` VALUES (504016, 300610, 2, '淋入 540g 水淀粉（260g 淀粉+280g 水），沸腾后关火，倒入 150g 鸡蛋液；', NULL);
INSERT INTO `recipe_step` VALUES (504017, 300610, 3, '再次煮沸，加入 15g 芝麻香油出品。', NULL);
INSERT INTO `recipe_step` VALUES (504018, 300611, 1, '500g 鸡汁辣鱼料中加入 100g 热的老鸡汤，搅拌均匀；', NULL);
INSERT INTO `recipe_step` VALUES (504019, 300611, 2, '在酱料中放入 1500g 鱼块，翻拌均匀；', NULL);
INSERT INTO `recipe_step` VALUES (504020, 300611, 3, '将拌好的辣鱼块分装到餐具中，每份点缀 3 块红椒片；', NULL);
INSERT INTO `recipe_step` VALUES (504021, 300611, 4, '蒸柜上汽后，蒸制 15 分钟出品。', NULL);
INSERT INTO `recipe_step` VALUES (504022, 300612, 1, '取 220g 娃娃菜，在沸水汆烫 2 分 30 秒；', NULL);
INSERT INTO `recipe_step` VALUES (504023, 300612, 2, '将烫好的娃娃菜放入餐具中，加入 330g 老鸡汤出品。', NULL);
INSERT INTO `recipe_step` VALUES (504024, 300613, 1, '1000ml 乌龙茶（鸡笼香）调味茶饮料加入 3000ml 直饮冰水搅均；', NULL);
INSERT INTO `recipe_step` VALUES (504025, 300613, 2, '放入保冷桶内保鲜 4 小时;', NULL);
INSERT INTO `recipe_step` VALUES (504026, 300613, 3, '出品时在杯中装入 8 颗冰块，再接取 280ml 左右鸡笼香茶饮料。', NULL);
INSERT INTO `recipe_step` VALUES (504027, 300614, 1, '5 个鸡肉洋葱圈无需解冻直接放入170℃的油锅中炸制3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (504028, 300615, 1, '吐司切去四边，备用', NULL);
INSERT INTO `recipe_step` VALUES (504029, 300615, 2, '鸡蛋煮熟，捣碎', NULL);
INSERT INTO `recipe_step` VALUES (504030, 300615, 3, '混合鸡蛋、蛋黄酱、盐、黑胡椒', NULL);
INSERT INTO `recipe_step` VALUES (504031, 300615, 4, '锅中加入黄油，煎熟培根', NULL);
INSERT INTO `recipe_step` VALUES (504032, 300615, 5, '组装吐司，在两片吐司间加入制作好的鸡蛋酱及培根', NULL);
INSERT INTO `recipe_step` VALUES (504033, 300615, 6, '四边形吐司切成三角形装盘', NULL);
INSERT INTO `recipe_step` VALUES (504034, 300616, 1, '黄瓜洗净，切半圆形片，备用', NULL);
INSERT INTO `recipe_step` VALUES (504035, 300616, 2, '火腿切半圆形片，备用', NULL);
INSERT INTO `recipe_step` VALUES (504036, 300616, 3, '红尖椒（可选）切碎，备用', NULL);
INSERT INTO `recipe_step` VALUES (504037, 300616, 4, '将鸡蛋打入碗中，搅匀，即为 鸡蛋液', NULL);
INSERT INTO `recipe_step` VALUES (504038, 300616, 5, '热锅里倒 5ml 食用油', NULL);
INSERT INTO `recipe_step` VALUES (504039, 300616, 6, '油热后转小火，倒入打散的鸡蛋液，用筷子划散，翻炒至鸡蛋结为固体且颜色微微发黄，即为 半熟鸡蛋，盛出备用', NULL);
INSERT INTO `recipe_step` VALUES (504040, 300616, 7, '不用洗锅，往锅内倒入 5ml 食用油，倒入黄瓜片大火翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (504041, 300616, 8, '把 半熟鸡蛋 倒入锅中，调入 2g 盐、3ml 生抽，立刻倒入火腿片和辣椒碎（可选）翻炒均匀', NULL);
INSERT INTO `recipe_step` VALUES (504042, 300616, 9, '关火，盛盘', NULL);
INSERT INTO `recipe_step` VALUES (504043, 300617, 1, '两个鸡蛋放入碗中打散', NULL);
INSERT INTO `recipe_step` VALUES (504044, 300617, 2, '加入食用盐 3g 盐起到了重要的增加底味和凝固作用', NULL);
INSERT INTO `recipe_step` VALUES (504045, 300617, 3, '加入 2ml 白醋，去除鸡蛋的腥味（可选） 加入米醋也行，但米醋的颜色会使鸡蛋微微发黑 还可以加入料酒，同样具有去腥的作用，且没有醋的酸味', NULL);
INSERT INTO `recipe_step` VALUES (504046, 300617, 4, '向碗中加入鸡蛋体积 1-1.5 倍的 70 度纯净水，并且搅拌均匀 1 倍的水鸡蛋更弹，1.5 倍的水鸡蛋更嫩', NULL);
INSERT INTO `recipe_step` VALUES (504047, 300617, 5, '过滤蛋液，去掉蛋液中的浮沫（可选，不过滤蒸出来的蛋会有气泡导致不好看）', NULL);
INSERT INTO `recipe_step` VALUES (504048, 300617, 6, '向任意一口锅中加入 300-500ml 清水，水烧开后，放入盛有鸡蛋液的碗 蒸碗要盖上一个盖子，倒扣一个有凹槽的铁碟子，或者使用保鲜膜来减少水汽进入，这是为了避免其变成蜂窝状', NULL);
INSERT INTO `recipe_step` VALUES (504049, 300617, 7, '蒸煮步骤（二选一）', NULL);
INSERT INTO `recipe_step` VALUES (504050, 300617, 8, '开中火蒸10 分钟, 10 分钟之后关火再闷上5 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (504051, 300617, 9, '开大火蒸5 分钟，要保持锅中水一直处于沸腾状态，否则要延长时间。每隔2 分钟开盖一次释放水蒸气，开盖过晚蛋羹容易变成蜂窝状；开盖太早/频繁蒸的时间需要久一些。', NULL);
INSERT INTO `recipe_step` VALUES (504052, 300617, 10, '如何判断已经熟了？ 晃动碗，蛋羹不再处于液体状态，拥有类似果冻的 Q 弹状态即可出锅。', NULL);
INSERT INTO `recipe_step` VALUES (504053, 300617, 11, '出锅', NULL);
INSERT INTO `recipe_step` VALUES (504054, 300617, 12, '加入香油和生抽即可享用 也可用藤椒油代替香油，增加麻爽口感', NULL);
INSERT INTO `recipe_step` VALUES (504055, 300618, 1, '将鸡蛋打入碗中。', NULL);
INSERT INTO `recipe_step` VALUES (504056, 300618, 2, '使用筷子或搅拌器，顺着一个方向搅打蛋液，直至蛋清与蛋黄完全混合均匀，颜色一致。（此过程约需 1 - 2 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (504057, 300618, 3, '将糖或盐等调味料加入蛋液中，略微搅匀。', NULL);
INSERT INTO `recipe_step` VALUES (504058, 300618, 4, '准备刚烧开的、100 ℃ 的沸水。', NULL);
INSERT INTO `recipe_step` VALUES (504059, 300618, 5, '一边用筷子快速搅拌碗中的蛋液，一边将沸水以细流状冲入蛋液中。确保沸水与蛋液充分混合。', NULL);
INSERT INTO `recipe_step` VALUES (504060, 300618, 6, '持续搅拌片刻，直至蛋液被完全烫熟，形成均匀的淡黄色蛋花。', NULL);
INSERT INTO `recipe_step` VALUES (504061, 300619, 1, '30g 鸡血用开水烫制 2 分钟后，冷却备用;', NULL);
INSERT INTO `recipe_step` VALUES (504062, 300619, 2, '取鸡血、4g 蛋皮、4g 青菜烫制 10 秒后放入汤盅，', NULL);
INSERT INTO `recipe_step` VALUES (504063, 300620, 1, '西兰花焯水30秒；', NULL);
INSERT INTO `recipe_step` VALUES (504064, 300620, 2, '1000g五花肉、600g鹌鹑蛋、450g酱汁、1300g水、40g熟猪油，烧煮20分钟；', NULL);
INSERT INTO `recipe_step` VALUES (504065, 300620, 3, '转炒锅，炖煮好的鹌鹑蛋五花肉中下入12g淀粉和60g水，大火收汁浓稠后，加入40g大豆油翻炒均匀；', NULL);
INSERT INTO `recipe_step` VALUES (504066, 300620, 4, '出品时候点缀30g西兰花。', NULL);
INSERT INTO `recipe_step` VALUES (504067, 300621, 1, '【准备工作（提前 8 小时）】将干鹰嘴豆用清水浸泡过夜（至少 8 小时），浸泡后体积会膨胀至约两倍', NULL);
INSERT INTO `recipe_step` VALUES (504068, 300621, 2, '【煮鹰嘴豆】将浸泡好的鹰嘴豆沥干水分', NULL);
INSERT INTO `recipe_step` VALUES (504069, 300621, 3, '【煮鹰嘴豆】放入锅中，加入 500ml 水和 1 个红茶包（用于上色）', NULL);
INSERT INTO `recipe_step` VALUES (504070, 300621, 4, '【煮鹰嘴豆】大火煮沸后转中火，煮 25-30 分钟，直至鹰嘴豆用手指可以轻松压碎', NULL);
INSERT INTO `recipe_step` VALUES (504071, 300621, 5, '【煮鹰嘴豆】取出红茶包，保留煮豆的汤水，备用', NULL);
INSERT INTO `recipe_step` VALUES (504072, 300621, 6, '【炒制咖喱酱】在炒锅中倒入 30ml 食用油，中火加热', NULL);
INSERT INTO `recipe_step` VALUES (504073, 300621, 7, '【炒制咖喱酱】放入切碎的洋葱，翻炒至金棕色（约 6-8 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (504074, 300621, 8, '【炒制咖喱酱】加入磨碎的生姜和大蒜，翻炒 1 分钟', NULL);
INSERT INTO `recipe_step` VALUES (504075, 300621, 9, '【炒制咖喱酱】加入切碎的番茄，翻炒至番茄完全软烂出油（约 5 分钟）', NULL);
INSERT INTO `recipe_step` VALUES (504076, 300621, 10, '【炒制咖喱酱】加入姜黄粉 3g、红辣椒粉 5g、香菜粉 8g、孜然粉 5g、盐 6g', NULL);
INSERT INTO `recipe_step` VALUES (504077, 300621, 11, '【炒制咖喱酱】翻炒 2 分钟，使香料充分释放香味', NULL);
INSERT INTO `recipe_step` VALUES (504078, 300621, 12, '【炒制咖喱酱】将煮好的鹰嘴豆连同汤水一起倒入锅中', NULL);
INSERT INTO `recipe_step` VALUES (504079, 300621, 13, '【炒制咖喱酱】加入青辣椒，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (504080, 300621, 14, '【炒制咖喱酱】大火煮沸后转小火，炖 15-20 分钟，期间可用铲子背面压碎一些鹰嘴豆使汤汁变稠', NULL);
INSERT INTO `recipe_step` VALUES (504081, 300621, 15, '【炒制咖喱酱】加入印度综合香料粉 5g 和石榴粉 3g（或柠檬汁 15ml）', NULL);
INSERT INTO `recipe_step` VALUES (504082, 300621, 16, '【炒制咖喱酱】搅拌均匀后关火，备用', NULL);
INSERT INTO `recipe_step` VALUES (504083, 300621, 17, '【制作炸饼面团】在大碗中混合中筋面粉 250g、小苏打 2g、盐 3g', NULL);
INSERT INTO `recipe_step` VALUES (504084, 300621, 18, '【制作炸饼面团】加入酸奶 60ml 和食用油 15ml', NULL);
INSERT INTO `recipe_step` VALUES (504085, 300621, 19, '【制作炸饼面团】逐渐加入温水，边加边揉，揉成光滑柔软的面团（面团应比普通面团稍软）', NULL);
INSERT INTO `recipe_step` VALUES (504086, 300621, 20, '【制作炸饼面团】用湿布盖住面团，静置 30 分钟', NULL);
INSERT INTO `recipe_step` VALUES (504087, 300621, 21, '【炸制面饼】将面团分成 8 个等大的小剂子', NULL);
INSERT INTO `recipe_step` VALUES (504088, 300621, 22, '【炸制面饼】取一个剂子，手上沾少量油，擀成直径约 15cm、厚度约 3mm 的圆形面饼', NULL);
INSERT INTO `recipe_step` VALUES (504089, 300621, 23, '【炸制面饼】在深锅中倒入 500ml 食用油，中大火加热至油温约 180°C', NULL);
INSERT INTO `recipe_step` VALUES (504090, 300621, 24, '【炸制面饼】将面饼轻轻滑入热油中，用漏勺轻轻按压面饼使其膨胀鼓起', NULL);
INSERT INTO `recipe_step` VALUES (504091, 300621, 25, '【炸制面饼】炸 1-2 分钟，翻面炸至两面金黄', NULL);
INSERT INTO `recipe_step` VALUES (504092, 300621, 26, '【炸制面饼】捞出，用厨房纸吸去多余油分', NULL);
INSERT INTO `recipe_step` VALUES (504093, 300621, 27, '【上菜】将鹰嘴豆咖喱重新加热', NULL);
INSERT INTO `recipe_step` VALUES (504094, 300621, 28, '【上菜】炸饼趁热上桌，搭配鹰嘴豆咖喱食用', NULL);
INSERT INTO `recipe_step` VALUES (504095, 300621, 29, '【上菜】可搭配切片洋葱、青辣椒和柠檬角', NULL);
INSERT INTO `recipe_step` VALUES (504096, 300622, 1, '大蒜和生姜切碎，备用', NULL);
INSERT INTO `recipe_step` VALUES (504097, 300622, 2, '小米辣切成辣椒圈，备用', NULL);
INSERT INTO `recipe_step` VALUES (504098, 300622, 3, '五花肉切成肉糜（本来就是买的肉糜的跳过）', NULL);
INSERT INTO `recipe_step` VALUES (504099, 300622, 4, '肉糜中加入一半的食盐和味极鲜酱油，搅拌均匀，备用', NULL);
INSERT INTO `recipe_step` VALUES (504100, 300622, 5, '鸭蛋用菜刀竖着对半切开（注意安全），去除蛋黄（一定要去除，不然会腥），剩下的蛋白捣碎成大约 2 mm 2 mm 大小，不用太碎，备用', NULL);
INSERT INTO `recipe_step` VALUES (504101, 300622, 6, '打开豆腐包装，用水果刀将在盒子中的豆腐划成大约 2.5 cm 3 cm 大小，备用', NULL);
INSERT INTO `recipe_step` VALUES (504102, 300622, 7, '热锅，锅内放入 10ml - 15ml 食用油。等待 10 秒让油温升高', NULL);
INSERT INTO `recipe_step` VALUES (504103, 300622, 8, '调成小火，放入大蒜、生姜、辣椒圈、花椒、咸鸭蛋、蒜蓉辣酱翻炒 20 秒，炒出香味', NULL);
INSERT INTO `recipe_step` VALUES (504104, 300622, 9, '调成中火，放入肉糜，翻炒大约 1 分钟，肉炒变色', NULL);
INSERT INTO `recipe_step` VALUES (504105, 300622, 10, '调成小火，放入豆腐，将剩下的食盐、味极鲜酱油酱油均匀的洒在豆腐上', NULL);
INSERT INTO `recipe_step` VALUES (504106, 300622, 11, '从锅边倒入开水（不然豆腐容易破），没过豆腐即可', NULL);
INSERT INTO `recipe_step` VALUES (504107, 300622, 12, '开大火，水沸腾后立马转入中火，等待大约 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (504108, 300622, 13, '等到水只剩 1/5 并且豆腐表面已经入色，关火，盛盘', NULL);
INSERT INTO `recipe_step` VALUES (504109, 300623, 1, '将水倒入锅中并煮沸 （喜欢吃 q 弹面的同学，可在水里加入 30 克盐，用盐水煮出来的面会比较 q 弹）', NULL);
INSERT INTO `recipe_step` VALUES (504110, 300623, 2, '将快熟面放入锅中 3 分钟（也可参考当下品牌快熟面的烹饪时间）', NULL);
INSERT INTO `recipe_step` VALUES (504111, 300623, 3, '当面开始散了可以开始搅拌，让面受热均匀', NULL);
INSERT INTO `recipe_step` VALUES (504112, 300623, 4, '将水滤干把面倒入碗中', NULL);
INSERT INTO `recipe_step` VALUES (504113, 300623, 5, '按照上面的计量放入麻油，老抽，胡椒粉，生抽（可选）', NULL);
INSERT INTO `recipe_step` VALUES (504114, 300623, 6, '筷子搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (504115, 300623, 7, '一道简单即省钱的懒人麻油拌面就完成啦', NULL);
INSERT INTO `recipe_step` VALUES (504116, 300624, 1, '娃娃菜、生菜洗好，备用', NULL);
INSERT INTO `recipe_step` VALUES (504117, 300624, 2, '锅内倒入 500ml 水，开大火，将荞麦面和娃娃菜放进去，等待水沸腾', NULL);
INSERT INTO `recipe_step` VALUES (504118, 300624, 3, '水沸腾后，转小火，加入火锅底料、花生酱、牛奶、生抽、辣椒油，水开后煮 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (504119, 300624, 4, '加入生菜，再煮 2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (504120, 300624, 5, '加入醋、花椒油，关火，直接端着小锅开吃。', NULL);
INSERT INTO `recipe_step` VALUES (504121, 300625, 1, '烧开一锅水（水量能没过第 2-4 步中的食材即可）。', NULL);
INSERT INTO `recipe_step` VALUES (504122, 300625, 2, '在开水中放入青菜，焯 5 分钟后盛出备用。', NULL);
INSERT INTO `recipe_step` VALUES (504123, 300625, 3, '在开水中放入无骨肉，焯 4 分钟后盛出备用。', NULL);
INSERT INTO `recipe_step` VALUES (504124, 300625, 4, '在开水中放入北京麻辣方便面，煮 2 分钟后盛出备用。', NULL);
INSERT INTO `recipe_step` VALUES (504125, 300625, 5, '倒出开水，擦干锅具，放入 105 克食用油，大火加热 30 秒。', NULL);
INSERT INTO `recipe_step` VALUES (504126, 300625, 6, '放入麻辣香锅调料，翻炒 20 秒。', NULL);
INSERT INTO `recipe_step` VALUES (504127, 300625, 7, '放入干辣椒，翻炒 10 秒。', NULL);
INSERT INTO `recipe_step` VALUES (504128, 300625, 8, '放入焯过的青菜，改中火，翻炒 3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (504129, 300625, 9, '放入焯过的无骨肉，翻炒 3 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (504130, 300625, 10, '放入煮过的北京麻辣方便面，用筷子翻动 1 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (504131, 300625, 11, '关火，出锅。', NULL);
INSERT INTO `recipe_step` VALUES (504132, 300626, 1, '老母鸡炖制：每只老母鸡加入 2g 盐，冷藏腌制 20 分钟；每 500g 老母鸡，加入 16g 盐、60g 鸡油、2500g 水，炖煮出老母鸡汤香味，老母鸡剁块备用；', NULL);
INSERT INTO `recipe_step` VALUES (504133, 300626, 2, '1 份麻辣鸡块调味汁配制：味极鲜酱油 25g、麻辣油 15g、直饮水 15g、红椒丁 10g、京葱丁 5g;', NULL);
INSERT INTO `recipe_step` VALUES (504134, 300626, 3, '将老鸡块放入沸水中烫 2 分钟，捞起沥干水分，淋上70g 调味汁出品。', NULL);
INSERT INTO `recipe_step` VALUES (504135, 300627, 1, '鲜虾摘除头部，顺带扯出虾线（这步处理不好可在下一步开背时取出虾线），使用剪刀剪开或菜刀片开虾背，沥干水分备用', NULL);
INSERT INTO `recipe_step` VALUES (504136, 300627, 2, '调制酱汁：小碗放入上述量的全部生抽、米酒、白糖、盐搅匀备用', NULL);
INSERT INTO `recipe_step` VALUES (504137, 300627, 3, '中大火热锅，热锅内放入食用油，等待 10 秒让油温升高', NULL);
INSERT INTO `recipe_step` VALUES (504138, 300627, 4, '虾全部放入锅中，开始瓶磨黑胡椒，均匀地撒在虾上翻炒', NULL);
INSERT INTO `recipe_step` VALUES (504139, 300627, 5, '虾变色后加入黄油，黄油完全融化后倒入调制酱汁，继续翻炒', NULL);
INSERT INTO `recipe_step` VALUES (504140, 300627, 6, '大火翻炒 15 秒收汁即可装盘', NULL);
INSERT INTO `recipe_step` VALUES (504141, 300628, 1, '【腌制鸡肉（提前 1 小时）】在大碗中混合酸奶、生姜泥、大蒜泥、红辣椒粉、姜黄粉、盐、柠檬汁', NULL);
INSERT INTO `recipe_step` VALUES (504142, 300628, 2, '【腌制鸡肉（提前 1 小时）】放入鸡肉块，充分裹上腌料', NULL);
INSERT INTO `recipe_step` VALUES (504143, 300628, 3, '【腌制鸡肉（提前 1 小时）】盖保鲜膜，冷藏腌制至少 1 小时', NULL);
INSERT INTO `recipe_step` VALUES (504144, 300628, 4, '【烤制鸡肉】在平底锅中倒入 15ml 食用油，大火加热', NULL);
INSERT INTO `recipe_step` VALUES (504145, 300628, 5, '【烤制鸡肉】将腌好的鸡肉块放入锅中（不要倒入腌料汁）', NULL);
INSERT INTO `recipe_step` VALUES (504146, 300628, 6, '【烤制鸡肉】大火煎至两面焦黄（每面约 3 分钟），鸡肉不需要完全煮熟', NULL);
INSERT INTO `recipe_step` VALUES (504147, 300628, 7, '【烤制鸡肉】盛出备用', NULL);
INSERT INTO `recipe_step` VALUES (504148, 300628, 8, '【制作酱汁底料】在锅中放入番茄块、洋葱块、腰果、生姜、大蒜和水 100ml', NULL);
INSERT INTO `recipe_step` VALUES (504149, 300628, 9, '【制作酱汁底料】大火煮沸后转中火，煮 15 分钟，直至所有材料完全软烂', NULL);
INSERT INTO `recipe_step` VALUES (504150, 300628, 10, '【制作酱汁底料】稍微冷却后，倒入搅拌机中打成细腻顺滑的泥状', NULL);
INSERT INTO `recipe_step` VALUES (504151, 300628, 11, '【制作酱汁底料】用滤网过滤一遍，去除渣滓，得到顺滑的酱汁，备用', NULL);
INSERT INTO `recipe_step` VALUES (504152, 300628, 12, '【炖煮】在炒锅中放入黄油 50g，中火加热融化', NULL);
INSERT INTO `recipe_step` VALUES (504153, 300628, 13, '【炖煮】倒入过滤好的番茄酱汁', NULL);
INSERT INTO `recipe_step` VALUES (504154, 300628, 14, '【炖煮】加入红辣椒粉 5g、香菜粉 5g、孜然粉 3g、盐 5g', NULL);
INSERT INTO `recipe_step` VALUES (504155, 300628, 15, '【炖煮】翻炒 3-5 分钟，直至酱汁颜色变深且油花浮出', NULL);
INSERT INTO `recipe_step` VALUES (504156, 300628, 16, '【炖煮】放入烤好的鸡肉块，翻拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (504157, 300628, 17, '【炖煮】加入糖 10g（平衡番茄的酸味），搅拌', NULL);
INSERT INTO `recipe_step` VALUES (504158, 300628, 18, '【炖煮】倒入淡奶油 100ml，搅拌均匀', NULL);
INSERT INTO `recipe_step` VALUES (504159, 300628, 19, '【炖煮】小火炖 10-12 分钟，使鸡肉完全熟透且吸收酱汁', NULL);
INSERT INTO `recipe_step` VALUES (504160, 300628, 20, '【炖煮】加入印度综合香料粉 3g、小豆蔻粉 2g', NULL);
INSERT INTO `recipe_step` VALUES (504161, 300628, 21, '【炖煮】撒入干葫芦巴叶 3g（用手搓碎后撒入）', NULL);
INSERT INTO `recipe_step` VALUES (504162, 300628, 22, '【炖煮】搅拌均匀，关火', NULL);
INSERT INTO `recipe_step` VALUES (504163, 300628, 23, '【炖煮】盛盘，可额外淋上少量淡奶油作为装饰', NULL);
INSERT INTO `recipe_step` VALUES (504164, 300629, 1, '【备菜阶段】鸡腿洗净，剁成4cm大小的块', NULL);
INSERT INTO `recipe_step` VALUES (504165, 300629, 2, '【备菜阶段】生姜切片、干辣椒切成小圈', NULL);
INSERT INTO `recipe_step` VALUES (504166, 300629, 3, '【备菜阶段】香菇切片，青椒切成细长的马蹄状，若为干香菇，洗净灰尘后泡一晚上并留香菇水备用', NULL);
INSERT INTO `recipe_step` VALUES (504167, 300629, 4, '【备菜阶段】若有土豆，切为与鸡肉大小类似的滚刀块', NULL);
INSERT INTO `recipe_step` VALUES (504168, 300629, 5, '【炒制阶段】炒糖色：锅里倒入底油，冷油时放入白糖（有一定难度，新手可跳至鸡肉炒制并使用老抽替代）', NULL);
INSERT INTO `recipe_step` VALUES (504169, 300629, 6, '【炒制阶段】小火慢慢加热，待油温逐渐升高，白糖开始融化并变成较深的棕色（期间要不断搅拌，防止糊锅）', NULL);
INSERT INTO `recipe_step` VALUES (504170, 300629, 7, '【炒制阶段】迅速倒入鸡块，转大火，快速翻炒！烹入料酒，继续翻炒片刻', NULL);
INSERT INTO `recipe_step` VALUES (504171, 300629, 8, '【炒制阶段】将生姜片和干辣椒倒入', NULL);
INSERT INTO `recipe_step` VALUES (504172, 300629, 9, '【炒制阶段】放入酱油，炒匀', NULL);
INSERT INTO `recipe_step` VALUES (504173, 300629, 10, '【炒制阶段】倒入香菇水或清水，以能淹住鸡肉为准', NULL);
INSERT INTO `recipe_step` VALUES (504174, 300629, 11, '【炒制阶段】倒入香菇片，白胡椒粉，盐，土豆', NULL);
INSERT INTO `recipe_step` VALUES (504175, 300629, 12, '【炒制阶段】翻炒均匀后，盖上锅盖焖煮，转中小火15——20分钟，有条件可以转至砂锅', NULL);
INSERT INTO `recipe_step` VALUES (504176, 300629, 13, '【炒制阶段】待鸡肉软烂，汤汁浓稠后（汤汁不要收的太干），最后放入青椒', NULL);
INSERT INTO `recipe_step` VALUES (504177, 300629, 14, '【炒制阶段】放入味精，兜炒均匀后，关火！青椒基本断生即可，不要炒时间久了', NULL);
INSERT INTO `recipe_step` VALUES (504178, 300630, 1, '黄瓜片预处理：1200g黄瓜去皮切片后，放15g盐、10g白砂糖腌制，再清水洗净；', NULL);
INSERT INTO `recipe_step` VALUES (504179, 300630, 2, '锅洗净，下入120g大豆油，油热后下入1000g红肠片，煸炒至表面微微焦黄；', NULL);
INSERT INTO `recipe_step` VALUES (504180, 300630, 3, '下入60g拍蒜，煸炒出香味；', NULL);
INSERT INTO `recipe_step` VALUES (504181, 300630, 4, '下入洗净沥干水分的黄瓜片、8g鸡精，快速翻炒后出锅。', NULL);
INSERT INTO `recipe_step` VALUES (504182, 300631, 1, '将猪瘦肉切片，放入碗中，倒入食用油 10 克，生抽，搅拌均匀，腌制 10 分钟', NULL);
INSERT INTO `recipe_step` VALUES (504183, 300631, 2, '将黄瓜切去 5 厘米的头尾，剩余部分斜着切成 0.5 厘米的薄片', NULL);
INSERT INTO `recipe_step` VALUES (504184, 300631, 3, '将黄瓜倒入碗中，撒上盐 8 克，搅拌均匀，腌制 5 分钟', NULL);
INSERT INTO `recipe_step` VALUES (504185, 300631, 4, '将蒜瓣去皮，压扁，切成蒜末备用', NULL);
INSERT INTO `recipe_step` VALUES (504186, 300631, 5, '将小米辣去丁切分成均匀 0.5 厘米的段状', NULL);
INSERT INTO `recipe_step` VALUES (504187, 300631, 6, '热锅，倒油 40 克，等油温到冒烟，放入蒜蓉小米辣翻炒 5 次', NULL);
INSERT INTO `recipe_step` VALUES (504188, 300631, 7, '放入腌制好的猪瘦肉，翻炒至肉熟变色', NULL);
INSERT INTO `recipe_step` VALUES (504189, 300631, 8, '放入黄瓜，加入盐 2 克，大火翻炒均匀半分钟，出锅 如果无法保证大火，可能会有点生。可以考虑增加到 50 秒。', NULL);
INSERT INTO `recipe_step` VALUES (504190, 300632, 1, '黄瓜洗净，切成 0.5-1.2 mm 厚的薄片', NULL);
INSERT INTO `recipe_step` VALUES (504191, 300632, 2, '葱洗净切成末，蒜用刀拍几下去皮，对半切一下', NULL);
INSERT INTO `recipe_step` VALUES (504192, 300632, 3, '皮蛋剥去壳，然后每个切成 6-8 份。锅里倒入油，放入切好的皮蛋和大蒜', NULL);
INSERT INTO `recipe_step` VALUES (504193, 300632, 4, '小火炒至皮蛋和大蒜表面有些焦黄，加入水，转大火烧开', NULL);
INSERT INTO `recipe_step` VALUES (504194, 300632, 5, '放入黄瓜片。水再次沸腾以后立马关火，放入盐、鸡精调味即可出锅', NULL);
INSERT INTO `recipe_step` VALUES (504195, 300632, 6, '装入碗中，再撒上葱花即可', NULL);
INSERT INTO `recipe_step` VALUES (504196, 300633, 1, '蒸柜上汽后，蒸制 12 分钟，出品。', NULL);
INSERT INTO `recipe_step` VALUES (504197, 300634, 1, '将牛肉切条，长度最好控制在 8 厘米以下，厚度约 5-10 毫米，宽度约 1 厘米（要求不严格）', NULL);
INSERT INTO `recipe_step` VALUES (504198, 300634, 2, '利用腌料腌制牛肉，混合均匀后静置，用量与时间请参照商品说明，可以延长不能缩短。', NULL);
INSERT INTO `recipe_step` VALUES (504199, 300634, 3, '如果使用液态腌料，可以在腌制结束前三分钟撒一层黑胡椒粉，然后再加入淀粉，再次混合均匀后静置 20 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (504200, 300634, 4, '开火，热锅，加入花生油。', NULL);
INSERT INTO `recipe_step` VALUES (504201, 300634, 5, '当能看到锅里的油冒出一丝烟时，放入牛肉，翻炒。', NULL);
INSERT INTO `recipe_step` VALUES (504202, 300634, 6, '开中火偏大，翻炒 2 分钟至牛肉外表变色（即不出现明显血色，有血色部分说明翻炒不到位）（此处应小心油滴溅射）。', NULL);
INSERT INTO `recipe_step` VALUES (504203, 300634, 7, '放入洋葱和菜椒，翻炒 2 分钟。', NULL);
INSERT INTO `recipe_step` VALUES (504204, 300634, 8, '加入盐，再次撒一份黑胡椒粉，翻炒 30 秒，搅拌均匀。', NULL);
INSERT INTO `recipe_step` VALUES (504205, 300634, 9, '观察洋葱已经变软即可关火，出锅，盛盘。', NULL);
INSERT INTO `recipe_step` VALUES (504206, 300635, 1, '锅内放入 750ml 水，开火加热至沸腾', NULL);
INSERT INTO `recipe_step` VALUES (504207, 300635, 2, '放入腊肠，计时 13 分钟', NULL);
INSERT INTO `recipe_step` VALUES (504208, 300635, 3, '放入娃娃菜，计时 2 分钟', NULL);
INSERT INTO `recipe_step` VALUES (504209, 300635, 4, '关火，夹出腊肠及娃娃菜', NULL);
INSERT INTO `recipe_step` VALUES (504210, 300635, 5, '娃娃菜切段、腊肠切片，装盘', NULL);
INSERT INTO `recipe_step` VALUES (504211, 300636, 1, '在锅中倒入龟苓膏粉 25 克与冷水 120 毫升，充分搅拌至无颗粒感。', NULL);
INSERT INTO `recipe_step` VALUES (504212, 300636, 2, '在另一个容器中加入白砂糖 100 克，倒入沸水 500 毫升，搅拌至糖完全溶解。', NULL);
INSERT INTO `recipe_step` VALUES (504213, 300636, 3, '将糖水缓慢倒入龟苓膏粉液中，立即搅拌均匀，避免结块。', NULL);
INSERT INTO `recipe_step` VALUES (504214, 300636, 4, '将混合液体放入锅中，加热时保持中小火，并持续搅拌以防粘锅。', NULL);
INSERT INTO `recipe_step` VALUES (504215, 300636, 5, '加热至液体变粘稠并开始冒小泡，即可关火。', NULL);
INSERT INTO `recipe_step` VALUES (504216, 300636, 6, '快速将液体倒入模具中，自然冷却凝固。建议冷藏 1~2 小时后食用，口感更佳。', NULL);
