INSERT INTO `recipe_tag` VALUES (1114, '烧烤', 200, '2026-08-23 15:56:41', '2026-08-23 15:56:41');
INSERT INTO `recipe_tag` VALUES (1115, '砂锅菜', 150, '2026-08-23 15:56:41', '2026-08-23 15:56:41');
INSERT INTO `recipe_tip` VALUES (600001, 300001, 1, '喝的时候，现在酒吧常用的方法是提供一个吸管，在火还燃烧的时候插入，然后快速全部吸入。');
INSERT INTO `recipe_tip` VALUES (600002, 300001, 2, '由于吸管太细，其中氧气不足，所以火苗会灭掉，不必担心。这时候，会感到一股热辣顺着喉咙一直烈到胃，之后就是久久的咖啡奶油回甘。非常刺激又好喝。');
INSERT INTO `recipe_tip` VALUES (600003, 300002, 1, '参考资料：【哔哩哔哩】莫吉托(Mojito)世界上最著名的经典鸡尾酒之一。');
INSERT INTO `recipe_tip` VALUES (600004, 300003, 1, '营养成分(每100g) 热量：59 Kcal');
INSERT INTO `recipe_tip` VALUES (600005, 300003, 2, '营养成分(每100g) 蛋白质：3.0 g');
INSERT INTO `recipe_tip` VALUES (600006, 300003, 3, '营养成分(每100g) 脂肪：2.7 g');
INSERT INTO `recipe_tip` VALUES (600007, 300003, 4, '营养成分(每100g) 碳水化合物：5.7 g');
INSERT INTO `recipe_tip` VALUES (600008, 300003, 5, '营养成分(每100g) 钠：497 mg');
INSERT INTO `recipe_tip` VALUES (600009, 300006, 1, '将肉沫和胡萝卜末加入面糊后，应该尽量搅匀，保证味道扩散到饼内各处。');
INSERT INTO `recipe_tip` VALUES (600010, 300006, 2, '肉沫和胡萝卜末即馅料可以使用各类熟馅料替代。');
INSERT INTO `recipe_tip` VALUES (600011, 300007, 1, '操作时，需要注意观察沸腾的水位线，如发现低于 2/3 的食材应加热水或者加啤酒。');
INSERT INTO `recipe_tip` VALUES (600012, 300007, 2, '厨师长：用土灶烧“乡村啤酒鸭”，味道安逸得不摆了');
INSERT INTO `recipe_tip` VALUES (600013, 300008, 1, '白菜控水是关键，越干越好；湿菜叶挂不住麻酱，整道菜口味会被稀释。');
INSERT INTO `recipe_tip` VALUES (600014, 300008, 2, '调麻酱汁时必须先用醋\"解\"酱，再依次加入其他调料，切勿一次全部倒入。');
INSERT INTO `recipe_tip` VALUES (600015, 300008, 3, '陈醋优先选用镇江香醋，颜色与酸香均最为适宜；不建议使用米醋（太淡）或白醋（色浅且味薄）。');
INSERT INTO `recipe_tip` VALUES (600016, 300008, 4, '本配方为醋糖版，如希望口味更醇厚圆润，可将白糖的一半替换为蜂蜜。');
INSERT INTO `recipe_tip` VALUES (600017, 300009, 1, '营养成分(每100g) 热量：138 Kcal');
INSERT INTO `recipe_tip` VALUES (600018, 300009, 2, '营养成分(每100g) 蛋白质：6.2 g');
INSERT INTO `recipe_tip` VALUES (600019, 300009, 3, '营养成分(每100g) 脂肪：4.9 g');
INSERT INTO `recipe_tip` VALUES (600020, 300009, 4, '营养成分(每100g) 碳水化合物：17.1 g');
INSERT INTO `recipe_tip` VALUES (600021, 300009, 5, '营养成分(每100g) 钠：398 mg');
INSERT INTO `recipe_tip` VALUES (600022, 300013, 1, '如果第一次炒鸡蛋的时候放的油太多，炒猪肉的时候可以视情况不加油。');
INSERT INTO `recipe_tip` VALUES (600023, 300013, 2, '参考资料下厨房');
INSERT INTO `recipe_tip` VALUES (600024, 300015, 1, '营养成分(每100g) 热量：191 Kcal');
INSERT INTO `recipe_tip` VALUES (600025, 300015, 2, '营养成分(每100g) 蛋白质：11.5 g');
INSERT INTO `recipe_tip` VALUES (600026, 300015, 3, '营养成分(每100g) 脂肪：14.5 g');
INSERT INTO `recipe_tip` VALUES (600027, 300015, 4, '营养成分(每100g) 碳水化合物：4.0 g');
INSERT INTO `recipe_tip` VALUES (600028, 300015, 5, '营养成分(每100g) 钠：754 mg');
INSERT INTO `recipe_tip` VALUES (600029, 300017, 1, '口感调整：冰糖的用量可以调整，以达到个人喜好的甜度。');
INSERT INTO `recipe_tip` VALUES (600030, 300017, 2, '保存方法：冷藏保存，建议 1 周内喝完。');
INSERT INTO `recipe_tip` VALUES (600031, 300018, 1, '操作时，拿出冬瓜酿肉时注意碟子很烫，小心操作。');
INSERT INTO `recipe_tip` VALUES (600032, 300018, 2, '参考资料：b站视频');
INSERT INTO `recipe_tip` VALUES (600033, 300019, 1, '操作时，需要注意观察凉白开的颜色和粘度变化，如颜色过浅或者水不黏，则说明冰粉籽量不足，或者是揉搓力度和时间没有到位。');
INSERT INTO `recipe_tip` VALUES (600034, 300021, 1, '调味品的数量可以根据个人口味进行调整, 如果不喜欢芥末, 可以不加入。');
INSERT INTO `recipe_tip` VALUES (600035, 300021, 2, '等木耳冷却入味后口味更佳, 约 15 分钟。');
INSERT INTO `recipe_tip` VALUES (600036, 300022, 1, '芝麻酱可以用花生酱代替');
INSERT INTO `recipe_tip` VALUES (600037, 300022, 2, '芝麻酱一定要和油麦菜混合均匀才更好吃.');
INSERT INTO `recipe_tip` VALUES (600038, 300023, 1, '萝卜非必须，只是为了增加菜色');
INSERT INTO `recipe_tip` VALUES (600039, 300023, 2, '端盘后，可以根据个人口味，额外增加生抽、白砂糖、香醋、芝麻等佐料');
INSERT INTO `recipe_tip` VALUES (600040, 300023, 3, '莴笋条的大小看个人口感决定，但莴笋皮要尽量多削点，不然真的影响口感');
INSERT INTO `recipe_tip` VALUES (600041, 300023, 4, '冰镇效果更加');
INSERT INTO `recipe_tip` VALUES (600042, 300025, 1, '制作凉拌豆腐时，建议选用质地较硬的北豆腐或老豆腐，不易碎裂，口感更佳。');
INSERT INTO `recipe_tip` VALUES (600043, 300025, 2, '如果喜欢更清淡的口感，可以省略醋和辣椒油。');
INSERT INTO `recipe_tip` VALUES (600044, 300025, 3, '酱汁的比例可以根据个人口味进行调整。');
INSERT INTO `recipe_tip` VALUES (600045, 300026, 1, '金针菇焯水时间不宜过长，以免影响口感。');
INSERT INTO `recipe_tip` VALUES (600046, 300026, 2, '酱汁的比例可以根据个人口味喜好进行调整。');
INSERT INTO `recipe_tip` VALUES (600047, 300026, 3, '如果不喜欢吃辣，可以省略辣椒油。');
INSERT INTO `recipe_tip` VALUES (600048, 300027, 1, '这道菜是隔离期间用现有材料做的，有条件可以加入香菜、小葱等进行调味，喜欢吃辣的可以加入辣椒油');
INSERT INTO `recipe_tip` VALUES (600049, 300028, 1, '部分情况下黄瓜端头有苦味，请洗净切下后确认');
INSERT INTO `recipe_tip` VALUES (600050, 300028, 2, '做好之后直接开吃，亦可先准备好后放入冰箱冷藏（并非冷冻）后食用');
INSERT INTO `recipe_tip` VALUES (600051, 300028, 3, '若放入冰箱冷藏，则需使用保鲜膜包紧，并在 8 小时内食用完毕，否则黄瓜会因过度腌制失去清脆口感');
INSERT INTO `recipe_tip` VALUES (600052, 300028, 4, '推荐黄瓜去皮，口感更好');
INSERT INTO `recipe_tip` VALUES (600053, 300030, 1, '参考: 制作凉粉的详细步骤');
INSERT INTO `recipe_tip` VALUES (600054, 300032, 1, '烤鹰嘴豆粉(Sattu)是比哈尔邦的特色食材，营养价值极高，富含蛋白质和纤维。在中国可能较难购买，可以自制：将鹰嘴豆(Chana)干炒至深棕色后磨成粉。');
INSERT INTO `recipe_tip` VALUES (600055, 300032, 2, '传统的利提用牛粪饼火(Cow dung cake fire)烤制，赋予独特的烟熏风味。家用烤箱或明火可以替代。');
INSERT INTO `recipe_tip` VALUES (600056, 300032, 3, '芥末油是这道菜的灵魂，不建议替换。如果买不到芥末油，可以使用菜籽油作为次选。');
INSERT INTO `recipe_tip` VALUES (600057, 300032, 4, '利提巧卡是印度最古老的食物之一，据传已有数千年历史，是古代士兵的行军食粮。');
INSERT INTO `recipe_tip` VALUES (600058, 300035, 1, '营养成分(每100g) 热量：95 Kcal');
INSERT INTO `recipe_tip` VALUES (600059, 300035, 2, '营养成分(每100g) 蛋白质：6.4 g');
INSERT INTO `recipe_tip` VALUES (600060, 300035, 3, '营养成分(每100g) 脂肪：5.1 g');
INSERT INTO `recipe_tip` VALUES (600061, 300035, 4, '营养成分(每100g) 碳水化合物：5.9 g');
INSERT INTO `recipe_tip` VALUES (600062, 300035, 5, '营养成分(每100g) 钠：1770 mg');
INSERT INTO `recipe_tip` VALUES (600063, 300036, 1, '营养成分(每100g) 热量：100 Kcal');
INSERT INTO `recipe_tip` VALUES (600064, 300036, 2, '营养成分(每100g) 蛋白质：9.8 g');
INSERT INTO `recipe_tip` VALUES (600065, 300036, 3, '营养成分(每100g) 脂肪：4.9 g');
INSERT INTO `recipe_tip` VALUES (600066, 300036, 4, '营养成分(每100g) 碳水化合物：4.2 g');
INSERT INTO `recipe_tip` VALUES (600067, 300036, 5, '营养成分(每100g) 钠：1580 mg');
INSERT INTO `recipe_tip` VALUES (600068, 300041, 1, '传统意大利面非常长。20 世纪下半叶开始流行短的意大利粉，典型长度 25–30 cm。');
INSERT INTO `recipe_tip` VALUES (600069, 300041, 2, '“Spaghettoni”是较厚的意大利粉。“Spaghettini”较细的意大利面。“capellini”是更细版的意大利面。');
INSERT INTO `recipe_tip` VALUES (600070, 300046, 1, '营养成分(每100g) 热量：303 Kcal');
INSERT INTO `recipe_tip` VALUES (600071, 300046, 2, '营养成分(每100g) 蛋白质：11.4 g');
INSERT INTO `recipe_tip` VALUES (600072, 300046, 3, '营养成分(每100g) 脂肪：23.6 g');
INSERT INTO `recipe_tip` VALUES (600073, 300046, 4, '营养成分(每100g) 碳水化合物：11.7 g');
INSERT INTO `recipe_tip` VALUES (600074, 300046, 5, '营养成分(每100g) 钠：782 mg');
INSERT INTO `recipe_tip` VALUES (600075, 300047, 1, '卤水可另取一部分做牛肉面，作为白水面条的汤底，再加上自己喜欢的蔬菜，味道极佳。');
INSERT INTO `recipe_tip` VALUES (600076, 300050, 1, '这道菜是干炒风格(Dry)，不需要加水。如果觉得太干容易粘锅，可以加入极少量水（约 15-30ml），但不宜过多。');
INSERT INTO `recipe_tip` VALUES (600077, 300050, 2, '土豆块不要切太小，否则容易炒散。');
INSERT INTO `recipe_tip` VALUES (600078, 300050, 3, '花菜的边缘略微焦黄是正常的，反而会增添风味。');
INSERT INTO `recipe_tip` VALUES (600079, 300050, 4, 'Aloo Gobi 因 2001 年的英国喜剧电影\"Bend It Like Beckham\"（像贝克汉姆一样踢球）而在西方世界广为人知。');
INSERT INTO `recipe_tip` VALUES (600080, 300050, 5, '这道菜可以搭配印度烤饼(Naan)、印度薄饼(Roti)或米饭食用。');
INSERT INTO `recipe_tip` VALUES (600081, 300051, 1, 'CTC 红茶（Crush, Tear, Curl 工艺制成）是印度奶茶的最佳选择，因为其颗粒细碎，能在短时间内释放浓厚的茶味。中国的祁门红茶或滇红也可以替代。');
INSERT INTO `recipe_tip` VALUES (600082, 300051, 2, '牛奶和水的比例可以根据个人喜好调整。更浓的奶茶用牛奶多水少，更清爽的用水多牛奶少。');
INSERT INTO `recipe_tip` VALUES (600083, 300051, 3, '生姜是印度奶茶的灵魂，不建议省略。');
INSERT INTO `recipe_tip` VALUES (600084, 300051, 4, '印度人喜欢将奶茶煮得很甜，如果不习惯可以减少糖量。');
INSERT INTO `recipe_tip` VALUES (600085, 300051, 5, '在印度，Chai 不仅是饮品，更是一种社交文化。朋友聚会、商务谈判、甚至初次见面，都从一份 Chai 开始。据统计印度每天消耗超过 10 亿份茶。');
INSERT INTO `recipe_tip` VALUES (600086, 300051, 6, '印度街头奶茶摊(Chai Wala)通常使用陶土杯(Kulhad)盛茶，赋予茶汤一种独特的泥土芬芳。');
INSERT INTO `recipe_tip` VALUES (600087, 300052, 1, '面团的柔软度是关键，太硬的面团烤出的饼会干硬。面团应该是湿润且略微粘手的状态。');
INSERT INTO `recipe_tip` VALUES (600088, 300052, 2, '铸铁锅比不粘锅效果更好，能产生更高的温度和更好的焦斑。');
INSERT INTO `recipe_tip` VALUES (600089, 300052, 3, '烤好后必须立刻涂酥油或黄油，这是印度烤饼香气和口感的关键。');
INSERT INTO `recipe_tip` VALUES (600090, 300052, 4, '除了原味 Naan，常见的变体还有：蒜蓉烤饼(Garlic Naan)、芝士烤饼(Cheese Naan)、黄油烤饼(Butter Naan)。');
INSERT INTO `recipe_tip` VALUES (600091, 300052, 5, 'Naan 在印度有数百年的历史，最早的记载出现在 1300 年，被认为源自波斯文化。');
INSERT INTO `recipe_tip` VALUES (600092, 300053, 1, '巴斯马蒂香米是制作 Biryani 的必备原料，普通大米无法替代其独特的长粒香气。中国各大电商平台均有售。');
INSERT INTO `recipe_tip` VALUES (600093, 300053, 2, '密封焖制(Dum)是这道菜的精髓，蒸汽不能泄漏，否则米饭会干燥。');
INSERT INTO `recipe_tip` VALUES (600094, 300053, 3, '米饭只能煮到七成熟，因为焖制过程中会继续吸水变熟。煮过头会导致最终成品米饭糊烂。');
INSERT INTO `recipe_tip` VALUES (600095, 300053, 4, '印度焖饭(Biryani)的两大流派：海得拉巴(Hyderabadi)式用生肉铺底焖制，勒克瑙(Lucknowi)式先将肉煮熟再与米饭组装。本食谱采用的是最常见的混合做法。');
INSERT INTO `recipe_tip` VALUES (600096, 300053, 5, '此菜在印度是婚礼和节日的必备菜品，被誉为\"印度的国菜\"。');
INSERT INTO `recipe_tip` VALUES (600097, 300054, 1, '瓠瓜挤水是关键步骤，水分过多会导致丸子散开无法成型。');
INSERT INTO `recipe_tip` VALUES (600098, 300054, 2, '丸子不宜在酱汁中炖太久，否则会变软失去口感。');
INSERT INTO `recipe_tip` VALUES (600099, 300054, 3, '此菜在印度通常搭配印度烤饼(Naan)或蒸米饭(Chawal)食用。');
INSERT INTO `recipe_tip` VALUES (600100, 300054, 4, '\"Kofte\"一词源自波斯语/阿拉伯语，意为\"压碎、磨碎\"，广泛流传于南亚和中东地区。');
