INSERT INTO `recipe_tip` VALUES (600111, 300058, 1, '刚做好的反沙芋头很烫，小心烫嘴哦');
INSERT INTO `recipe_tip` VALUES (600112, 300058, 2, '再配上茶，啊~真惬意啊');
INSERT INTO `recipe_tip` VALUES (600113, 300059, 1, '口水鸡第二种做法待更');
INSERT INTO `recipe_tip` VALUES (600114, 300061, 1, '含糖可乐口感更好');
INSERT INTO `recipe_tip` VALUES (600115, 300061, 2, '如果喜欢干一点，多炒一会儿');
INSERT INTO `recipe_tip` VALUES (600116, 300061, 3, '如果嫌麻烦，可以在第一步直接放 3 个鸡蛋，取消挖洞打另一个鸡蛋的步骤');
INSERT INTO `recipe_tip` VALUES (600117, 300062, 1, '加入生姜爆香的同时能防止鸡翅粘锅。');
INSERT INTO `recipe_tip` VALUES (600118, 300062, 2, '最后收汁时勿开过大火，防止味道偏苦。');
INSERT INTO `recipe_tip` VALUES (600119, 300062, 3, '本菜品偏甜。');
INSERT INTO `recipe_tip` VALUES (600120, 300063, 1, '对于五花肉切条步骤，定义：五花肉带皮面向上摆在桌上，此时肉皮所在平面为长宽形成的平面，垂直此平面的为高。肉条最终效果是肥瘦相间的细长条。（注意：此处肉条一定要细，即长宽较小。细肉条更易于炖煮软糯）。');
INSERT INTO `recipe_tip` VALUES (600121, 300063, 2, '五花肉切条小技巧：');
INSERT INTO `recipe_tip` VALUES (600122, 300063, 3, '若五花肉是未冷冻的，可以放入冰箱冷冻室 30 分钟 再取出切条。');
INSERT INTO `recipe_tip` VALUES (600123, 300063, 4, '若是冷冻五花肉，可以在常温下放置 30 分钟 后再切条。');
INSERT INTO `recipe_tip` VALUES (600124, 300063, 5, '切条时可以较小的力度将刀刃与肉快速摩擦，如此更易于切割并保护五花肉肥瘦相间的结构。');
INSERT INTO `recipe_tip` VALUES (600125, 300065, 1, '想让肉更有层次可以在生粉中加鸡蛋，炸出来会更香脆');
INSERT INTO `recipe_tip` VALUES (600126, 300067, 1, '做法参考：十几年澳门厨房佬教学挂汁的咖喱蟹怎么做');
INSERT INTO `recipe_tip` VALUES (600127, 300068, 1, '咖喱块不用捣碎，直接整块投入即可。');
INSERT INTO `recipe_tip` VALUES (600128, 300068, 2, '操作时，需要注意搅拌食材，避免食材调味料不均匀。');
INSERT INTO `recipe_tip` VALUES (600129, 300069, 1, '炒好的咸肉和菜梗铺在饭上，煮饭时千万不要搅匀');
INSERT INTO `recipe_tip` VALUES (600130, 300069, 2, '尽量不要买“家乡鲜肉”，可以预期会很咸。如果不是淡咸肉可以混入新鲜五花肉丁，或减少咸肉的用量，或将瘦肉部分切下泡入 5% 糖水 20 分钟。');
INSERT INTO `recipe_tip` VALUES (600131, 300069, 3, '参考资料：咸肉菜饭 - 维基百科');
