INSERT INTO `recipe_tip` VALUES (600198, 300111, 5, '营养成分(每100g) 钠：470 mg');
INSERT INTO `recipe_tip` VALUES (600199, 300113, 1, '食用莲藕要挑选外皮呈黄褐色、肉肥厚而白的。如果发黑，有异味，则不宜食用。');
INSERT INTO `recipe_tip` VALUES (600200, 300113, 2, '请尽量不要使用铁器，会导致莲藕发黑');
INSERT INTO `recipe_tip` VALUES (600201, 300117, 1, '焯水时，需要注意观察沸腾的水位线，不要让水溢出避免发生危险。');
INSERT INTO `recipe_tip` VALUES (600202, 300117, 2, '焯完水的鸡肝建议用凉水冲洗，更推荐冰水，可以让口感更好。');
INSERT INTO `recipe_tip` VALUES (600203, 300118, 1, '操作时，全程需要开大火');
INSERT INTO `recipe_tip` VALUES (600204, 300120, 1, '这是普通锅熬制（只需 30-35 分钟即可出锅）,味道最佳。高压锅和电饭锅省事，不过效果下降，水量要适当减少，一般 100 克小米+1800 克水');
INSERT INTO `recipe_tip` VALUES (600205, 300120, 2, '小米只需用水去除浮灰，千万不可过分淘，会损失掉小米油的');
INSERT INTO `recipe_tip` VALUES (600206, 300120, 3, '千万记住小米需要在水开的时候下锅');
INSERT INTO `recipe_tip` VALUES (600207, 300120, 4, '不喜欢放碱，更喜欢原汁原味的小米香');
INSERT INTO `recipe_tip` VALUES (600208, 300122, 1, '裹粉一定要把红薯粉揉散，不要有干的颗粒裹在里面，否则会炸！！！');
INSERT INTO `recipe_tip` VALUES (600209, 300122, 2, '如果肉太多吃不完，可以只炸一遍然后放冰箱。后面再吃的时候拿出来复炸，口感基本没影响。');
INSERT INTO `recipe_tip` VALUES (600210, 300123, 1, '营养成分(每100g) 热量：131 Kcal');
INSERT INTO `recipe_tip` VALUES (600211, 300123, 2, '营养成分(每100g) 蛋白质：13.2 g');
INSERT INTO `recipe_tip` VALUES (600212, 300123, 3, '营养成分(每100g) 脂肪：7.1 g');
INSERT INTO `recipe_tip` VALUES (600213, 300123, 4, '营养成分(每100g) 碳水化合物：3.6 g');
INSERT INTO `recipe_tip` VALUES (600214, 300123, 5, '营养成分(每100g) 钠：407 mg');
INSERT INTO `recipe_tip` VALUES (600215, 300125, 1, '控干水分的时候可以选择漏勺按压');
INSERT INTO `recipe_tip` VALUES (600216, 300125, 2, '生粉抓揉的时候要均匀覆盖蛙肉');
INSERT INTO `recipe_tip` VALUES (600217, 300126, 1, '腌制可以加入小苏打使牛肉变嫩，牛肉苏打比例为 500g：3g。');
INSERT INTO `recipe_tip` VALUES (600218, 300126, 2, '腌制的时候姜片可用料酒代替，料酒的用量为 3 g/人');
INSERT INTO `recipe_tip` VALUES (600219, 300127, 1, '炸肉片时，表面微焦即可，注意控制火候。');
INSERT INTO `recipe_tip` VALUES (600220, 300127, 2, '起锅前也可以打个薄薄的水淀粉，口感更佳。');
INSERT INTO `recipe_tip` VALUES (600221, 300129, 1, '肘子七成熟要根据实际情况判断，有条件可询问家中长辈。');
INSERT INTO `recipe_tip` VALUES (600222, 300129, 2, '蒸锅下半放水，上半放肘子，蒸时及时加水防止蒸干。');
INSERT INTO `recipe_tip` VALUES (600223, 300130, 1, '柠檬可提升虾的口感，但偏酸，可以根据喜好添加，也可以不用');
INSERT INTO `recipe_tip` VALUES (600224, 300130, 2, '趁热吃');
INSERT INTO `recipe_tip` VALUES (600225, 300131, 1, '不舍得使用宽油油炸的话，可改用更少的油煎鸡块和土豆块。会增长用时，部分影响口感，但不会影响总体味道。');
INSERT INTO `recipe_tip` VALUES (600226, 300131, 2, '参考资料：北大餐饮中心官方资讯');
INSERT INTO `recipe_tip` VALUES (600227, 300135, 1, '微波炉加热前，如果想进一步避免蛋黄和蛋白溅射，可以在碗上盖个盖子避免弄脏微波炉');
INSERT INTO `recipe_tip` VALUES (600228, 300136, 1, '水温应在 40–50℃ ，不宜过热。');
INSERT INTO `recipe_tip` VALUES (600229, 300136, 2, '蛋液与水比例控制在 1:1 至 1:1.2 之间口感最佳。');
INSERT INTO `recipe_tip` VALUES (600230, 300136, 3, '覆盖保鲜膜并扎孔能防止表面爆开或出现蜂窝。');
INSERT INTO `recipe_tip` VALUES (600231, 300136, 4, '过筛可显著提升细腻度。');
INSERT INTO `recipe_tip` VALUES (600232, 300136, 5, '若表面鼓泡或出水，说明加热过头，下次缩短时间即可。');
INSERT INTO `recipe_tip` VALUES (600233, 300137, 1, '在夸赞自己之前的操作可以重复多遍做出更大的蛋糕');
INSERT INTO `recipe_tip` VALUES (600234, 300137, 2, '泡打粉用来让蛋糕更蓬松 大多不含铝 几块钱一包 可以买了在家备着');
INSERT INTO `recipe_tip` VALUES (600235, 300137, 3, '在 加入任何喜欢的口味食材！ 这一步骤中 若加入液体（如牛奶） 请务必确保下一步可以搅和成稠酸奶状 建议少量多次加入以防止水分过量而导致成品湿瘪');
INSERT INTO `recipe_tip` VALUES (600236, 300137, 4, '食材不要超过容器的3/4!!');
INSERT INTO `recipe_tip` VALUES (600237, 300138, 1, '鸡蛋 1 个约为 50±5g。若使用其他品种蛋品可按比例增减水量。');
INSERT INTO `recipe_tip` VALUES (600238, 300138, 2, '一定要确保将鸡蛋打散，否则可能会发生轻度鸡蛋爆炸。');
INSERT INTO `recipe_tip` VALUES (600239, 300138, 3, '鸡蛋和水不能超过碗容量的 2/3，否则可能发生溢出。');
INSERT INTO `recipe_tip` VALUES (600240, 300139, 1, '如果想让香气更为浓郁，在微波前可将葱姜与料酒均匀涂抹在鱼片的两侧，再进行微波加热。');
INSERT INTO `recipe_tip` VALUES (600241, 300140, 1, '葱是整根，不需要切碎');
INSERT INTO `recipe_tip` VALUES (600242, 300140, 2, '步骤二加盐的目的是锁住五花肉的油脂');
INSERT INTO `recipe_tip` VALUES (600243, 300140, 3, '制作过程，用部分五花肉做了水煮处理，跟未处理的一起做后续制作，发现未水煮的肉质更 Q 弹');
INSERT INTO `recipe_tip` VALUES (600244, 300142, 1, '烤制时可以将鸡肉淋上蜂蜜或其他烤肉酱提升口感');
INSERT INTO `recipe_tip` VALUES (600245, 300142, 2, '烤箱预热至 180 度，烤制时间根据鸡肉的大小和厚度而定，需确保鸡肉熟透');
INSERT INTO `recipe_tip` VALUES (600246, 300142, 3, '鸡肉必须全熟才能吃，吃未全熟的鸡肉可能会导致食物中毒和感染细菌，如沙门氏菌和福氏杆菌等。');
INSERT INTO `recipe_tip` VALUES (600247, 300143, 1, '意大利面分为很多不同的粗细，煮面条之前请注意意面盒子上标注的时间');
INSERT INTO `recipe_tip` VALUES (600248, 300143, 2, '意大利面酱并不是番茄酱，平常用的番茄酱准确是叫番茄沙司，而意大利面酱虽然和番茄沙司都是调味过的番茄酱，但加的调味料不同');
INSERT INTO `recipe_tip` VALUES (600249, 300144, 1, '肉类选择建议：');
INSERT INTO `recipe_tip` VALUES (600250, 300144, 2, '意式香肠：最能体现正宗风味（推荐寻找配料中含有小茴香籽/Fennel seeds 的香肠）。');
INSERT INTO `recipe_tip` VALUES (600251, 300144, 3, '午餐肉：带来咸香、怀旧的口感，并且表面能煎得微脆。');
INSERT INTO `recipe_tip` VALUES (600252, 300144, 4, '辣香肠 (Chorizo)：若喜欢烟熏、辛辣的口感，并且能将底油染成诱人的红色，这是最好的选择。');
INSERT INTO `recipe_tip` VALUES (600253, 300145, 1, '操作时，可以根据焦褐斑大小适当调整时间，如果需要');
INSERT INTO `recipe_tip` VALUES (600254, 300145, 2, '可以在蛋挞中加 10g 碎芝士，就是一道芝士蛋挞啦~');
INSERT INTO `recipe_tip` VALUES (600255, 300146, 1, '参考了以下教程，文中说明非常详细且有每一步骤的配图。同时，对于为什么做某一个操作、背后的原理也有阐释，以及出现某些问题的分析：');
INSERT INTO `recipe_tip` VALUES (600256, 300146, 2, '为了做好这个戚风蛋糕，用了一整箱鸡蛋，从此告别凹底和塌陷');
INSERT INTO `recipe_tip` VALUES (600257, 300146, 3, '对戚风蛋糕而言，蛋清打发是次要问题，关键是烤制时的温度和时间。');
INSERT INTO `recipe_tip` VALUES (600258, 300146, 4, '蛋清容器而言，可有水珠，蛋黄容器不能有。');
INSERT INTO `recipe_tip` VALUES (600259, 300146, 5, '原因：油会影响蛋白的打发，蛋清 85%是水，稍有水珠并不影响打发。');
INSERT INTO `recipe_tip` VALUES (600260, 300146, 6, '特别新鲜的鸡蛋蛋清会比较硬，应对硬蛋清 5 个鸡蛋配方的话加 15ml 水会帮助蛋清打发（1 个鸡蛋配方则是 3g 水）');
INSERT INTO `recipe_tip` VALUES (600261, 300146, 7, '蛋清打发途中加的糖，实际也是先融于蛋清中的水里，成为糖浆溶液包裹在气泡外，对打发的气泡起保护作用。');
INSERT INTO `recipe_tip` VALUES (600262, 300146, 8, '温度对糖融于水的速率以及溶解度影响较大，刚从冰箱拿出的蛋清不易打发。但温度较低的鸡蛋容易分离蛋清蛋黄，建议分离后恢复室温再进行打发。');
INSERT INTO `recipe_tip` VALUES (600263, 300146, 9, '一些参考图片');
INSERT INTO `recipe_tip` VALUES (600264, 300148, 1, '煮水饺不需要盖锅盖，加三次水就是为了不让饺子一直处于沸腾状态导致表皮破损变成面片。');
INSERT INTO `recipe_tip` VALUES (600265, 300148, 2, '黑醋 10ml');
INSERT INTO `recipe_tip` VALUES (600266, 300148, 3, '姜 一小块 50 克');
INSERT INTO `recipe_tip` VALUES (600267, 300148, 4, '香油 2 滴');
INSERT INTO `recipe_tip` VALUES (600268, 300148, 5, '大蒜/蒜泥 3 瓣/人');
INSERT INTO `recipe_tip` VALUES (600269, 300148, 6, '考虑搭配黑醋食用。建议用量：10-20ml。');
INSERT INTO `recipe_tip` VALUES (600270, 300148, 7, '考虑姜切丝，在小碗加入 20ml 的黑醋与姜丝搅拌当蘸料，味道更丰富。');
INSERT INTO `recipe_tip` VALUES (600271, 300148, 8, '考虑搭配黑醋时加入 1~3 滴香油，搅拌当蘸料。');
INSERT INTO `recipe_tip` VALUES (600272, 300148, 9, '考虑搭配黑醋时加入砸好的蒜泥，搅拌当蘸料。（口腔内会残留蒜味，若饭后需要与他人面对面谈话建议放弃或清洁口腔）');
INSERT INTO `recipe_tip` VALUES (600273, 300150, 1, '使用开水与冷水混合和面，有助于提升饼皮柔韧度。');
INSERT INTO `recipe_tip` VALUES (600274, 300150, 2, '面团醒发时间不宜少于 20 分钟，否则不易擀薄。');
INSERT INTO `recipe_tip` VALUES (600275, 300150, 3, '可根据个人口味增减配料，建议配料总重控制在 100 克以内。');
INSERT INTO `recipe_tip` VALUES (600276, 300150, 4, '剩余生饼皮可冷藏保存 24 小时，使用时回温擀平即可。');
INSERT INTO `recipe_tip` VALUES (600277, 300151, 1, '步骤五中，翻炒时间需要实际情况做调整，一般是炒到包菜七分熟后即可。七分熟是指包菜已经出水质感变软');
INSERT INTO `recipe_tip` VALUES (600278, 300151, 2, '步骤五中，加盐的作用是锁住包菜水分的同时，给包菜上一点味道');
INSERT INTO `recipe_tip` VALUES (600279, 300151, 3, '最后一个步骤中，翻炒时间根据实际情况和个人口感做灵活调整');
INSERT INTO `recipe_tip` VALUES (600280, 300153, 1, '如做完后胳膊酸痛为正常现象，需加强上肢锻炼');
INSERT INTO `recipe_tip` VALUES (600281, 300153, 2, '超市有青豆，胡萝卜，玉米粒的混合冷冻包装，可以使用这个省去切丁的烦恼，推荐 Pams Mixed Veges 很便宜，或者类似的都可以用（如下图）');
INSERT INTO `recipe_tip` VALUES (600282, 300154, 1, '营养成分(每100g) 热量：529 Kcal');
INSERT INTO `recipe_tip` VALUES (600283, 300154, 2, '营养成分(每100g) 蛋白质：14.7 g');
INSERT INTO `recipe_tip` VALUES (600284, 300154, 3, '营养成分(每100g) 脂肪：53.1 g');
INSERT INTO `recipe_tip` VALUES (600285, 300154, 4, '营养成分(每100g) 碳水化合物：0.0 g');
INSERT INTO `recipe_tip` VALUES (600286, 300154, 5, '营养成分(每100g) 钠：518 mg');
INSERT INTO `recipe_tip` VALUES (600287, 300155, 1, '一定要注意水的比例');
INSERT INTO `recipe_tip` VALUES (600288, 300155, 2, '烤箱品质层次不齐，第一次做注意观察火候对披萨的影响');
INSERT INTO `recipe_tip` VALUES (600289, 300155, 3, '一般不特别标注是低筋或高筋面粉，基本都是中筋面粉');
INSERT INTO `recipe_tip` VALUES (600290, 300155, 4, '容易出水的水果不能作为食材，比如西瓜、橘子等');
INSERT INTO `recipe_tip` VALUES (600291, 300156, 1, '土豆煎炸不可太熟透，否则在拔丝端盘时不容易定型，影响美观');
INSERT INTO `recipe_tip` VALUES (600292, 300156, 2, '对于使用剩余的食用油，可以考虑重新收集到油壶。');
INSERT INTO `recipe_tip` VALUES (600293, 300157, 1, '防氧化技巧：山药去皮后若不立即下锅，应浸泡在清水中，防止接触空气氧化变黑。');
INSERT INTO `recipe_tip` VALUES (600294, 300157, 2, '口感控制：若喜欢山药极度软糯，可与排骨同时下锅；若喜欢山药成块不散，可在排骨炖煮 20 分钟后再放入山药。');
INSERT INTO `recipe_tip` VALUES (600295, 300157, 3, '补水须知：炖煮过程中如发现水位低于食材，务必添加热水，避免加入冷水导致肉质纤维瞬间收缩变柴。');
INSERT INTO `recipe_tip` VALUES (600296, 300158, 1, '可以使用其他带有鲜味的食材代替虾皮，如瑶柱');
INSERT INTO `recipe_tip` VALUES (600297, 300159, 1, '下厨房蛋白打发具体教程');
INSERT INTO `recipe_tip` VALUES (600298, 300161, 1, '发面时间并不固定, 每 1 小时看一下确认就可以, 明显发酵变大即可, 建议发酵 2 - 2.5 倍大。');
INSERT INTO `recipe_tip` VALUES (600299, 300161, 2, '面团大小不会显著影响口感和烘烤效果，可根据喜好调整。');
INSERT INTO `recipe_tip` VALUES (600300, 300161, 3, '参考资料：下厨房 - 脆底蜂蜜小面包');
INSERT INTO `recipe_tip` VALUES (600301, 300162, 1, '操作时，需要注意观察沸腾的水位线，如发现低于 3/4 的食材应加热水至没过食材。');
INSERT INTO `recipe_tip` VALUES (600302, 300162, 2, '鸡爪去骨教程 ：bili_89324373958');
INSERT INTO `recipe_tip` VALUES (600303, 300163, 1, '步骤 1-6 可以在 2-5 的等待过程进行，在这个过程也可以用清水锅煮些蔬菜，或做个煎蛋。');
INSERT INTO `recipe_tip` VALUES (600304, 300163, 2, '2-5 到 2-6 之间，需要注意观察沸腾的水位线，如发现低于 2/3 的食材应加热水至没过食材。');
INSERT INTO `recipe_tip` VALUES (600305, 300163, 3, '世界美食教程的微博视频');
INSERT INTO `recipe_tip` VALUES (600306, 300164, 1, '如果用的是比较不错的牛肉，可以选择不焯水，能够更加保留牛肉的风味，因为加入了味淋所以不会很腥，无需担心牛肉不熟，加热 10 分钟肯定熟了');
INSERT INTO `recipe_tip` VALUES (600307, 300164, 2, '如果有条件，选择加入 15g清酒');
INSERT INTO `recipe_tip` VALUES (600308, 300164, 3, '河水洋洋实验室 【牛丼｜肥牛饭】吉野家牛肉饭的正宗做法');
INSERT INTO `recipe_tip` VALUES (600309, 300164, 4, '夏叔厨房 60秒搞定神仙配方，好吃又下饭的肥牛饭！');
INSERT INTO `recipe_tip` VALUES (600310, 300166, 1, '鸡蛋一定要打散，水一定要在沸腾冒泡状态倒入鸡蛋液中，否则汤可能会浑浊影响口感');
INSERT INTO `recipe_tip` VALUES (600311, 300166, 2, '此为豫东地区做法，其他地区有不放白糖放盐的，口味不同，根据个人口味调整');
INSERT INTO `recipe_tip` VALUES (600312, 300166, 3, '此汤乃去火神器！');
INSERT INTO `recipe_tip` VALUES (600313, 300170, 1, '松仁可以提前用小火干炒至微微金黄香脆，更加美味');
INSERT INTO `recipe_tip` VALUES (600314, 300170, 2, '使用罐头玉米时应先沥干水分，避免炒制过程中出水过多');
INSERT INTO `recipe_tip` VALUES (600315, 300170, 3, '炒制时火候不宜过大，以防糊锅或松仁焦糊');
INSERT INTO `recipe_tip` VALUES (600316, 300172, 1, '此菜属于粤菜，正宗做法多会添加马蹄。考虑到萝卜青菜各有所爱，也可根据个人口味替换成土豆、萝卜等其他食材');
INSERT INTO `recipe_tip` VALUES (600317, 300172, 2, '参考资料：[枝竹羊腩煲 Lamb Stew with Bean Curd Sheet [by 點Cook Guide]](https://www.youtube.com/watch?v=ThVDpVoToDQ)');
INSERT INTO `recipe_tip` VALUES (600318, 300174, 1, '参考资料：柠檬水教程');
INSERT INTO `recipe_tip` VALUES (600319, 300175, 1, '参考: 柱候牛腩+茅根马蹄竹蔗水教程');
INSERT INTO `recipe_tip` VALUES (600320, 300175, 2, '操作高压锅要注意安全哦！');
INSERT INTO `recipe_tip` VALUES (600321, 300177, 1, '青椒酿 — 青椒酿肉 / 虾滑酿青椒（fork 版本）');
INSERT INTO `recipe_tip` VALUES (600322, 300177, 2, '田螺酿 — 螺肉猪肉 1:1，配紫苏薄荷');
INSERT INTO `recipe_tip` VALUES (600323, 300179, 1, '制作过程中发现，脆皮五花肉真香 Orz~');
INSERT INTO `recipe_tip` VALUES (600324, 300179, 2, '不喜欢吃甜的可以去掉白砂糖，不影响主流程');
INSERT INTO `recipe_tip` VALUES (600325, 300179, 3, '倒数第二个步骤，可以根据个人喜好调整时间');
INSERT INTO `recipe_tip` VALUES (600326, 300179, 4, '炒干梅干菜的作用是为了后续吸油（盲猜）');
INSERT INTO `recipe_tip` VALUES (600327, 300181, 1, '也可以用面包糠代替炸糊，但口感差距很大。');
INSERT INTO `recipe_tip` VALUES (600328, 300181, 2, '炸糊也可以用来炸鸡腿、炸鱼等。');
INSERT INTO `recipe_tip` VALUES (600329, 300181, 3, '参考：椒盐排条的做法');
INSERT INTO `recipe_tip` VALUES (600330, 300185, 1, '不确定咸淡的情况， 可以先少放盐， 在出锅前尝味， 考虑调整加盐');
INSERT INTO `recipe_tip` VALUES (600331, 300185, 2, '可以用鸡汤、骨头汤等替代水， 更好吃');
INSERT INTO `recipe_tip` VALUES (600332, 300185, 3, '焖的时间不可过长');
INSERT INTO `recipe_tip` VALUES (600333, 300186, 1, '参考: 水煮牛肉的详细步骤');
INSERT INTO `recipe_tip` VALUES (600334, 300188, 1, '垫底的蔬菜根据自己口味选择（蘑菇、白菜、油麦菜等）。');
INSERT INTO `recipe_tip` VALUES (600335, 300188, 2, '刀口辣椒制作嫌麻烦也可以直接用干辣椒段和青花椒代替。');
INSERT INTO `recipe_tip` VALUES (600336, 300188, 3, '特别注意肉的腌制（搅拌的时候朝着一个方向、血水处理干净），保证肉滑嫩（鸡蛋清、淀粉搅拌均匀）。');
INSERT INTO `recipe_tip` VALUES (600337, 300188, 4, '水煮牛肉也可以按照这个做法。');
INSERT INTO `recipe_tip` VALUES (600338, 300188, 5, '美食作家王刚R');
INSERT INTO `recipe_tip` VALUES (600339, 300190, 1, '垫底的蔬菜组合及用量可自由发挥，但需要注意各种蔬菜的特点，比如改成土豆的时候，需要将土豆片/土豆块煮熟（可以用筷子戳一戳确认）。');
INSERT INTO `recipe_tip` VALUES (600340, 300190, 2, '红油豆瓣酱（辣度）以及盐的用量可根据个人口味调整。');
INSERT INTO `recipe_tip` VALUES (600341, 300190, 3, '注意切鱼片的时候可以垂直于鱼片长条的方向先剁成 5cm 的鱼块，然后翻转 90 度斜着撇成薄片。');
INSERT INTO `recipe_tip` VALUES (600342, 300190, 4, '腌制的时候注意不要太用力抓。');
INSERT INTO `recipe_tip` VALUES (600343, 300190, 5, 'How to Fillet a Fish 怎样给鱼剔骨');
INSERT INTO `recipe_tip` VALUES (600344, 300191, 1, '操作流程可根据自己喜好更改，多多尝试会有惊喜');
INSERT INTO `recipe_tip` VALUES (600345, 300191, 2, '如掌握不好加盐量，可采用少量多次添加的方法，以免过量');
INSERT INTO `recipe_tip` VALUES (600346, 300192, 1, '细的、圆的 （超市大部分都是这种，口感更加劲道）');
INSERT INTO `recipe_tip` VALUES (600347, 300192, 2, '宽的、扁的 （口感比较软）');
INSERT INTO `recipe_tip` VALUES (600348, 300193, 1, '五香粉、草寇作为\"调料\"加入，可以增加香味，使油泼辣子更香');
INSERT INTO `recipe_tip` VALUES (600349, 300195, 1, '做法参考：B 站老饭骨视频从小吃到大的油焖大虾居然是假的？泰斗级大师还原真·味道');
INSERT INTO `recipe_tip` VALUES (600350, 300197, 1, '亲测老恒和酿造香醋零添加口味最好，醋香是本菜灵魂所在。');
INSERT INTO `recipe_tip` VALUES (600351, 300198, 1, '营养成分(每100g) 热量：121 Kcal');
INSERT INTO `recipe_tip` VALUES (600352, 300198, 2, '营养成分(每100g) 蛋白质：4.3 g');
INSERT INTO `recipe_tip` VALUES (600353, 300198, 3, '营养成分(每100g) 脂肪：5.0 g');
INSERT INTO `recipe_tip` VALUES (600354, 300198, 4, '营养成分(每100g) 碳水化合物：14.5 g');
INSERT INTO `recipe_tip` VALUES (600355, 300198, 5, '营养成分(每100g) 钠：393 mg');
INSERT INTO `recipe_tip` VALUES (600356, 300200, 1, '猪肉可选猪肩肉片或是切好的肉丝看个人喜好');
INSERT INTO `recipe_tip` VALUES (600357, 300200, 2, '爱料理');
INSERT INTO `recipe_tip` VALUES (600358, 300205, 1, '营养成分(每100g) 热量：44 Kcal');
INSERT INTO `recipe_tip` VALUES (600359, 300205, 2, '营养成分(每100g) 蛋白质：1.5 g');
INSERT INTO `recipe_tip` VALUES (600360, 300205, 3, '营养成分(每100g) 脂肪：2.0 g');
INSERT INTO `recipe_tip` VALUES (600361, 300205, 4, '营养成分(每100g) 碳水化合物：5.0 g');
INSERT INTO `recipe_tip` VALUES (600362, 300205, 5, '营养成分(每100g) 钠：677 mg');
INSERT INTO `recipe_tip` VALUES (600363, 300207, 1, '五花肉切片时建议放入冰箱冷冻 30 分钟后再切，更易切块。');
INSERT INTO `recipe_tip` VALUES (600364, 300207, 2, '炭火烤制风味优于燃气，有条件建议使用木炭。');
INSERT INTO `recipe_tip` VALUES (600365, 300207, 3, '酱料可根据个人口味调整芝麻酱与甜面酱的比例，也可以换成芝麻盐。');
INSERT INTO `recipe_tip` VALUES (600366, 300211, 1, '提前将花菜焯水可以缩短炒制时间，并使花菜更容易熟透。');
INSERT INTO `recipe_tip` VALUES (600367, 300211, 2, '炒制时间可以根据个人喜欢的花菜软硬程度调整。喜欢脆一些可以缩短时间。');
INSERT INTO `recipe_tip` VALUES (600368, 300216, 1, '南瓜的品种不同，甜度和口感会有差异。老南瓜通常更甜更面。');
INSERT INTO `recipe_tip` VALUES (600369, 300216, 2, '南瓜皮含有营养，如果喜欢也可以不去皮蒸，但需要彻底洗净。');
INSERT INTO `recipe_tip` VALUES (600370, 300216, 3, '蒸的时间取决于南瓜块的大小和厚度，以及南瓜的品种。用筷子测试是判断是否蒸熟的好方法。');
INSERT INTO `recipe_tip` VALUES (600371, 300218, 1, '技术总结：');
INSERT INTO `recipe_tip` VALUES (600372, 300218, 2, '这道菜属于有手就行，关键点在于火候，鱼的大小跟火候都会相关，太久会导致鱼肉太老极度影响口感，太短会导致部分鱼肉没熟。所以大火蒸鱼一般是 10 分钟内较佳。');
INSERT INTO `recipe_tip` VALUES (600373, 300218, 3, '切记蒸鱼需要用筷子隔开装鱼的盘子，这样做的好处有两点：');
INSERT INTO `recipe_tip` VALUES (600374, 300218, 4, '1、鱼在蒸的过程中会将水滴到盘子，如果鱼直接接触会导致鱼食用时会腥。');
INSERT INTO `recipe_tip` VALUES (600375, 300218, 5, '2、能够将鱼均匀受热。');
INSERT INTO `recipe_tip` VALUES (600376, 300218, 6, '这道菜难度系数简单，而且味道非常棒哦');
INSERT INTO `recipe_tip` VALUES (600377, 300219, 1, '注意事项：');
INSERT INTO `recipe_tip` VALUES (600378, 300219, 2, '1. 鳜鱼背部鱼鳍容易伤人，处理时候需要注意，最好用剪刀剪掉');
INSERT INTO `recipe_tip` VALUES (600379, 300219, 3, '2. 蒸制时间需要根据鱼的大小调整，蒸鱼的关键在于水多汽大火足');
INSERT INTO `recipe_tip` VALUES (600380, 300220, 1, '若使用机械式温度计（无需供电）则温度计探头需没入水中至少 6cm，若使用电子温度计则无特殊要求');
INSERT INTO `recipe_tip` VALUES (600381, 300220, 2, '锅可以采用稍厚的锅，方便控制温度');
INSERT INTO `recipe_tip` VALUES (600382, 300220, 3, '虽然 70 摄氏度 25 分钟已经完全可以杀死沙门氏菌，但还是要尽量少吃，或购买正规可生食鸡蛋制作');
INSERT INTO `recipe_tip` VALUES (600383, 300224, 1, '如果没有黄油，使用普通食用油也可以，但黄油会增加独特的奶香味。');
INSERT INTO `recipe_tip` VALUES (600384, 300224, 2, '吃的时候将半熟的蛋黄戳破，与牛肉和米饭拌匀食用，口感最佳。');
INSERT INTO `recipe_tip` VALUES (600385, 300225, 1, '沙拉酱的程度可以根据个人口味酌情删减。');
INSERT INTO `recipe_tip` VALUES (600386, 300225, 2, '可以尝试混合沙拉酱。');
INSERT INTO `recipe_tip` VALUES (600387, 300225, 3, '参考资料：小红书 - 干饭选手又困了');
INSERT INTO `recipe_tip` VALUES (600388, 300226, 1, '选择凉粉时最好选用豌豆淀粉制作成的凉粉，条件不允许的话红薯淀粉或其他也可');
INSERT INTO `recipe_tip` VALUES (600389, 300227, 1, '辅料的选择可以根据个人选择酌情添加，如加入瘦肉等');
INSERT INTO `recipe_tip` VALUES (600390, 300227, 2, '在煮年糕的时候注意搅拌，以免粘锅');
INSERT INTO `recipe_tip` VALUES (600391, 300229, 1, '在北京，可以考虑在盛盘后加入芝麻酱。如果芝麻酱太浓稠，可以 1:1 兑水稀释。');
INSERT INTO `recipe_tip` VALUES (600392, 300229, 2, '必须使用冷水冲面条！冷水能瞬间剥离面条表面的糊化淀粉，并强制中断内部的余温加热，这是保证面条下锅炒不坨、不粘锅、保持 Q 弹的核心原理。');
INSERT INTO `recipe_tip` VALUES (600393, 300229, 3, '处理面条的另一种方案，同样可以让面条劲道弹牙。拉长了面条整体处理时间，可以同步准备其他辅料：');
INSERT INTO `recipe_tip` VALUES (600394, 300229, 4, '洗面：将方便面面饼放入凉水中浸泡 2 分钟，使其完全吸收水分变湿润，捞出沥干（不用泡软）。');
INSERT INTO `recipe_tip` VALUES (600395, 300229, 5, '上蒸：将湿面饼放入蒸锅，水开后大火蒸 8 分钟，取出抖散备用（蒸能锁住水分，保证面条弹牙）。');
INSERT INTO `recipe_tip` VALUES (600396, 300231, 1, '最后可根据个人口味撒些黑胡椒或者盐来调味。');
INSERT INTO `recipe_tip` VALUES (600397, 300231, 2, '甜琛廚房');
INSERT INTO `recipe_tip` VALUES (600398, 300232, 1, '因为酱油的缘故，所以本菜不必加盐。出锅之前可以尝一下，如果不咸可以加微量的盐，下次炒时酱油量要增加');
INSERT INTO `recipe_tip` VALUES (600399, 300232, 2, '如果加了虾皮，可以将酱油量酌情减少。');
INSERT INTO `recipe_tip` VALUES (600400, 300232, 3, '炒本菜时，一直大火即可。');
INSERT INTO `recipe_tip` VALUES (600401, 300232, 4, '切忌！一定不可加水，会变成水煮茄子，口感差，所以油可多放，不可少放。');
INSERT INTO `recipe_tip` VALUES (600402, 300232, 5, '如果家用灶达到 7 成油温后温度不再继续明显上升，可直接进行下一步，不必强求 9 成油温。');
INSERT INTO `recipe_tip` VALUES (600403, 300232, 6, '糖和醋在最后阶段加，翻炒 20 秒就出锅，避免过早加醋，否则酸味挥发。');
INSERT INTO `recipe_tip` VALUES (600404, 300234, 1, '炒的过程中要注意控制火候，以防炒糊');
INSERT INTO `recipe_tip` VALUES (600405, 300234, 2, '火大补救措施将火调小，可沿锅边加油润锅或洒水，注意不要全倒在一个地方，最好分散开');
INSERT INTO `recipe_tip` VALUES (600406, 300234, 3, '调味料可根据个人喜好放入其他香料（比如南德调味料）');
INSERT INTO `recipe_tip` VALUES (600407, 300234, 4, '如果喜欢吃脆的，可以将火开到最小，多翻炒一会，关火后趁锅热再放置一会再倒出，更香脆');
INSERT INTO `recipe_tip` VALUES (600408, 300234, 5, '辅料也可根据个人口味方位蒜末，蒜苗等，可以单独爆香在混合');
INSERT INTO `recipe_tip` VALUES (600409, 300235, 1, '最后一步的调味可按自己喜好添加。');
INSERT INTO `recipe_tip` VALUES (600410, 300235, 2, '不得一次性倒入所有热油，必须分次倒入并搅拌。');
INSERT INTO `recipe_tip` VALUES (600411, 300235, 3, '原料可按比例缩减。');
INSERT INTO `recipe_tip` VALUES (600412, 300236, 1, '营养成分(每100g) 热量：226 Kcal');
INSERT INTO `recipe_tip` VALUES (600413, 300236, 2, '营养成分(每100g) 蛋白质：14.4 g');
INSERT INTO `recipe_tip` VALUES (600414, 300236, 3, '营养成分(每100g) 脂肪：11.4 g');
INSERT INTO `recipe_tip` VALUES (600415, 300236, 4, '营养成分(每100g) 碳水化合物：16.5 g');
INSERT INTO `recipe_tip` VALUES (600416, 300236, 5, '营养成分(每100g) 钠：922 mg');
INSERT INTO `recipe_tip` VALUES (600417, 300237, 1, '番茄酱、蛋黄酱、蜂蜜芥末酱、蒜香酱油……炸薯条的晋级之路在于对酱料及酱料组合的探究。');
INSERT INTO `recipe_tip` VALUES (600418, 300238, 1, '肉推荐瘦肉丁，口感更好，推荐现买现用。');
INSERT INTO `recipe_tip` VALUES (600419, 300238, 2, '面条推荐使用普通面条。');
INSERT INTO `recipe_tip` VALUES (600420, 300238, 3, '面条口感关键在于劲道。勿选龙须等细面。');
INSERT INTO `recipe_tip` VALUES (600421, 300238, 4, '如有条件（另一个锅）且熟练后，第 2、3 步和 1、4、5、6 步可分时并行执行。');
INSERT INTO `recipe_tip` VALUES (600422, 300238, 5, '甜咸口个人有爱好，两种酱的配比需要自己迭代优化。');
INSERT INTO `recipe_tip` VALUES (600423, 300239, 1, '玉米淀粉容易沉底，倒入锅前必须再次搅匀。');
INSERT INTO `recipe_tip` VALUES (600424, 300239, 2, '一次放入过多奶条会使油温快速下降，导致外壳吸油且容易破裂。');
INSERT INTO `recipe_tip` VALUES (600425, 300239, 3, '刚炸好的奶馅温度较高，食用前应先从中间掰开散热，避免烫伤。');
INSERT INTO `recipe_tip` VALUES (600426, 300239, 4, '参考资料：王刚的教学视频');
INSERT INTO `recipe_tip` VALUES (600427, 300241, 1, '营养成分(每100g) 热量：297 Kcal');
INSERT INTO `recipe_tip` VALUES (600428, 300241, 2, '营养成分(每100g) 蛋白质：16.1 g');
INSERT INTO `recipe_tip` VALUES (600429, 300241, 3, '营养成分(每100g) 脂肪：18.3 g');
INSERT INTO `recipe_tip` VALUES (600430, 300241, 4, '营养成分(每100g) 碳水化合物：17.3 g');
INSERT INTO `recipe_tip` VALUES (600431, 300241, 5, '营养成分(每100g) 钠：887 mg');
INSERT INTO `recipe_tip` VALUES (600432, 300242, 1, '营养成分(每100g) 热量：230 Kcal');
INSERT INTO `recipe_tip` VALUES (600433, 300242, 2, '营养成分(每100g) 蛋白质：15.2 g');
INSERT INTO `recipe_tip` VALUES (600434, 300242, 3, '营养成分(每100g) 脂肪：12.4 g');
INSERT INTO `recipe_tip` VALUES (600435, 300242, 4, '营养成分(每100g) 碳水化合物：14.4 g');
INSERT INTO `recipe_tip` VALUES (600436, 300242, 5, '营养成分(每100g) 钠：676 mg');
INSERT INTO `recipe_tip` VALUES (600437, 300246, 1, '烤箱出来成品抖动是正常的，放凉后口感还不是最好的，一定要冷藏才好吃！');
INSERT INTO `recipe_tip` VALUES (600438, 300246, 2, '参考资料：下厨房 - 巴斯克芝士蛋糕『最简单的蛋糕』零失败🔥芝士控');
INSERT INTO `recipe_tip` VALUES (600439, 300250, 1, '技术总结：上述');
INSERT INTO `recipe_tip` VALUES (600440, 300250, 2, '这道菜的食盐，胡椒粉，孜然粉，食用油，生抽，白糖等的使用量，根据个人口味和食材比例做决定，并不需要严格按照上述分量来做。');
INSERT INTO `recipe_tip` VALUES (600441, 300251, 1, '可以在腌制鸡翅时加入蜂蜜、酱油、姜蒜粉、五香粉等作为调味料，提升口感和香气');
INSERT INTO `recipe_tip` VALUES (600442, 300251, 2, '烤鸡翅时，建议将烤盘底部垫上一层锡纸，便于清洁烤盘');
INSERT INTO `recipe_tip` VALUES (600443, 300253, 1, '辣椒油看个人口味添加');
INSERT INTO `recipe_tip` VALUES (600444, 300254, 1, '花椒和白芷是这道菜的关键调料，不可缺少。');
INSERT INTO `recipe_tip` VALUES (600445, 300254, 2, '炖煮时间不宜过长，羊排过于软烂则在煎制时容易碎裂。');
INSERT INTO `recipe_tip` VALUES (600446, 300254, 3, '煎制时利用羊排自身煎出的油脂来炒香调料，风味更佳。');
INSERT INTO `recipe_tip` VALUES (600447, 300254, 4, '焯水、炖煮、煎制过程中会产生较多羊油，处理时请注意不要直接倒入下水道，以防堵塞。');
INSERT INTO `recipe_tip` VALUES (600448, 300255, 1, '操作时，需时刻观察锅内情况，切记不可分神玩手机。');
INSERT INTO `recipe_tip` VALUES (600449, 300256, 1, '如果使用白砂糖、淀粉组合代替一定让白砂糖和淀粉完全溶解再下锅，否则容易糊锅');
INSERT INTO `recipe_tip` VALUES (600450, 300256, 2, '焖煮时每隔 3-5 分钟翻搅一下，避免局部过热');
INSERT INTO `recipe_tip` VALUES (600451, 300256, 3, '如果酱汁冒大泡、颜色变深褐，或边缘出现细密焦糖结晶，立即关火');
INSERT INTO `recipe_tip` VALUES (600452, 300256, 4, '参考资料：【照烧鸡腿饭的做法步骤图，照烧鸡腿饭怎么做好吃】小晓姐姐_下厨房');
INSERT INTO `recipe_tip` VALUES (600453, 300257, 1, '本指南中的鸡蛋包括但不仅限于：生鸡蛋，熟鸡蛋，卤蛋等');
INSERT INTO `recipe_tip` VALUES (600454, 300257, 2, '原材料泡面可在楼下便利店购买');
INSERT INTO `recipe_tip` VALUES (600455, 300257, 3, '可根据个人需要加入佐料，和其他食材包括但不仅限于：火腿肠，生菜，小肉丝，辣条，鱼干，虾仁，鸡腿');
INSERT INTO `recipe_tip` VALUES (600456, 300259, 1, '如果口味偏咸口，可以在搅拌鸡蛋液时加入盐，胡椒等调料。');
INSERT INTO `recipe_tip` VALUES (600457, 300259, 2, '煎饼时使用小火，避免燕麦部分煎糊。');
INSERT INTO `recipe_tip` VALUES (600458, 300259, 3, '碳水化合物：39g');
INSERT INTO `recipe_tip` VALUES (600459, 300259, 4, '蛋白质：30g');
INSERT INTO `recipe_tip` VALUES (600460, 300259, 5, '脂肪：19g');
INSERT INTO `recipe_tip` VALUES (600461, 300259, 6, '总热量：450kcal');
INSERT INTO `recipe_tip` VALUES (600462, 300260, 1, '营养成分(每100g) 热量：126 Kcal');
INSERT INTO `recipe_tip` VALUES (600463, 300260, 2, '营养成分(每100g) 蛋白质：6.8 g');
INSERT INTO `recipe_tip` VALUES (600464, 300260, 3, '营养成分(每100g) 脂肪：8.1 g');
INSERT INTO `recipe_tip` VALUES (600465, 300260, 4, '营养成分(每100g) 碳水化合物：6.5 g');
INSERT INTO `recipe_tip` VALUES (600466, 300260, 5, '营养成分(每100g) 钠：844 mg');
INSERT INTO `recipe_tip` VALUES (600467, 300261, 1, '由于不同微波炉火力不同，故微波炉火力无法精确表明');
INSERT INTO `recipe_tip` VALUES (600468, 300261, 2, '不建议混合物超过容器容量 50%，否则加热过程中内容物极有可能溢出');
INSERT INTO `recipe_tip` VALUES (600469, 300261, 3, '不建议使用玻璃杯进行烹饪，理由同上');
INSERT INTO `recipe_tip` VALUES (600470, 300262, 1, '对于电磁炉：');
INSERT INTO `recipe_tip` VALUES (600471, 300262, 2, '高火：功率 1.8Kw - 2.2kw。');
INSERT INTO `recipe_tip` VALUES (600472, 300262, 3, '中火：功率 800w - 1.4kw。');
INSERT INTO `recipe_tip` VALUES (600473, 300262, 4, '小火：功率 200w - 600w。');
INSERT INTO `recipe_tip` VALUES (600474, 300262, 5, '对于燃气灶：');
INSERT INTO `recipe_tip` VALUES (600475, 300262, 6, '高火：旋转气阀至最大出气速度的 70%-90%。');
INSERT INTO `recipe_tip` VALUES (600476, 300262, 7, '中火：旋转气阀至最大出气速度的 40%-60%。');
INSERT INTO `recipe_tip` VALUES (600477, 300262, 8, '小火：旋转气阀至最大出气速度的 10%-30%。');
INSERT INTO `recipe_tip` VALUES (600478, 300263, 1, '牛油果必须选择熟透的，这样才能保证饮品的绵密口感和颜色。');
INSERT INTO `recipe_tip` VALUES (600479, 300263, 2, '如果喜欢更冰凉的口感，可以适当减少一点牛奶，加入几块冰块一起搅拌。');
INSERT INTO `recipe_tip` VALUES (600480, 300264, 1, '警告：操作时请擦干手上水滴！以免水进入油锅中发生爆炸！造成严重烧伤！');
INSERT INTO `recipe_tip` VALUES (600481, 300268, 1, '建议搭配瘦肉和蔬菜食用来均衡营养');
INSERT INTO `recipe_tip` VALUES (600482, 300268, 2, '高胆固醇，不建议经常食用');
INSERT INTO `recipe_tip` VALUES (600483, 300268, 3, '参考资料：猪油拌饭 - 维基百科，自由的百科全书');
INSERT INTO `recipe_tip` VALUES (600484, 300269, 1, '操作时，需要注意，做猪皮冻，直接下锅煮就“废”了，也是最忌讳的，一定要用白醋和盐不断搓洗猪皮，这样保证煮好的猪皮晶莹剔透，而且还没腥味');
INSERT INTO `recipe_tip` VALUES (600485, 300269, 2, '参考资料：铭哥说美食');
INSERT INTO `recipe_tip` VALUES (600486, 300270, 1, '大火收汤时，注意不要糊锅，可以适当翻动来检查水位。');
INSERT INTO `recipe_tip` VALUES (600487, 300270, 2, '调味的技巧，最后加盐时，可以一点一点加入，搅拌后品尝味道，直到可以接受的口味');
INSERT INTO `recipe_tip` VALUES (600488, 300270, 3, '本菜品有酸菜的特殊风味');
INSERT INTO `recipe_tip` VALUES (600489, 300271, 1, '营养成分(每100g) 热量：64 Kcal');
INSERT INTO `recipe_tip` VALUES (600490, 300271, 2, '营养成分(每100g) 蛋白质：1.3 g');
INSERT INTO `recipe_tip` VALUES (600491, 300271, 3, '营养成分(每100g) 脂肪：0.0 g');
INSERT INTO `recipe_tip` VALUES (600492, 300271, 4, '营养成分(每100g) 碳水化合物：14.4 g');
INSERT INTO `recipe_tip` VALUES (600493, 300271, 5, '营养成分(每100g) 钠：0 mg');
INSERT INTO `recipe_tip` VALUES (600494, 300273, 1, '可根据个人口味微调盐与糖的比例，如果喜欢其他风味可以把每份的 3 克玉米淀粉换成可可粉或抹茶粉。');
INSERT INTO `recipe_tip` VALUES (600495, 300273, 2, '如果条件允许可以把蛋黄、低筋面粉等食材过筛，口感会更好。');
INSERT INTO `recipe_tip` VALUES (600496, 300273, 3, '介于材料获取难度选择了白砂糖，如果条件允许可以换成糖粉 30 克。');
INSERT INTO `recipe_tip` VALUES (600497, 300273, 4, '如果没有烤箱可使用微波炉、空气炸锅等，微波炉为高火 2-3 分钟，空气炸锅为 150℃20 分钟');
INSERT INTO `recipe_tip` VALUES (600498, 300273, 5, '参考资料：第一百种可邮寄的小饼干 酥酥糯糯入口即化~-哔哩哔哩');
INSERT INTO `recipe_tip` VALUES (600499, 300276, 1, '营养成分(每100g) 热量：204 Kcal');
INSERT INTO `recipe_tip` VALUES (600500, 300276, 2, '营养成分(每100g) 蛋白质：9.4 g');
INSERT INTO `recipe_tip` VALUES (600501, 300276, 3, '营养成分(每100g) 脂肪：12.3 g');
INSERT INTO `recipe_tip` VALUES (600502, 300276, 4, '营养成分(每100g) 碳水化合物：14.1 g');
INSERT INTO `recipe_tip` VALUES (600503, 300276, 5, '营养成分(每100g) 钠：467 mg');
INSERT INTO `recipe_tip` VALUES (600504, 300277, 1, '本例中鸡全翅口感为微辣，需增加辣度请增加辣椒粉用量，但不宜超过 30g');
INSERT INTO `recipe_tip` VALUES (600505, 300277, 2, '鸡全翅指包含翅尖，翅中和翅根的鸡翅');
INSERT INTO `recipe_tip` VALUES (600506, 300277, 3, '本品效果微焦，如不喜欢焦褐色外观可 不向锡纸盘中倒入残余酱汁并 每面只烤制 20 分钟');
INSERT INTO `recipe_tip` VALUES (600507, 300277, 4, '实际烤制效果请根据自己空气炸锅的功率判断');
INSERT INTO `recipe_tip` VALUES (600508, 300277, 5, '甜椒粉起增加色泽和风味作用，本身不能作为辣味剂');
INSERT INTO `recipe_tip` VALUES (600509, 300277, 6, '腌制时间可自由掌控，建议在 60 分钟到 180 分钟之间为宜');
INSERT INTO `recipe_tip` VALUES (600510, 300277, 7, '刚出锅的锡纸盘比较烫，请用夹子夹取或使用湿抹布之类的隔热材料拿取');
INSERT INTO `recipe_tip` VALUES (600511, 300279, 1, '辣椒油可以根据口味放');
INSERT INTO `recipe_tip` VALUES (600512, 300282, 1, '食用方法：先吮吸壳内汤汁，再用牙签挑出或用嘴猛吸出肉馅——\"嗦螺贴唇猛吸气\"');
INSERT INTO `recipe_tip` VALUES (600513, 300282, 2, '螺肉和猪肉最佳比例为 1:1');
INSERT INTO `recipe_tip` VALUES (600514, 300282, 3, '薄荷是这道菜的精华，紫苏配田螺是绝配，两者至少要有其一');
INSERT INTO `recipe_tip` VALUES (600515, 300282, 4, '没有三花酒可用料酒代替，但风味会打折扣');
INSERT INTO `recipe_tip` VALUES (600516, 300282, 5, '焯水时间一定要短，久了螺肉变老发硬');
INSERT INTO `recipe_tip` VALUES (600517, 300282, 6, '搭配冰镇漓泉啤酒是阳朔当地的标准吃法');
INSERT INTO `recipe_tip` VALUES (600518, 300282, 7, '参考资料：阳朔田螺酿_百度百科');
INSERT INTO `recipe_tip` VALUES (600519, 300284, 1, '技术总结');
INSERT INTO `recipe_tip` VALUES (600520, 300284, 2, '不论什么容器，水的量都是可以使用“指尖量水法”煮出好米饭。');
INSERT INTO `recipe_tip` VALUES (600521, 300284, 3, '水的多少是能够严重影响一碗好米饭的口感。');
INSERT INTO `recipe_tip` VALUES (600522, 300284, 4, '南方一般食用江南米，北方一般食用北方大米，江南米会比较细长，而北方大米会比较短且圆。');
INSERT INTO `recipe_tip` VALUES (600523, 300284, 5, '米饭不同品种的米，不同的水量会极度影响口感。');
INSERT INTO `recipe_tip` VALUES (600524, 300284, 6, '更多信息请参考使用的电饭煲的说明书。');
INSERT INTO `recipe_tip` VALUES (600525, 300285, 1, '可以根据口味加入一定的醋或糖来调整口感');
INSERT INTO `recipe_tip` VALUES (600526, 300285, 2, '如果喜欢辣味，可以加入一定的辣椒或辣椒酱来调味');
INSERT INTO `recipe_tip` VALUES (600527, 300286, 1, '考虑各个品牌的番茄酱内含盐量不同，建议在炒牛肉时少放盐，煮的时候尝一下再调味');
INSERT INTO `recipe_tip` VALUES (600528, 300286, 2, '煮酱料期间请搅动，以免粘锅。如果酱料变粘稠就可以出锅啦！');
INSERT INTO `recipe_tip` VALUES (600529, 300286, 3, '可根据个人口味，将碎牛肉替换成一半碎猪肉一半碎牛肉，牛奶替换成鸡汤或饮用水。');
