INSERT INTO `recipe_tip` VALUES (600585, 300320, 2, '蒜粉、红甜椒粉和洋葱粉可以根据个人口味调整用量。');
INSERT INTO `recipe_tip` VALUES (600586, 300320, 3, '想做辣味：在裹粉中加入辣椒粉 3g，或在出锅后撒辣椒面 2g。');
INSERT INTO `recipe_tip` VALUES (600587, 300320, 4, '想做孜然味：在出锅后撒孜然粉 2g 和白芝麻 2g。');
INSERT INTO `recipe_tip` VALUES (600588, 300320, 5, '不建议鸡翅叠放，会导致接触面受热不足，外壳不够脆。');
