INSERT INTO `recipe_tip` VALUES (600628, 300343, 5, '营养成分(每100g) 钠：410 mg');
INSERT INTO `recipe_tip` VALUES (600629, 300344, 1, '切豆角需要一定的刀工，不会的可以使用剪刀');
INSERT INTO `recipe_tip` VALUES (600630, 300346, 1, '水开后，将火关小，将打好的蛋液围绕中间沸腾的水倒入。为了使蛋花比较嫩，锅盖盖上熄灭火等半分钟后再打开.');
INSERT INTO `recipe_tip` VALUES (600631, 300346, 2, '如果喜欢浓稠口感，可加入 2g 淀粉.');
INSERT INTO `recipe_tip` VALUES (600632, 300347, 1, '营养成分(每100g) 热量：168 Kcal');
INSERT INTO `recipe_tip` VALUES (600633, 300347, 2, '营养成分(每100g) 蛋白质：3.1 g');
INSERT INTO `recipe_tip` VALUES (600634, 300347, 3, '营养成分(每100g) 脂肪：1.4 g');
INSERT INTO `recipe_tip` VALUES (600635, 300347, 4, '营养成分(每100g) 碳水化合物：35.1 g');
INSERT INTO `recipe_tip` VALUES (600636, 300347, 5, '营养成分(每100g) 钠：0 mg');
INSERT INTO `recipe_tip` VALUES (600637, 300348, 1, '如果喜欢较甜的口感可以增加 10g 糖');
INSERT INTO `recipe_tip` VALUES (600638, 300348, 2, '红柚果肉可以酌情添加，但每份最好不超过 40g 以免影响成品观感');
INSERT INTO `recipe_tip` VALUES (600639, 300348, 3, '糊状指没有面粉疙瘩且整体颜色均匀');
INSERT INTO `recipe_tip` VALUES (600640, 300348, 4, '刚出锅的锡纸盘比较烫，请用夹子夹取或使用湿抹布之类的隔热材料拿取');
INSERT INTO `recipe_tip` VALUES (600641, 300355, 1, '五花肉煸炒的时候会出猪油，相比较于植物油，动物油脂更香。');
INSERT INTO `recipe_tip` VALUES (600642, 300355, 2, '煸炒至金黄的五花肉炖煮过后吃起来也很香的，相当于配菜。');
INSERT INTO `recipe_tip` VALUES (600643, 300355, 3, '鱼类本身脂肪含量少，所以香味欠缺，着重的是肉质的口感。所以一般做鱼类菜都建议用猪油，想要一锅奶白香醇的鱼汤。猪油是最好的选择~');
INSERT INTO `recipe_tip` VALUES (600644, 300356, 1, '如果闻着有腥味，可以增加一倍香料用量。');
INSERT INTO `recipe_tip` VALUES (600645, 300357, 1, '红芸豆必须煮熟透才能食用，未熟的红芸豆含有植物血凝素(Phytohaemagglutinin)，可能导致食物中毒。');
INSERT INTO `recipe_tip` VALUES (600646, 300357, 2, '在印度，Rajma Chawal 被认为是最有家的味道的食物，地位类似于中国的\"红烧肉配米饭\"。');
INSERT INTO `recipe_tip` VALUES (600647, 300357, 3, '如果想要更浓郁的口感，可以加入 30ml 淡奶油。');
INSERT INTO `recipe_tip` VALUES (600648, 300357, 4, '剩余的红芸豆咖喱冷藏保存可达 3-4 天，味道会更好。');
INSERT INTO `recipe_tip` VALUES (600649, 300358, 1, '营养成分(每100g) 热量：56 Kcal');
INSERT INTO `recipe_tip` VALUES (600650, 300358, 2, '营养成分(每100g) 蛋白质：1.6 g');
