INSERT INTO `recipe_tip` VALUES (600658, 300359, 5, '营养成分(每100g) 钠：663 mg');
INSERT INTO `recipe_tip` VALUES (600659, 300360, 1, '番茄尽量不用新鲜番茄代替，番茄罐头+番茄膏的组合风味更足');
INSERT INTO `recipe_tip` VALUES (600660, 300360, 2, '除了胡萝卜、洋葱、欧芹、牛肉是必备食材外，其余可自由搭配');
INSERT INTO `recipe_tip` VALUES (600661, 300361, 1, '中筋面粉 300 g');
INSERT INTO `recipe_tip` VALUES (600662, 300361, 2, '盐 3 g');
INSERT INTO `recipe_tip` VALUES (600663, 300361, 3, '水 180 ml');
INSERT INTO `recipe_tip` VALUES (600664, 300361, 4, '先把材料混合均匀，加水边和边搅拌，然后把面团和到光滑');
INSERT INTO `recipe_tip` VALUES (600665, 300361, 5, '醒面（ 10 分钟）');
INSERT INTO `recipe_tip` VALUES (600666, 300361, 6, '再次和面到光滑');
INSERT INTO `recipe_tip` VALUES (600667, 300361, 7, '醒面（ 5 分钟）');
INSERT INTO `recipe_tip` VALUES (600668, 300361, 8, '把面团揉成条，切成 6 到 8 个小剂子');
INSERT INTO `recipe_tip` VALUES (600669, 300361, 9, '抹上油，等待 5 分钟');
INSERT INTO `recipe_tip` VALUES (600670, 300361, 10, '把面团剂子擀成面皮');
INSERT INTO `recipe_tip` VALUES (600671, 300361, 11, '放入锅中焖煮 4 分钟（一片一片操作）');
INSERT INTO `recipe_tip` VALUES (600672, 300362, 1, '加入开水时，注意要开大火，使油脂与汤汁更好的融合');
INSERT INTO `recipe_tip` VALUES (600673, 300363, 1, '想吃的更丰富可以在最后一步那里加上炒好的番茄丁，洋葱丁，培根丁，切好的芝士小丁，等等。(总之不会再出水的东东）');
INSERT INTO `recipe_tip` VALUES (600674, 300363, 2, '使用平底锅（不粘锅）。');
INSERT INTO `recipe_tip` VALUES (600675, 300363, 3, '考虑到很多人是一人食就炒一两个鸡蛋，口径比较小的锅或许更方便在锅中均匀搅拌。');
INSERT INTO `recipe_tip` VALUES (600676, 300364, 1, '记得米粉必须是泡过的才好吃，没有泡过的话是很难吃的！');
INSERT INTO `recipe_tip` VALUES (600677, 300367, 1, '注意事项：');
INSERT INTO `recipe_tip` VALUES (600678, 300367, 2, '1. 肉片厚度应为 8mm，过厚过薄都会影响口感。');
INSERT INTO `recipe_tip` VALUES (600679, 300367, 3, '2. 炸制时控制油温，避免外壳过深或不酥脆，这点非常重要。');
INSERT INTO `recipe_tip` VALUES (600680, 300367, 4, '3. 熬糖醋汁时，注意熬至粘稠但不结块，避免变成糖浆。');
INSERT INTO `recipe_tip` VALUES (600681, 300367, 5, '参考资料：');
INSERT INTO `recipe_tip` VALUES (600682, 300367, 6, '老饭骨版本');
INSERT INTO `recipe_tip` VALUES (600683, 300367, 7, '老东北美食版本');
INSERT INTO `recipe_tip` VALUES (600684, 300367, 8, '村驴版本');
