INSERT INTO `recipe_tip` VALUES (600699, 300370, 5, '营养成分(每100g) 钠：101 mg');
INSERT INTO `recipe_tip` VALUES (600700, 300373, 1, '耙耙柑可以用其他容易分离果肉的柑橘替代，比如丑橘');
INSERT INTO `recipe_tip` VALUES (600701, 300373, 2, '果肉和茶水比例为 1 : 1，如果需要配置更大的分量，可按比例提升用量');
INSERT INTO `recipe_tip` VALUES (600702, 300375, 1, '如果喜欢甜口可以增加 10g 糖');
INSERT INTO `recipe_tip` VALUES (600703, 300375, 2, '请务必保证做完饭后关掉燃气设备以免发生危险');
INSERT INTO `recipe_tip` VALUES (600704, 300376, 1, '建议冷冻 20 分钟让螃蟹昏迷（别冻硬！），或用筷子从口器插入破坏神经');
INSERT INTO `recipe_tip` VALUES (600705, 300376, 2, '如果使用的是冷冻蟹，完全解冻蟹脚容易掉，并且容易造成肉质流失。建议半解冻后裹粉油炸，并将油炸时间延长至 2 分钟');
INSERT INTO `recipe_tip` VALUES (600706, 300376, 3, '如果灶具功率较小，食材下油锅后容易迅速降温，建议油温预热到 200 °C，并且分多批次油炸');
INSERT INTO `recipe_tip` VALUES (600707, 300376, 4, '务必去掉蟹胃（三角包）、蟹腮、蟹心（六角形白片）');
INSERT INTO `recipe_tip` VALUES (600708, 300376, 5, '裹淀粉的螃蟹下锅前务必擦干，热油遇水容易飞溅');
INSERT INTO `recipe_tip` VALUES (600709, 300376, 6, '死蟹绝对不能用（买来的就是冷冻的除外，但是解冻后未及时使用的也不行）');
INSERT INTO `recipe_tip` VALUES (600710, 300376, 7, '不与柿子、浓茶同食');
INSERT INTO `recipe_tip` VALUES (600711, 300376, 8, '痛风患者慎食');
INSERT INTO `recipe_tip` VALUES (600712, 300376, 9, '年糕切片后泡冷水，下锅前冲洗不容易粘锅，下锅后放在表面，沉入锅底容易糊锅');
INSERT INTO `recipe_tip` VALUES (600713, 300376, 10, '要是被螃蟹夹了或者烫伤了，先用冷水冲 15 分钟，严重的话及时就医，如果伤口比较深务必就医');
INSERT INTO `recipe_tip` VALUES (600714, 300377, 1, '在取出肉饼炖蛋时，注意盘子很烫，请小心操作。');
INSERT INTO `recipe_tip` VALUES (600715, 300379, 1, '营养成分(每100g) 热量：142 Kcal');
INSERT INTO `recipe_tip` VALUES (600716, 300379, 2, '营养成分(每100g) 蛋白质：10.6 g');
INSERT INTO `recipe_tip` VALUES (600717, 300379, 3, '营养成分(每100g) 脂肪：10.9 g');
INSERT INTO `recipe_tip` VALUES (600718, 300379, 4, '营养成分(每100g) 碳水化合物：0.7 g');
INSERT INTO `recipe_tip` VALUES (600719, 300379, 5, '营养成分(每100g) 钠：422 mg');
INSERT INTO `recipe_tip` VALUES (600720, 300380, 1, '营养成分(每100g) 热量：131 Kcal');
INSERT INTO `recipe_tip` VALUES (600721, 300380, 2, '营养成分(每100g) 蛋白质：12.4 g');
INSERT INTO `recipe_tip` VALUES (600722, 300380, 3, '营养成分(每100g) 脂肪：8.5 g');
INSERT INTO `recipe_tip` VALUES (600723, 300380, 4, '营养成分(每100g) 碳水化合物：1.4 g');
INSERT INTO `recipe_tip` VALUES (600724, 300380, 5, '营养成分(每100g) 钠：485 mg');
INSERT INTO `recipe_tip` VALUES (600725, 300389, 1, '胡萝卜甜糕可以热吃也可以冷吃，两种风味各有特色。');
INSERT INTO `recipe_tip` VALUES (600726, 300389, 2, '使用红色胡萝卜比橙色胡萝卜做出来的色泽更好看。');
INSERT INTO `recipe_tip` VALUES (600727, 300389, 3, '如果想要更浓郁的口感，可以用淡奶油替代部分牛奶。');
INSERT INTO `recipe_tip` VALUES (600728, 300389, 4, '密封冷藏可保存 4-5 天。食用前可用微波炉加热 1 分钟。');
INSERT INTO `recipe_tip` VALUES (600729, 300389, 5, '这道甜品在印度几乎每个家庭都会做，是排灯节(Diwali)和婚礼上必不可少的甜品。');
INSERT INTO `recipe_tip` VALUES (600730, 300391, 1, '营养成分(每100g) 热量：314 Kcal');
INSERT INTO `recipe_tip` VALUES (600731, 300391, 2, '营养成分(每100g) 蛋白质：13.8 g');
INSERT INTO `recipe_tip` VALUES (600732, 300391, 3, '营养成分(每100g) 脂肪：21.8 g');
INSERT INTO `recipe_tip` VALUES (600733, 300391, 4, '营养成分(每100g) 碳水化合物：16.1 g');
INSERT INTO `recipe_tip` VALUES (600734, 300391, 5, '营养成分(每100g) 钠：730 mg');
INSERT INTO `recipe_tip` VALUES (600735, 300392, 1, '往粥锅加入食材时，应当进行搅拌，使食材原料均匀分布在各处，并注意观察水位线，如发现水位线低于米线及食材应立即补水。');
INSERT INTO `recipe_tip` VALUES (600736, 300392, 2, '注意控制火候，不要过大，定时搅拌。如果使用普通锅，建议烧开水后再下原料，搅拌到再次烧开改小火，避免锅底烧糊。如果有条件，建议改用高压锅或粥锅。');
INSERT INTO `recipe_tip` VALUES (600737, 300392, 3, '参考资料：全网最正宗腊八粥做法，香甜软糯一次成功！\\_哔哩哔哩\\_bilibili 、 腊八粥（在腊八节用多种食材熬制的粥）_百度百科');
INSERT INTO `recipe_tip` VALUES (600738, 300393, 1, '建议用单晶冰糖');
INSERT INTO `recipe_tip` VALUES (600739, 300393, 2, '腐乳自带咸鲜，不用额外放盐');
INSERT INTO `recipe_tip` VALUES (600740, 300393, 3, '大火收汁时要不断晃动锅体避免粘底');
INSERT INTO `recipe_tip` VALUES (600741, 300393, 4, '参考资料：【步骤图】腐乳肉的做法_腐乳肉的做法步骤_菜谱_下厨房');
INSERT INTO `recipe_tip` VALUES (600742, 300395, 1, '制作时最好佩戴不粘手套');
INSERT INTO `recipe_tip` VALUES (600743, 300395, 2, '制作完即可食用，不用再加热');
INSERT INTO `recipe_tip` VALUES (600744, 300396, 1, '如果没有电饼铛，也可以用平底锅');
INSERT INTO `recipe_tip` VALUES (600745, 300396, 2, '芝麻如果没有也可不用，一样好吃');
INSERT INTO `recipe_tip` VALUES (600746, 300397, 1, '注意事项：');
INSERT INTO `recipe_tip` VALUES (600747, 300397, 2, '1. 黄油入锅后不宜炸制太久，融化翻拌均匀即可烹入碗汁');
INSERT INTO `recipe_tip` VALUES (600748, 300398, 1, '酱汁提前调配好，黄油提前备好，防止中间备料耗时。');
INSERT INTO `recipe_tip` VALUES (600749, 300398, 2, '蒜蓉切记要等虾煎好后捞出再下，防止煎炒过久变黑，发苦。');
INSERT INTO `recipe_tip` VALUES (600750, 300398, 3, '如果不太能接受芥末就放少点，能接受就放多点，如果放多了，煮久一会儿，芥末味也会散去。');
INSERT INTO `recipe_tip` VALUES (600751, 300400, 1, '焯水时的水位需要没过芹菜');
INSERT INTO `recipe_tip` VALUES (600752, 300400, 2, '芹菜叶太老太硬的话可以不要');
INSERT INTO `recipe_tip` VALUES (600753, 300403, 1, '芝士片、培根片、手抓饼直接淘宝购买即可');
INSERT INTO `recipe_tip` VALUES (600754, 300404, 1, '最简单的分切方案是擀成圆形面皮，用刀切成 6 个扇形');
INSERT INTO `recipe_tip` VALUES (600755, 300407, 1, '用小火煎');
INSERT INTO `recipe_tip` VALUES (600756, 300408, 1, '最后一个步骤，可以考虑加蚝油、生抽代替盐上色');
INSERT INTO `recipe_tip` VALUES (600757, 300409, 1, '鸡蛋捞出过冷水是为了让鸡蛋和壳之间产生间隙');
INSERT INTO `recipe_tip` VALUES (600758, 300409, 2, '食盐可根据个人口味选择不加');
INSERT INTO `recipe_tip` VALUES (600759, 300409, 3, '八角，香叶，桂皮，茴香，冰糖，自己没有这么多食材可以买现成的卤料包');
INSERT INTO `recipe_tip` VALUES (600760, 300409, 4, '常规做法的卤汁渗透速度慢，内部味道容易偏淡。想入味更快、切面更好看：剥壳 → 在蛋白侧面划 3–11 刀（上下十字方向，接近蛋黄即可，别太深以免蛋黄散出）→ 放入小容器，卤汁没过鸡蛋 → 浸泡 2 天以上');
INSERT INTO `recipe_tip` VALUES (600761, 300410, 1, '制作过程中注意安全，避免割/烫到手。');
INSERT INTO `recipe_tip` VALUES (600762, 300412, 1, '更多情况下，福州当地会选用马蹄（解腻）和马铃薯（洗油），因为疫情期间买不到，所以选用了凤梨');
INSERT INTO `recipe_tip` VALUES (600763, 300412, 2, '闽菜以甜为主，如果吃不惯的可以放弃白糖');
INSERT INTO `recipe_tip` VALUES (600764, 300412, 3, '可以通过勺子敲打瘦肉块，听到声响来判断是否炸透瘦肉');
INSERT INTO `recipe_tip` VALUES (600765, 300414, 1, '在制作过程中没有放盐，是因为腊肠本身会有一些味道，同时生抽也会有一些咸味。');
INSERT INTO `recipe_tip` VALUES (600766, 300414, 2, '腊肠虽然味道不错，但属于不太健康的食物，建议少放。');
INSERT INTO `recipe_tip` VALUES (600767, 300416, 1, '选择莴笋叶是某省市买到的蔬菜包基本都包含莴笋，可以换成韭菜等');
INSERT INTO `recipe_tip` VALUES (600768, 300416, 2, '莴笋叶直接焯水后凉拌有苦味，所以选择做成煎饼的配菜');
INSERT INTO `recipe_tip` VALUES (600769, 300418, 1, '营养成分(每100g) 热量：20 Kcal');
INSERT INTO `recipe_tip` VALUES (600770, 300418, 2, '营养成分(每100g) 蛋白质：2.4 g');
INSERT INTO `recipe_tip` VALUES (600771, 300418, 3, '营养成分(每100g) 脂肪：0.7 g');
INSERT INTO `recipe_tip` VALUES (600772, 300418, 4, '营养成分(每100g) 碳水化合物：1.0 g');
INSERT INTO `recipe_tip` VALUES (600773, 300418, 5, '营养成分(每100g) 钠：237 mg');
INSERT INTO `recipe_tip` VALUES (600774, 300423, 1, '咖啡液建议选用花果风味，浓缩可以用中烘豆，冷萃可以用普通水洗或者日晒');
INSERT INTO `recipe_tip` VALUES (600775, 300423, 2, '倒入奶油时，高度尽量放低，让奶油能均匀漂浮在饮料表面形成奶盖');
INSERT INTO `recipe_tip` VALUES (600776, 300423, 3, '用新鲜的咖啡液和菠萝汁能大大提升整体风味口感');
INSERT INTO `recipe_tip` VALUES (600777, 300424, 1, '操作时，需要注意观察沸腾的水位线，如发现低于 2/3 的食材应加热水至没过食材。');
INSERT INTO `recipe_tip` VALUES (600778, 300425, 1, '渣后的开洋葱渣也可以食用，葱油可以滤掉这些料渣，也可以保留');
INSERT INTO `recipe_tip` VALUES (600779, 300425, 2, '开洋可以极大提升葱油鲜香，并增加鲜甜风味');
INSERT INTO `recipe_tip` VALUES (600780, 300426, 1, '炸葱油时，火一定要小，要有耐心，才能将葱的香味充分炸出。');
INSERT INTO `recipe_tip` VALUES (600781, 300426, 2, '制作好的葱油酱汁可以冷藏保存一段时间，下次吃面时直接取用。');
INSERT INTO `recipe_tip` VALUES (600782, 300433, 1, '营养成分(每100g) 热量：180 Kcal');
INSERT INTO `recipe_tip` VALUES (600783, 300433, 2, '营养成分(每100g) 蛋白质：20.7 g');
INSERT INTO `recipe_tip` VALUES (600784, 300433, 3, '营养成分(每100g) 脂肪：9.9 g');
INSERT INTO `recipe_tip` VALUES (600785, 300433, 4, '营养成分(每100g) 碳水化合物：2.0 g');
INSERT INTO `recipe_tip` VALUES (600786, 300433, 5, '营养成分(每100g) 钠：1080 mg');
INSERT INTO `recipe_tip` VALUES (600787, 300434, 1, '营养成分(每100g) 热量：183 Kcal');
INSERT INTO `recipe_tip` VALUES (600788, 300434, 2, '营养成分(每100g) 蛋白质：15.0 g');
INSERT INTO `recipe_tip` VALUES (600789, 300434, 3, '营养成分(每100g) 脂肪：13.3 g');
INSERT INTO `recipe_tip` VALUES (600790, 300434, 4, '营养成分(每100g) 碳水化合物：1.1 g');
INSERT INTO `recipe_tip` VALUES (600791, 300434, 5, '营养成分(每100g) 钠：812 mg');
INSERT INTO `recipe_tip` VALUES (600792, 300436, 1, '操作时，需要注意观察锅中的水量，如快见底的时候就直接接入水淀粉即可。');
INSERT INTO `recipe_tip` VALUES (600793, 300437, 1, '1. 把鸡腿洗干净，用厨房纸吸干表面水分。');
INSERT INTO `recipe_tip` VALUES (600794, 300437, 2, '2. 从鸡腿较粗的一头找到骨头的末端。');
INSERT INTO `recipe_tip` VALUES (600795, 300437, 3, '3. 用剪刀尖贴着骨头剪开外层的皮和肉，沿着骨头一侧剪到底。');
INSERT INTO `recipe_tip` VALUES (600796, 300437, 4, '4. 把鸡腿翻个面，沿骨头的另一侧继续剪。');
INSERT INTO `recipe_tip` VALUES (600797, 300437, 5, '5. 用手指把肉和骨头之间的连接处剥开。');
INSERT INTO `recipe_tip` VALUES (600798, 300437, 6, '6. 找到骨头的关节处剪断，把骨头整根抽出。');
INSERT INTO `recipe_tip` VALUES (600799, 300437, 7, '极简版：只用葱 + 鸡腿 + 盐 + 生抽 + 糖也能做出来，但葱香会比较单一。');
INSERT INTO `recipe_tip` VALUES (600800, 300437, 8, '推荐版：加上姜、花椒、蚝油，香味会丰富很多。');
INSERT INTO `recipe_tip` VALUES (600801, 300437, 9, '完美版：再加点老抽上色 + 熟白芝麻点缀，卖相和口感都能上一个台阶。');
INSERT INTO `recipe_tip` VALUES (600802, 300437, 10, '1. 冷藏保存：密封后放冰箱冷藏，可保存 2 天。');
INSERT INTO `recipe_tip` VALUES (600803, 300437, 11, '2. 冷冻保存：放凉后分装冷冻，可保存 1 个月。');
INSERT INTO `recipe_tip` VALUES (600804, 300437, 12, '3. 回热方式：微波炉中火加热 2 分钟，或回锅加一点点水翻炒。');
INSERT INTO `recipe_tip` VALUES (600805, 300439, 1, '营养成分(每100g) 热量：282 Kcal');
INSERT INTO `recipe_tip` VALUES (600806, 300439, 2, '营养成分(每100g) 蛋白质：8.4 g');
INSERT INTO `recipe_tip` VALUES (600807, 300439, 3, '营养成分(每100g) 脂肪：14.0 g');
INSERT INTO `recipe_tip` VALUES (600808, 300439, 4, '营养成分(每100g) 碳水化合物：30.7 g');
INSERT INTO `recipe_tip` VALUES (600809, 300439, 5, '营养成分(每100g) 钠：254 mg');
INSERT INTO `recipe_tip` VALUES (600810, 300441, 1, '营养成分(每100g) 热量：129 Kcal');
INSERT INTO `recipe_tip` VALUES (600811, 300441, 2, '营养成分(每100g) 蛋白质：2.1 g');
INSERT INTO `recipe_tip` VALUES (600812, 300441, 3, '营养成分(每100g) 脂肪：8.8 g');
INSERT INTO `recipe_tip` VALUES (600813, 300441, 4, '营养成分(每100g) 碳水化合物：10.5 g');
INSERT INTO `recipe_tip` VALUES (600814, 300441, 5, '营养成分(每100g) 钠：1120 mg');
INSERT INTO `recipe_tip` VALUES (600815, 300442, 1, '加入食盐前可尝一下咸淡，自行决定是否增减盐量');
INSERT INTO `recipe_tip` VALUES (600816, 300442, 2, '选用五花肉薄片是因为切肉简单且不用腌制即可入味');
INSERT INTO `recipe_tip` VALUES (600817, 300444, 1, '营养成分(每100g) 热量：150 Kcal');
INSERT INTO `recipe_tip` VALUES (600818, 300444, 2, '营养成分(每100g) 蛋白质：9.7 g');
INSERT INTO `recipe_tip` VALUES (600819, 300444, 3, '营养成分(每100g) 脂肪：8.9 g');
INSERT INTO `recipe_tip` VALUES (600820, 300444, 4, '营养成分(每100g) 碳水化合物：7.8 g');
INSERT INTO `recipe_tip` VALUES (600821, 300444, 5, '营养成分(每100g) 钠：733 mg');
INSERT INTO `recipe_tip` VALUES (600822, 300446, 1, '芹菜选香芹（细梗品种）最佳，口感最脆嫩。普通芹菜也可以，但梗粗的需要纵向切细');
INSERT INTO `recipe_tip` VALUES (600823, 300446, 2, '大火快炒是关键，芹菜下锅到出锅不超过 1 分钟。炒久了会变软变蔫，失去脆生的口感');
INSERT INTO `recipe_tip` VALUES (600824, 300446, 3, '芹菜下锅前一定要尽量沥干水，水分太多会降低锅温，导致变成「煮」而不是「炒」');
INSERT INTO `recipe_tip` VALUES (600825, 300446, 4, '用猪油炒比食用油更香，如果没有猪油，食用油也可替代');
INSERT INTO `recipe_tip` VALUES (600826, 300447, 1, '空心菜尽量选择新鲜，鲜嫩的，否则炒出来口感可能会比较老');
INSERT INTO `recipe_tip` VALUES (600827, 300447, 2, '实际放入空心菜的量可以根据锅的大小决定，建议不超过一个锅，否则太多的话开始的翻动阶段和后续的翻炒，容易掉出少量空心菜到灶台');
INSERT INTO `recipe_tip` VALUES (600828, 300447, 3, '炒空心菜时，一定要开大火，这样空心菜才能快速变软的同时保持脆嫩的口感，大火也有利于炒出生抽的香味。');
INSERT INTO `recipe_tip` VALUES (600829, 300450, 1, '焯水时间不宜超过推荐时长，以免影响西兰花的口感和营养。');
INSERT INTO `recipe_tip` VALUES (600830, 300450, 2, '如果想保留西兰花更脆的口感，可以缩短焯水时间。');
INSERT INTO `recipe_tip` VALUES (600831, 300452, 1, '虾不宜过度烹饪，否则会变硬');
INSERT INTO `recipe_tip` VALUES (600832, 300453, 1, '营养成分(每100g) 热量：114 Kcal');
INSERT INTO `recipe_tip` VALUES (600833, 300453, 2, '营养成分(每100g) 蛋白质：4.2 g');
INSERT INTO `recipe_tip` VALUES (600834, 300453, 3, '营养成分(每100g) 脂肪：9.4 g');
INSERT INTO `recipe_tip` VALUES (600835, 300453, 4, '营养成分(每100g) 碳水化合物：3.3 g');
INSERT INTO `recipe_tip` VALUES (600836, 300453, 5, '营养成分(每100g) 钠：475 mg');
INSERT INTO `recipe_tip` VALUES (600837, 300454, 1, '这个蒲焼き其实很中国，日式的蒲烧其实是烤的。');
INSERT INTO `recipe_tip` VALUES (600838, 300454, 2, '灵魂其实在于蒲烧汁？也可以买现成的蒲烧汁。');
INSERT INTO `recipe_tip` VALUES (600839, 300454, 3, '如果觉得腻可以在装盘后撒点切成 2~5 mm 的小葱，颜色搭配上也能不那么单调。');
INSERT INTO `recipe_tip` VALUES (600840, 300454, 4, '炒茄子（鱼香茄子、酱爆茄子）墙裂推荐浙茄，细长所以切成滚刀块刚刚好，皮很嫩不像这里需要去皮，茄子的味道适中。');
INSERT INTO `recipe_tip` VALUES (600841, 300455, 1, '营养成分(每100g) 热量：65 Kcal');
INSERT INTO `recipe_tip` VALUES (600842, 300455, 2, '营养成分(每100g) 蛋白质：2.2 g');
INSERT INTO `recipe_tip` VALUES (600843, 300455, 3, '营养成分(每100g) 脂肪：0.0 g');
INSERT INTO `recipe_tip` VALUES (600844, 300455, 4, '营养成分(每100g) 碳水化合物：13.7 g');
INSERT INTO `recipe_tip` VALUES (600845, 300455, 5, '营养成分(每100g) 钠：0 mg');
INSERT INTO `recipe_tip` VALUES (600846, 300456, 1, '技术总结');
INSERT INTO `recipe_tip` VALUES (600847, 300456, 2, '切割猪肉时，可以让菜市场摊贩帮忙，根据经验，请求时机把握在已切割后未付款之前成功率最高');
INSERT INTO `recipe_tip` VALUES (600848, 300456, 3, '首次做饭时可以提前备好料防止手忙脚乱，后续熟练后可以并发执行');
INSERT INTO `recipe_tip` VALUES (600849, 300456, 4, '两次蒸面条时，都要尽量的弄散开，可以避免蒸好后团在一起。面条太长时可以拽断，方便后续搅拌与盛取');
INSERT INTO `recipe_tip` VALUES (600850, 300456, 5, '取出蒸好的面条时尽量动作轻一些，避免蒸屉翻到面条触水');
INSERT INTO `recipe_tip` VALUES (600851, 300456, 6, '佐餐时啤酒更配呦！');
INSERT INTO `recipe_tip` VALUES (600852, 300457, 1, '营养成分(每100g) 热量：112 Kcal');
INSERT INTO `recipe_tip` VALUES (600853, 300457, 2, '营养成分(每100g) 蛋白质：7.2 g');
INSERT INTO `recipe_tip` VALUES (600854, 300457, 3, '营养成分(每100g) 脂肪：4.5 g');
INSERT INTO `recipe_tip` VALUES (600855, 300457, 4, '营养成分(每100g) 碳水化合物：10.5 g');
INSERT INTO `recipe_tip` VALUES (600856, 300457, 5, '营养成分(每100g) 钠：529 mg');
INSERT INTO `recipe_tip` VALUES (600857, 300458, 1, '一般出锅稍晾即可食用，保留鸡蛋原香的终极口感');
INSERT INTO `recipe_tip` VALUES (600858, 300458, 2, '也可加入蒸鱼豉油，葱花香油作为佐料。');
INSERT INTO `recipe_tip` VALUES (600859, 300460, 1, '操作时，需要注意观察锅里的水不能少于 50ml。');
INSERT INTO `recipe_tip` VALUES (600860, 300462, 1, '营养成分(每100g) 热量：231 Kcal');
