INSERT INTO `recipe_tip` VALUES (600864, 300462, 5, '营养成分(每100g) 钠：473 mg');
INSERT INTO `recipe_tip` VALUES (600865, 300463, 1, '营养成分(每100g) 热量：70 Kcal');
INSERT INTO `recipe_tip` VALUES (600866, 300463, 2, '营养成分(每100g) 蛋白质：1.2 g');
INSERT INTO `recipe_tip` VALUES (600867, 300463, 3, '营养成分(每100g) 脂肪：5.7 g');
INSERT INTO `recipe_tip` VALUES (600868, 300463, 4, '营养成分(每100g) 碳水化合物：3.5 g');
INSERT INTO `recipe_tip` VALUES (600869, 300463, 5, '营养成分(每100g) 钠：98 mg');
INSERT INTO `recipe_tip` VALUES (600870, 300465, 1, '参考资料：Bilibili老饭骨的视频教程');
INSERT INTO `recipe_tip` VALUES (600871, 300468, 1, '粉丝不建议煮太久，易断且口感变差；若时间过长汤汁应适当减少');
INSERT INTO `recipe_tip` VALUES (600872, 300468, 2, '郫县豆瓣酱含盐量较高，可根据口味酌情减少生抽用量');
INSERT INTO `recipe_tip` VALUES (600873, 300468, 3, '可加入 0.5g 白胡椒粉调味，风味更佳');
INSERT INTO `recipe_tip` VALUES (600874, 300469, 1, '营养成分(每100g) 热量：154 Kcal');
INSERT INTO `recipe_tip` VALUES (600875, 300469, 2, '营养成分(每100g) 蛋白质：8.3 g');
INSERT INTO `recipe_tip` VALUES (600876, 300469, 3, '营养成分(每100g) 脂肪：8.3 g');
INSERT INTO `recipe_tip` VALUES (600877, 300469, 4, '营养成分(每100g) 碳水化合物：11.5 g');
INSERT INTO `recipe_tip` VALUES (600878, 300469, 5, '营养成分(每100g) 钠：458 mg');
INSERT INTO `recipe_tip` VALUES (600879, 300473, 1, '炒饭用隔夜饭不易粘锅，口感更好。');
INSERT INTO `recipe_tip` VALUES (600880, 300473, 2, '打蛋时加入牛奶可以让蛋皮更加嫩滑。');
INSERT INTO `recipe_tip` VALUES (600881, 300473, 3, '操作蛋皮时火力需小，避免底部焦糊。');
INSERT INTO `recipe_tip` VALUES (600882, 300473, 4, '如果不擅长包裹造型，也可以直接将炒饭铺盘后盖上蛋皮。');
INSERT INTO `recipe_tip` VALUES (600883, 300474, 1, '技术总结');
INSERT INTO `recipe_tip` VALUES (600884, 300474, 2, '使用隔夜的冷饭炒饭最佳，没有冷饭的同学也可以现煮（可以使用冰箱立马给米饭降温），不过要做到“粒粒分明”的口感就需要炒更久。');
INSERT INTO `recipe_tip` VALUES (600885, 300474, 3, '炒饭要做到“粒粒分明”其实就是要将饭炒干。为什么要用隔夜的冷饭是因为隔夜已经流失了一定的水分。');
INSERT INTO `recipe_tip` VALUES (600886, 300475, 1, '放糍粑进去时候注意把糍粑间隔开来，防止粘在一起');
INSERT INTO `recipe_tip` VALUES (600887, 300475, 2, '鸡蛋的量根据糍粑的量而定');
INSERT INTO `recipe_tip` VALUES (600888, 300475, 3, '糖的量根据个人喜好');
INSERT INTO `recipe_tip` VALUES (600889, 300475, 4, '蛋煎糍粑教程');
INSERT INTO `recipe_tip` VALUES (600890, 300477, 1, '更多情况下，福州当地会选用马蹄（解腻）和马铃薯（洗油），因为疫情期间买不到，所以选用了凤梨');
INSERT INTO `recipe_tip` VALUES (600891, 300477, 2, '闽菜以甜为主，如果吃不惯的可以放弃白糖');
INSERT INTO `recipe_tip` VALUES (600892, 300477, 3, '可以通过勺子敲打瘦肉块，听到声响来判断是否炸透瘦肉');
INSERT INTO `recipe_tip` VALUES (600893, 300479, 1, '如果想要更有嚼劲的粉，可以缩短第二步煮粉的时间');
INSERT INTO `recipe_tip` VALUES (600894, 300479, 2, '如果想在螺蛳粉中添加炸蛋，请参考炸蛋的教程');
INSERT INTO `recipe_tip` VALUES (600895, 300479, 3, '配料的选择请依照个人口味');
INSERT INTO `recipe_tip` VALUES (600896, 300480, 1, '操作时，需要注意观察水位线，调整炉火大小，以防水烧干粘锅。');
INSERT INTO `recipe_tip` VALUES (600897, 300480, 2, '放入鲜鸭血时，需要不断翻炒搅拌，防止鸭血抱团凝固成块。');
INSERT INTO `recipe_tip` VALUES (600898, 300481, 1, '营养成分(每100g) 热量：94 Kcal');
INSERT INTO `recipe_tip` VALUES (600899, 300481, 2, '营养成分(每100g) 蛋白质：8.3 g');
INSERT INTO `recipe_tip` VALUES (600900, 300481, 3, '营养成分(每100g) 脂肪：5.2 g');
INSERT INTO `recipe_tip` VALUES (600901, 300481, 4, '营养成分(每100g) 碳水化合物：3.5 g');
INSERT INTO `recipe_tip` VALUES (600902, 300481, 5, '营养成分(每100g) 钠：261 mg');
INSERT INTO `recipe_tip` VALUES (600903, 300482, 1, '炖煮时保证汤加入的时候是温热的');
INSERT INTO `recipe_tip` VALUES (600904, 300482, 2, '炖煮时不要扣盖否则土豆会烂');
INSERT INTO `recipe_tip` VALUES (600905, 300482, 3, '炖煮时时不时翻动避免糊底');
INSERT INTO `recipe_tip` VALUES (600906, 300482, 4, '砂锅炖煮会更好吃，可以在炒锅里炒完倒到煮锅里炖，如果用砂锅开锅之前不要用大火避免裂开');
INSERT INTO `recipe_tip` VALUES (600907, 300482, 5, '酱油总量不要太多，汤汁浓缩的时候会变咸，稀的时候稍微淡点没事，炖煮时候觉得不够也可以再加酱油');
INSERT INTO `recipe_tip` VALUES (600908, 300482, 6, '不要用鸡精味精，会抢夺牛肉的鲜味');
INSERT INTO `recipe_tip` VALUES (600909, 300483, 1, '快速做法：');
INSERT INTO `recipe_tip` VALUES (600910, 300483, 2, '直接在有半熟鸡蛋的锅中加入 西红柿块，与鸡蛋一起翻炒直至西红柿软烂');
INSERT INTO `recipe_tip` VALUES (600911, 300483, 3, '继续 第 10 步');
INSERT INTO `recipe_tip` VALUES (600912, 300483, 4, '加入盐 改为 “加入两滴生抽”');
INSERT INTO `recipe_tip` VALUES (600913, 300484, 1, '营养成分(每100g) 热量：149 Kcal');
INSERT INTO `recipe_tip` VALUES (600914, 300484, 2, '营养成分(每100g) 蛋白质：5.0 g');
INSERT INTO `recipe_tip` VALUES (600915, 300484, 3, '营养成分(每100g) 脂肪：4.8 g');
INSERT INTO `recipe_tip` VALUES (600916, 300484, 4, '营养成分(每100g) 碳水化合物：21.3 g');
INSERT INTO `recipe_tip` VALUES (600917, 300484, 5, '营养成分(每100g) 钠：334 mg');
INSERT INTO `recipe_tip` VALUES (600918, 300485, 1, '用火注意安全、用火注意安全、用火注意安全');
INSERT INTO `recipe_tip` VALUES (600919, 300485, 2, '用砂锅/铝锅炖肉时，水开后转中小火/小火，使用高压锅见学习使用压力锅');
INSERT INTO `recipe_tip` VALUES (600920, 300485, 3, '教程中的番茄去皮方式是目前为止本人实践最快的方式');
INSERT INTO `recipe_tip` VALUES (600921, 300485, 4, '绝对不用番茄酱和少加佐料，尽可能还原食材的原味');
INSERT INTO `recipe_tip` VALUES (600922, 300487, 1, '鸡蛋蛋液中可以加入 2g 黑胡椒味道更好');
INSERT INTO `recipe_tip` VALUES (600923, 300487, 2, '熬臊子过程中加入 2g 白胡椒粉提升香辛口味');
INSERT INTO `recipe_tip` VALUES (600924, 300487, 3, '煮面条如果一次性煮熟也可以，多次加水是为了让面条口感劲道，面条不粘黏，技巧在于煮沸就加冷水，循环往复两三次即可');
