INSERT INTO `recipe_tip` VALUES (600935, 300494, 1, '毛细（顾名思义，就像头发，其实就有点像细粉丝那样细）');
INSERT INTO `recipe_tip` VALUES (600936, 300494, 2, '细（这个比毛细粗点，跟香头一样）');
INSERT INTO `recipe_tip` VALUES (600937, 300494, 3, '二细（有点像一般的炒面条那样粗）');
INSERT INTO `recipe_tip` VALUES (600938, 300494, 4, '三细（比二细稍微粗点，吃起来像吃粗粉条，不过面如果拉的比较劲道的话，这个嚼起来感觉很有味）');
INSERT INTO `recipe_tip` VALUES (600939, 300494, 5, '韭叶（这鸡就像韭菜叶子一样宽）');
INSERT INTO `recipe_tip` VALUES (600940, 300494, 6, '大宽（就像吃麻辣烫的那个宽粉一样）');
INSERT INTO `recipe_tip` VALUES (600941, 300495, 1, '注意事项：');
INSERT INTO `recipe_tip` VALUES (600942, 300495, 2, '1. 鲮鱼罐头本身带味道，加入生抽后够味，无需下盐');
INSERT INTO `recipe_tip` VALUES (600943, 300496, 1, '豆豉浸泡后稍微剁碎会更入味');
INSERT INTO `recipe_tip` VALUES (600944, 300496, 2, '蒸制时间随排骨大小调整，以筷子能轻松插入软骨处为准');
INSERT INTO `recipe_tip` VALUES (600945, 300496, 3, '传统的豉汁排骨不放撒料和淋热油');
INSERT INTO `recipe_tip` VALUES (600946, 300496, 4, '吃剩的汤汁可以用来拌饭或者拌面');
INSERT INTO `recipe_tip` VALUES (600947, 300497, 1, '注意事项：');
INSERT INTO `recipe_tip` VALUES (600948, 300497, 2, '确保白鱔新鲜，购买时选择活鱼，肉质更鲜嫩。');
INSERT INTO `recipe_tip` VALUES (600949, 300497, 3, '鱼贩切段时可指定长度 （约 5 厘米为宜），方便蒸制和食用。');
INSERT INTO `recipe_tip` VALUES (600950, 300497, 4, '蒸制时间不宜过长，以免白鱔肉质变韧。');
INSERT INTO `recipe_tip` VALUES (600951, 300497, 5, '变种做法：');
INSERT INTO `recipe_tip` VALUES (600952, 300497, 6, '可加入辣椒或 XO 酱，增加辣味和层次感。');
INSERT INTO `recipe_tip` VALUES (600953, 300497, 7, '若喜欢更软嫩的口感，可在腌制时加入米酒。');
INSERT INTO `recipe_tip` VALUES (600954, 300498, 1, '营养成分(每100g) 热量：121 Kcal');
INSERT INTO `recipe_tip` VALUES (600955, 300498, 2, '营养成分(每100g) 蛋白质：12.7 g');
INSERT INTO `recipe_tip` VALUES (600956, 300498, 3, '营养成分(每100g) 脂肪：7.3 g');
INSERT INTO `recipe_tip` VALUES (600957, 300498, 4, '营养成分(每100g) 碳水化合物：1.2 g');
INSERT INTO `recipe_tip` VALUES (600958, 300498, 5, '营养成分(每100g) 钠：927 mg');
INSERT INTO `recipe_tip` VALUES (600959, 300500, 1, '操作时，需要注意翻炒，因为糍粑辣椒会糊掉');
INSERT INTO `recipe_tip` VALUES (600960, 300504, 1, '黑醋 10ml');
INSERT INTO `recipe_tip` VALUES (600961, 300504, 2, '姜 一小块 50 克');
INSERT INTO `recipe_tip` VALUES (600962, 300504, 3, '香油 2 滴');
INSERT INTO `recipe_tip` VALUES (600963, 300504, 4, '大蒜/蒜泥 3 瓣/人');
INSERT INTO `recipe_tip` VALUES (600964, 300504, 5, '考虑搭配黑醋食用。建议用量：10-20ml。');
INSERT INTO `recipe_tip` VALUES (600965, 300504, 6, '考虑姜切丝，在小碗加入 20ml 的黑醋与姜丝搅拌当蘸料，味道更丰富。');
INSERT INTO `recipe_tip` VALUES (600966, 300504, 7, '考虑搭配黑醋时加入 1~3 滴香油，搅拌当蘸料。');
INSERT INTO `recipe_tip` VALUES (600967, 300504, 8, '考虑搭配黑醋时加入砸好的蒜泥，搅拌当蘸料。（口腔内会残留蒜味，若饭后需要与他人面对面谈话建议放弃或清洁口腔）');
INSERT INTO `recipe_tip` VALUES (600968, 300505, 1, '注意先加汤圆再加热水，不要颠倒，不然汤圆倒入热水可能会溅出烫伤。以及无法控制水面高度可能溢出。');
INSERT INTO `recipe_tip` VALUES (600969, 300505, 2, '假如微波炉里碗太烫无法取出，可以用毛巾，或者某些微波炉可以连托盘一起取出。');
INSERT INTO `recipe_tip` VALUES (600970, 300506, 1, '出锅后也可以加入水煮荷包蛋（太阳蛋）一起食用。');
INSERT INTO `recipe_tip` VALUES (600971, 300507, 1, '营养成分(每100g) 热量：37 Kcal');
INSERT INTO `recipe_tip` VALUES (600972, 300507, 2, '营养成分(每100g) 蛋白质：0.7 g');
INSERT INTO `recipe_tip` VALUES (600973, 300507, 3, '营养成分(每100g) 脂肪：0.7 g');
INSERT INTO `recipe_tip` VALUES (600974, 300507, 4, '营养成分(每100g) 碳水化合物：7.0 g');
INSERT INTO `recipe_tip` VALUES (600975, 300507, 5, '营养成分(每100g) 钠：8 mg');
INSERT INTO `recipe_tip` VALUES (600976, 300508, 1, '发酵温度至关重要，低温会发酵缓慢或失败，高温会杀死酒曲');
INSERT INTO `recipe_tip` VALUES (600977, 300508, 2, '发酵失败常见原因：温度过高、米饭太热时拌入酒曲、容器未清洁干净或进水进油');
INSERT INTO `recipe_tip` VALUES (600978, 300508, 3, '可搭配汤圆、蛋花、枸杞等加热食用，但注意不要煮沸时间过长以免酒香散失');
INSERT INTO `recipe_tip` VALUES (600979, 300508, 4, '酒酿汁可用于制作酒酿米糕、酒酿饼等，还可以用作调料为肥牛饭、照烧汁增添风味');
INSERT INTO `recipe_tip` VALUES (600980, 300510, 1, '荞麦面沥干后可以放冰箱冰镇后口感更佳');
INSERT INTO `recipe_tip` VALUES (600981, 300510, 2, '配料可以根据个人喜好选择其他，例如虾仁、肉沫等');
INSERT INTO `recipe_tip` VALUES (600982, 300510, 3, '酱料可以根据个人喜欢选择其他，例如花生酱、芝麻酱等');
INSERT INTO `recipe_tip` VALUES (600983, 300510, 4, '荞麦面跟其他面条热量几乎一致，所以不适合作为减脂的主食');
INSERT INTO `recipe_tip` VALUES (600984, 300511, 1, '增加味道的可以考虑加入豆瓣酱、番茄酱等');
INSERT INTO `recipe_tip` VALUES (600985, 300511, 2, '大火煮时间可以根据每个人情况做调整');
INSERT INTO `recipe_tip` VALUES (600986, 300511, 3, '煮排骨期间，可以顺道放入 2-3 个 鸡蛋一起煮，做成简易版卤蛋');
INSERT INTO `recipe_tip` VALUES (600987, 300513, 1, '咸口放 50 g 豆瓣酱，甜口减少豆瓣酱的用量并加入冰糖和番茄酱');
INSERT INTO `recipe_tip` VALUES (600988, 300513, 2, '出锅后再撒上一点葱花会更香也更好看');
INSERT INTO `recipe_tip` VALUES (600989, 300513, 3, '参考资料：秋风起，平湖这道美味很下饭_潮新闻官网');
INSERT INTO `recipe_tip` VALUES (600990, 300514, 1, '操作时，需要注意观察沸腾的水位线，如发现低于 2/3 的食材应加热水至没过食材（约每 30 分钟确认一次）。');
INSERT INTO `recipe_tip` VALUES (600991, 300514, 2, '用保鲜膜紧密包裹牛肉，放入冰箱冷藏数小时，可以使得切片肉质紧实不散。');
INSERT INTO `recipe_tip` VALUES (600992, 300514, 3, '用牙签或者叉子在牛肉表面扎孔可以破坏筋膜，便于入味。');
INSERT INTO `recipe_tip` VALUES (600993, 300514, 4, '下厨房app中的食谱');
INSERT INTO `recipe_tip` VALUES (600994, 300518, 1, '传统版本的意式奶冻只用淡奶油，且糖量更大，比较甜腻。此版本做了改良，吃起来负担更小。');
