INSERT INTO `recipe_tip` VALUES (601005, 300524, 1, '清洗土豆丝淀粉一定要去干净，不然会全黏在一起');
INSERT INTO `recipe_tip` VALUES (601006, 300524, 2, '加入蒜末、盐后应尽快出锅，保留蒜香以及避免破坏口感。');
INSERT INTO `recipe_tip` VALUES (601007, 300527, 1, '葱姜蒜为附加调料，加入可以增添风味，不加也并无大碍');
INSERT INTO `recipe_tip` VALUES (601008, 300527, 2, '糖和盐根据个人口味，需要加入的具体量不同，请酌情加入');
INSERT INTO `recipe_tip` VALUES (601009, 300527, 3, '建议使用碗作为最终装盘餐具，因为使用盘子会使吃粉变得困难一些');
INSERT INTO `recipe_tip` VALUES (601010, 300527, 4, '整体口味偏辣，如果不能吃辣请减少油泼辣子的量并且不加入小米辣');
INSERT INTO `recipe_tip` VALUES (601011, 300528, 1, '鱼露，又称鱼酱油，是一种广东，福建等地常见的调味品。效果类似于生抽');
INSERT INTO `recipe_tip` VALUES (601012, 300528, 2, '本次制作过程中，由于疫情原因没有雨露，只能用老抽代替，所以排骨颜色偏黑，正常是金黄色');
INSERT INTO `recipe_tip` VALUES (601013, 300529, 1, '白糖的用量根据个人口味更改');
INSERT INTO `recipe_tip` VALUES (601014, 300529, 2, '若喜欢更浓的口感可以减少 100 毫升内的水');
INSERT INTO `recipe_tip` VALUES (601015, 300529, 3, '若喜欢软点的枸杞口感，可以将枸杞和小汤圆同时煮');
INSERT INTO `recipe_tip` VALUES (601016, 300530, 1, '金枪鱼酱可以在前一天晚上在冰箱冷藏');
INSERT INTO `recipe_tip` VALUES (601017, 300530, 2, '金枪鱼酱建议冷藏时间不超过一周，切需要使用保鲜膜盖住');
INSERT INTO `recipe_tip` VALUES (601018, 300530, 3, '注意在按压操作之前不要将轻食机电源接通，以免引发安全问题');
