INSERT INTO `recipe_tip` VALUES (601069, 300548, 1, '鱼鳞是这道菜的关键特色，一定要保留，煎炸后会变得酥脆可口');
INSERT INTO `recipe_tip` VALUES (601070, 300548, 2, '鱼剖成两半更容易煎透入味，比整条划刀效果更好');
INSERT INTO `recipe_tip` VALUES (601071, 300548, 3, '正宗做法使用桂林辣椒酱（非郫县豆瓣酱），搭配漓泉啤酒，没有桂林辣椒酱可以用蒜蓉辣酱代替');
INSERT INTO `recipe_tip` VALUES (601072, 300548, 4, '番茄要炒软出汁，这样汤汁更浓郁');
INSERT INTO `recipe_tip` VALUES (601073, 300548, 5, '汤汁不要收太干，留一些拌饭或拌面非常好吃');
INSERT INTO `recipe_tip` VALUES (601074, 300548, 6, '参考资料：阳朔啤酒鱼的做法');
INSERT INTO `recipe_tip` VALUES (601075, 300550, 1, '加入西红柿后开始继续熬制后，需要偶尔翻搅防止糊底');
INSERT INTO `recipe_tip` VALUES (601076, 300551, 1, '技术总结');
INSERT INTO `recipe_tip` VALUES (601077, 300551, 2, '辣椒面的选择很关键，建议使用陕西秦椒面，香而不辣; 陕西八大怪之一: 油泼辣子一道菜😂');
INSERT INTO `recipe_tip` VALUES (601078, 300551, 3, '泼油的油温是成败关键，油温过低辣椒不香，油温过高容易糊');
INSERT INTO `recipe_tip` VALUES (601079, 300551, 4, '喜欢吃肉的可以加入肉末做成肉臊子油泼面');
INSERT INTO `recipe_tip` VALUES (601080, 300551, 5, '传统陕西油泼面讲究“一青二白三红四绿”，即面条、蒜末、辣椒、葱花的颜色搭配');
INSERT INTO `recipe_tip` VALUES (601081, 300552, 1, '棉花糖加热时间越长，最后成品越硬');
INSERT INTO `recipe_tip` VALUES (601082, 300552, 2, '参考资料：【一口小锅 十分钟搞定的网红草莓“雪花酥”-哔哩哔哩】');
INSERT INTO `recipe_tip` VALUES (601083, 300559, 1, '营养成分(每100g) 热量：172 Kcal');
INSERT INTO `recipe_tip` VALUES (601084, 300559, 2, '营养成分(每100g) 蛋白质：9.1 g');
INSERT INTO `recipe_tip` VALUES (601085, 300559, 3, '营养成分(每100g) 脂肪：11.1 g');
INSERT INTO `recipe_tip` VALUES (601086, 300559, 4, '营养成分(每100g) 碳水化合物：9.0 g');
INSERT INTO `recipe_tip` VALUES (601087, 300559, 5, '营养成分(每100g) 钠：455 mg');
INSERT INTO `recipe_tip` VALUES (601088, 300560, 1, '青椒选笔直的比弯的好塞馅料，肉厚的尖椒比薄皮的口感更好');
INSERT INTO `recipe_tip` VALUES (601089, 300560, 2, '馅料朝一个方向搅拌才能上劲，口感更 Q 弹');
INSERT INTO `recipe_tip` VALUES (601090, 300560, 3, '青椒内壁涂干淀粉是防粘的关键，煎时肉馅不会脱落');
INSERT INTO `recipe_tip` VALUES (601091, 300560, 4, '煎至虎皮色是风味来源，不要跳过');
INSERT INTO `recipe_tip` VALUES (601092, 300560, 5, '酱汁可依个人口味调整，喜欢更辣的可加桂林辣椒酱');
INSERT INTO `recipe_tip` VALUES (601093, 300560, 6, '虾滑和猪肉馅可以混合使用，比例随意，虾肉增加鲜甜，猪肉提供油脂香');
INSERT INTO `recipe_tip` VALUES (601094, 300560, 7, '汤汁拌饭极佳，不要收太干');
INSERT INTO `recipe_tip` VALUES (601095, 300561, 1, '酱汁的比例可以根据个人口味微调。如果喜欢更甜，可以增加糖的用量。');
INSERT INTO `recipe_tip` VALUES (601096, 300561, 2, '剩余的酱汁非常美味，可以直接用来拌饭。');
INSERT INTO `recipe_tip` VALUES (601097, 300562, 1, '这是道非常简单的菜 过程会比较繁琐 但当将菜肉米饭酱汁搅拌起来吃会很满足');
INSERT INTO `recipe_tip` VALUES (601098, 300562, 2, '如果对外观有一定要求 可以用砂锅代替普通碗');
INSERT INTO `recipe_tip` VALUES (601099, 300563, 1, '韭菜炒蛋讲究大火快炒，韭菜炒久了容易失去香气和脆嫩口感');
INSERT INTO `recipe_tip` VALUES (601100, 300563, 2, '如果喜欢韭菜更软烂，可以适当延长翻炒时间');
INSERT INTO `recipe_tip` VALUES (601101, 300564, 1, '制作时可根据个人口味添加豆腐干等配料。');
INSERT INTO `recipe_tip` VALUES (601102, 300564, 2, '注意煎制时火候，避免外焦内生。');
INSERT INTO `recipe_tip` VALUES (601103, 300569, 1, '如果没有买到香芹，或者用的芹菜比较粗，可以考虑焯水，放入滚水中 1 分钟捞出，冷水冲洗（保持爽脆）');
INSERT INTO `recipe_tip` VALUES (601104, 300569, 2, '如果买到的豆干比较硬、紧实，也可以切条后再焯水');
INSERT INTO `recipe_tip` VALUES (601105, 300569, 3, '香干芹菜炒肉教程');
INSERT INTO `recipe_tip` VALUES (601106, 300571, 1, '操作时，小心被溅出的油烫到');
INSERT INTO `recipe_tip` VALUES (601107, 300572, 1, '切记鱼是开背杀，腌制时，鱼表面涂抹均匀食盐即可，腌制时间，晾晒时间 1-2 天即可');
INSERT INTO `recipe_tip` VALUES (601108, 300572, 2, '煎鱼全程小火，刚入锅时不要移动鱼，会破皮');
INSERT INTO `recipe_tip` VALUES (601109, 300572, 3, '青椒断放入后注意观察熟透程度，里面的青椒很好吃，另外香菜最后放');
INSERT INTO `recipe_tip` VALUES (601110, 300572, 4, '注意火候的切换，豆瓣酱，白糖的调鲜效果，与陈醋的增香效果');
