INSERT INTO `recipe_tip` VALUES (601126, 300581, 1, '鸡腿去骨操作较复杂，本人经验可供参考：');
INSERT INTO `recipe_tip` VALUES (601127, 300581, 2, '鸡腿于案板摆正，骨头正对程序员，从头部划一刀至最底部，刀口要深，确保有碰到骨头');
INSERT INTO `recipe_tip` VALUES (601128, 300581, 3, '用手扒拉肉到两边');
INSERT INTO `recipe_tip` VALUES (601129, 300581, 4, '用刀尖隔开骨头上沾着的肉');
INSERT INTO `recipe_tip` VALUES (601130, 300581, 5, '鸡腿翻面，刀紧贴骨头插入，挑断骨头与肉的连接点');
INSERT INTO `recipe_tip` VALUES (601131, 300581, 6, '用刀尖切断最后的粘连即可');
