INSERT INTO `recipe_tip` VALUES (601159, 300602, 1, '茄子看个人喜好，可以去皮，肉沫也可以多放一点。');
INSERT INTO `recipe_tip` VALUES (601160, 300602, 2, '参考: 鱼香茄子详细步骤');
INSERT INTO `recipe_tip` VALUES (601161, 300603, 1, '烧卖中的脂肪主要来自肥肉，低脂版本中的肥肉被移除后为保证口感需要使用少量动物油来补偿');
INSERT INTO `recipe_tip` VALUES (601162, 300603, 2, '如果没有烧卖皮，可用大馄饨皮，或者饺子皮擀薄');
INSERT INTO `recipe_tip` VALUES (601163, 300603, 3, '皮的直径在 8-10 cm 之间，每张皮重约 10-15g，皮和馅的比例控制在 1:2 - 1:2.5');
INSERT INTO `recipe_tip` VALUES (601164, 300603, 4, '绞肉机建议用中档，这样肉末不会太细（像糊糊）也不会太粗（像碎块），保持适中纹理，让馅料口感 Q 弹');
INSERT INTO `recipe_tip` VALUES (601165, 300603, 5, '使用姜末 5 g，葱末 10 g 不容易掩盖鲜肉的味道；姜末 10 g，葱末 20 g 有点像饺子馅');
INSERT INTO `recipe_tip` VALUES (601166, 300603, 6, '包烧卖的时候在虎口抹点油，收口不会粘手');
INSERT INTO `recipe_tip` VALUES (601167, 300603, 7, '蒸的时候记得水开了再上笼，这样皮子不会塌掉');
INSERT INTO `recipe_tip` VALUES (601168, 300603, 8, '做多了可 -18 ℃ 冷冻保存，冷冻保存的需要蒸 12-15 分钟');
INSERT INTO `recipe_tip` VALUES (601169, 300603, 9, '蘸上玫瑰米醋更好吃，也可以根据口味配上桐乡辣酱、油泼辣子、生抽、姜丝');
INSERT INTO `recipe_tip` VALUES (601170, 300603, 10, '参考资料：【鲜肉烧麦的做法步骤图，鲜肉烧麦怎么做好吃】小什么l_下厨房');
INSERT INTO `recipe_tip` VALUES (601171, 300604, 1, '使用米家小饭煲煮东北米的话，水没过米 3 毫米就行，太多水煮出来不是一粒一粒的饭');
INSERT INTO `recipe_tip` VALUES (601172, 300605, 1, '也可以放一些粉条，粉条先凉水/热水，需要泡软，可以和娃娃菜一起放入');
INSERT INTO `recipe_tip` VALUES (601173, 300606, 1, '鱼的两面，各煎 2-4 分钟即可');
INSERT INTO `recipe_tip` VALUES (601174, 300606, 2, '煎鱼的时候全程中小火');
INSERT INTO `recipe_tip` VALUES (601175, 300606, 3, '最后出锅时，加入一些切碎的大蒜，味道会更好');
