INSERT INTO `recipe_tip` VALUES (601186, 300610, 1, '营养成分(每100g) 热量：54 Kcal');
INSERT INTO `recipe_tip` VALUES (601187, 300610, 2, '营养成分(每100g) 蛋白质：2.7 g');
