INSERT INTO `recipe_tip` VALUES (601191, 300615, 1, '也可加入芝士、酸黄瓜等食材');
INSERT INTO `recipe_tip` VALUES (601192, 300616, 1, '火腿是咸的，要在调味后才加入，这样不会让火腿也沾上盐');
INSERT INTO `recipe_tip` VALUES (601193, 300618, 1, '为了防止生鸡蛋中可能含有的沙门氏菌，建议使用刚烧开的、100 ℃ 的滚水，瞬间将鸡蛋液完全烫熟。');
INSERT INTO `recipe_tip` VALUES (601194, 300620, 1, '营养成分(每100g) 热量：376 Kcal');
INSERT INTO `recipe_tip` VALUES (601195, 300620, 2, '营养成分(每100g) 蛋白质：17.0 g');
INSERT INTO `recipe_tip` VALUES (601196, 300620, 3, '营养成分(每100g) 脂肪：31.6 g');
INSERT INTO `recipe_tip` VALUES (601197, 300620, 4, '营养成分(每100g) 碳水化合物：6.7 g');
INSERT INTO `recipe_tip` VALUES (601198, 300620, 5, '营养成分(每100g) 钠：448 mg');
INSERT INTO `recipe_tip` VALUES (601199, 300621, 1, '鹰嘴豆提前浸泡是必须步骤，不泡的话煮不软。如果时间紧迫，可以用高压锅将未泡的鹰嘴豆压 20 分钟。');
INSERT INTO `recipe_tip` VALUES (601200, 300621, 2, '红茶包的作用是给鹰嘴豆上色，使其呈现深棕色。这是印度餐厅的秘诀。');
INSERT INTO `recipe_tip` VALUES (601201, 300621, 3, '炸饼面团中的酸奶和小苏打是其松软蓬松的关键。面团不宜太硬。');
INSERT INTO `recipe_tip` VALUES (601202, 300621, 4, '这道菜在印度是国民级的早午餐，从路边摊到高档餐厅都有供应。在中国的印度餐厅中通常被称为\"鹰嘴豆咖喱配炸饼\"。');
INSERT INTO `recipe_tip` VALUES (601203, 300622, 1, '期间一定要注意观察，防止糊锅');
INSERT INTO `recipe_tip` VALUES (601204, 300624, 1, '一定要选半干荞麦面，口感最好');
INSERT INTO `recipe_tip` VALUES (601205, 300624, 2, '可以随意添加其他东西，比如火锅丸、蛋饺等');
INSERT INTO `recipe_tip` VALUES (601206, 300624, 3, '火锅底料、花生酱、牛奶一定要加，口味三大巨头');
INSERT INTO `recipe_tip` VALUES (601207, 300624, 4, '如果不能吃酸，可以不加醋');
INSERT INTO `recipe_tip` VALUES (601208, 300625, 1, '大火通常温度在 240 摄氏度，以电磁炉为例，输入功率大约 2 千瓦。');
INSERT INTO `recipe_tip` VALUES (601209, 300625, 2, '中火通常温度在 120 摄氏度，以电磁炉为例，输入功率大约 1.4 千瓦。');
INSERT INTO `recipe_tip` VALUES (601210, 300627, 1, '虾开背才更好入味，不过处理时切记切记小心用刀，新手容易伤到手');
INSERT INTO `recipe_tip` VALUES (601211, 300627, 2, '冯小厨的菜谱');
INSERT INTO `recipe_tip` VALUES (601212, 300628, 1, '干葫芦巴叶(Kasuri Methi)是这道菜独特风味的关键配料，能赋予一种特殊的草本香气。在印度食品店或电商平台可以购买到。');
INSERT INTO `recipe_tip` VALUES (601213, 300628, 2, '使用 Kashmiri 红辣椒粉可以使颜色更鲜红但辣度较低。如果买不到，可以用普通红辣椒粉减半并加入 3g 红甜椒粉。');
INSERT INTO `recipe_tip` VALUES (601214, 300628, 3, '腰果的作用是使酱汁更加浓稠丝滑。如果对坚果过敏，可以用等量的淡奶油替代。');
INSERT INTO `recipe_tip` VALUES (601215, 300628, 4, '此菜通常搭配印度烤饼(Naan)或巴斯马蒂米饭食用。');
INSERT INTO `recipe_tip` VALUES (601216, 300628, 5, '黄油鸡被认为是印度对世界美食最大的贡献之一，在全球各地的印度餐厅菜单上几乎都名列前茅。');
INSERT INTO `recipe_tip` VALUES (601217, 300630, 1, '营养成分(每100g) 热量：104 Kcal');
INSERT INTO `recipe_tip` VALUES (601218, 300630, 2, '营养成分(每100g) 蛋白质：6.0 g');
INSERT INTO `recipe_tip` VALUES (601219, 300630, 3, '营养成分(每100g) 脂肪：6.9 g');
INSERT INTO `recipe_tip` VALUES (601220, 300630, 4, '营养成分(每100g) 碳水化合物：4.6 g');
INSERT INTO `recipe_tip` VALUES (601221, 300630, 5, '营养成分(每100g) 钠：811 mg');
INSERT INTO `recipe_tip` VALUES (601222, 300632, 1, '黄瓜可以根据喜好决定是否去皮');
INSERT INTO `recipe_tip` VALUES (601223, 300632, 2, '黄瓜薄片可以用刮皮刀刮');
INSERT INTO `recipe_tip` VALUES (601224, 300632, 3, '皮蛋切块时抹点香油不容易粘刀');
INSERT INTO `recipe_tip` VALUES (601225, 300632, 4, '参考资料：【黄瓜皮蛋汤的做法步骤图，黄瓜皮蛋汤怎么做好吃】是春天呐__下厨房');
INSERT INTO `recipe_tip` VALUES (601226, 300633, 1, '营养成分(每100g) 热量：201 Kcal');
INSERT INTO `recipe_tip` VALUES (601227, 300633, 2, '营养成分(每100g) 蛋白质：9.2 g');
INSERT INTO `recipe_tip` VALUES (601228, 300633, 3, '营养成分(每100g) 脂肪：5.0 g');
