INSERT INTO `recipe_tip` VALUES (601230, 300633, 5, '营养成分(每100g) 钠：329 mg');
INSERT INTO `recipe_tip` VALUES (601231, 300635, 1, '根据锅的大小，建议以水量没过食材为宜，宁多勿少');
INSERT INTO `recipe_tip` VALUES (601232, 300635, 2, '如果没有刀具，娃娃菜和腊肠不切也可以');
INSERT INTO `recipe_tip` VALUES (601233, 300636, 1, '龟苓膏冷却过程中不可随意移动容器，否则可能影响成型。');
INSERT INTO `recipe_tip` VALUES (601234, 300636, 2, '加热时应避免使用大火，防止结块或糊底。');
INSERT INTO `recipe_tip` VALUES (601235, 300636, 3, '可根据个人口味添加蜂蜜、炼乳或水果食用。');
INSERT INTO `recipe_tip` VALUES (601236, 300636, 4, '不同品牌龟苓膏粉浓度略有差异，建议参照包装说明调整配比。');
