-- ----------------------------
-- Table structure for ai_call_log
-- ----------------------------
DROP TABLE IF EXISTS `ai_call_log`;
CREATE TABLE `ai_call_log`  (
  `id` bigint NOT NULL COMMENT '主键(雪花ID)',
  `user_id` bigint NOT NULL COMMENT '调用用户 -> app_user.id (AI功能要求登录)',
  `model_config_id` bigint NULL DEFAULT NULL COMMENT '模型配置ID -> ai_model_config.id',
  `model_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模型名称(冗余，配置删除后仍可追溯)',
  `scene` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '应用场景: INGREDIENT_RECOMMEND/CONDITION_FILTER/FALLBACK_GENERATE',
  `input_tokens` int NOT NULL DEFAULT 0 COMMENT '输入token数',
  `output_tokens` int NOT NULL DEFAULT 0 COMMENT '输出token数',
  `success` tinyint NOT NULL DEFAULT 1 COMMENT '是否成功: 1-成功 0-失败',
  `error_msg` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '失败原因',
  `duration_ms` int NOT NULL DEFAULT 0 COMMENT '耗时(毫秒)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '调用时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_call_log_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_call_log_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_call_log_scene`(`scene` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'AI调用日志' ROW_FORMAT = Dynamic;

