-- Records of ai_call_log
-- ----------------------------

-- ----------------------------
-- Table structure for ai_generated_recipe
-- ----------------------------
DROP TABLE IF EXISTS `ai_generated_recipe`;
CREATE TABLE `ai_generated_recipe`  (
  `id` bigint NOT NULL COMMENT '主键(雪花ID)',
  `user_id` bigint NOT NULL COMMENT '触发生成的用户 -> app_user.id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '生成的菜名',
  `summary` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '简介',
  `difficulty` tinyint NOT NULL DEFAULT 3 COMMENT '难度星级 1-5',
  `calorie` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '整道菜总热量(按食材库营养成分计算)',
  `cook_time` int NOT NULL DEFAULT 0 COMMENT '预估耗时(分钟)',
  `base_servings` int NOT NULL DEFAULT 1 COMMENT '基准份数',
  `ingredients` json NOT NULL COMMENT '食材列表JSON: [{ingredientId,name,amount,unit,isOptional,remark}]',
  `steps` json NOT NULL COMMENT '步骤列表JSON: [{sort,content}]',
  `tips` json NULL COMMENT '提示列表JSON: [{sort,content}]',
  `scene` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '触发场景: INGREDIENT_RECOMMEND/CONDITION_FILTER',
  `user_input` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '用户原始输入(便于评估生成质量)',
  `converted` tinyint NOT NULL DEFAULT 0 COMMENT '是否已转正: 0-否 1-是',
  `converted_recipe_id` bigint NULL DEFAULT NULL COMMENT '转正后的食谱ID -> recipe.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '生成时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_gen_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_gen_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_gen_converted`(`converted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'AI生成食谱记录' ROW_FORMAT = Dynamic;

