  `user_id` bigint NOT NULL COMMENT '前台用户ID -> app_user.id',
  `ai_recipe_id` bigint NOT NULL COMMENT 'AI生成食谱ID -> ai_generated_recipe.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '收藏时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_gen_favorite_user_recipe`(`user_id` ASC, `ai_recipe_id` ASC) USING BTREE,
  INDEX `idx_gen_favorite_recipe`(`ai_recipe_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'AI生成食谱收藏' ROW_FORMAT = Dynamic;

