-- ----------------------------
-- Table structure for recipe
-- ----------------------------
DROP TABLE IF EXISTS `recipe`;
CREATE TABLE `recipe`  (
  `id` bigint NOT NULL COMMENT '主键(雪花ID)',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '菜名',
  `cover_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '封面图地址',
  `summary` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '简介',
  `difficulty` tinyint NOT NULL DEFAULT 3 COMMENT '难度星级 1-5',
  `calorie` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '整道菜总热量(大卡)，由食材自动计算，不可手填',
  `cook_time` int NOT NULL DEFAULT 0 COMMENT '预估耗时(分钟)',
  `base_servings` int NOT NULL DEFAULT 1 COMMENT '基准份数，前台按此比例换算用量',
  `tag_id` bigint NULL DEFAULT NULL COMMENT '标签ID -> recipe_tag.id (单选)',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态: 0-草稿 1-已发布 2-已下架',
  `favorite_count` int NOT NULL DEFAULT 0 COMMENT '收藏数(冗余计数)',
  `like_count` int NOT NULL DEFAULT 0 COMMENT '点赞数(冗余计数)',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人 -> sys_user.id',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后更新人 -> sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除: 0-未删除 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_recipe_tag`(`tag_id` ASC) USING BTREE,
  INDEX `idx_recipe_status`(`status` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_recipe_name`(`name` ASC) USING BTREE,
  INDEX `idx_recipe_calorie`(`calorie` ASC) USING BTREE,
  INDEX `idx_recipe_favorite_count`(`favorite_count` ASC) USING BTREE,
  INDEX `idx_recipe_like_count`(`like_count` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '食谱' ROW_FORMAT = Dynamic;

