  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ri_recipe`(`recipe_id` ASC) USING BTREE,
  INDEX `idx_ri_ingredient`(`ingredient_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '食谱食材关联' ROW_FORMAT = Dynamic;

