  `recipe_id` bigint NOT NULL COMMENT '食谱ID -> recipe.id',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序值',
  `content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '提示内容',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tip_recipe`(`recipe_id` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '食谱附加提示' ROW_FORMAT = Dynamic;

